--
-- Name: acquitter_instantane(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.acquitter_instantane(p_instantane uuid, p_verdict text, p_raison text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  b public.branchements;
begin
  select * into i from public.instantanes where id = p_instantane for update;
  if not found then
    raise exception 'Instantané introuvable.' using errcode = 'P0002';
  end if;
  if i.statut <> 'a_appliquer' then
    raise exception 'Cet export n''attend pas de verdict (statut %).', i.statut using errcode = '55000';
  end if;
  select * into b from public.branchements where id = i.branchement_id;
  if p_verdict = 'applique' then
    perform private.appliquer_instantane(i.id);
  elsif p_verdict = 'douteux' then
    if nullif(btrim(p_raison), '') is null then
      raise exception 'Un refus dit pourquoi.' using errcode = '22023';
    end if;
    delete from public.instantanes_ecarts where instantane_id = i.id;
    update public.instantanes
       set statut = 'douteux',
           garde = coalesce(garde, '{}'::jsonb) || jsonb_build_object('raison', 'module', 'source', b.module,
                                                                      'detail', left(btrim(p_raison), 300)),
           motif = private.phrase_garde(jsonb_build_object('raison', 'module', 'source', b.module, 'detail', left(btrim(p_raison), 300)))
     where id = i.id;
    update public.pieces set statut = 'a_verifier', motif = left(btrim(p_raison), 500) where id = i.piece_id;
    perform private.alerter_douteux(i.id);
    perform private.fermer_alertes_releve(b.client_id, b.module, 'releve.en_souffrance.' || i.jeu_id::text, 'le module a rendu son verdict');
  else
    raise exception 'Verdict inconnu : % (applique ou douteux).', coalesce(p_verdict, 'vide') using errcode = '22023';
  end if;
  perform private.avancer_jeu(i.jeu_id, private.limite_requete());
  return (select jsonb_build_object('instantane', x.id, 'statut', x.statut) from public.instantanes x where x.id = i.id);
end $$;


--
-- Name: acteur_courant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.acteur_courant(OUT acteur_type text, OUT acteur_id uuid, OUT acteur_libelle text) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entetes jsonb;
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
begin
  acteur_id := (select auth.uid());
  if acteur_id is not null then acteur_type := 'utilisateur'; return; end if;
  begin
    v_entetes := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then v_entetes := null;
  end;
  acteur_libelle := nullif(current_setting('omega.operateur', true), '');
  if acteur_libelle is null and v_role = 'service_role' then
    acteur_libelle := nullif(v_entetes ->> 'x-omega-operateur', '');
  end if;
  if acteur_libelle is not null then acteur_type := 'operateur'; return; end if;
  acteur_type := 'systeme';
  acteur_libelle := coalesce(nullif(current_setting('omega.module', true), ''), v_entetes ->> 'x-omega-module', v_role);
end $$;


--
-- Name: alerter_douteux(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.alerter_douteux(p_instantane uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  j public.branchements_jeux;
  b public.branchements;
  v_suite integer;
  v_detail jsonb;
begin
  select * into i from public.instantanes where id = p_instantane;
  select * into j from public.branchements_jeux where id = i.jeu_id;
  select * into b from public.branchements where id = i.branchement_id;
  select count(*) into v_suite from public.instantanes k
  where k.jeu_id = j.id and k.statut = 'douteux'
    and k.recu_le > coalesce((select max(x.recu_le) from public.instantanes x
                              where x.jeu_id = j.id and x.statut in ('applique', 'identique')), '-infinity'::timestamptz);
  v_detail := jsonb_build_object('instantane', i.id, 'branchement', b.id, 'jeu', j.code, 'garde', i.garde, 'de_suite', v_suite);
  perform private.lever_alerte_module(b.client_id, b.module, 'attention',
    left(format('Relevé douteux, non appliqué : %s, %s (%s)', b.libelle, j.libelle, i.motif), 200),
    v_detail, 'releve.douteux.' || j.id::text, false, null);
  if v_suite >= 3 then
    perform private.lever_alerte_module(b.client_id, b.module, 'critique',
      left(format('%s relevés douteux de suite : %s, %s', v_suite, b.libelle, j.libelle), 200),
      v_detail, 'releve.douteux_suite.' || j.id::text, false, null);
  end if;
end $$;


--
-- Name: annuler_envoi(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.annuler_envoi(p_envoi uuid, p_motif text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
  v_uid uuid := (select auth.uid());
begin
  select * into e from public.envois where id = p_envoi;
  if e.id is null then
    raise exception 'Envoi introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is not null then
    if not exists (select 1 from public.comptes c where c.user_id = v_uid and c.client_id = e.client_id)
       or not private.voit_objet(e.client_id, e.objet_type, e.objet_id)
       or not private.perimetre_couvre(v_uid, e.client_id, e.entite_id) then
      raise exception 'Envoi introuvable.' using errcode = 'P0002';
    end if;
    if e.prepare_par is distinct from v_uid and not private.a_un_role(e.client_id, array['gerant', 'admin']) then
      raise exception 'Seul qui l''a préparé, un gérant ou un admin annule un envoi.' using errcode = '42501';
    end if;
  else
    perform private.exiger_ouvrier();
  end if;
  if e.statut = 'en_cours' and (e.fournisseur <> 'manuel' or e.bail_jusqu_au > now()) then
    raise exception 'Cet envoi est en train de partir : il ne s''annule plus.' using errcode = '55000';
  end if;
  if not private.clore_envoi(p_envoi, 'annule', 'ANNULE', coalesce(left(nullif(btrim(p_motif), ''), 500), 'Annulé.')) then
    raise exception 'Cet envoi ne s''annule plus (%).', e.statut using errcode = '55000';
  end if;
end $$;


--
-- Name: apercu_gabarit(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apercu_gabarit(p_client uuid, p_module text, p_code text, p_variables jsonb DEFAULT '{}'::jsonb, p_langue text DEFAULT 'fr'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_g public.gabarits_messages;
  v_rendu jsonb;
begin
  if (select auth.uid()) is not null then
    if not exists (select 1 from public.comptes c where c.user_id = (select auth.uid()) and c.client_id = p_client) then
      raise exception 'Organisation introuvable.' using errcode = 'P0002';
    end if;
  else
    perform private.exiger_ouvrier();
  end if;
  v_g := private.gabarit_pour(p_client, p_module, p_code, p_langue);
  if v_g.id is null then
    raise exception 'Aucun gabarit validé « % » pour le module %.', p_code, p_module using errcode = 'P0002';
  end if;
  v_rendu := private.rendre_gabarit(v_g, p_variables, p_client, null);
  return jsonb_build_object('gabarit', v_g.code, 'version', v_g.version, 'langue', v_g.langue, 'canal', v_g.canal,
                            'sujet', v_rendu -> 'sujet', 'corps', v_rendu -> 'corps');
end $$;


--
-- Name: apercu_point(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apercu_point(p_client uuid, p_user uuid DEFAULT NULL::uuid, p_jour date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  v_user uuid := coalesce(p_user, v_uid);
  v_jour date;
  v_prevu timestamptz;
  r record;
begin
  if v_uid is not null then
    if v_user <> v_uid and not private.a_un_role(p_client, array['gerant']) then
      raise exception 'Seul le gérant regarde le point d''un autre membre.' using errcode = '42501';
    end if;
  elsif v_role not in ('service_role', 'postgres') then
    raise exception 'Le point se regarde par un membre, ou par le serveur.' using errcode = '42501';
  end if;
  if v_user is null or not exists (select 1 from public.comptes c where c.client_id = p_client and c.user_id = v_user) then
    raise exception 'Ce membre n''appartient pas à l''organisation.' using errcode = '42501';
  end if;
  select * into r from private.point_reglage(p_client, v_user);
  v_jour := coalesce(p_jour, (now() at time zone r.fuseau)::date);
  v_prevu := private.point_du(p_client, v_user, v_jour);
  return jsonb_build_object('jour', v_jour, 'fuseau', r.fuseau, 'prevu_le', v_prevu,
                            'du_le', private.point_devenu_du(v_prevu, r.horaire_depuis, now()),
                            'sections', private.point_composer(p_client, v_user, v_jour),
                            'motifs', private.point_motifs(p_client, v_user, v_jour, now()));
end $$;


--
-- Name: appeler_gardien(regprocedure, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.appeler_gardien(p_fonction regprocedure, p_user uuid, p_client uuid, p_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_nom text;
  v boolean;
begin
  select format('%I.%I', n.nspname, p.proname) into v_nom
  from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace
  where p.oid = p_fonction;
  execute format('select %s($1, $2, $3)', v_nom) into v using p_user, p_client, p_id;
  return coalesce(v, false);
end $_$;


--
-- Name: appliquer_decision(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.appliquer_decision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_requises smallint; v_oui int; v_non int;
begin
  select d.approbations_requises into v_requises from public.demandes_validation d where d.id = new.demande_id;
  select count(*) filter (where a.decision = 'approuve'), count(*) filter (where a.decision = 'rejete') into v_oui, v_non
  from public.approbations a where a.demande_id = new.demande_id;
  if v_non > 0 then
    update public.demandes_validation set statut = 'rejetee' where id = new.demande_id and statut = 'en_attente';
  elsif v_oui >= v_requises then
    update public.demandes_validation set statut = 'approuvee' where id = new.demande_id and statut = 'en_attente';
  end if;
  return null;
end $$;


--
-- Name: appliquer_instantane(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.appliquer_instantane(p_instantane uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET enable_nestloop TO 'off'
    SET work_mem TO '32MB'
    AS $$
declare
  i public.instantanes;
  j public.branchements_jeux;
  b public.branchements;
  v_complet boolean;
  v_col text;
  v_du date;
  v_au date;
  v_sensibles text[];
begin
  select * into i from public.instantanes where id = p_instantane for update;
  select * into j from public.branchements_jeux where id = i.jeu_id for update;
  select * into b from public.branchements where id = i.branchement_id;
  v_complet := coalesce(i.complet, j.complet);
  v_col := i.garde #>> '{fenetre,colonne}';
  v_du := (i.garde #>> '{fenetre,du}')::date;
  v_au := (i.garde #>> '{fenetre,au}')::date;
  v_sensibles := private.codes_sensibles(j.colonnes);

  -- Les lignes nouvelles ou changées, et celles qui reviennent après une absence.
  insert into public.jeux_lignes as s (client_id, jeu_id, cle, valeurs, anomalies, empreinte, sensibles, instantane_id,
                                       entre_le, modifie_le, absences)
  select l.client_id, j.id, l.cle, l.valeurs - v_sensibles, nullif(l.anomalies - v_sensibles, '{}'::jsonb), l.empreinte,
         private.empreintes_sensibles(j.id, l.valeurs, v_sensibles), i.id, now(), now(), 0
  from public.instantanes_lignes l
  where l.instantane_id = i.id
    and not exists (select 1 from public.jeux_lignes x
                    where x.jeu_id = j.id and x.cle = l.cle and x.empreinte = l.empreinte and x.absences = 0)
  on conflict (jeu_id, cle) do update
    set valeurs = excluded.valeurs, anomalies = excluded.anomalies, sensibles = excluded.sensibles, absences = 0,
        instantane_id = case when s.empreinte = excluded.empreinte then s.instantane_id else excluded.instantane_id end,
        modifie_le = case when s.empreinte = excluded.empreinte then s.modifie_le else excluded.modifie_le end,
        empreinte = excluded.empreinte;

  if v_complet then
    delete from public.jeux_lignes s
    where s.jeu_id = j.id and s.absences + 1 >= j.confirmer_disparition
      and private.dans_portee(s.valeurs, v_col, v_du, v_au, i.perimetre, b.fuseau)
      and not exists (select 1 from public.instantanes_lignes l where l.instantane_id = i.id and l.cle = s.cle);
    update public.jeux_lignes s set absences = s.absences + 1
    where s.jeu_id = j.id
      and private.dans_portee(s.valeurs, v_col, v_du, v_au, i.perimetre, b.fuseau)
      and not exists (select 1 from public.instantanes_lignes l where l.instantane_id = i.id and l.cle = s.cle);
  end if;

  update public.branchements_jeux
     set courant_id = i.id, lignes = (select count(*) from public.jeux_lignes s where s.jeu_id = j.id)
   where id = j.id;
  update public.instantanes set statut = 'applique', applique_le = now() where id = i.id;
  delete from public.instantanes_lignes where instantane_id = i.id;
  -- La valeur brute d'une colonne sensible ne survit pas à l'application.
  if cardinality(v_sensibles) > 0 then
    update public.instantanes_ecarts
       set avant = avant - v_sensibles, apres = apres - v_sensibles, anomalies = nullif(anomalies - v_sensibles, '{}'::jsonb)
     where instantane_id = i.id;
  end if;
  update public.pieces set statut = 'lue' where id = i.piece_id and statut = 'a_verifier';
  perform private.confirmer_etat(j.id, i.recu_le);
  perform private.fermer_alertes_releve(b.client_id, b.module, 'releve.en_souffrance.' || j.id::text, 'l''export est appliqué');
end $$;


--
-- Name: arret_general_envois(boolean, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.arret_general_envois(p_arret boolean, p_motif text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_acteur record;
begin
  perform private.exiger_ouvrier();
  select * into v_acteur from private.acteur_courant();
  update private.reglages set valeur = case when p_arret then 'oui' else 'non' end where cle = 'envois_arret_general';
  if p_arret then
    perform private.lever_alerte(null, true, 'attention', 'envois', 'Arrêt général des envois',
      jsonb_build_object('motif', left(p_motif, 300), 'par', v_acteur.acteur_libelle), 'envois:arret_general');
  else
    update public.alertes
       set acquittee_le = now(), detail = detail || jsonb_build_object('resolution', 'envois repris', 'motif', left(p_motif, 300))
     where client_id is null and cle_regroupement = 'envois:arret_general' and acquittee_le is null;
  end if;
end $$;


--
-- Name: attendu_valide(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.attendu_valide(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  e jsonb;
  j jsonb;
begin
  if p is null then
    return true;
  end if;
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) = 0 then
    return false;
  end if;
  for e in select * from jsonb_array_elements(p) loop
    if jsonb_typeof(e) <> 'object'
       or exists (select 1 from jsonb_object_keys(e) x where x not in ('jours', 'avant', 'depuis', 'alerter', 'titre'))
       or jsonb_typeof(e -> 'jours') is distinct from 'array'
       or coalesce(e ->> 'avant', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or (e ? 'alerter' and jsonb_typeof(e -> 'alerter') <> 'boolean')
       or (e ? 'titre' and (jsonb_typeof(e -> 'titre') <> 'string' or char_length(e ->> 'titre') not between 1 and 200)) then
      return false;
    end if;
    if jsonb_array_length(e -> 'jours') = 0 then
      return false;
    end if;
    if e ? 'depuis' then
      if coalesce(e ->> 'depuis', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
        return false;
      end if;
      if (e ->> 'depuis')::time >= (e ->> 'avant')::time then
        return false;
      end if;
    end if;
    for j in select * from jsonb_array_elements(e -> 'jours') loop
      if jsonb_typeof(j) <> 'number' or j::text !~ '^[1-7]$' then
        return false;
      end if;
    end loop;
  end loop;
  return true;
end $_$;


--
-- Name: avancer_jeu(uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.avancer_jeu(p_jeu uuid, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_releve uuid;
  v_lignes integer;
  n integer := 0;
begin
  perform 1 from public.branchements_jeux where id = p_jeu for update;
  loop
    exit when exists (select 1 from public.instantanes where jeu_id = p_jeu and statut = 'a_appliquer');
    select i.id, i.releve_id, i.lignes into v_id, v_releve, v_lignes from public.instantanes i
    where i.jeu_id = p_jeu and i.statut = 'lu'
    order by i.recu_le, i.id
    limit 1;
    exit when not found;
    exit when p_limite is not null
              and coalesce(v_lignes, 0) + (select j.lignes from public.branchements_jeux j where j.id = p_jeu) > p_limite;
    perform private.finaliser_instantane(v_id);
    perform private.publier_releve(v_releve);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: avancer_releves(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.avancer_releves() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  n integer := 0;
begin
  for r in
    select distinct i.jeu_id from public.instantanes i
    where i.statut = 'lu'
      and not exists (select 1 from public.instantanes k where k.jeu_id = i.jeu_id and k.statut = 'a_appliquer')
  loop
    n := n + private.avancer_jeu(r.jeu_id, null);
  end loop;
  return n;
end $$;


--
-- Name: battre(uuid, text, jsonb, interval); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.battre(p_client uuid, p_module text, p_detail jsonb DEFAULT '{}'::jsonb, p_attendu interval DEFAULT NULL::interval) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.battements as b (client_id, module, dernier_le, attendu_toutes, detail)
  values (p_client, p_module, now(), coalesce(p_attendu, interval '1 day'), coalesce(p_detail, '{}'::jsonb))
  on conflict (client_id, module) do update
    set dernier_le = now(), detail = coalesce(p_detail, '{}'::jsonb), attendu_toutes = coalesce(p_attendu, b.attendu_toutes), actif = true;
  update public.alertes set acquittee_le = now(), detail = detail || jsonb_build_object('resolution', 'le module bat de nouveau')
   where client_id = p_client and cle_regroupement = 'battement:' || p_module and acquittee_le is null;
end $$;


--
-- Name: brancher(uuid, text, text, text, text, uuid, text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.brancher(p_client uuid, p_module text, p_logiciel text, p_voie text, p_libelle text, p_entite uuid DEFAULT NULL::uuid, p_fuseau text DEFAULT NULL::text, p_jeux text[] DEFAULT NULL::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_code text;
begin
  perform private.exiger_gestion_releve(p_client, p_entite);
  if exists (select 1 from public.branchements b
             where b.client_id = p_client and b.module = p_module and b.logiciel = p_logiciel
               and b.entite_id is not distinct from p_entite) then
    raise exception 'Ce logiciel est déjà branché pour ce module et cette entité.' using errcode = '23505';
  end if;
  insert into public.branchements (client_id, entite_id, module, logiciel, libelle, voie, fuseau, cree_par)
  values (p_client, p_entite, p_module, p_logiciel, p_libelle, p_voie,
          coalesce(p_fuseau,
                   (select e.fuseau from public.entites e where e.client_id = p_client and e.id = p_entite),
                   (select e.fuseau from public.entites e where e.client_id = p_client and e.principale),
                   'Europe/Paris'),
          (select auth.uid()))
  returning id into v_id;
  foreach v_code in array coalesce(p_jeux, array(
    select distinct m.code from public.modeles_jeux m where m.module = p_module and m.logiciel = p_logiciel order by m.code)) loop
    if p_jeux is not null and private.modele_pour(p_module, p_logiciel, v_code) is null then
      raise exception 'Aucun modèle « % » pour %, %.', v_code, p_module, p_logiciel using errcode = 'P0002';
    end if;
    perform private.declarer_jeu(v_id, v_code, '{}'::jsonb);
  end loop;
  return v_id;
end $$;


--
-- Name: capacites_valides(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.capacites_valides(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  k text;
  v jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    return false;
  end if;
  for k, v in select * from jsonb_each(p) loop
    if k !~ '^[a-z][a-z0-9_.]{1,59}$' or jsonb_typeof(v) <> 'object'
       or exists (select 1 from jsonb_object_keys(v) x
                  where x not in ('lecture', 'action', 'tenue', 'mesure', 'mesure_le', 'note')) then
      return false;
    end if;
    if (v ? 'lecture' and jsonb_typeof(v -> 'lecture') <> 'boolean')
       or (v ? 'action' and coalesce(v ->> 'action', '') not in ('aucune', 'flux', 'ecriture'))
       or (v ? 'tenue' and coalesce(v ->> 'tenue', '') not in ('tenu', 'partiel', 'non_tenu', 'inconnu'))
       or (v ? 'mesure' and jsonb_typeof(v -> 'mesure') <> 'object')
       or (v ? 'mesure_le' and jsonb_typeof(v -> 'mesure_le') <> 'string')
       or (v ? 'note' and (jsonb_typeof(v -> 'note') <> 'string' or char_length(v ->> 'note') > 300)) then
      return false;
    end if;
  end loop;
  return true;
end $_$;


--
-- Name: champs_changes(jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.champs_changes(p_avant jsonb, p_apres jsonb, p_anom_avant jsonb, p_anom_apres jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(distinct k order by k), '{}')
  from jsonb_object_keys(coalesce(p_avant, '{}'::jsonb) || coalesce(p_apres, '{}'::jsonb)
                         || coalesce(p_anom_avant, '{}'::jsonb) || coalesce(p_anom_apres, '{}'::jsonb)) k
  where (p_avant -> k) is distinct from (p_apres -> k)
     or (p_anom_avant -> k) is distinct from (p_anom_apres -> k)
$$;


