    type_piece text,
    tiers jsonb NOT NULL,
    tiers_nom text,
    tiers_ref text,
    depuis timestamp with time zone DEFAULT now() NOT NULL,
    echeance timestamp with time zone,
    territoire text,
    date_promise date,
    date_promise_initiale date,
    glissements smallint DEFAULT 0 NOT NULL,
    plan jsonb DEFAULT '{}'::jsonb NOT NULL,
    relances smallint DEFAULT 0 NOT NULL,
    derniere_relance_le timestamp with time zone,
