    CONSTRAINT envois_objet_id_check CHECK (((char_length(objet_id) >= 1) AND (char_length(objet_id) <= 120))),
    CONSTRAINT envois_objet_type_check CHECK ((objet_type ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
