    CONSTRAINT envois_repondre_a_check CHECK ((char_length(repondre_a) <= 254)),
    CONSTRAINT envois_statut_check CHECK ((statut = ANY (ARRAY['a_valider'::text, 'differe'::text, 'pret'::text, 'en_cours'::text, 'envoye'::text, 'bloque'::text, 'refuse'::text, 'annule'::text, 'expire'::text, 'echec'::text]))),
    CONSTRAINT envois_verrou_check CHECK ((char_length(verrou) <= 60))
);


--
-- Name: clore_demande_envoi(public.envois, boolean, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.clore_demande_envoi(p_e public.envois, p_executee boolean, p_motif text, p_fin text DEFAULT 'annulee'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_statut text;
begin
  if p_e.demande_id is null then
    return;
  end if;
  select d.statut into v_statut from public.demandes_validation d where d.id = p_e.demande_id for update;
  if v_statut = 'approuvee' or (v_statut = 'echec_execution' and p_executee) then
    update public.demandes_validation
       set statut = case when p_executee then 'executee' else 'echec_execution' end,
           motif_echec = case when p_executee then null else left(p_motif, 500) end
     where id = p_e.demande_id;
  elsif v_statut = 'en_attente' and not p_e.adossee and not p_executee then
    update public.demandes_validation set statut = p_fin where id = p_e.demande_id;
  end if;
end $$;


--
-- Name: clore_envoi(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.clore_envoi(p_envoi uuid, p_statut text, p_verrou text, p_motif text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
begin
  update public.envois
     set statut = p_statut, verrou = coalesce(p_verrou, verrou), motif = left(p_motif, 500), reprise_le = null,
         bail_jusqu_au = null, clos_le = now()
   where id = p_envoi
     and (statut in ('a_valider', 'differe', 'pret') or (statut = 'en_cours' and p_statut in ('bloque', 'annule', 'expire')))
  returning * into e;
  if not found then
    return false;
  end if;
  perform private.clore_demande_envoi(e, false, p_motif, case when p_statut = 'expire' then 'expiree' else 'annulee' end);
  if p_statut in ('bloque', 'refuse', 'expire') then
    perform private.publier_envoi(e, p_statut);
  end if;
  return true;
end $$;


--
-- Name: clore_suivi(uuid, text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.clore_suivi(p_suivi uuid, p_issue text, p_piece uuid DEFAULT NULL::uuid, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s public.suivis;
  v_uid uuid := (select auth.uid());
  v_statut text;
  r record;
begin
  s := private.charger_suivi(p_suivi);
  if s.statut <> 'ouvert' then
    raise exception 'Ce suivi est déjà clos (%).', s.statut using errcode = '55000';
  end if;
  v_statut := case p_issue when 'recu' then 'recu' when 'repondu' then 'recu' when 'paye' then 'recu' when 'livre' then 'recu'
                           when 'signe' then 'recu' when 'abandonne' then 'abandonne' when 'annule' then 'annule' end;
  if v_statut is null then
    raise exception 'Issue inconnue : recu, repondu, paye, livre, signe, abandonne ou annule.' using errcode = '22023';
  end if;
  if v_statut <> 'recu' and nullif(btrim(p_detail), '') is null then
    raise exception 'Un abandon ou une annulation dit pourquoi.' using errcode = '22023';
  end if;
  if p_piece is not null and not exists (
       select 1 from public.pieces p where p.client_id = s.client_id and p.id = p_piece) then
    raise exception 'Pièce introuvable dans cette organisation.' using errcode = '22023';
  end if;
  update public.suivis
     set statut = v_statut, issue = left(coalesce(nullif(btrim(p_detail), ''), p_issue), 300), piece_id = p_piece,
         clos_par = v_uid, clos_le = now(), prochaine_relance_le = null
   where id = s.id
  returning * into s;
  -- Une relance en attente n'a plus lieu d'être.
  for r in select e.id from public.envois e where e.suivi_id = s.id and e.statut in ('a_valider', 'differe', 'pret') loop
    perform private.clore_envoi(r.id, 'annule', 'ANNULE', 'Le suivi est clos : la relance n''a plus lieu d''être.');
  end loop;
  perform private.noter_evenement_suivi(s, 'cloture', null, null,
    jsonb_build_object('issue', p_issue, 'statut', v_statut, 'piece', p_piece, 'relances', s.relances, 'glissements', s.glissements,
                       'age_jours', extract(day from (now() - s.depuis))), v_uid);
  perform private.publier_evenement(s.client_id, 'suivi.clos.' || s.module,
    jsonb_build_object('suivi', s.id, 'module', s.module, 'objet_type', s.objet_type, 'objet_id', s.objet_id,
                       'statut', v_statut, 'issue', p_issue, 'piece', p_piece, 'relances', s.relances, 'glissements', s.glissements),
    s.id::text || ':clos');
end $$;


--
-- Name: codes_sensibles(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.codes_sensibles(p_colonnes jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(k order by k), '{}')
  from jsonb_each(coalesce(p_colonnes, '{}'::jsonb)) as e(k, v)
  where v -> 'sensible' = 'true'::jsonb
$$;


--
-- Name: colonnes_valides(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.colonnes_valides(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  k text;
  v jsonb;
  e jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    return false;
  end if;
  for k, v in select * from jsonb_each(p) loop
    if k !~ '^[a-z][a-z0-9_]{0,62}$' or jsonb_typeof(v) <> 'object' then
      return false;
    end if;
    if exists (select 1 from jsonb_object_keys(v) x
               where x not in ('type', 'entetes', 'format', 'obligatoire', 'facultative', 'sensible', 'libelle')) then
      return false;
    end if;
    if coalesce(v ->> 'type', '') not in ('texte', 'entier', 'decimal', 'date', 'dateheure', 'heure', 'booleen') then
      return false;
    end if;
    if v ? 'entetes' then
      if jsonb_typeof(v -> 'entetes') <> 'array' or jsonb_array_length(v -> 'entetes') = 0 then
        return false;
      end if;
      for e in select * from jsonb_array_elements(v -> 'entetes') loop
        if jsonb_typeof(e) <> 'string' or char_length(btrim(e #>> '{}')) not between 1 and 200 then
          return false;
        end if;
      end loop;
    end if;
    if v ? 'format' and (jsonb_typeof(v -> 'format') <> 'string' or not private.format_valide(v ->> 'type', v ->> 'format')) then
      return false;
    end if;
    if (v ? 'obligatoire' and jsonb_typeof(v -> 'obligatoire') <> 'boolean')
       or (v ? 'facultative' and jsonb_typeof(v -> 'facultative') <> 'boolean')
       or (v ? 'sensible' and jsonb_typeof(v -> 'sensible') <> 'boolean')
       or (v ? 'libelle' and (jsonb_typeof(v -> 'libelle') <> 'string' or char_length(v ->> 'libelle') > 200)) then
      return false;
    end if;
  end loop;
  return true;
end $_$;


--
-- Name: commencer_envoi(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commencer_envoi(p_envoi uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
  v_uid uuid := (select auth.uid());
  v jsonb;
  v_canal private.canaux_envoi;
  v_exp public.expediteurs;
  v_g public.gabarits_messages;
  v_pieces jsonb;
  v_essai_adresse text;
begin
  select * into e from public.envois where id = p_envoi;
  if e.id is null then
    return jsonb_build_object('envoyer', false, 'raison', 'introuvable');
  end if;
  if v_uid is not null then
    perform private.exiger_acteur_envoi(e.client_id, e.entite_id, e.objet_type, e.objet_id);
    if e.fournisseur is distinct from 'manuel' then
      raise exception 'Cet envoi part par l''ouvrier d''envoi, pas à la main.' using errcode = '42501';
    end if;
  else
    perform private.exiger_ouvrier();
  end if;

  perform pg_advisory_xact_lock(hashtextextended('omega.envois:' || e.client_id::text, 0));
  select * into e from public.envois where id = p_envoi for update;
  if e.statut not in ('pret', 'en_cours') then
    return jsonb_build_object('envoyer', false, 'statut', e.statut, 'verrou', e.verrou, 'motif', e.motif);
  end if;
  if e.echeance <= now() then
    perform private.clore_envoi(p_envoi, 'expire', 'ECHEANCE', 'L''échéance de cet envoi est passée avant son départ.');
    return jsonb_build_object('envoyer', false, 'statut', 'expire', 'verrou', 'ECHEANCE');
  end if;

  v := private.verrous_envoi(e, true, now());
  if v ->> 'code' is not null then
    if (v ->> 'definitif')::boolean then
      perform private.clore_envoi(p_envoi, 'bloque', v ->> 'code', v ->> 'motif');
      return jsonb_build_object('envoyer', false, 'statut', 'bloque', 'verrou', v ->> 'code', 'motif', v ->> 'motif');
    end if;
    update public.envois
       set statut = 'differe', verrou = v ->> 'code', motif = v ->> 'motif', reprise_le = (v ->> 'reprise')::timestamptz,
           bail_jusqu_au = null
     where id = p_envoi;
    return jsonb_build_object('envoyer', false, 'statut', 'differe', 'verrou', v ->> 'code', 'motif', v ->> 'motif',
                              'reprise_le', v ->> 'reprise');
  end if;
  if (v ->> 'fournisseur') is distinct from e.fournisseur then
    -- L'expéditeur a changé depuis « pret » : l'envoi repart vers le bon fournisseur.
    update public.envois
       set statut = 'pret', mode = v ->> 'mode', expediteur_id = (v ->> 'expediteur')::uuid,
           fournisseur = v ->> 'fournisseur', pret_le = now(), bail_jusqu_au = null
     where id = p_envoi
    returning * into e;
    perform private.confier_envoi(e);
    return jsonb_build_object('envoyer', false, 'statut', 'pret', 'raison', 'fournisseur_change', 'fournisseur', e.fournisseur);
  end if;

  update public.envois
     set statut = 'en_cours', essais = essais + 1, mode = v ->> 'mode', expediteur_id = (v ->> 'expediteur')::uuid,
         verrou = null, motif = null, reprise_le = null,
         bail_jusqu_au = now() + case when e.fournisseur = 'manuel' then interval '2 hours' else interval '15 minutes' end
   where id = p_envoi
  returning * into e;

  select * into v_canal from private.canaux_envoi c where c.canal = e.canal;
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'chemin', p.chemin, 'nom', p.nom_fichier, 'mime', p.mime,
                                               'octets', p.octets, 'sha256', p.sha256) order by p.nom_fichier), '[]'::jsonb)
  into v_pieces
  from public.pieces p where p.client_id = e.client_id and p.id = any (e.pieces);

  if e.mode = 'essai' then
    v_essai_adresse := private.reglages_envois_effectifs(e.client_id, e.module) ->> 'essai_adresse';
    return jsonb_build_object(
      'envoyer', true, 'envoi', e.id, 'mode', 'essai', 'module', e.module, 'canal', 'email', 'canal_reel', e.canal,
      'fournisseur', e.fournisseur,
      'expediteur', jsonb_build_object(
        'identite', (select g.valeur from private.reglages g where g.cle = 'envois_essai_expediteur'),
        'nom_affiche', (select g.valeur from private.reglages g where g.cle = 'envois_essai_nom'),
        'repondre_a', null, 'parametres', '{}'::jsonb, 'secret', false),
      'destinataire', jsonb_build_object('adresse', v_essai_adresse, 'nom', null, 'langue', 'fr', 'professionnel', true),
      'sujet', '[ESSAI] ' || coalesce(e.sujet, v_canal.libelle || ' pour ' || coalesce(e.destinataire_nom, e.destinataire_adresse)),
      'corps', 'Message d''essai. En service réel, il partirait '
               || case e.canal when 'email' then 'par courriel' when 'whatsapp' then 'par WhatsApp' when 'sms' then 'par SMS'
                               when 'lre' then 'en lettre recommandée électronique' else 'par un appel' end
               || ' à ' || coalesce(e.destinataire_nom || ' ', '') || '<' || e.destinataire_adresse || '>.'
               || E'\n\n' || e.corps,
      'pieces', v_pieces, 'modele_externe', null, 'parametres_modele', '[]'::jsonb, 'langue', 'fr',
      'repondre_a', null, 'transactionnel', e.transactionnel, 'cle', e.id,
      'objet', jsonb_build_object('type', e.objet_type, 'id', e.objet_id));
  end if;

  select * into v_exp from public.expediteurs x where x.id = e.expediteur_id;
  select * into v_g from public.gabarits_messages g where g.id = e.gabarit_id;
  return jsonb_build_object(
    'envoyer', true, 'envoi', e.id, 'mode', 'reel', 'module', e.module, 'canal', e.canal, 'fournisseur', e.fournisseur,
    'expediteur', jsonb_build_object('identite', v_exp.identite, 'nom_affiche', v_exp.nom_affiche,
                                     'repondre_a', v_exp.repondre_a, 'parametres', v_exp.parametres,
                                     'secret', v_exp.secret_nom is not null),
    'destinataire', jsonb_build_object('adresse', e.destinataire_adresse, 'nom', e.destinataire_nom,
                                       'langue', e.destinataire_langue, 'professionnel', e.destinataire_professionnel),
    'sujet', e.sujet, 'corps', e.corps, 'pieces', v_pieces,
    'modele_externe', v_g.modele_externe, 'langue', coalesce(v_g.langue, e.destinataire_langue),
    'parametres_modele', case when v_g.id is null then '[]'::jsonb
                              else private.rendre_gabarit(v_g, e.variables, e.client_id, e.entite_id) -> 'parametres' end,
    'repondre_a', coalesce(e.repondre_a, v_exp.repondre_a), 'transactionnel', e.transactionnel, 'cle', e.id,
    'objet', jsonb_build_object('type', e.objet_type, 'id', e.objet_id));
end $$;


--
-- Name: commencer_lecture(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commencer_lecture(p_piece uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- « en_lecture » : un essai précédent s'est interrompu, la file le reprend.
  update public.pieces set statut = 'en_lecture'
   where id = p_piece and objet_id is not null and statut in ('recue', 'en_lecture');
  return found;
end $$;


--
-- Name: commencer_releve(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commencer_releve(p_instantane uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  b public.branchements;
  p public.pieces;
begin
  select * into i from public.instantanes where id = p_instantane for update;
  if not found or i.statut not in ('recu', 'en_lecture') then
    return null;
  end if;
  select * into b from public.branchements where id = i.branchement_id;
  select * into p from public.pieces where id = i.piece_id;
  -- Un essai interrompu repart de zéro.
  delete from public.instantanes_lignes where instantane_id = i.id;
  if i.statut = 'recu' then
    update public.instantanes set statut = 'en_lecture' where id = i.id;
  end if;
  return jsonb_build_object(
    'instantane', i.id, 'client', i.client_id, 'branchement', b.id, 'module', b.module, 'logiciel', b.logiciel,
    'fuseau', b.fuseau, 'nom_fichier', i.nom_fichier, 'chemin', p.chemin, 'mime', p.mime, 'octets', i.octets,
    'sha256', i.sha256, 'force', i.force,
    'jeu', (select x.code from public.branchements_jeux x where x.id = i.jeu_id),
    'jeux', coalesce((
      select jsonb_agg(jsonb_build_object('code', x.code, 'libelle', x.libelle, 'motif_fichier', x.motif_fichier,
                                          'entetes', to_jsonb(x.entetes), 'colonnes', x.colonnes, 'cle', to_jsonb(x.cle),
                                          'options', x.options) order by x.code)
      from public.branchements_jeux x where x.branchement_id = b.id and (x.actif or x.id = i.jeu_id)), '[]'::jsonb));
end $$;


--
-- Name: confier_envoi(public.envois); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.confier_envoi(p_e public.envois) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_e.statut = 'pret' and exists (select 1 from private.fournisseurs_envoi f
                                     where f.fournisseur = p_e.fournisseur and f.automatique and f.branche) then
    perform private.deposer_travail(p_e.client_id, p_e.module, 'envois.' || p_e.fournisseur,
                                    jsonb_build_object('envoi', p_e.id), 'envoi:' || p_e.id::text, 0::smallint);
  end if;
end $$;


--
-- Name: confirmer_envoi(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.confirmer_envoi(p_envoi uuid, p_reference text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
begin
  perform private.exiger_ouvrier();
  perform set_config('omega.envois_ouvrier', 'oui', true);
  update public.envois
     set statut = 'envoye', envoye_le = now(), clos_le = now(), erreur = null, bail_jusqu_au = null,
         reference_externe = left(nullif(btrim(p_reference), ''), 300)
   where id = p_envoi and statut = 'en_cours' and fournisseur <> 'manuel'
  returning * into e;
  perform set_config('omega.envois_ouvrier', '', true);
  if e.id is null then
    if exists (select 1 from public.envois x where x.id = p_envoi and x.statut = 'envoye') then
      return;   -- une confirmation rejouée n'est pas une faute
    end if;
    raise exception 'Envoi introuvable, ou pas en cours d''envoi.' using errcode = 'P0002';
  end if;
  perform private.clore_demande_envoi(e, true, null);
  perform private.publier_envoi(e, 'envoye');
end $$;


--
-- Name: confirmer_etat(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.confirmer_etat(p_jeu uuid, p_recu_le timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.branchements_jeux;
  v_module text;
begin
  select * into j from public.branchements_jeux where id = p_jeu;
  select b.module into v_module from public.branchements b where b.id = j.branchement_id;
  update public.branchements_jeux set etat_le = now() where id = j.id;
  with remplaces as (
    update public.instantanes
       set statut = 'remplace', motif = coalesce(motif, 'Un export plus récent a été appliqué.')
     where jeu_id = j.id and statut = 'douteux' and recu_le < p_recu_le
    returning id, piece_id
  )
  update public.pieces p set statut = 'lue' from remplaces r where p.id = r.piece_id and p.statut = 'a_verifier';
  delete from public.instantanes_lignes l using public.instantanes k
   where k.id = l.instantane_id and k.jeu_id = j.id and k.statut = 'remplace';
  if not exists (select 1 from public.instantanes k where k.jeu_id = j.id and k.statut = 'douteux') then
    perform private.fermer_alertes_releve(j.client_id, v_module, 'releve.douteux.' || j.id::text, 'un export a été appliqué');
    perform private.fermer_alertes_releve(j.client_id, v_module, 'releve.douteux_suite.' || j.id::text, 'un export a été appliqué');
  end if;
end $$;


--
-- Name: construire_rapport_du_mois(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.construire_rapport_du_mois(p_client uuid, p_mois date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m0 date := date_trunc('month', p_mois)::date;
  v_contenu jsonb;
  v_empreinte text;
begin
  v_contenu := private.rapport_du_mois(p_client, v_m0, null, false);
  v_empreinte := encode(sha256(convert_to(v_contenu::text, 'UTF8')), 'hex');
  insert into public.rapports_du_mois as r (client_id, mois, contenu, empreinte)
  values (p_client, v_m0, v_contenu, v_empreinte)
  on conflict (client_id, mois) do update
    set contenu = excluded.contenu, empreinte = excluded.empreinte, perime = false, construit_le = now(),
        version = r.version + case when r.empreinte = excluded.empreinte then 0 else 1 end;
  return v_contenu;
end $$;


--
-- Name: controler_battements(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.controler_battements(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record; n integer := 0;
begin
  for r in
    select b.client_id, b.module, b.dernier_le, b.attendu_toutes, c.nom,
           private.debut_plage_courante(b.plages, b.fuseau, p_maintenant) as debut
    from public.battements b join public.clients c on c.id = b.client_id
    where b.actif
  loop
    continue when r.debut is null;
    if greatest(r.dernier_le, r.debut) + r.attendu_toutes * 1.5 < p_maintenant then
      if private.lever_alerte(r.client_id, true, 'critique', 'chien_de_garde',
           format('%s se tait chez %s', upper(r.module), r.nom),
           jsonb_build_object('module', r.module, 'dernier_battement', r.dernier_le, 'attendu_toutes', r.attendu_toutes::text),
           'battement:' || r.module) is not null then
        n := n + 1;
      end if;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: controler_delais(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.controler_delais(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_reste integer;
  v_dus integer[];
  v_rappel integer;
  n integer := 0;
begin
  for r in
    select d.*, t.fuseau from public.delais d join public.territoires t on t.code = d.territoire
    where d.statut = 'ouvert'
    for update of d skip locked
  loop
    v_reste := r.echeance - (p_maintenant at time zone r.fuseau)::date;
    if v_reste < 0 then
      update public.delais set statut = 'depasse', maj_le = now() where id = r.id;
      perform private.publier_evenement(r.client_id, 'delai.depasse.' || r.module,
        jsonb_build_object('delai', r.id, 'module', r.module, 'objet_type', r.objet_type, 'objet_id', r.objet_id,
                           'echeance', r.echeance, 'jours_de_retard', -v_reste),
        r.id::text || ':' || r.echeance::text);
      n := n + 1;
      continue;
    end if;
    v_dus := array(select x from unnest(r.rappels) x where x >= v_reste and not (x = any (r.rappels_faits)));
    if cardinality(v_dus) > 0 then
      v_rappel := (select min(x) from unnest(v_dus) x);
      update public.delais set rappels_faits = rappels_faits || v_dus where id = r.id;
      perform private.publier_evenement(r.client_id, 'delai.proche.' || r.module,
        jsonb_build_object('delai', r.id, 'module', r.module, 'objet_type', r.objet_type, 'objet_id', r.objet_id,
                           'echeance', r.echeance, 'jours_restants', v_reste, 'rappel', v_rappel),
        r.id::text || ':' || r.echeance::text || ':' || v_rappel::text);
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: controler_releves(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.controler_releves(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  e jsonb;
  n integer := 0;
  v_jour date;
  v_avant timestamptz;
  v_depuis timestamptz;
  v_debut timestamptz;
  v_cle text;
begin
  -- 1. Le fichier attendu avant une heure fixe.
  for r in
    select j.id, j.client_id, j.branchement_id, j.code, j.libelle, j.attendu, j.dernier_recu_le, j.etat_le,
           j.retard_signale, b.module, b.libelle as b_libelle, b.fuseau
    from public.branchements_jeux j join public.branchements b on b.id = j.branchement_id
    where j.actif and b.statut = 'actif' and j.attendu is not null
  loop
    v_jour := (p_maintenant at time zone r.fuseau)::date;
    for e in select * from jsonb_array_elements(r.attendu) loop
      continue when not ((e -> 'jours') @> to_jsonb(extract(isodow from v_jour)::integer));
      v_avant := (v_jour + (e ->> 'avant')::time) at time zone r.fuseau;
      continue when p_maintenant < v_avant or (r.retard_signale is not null and r.retard_signale >= v_avant);
      v_depuis := (v_jour + coalesce(e ->> 'depuis', '00:00')::time) at time zone r.fuseau;
      continue when exists (
        select 1 from public.instantanes i
        where i.recu_le >= v_depuis
          and (i.jeu_id = r.id or (i.jeu_id is null and i.branchement_id = r.branchement_id and i.statut in ('recu', 'en_lecture'))));
      v_cle := 'releve.en_retard.' || r.id::text || '.' || to_char(v_jour, 'YYYYMMDD');
      perform private.publier_evenement(r.client_id, 'releve.en_retard.' || r.module,
        jsonb_build_object('jeu', r.id, 'code', r.code, 'branchement', r.branchement_id, 'module', r.module,
                           'avant', v_avant, 'depuis', v_depuis, 'dernier_recu_le', r.dernier_recu_le, 'etat_le', r.etat_le),
        r.id::text || ':' || to_char(v_jour, 'YYYYMMDD'));
      if coalesce((e ->> 'alerter')::boolean, true) then
        perform private.lever_alerte_module(r.client_id, r.module, 'attention',
          coalesce(e ->> 'titre', left(format('Le fichier « %s » (%s) n''est pas arrivé à %s : les données datent %s',
                   r.libelle, r.b_libelle, e ->> 'avant',
                   coalesce('du ' || to_char(r.etat_le at time zone r.fuseau, 'DD/MM à HH24:MI'), 'd''avant le premier export')), 200)),
          jsonb_build_object('jeu', r.code, 'avant', v_avant, 'dernier_recu_le', r.dernier_recu_le),
          v_cle, true, null);
      end if;
      update public.branchements_jeux set retard_signale = v_avant where id = r.id;
      n := n + 1;
    end loop;
  end loop;

  -- 2. Le jeu qui se tait dans sa plage, au-delà d'une fois et demie son rythme.
  for r in
    select j.id, j.client_id, j.libelle, j.rythme, j.plages, j.cree_le, j.dernier_recu_le,
           b.module, b.libelle as b_libelle, b.fuseau
    from public.branchements_jeux j join public.branchements b on b.id = j.branchement_id
    where j.actif and b.statut = 'actif' and j.rythme is not null
  loop
    v_debut := private.debut_plage_courante(r.plages, r.fuseau, p_maintenant);
    continue when v_debut is null;
    if greatest(coalesce(r.dernier_recu_le, r.cree_le), v_debut) + r.rythme * 1.5 < p_maintenant then
      if private.lever_alerte_module(r.client_id, r.module, 'attention',
           left(format('Plus aucun fichier « %s » (%s) depuis %s', r.libelle, r.b_libelle,
                       coalesce(to_char(r.dernier_recu_le at time zone r.fuseau, 'DD/MM à HH24:MI'), 'le branchement')), 200),
           jsonb_build_object('jeu', r.id, 'rythme', r.rythme::text, 'dernier_recu_le', r.dernier_recu_le),
           'releve.muet.' || r.id::text, true, null) is not null then
        n := n + 1;
      end if;
    end if;
  end loop;

  -- 3. L'export lu que le module n'applique pas.
  for r in
    select distinct on (i.jeu_id) i.jeu_id, i.client_id, i.finalise_le, j.libelle, b.module, b.libelle as b_libelle
    from public.instantanes i
    join public.branchements_jeux j on j.id = i.jeu_id
    join public.branchements b on b.id = i.branchement_id
    where i.statut = 'a_appliquer' and i.finalise_le < p_maintenant - interval '2 hours'
    order by i.jeu_id, i.finalise_le
  loop
    if private.lever_alerte_module(r.client_id, r.module, 'critique',
         left(format('%s n''applique pas le relevé « %s » (%s) depuis %s', upper(r.module), r.libelle, r.b_libelle,
                     to_char(r.finalise_le at time zone 'UTC', 'DD/MM HH24:MI "UTC"')), 200),
         jsonb_build_object('jeu', r.jeu_id, 'depuis', r.finalise_le),
         'releve.en_souffrance.' || r.jeu_id::text, false, null) is not null then
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: controler_suivis(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.controler_suivis(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s public.suivis;
  v_relances integer := 0;
  v_expires integer := 0;
begin
  for s in
    select x.* from public.suivis x
    where x.statut = 'ouvert' and x.echeance is not null and x.echeance <= p_maintenant
    order by x.echeance limit 500
    for update skip locked
  loop
    update public.suivis set statut = 'expire', issue = 'Sans réponse à l''échéance.', clos_le = now(), prochaine_relance_le = null
     where id = s.id returning * into s;
    perform private.noter_evenement_suivi(s, 'expiration', s.date_promise, null,
      jsonb_build_object('relances', s.relances, 'glissements', s.glissements, 'age_jours', extract(day from (p_maintenant - s.depuis))));
    perform private.publier_evenement(s.client_id, 'suivi.expire.' || s.module,
      jsonb_build_object('suivi', s.id, 'module', s.module, 'objet_type', s.objet_type, 'objet_id', s.objet_id,
                         'attendu', s.attendu, 'relances', s.relances, 'glissements', s.glissements, 'echeance', s.echeance),
      s.id::text || ':expire');
    v_expires := v_expires + 1;
  end loop;
  for s in
    select x.* from public.suivis x
    where x.statut = 'ouvert' and x.prochaine_relance_le is not null and x.prochaine_relance_le <= p_maintenant
    order by x.prochaine_relance_le limit 500
    for update skip locked
  loop
    perform private.relancer_suivi(s, p_maintenant);
    v_relances := v_relances + 1;
  end loop;
  return jsonb_build_object('relances', v_relances, 'expires', v_expires);
end $$;


--
-- Name: controler_travaux(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.controler_travaux(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record; n integer := 0;
begin
  for r in
    select t.client_id, t.module, min(t.prochain_le) as plus_ancien, count(*) as nombre
    from public.travaux t
    where t.etat = 'a_faire' and t.prochain_le < p_maintenant - interval '2 hours'
    group by t.client_id, t.module
  loop
    if private.lever_alerte(r.client_id, true, 'attention', r.module,
         format('La file de %s n''avance plus (%s travaux en retard)', upper(r.module), r.nombre),
         jsonb_build_object('plus_ancien', r.plus_ancien, 'nombre', r.nombre),
         'file:' || r.module) is not null then
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: creer_entite_principale(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.creer_entite_principale() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  insert into public.entites (client_id, nom, type, siren, principale)
  values (new.id, new.nom, 'societe', case when new.siren ~ '^[0-9]{9}$' then new.siren end, true);
  return new;
end $_$;


--
-- Name: creer_envoi(uuid, text, text, text, text, jsonb, text, jsonb, text, text, uuid[], text, uuid, boolean, boolean, timestamp with time zone, boolean, text, uuid, boolean, uuid, uuid, smallint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.creer_envoi(p_client uuid, p_module text, p_objet_type text, p_objet_id text, p_canal text, p_destinataire jsonb, p_gabarit text, p_variables jsonb, p_sujet text, p_corps text, p_pieces uuid[], p_cle text, p_entite uuid, p_transactionnel boolean, p_donnees_sante boolean, p_echeance timestamp with time zone, p_direct boolean, p_repondre_a text, p_demande uuid, p_espacement boolean, p_prepare_par uuid, p_suivi uuid, p_rang smallint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_canal private.canaux_envoi;
  v_module private.modules_envois;
  v_r jsonb;
  v_dest jsonb;
  v_g public.gabarits_messages;
  v_rendu jsonb;
  v_sujet text;
  v_corps text;
  v_transactionnel boolean;
  v_sante boolean;
  v_espacement boolean;
  v_contexte_sante boolean;
  v_pieces uuid[] := coalesce(array(select distinct x from unnest(coalesce(p_pieces, '{}'::uuid[])) x), '{}');
  v_octets bigint;
  v_mode text;
  v_e public.envois;
  v_v jsonb;
  v_d public.demandes_validation;
  v_resume text;
begin
  if not exists (select 1 from public.clients c where c.id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  if p_module is null or p_module !~ '^[a-z][a-z_]{1,29}$' then
    raise exception 'Module inconnu : %.', coalesce(p_module, 'vide') using errcode = '22023';
  end if;
  select * into v_canal from private.canaux_envoi c where c.canal = p_canal;
  if v_canal.canal is null then
    raise exception 'Canal inconnu : %. Canaux : email, whatsapp, sms, lre, appel.', coalesce(p_canal, 'vide')
      using errcode = '22023';
  end if;
  if (p_objet_type is null) <> (p_objet_id is null) then
    raise exception 'Un objet se désigne par son type et son identifiant.' using errcode = '22023';
  end if;
  if p_entite is not null and not exists (select 1 from public.entites e where e.client_id = p_client and e.id = p_entite) then
    raise exception 'Entité introuvable dans cette organisation.' using errcode = '22023';
  end if;
  if p_echeance is not null and p_echeance <= now() then
    raise exception 'L''échéance d''un envoi est dans le futur.' using errcode = '22023';
  end if;
  if p_repondre_a is not null and private.normaliser_email(p_repondre_a) is null then
    raise exception 'Adresse de réponse invalide.' using errcode = '22023';
  end if;

  v_dest := private.resoudre_destinataire(p_client, p_canal, p_destinataire, p_entite);
  select * into v_module from private.modules_envois m where m.module = p_module;
  v_r := private.reglages_envois_effectifs(p_client, p_module);
  v_contexte_sante := coalesce(v_module.sante, false) or (v_r ->> 'sante')::boolean;

  -- Le contenu : un gabarit validé, ou un texte.
  if p_gabarit is not null then
    if p_sujet is not null or p_corps is not null then
      raise exception 'Un gabarit ou un texte (sujet, corps), pas les deux.' using errcode = '22023';
    end if;
    v_g := private.gabarit_pour(p_client, p_module, p_gabarit, v_dest ->> 'langue');
    if v_g.id is null then
      raise exception 'Aucun gabarit validé « % » pour le module %.', p_gabarit, p_module using errcode = 'P0002';
    end if;
    if v_g.canal <> p_canal then
      raise exception 'Le gabarit % est écrit pour le canal %, pas pour %.', p_gabarit, v_g.canal, p_canal
        using errcode = '22023';
    end if;
    v_rendu := private.rendre_gabarit(v_g, p_variables, p_client, p_entite);
    v_sujet := v_rendu ->> 'sujet';
    v_corps := v_rendu ->> 'corps';
    v_transactionnel := v_g.transactionnel;
    -- Dans un contexte de santé, un texte libre peut nommer un patient : il porte de la santé.
    v_sante := v_g.donnees_sante or (v_contexte_sante and (v_rendu ->> 'texte_libre')::boolean);
    v_espacement := v_g.espacement;
  else
    if nullif(btrim(p_corps), '') is null then
      raise exception 'Un envoi sans gabarit porte un corps.' using errcode = '22023';
    end if;
    if p_variables is not null and p_variables <> '{}'::jsonb then
      raise exception 'Des variables sans gabarit : rien à remplir.' using errcode = '22023';
    end if;
    v_sujet := nullif(btrim(p_sujet), '');
    v_corps := p_corps;
    v_transactionnel := coalesce(p_transactionnel, false);
    v_sante := coalesce(p_donnees_sante, false) or v_contexte_sante;
    v_espacement := coalesce(p_espacement, true);
  end if;
  if v_canal.sujet = 'obligatoire' and v_sujet is null then
    raise exception 'Un envoi par % porte un sujet.', lower(v_canal.libelle) using errcode = '22023';
  end if;
  if v_canal.sujet = 'interdit' and v_sujet is not null then
    raise exception 'Un envoi par % n''a pas de sujet.', v_canal.libelle using errcode = '22023';
  end if;
  if char_length(v_corps) > v_canal.longueur_max or char_length(coalesce(v_sujet, '')) > 300 then
    raise exception 'Message trop long pour le canal % : % caractères au plus.', v_canal.libelle, v_canal.longueur_max
      using errcode = '22023';
  end if;

  if cardinality(v_pieces) > 0 then
    if not v_canal.pieces then
      raise exception 'Le canal % ne porte pas de pièce jointe.', v_canal.libelle using errcode = '22023';
    end if;
    if cardinality(v_pieces) > 10 then
      raise exception 'Dix pièces jointes au plus.' using errcode = '22023';
    end if;
    if (select count(*) from public.pieces p
        where p.client_id = p_client and p.id = any (v_pieces) and p.statut not in ('rejetee', 'echec')) <> cardinality(v_pieces) then
      raise exception 'Pièce jointe introuvable dans cette organisation, ou illisible.' using errcode = '22023';
    end if;
    select coalesce(sum(p.octets), 0) into v_octets from public.pieces p where p.client_id = p_client and p.id = any (v_pieces);
    if v_octets > 15 * 1024 * 1024 then
      raise exception 'Pièces jointes trop lourdes : 15 Mo au plus.' using errcode = '22023';
    end if;
    v_sante := v_sante or v_contexte_sante;   -- une pièce d'un contexte de santé en porte
  end if;

  v_mode := case when v_r ->> 'mode' = 'essai' then 'essai' else 'reel' end;

  -- La décision métier à laquelle l'envoi s'adosse : vérifiée avant tout, liée dès la naissance.
  if p_demande is not null then
    select * into v_d from public.demandes_validation d where d.id = p_demande for update;
    if v_d.id is null or v_d.client_id <> p_client then
      raise exception 'Décision introuvable dans cette organisation.' using errcode = 'P0002';
    end if;
    if v_d.module <> p_module or v_d.type_action = 'politique.activer'
       or v_d.objet_type is distinct from p_objet_type or v_d.objet_id is distinct from p_objet_id then
      raise exception 'Cette décision ne porte pas sur cet envoi : même module, même objet.' using errcode = '22023';
    end if;
    if v_d.statut not in ('en_attente', 'approuvee') then
      raise exception 'Cette décision n''est plus ouverte (%).', v_d.statut using errcode = '23514';
    end if;
    if exists (select 1 from public.envois x where x.demande_id = p_demande) then
      raise exception 'Cette décision porte déjà un envoi.' using errcode = '23505';
    end if;
  end if;

  insert into public.envois (
    client_id, entite_id, module, objet_type, objet_id, canal,
    destinataire_adresse, destinataire_empreinte, destinataire_nom, destinataire_ref, destinataire_membre,
    destinataire_fuseau, destinataire_territoire, destinataire_professionnel, destinataire_langue,
    gabarit_id, variables, sujet, corps, pieces, empreinte, repondre_a, transactionnel, donnees_sante, espacement,
    demande_id, adossee, direct, mode, statut, verrou, motif, echeance, suivi_id, rang, cle_idempotence, prepare_par,
    cree_le, clos_le)
  values (
    p_client, p_entite, p_module, p_objet_type, p_objet_id, p_canal,
    v_dest ->> 'adresse', private.empreinte_adresse(p_client, v_dest ->> 'adresse'), v_dest ->> 'nom', v_dest ->> 'ref',
    (v_dest ->> 'membre')::uuid, v_dest ->> 'fuseau', v_dest ->> 'territoire', (v_dest ->> 'professionnel')::boolean,
    v_dest ->> 'langue',
    v_g.id, case when v_g.id is null then '{}'::jsonb else coalesce(p_variables, '{}'::jsonb) end,
    v_sujet, v_corps, v_pieces,
    private.empreinte_contenu(p_canal, v_dest ->> 'adresse', v_sujet, v_corps, v_pieces),
    private.normaliser_email(p_repondre_a), v_transactionnel, v_sante, v_espacement,
    p_demande, p_demande is not null, coalesce(p_direct, false), v_mode,
    case when v_dest ->> 'adresse' is null then 'bloque' else 'a_valider' end,
    case when v_dest ->> 'adresse' is null then 'DESTINATAIRE_SANS_ADRESSE' end,
    v_dest ->> 'manque', coalesce(p_echeance, now() + interval '7 days'),
    p_suivi, p_rang, p_cle, p_prepare_par, clock_timestamp(),
    case when v_dest ->> 'adresse' is null then now() end)
  returning * into v_e;

  if v_e.statut = 'bloque' then
    perform private.publier_envoi(v_e, 'bloque');
    return v_e.id;
  end if;

  -- Ce qui ne dépend pas de l'heure : un envoi voué au refus ne dérange personne.
  v_v := private.verrous_envoi(v_e, false, now());
  if v_v ->> 'code' is not null then
    perform private.clore_envoi(v_e.id, 'bloque', v_v ->> 'code', v_v ->> 'motif');
    return v_e.id;
  end if;

  if coalesce(p_direct, false) then
    -- Un membre qui en a le droit décide lui-même : c'est sa décision, tracée.
    perform private.envoi_valide(v_e.id);
  elsif p_demande is not null then
    if v_d.statut = 'approuvee' then
      perform private.envoi_valide(v_e.id);
    end if;
  else
    v_resume := case when v_mode = 'essai' then 'Essai — ' else '' end || v_canal.libelle || ' : '
                || coalesce(v_g.libelle, 'message rédigé');
    insert into public.demandes_validation (
      client_id, entite_id, module, type_action, objet_type, objet_id, resume, payload, echeance, cle_idempotence)
    values (
      p_client, p_entite, p_module, 'envoi.' || p_canal, p_objet_type, p_objet_id, left(v_resume, 500),
      jsonb_build_object(
        'envoi', v_e.id, 'canal', p_canal, 'mode', v_mode,
        'destinataire', jsonb_build_object('nom', v_e.destinataire_nom, 'adresse', v_e.destinataire_adresse),
        'gabarit', case when v_g.id is null then null
                        else jsonb_build_object('code', v_g.code, 'version', v_g.version, 'libelle', v_g.libelle) end,
        'sujet', v_sujet, 'corps', v_corps,
        'pieces', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'nom', p.nom_fichier) order by p.nom_fichier), '[]'::jsonb)
                   from public.pieces p where p.client_id = p_client and p.id = any (v_pieces)),
        'transactionnel', v_transactionnel, 'donnees_sante', v_sante),
      v_e.echeance, 'envoi:' || v_e.id::text)
    returning * into v_d;
    update public.envois set demande_id = v_d.id where id = v_e.id;
    if v_d.statut = 'approuvee' then   -- un accord permanent la couvre
      perform private.envoi_valide(v_e.id);
    end if;
  end if;
  return v_e.id;
end $_$;


--
-- Name: dans_equipe(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dans_equipe(p_user uuid, p_equipe uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.equipes_membres m where m.equipe_id = p_equipe and m.user_id = p_user)
$$;


--
-- Name: dans_plages(jsonb, timestamp without time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dans_plages(p_plages jsonb, p_local timestamp without time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from jsonb_array_elements(p_plages) e
    where (e -> 'jours') @> to_jsonb(extract(isodow from p_local)::int)
      and p_local::time >= (e ->> 'debut')::time
      and p_local::time < (e ->> 'fin')::time)
$$;


--
-- Name: dans_portee(jsonb, text, date, date, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dans_portee(p_valeurs jsonb, p_colonne text, p_du date, p_au date, p_perimetre jsonb, p_fuseau text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select (p_perimetre is null or p_valeurs @> p_perimetre)
     and (p_colonne is null
          or coalesce(private.date_de(p_valeurs ->> p_colonne, p_fuseau) between p_du and p_au, true))
$$;


--
-- Name: date_de(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.date_de(p text, p_fuseau text) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  select case
    when p ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then p::date
    when p ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}' then (p::timestamptz at time zone p_fuseau)::date
  end
$_$;


--
-- Name: date_fr(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.date_fr(p timestamp with time zone, p_fuseau text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select to_char(p at time zone p_fuseau, 'DD/MM/YYYY "à" HH24"h"MI')
$$;


--
-- Name: debut_plage_courante(jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.debut_plage_courante(p_plages jsonb, p_fuseau text, p_instant timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_local timestamp;
  v_jour integer;
  v_heure time;
  e jsonb;
begin
  if p_plages is null then
    return '-infinity'::timestamptz;
  end if;
  v_local := p_instant at time zone p_fuseau;
  v_jour := extract(isodow from v_local)::integer;
  v_heure := v_local::time;
  for e in select * from jsonb_array_elements(p_plages) loop
    if (e -> 'jours') @> to_jsonb(v_jour)
       and v_heure >= (e ->> 'debut')::time
       and ((e ->> 'fin') = '24:00' or v_heure < (e ->> 'fin')::time) then
      return (v_local::date + (e ->> 'debut')::time) at time zone p_fuseau;
    end if;
  end loop;
  return null;
end $$;


--
-- Name: declaration_coherente(jsonb, text[], jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.declaration_coherente(p_colonnes jsonb, p_cle text[], p_fenetre jsonb, p_entetes text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  c text;
  v_col text := p_fenetre ->> 'colonne';
begin
  if exists (select 1 from unnest(coalesce(p_entetes, '{}')) e where e is null or char_length(btrim(e)) not between 1 and 200) then
    return false;
  end if;
  if exists (select 1 from unnest(coalesce(p_cle, '{}')) c2 where c2 is null or c2 !~ '^[a-z][a-z0-9_]{0,62}$')
     or cardinality(coalesce(p_cle, '{}')) <> (select count(distinct c3) from unnest(coalesce(p_cle, '{}')) c3) then
    return false;
  end if;
  if p_colonnes is null or p_colonnes = '{}'::jsonb then
    return true;
  end if;
  foreach c in array coalesce(p_cle, '{}') loop
    if not (p_colonnes ? c)
       or p_colonnes -> c -> 'facultative' = 'true'::jsonb
       or p_colonnes -> c -> 'sensible' = 'true'::jsonb then
      return false;
    end if;
  end loop;
  if v_col is not null and (not (p_colonnes ? v_col)
                            or coalesce(p_colonnes -> v_col ->> 'type', '') not in ('date', 'dateheure')
                            or p_colonnes -> v_col -> 'sensible' = 'true'::jsonb) then
    return false;
  end if;
  return true;
end $_$;


--
-- Name: declarer_jeu(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.declarer_jeu(p_branchement uuid, p_code text, p_declaration jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b public.branchements;
  j public.branchements_jeux;
  m public.modeles_jeux;
  p jsonb := coalesce(p_declaration, '{}'::jsonb);
  d jsonb;
  v_id uuid;
  v_inconnus text;
begin
  select * into b from public.branchements where id = p_branchement;
  if not found then
    raise exception 'Branchement introuvable.' using errcode = 'P0002';
  end if;
  perform private.exiger_gestion_releve(b.client_id, b.entite_id);
  if jsonb_typeof(p) <> 'object' then
    raise exception 'Un jeu se déclare en objet.' using errcode = '22023';
  end if;
  select string_agg(k, ', ') into v_inconnus from jsonb_object_keys(p) k where k not in (
    'libelle', 'motif_fichier', 'entetes', 'colonnes', 'cle', 'complet', 'fenetre', 'confirmer_disparition',
    'seuil_perte', 'perte_min', 'seuil_anomalies', 'options', 'accuse', 'rythme', 'plages', 'attendu', 'actif');
  if v_inconnus is not null then
    raise exception 'Réglage de jeu inconnu : %.', v_inconnus using errcode = '22023';
  end if;

  select * into j from public.branchements_jeux where branchement_id = b.id and code = p_code for update;
  if found then
    update public.branchements_jeux set
      libelle = case when p ? 'libelle' then p ->> 'libelle' else libelle end,
      motif_fichier = case when p ? 'motif_fichier' then p ->> 'motif_fichier' else motif_fichier end,
      entetes = case when p ? 'entetes' then coalesce(private.tableau_texte(p -> 'entetes'), '{}') else entetes end,
      colonnes = case when p ? 'colonnes' then coalesce(nullif(p -> 'colonnes', 'null'::jsonb), '{}'::jsonb) else colonnes end,
      cle = case when p ? 'cle' then coalesce(private.tableau_texte(p -> 'cle'), '{}') else cle end,
      complet = case when p ? 'complet' then coalesce((p ->> 'complet')::boolean, true) else complet end,
      fenetre = case when p ? 'fenetre' then nullif(p -> 'fenetre', 'null'::jsonb) else fenetre end,
      confirmer_disparition = case when p ? 'confirmer_disparition' then (p ->> 'confirmer_disparition')::smallint else confirmer_disparition end,
      seuil_perte = case when p ? 'seuil_perte' then (p ->> 'seuil_perte')::numeric else seuil_perte end,
      perte_min = case when p ? 'perte_min' then (p ->> 'perte_min')::integer else perte_min end,
      seuil_anomalies = case when p ? 'seuil_anomalies' then (p ->> 'seuil_anomalies')::numeric else seuil_anomalies end,
      options = case when p ? 'options' then coalesce(nullif(p -> 'options', 'null'::jsonb), '{}'::jsonb) else options end,
      accuse = case when p ? 'accuse' then (p ->> 'accuse')::boolean else accuse end,
      rythme = case when p ? 'rythme' then (p ->> 'rythme')::interval else rythme end,
      plages = case when p ? 'plages' then nullif(p -> 'plages', 'null'::jsonb) else plages end,
      attendu = case when p ? 'attendu' then nullif(p -> 'attendu', 'null'::jsonb) else attendu end,
      actif = case when p ? 'actif' then (p ->> 'actif')::boolean else actif end,
      maj_le = now()
    where id = j.id;
    -- Une clé qui change rend l'état incomparable : le prochain export repart de zéro.
    if (select x.cle from public.branchements_jeux x where x.id = j.id) is distinct from j.cle then
      if exists (select 1 from public.instantanes i where i.jeu_id = j.id and i.statut in ('lu', 'a_appliquer')) then
        raise exception 'Un export de ce jeu est en cours d''application : changez la clé après lui.' using errcode = '55000';
      end if;
      delete from public.jeux_lignes where jeu_id = j.id;
      update public.branchements_jeux set courant_id = null, lignes = 0, etat_le = null where id = j.id;
    end if;
    return j.id;
  end if;

  m := private.modele_pour(b.module, b.logiciel, p_code);
  d := coalesce(to_jsonb(m) - array['id', 'module', 'logiciel', 'code', 'version', 'source', 'cree_le'], '{}'::jsonb)
       || p;
  insert into public.branchements_jeux (client_id, branchement_id, code, modele_id, libelle, motif_fichier, entetes, colonnes,
    cle, complet, fenetre, confirmer_disparition, seuil_perte, perte_min, seuil_anomalies, options, accuse, rythme, plages,
    attendu, actif)
  values (b.client_id, b.id, p_code, m.id, coalesce(d ->> 'libelle', p_code), d ->> 'motif_fichier',
    coalesce(private.tableau_texte(d -> 'entetes'), '{}'), coalesce(nullif(d -> 'colonnes', 'null'::jsonb), '{}'::jsonb),
    coalesce(private.tableau_texte(d -> 'cle'), '{}'), coalesce((d ->> 'complet')::boolean, true),
    nullif(d -> 'fenetre', 'null'::jsonb), coalesce((d ->> 'confirmer_disparition')::smallint, 1),
    coalesce((d ->> 'seuil_perte')::numeric, 0.2), coalesce((d ->> 'perte_min')::integer, 1),
    coalesce((d ->> 'seuil_anomalies')::numeric, 0.05), coalesce(nullif(d -> 'options', 'null'::jsonb), '{}'::jsonb),
    coalesce((d ->> 'accuse')::boolean, true), (d ->> 'rythme')::interval, nullif(d -> 'plages', 'null'::jsonb),
    nullif(d -> 'attendu', 'null'::jsonb), coalesce((d ->> 'actif')::boolean, true))
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: declarer_modele(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.declarer_modele(p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'Un modèle se déclare en objet.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_object_keys(p) k where k not in (
       'module', 'logiciel', 'code', 'version', 'libelle', 'motif_fichier', 'entetes', 'colonnes', 'cle', 'complet',
       'fenetre', 'confirmer_disparition', 'seuil_perte', 'perte_min', 'seuil_anomalies', 'options', 'accuse',
       'rythme', 'plages', 'attendu', 'source')) then
    raise exception 'Réglage de modèle inconnu : %.', (select string_agg(k, ', ') from jsonb_object_keys(p) k where k not in (
       'module', 'logiciel', 'code', 'version', 'libelle', 'motif_fichier', 'entetes', 'colonnes', 'cle', 'complet',
       'fenetre', 'confirmer_disparition', 'seuil_perte', 'perte_min', 'seuil_anomalies', 'options', 'accuse',
       'rythme', 'plages', 'attendu', 'source')) using errcode = '22023';
  end if;
  insert into public.modeles_jeux (module, logiciel, code, version, libelle, motif_fichier, entetes, colonnes, cle, complet,
    fenetre, confirmer_disparition, seuil_perte, perte_min, seuil_anomalies, options, accuse, rythme, plages, attendu, source)
  values (p ->> 'module', p ->> 'logiciel', p ->> 'code', coalesce((p ->> 'version')::smallint, 1),
    coalesce(p ->> 'libelle', p ->> 'code'), p ->> 'motif_fichier',
    coalesce(private.tableau_texte(p -> 'entetes'), '{}'), coalesce(nullif(p -> 'colonnes', 'null'::jsonb), '{}'::jsonb),
    coalesce(private.tableau_texte(p -> 'cle'), '{}'), coalesce((p ->> 'complet')::boolean, true),
    nullif(p -> 'fenetre', 'null'::jsonb), coalesce((p ->> 'confirmer_disparition')::smallint, 1),
    coalesce((p ->> 'seuil_perte')::numeric, 0.2), coalesce((p ->> 'perte_min')::integer, 1),
    coalesce((p ->> 'seuil_anomalies')::numeric, 0.05), coalesce(nullif(p -> 'options', 'null'::jsonb), '{}'::jsonb),
    coalesce((p ->> 'accuse')::boolean, true), (p ->> 'rythme')::interval, nullif(p -> 'plages', 'null'::jsonb),
    nullif(p -> 'attendu', 'null'::jsonb), p ->> 'source')
  on conflict (module, logiciel, code, version) do update
    set libelle = excluded.libelle, motif_fichier = excluded.motif_fichier, entetes = excluded.entetes,
        colonnes = excluded.colonnes, cle = excluded.cle, complet = excluded.complet, fenetre = excluded.fenetre,
        confirmer_disparition = excluded.confirmer_disparition, seuil_perte = excluded.seuil_perte,
        perte_min = excluded.perte_min, seuil_anomalies = excluded.seuil_anomalies, options = excluded.options,
        accuse = excluded.accuse, rythme = excluded.rythme, plages = excluded.plages, attendu = excluded.attendu,
        source = excluded.source
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: demander_lecture(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.demander_lecture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.objet_id is not null and new.statut = 'recue' and new.source <> 'export'
     and (tg_op = 'INSERT' or old.objet_id is null or old.statut is distinct from new.statut) then
    perform private.deposer_travail(new.client_id, new.module, 'lecteur.lire',
      jsonb_build_object('piece', new.id), 'piece:' || new.id::text, 0::smallint);
  end if;
  return null;
end $$;


--
-- Name: deposer_activation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.deposer_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.demandes_validation (
    id, client_id, entite_id, module, type_action, objet_type, objet_id, resume, montant, payload, cle_idempotence)
  values (
    new.demande_id, new.client_id, new.entite_id, new.module, 'politique.activer', 'politique', new.id::text,
    left('Accord permanent : ' || new.libelle, 500),
    coalesce(new.plafond_mensuel, new.plafond_operation),
    jsonb_build_object('type_action', new.type_action, 'plafond_operation', new.plafond_operation,
                       'plafond_mensuel', new.plafond_mensuel, 'nombre_mensuel', new.nombre_mensuel,
                       'debut', new.debut, 'fin', new.fin),
    'politique:' || new.id::text);
  return null;
end $$;


--
-- Name: deposer_lignes(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.deposer_lignes(p_instantane uuid, p_lignes jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  n integer;
begin
  select * into i from public.instantanes where id = p_instantane for share;
  if not found then
    raise exception 'Instantané introuvable.' using errcode = 'P0002';
  end if;
  if i.statut <> 'en_lecture' then
    raise exception 'L''instantané n''est pas en lecture (statut %).', i.statut using errcode = '55000';
  end if;
  if p_lignes is null or jsonb_typeof(p_lignes) <> 'array' then
    raise exception 'Les lignes se déposent en tableau.' using errcode = '22023';
  end if;
  insert into public.instantanes_lignes (client_id, instantane_id, n, ligne, cle, valeurs, anomalies, empreinte)
  select i.client_id, i.id, (e ->> 'n')::integer, (e ->> 'ligne')::integer, e ->> 'cle', e -> 'valeurs', x.anomalies,
         private.empreinte_ligne(e -> 'valeurs', x.anomalies)
  from jsonb_array_elements(p_lignes) e
  cross join lateral (
    select case when jsonb_typeof(e -> 'anomalies') = 'object' and e -> 'anomalies' <> '{}'::jsonb
                then e -> 'anomalies' end as anomalies) x;
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: deposer_section(uuid, text, date, uuid, text, text, jsonb, uuid, uuid, boolean, timestamp with time zone, boolean, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.deposer_section(p_client uuid, p_module text, p_jour date, p_destinataire uuid, p_role text, p_titre text, p_items jsonb, p_entite uuid DEFAULT NULL::uuid, p_equipe uuid DEFAULT NULL::uuid, p_sante boolean DEFAULT false, p_donnees_du timestamp with time zone DEFAULT NULL::timestamp with time zone, p_incomplete boolean DEFAULT false, p_ordre integer DEFAULT 100) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_titre text := btrim(p_titre);
  v_items jsonb := '[]'::jsonb;
  v_existants jsonb;
  e jsonb;
  v_rang integer := 0;
  v_inconnus text;
  v_texte text;
  v_code text;
  v_version integer;
  v_id uuid;
  v_sante boolean;
begin
  if p_module is null or p_module !~ '^[a-z][a-z_]{1,29}$' then
    raise exception 'Module inconnu : %.', coalesce(p_module, 'vide') using errcode = '22023';
  end if;
  if not exists (select 1 from public.clients c where c.id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  if p_jour is null then
    raise exception 'Une section vaut pour un jour.' using errcode = '22023';
  end if;
  if num_nonnulls(p_destinataire, p_role, p_equipe) <> 1 then
    raise exception 'Une section s''adresse à un membre, à un rôle ou à une équipe : un seul des trois.' using errcode = '22023';
  end if;
  if p_destinataire is not null
     and not exists (select 1 from public.comptes c where c.client_id = p_client and c.user_id = p_destinataire) then
    raise exception 'Ce destinataire n''est pas membre de l''organisation.' using errcode = '22023';
  end if;
  if p_role is not null and p_role not in ('gerant', 'admin', 'valideur', 'collaborateur', 'lecteur') then
    raise exception 'Rôle inconnu : %.', p_role using errcode = '22023';
  end if;
  if p_equipe is not null and not exists (select 1 from public.equipes q where q.client_id = p_client and q.id = p_equipe) then
    raise exception 'Équipe inconnue dans cette organisation.' using errcode = '22023';
  end if;
  if p_entite is not null and not exists (select 1 from public.entites en where en.client_id = p_client and en.id = p_entite) then
    raise exception 'Entité inconnue dans cette organisation.' using errcode = '22023';
  end if;
  if v_titre is null or char_length(v_titre) not between 1 and 120 or v_titre ~ '[[:cntrl:]]' then
    raise exception 'Le titre tient en une ligne de 120 caractères au plus.' using errcode = '22023';
  end if;
  if p_ordre is null or p_ordre not between 0 and 999 then
    raise exception 'L''ordre d''une section va de 0 à 999.' using errcode = '22023';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 50 then
    raise exception 'Les lignes forment un tableau de 50 au plus ; vide, la section dit « rien à signaler ».' using errcode = '22023';
  end if;

  for e in select x.value from jsonb_array_elements(p_items) x loop
    v_rang := v_rang + 1;
    v_code := null;
    v_version := null;
    if jsonb_typeof(e) <> 'object' then
      raise exception 'La ligne % n''est pas un objet.', v_rang using errcode = '22023';
    end if;
    select string_agg(k, ', ' order by k) into v_inconnus
    from jsonb_object_keys(e) k
    where k not in ('texte', 'lien', 'gravite', 'objet_type', 'objet_id', 'gabarit', 'version', 'valeurs');
    if v_inconnus is not null then
      raise exception 'La ligne % porte des champs inconnus : %.', v_rang, v_inconnus using errcode = '22023';
    end if;
    if coalesce(e ->> 'gravite', '') not in ('info', 'attention', 'critique') then
      raise exception 'La ligne % : la gravité vaut info, attention ou critique.', v_rang using errcode = '22023';
    end if;
    if jsonb_typeof(e -> 'lien') is distinct from 'string' or not private.point_lien_valide(e ->> 'lien') then
      raise exception 'La ligne % : le lien est un chemin de l''espace, qui commence par « / ».', v_rang using errcode = '22023';
    end if;
    if (e ? 'objet_type') <> (e ? 'objet_id')
       or (e ? 'objet_type' and (jsonb_typeof(e -> 'objet_type') <> 'string'
                                 or (e ->> 'objet_type') !~ '^[a-z][a-z0-9_]{1,39}$'
                                 or jsonb_typeof(e -> 'objet_id') <> 'string'
                                 or char_length(e ->> 'objet_id') not between 1 and 120)) then
      raise exception 'La ligne % : un objet se désigne par son type et son identifiant.', v_rang using errcode = '22023';
    end if;
    if e ? 'texte' and jsonb_typeof(e -> 'texte') <> 'string' then
      raise exception 'La ligne % : le texte est une chaîne.', v_rang using errcode = '22023';
    end if;
    v_texte := nullif(btrim(e ->> 'texte'), '');
    if e ? 'gabarit' then
      if jsonb_typeof(e -> 'gabarit') <> 'string' or (e ? 'version' and jsonb_typeof(e -> 'version') <> 'number') then
        raise exception 'La ligne % : un gabarit se nomme par son code ; sa version est un nombre.', v_rang using errcode = '22023';
      end if;
      v_code := e ->> 'gabarit';
      v_version := coalesce((e ->> 'version')::integer,
                            (select max(g.version) from public.points_gabarits g where g.code = v_code and g.en_service));
      if not exists (select 1 from public.points_gabarits g where g.code = v_code and g.version = v_version and g.en_service) then
        raise exception 'La ligne % : gabarit inconnu ou retiré du service (%).', v_rang, v_code using errcode = '22023';
      end if;
      if split_part(v_code, '.', 1) <> p_module then
        raise exception 'La ligne % : un module n''emploie que ses propres gabarits.', v_rang using errcode = '22023';
      end if;
      -- Les valeurs sont vérifiées, même quand un texte les accompagne.
      v_texte := coalesce(v_texte, private.point_rendre_gabarit(v_code, v_version, e -> 'valeurs'));
      perform private.point_rendre_gabarit(v_code, v_version, e -> 'valeurs');
    elsif e ? 'version' or e ? 'valeurs' then
      raise exception 'La ligne % : version et valeurs accompagnent un gabarit.', v_rang using errcode = '22023';
    end if;
    -- Un objet chiffré (lot 14b) ne laisse rien de lui en clair : un gabarit, jamais de texte libre.
    if e ? 'objet_type' and exists (select 1 from private.objets_chiffres oc where oc.objet_type = e ->> 'objet_type')
       and (v_code is null or nullif(btrim(e ->> 'texte'), '') is not null) then
      raise exception 'La ligne % porte sur un objet chiffré (%) : un gabarit seulement, jamais de texte libre.',
        v_rang, e ->> 'objet_type' using errcode = '22023';
    end if;
    if v_texte is null or char_length(v_texte) > 300 or v_texte ~ '[[:cntrl:]]' then
      raise exception 'La ligne % : un texte d''une ligne, de 300 caractères au plus.', v_rang using errcode = '22023';
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'rang', v_rang, 'texte', v_texte, 'lien', e ->> 'lien', 'gravite', e ->> 'gravite',
      'objet_type', e ->> 'objet_type', 'objet_id', e ->> 'objet_id',
      'gabarit', v_code, 'gabarit_version', v_version,
      'valeurs', case when v_code is null then null else e -> 'valeurs' end));
  end loop;

  v_sante := coalesce(p_sante, false) or private.point_module_sante(p_module);
  perform pg_advisory_xact_lock(hashtextextended(concat_ws('|', 'section', p_client, p_module, p_jour, p_destinataire,
                                                           p_role, p_equipe, p_entite, v_titre), 0));
  select s.id into v_id
  from public.points_sections s
  where s.client_id = p_client and s.module = p_module and s.jour = p_jour
    and s.destinataire is not distinct from p_destinataire and s.role is not distinct from p_role
    and s.equipe_id is not distinct from p_equipe and s.entite_id is not distinct from p_entite and s.titre = v_titre;

  if v_id is null then
    insert into public.points_sections (client_id, module, jour, destinataire, role, equipe_id, entite_id, titre, ordre,
                                        sante, incomplete, donnees_du, nb_items)
    values (p_client, p_module, p_jour, p_destinataire, p_role, p_equipe, p_entite, v_titre, p_ordre,
            v_sante, coalesce(p_incomplete, false), p_donnees_du, v_rang)
    returning id into v_id;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
             'rang', i.rang, 'texte', i.texte, 'lien', i.lien, 'gravite', i.gravite, 'objet_type', i.objet_type,
             'objet_id', i.objet_id, 'gabarit', i.gabarit, 'gabarit_version', i.gabarit_version, 'valeurs', i.valeurs)
             order by i.rang), '[]'::jsonb)
      into v_existants
    from public.points_items i where i.section_id = v_id;
    if v_existants = v_items and exists (
        select 1 from public.points_sections s
        where s.id = v_id and s.ordre = p_ordre and s.sante = v_sante and s.incomplete = coalesce(p_incomplete, false)
          and s.donnees_du is not distinct from p_donnees_du) then
      return v_id;   -- rien n'a changé : ni écriture, ni journal
    end if;
    update public.points_sections
       set ordre = p_ordre, sante = v_sante, incomplete = coalesce(p_incomplete, false), donnees_du = p_donnees_du,
           nb_items = v_rang, maj_le = now()
     where id = v_id;
    delete from public.points_items where section_id = v_id;
  end if;

  insert into public.points_items (client_id, section_id, rang, texte, lien, gravite, objet_type, objet_id,
                                   gabarit, gabarit_version, valeurs)
  select p_client, v_id, (x ->> 'rang')::smallint, x ->> 'texte', x ->> 'lien', x ->> 'gravite', x ->> 'objet_type',
         x ->> 'objet_id', x ->> 'gabarit', (x ->> 'gabarit_version')::smallint, nullif(x -> 'valeurs', 'null'::jsonb)
  from jsonb_array_elements(v_items) x;
  return v_id;
end $_$;


--
-- Name: deposer_travail(uuid, text, text, jsonb, text, smallint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.deposer_travail(p_client uuid, p_module text, p_genre text, p_charge jsonb DEFAULT '{}'::jsonb, p_cle text DEFAULT NULL::text, p_priorite smallint DEFAULT 0) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id bigint;
begin
  insert into public.travaux (client_id, module, genre, charge, cle, priorite)
  values (p_client, p_module, p_genre, coalesce(p_charge, '{}'::jsonb), p_cle, coalesce(p_priorite, 0))
  on conflict (genre, cle) where cle is not null and etat in ('a_faire', 'en_cours') do nothing
  returning id into v_id;
  if v_id is null then
    select t.id into v_id from public.travaux t
    where t.genre = p_genre and t.cle = p_cle and t.etat in ('a_faire', 'en_cours') limit 1;
  end if;
  return v_id;
end $$;


--
-- Name: echouer_envoi(uuid, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.echouer_envoi(p_envoi uuid, p_erreur text, p_definitif boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
begin
  perform private.exiger_ouvrier();
  if coalesce(p_definitif, false) then
    update public.envois
       set statut = 'echec', erreur = left(p_erreur, 2000), bail_jusqu_au = null, clos_le = now(),
           motif = 'L''envoi a échoué chez le fournisseur ; l''équipe Omega est prévenue.'
     where id = p_envoi and statut = 'en_cours'
    returning * into e;
    if e.id is not null then
      perform private.clore_demande_envoi(e, false, e.motif);
      perform private.publier_envoi(e, 'echec');
      return 'echec';
    end if;
  else
    update public.envois set statut = 'pret', erreur = left(p_erreur, 2000), bail_jusqu_au = null
     where id = p_envoi and statut = 'en_cours'
    returning * into e;
    if e.id is not null then
      return 'pret';
    end if;
  end if;
  return coalesce((select x.statut from public.envois x where x.id = p_envoi), 'introuvable');
end $$;


--
-- Name: echouer_travail(bigint, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.echouer_travail(p_id bigint, p_erreur text, p_reprendre boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_t public.travaux;
begin
  select * into v_t from public.travaux where id = p_id and etat = 'en_cours' for update;
  if not found then
    raise exception 'Travail introuvable ou pas en cours : %.', p_id using errcode = 'P0002';
  end if;
  if coalesce(p_reprendre, true) and v_t.essais < v_t.essais_max then
    update public.travaux
       set etat = 'a_faire', erreur = left(p_erreur, 2000), verrou_jusqu_au = null,
           prochain_le = now() + least(interval '6 hours', interval '1 minute' * power(2, v_t.essais - 1))
     where id = p_id;
    return 'repris';
  end if;
  update public.travaux
     set etat = 'echec', erreur = left(p_erreur, 2000), verrou_jusqu_au = null, fini_le = now()
   where id = p_id;
  perform private.lever_alerte(v_t.client_id, true, 'critique', v_t.module,
    format('Travail en échec : %s', v_t.genre),
    jsonb_build_object('travail', v_t.id, 'genre', v_t.genre, 'essais', v_t.essais, 'erreur', left(p_erreur, 300)),
    'travail:' || v_t.genre || ':' || coalesce(v_t.cle, v_t.id::text));
  return 'echec';
end $$;


--
-- Name: ecrit_objet(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ecrit_objet(p_client uuid, p_type text, p_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.ecrit_objet_pour((select auth.uid()), p_client, p_type, p_id)
$$;


--
-- Name: ecrit_objet_pour(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ecrit_objet_pour(p_user uuid, p_client uuid, p_type text, p_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gardien regprocedure;
begin
  if p_type is not null and p_id is not null then
    select g.ecrit into v_gardien from private.gardiens_objets g where g.objet_type = p_type;
    if found then
      if not exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client) then
        return false;
      end if;
      return private.appeler_gardien(v_gardien, p_user, p_client, p_id);
    end if;
  end if;
  return exists (
      select 1 from public.comptes c
      where c.user_id = p_user and c.client_id = p_client and c.role = 'gerant')
    or (exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client)
        and (not exists (select 1 from public.objets_restreints r
                         where r.client_id = p_client and r.objet_type = p_type)
             or exists (select 1 from public.acces_objets a
                        where a.client_id = p_client and a.objet_type = p_type and a.objet_id = p_id
                          and a.niveau = 'ecriture'
                          and (a.user_id = p_user
                               or a.equipe_id in (select m.equipe_id from public.equipes_membres m
                                                  where m.user_id = p_user and m.client_id = p_client)))));
end $$;


--
-- Name: ecrit_par_la_brique(oid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ecrit_par_la_brique(p_table oid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select current_user = (select r.rolname from pg_catalog.pg_class c
                         join pg_catalog.pg_roles r on r.oid = c.relowner where c.oid = p_table)
$$;


--
-- Name: effacement_en_cours(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effacement_en_cours(p_client uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select p_client::text = coalesce(current_setting('omega.effacement_client', true), '')
      or coalesce(current_setting('omega.effacement_objet', true), '') = 'oui'
$$;


--
-- Name: effacements_immuables(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effacements_immuables() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'La preuve d''un effacement ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: effacements_objets_immuables(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effacements_objets_immuables() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return old;
  end if;
  raise exception 'La preuve d''un effacement ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: effacer_client(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effacer_client(p_client uuid, p_confirmation text, p_par text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_nom text;
  v_export jsonb;
  v_lignes jsonb := '{}'::jsonb;
  v_restantes text[];
  v_orphelins uuid[];
  v_nom_table text;
  v_n bigint;
  v_passe int := 0;
  v_progres boolean;
  v_fichiers jsonb;
begin
  select c.nom into v_nom from public.clients c where c.id = p_client for update;
  if not found then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  if p_confirmation is distinct from v_nom then
    raise exception 'Confirmation refusée : saisir exactement le nom de l''organisation.' using errcode = '22023';
  end if;
  if coalesce(btrim(p_par), '') = '' then
    raise exception 'Un effacement est toujours signé : qui efface ?' using errcode = '22023';
  end if;
  if exists (select 1 from private.fichiers_de(p_client)) then
    raise exception 'Des fichiers de l''organisation restent dans le stockage : le serveur les efface d''abord (preparer_effacement, puis l''API du stockage).'
      using errcode = '55000';
  end if;
  select m.manifeste into v_fichiers from private.manifestes_effacement m where m.cle = p_client::text;

  -- L'export est tiré avant tout : son empreinte signe la preuve.
  v_export := private.exporter_client(p_client, null);

  -- Les comptes qui n'appartiennent qu'à cette organisation : au serveur de les fermer.
  select coalesce(array_agg(c.user_id), '{}') into v_orphelins
  from public.comptes c
  where c.client_id = p_client
    and not exists (select 1 from public.comptes o where o.user_id = c.user_id and o.client_id <> p_client);

  perform set_config('omega.effacement_client', p_client::text, true);

  select array_agg(t.nom order by t.ordre_effacement, t.nom) into v_restantes from private.tables_locataires t;
  loop
    v_passe := v_passe + 1;
    v_progres := false;
    foreach v_nom_table in array v_restantes loop
      begin
        execute format('delete from public.%I where client_id = $1', v_nom_table) using p_client;
        get diagnostics v_n = row_count;
        v_lignes := v_lignes || jsonb_build_object(v_nom_table, v_n);
        v_restantes := array_remove(v_restantes, v_nom_table);
        v_progres := true;
      exception when foreign_key_violation then
        null; -- une autre table la retient encore : passe suivante
      end;
    end loop;
    exit when cardinality(v_restantes) = 0;
    if not v_progres or v_passe >= 10 then
      raise exception 'Effacement bloqué par des références croisées : %.', v_restantes using errcode = '23503';
    end if;
  end loop;

  delete from public.clients where id = p_client;
  v_lignes := v_lignes || jsonb_build_object('clients', 1);

  -- Le journal technique ancien garde des copies de lignes : on les retire aussi.
  delete from public.audit_journal a
  where a.cle_ligne = p_client::text
     or a.cle_ligne like p_client::text || '/%'
     or a.avant ->> 'client_id' = p_client::text
     or a.apres ->> 'client_id' = p_client::text
     or (a.table_cible = 'clients' and (a.avant ->> 'id' = p_client::text or a.apres ->> 'id' = p_client::text));
  get diagnostics v_n = row_count;
  v_lignes := v_lignes || jsonb_build_object('audit_journal', v_n);

  delete from private.manifestes_effacement m
  where m.cle = p_client::text or starts_with(m.cle, p_client::text || '/');

  insert into public.effacements (client_efface, nom_client, par, empreinte_export, lignes, comptes_orphelins, fichiers)
  values (p_client, v_nom, p_par, v_export ->> 'empreinte_sha256', v_lignes, v_orphelins,
          coalesce(v_fichiers, '{"nombre": 0}'::jsonb));

  perform set_config('omega.effacement_client', '', true);

  return jsonb_build_object(
    'organisation', p_client,
    'lignes', v_lignes,
    'fichiers', coalesce(v_fichiers, '{"nombre": 0}'::jsonb),
    'empreinte_export', v_export ->> 'empreinte_sha256',
    'comptes_orphelins', to_jsonb(v_orphelins));
end $_$;


--
-- Name: effacer_objet(uuid, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effacer_objet(p_client uuid, p_objet_type text, p_objet_id text, p_confirmation text, p_par text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  v_entetes jsonb;
  v_par text;
  v_cle text := p_client::text || '/' || p_objet_type || '/' || p_objet_id;
  v_manifeste jsonb;
  v_lignes jsonb := '{}'::jsonb;
  v_n bigint;
  r record;
begin
  if p_objet_type is null or p_objet_id is null or not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Objet introuvable.' using errcode = 'P0002';
  end if;
  if p_confirmation is distinct from p_objet_id then
    raise exception 'Confirmation refusée : saisir exactement l''identifiant de l''objet.' using errcode = '22023';
  end if;

  if v_uid is not null then
    if not ((private.a_un_role(p_client, array['gerant'])
             and (not exists (select 1 from private.gardiens_objets g where g.objet_type = p_objet_type)
                  or private.ecrit_objet(p_client, p_objet_type, p_objet_id)))
            or (private.a_le_droit(p_client, 'effacer.' || p_objet_type)
                and private.ecrit_objet(p_client, p_objet_type, p_objet_id))) then
      raise exception 'Seul le gérant, ou qui en a reçu le droit, efface un objet.' using errcode = '42501';
    end if;
    select coalesce(u.email, v_uid::text) into v_par from auth.users u where u.id = v_uid;
  elsif v_role = 'service_role' then
    begin
      v_entetes := nullif(current_setting('request.headers', true), '')::jsonb;
    exception when others then
      v_entetes := null;
    end;
    v_par := coalesce(nullif(btrim(p_par), ''), nullif(v_entetes ->> 'x-omega-operateur', ''));
    if v_par is null then
      raise exception 'Un effacement est toujours signé : qui efface ?' using errcode = '22023';
    end if;
  else
    raise exception 'Seul le gérant, ou qui en a reçu le droit, efface un objet.' using errcode = '42501';
  end if;

  if exists (select 1 from private.fichiers_de(p_client, p_objet_type, p_objet_id)) then
    raise exception 'Des fichiers de cet objet restent dans le stockage : le serveur les efface d''abord.'
      using errcode = '55000';
  end if;
  select m.manifeste into v_manifeste from private.manifestes_effacement m where m.cle = v_cle;

  perform set_config('omega.effacement_objet', 'oui', true);
  for r in
    select t.nom, t.colonne from private.tables_objets t
    where t.objet_type = p_objet_type
    order by t.ordre_effacement, t.nom
  loop
    execute format('delete from public.%I where client_id = $1 and %I::text = $2', r.nom, r.colonne)
      using p_client, p_objet_id;
    get diagnostics v_n = row_count;
    v_lignes := v_lignes || jsonb_build_object(r.nom, v_n);
  end loop;

  -- Les tables génériques : délais, envois, suivis… de cet objet, quel que soit son type.
  for r in select g.nom from private.tables_objets_generiques g order by g.ordre_effacement, g.nom loop
    execute format('delete from public.%I where client_id = $1 and objet_type = $2 and objet_id = $3', r.nom)
      using p_client, p_objet_type, p_objet_id;
    get diagnostics v_n = row_count;
    v_lignes := v_lignes || jsonb_build_object(r.nom, v_n);
  end loop;

  -- Du socle : les pièces de l'objet (leurs pages et valeurs suivent), ses
  -- demandes de validation (et leurs décisions), ses accès.
  delete from public.pieces p
  where p.client_id = p_client and p.objet_type = p_objet_type and p.objet_id = p_objet_id;
  get diagnostics v_n = row_count;
  v_lignes := v_lignes || jsonb_build_object('pieces', v_n);
  delete from public.demandes_validation d
  where d.client_id = p_client and d.objet_type = p_objet_type and d.objet_id = p_objet_id;
  get diagnostics v_n = row_count;
  v_lignes := v_lignes || jsonb_build_object('demandes_validation', v_n);
  delete from public.acces_objets a
  where a.client_id = p_client and a.objet_type = p_objet_type and a.objet_id = p_objet_id;
  get diagnostics v_n = row_count;
  v_lignes := v_lignes || jsonb_build_object('acces_objets', v_n);
  perform set_config('omega.effacement_objet', '', true);

  insert into public.effacements_objets (client_id, objet_type, objet_id, par, acteur_id, lignes, fichiers)
  values (p_client, p_objet_type, p_objet_id, v_par, v_uid, v_lignes, coalesce(v_manifeste, '{"nombre": 0}'::jsonb));
  delete from private.manifestes_effacement m where m.cle = v_cle;

  perform private.journaliser(p_client, 'objet.effacement', p_objet_type, p_objet_id,
    jsonb_build_object('lignes', v_lignes, 'fichiers', coalesce(v_manifeste -> 'nombre', '0'::jsonb)));

  return jsonb_build_object('objet_type', p_objet_type, 'objet_id', p_objet_id, 'lignes', v_lignes,
                            'fichiers', coalesce(v_manifeste, '{"nombre": 0}'::jsonb));
end $_$;


--
-- Name: empreinte_adresse(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.empreinte_adresse(p_client uuid, p_adresse text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_client is null or p_adresse is null then null
              else encode(sha256(convert_to(p_client::text || ':' || p_adresse, 'UTF8')), 'hex') end
$$;


--
-- Name: empreinte_contenu(text, text, text, text, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.empreinte_contenu(p_canal text, p_adresse text, p_sujet text, p_corps text, p_pieces uuid[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select encode(sha256(convert_to(
    p_canal || chr(31) || coalesce(p_adresse, '') || chr(31) || coalesce(p_sujet, '') || chr(31) || p_corps || chr(31)
    || coalesce(array_to_string(array(select x::text from unnest(p_pieces) x order by x), ','), ''), 'UTF8')), 'hex')
$$;


--
-- Name: empreinte_journal(bytea, bigint, uuid, uuid, timestamp with time zone, text, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.empreinte_journal(p_precedent bytea, p_id bigint, p_client uuid, p_entite uuid, p_quand timestamp with time zone, p_acteur_type text, p_acteur_id uuid, p_acteur_libelle text, p_action text, p_objet_type text, p_objet_id text, p_donnees jsonb) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select sha256(coalesce(p_precedent, '\x'::bytea) || convert_to(jsonb_build_object(
    'id', p_id, 'client', p_client, 'entite', p_entite,
    'quand', to_char(p_quand at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'acteur_type', p_acteur_type, 'acteur_id', p_acteur_id, 'acteur_libelle', p_acteur_libelle,
    'action', p_action, 'objet_type', p_objet_type, 'objet_id', p_objet_id,
    'donnees', p_donnees)::text, 'UTF8'))
$$;


--
-- Name: empreinte_ligne(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.empreinte_ligne(p_valeurs jsonb, p_anomalies jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select encode(sha256(convert_to(
    case when p_anomalies is null then p_valeurs::text
         else jsonb_build_object('valeurs', p_valeurs, 'anomalies', p_anomalies)::text end, 'UTF8')), 'hex')
$$;


--
-- Name: empreintes_sensibles(uuid, jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.empreintes_sensibles(p_jeu uuid, p_valeurs jsonb, p_codes text[]) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when cardinality(p_codes) = 0 then null else (
    select jsonb_object_agg(c, case when p_valeurs -> c is null or p_valeurs -> c = 'null'::jsonb then null
                                    else encode(sha256(convert_to(p_jeu::text || ':' || c || ':' || (p_valeurs -> c)::text, 'UTF8')), 'hex') end)
    from unnest(p_codes) c) end
$$;


--
-- Name: enregistrer_lecture(uuid, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enregistrer_lecture(p_piece uuid, p_resultat jsonb, p_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p public.pieces;
  v_statut text := p_resultat ->> 'statut';
  v_pages integer;
  v_valeurs integer;
begin
  select * into v_p from public.pieces where id = p_piece for update;
  if not found then
    raise exception 'Pièce introuvable.' using errcode = 'P0002';
  end if;
  if v_p.statut <> 'en_lecture' then
    raise exception 'La pièce n''est pas en lecture (statut %).', v_p.statut using errcode = '55000';
  end if;
  if v_statut is null or v_statut not in ('lue', 'a_verifier', 'a_classer', 'rejetee', 'echec') then
    raise exception 'Statut de lecture inconnu : %.', coalesce(v_statut, 'vide') using errcode = '22023';
  end if;
  if v_p.chiffrement is not null then
    if exists (select 1 from jsonb_array_elements(coalesce(p_resultat -> 'pages', '[]'::jsonb)) e
               where coalesce(e ->> 'texte', '') <> '' or e ->> 'texte_chiffre' is null)
       or exists (select 1 from jsonb_array_elements(coalesce(p_resultat -> 'valeurs', '[]'::jsonb)) e
                  where e ->> 'source' is distinct from 'humain'
                    and (e ->> 'chiffre' is null or coalesce(e -> 'valeur', 'null'::jsonb) <> 'null'::jsonb
                         or e ->> 'texte' is not null or coalesce(e -> 'boite', 'null'::jsonb) <> 'null'::jsonb
                         or e ->> 'controle' is not null)) then
      raise exception 'Pièce chiffrée (%) : ni texte ni valeur en clair.', v_p.chiffrement using errcode = '22023';
    end if;
  elsif exists (select 1 from jsonb_array_elements(coalesce(p_resultat -> 'pages', '[]'::jsonb)) e where e ? 'texte_chiffre')
     or exists (select 1 from jsonb_array_elements(coalesce(p_resultat -> 'valeurs', '[]'::jsonb)) e where e ? 'chiffre') then
    raise exception 'Pièce en clair : rien ne s''y écrit chiffré.' using errcode = '22023';
  end if;

  delete from public.pieces_valeurs where piece_id = p_piece and source <> 'humain';
  delete from public.pieces_pages where piece_id = p_piece;

  insert into public.pieces_pages (client_id, piece_id, n, methode, texte, texte_chiffre, confiance, largeur, hauteur)
  select v_p.client_id, p_piece, (e ->> 'n')::integer, e ->> 'methode',
         case when v_p.chiffrement is null then coalesce(e ->> 'texte', '') else '' end,
         case when v_p.chiffrement is not null then decode(e ->> 'texte_chiffre', 'base64') end,
         (e ->> 'confiance')::numeric, (e ->> 'largeur')::numeric, (e ->> 'hauteur')::numeric
  from jsonb_array_elements(coalesce(p_resultat -> 'pages', '[]'::jsonb)) e;
  get diagnostics v_pages = row_count;

  insert into public.pieces_valeurs (client_id, piece_id, champ, valeur, texte, page, boite, source, confiance, verifiee,
                                     controle, chiffre)
  select v_p.client_id, p_piece, e ->> 'champ',
         case when v_p.chiffrement is null then coalesce(e -> 'valeur', 'null'::jsonb) else 'null'::jsonb end,
         case when v_p.chiffrement is null then left(e ->> 'texte', 2000) end,
         (e ->> 'page')::integer,
         case when v_p.chiffrement is null then nullif(e -> 'boite', 'null'::jsonb) end,
         e ->> 'source', (e ->> 'confiance')::numeric, coalesce((e ->> 'verifiee')::boolean, false),
         case when v_p.chiffrement is null then left(e ->> 'controle', 300) end,
         case when v_p.chiffrement is not null then decode(e ->> 'chiffre', 'base64') end
  from jsonb_array_elements(coalesce(p_resultat -> 'valeurs', '[]'::jsonb)) e
  where e ->> 'source' is distinct from 'humain';
  get diagnostics v_valeurs = row_count;

  update public.pieces
     set statut = v_statut,
         type_piece = nullif(p_resultat ->> 'type_piece', ''),
         confiance_type = (p_resultat ->> 'confiance_type')::numeric,
         nb_pages = coalesce((p_resultat ->> 'nb_pages')::integer, v_pages),
         methode = nullif(p_resultat ->> 'methode', ''),
         version_lecteur = left(p_version, 40),
         motif = left(p_resultat ->> 'motif', 500),
         lue_le = now()
   where id = p_piece;

  if v_statut in ('lue', 'a_verifier') then
    perform private.publier_evenement(v_p.client_id, 'piece_lue.' || v_p.module,
      jsonb_build_object('piece', p_piece, 'module', v_p.module, 'objet_type', v_p.objet_type,
                         'objet_id', v_p.objet_id, 'type_piece', nullif(p_resultat ->> 'type_piece', ''),
                         'statut', v_statut, 'chiffrement', v_p.chiffrement),
      p_piece::text || ':' || coalesce(p_version, ''));
  end if;
  return jsonb_build_object('pages', v_pages, 'valeurs', v_valeurs, 'statut', v_statut);
end $$;


--
-- Name: enregistrer_mesure(uuid, text, integer, text, date, numeric, numeric, text, numeric, uuid, text, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enregistrer_mesure(p_client uuid, p_indicateur text, p_version integer, p_periode_type text, p_periode_debut date, p_valeur numeric, p_base numeric, p_mode text, p_numerateur numeric DEFAULT NULL::numeric, p_entite uuid DEFAULT NULL::uuid, p_objet_type text DEFAULT NULL::text, p_objet_id text DEFAULT NULL::text, p_objet_libelle text DEFAULT NULL::text, p_periode_fin date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ind public.indicateurs;
  v_fin date;
  v_valeur numeric;
  v_num numeric;
  v_libelle text := nullif(btrim(p_objet_libelle), '');
  v_grain text;
  v_id uuid;
begin
  if not exists (select 1 from public.clients c where c.id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  select * into v_ind from public.indicateurs i where i.code = p_indicateur and i.version = p_version;
  if not found then
    raise exception 'Indicateur inconnu : % (version %).', coalesce(p_indicateur, 'vide'), coalesce(p_version::text, '?')
      using errcode = '22023', hint = 'Un indicateur s''inscrit par migration dans public.indicateurs.';
  end if;
  if not v_ind.en_service then
    raise exception 'La version % de % est retirée du service.', p_version, p_indicateur using errcode = '22023';
  end if;
  if p_mode is null or p_mode not in ('a_blanc', 'reel') then
    raise exception 'Le mode vaut a_blanc (la situation de départ) ou reel.' using errcode = '22023';
  end if;
  if p_periode_debut is null then
    raise exception 'Une mesure porte sur une période : son début est nécessaire.' using errcode = '22023';
  end if;
  if p_periode_debut > current_date + 1 then
    raise exception 'Une mesure ne porte pas sur l''avenir.' using errcode = '22023';
  end if;

  case p_periode_type
    when 'jour' then
      v_fin := p_periode_debut;
    when 'semaine' then
      if extract(isodow from p_periode_debut) <> 1 then
        raise exception 'Une semaine commence un lundi.' using errcode = '22023';
      end if;
      v_fin := p_periode_debut + 6;
    when 'mois' then
      if extract(day from p_periode_debut) <> 1 then
        raise exception 'Un mois commence le 1er.' using errcode = '22023';
      end if;
      v_fin := (p_periode_debut + interval '1 month')::date - 1;
    when 'libre' then
      if p_mode <> 'a_blanc' then
        raise exception 'Une période libre ne vaut que pour la mesure à blanc : le réel se mesure par jour, semaine ou mois.'
          using errcode = '22023';
      end if;
      if p_periode_fin is null or p_periode_fin < p_periode_debut or p_periode_fin - p_periode_debut > 366 then
        raise exception 'Une période libre a une fin (dernier jour compris), d''un an au plus.' using errcode = '22023';
      end if;
      v_fin := p_periode_fin;
    else
      raise exception 'Période inconnue : jour, semaine, mois ou libre.' using errcode = '22023';
  end case;
  if p_periode_type <> 'libre' and p_periode_fin is not null and p_periode_fin <> v_fin then
    raise exception 'La période % qui commence le % finit le %.', p_periode_type, p_periode_debut, v_fin using errcode = '22023';
  end if;
  if (p_objet_type is null) <> (p_objet_id is null) then
    raise exception 'Un objet se désigne par son type et son identifiant.' using errcode = '22023';
  end if;
  if v_libelle is not null and p_objet_id is null then
    raise exception 'Un libellé d''objet accompagne un objet.' using errcode = '22023';
  end if;
  if p_entite is not null and not exists (select 1 from public.entites e where e.client_id = p_client and e.id = p_entite) then
    raise exception 'Entité inconnue dans cette organisation.' using errcode = '22023';
  end if;

  if v_ind.agregation = 'moyenne' then
    if p_base is null or p_base <= 0 then
      raise exception 'Une moyenne (un taux) a une base positive : son dénominateur.' using errcode = '22023';
    end if;
    if p_numerateur is null and p_valeur is null then
      raise exception 'Une moyenne a un numérateur, ou une valeur.' using errcode = '22023';
    end if;
    v_num := coalesce(p_numerateur, p_valeur * p_base);
    v_valeur := v_num / p_base;
    if p_valeur is not null and abs(p_valeur - v_valeur) > 0.005 + 0.005 * abs(v_valeur) then
      raise exception 'Valeur incohérente : % ne vaut pas % ÷ %.', p_valeur, v_num, p_base
        using errcode = '22023', hint = 'Un pourcentage s''enregistre en fraction : 0,78 pour 78 %.';
    end if;
  else
    if p_valeur is null then
      raise exception 'Une valeur est nécessaire.' using errcode = '22023';
    end if;
    if p_numerateur is not null then
      raise exception 'Un numérateur ne sert qu''aux moyennes.' using errcode = '22023';
    end if;
    if p_base is not null and p_base < 0 then
      raise exception 'Une base est positive.' using errcode = '22023';
    end if;
    v_valeur := p_valeur;
    v_num := null;
  end if;

  -- Une série garde un seul grain : deux grains ensemble compteraient deux fois.
  perform pg_advisory_xact_lock(hashtextextended(concat_ws('|', 'mesure', p_client, p_indicateur, p_version, p_mode,
                                                           p_entite, p_objet_type, p_objet_id), 0));
  select m.periode_type into v_grain
  from public.mesures m
  where m.client_id = p_client and m.indicateur = p_indicateur and m.version = p_version and m.mode = p_mode
    and m.entite_id is not distinct from p_entite and m.objet_type is not distinct from p_objet_type
    and m.objet_id is not distinct from p_objet_id and m.periode_type <> p_periode_type
  limit 1;
  if v_grain is not null then
    raise exception 'Cette série se mesure déjà par %, pas par % : un seul grain par série.', v_grain, p_periode_type
      using errcode = '22023', hint = 'Enregistrer le grain le plus fin : le rapport en tire la semaine et le mois.';
  end if;
  if p_periode_type = 'libre' and exists (
      select 1 from public.mesures m
      where m.client_id = p_client and m.indicateur = p_indicateur and m.version = p_version and m.mode = p_mode
        and m.entite_id is not distinct from p_entite and m.objet_type is not distinct from p_objet_type
        and m.objet_id is not distinct from p_objet_id
        and (m.debut, m.fin) <> (p_periode_debut, v_fin)
        and m.debut <= v_fin and m.fin >= p_periode_debut) then
    raise exception 'Cette période chevauche une autre mesure à blanc de la série.' using errcode = '22023';
  end if;

  select m.id into v_id
  from public.mesures m
  where m.client_id = p_client and m.indicateur = p_indicateur and m.version = p_version and m.mode = p_mode
    and m.periode_type = p_periode_type and m.debut = p_periode_debut and m.fin = v_fin
    and m.entite_id is not distinct from p_entite and m.objet_type is not distinct from p_objet_type
    and m.objet_id is not distinct from p_objet_id;
  if v_id is null then
    insert into public.mesures (client_id, indicateur, version, mode, periode_type, debut, fin, valeur, numerateur, base,
                                entite_id, objet_type, objet_id, objet_libelle)
    values (p_client, p_indicateur, p_version, p_mode, p_periode_type, p_periode_debut, v_fin, v_valeur, v_num, p_base,
            p_entite, p_objet_type, p_objet_id, v_libelle)
    returning id into v_id;
  else
    -- Recalculer remplace ; sans changement, ni écriture ni journal.
    update public.mesures m
       set valeur = v_valeur, numerateur = v_num, base = p_base,
           objet_libelle = coalesce(v_libelle, m.objet_libelle), maj_le = now()
     where m.id = v_id
       and (m.valeur, m.numerateur, m.base, m.objet_libelle)
           is distinct from (v_valeur, v_num, p_base, coalesce(v_libelle, m.objet_libelle));
  end if;
  return v_id;
end $$;


--
-- Name: entites_sans_cycle(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entites_sans_cycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.parent_id is not null and exists (
    with recursive ascendants (id, parent_id) as (
      select e.id, e.parent_id from public.entites e where e.id = new.parent_id
      union
      select e.id, e.parent_id from public.entites e join ascendants a on e.id = a.parent_id
    )
    select 1 from ascendants where id = new.id
  ) then
    raise exception 'Une entité ne peut pas dépendre d''elle-même, même indirectement.'
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: envoi_valide(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.envoi_valide(p_envoi uuid, p_instant timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
  v jsonb;
begin
  select * into e from public.envois where id = p_envoi;
  if not found or e.statut not in ('a_valider', 'differe', 'pret') then
    return coalesce(e.statut, 'introuvable');
  end if;
  -- Un envoi à la fois par organisation : délai, plafonds et doublons ne se croisent pas.
  perform pg_advisory_xact_lock(hashtextextended('omega.envois:' || e.client_id::text, 0));
  select * into e from public.envois where id = p_envoi for update;
  if e.statut not in ('a_valider', 'differe', 'pret') then
    return e.statut;
  end if;
  if e.echeance <= p_instant then
    perform private.clore_envoi(p_envoi, 'expire', 'ECHEANCE', 'L''échéance de cet envoi est passée avant son départ.');
    return 'expire';
  end if;
  v := private.verrous_envoi(e, true, p_instant);
  if v ->> 'code' is null then
    update public.envois
       set statut = 'pret', verrou = null, motif = null, reprise_le = null, mode = v ->> 'mode',
           expediteur_id = (v ->> 'expediteur')::uuid, fournisseur = v ->> 'fournisseur',
           pret_le = now(), decide_le = coalesce(decide_le, now())
     where id = p_envoi
    returning * into e;
    perform private.confier_envoi(e);
    return 'pret';
  elsif not (v ->> 'definitif')::boolean then
    update public.envois
       set statut = 'differe', verrou = v ->> 'code', motif = v ->> 'motif', reprise_le = (v ->> 'reprise')::timestamptz,
           decide_le = coalesce(decide_le, now())
     where id = p_envoi;
    return 'differe';
  end if;
  update public.envois set decide_le = coalesce(decide_le, now()) where id = p_envoi;
  perform private.clore_envoi(p_envoi, 'bloque', v ->> 'code', v ->> 'motif');
  return 'bloque';
end $$;


--
-- Name: envois_suivre_demande(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.envois_suivre_demande() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
begin
  if new.statut is not distinct from old.statut or new.statut not in ('approuvee', 'rejetee', 'expiree', 'annulee') then
    return null;
  end if;
  select e.id into v_id from public.envois e where e.demande_id = new.id and e.statut = 'a_valider';
  if v_id is null then
    return null;
  end if;
  if new.statut = 'approuvee' then
    perform private.envoi_valide(v_id);
  else
    perform private.clore_envoi(v_id,
      case new.statut when 'rejetee' then 'refuse' when 'expiree' then 'expire' else 'annule' end,
      case new.statut when 'rejetee' then 'REFUSE' when 'expiree' then 'ECHEANCE' else 'ANNULE' end,
      case new.statut when 'rejetee' then 'Refusé à la validation.'
                      when 'expiree' then 'La validation n''est pas venue avant l''échéance.'
                      else 'Demande de validation annulée.' end);
  end if;
  return null;
end $$;


--
-- Name: envois_suivre_modification(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.envois_suivre_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
  v_ancien jsonb;
  v_cle text;
  v_canal private.canaux_envoi;
  v_sujet text;
  v_corps text;
  v_v jsonb;
  v_contexte boolean;
begin
  select * into e from public.envois x
  where x.demande_id = (new.payload ->> 'remplace')::uuid and x.statut = 'a_valider' and not x.adossee
  for update;
  if e.id is null then
    return null;
  end if;
  select d.payload into v_ancien from public.demandes_validation d where d.id = e.demande_id;
  for v_cle in select k from jsonb_object_keys(new.payload) k union select k from jsonb_object_keys(v_ancien) k loop
    if v_cle not in ('sujet', 'corps', 'remplace', 'modifications')
       and (new.payload -> v_cle) is distinct from (v_ancien -> v_cle) then
      raise exception 'Seuls le sujet et le corps d''un envoi se modifient.' using errcode = '42501';
    end if;
  end loop;
  if e.canal = 'whatsapp' and e.gabarit_id is not null then
    raise exception 'Un message WhatsApp suit le modèle approuvé par Meta : il ne se retouche pas.' using errcode = '42501';
  end if;
  select * into v_canal from private.canaux_envoi c where c.canal = e.canal;
  v_sujet := nullif(btrim(new.payload ->> 'sujet'), '');
  v_corps := new.payload ->> 'corps';
  if nullif(btrim(v_corps), '') is null or char_length(v_corps) > v_canal.longueur_max
     or char_length(coalesce(v_sujet, '')) > 300
     or (v_canal.sujet = 'obligatoire' and v_sujet is null) or (v_canal.sujet = 'interdit' and v_sujet is not null) then
    raise exception 'Le texte modifié ne convient pas au canal % (sujet, longueur).', v_canal.libelle using errcode = '22023';
  end if;
  -- Un texte retouché est un texte libre : dans un contexte de santé, il en porte.
  v_contexte := coalesce((select m.sante from private.modules_envois m where m.module = e.module), false)
                or (private.reglages_envois_effectifs(e.client_id, e.module) ->> 'sante')::boolean;
  update public.envois
     set demande_id = new.id, sujet = v_sujet, corps = v_corps,
         empreinte = private.empreinte_contenu(e.canal, e.destinataire_adresse, v_sujet, v_corps, e.pieces),
         donnees_sante = e.donnees_sante or v_contexte, modifie_par = (select auth.uid())
   where id = e.id
  returning * into e;
  v_v := private.verrous_envoi(e, false, now());
  if v_v ->> 'code' is not null then
    perform private.clore_envoi(e.id, 'bloque', v_v ->> 'code', v_v ->> 'motif');
    update public.demandes_validation set statut = 'annulee' where id = new.id and statut = 'en_attente';
  elsif new.statut = 'approuvee' then
    perform private.envoi_valide(e.id);
  end if;
  return null;
end $$;


--
-- Name: envoyer_alertes(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.envoyer_alertes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cle text;
  v_nom_secret text := (select valeur from private.reglages where cle = 'alertes_secret_resend');
  v_expediteur text := (select valeur from private.reglages where cle = 'alertes_expediteur');
  v_destinataire text := (select valeur from private.reglages where cle = 'alertes_destinataire');
  v_exp_avis text := coalesce((select valeur from private.reglages where cle = 'avis_expediteur'),
                              (select valeur from private.reglages where cle = 'alertes_expediteur'));
  v_espace text := coalesce((select valeur from private.reglages where cle = 'espace_url'), 'https://app.omegaai.fr/espace');
  v_dest text[];
  r record;
  n integer := 0;
begin
  select s.decrypted_secret into v_cle from vault.decrypted_secrets s where s.name = v_nom_secret limit 1;
  if v_cle is null then
    return 0;
  end if;

  -- Les alertes critiques internes : à Omega, avec le détail technique.
  if v_destinataire is not null then
    for r in
      select a.id, a.titre, a.detail, a.cree_le
      from public.alertes a
      where a.envoyee_le is null and a.niveau = 'critique' and a.acquittee_le is null and a.interne
      order by a.cree_le
      limit 20
    loop
      perform net.http_post(
        url := 'https://api.resend.com/emails',
        headers := jsonb_build_object('Authorization', 'Bearer ' || v_cle, 'Content-Type', 'application/json'),
        body := jsonb_build_object(
          'from', v_expediteur,
          'to', jsonb_build_array(v_destinataire),
          'subject', '[Omega] ' || r.titre,
          'text', r.titre || E'\n\nLevée le ' || to_char(r.cree_le at time zone 'America/Guadeloupe', 'DD/MM/YYYY à HH24:MI')
                  || ' (heure de Guadeloupe).' || E'\n\nDétail : ' || r.detail::text
                  || E'\n\nCet e-mail part de la base Omega (chien de garde).'));
      update public.alertes set envoyee_le = now() where id = r.id;
      n := n + 1;
    end loop;
  end if;

  -- Les avis au client : à la personne nommée s'il y en a une ; sinon à ses
  -- destinataires désignés ; sinon, pour le critique, à ses gérants.
  for r in
    select a.id, a.client_id, a.niveau, a.source, a.titre, a.destinataire_id
    from public.alertes a
    where a.envoyee_le is null and a.acquittee_le is null and not a.interne
      and a.niveau in ('attention', 'critique') and a.cree_le > now() - interval '7 days'
    order by a.cree_le
    limit 20
  loop
    v_dest := null;
    if r.destinataire_id is not null then
      select array_agg(u.email) into v_dest from auth.users u where u.id = r.destinataire_id and u.email is not null;
    end if;

    if v_dest is null then
      select array_agg(distinct u.email order by u.email) into v_dest
      from (
        select d.user_id from public.destinataires_avis d
        where d.client_id = r.client_id and d.user_id is not null
          and private.rang_niveau(r.niveau) >= private.rang_niveau(d.niveau_min)
          and (d.sources is null or r.source = any (d.sources))
        union
        select m.user_id from public.destinataires_avis d
        join public.equipes_membres m on m.equipe_id = d.equipe_id
        where d.client_id = r.client_id and d.equipe_id is not null
          and private.rang_niveau(r.niveau) >= private.rang_niveau(d.niveau_min)
          and (d.sources is null or r.source = any (d.sources))
      ) x
      join auth.users u on u.id = x.user_id
      where u.email is not null;
    end if;

    if v_dest is null and r.niveau = 'critique'
       and not exists (select 1 from public.destinataires_avis d where d.client_id = r.client_id) then
      select array_agg(distinct u.email order by u.email) into v_dest
      from public.comptes c join auth.users u on u.id = c.user_id
      where c.client_id = r.client_id and c.role = 'gerant' and u.email is not null;
    end if;

    continue when v_dest is null or cardinality(v_dest) = 0;

    perform net.http_post(
      url := 'https://api.resend.com/emails',
      headers := jsonb_build_object('Authorization', 'Bearer ' || v_cle, 'Content-Type', 'application/json'),
      body := jsonb_build_object(
        'from', v_exp_avis,
        'to', to_jsonb(v_dest),
        'subject', r.titre,
        'text', r.titre || E'\n\nLe détail vous attend dans votre espace : ' || v_espace
                || E'\n\nVous recevez cet avis parce que votre organisation vous a désigné pour le recevoir.'
                || E'\n\n— Omega'));
    update public.alertes set envoyee_le = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: est_mon_adresse(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.est_mon_adresse(p_client uuid, p_adresse text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.comptes c join auth.users u on u.id = c.user_id
    where c.client_id = p_client and c.user_id = (select auth.uid())
      and (private.normaliser_email(u.email) = p_adresse
           or (nullif(u.phone, '') is not null and private.normaliser_telephone('+' || ltrim(u.phone, '+')) = p_adresse)))
$$;


--
-- Name: exiger_acteur_envoi(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_acteur_envoi(p_client uuid, p_entite uuid, p_objet_type text, p_objet_id text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    if coalesce(nullif(current_setting('role', true), 'none'), session_user::text) in ('service_role', 'postgres') then
      return null;
    end if;
    raise exception 'Seul un membre de l''organisation, ou un moteur, agit sur les envois.' using errcode = '42501';
  end if;
  if not private.a_un_role(p_client, array['gerant', 'admin', 'valideur', 'collaborateur'])
     or not private.perimetre_couvre(v_uid, p_client, p_entite)
     or (p_objet_type is not null and not private.ecrit_objet(p_client, p_objet_type, p_objet_id)) then
    raise exception 'Seul un membre qui agit, dans son périmètre et sur un objet qu''il peut écrire, agit sur cet envoi.'
      using errcode = '42501';
  end if;
  return v_uid;
end $$;


--
-- Name: exiger_acteur_suivi(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_acteur_suivi(p_client uuid, p_entite uuid, p_objet_type text, p_objet_id text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.exiger_acteur_envoi(p_client, p_entite, p_objet_type, p_objet_id)
$$;


--
-- Name: demandes_validation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.demandes_validation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid,
    module text NOT NULL,
    type_action text NOT NULL,
    objet_type text,
    objet_id text,
    resume text NOT NULL,
    montant numeric(14,2),
    devise character(3) DEFAULT 'EUR'::bpchar NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    demandeur_type text DEFAULT 'utilisateur'::text NOT NULL,
    demandeur_id uuid,
    statut text DEFAULT 'en_attente'::text NOT NULL,
    approbations_requises smallint DEFAULT 1 NOT NULL,
    roles_autorises text[] DEFAULT ARRAY['gerant'::text, 'admin'::text, 'valideur'::text] NOT NULL,
    regle_id uuid,
    echeance timestamp with time zone,
    cle_idempotence text NOT NULL,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    decide_le timestamp with time zone,
    execute_le timestamp with time zone,
    motif_echec text,
    equipe_id uuid,
    politique_id uuid,
    CONSTRAINT demandes_validation_cle_idempotence_check CHECK (((char_length(cle_idempotence) >= 1) AND (char_length(cle_idempotence) <= 200))),
    CONSTRAINT demandes_validation_demandeur_type_check CHECK ((demandeur_type = ANY (ARRAY['utilisateur'::text, 'systeme'::text]))),
    CONSTRAINT demandes_validation_module_check CHECK ((module ~ '^[a-z][a-z_]{1,29}$'::text)),
    CONSTRAINT demandes_validation_montant_check CHECK (((montant IS NULL) OR (montant >= (0)::numeric))),
    CONSTRAINT demandes_validation_resume_check CHECK (((char_length(resume) >= 1) AND (char_length(resume) <= 500))),
    CONSTRAINT demandes_validation_statut_check CHECK ((statut = ANY (ARRAY['en_attente'::text, 'approuvee'::text, 'rejetee'::text, 'annulee'::text, 'expiree'::text, 'executee'::text, 'echec_execution'::text]))),
    CONSTRAINT demandes_validation_type_action_check CHECK (((char_length(type_action) >= 1) AND (char_length(type_action) <= 80)))
);


--
-- Name: exiger_decideur(public.demandes_validation, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_decideur(p_d public.demandes_validation, p_decideur uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text;
  v_equipe text;
begin
  select c.role into v_role from public.comptes c
  where c.user_id = p_decideur and c.client_id = p_d.client_id;
  if v_role is null or not (v_role = any (p_d.roles_autorises)) then
    raise exception 'Ce rôle ne peut pas décider de cette demande.' using errcode = '42501';
  end if;
  if not private.perimetre_couvre(p_decideur, p_d.client_id, p_d.entite_id) then
    raise exception 'Cette demande est hors de votre périmètre.' using errcode = '42501';
  end if;
  if p_d.equipe_id is not null and not private.dans_equipe(p_decideur, p_d.equipe_id) then
    select e.nom into v_equipe from public.equipes e where e.id = p_d.equipe_id;
    raise exception 'Cette demande revient à l''équipe « % ».', coalesce(v_equipe, '?') using errcode = '42501';
  end if;
  if not private.voit_objet_pour(p_decideur, p_d.client_id, p_d.objet_type, p_d.objet_id) then
    raise exception 'Vous n''avez pas accès à l''objet de cette demande.' using errcode = '42501';
  end if;
end $$;


--
-- Name: exiger_ecriture_delai(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_ecriture_delai(p_client uuid, p_objet_type text, p_objet_id text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    if coalesce(nullif(current_setting('role', true), 'none'), session_user::text) in ('service_role', 'postgres') then
      return;
    end if;
    raise exception 'Seul un membre de l''organisation, ou un moteur, pose un délai.' using errcode = '42501';
  end if;
  if not private.a_un_role(p_client, array['gerant', 'admin', 'valideur', 'collaborateur'])
     or not private.ecrit_objet(p_client, p_objet_type, p_objet_id) then
    raise exception 'Seul un membre qui peut écrire sur cet objet y pose ou y clôt un délai.' using errcode = '42501';
  end if;
end $$;


--
-- Name: exiger_gestion_releve(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_gestion_releve(p_client uuid, p_entite uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    if coalesce(nullif(current_setting('role', true), 'none'), session_user::text) in ('service_role', 'postgres') then
      return;
    end if;
    raise exception 'Seuls un gérant ou un administrateur de l''organisation, ou Omega, règlent ses branchements.'
      using errcode = '42501';
  end if;
  if not private.a_un_role(p_client, array['gerant', 'admin'])
     or (p_entite is not null and not private.voit_entite(p_client, p_entite)) then
    raise exception 'Seuls un gérant ou un administrateur de l''organisation, ou Omega, règlent ses branchements.'
      using errcode = '42501';
  end if;
end $$;


--
-- Name: exiger_ouvrier(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_ouvrier() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is not null
     or coalesce(nullif(current_setting('role', true), 'none'), session_user::text) not in ('service_role', 'postgres') then
    raise exception 'Réservé à l''ouvrier d''envoi (le serveur).' using errcode = '42501';
  end if;
end $$;


--
-- Name: exiger_porte_du_module(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_porte_du_module(p_module text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is not null
     and exists (select 1 from private.delais_verrouilles v where v.module = p_module)
     and coalesce(current_setting('omega.delai_module', true), '') is distinct from p_module then
    raise exception 'Les délais de % se posent, se notifient, se tiennent et s''annulent dans le module.', p_module
      using errcode = '42501';
  end if;
end $$;


--
-- Name: exiger_reglage_destinataire(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exiger_reglage_destinataire(p_client uuid, p_adresse text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    perform private.exiger_ouvrier();
    return null;
  end if;
  if private.a_un_role(p_client, array['gerant', 'admin', 'valideur', 'collaborateur'])
     or (p_adresse is not null and private.est_mon_adresse(p_client, p_adresse)) then
    return v_uid;
  end if;
  raise exception 'Seul un membre qui agit, ou la personne elle-même pour sa propre adresse, règle ce qu''elle reçoit.'
    using errcode = '42501';
end $$;


--
-- Name: expirer_demandes(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expirer_demandes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  update public.demandes_validation set statut = 'expiree' where statut = 'en_attente' and echeance is not null and echeance < now();
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: exporter_client(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.exporter_client(p_client uuid, p_demandeur uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  r record;
  v_tables jsonb := '{}'::jsonb;
  v_lignes jsonb;
  v_empreinte text;
begin
  if not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;

  for r in select t.nom from private.tables_locataires t order by t.nom loop
    execute format(
      'select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text), ''[]''::jsonb) from public.%I x where x.client_id = $1',
      r.nom)
    into v_lignes using p_client;
    v_tables := v_tables || jsonb_build_object(r.nom, v_lignes);
  end loop;

  -- La fiche de l'organisation, sans identifiant de paiement ni secret de configuration.
  v_tables := v_tables || jsonb_build_object('clients', (
    select coalesce(jsonb_agg(
      (to_jsonb(c) - 'stripe_customer_id') || jsonb_build_object('config', (
        select coalesce(jsonb_object_agg(e.cle, e.valeur), '{}'::jsonb)
        from jsonb_each(c.config) as e(cle, valeur)
        where e.cle !~* '(token|secret|jeton|password|mot_de_passe|cle_api|api_key)'))), '[]'::jsonb)
    from public.clients c where c.id = p_client));

  -- Les fichiers du stockage : leur liste, avec taille et empreinte.
  v_tables := v_tables || jsonb_build_object('fichiers', (
    select coalesce(jsonb_agg(jsonb_build_object('bucket', f.bucket, 'nom', f.nom, 'octets', f.octets,
                                                 'empreinte', f.empreinte, 'cree_le', f.cree_le)
                              order by f.bucket, f.nom), '[]'::jsonb)
    from private.fichiers_de(p_client) f));

  v_empreinte := encode(sha256(convert_to(v_tables::text, 'UTF8')), 'hex');

  perform private.journaliser(p_client, 'donnees.export', 'clients', p_client::text,
    jsonb_build_object('empreinte_sha256', v_empreinte, 'demandeur', p_demandeur));

  return jsonb_build_object(
    'organisation', p_client,
    'genere_le', to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'empreinte_sha256', v_empreinte,
    'tables', v_tables);
end $_$;


--
-- Name: fenetre_effective(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fenetre_effective(p_instantane uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  j public.branchements_jeux;
  v_fuseau text;
  v_col text;
  v_du date;
  v_au date;
  v_base date;
begin
  select * into i from public.instantanes where id = p_instantane;
  select * into j from public.branchements_jeux where id = i.jeu_id;
  select b.fuseau into v_fuseau from public.branchements b where b.id = i.branchement_id;
  if i.fenetre is not null then
    return jsonb_build_object('colonne', coalesce(i.fenetre ->> 'colonne', j.fenetre ->> 'colonne'),
                              'du', i.fenetre ->> 'du', 'au', i.fenetre ->> 'au', 'origine', 'fichier');
  end if;
  if j.fenetre is null then
    return null;
  end if;
  v_col := j.fenetre ->> 'colonne';
  if coalesce((j.fenetre ->> 'observee')::boolean, false) then
    select min(d), max(d) into v_du, v_au
    from (select private.date_de(l.valeurs ->> v_col, v_fuseau) d
          from public.instantanes_lignes l where l.instantane_id = i.id) x;
    if v_du is null then
      -- Aucune date dans l'export : aucune ligne datée n'est dans sa portée.
      return jsonb_build_object('colonne', v_col, 'du', '9999-12-31', 'au', '0001-01-01', 'origine', 'observee');
    end if;
    return jsonb_build_object('colonne', v_col, 'du', v_du, 'au', v_au, 'origine', 'observee');
  end if;
  v_base := (i.recu_le at time zone v_fuseau)::date;
  return jsonb_build_object('colonne', v_col, 'du', v_base + (j.fenetre ->> 'du')::integer,
                            'au', v_base + (j.fenetre ->> 'au')::integer, 'origine', 'relative');
end $$;


--
-- Name: fenetre_fichier_valide(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fenetre_fichier_valide(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p is null then
    return true;
  end if;
  if jsonb_typeof(p) <> 'object'
     or exists (select 1 from jsonb_object_keys(p) x where x not in ('colonne', 'du', 'au'))
     or coalesce(p ->> 'du', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or coalesce(p ->> 'au', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or (p ? 'colonne' and coalesce(p ->> 'colonne', '') !~ '^[a-z][a-z0-9_]{0,62}$') then
    return false;
  end if;
  return (p ->> 'du')::date <= (p ->> 'au')::date;
exception when others then
  return false;
end $_$;


--
-- Name: fenetre_jeu_valide(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fenetre_jeu_valide(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p is null then
    return true;
  end if;
  if jsonb_typeof(p) <> 'object' or coalesce(p ->> 'colonne', '') !~ '^[a-z][a-z0-9_]{0,62}$'
     or exists (select 1 from jsonb_object_keys(p) x where x not in ('colonne', 'du', 'au', 'observee')) then
    return false;
  end if;
  if p ? 'observee' then
    return p -> 'observee' = 'true'::jsonb and not (p ? 'du') and not (p ? 'au');
  end if;
  if jsonb_typeof(p -> 'du') is distinct from 'number' or jsonb_typeof(p -> 'au') is distinct from 'number'
     or (p ->> 'du') !~ '^-?[0-9]{1,5}$' or (p ->> 'au') !~ '^-?[0-9]{1,5}$' then
    return false;
  end if;
  return (p ->> 'du')::integer <= (p ->> 'au')::integer;
end $_$;


--
-- Name: fermer_alertes_releve(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fermer_alertes_releve(p_client uuid, p_module text, p_cle text, p_resolution text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  update public.alertes
     set acquittee_le = now(), detail = detail || jsonb_build_object('resolution', p_resolution)
   where client_id = p_client and acquittee_le is null
     and (cle_regroupement = p_module || ':' || p_cle or starts_with(cle_regroupement, p_module || ':' || p_cle || '.'));
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: fichiers_de(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fichiers_de(p_client uuid, p_objet_type text DEFAULT NULL::text, p_objet_id text DEFAULT NULL::text) RETURNS TABLE(bucket text, nom text, octets bigint, empreinte text, cree_le timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select o.bucket_id, o.name, nullif(o.metadata ->> 'size', '')::bigint, o.metadata ->> 'eTag', o.created_at
  from storage.objects o
  join private.buckets_locataires b on b.bucket = o.bucket_id
  where starts_with(o.name, p_client::text || '/'
                    || case when p_objet_type is null then '' else p_objet_type || '/' || p_objet_id || '/' end)
  order by o.bucket_id, o.name
$$;


--
-- Name: filed_annuler_reception(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_annuler_reception(p_reception uuid, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_r public.filed_receptions;
begin
  select * into v_r from public.filed_receptions where id = p_reception for update;
  if not found then
    raise exception 'Réception introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_r.client_id, array['gerant', 'admin', 'valideur'], v_r.entite_id);
  if nullif(btrim(p_motif), '') is null then
    raise exception 'Dites pourquoi.' using errcode = '22023';
  end if;
  if v_r.statut = 'annulee' then
    raise exception 'Cette réception est déjà annulée.' using errcode = '55000';
  end if;
  update public.filed_receptions set statut = 'annulee', motif = left(btrim(p_motif), 500), maj_le = now() where id = v_r.id;
  perform private.filed_historiser(v_r.client_id, v_r.document_id, 'filed_reception', v_r.id::text, 'annulee',
    'Réception annulée par une personne : ' || left(btrim(p_motif), 300), '{}'::jsonb);
  perform private.filed_recontroler_reception(v_r.id);
end $$;


--
-- Name: filed_apparier_ligne(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_apparier_ligne(p_facture uuid, p_facture_ligne uuid, p_commande_ligne uuid, p_motif text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_l public.filed_factures_lignes;
  v_cl public.filed_commandes_lignes;
begin
  v_f := private.filed_exiger_facture(p_facture, array['gerant', 'admin', 'valideur', 'collaborateur']);
  select * into v_l from public.filed_factures_lignes where id = p_facture_ligne and facture_id = v_f.id;
  if not found then
    raise exception 'Cette ligne n''est pas une ligne de la facture.' using errcode = 'P0002';
  end if;
  delete from public.filed_appariements where facture_ligne_id = v_l.id;
  if p_commande_ligne is not null then
    select * into v_cl from public.filed_commandes_lignes where id = p_commande_ligne and client_id = v_f.client_id;
    if not found then
      raise exception 'Ligne de commande introuvable dans cette organisation.' using errcode = 'P0002';
    end if;
    if coalesce(v_f.commande_force, v_f.commande_id) is distinct from v_cl.commande_id then
      -- La ligne désigne aussi sa commande.
      update public.filed_factures set commande_force = v_cl.commande_id, maj_le = now() where id = v_f.id;
    end if;
    insert into public.filed_appariements (client_id, facture_id, document_id, facture_ligne_id, commande_ligne_id, motif, apparie_par)
    values (v_f.client_id, v_f.id, v_f.document_id, v_l.id, v_cl.id, left(nullif(btrim(p_motif), ''), 500), (select auth.uid()));
  end if;
  perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'ligne_appariee',
    case when p_commande_ligne is null then format('Ligne %s détachée de sa ligne de commande par une personne', v_l.rang)
         else format('Ligne %s appariée par une personne à la ligne %s de la commande', v_l.rang, v_cl.rang) end
      || coalesce(' (' || nullif(btrim(p_motif), '') || ')', '') || '.',
    jsonb_strip_nulls(jsonb_build_object('facture_ligne', v_l.id, 'commande_ligne', p_commande_ligne)));
  return private.filed_controler_facture(v_f.id);
end $$;


--
-- Name: filed_apparier_reception(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_apparier_reception(p_reception uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public.filed_receptions;
  r record;
  v_cl uuid;
  v_n integer := 0;
begin
  select * into v_r from public.filed_receptions where id = p_reception;
  if v_r.commande_id is null then
    return 0;
  end if;
  for r in select l.* from public.filed_receptions_lignes l where l.reception_id = v_r.id
           and (l.methode is null or l.methode in ('reference', 'designation', 'seule')) order by l.rang
  loop
    v_cl := null;
    -- La référence reçue est celle d'une ligne commandée (référence, référence acheteur, GTIN).
    if private.filed_normaliser_numero(r.reference) is not null then
      select c.id into v_cl from public.filed_commandes_lignes c
      where c.commande_id = v_r.commande_id
        and private.filed_normaliser_numero(r.reference) in (private.filed_normaliser_numero(c.reference),
                                                              private.filed_normaliser_numero(c.reference_acheteur),
                                                              private.filed_normaliser_numero(c.gtin))
      order by c.rang limit 1;
      if v_cl is not null then
        update public.filed_receptions_lignes set commande_ligne_id = v_cl, methode = 'reference' where id = r.id;
        v_n := v_n + 1;
        continue;
      end if;
    end if;
    -- La même désignation, portée par une seule ligne commandée.
    if coalesce(r.designation_normalisee, '') <> '' then
      select min(c.id::text)::uuid into v_cl from public.filed_commandes_lignes c
      where c.commande_id = v_r.commande_id and c.designation_normalisee = r.designation_normalisee
      having count(*) = 1;
      if v_cl is not null then
        update public.filed_receptions_lignes set commande_ligne_id = v_cl, methode = 'designation' where id = r.id;
        v_n := v_n + 1;
        continue;
      end if;
    end if;
    update public.filed_receptions_lignes set commande_ligne_id = null, methode = null where id = r.id;
  end loop;
  -- Une seule ligne reçue sans ligne, une seule ligne commandée sans réception : c'est elle.
  if (select count(*) from public.filed_receptions_lignes l where l.reception_id = v_r.id and l.commande_ligne_id is null) = 1
     and (select count(*) from public.filed_commandes_lignes c where c.commande_id = v_r.commande_id
          and not exists (select 1 from public.filed_receptions_lignes x where x.reception_id = v_r.id and x.commande_ligne_id = c.id)) = 1 then
    update public.filed_receptions_lignes l
       set commande_ligne_id = (select c.id from public.filed_commandes_lignes c where c.commande_id = v_r.commande_id
                                and not exists (select 1 from public.filed_receptions_lignes x
                                                where x.reception_id = v_r.id and x.commande_ligne_id = c.id)),
           methode = 'seule'
     where l.reception_id = v_r.id and l.commande_ligne_id is null;
    v_n := v_n + 1;
  end if;
  return v_n;
end $$;


--
-- Name: filed_bloquer_fournisseur(uuid, boolean, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_bloquer_fournisseur(p_fournisseur uuid, p_bloquer boolean, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_f public.filed_fournisseurs;
begin
  select * into v_f from public.filed_fournisseurs where id = p_fournisseur for update;
  if not found then
    raise exception 'Fournisseur introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_f.client_id, array['gerant', 'admin'], null);
  if nullif(btrim(p_motif), '') is null then
    raise exception 'Un blocage dit pourquoi.' using errcode = '22023';
  end if;
  if p_bloquer and v_f.statut not in ('actif', 'a_confirmer') then
    raise exception 'Ce fournisseur ne se bloque pas (%).', v_f.statut using errcode = '55000';
  end if;
  if not p_bloquer and v_f.statut <> 'bloque' then
    raise exception 'Ce fournisseur n''est pas bloqué.' using errcode = '55000';
  end if;
  update public.filed_fournisseurs
     set statut = case when p_bloquer then 'bloque' when confirme_le is not null then 'actif' else 'a_confirmer' end,
         motif = left(btrim(p_motif), 500), maj_le = now()
   where id = v_f.id;
  perform private.filed_historiser(v_f.client_id, null, 'filed_fournisseur', v_f.id::text,
    case when p_bloquer then 'bloque' else 'debloque' end,
    case when p_bloquer then 'Fournisseur bloqué : ' else 'Fournisseur débloqué : ' end || left(btrim(p_motif), 300),
    '{}'::jsonb);
  perform private.filed_recontroler_fournisseur(v_f.id);
end $$;


--
-- Name: filed_booleen(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_booleen(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case jsonb_typeof(p) when 'boolean' then (p #>> '{}')::boolean
                              when 'string' then lower(p #>> '{}') in ('true', 'oui', '1') else null end
$$;


--
-- Name: filed_classer_document(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_classer_document(p_document uuid, p_nature text, p_motif text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_doc public.filed_documents;
  v_statut_piece text;
  v_relire boolean;
  v_etat text;
begin
  select * into v_doc from public.filed_documents where id = p_document for update;
  if not found then
    raise exception 'Document introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_doc.client_id, array['gerant', 'admin', 'valideur', 'collaborateur'], v_doc.entite_id);
  if (select auth.uid()) is not null
     and not private.voit_objet(v_doc.client_id, 'filed_document', v_doc.id::text) then
    raise exception 'Document introuvable.' using errcode = 'P0002';
  end if;
  if p_nature is null or p_nature not in ('facture', 'avoir', 'bon_commande', 'bon_livraison', 'devis', 'releve',
                                          'contrat', 'attestation_assurance', 'autre') then
    raise exception 'Type inconnu : %.', coalesce(p_nature, 'vide') using errcode = '22023';
  end if;
  if v_doc.etat not in ('a_classer', 'illisible', 'classe', 'a_traiter') then
    raise exception 'Ce document ne se reclasse plus (%).', v_doc.etat using errcode = '55000';
  end if;

  delete from public.pieces_valeurs v
  where v.piece_id = v_doc.piece_id and v.champ = 'type_piece' and v.source = 'humain';
  insert into public.pieces_valeurs (client_id, piece_id, champ, valeur, texte, source, confiance, verifiee, controle)
  values (v_doc.client_id, v_doc.piece_id, 'type_piece', to_jsonb(p_nature), 'Type tranché par une personne',
          'humain', 1, true, left(nullif(btrim(p_motif), ''), 300));

  select p.statut into v_statut_piece from public.pieces p where p.id = v_doc.piece_id for update;
  v_relire := p_nature in ('facture', 'avoir', 'bon_commande', 'bon_livraison')
              and v_statut_piece in ('lue', 'a_verifier', 'a_classer');
  v_etat := case when v_relire then 'en_lecture' else private.filed_etat_de(p_nature) end;

  update public.filed_documents
     set nature = p_nature, nature_source = 'humain', etat = v_etat, motif = left(nullif(btrim(p_motif), ''), 500),
         traite_le = now()
   where id = p_document;
  if v_relire then
    -- Remise « recue », la pièce se relit d'elle-même (socle, lot 9b).
    update public.pieces set statut = 'recue' where id = v_doc.piece_id;
  end if;

  perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'classe_par_une_personne',
    'Classé par une personne : ' || private.filed_libelle_nature(p_nature)
      || coalesce(' (' || nullif(btrim(p_motif), '') || ')', '')
      || case when v_relire then ', relu avec ce type.' else '.' end,
    jsonb_build_object('nature', p_nature, 'etat_avant', v_doc.etat, 'nature_avant', v_doc.nature, 'relecture', v_relire));
  return v_etat;
end $$;


--
-- Name: filed_confirmer_valeurs(uuid, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_confirmer_valeurs(p_facture uuid, p_champs text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_piece uuid;
  v jsonb;
  k text;
begin
  v_f := private.filed_exiger_facture(p_facture, array['gerant', 'admin', 'valideur', 'collaborateur']);
  select d.piece_id into v_piece from public.filed_documents d where d.id = v_f.document_id;
  v := private.filed_valeurs(v_piece);
  if p_champs is null or cardinality(p_champs) = 0 then
    raise exception 'Aucun champ à confirmer.' using errcode = '22023';
  end if;
  foreach k in array p_champs loop
    if not (v ? k) or v -> k ->> 'source' = 'humain' then
      raise exception 'Rien à confirmer pour « % » : la pièce n''en porte pas de valeur lue.', k using errcode = '22023';
    end if;
    insert into public.pieces_valeurs (client_id, piece_id, champ, valeur, texte, page, source, confiance, verifiee, controle)
    values (v_f.client_id, v_piece, k, v -> k -> 'valeur', left(v -> k ->> 'texte', 2000), (v -> k ->> 'page')::integer,
            'humain', 1, true, 'Confirmé sur la pièce par une personne');
  end loop;
  perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'confirmee',
    'Valeurs confirmées sur la pièce par une personne : ' || array_to_string(p_champs, ', ') || '.',
    jsonb_build_object('champs', to_jsonb(p_champs)));
  return private.filed_integrer_facture(v_f.document_id);
end $$;


--
-- Name: filed_controler_facture(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_controler_facture(p_facture uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_doc public.filed_documents;
  v_four public.filed_fournisseurs;
  v_ent public.entites;
  v_reglage public.filed_reglages;
  v_regime_ter text;
  v_regime text;
  v_manque text[] := '{}';
  v_tol numeric;
  v_ecart numeric;
  v_somme numeric;
  v_nb_lignes integer;
  v_autre public.filed_factures;
  v_autre_ref text;
  v_ecartee uuid;
  v_ib public.filed_fournisseurs_ibans;
  v_autre_four public.filed_fournisseurs;
  v_pays_iban text;
  v_taux_ok numeric[];
  v_taux_fr numeric[];
  v_taux numeric;
  v_taux_trouve numeric;
  v_hors text[];
  v_tol_taux numeric;
  v_ach_siren text;
  v_ent_siren text;
  v_autre_ent public.entites;
  v_auj date;
  v_statut text;
  v_anomalies text[];
  v_bloquants integer;
  v_attention integer;
  v_lecture boolean;
  v_message text;
begin
  select * into v_f from public.filed_factures where id = p_facture for update;
  if not found then
    raise exception 'Facture introuvable.' using errcode = 'P0002';
  end if;
  select * into v_doc from public.filed_documents where id = v_f.document_id;
  select * into v_four from public.filed_fournisseurs where id = v_f.fournisseur_id;
  select * into v_ent from public.entites where id = v_f.entite_id;
  v_reglage := private.filed_reglage(v_f.client_id, v_f.entite_id);
  v_tol := coalesce(v_reglage.tolerance_totaux, 0.05);
  v_auj := (now() at time zone coalesce(v_ent.fuseau, 'Europe/Paris'))::date;
  select count(*) into v_nb_lignes from public.filed_factures_lignes l where l.facture_id = v_f.id;

  delete from public.filed_controles where facture_id = v_f.id;

  -- ── La lecture : ce qui manque, ce qui reste à vérifier ──
  if v_f.numero is null then v_manque := array_append(v_manque, 'le numéro'); end if;
  if v_f.date_emission is null then v_manque := array_append(v_manque, 'la date d''émission'); end if;
  if v_f.montant_ttc is null then v_manque := array_append(v_manque, 'le total TTC'); end if;
  if v_f.montant_ht is null or v_f.montant_tva is null then v_manque := array_append(v_manque, 'le HT et la TVA'); end if;
  if v_f.fournisseur_id is null then v_manque := array_append(v_manque, 'le fournisseur'); end if;
  perform private.filed_poser_resultat(v_f, 'lecture.complete', 'bloquant', cardinality(v_manque) > 0,
    case when cardinality(v_manque) = 0 then 'Les champs essentiels sont lus.'
         else 'À compléter : ' || array_to_string(v_manque, ', ') || '.' end,
    'NON_CONFORME', jsonb_build_object('manque', to_jsonb(v_manque)));
  perform private.filed_poser_resultat(v_f, 'lecture.verifiee', 'bloquant', jsonb_array_length(v_f.champs_douteux) > 0,
    case when jsonb_array_length(v_f.champs_douteux) = 0 then 'Chaque valeur retenue est vérifiée sur la pièce.'
         else 'À vérifier sur la pièce : ' || (select string_agg(x ->> 'champ' || coalesce(' (' || (x ->> 'controle') || ')', ''), ', ')
                                                from jsonb_array_elements(v_f.champs_douteux) x) || '.' end,
    null, jsonb_build_object('champs', v_f.champs_douteux));

  -- ── Les montants ──
  if v_f.montant_ttc is not null then
    perform private.filed_poser_resultat(v_f, 'montant.nul', 'bloquant', v_f.montant_ttc = 0,
      case when v_f.montant_ttc = 0 then 'Total à zéro : une lecture ratée, le plus souvent. La pièce attend une personne.'
           else 'Le total n''est pas nul.' end, 'MONTANTTOTAL_ERR');
    perform private.filed_poser_resultat(v_f, 'montant.signe', 'bloquant', v_f.nature = 'facture' and v_f.montant_ttc < 0,
      case when v_f.nature = 'facture' and v_f.montant_ttc < 0
           then 'Total négatif sur une facture : c''est peut-être un avoir.' else 'Le signe du total est cohérent.' end,
      'MONTANTTOTAL_ERR', '{}'::jsonb, v_f.montant_ttc::text);
  end if;
  if v_f.montant_ht is not null and v_f.montant_tva is not null and v_f.montant_ttc is not null then
    v_ecart := v_f.montant_ht + v_f.montant_tva - v_f.montant_ttc;
    perform private.filed_poser_resultat(v_f, 'montant.coherence', 'bloquant', abs(v_ecart) > v_tol,
      case when abs(v_ecart) > v_tol
           then format('HT + TVA − TTC = %s : l''écart dépasse la tolérance de %s. La pièce attend une personne.',
                       private.filed_montant_texte(v_ecart), private.filed_montant_texte(v_tol))
           else 'HT + TVA = TTC.' end,
      'CALCUL_ERR', jsonb_build_object('ht', v_f.montant_ht, 'tva', v_f.montant_tva, 'ttc', v_f.montant_ttc,
                                       'ecart', v_ecart, 'tolerance', v_tol), v_ecart::text);
  end if;
  if v_nb_lignes > 0 and v_f.montant_ht is not null then
    select sum(l.montant_ht) into v_somme from public.filed_factures_lignes l where l.facture_id = v_f.id;
    if v_somme is not null then
      perform private.filed_poser_resultat(v_f, 'montant.lignes', 'attention', abs(v_somme - v_f.montant_ht) > v_tol,
        case when abs(v_somme - v_f.montant_ht) > v_tol
             then format('Les lignes font %s pour un HT de %s : remise ou frais au pied de la facture, ou ligne mal lue.',
                         private.filed_montant_texte(v_somme), private.filed_montant_texte(v_f.montant_ht))
             else 'La somme des lignes égale le HT.' end,
        'CALCUL_ERR', jsonb_build_object('somme_lignes', v_somme, 'ht', v_f.montant_ht, 'lignes', v_nb_lignes));
    end if;
  end if;
  if v_f.net_a_payer is not null and v_f.montant_ttc is not null and v_f.net_a_payer <> v_f.montant_ttc then
    perform private.filed_poser_resultat(v_f, 'montant.net_a_payer', 'info', true,
      format('Net à payer de %s pour un TTC de %s : un acompte ou un paiement déjà fait est déduit.',
             private.filed_montant_texte(v_f.net_a_payer), private.filed_montant_texte(v_f.montant_ttc)),
      null, jsonb_build_object('net_a_payer', v_f.net_a_payer, 'ttc', v_f.montant_ttc));
  end if;
  if v_f.devise <> 'EUR' then
    perform private.filed_poser_resultat(v_f, 'montant.devise', 'info', true,
      format('Montants en %s, lus tels qu''ils figurent sur la pièce, sans conversion.', v_f.devise));
  end if;
  if cardinality(v_f.montants_calcules) > 0 then
    perform private.filed_poser_resultat(v_f, 'montant.calcule', 'info', true,
      'Montant déduit des autres, faute de ligne sur la pièce : ' || array_to_string(v_f.montants_calcules, ', ') || '.',
      null, jsonb_build_object('champs', to_jsonb(v_f.montants_calcules)));
  end if;

  -- ── Les doublons : numéro, année de la date d'émission, SIREN du fournisseur
  -- (règles G1.42 et G1.45 de la DGFiP). Seule une pièce reçue plus tôt fait
  -- d'une autre son doublon. ──
  if v_f.numero_normalise is not null and v_f.date_emission is not null and v_f.fournisseur_id is not null then
    select e.* into v_autre
    from public.filed_factures e
    join public.filed_documents d on d.id = e.document_id
    left join public.filed_fournisseurs ef on ef.id = e.fournisseur_id
    where e.client_id = v_f.client_id and e.id <> v_f.id and e.nature = v_f.nature and e.statut <> 'ecartee'
      and (e.fournisseur_id = v_f.fournisseur_id or (v_four.siren is not null and ef.siren = v_four.siren))
      and e.numero_normalise = v_f.numero_normalise
      and extract(year from e.date_emission) = extract(year from v_f.date_emission)
      and (d.annee_reception, d.numero_reception) < (v_doc.annee_reception, v_doc.numero_reception)
    order by d.annee_reception, d.numero_reception
    limit 1;
    if v_autre.id is not null then
      select d.reference into v_autre_ref from public.filed_documents d where d.id = v_autre.document_id;
      if v_autre.montant_ttc is not distinct from v_f.montant_ttc and v_autre.date_emission = v_f.date_emission then
        v_ecartee := v_autre.id;
      end if;
    end if;
    perform private.filed_poser_resultat(v_f, 'doublon.exact', 'bloquant', v_autre.id is not null,
      case when v_autre.id is null then 'Aucune autre facture de ce fournisseur ne porte ce numéro cette année.'
           when v_ecartee is not null then format('Même facture que la pièce %s : même numéro, même date, même montant. Écartée, elle reste consultable.', v_autre_ref)
           else format('Même numéro que la pièce %s, pour un montant de %s au lieu de %s : un numéro ne sert qu''une fois.',
                       v_autre_ref, private.filed_montant_texte(v_f.montant_ttc), private.filed_montant_texte(v_autre.montant_ttc)) end,
      'DOUBLON', case when v_autre.id is null then '{}'::jsonb
                      else jsonb_build_object('facture', v_autre.id, 'piece', v_autre_ref) end,
      coalesce(v_autre.id::text, ''));
  end if;
  if v_f.montant_ttc is not null and v_f.date_emission is not null and v_f.fournisseur_id is not null and v_ecartee is null then
    v_autre := null;
    select e.* into v_autre
    from public.filed_factures e join public.filed_documents d on d.id = e.document_id
    where e.client_id = v_f.client_id and e.id <> v_f.id and e.nature = v_f.nature and e.statut <> 'ecartee'
      and e.fournisseur_id = v_f.fournisseur_id and e.montant_ttc = v_f.montant_ttc
      and e.numero_normalise is distinct from v_f.numero_normalise
      and abs(e.date_emission - v_f.date_emission) <= coalesce(v_reglage.doublon_fenetre_jours, 3)
      and (d.annee_reception, d.numero_reception) < (v_doc.annee_reception, v_doc.numero_reception)
    order by d.annee_reception, d.numero_reception
    limit 1;
    if v_autre.id is not null then
      select d.reference into v_autre_ref from public.filed_documents d where d.id = v_autre.document_id;
    end if;
    perform private.filed_poser_resultat(v_f, 'doublon.probable', 'bloquant', v_autre.id is not null,
      case when v_autre.id is null then 'Aucune facture voisine du même fournisseur au même montant.'
           else format('Même fournisseur, même montant (%s), à %s jour(s) de la pièce %s : doublon probable, sous un autre numéro.',
                       private.filed_montant_texte(v_f.montant_ttc), abs(v_autre.date_emission - v_f.date_emission), v_autre_ref) end,
      'DOUBLON', case when v_autre.id is null then '{}'::jsonb
                      else jsonb_build_object('facture', v_autre.id, 'piece', v_autre_ref, 'numero', v_autre.numero) end,
      coalesce(v_autre.id::text, ''));
    v_autre := null;
    select e.* into v_autre
    from public.filed_factures e join public.filed_documents d on d.id = e.document_id
    where e.client_id = v_f.client_id and e.id <> v_f.id and e.fournisseur_id is distinct from v_f.fournisseur_id
      and e.numero_normalise = v_f.numero_normalise and e.montant_ttc = v_f.montant_ttc
      and e.date_emission = v_f.date_emission and e.statut <> 'ecartee'
      and (d.annee_reception, d.numero_reception) < (v_doc.annee_reception, v_doc.numero_reception)
    limit 1;
    if v_autre.id is not null then
      select d.reference into v_autre_ref from public.filed_documents d where d.id = v_autre.document_id;
      perform private.filed_poser_resultat(v_f, 'doublon.autre_fournisseur', 'attention', true,
        format('Même numéro, même date et même montant que la pièce %s, sous un autre fournisseur : la même facture présentée deux fois ?', v_autre_ref),
        'DOUBLON', jsonb_build_object('facture', v_autre.id, 'piece', v_autre_ref), v_autre.id::text);
    end if;
  end if;

  -- ── Le fournisseur ──
  if v_four.id is not null then
    perform private.filed_poser_resultat(v_f, 'fournisseur.a_confirmer', 'bloquant', v_four.statut = 'a_confirmer',
      case when v_four.statut = 'a_confirmer'
           then format('Fournisseur nouveau (%s) : une personne le confirme avant tout paiement.', private.filed_libelle_fournisseur(v_four))
           else 'Fournisseur connu.' end,
      'EMMET_INC', jsonb_build_object('fournisseur', v_four.id));
    if v_four.statut = 'refuse' then
      perform private.filed_poser_resultat(v_f, 'fournisseur.refuse', 'bloquant', true,
        format('Fournisseur refusé par une personne (%s) : ne pas payer.', coalesce(v_four.motif, 'sans motif écrit')),
        'EMMET_INC', jsonb_build_object('fournisseur', v_four.id));
    end if;
    if v_four.statut = 'bloque' then
      perform private.filed_poser_resultat(v_f, 'fournisseur.bloque', 'bloquant', true,
        format('Fournisseur bloqué (%s) : aucune facture ne passe.', coalesce(v_four.motif, 'sans motif écrit')),
        'CREANCIER_ERR', jsonb_build_object('fournisseur', v_four.id));
    end if;
    if v_f.fournisseur_identification = 'nom' then
      perform private.filed_poser_resultat(v_f, 'fournisseur.identification', 'attention', true,
        'Fournisseur reconnu à son seul nom, faute de SIREN ou de TVA lisibles : vérifier.', null,
        jsonb_build_object('fournisseur', v_four.id));
    end if;
    if v_f.fournisseur_lu ? 'siren' and v_four.siren is not null then
      perform private.filed_poser_resultat(v_f, 'fournisseur.siren', 'bloquant', v_f.fournisseur_lu ->> 'siren' <> v_four.siren,
        case when v_f.fournisseur_lu ->> 'siren' <> v_four.siren
             then format('Le SIREN de la facture (%s) n''est pas celui du fournisseur retenu (%s).', v_f.fournisseur_lu ->> 'siren', v_four.siren)
             else 'Le SIREN de la facture est celui du fournisseur.' end,
        'NON_CONFORME', jsonb_build_object('lu', v_f.fournisseur_lu ->> 'siren', 'fournisseur', v_four.siren),
        v_f.fournisseur_lu ->> 'siren');
    end if;
  end if;

  -- ── L'IBAN ──
  if v_f.iban is not null then
    if not private.filed_iban_valide(v_f.iban) then
      perform private.filed_poser_resultat(v_f, 'iban.invalide', 'bloquant', true,
        format('IBAN faux (%s) : sa clé ne tombe pas juste.', private.filed_masquer_iban(v_f.iban)), 'COORD_BANC_ERR');
    elsif v_four.id is not null then
      select * into v_ib from public.filed_fournisseurs_ibans
      where client_id = v_f.client_id and fournisseur_id = v_four.id and iban = v_f.iban;
      if v_ib.statut = 'refuse' then
        perform private.filed_poser_resultat(v_f, 'iban.refuse', 'bloquant', true,
          format('IBAN déjà refusé pour ce fournisseur (%s) : ne pas payer, alerter.', v_ib.iban_masque), 'COORD_BANC_ERR',
          jsonb_build_object('iban', v_ib.iban_masque, 'refuse_le', v_ib.decide_le));
        perform private.lever_alerte_module(v_f.client_id, 'filed', 'critique',
          left(format('IBAN refusé présenté de nouveau par %s', v_four.nom), 200),
          jsonb_build_object('facture', v_f.id, 'fournisseur', v_four.id, 'iban', v_ib.iban_masque),
          'iban_refuse:' || v_ib.id::text || ':' || v_f.id::text, true, null);
      elsif v_ib.statut = 'propose' and v_four.statut = 'actif' then
        perform private.filed_poser_resultat(v_f, 'iban.nouveau', 'bloquant', true,
          format('Nouvel IBAN (%s) pour ce fournisseur : une personne le vérifie auprès de lui avant tout paiement.', v_ib.iban_masque),
          'COORD_BANC_ERR', jsonb_build_object('iban', v_ib.iban_masque));
      elsif v_ib.statut = 'revoque' then
        perform private.filed_poser_resultat(v_f, 'iban.nouveau', 'bloquant', true,
          format('IBAN révoqué pour ce fournisseur (%s) : il ne sert plus.', v_ib.iban_masque), 'COORD_BANC_ERR',
          jsonb_build_object('iban', v_ib.iban_masque));
      else
        perform private.filed_poser_resultat(v_f, 'iban.nouveau', 'bloquant', false,
          case when v_ib.statut = 'valide' then 'IBAN connu et validé pour ce fournisseur.'
               else 'IBAN proposé avec le fournisseur nouveau : il se valide avec lui.' end);
      end if;
      select f.* into v_autre_four
      from public.filed_fournisseurs_ibans i join public.filed_fournisseurs f on f.id = i.fournisseur_id
      where i.client_id = v_f.client_id and i.iban = v_f.iban and i.statut = 'valide' and i.fournisseur_id <> v_four.id
      limit 1;
      perform private.filed_poser_resultat(v_f, 'iban.partage', 'bloquant', v_autre_four.id is not null,
        case when v_autre_four.id is null then 'L''IBAN n''appartient à aucun autre fournisseur.'
             else format('Cet IBAN est déjà celui d''un autre fournisseur (%s) : affacturage à justifier, ou fraude.', v_autre_four.nom) end,
        'COORD_BANC_ERR', case when v_autre_four.id is null then '{}'::jsonb
                               else jsonb_build_object('autre_fournisseur', v_autre_four.id) end,
        coalesce(v_autre_four.id::text, ''));
      v_pays_iban := left(v_f.iban, 2);
      if v_four.pays is not null and v_pays_iban <> replace(v_four.pays, 'EL', 'GR') then
        perform private.filed_poser_resultat(v_f, 'iban.pays', 'attention', true,
          format('IBAN tenu dans un autre pays (%s) que celui du fournisseur (%s) : à vérifier.', v_pays_iban, v_four.pays),
          'COORD_BANC_ERR', jsonb_build_object('pays_iban', v_pays_iban, 'pays_fournisseur', v_four.pays));
      end if;
    end if;
  elsif v_four.id is not null and not exists (select 1 from public.filed_fournisseurs_ibans i
                                             where i.fournisseur_id = v_four.id and i.statut = 'valide') then
    perform private.filed_poser_resultat(v_f, 'iban.absent', 'info', true,
      'Aucun IBAN sur la facture ni au référentiel : le paiement passera par un autre moyen.');
  end if;

  -- ── Le destinataire : la facture est-elle adressée à cette société ? ──
  v_ach_siren := v_f.acheteur_lu ->> 'siren';
  v_ent_siren := coalesce(v_ent.siren, case when v_ent.principale then (select c.siren from public.clients c where c.id = v_f.client_id) end);
  if v_ach_siren is not null then
    if v_ent_siren = v_ach_siren then
      perform private.filed_poser_resultat(v_f, 'destinataire.societe', 'bloquant', false,
        'Facture adressée à cette société.');
    else
      select e.* into v_autre_ent from public.entites e
      where e.client_id = v_f.client_id and e.id <> v_f.entite_id and e.siren = v_ach_siren
      limit 1;
      if v_autre_ent.id is not null then
        update public.filed_factures set entite_id = v_autre_ent.id where id = v_f.id;
        update public.filed_documents set entite_id = v_autre_ent.id where id = v_f.document_id;
        v_f.entite_id := v_autre_ent.id;
        perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'reorientee',
          format('Adressée à %s (SIREN %s) : rangée dans cette société.', v_autre_ent.nom, v_ach_siren),
          jsonb_build_object('entite', v_autre_ent.id, 'siren', v_ach_siren));
        perform private.filed_poser_resultat(v_f, 'destinataire.societe', 'info', true,
          format('Adressée à %s : rangée dans cette société.', v_autre_ent.nom), null,
          jsonb_build_object('entite', v_autre_ent.id));
      elsif v_ent_siren is null then
        perform private.filed_poser_resultat(v_f, 'destinataire.societe', 'info', true,
          'Le SIREN de la société n''est pas renseigné : le destinataire n''est pas vérifié.');
      else
        perform private.filed_poser_resultat(v_f, 'destinataire.societe', 'bloquant', true,
          format('Facture adressée à une autre société (SIREN %s) que celle-ci (SIREN %s).', v_ach_siren, v_ent_siren),
          'DEST_ERR', jsonb_build_object('siren_facture', v_ach_siren, 'siren_societe', v_ent_siren), v_ach_siren);
      end if;
    end if;
  end if;

  -- ── La TVA ──
  if v_f.montant_tva is not null and v_f.montant_ht is not null then
    v_regime := case
      when v_f.montant_tva <> 0 and (select count(distinct t.taux) from public.filed_factures_tva t
                                     where t.facture_id = v_f.id and t.taux > 0) > 1 then 'mixte'
      when v_f.montant_tva <> 0 then 'normal'
      when exists (select 1 from public.filed_factures_tva t where t.facture_id = v_f.id and upper(t.categorie) = 'AE')
           or coalesce((v_f.mentions ->> 'autoliquidation')::boolean, false)
           or v_four.regime_tva = 'autoliquidation_btp' then 'autoliquidation'
      when private.filed_pays_ue(v_four.pays) then 'intracom'
      when v_four.pays is not null and v_four.pays <> 'FR' then 'hors_ue'
      when coalesce((v_f.mentions ->> 'franchise_293b')::boolean, false) or v_four.regime_tva = 'franchise' then 'franchise'
      when exists (select 1 from public.filed_factures_tva t where t.facture_id = v_f.id
                   and upper(t.categorie) in ('E', 'Z', 'G', 'K', 'O'))
           or v_four.regime_tva = 'exonere' then 'exonere'
      else 'sans_tva' end;
    update public.filed_factures set regime_tva = v_regime where id = v_f.id;
    v_f.regime_tva := v_regime;

    if v_four.pays = 'FR' and v_f.montant_ht > coalesce(v_reglage.seuil_mentions_ht, 150)
       and v_regime not in ('franchise') and v_four.tva is null and not (v_f.fournisseur_lu ? 'tva') then
      perform private.filed_poser_resultat(v_f, 'tva.numero', 'attention', true,
        'Numéro de TVA du fournisseur absent de la facture : mention obligatoire (CGI, art. 242 nonies A), et la TVA déductible en dépend.',
        'NON_CONFORME');
    end if;
    if v_f.fournisseur_lu ->> 'tva' like 'FR%' and coalesce(v_f.fournisseur_lu ->> 'siren', v_four.siren) is not null then
      perform private.filed_poser_resultat(v_f, 'tva.numero_siren', 'bloquant',
        right(v_f.fournisseur_lu ->> 'tva', 9) <> coalesce(v_f.fournisseur_lu ->> 'siren', v_four.siren),
        case when right(v_f.fournisseur_lu ->> 'tva', 9) <> coalesce(v_f.fournisseur_lu ->> 'siren', v_four.siren)
             then format('Le numéro de TVA (%s) n''est pas celui du SIREN %s : il appartient à une autre société.',
                         v_f.fournisseur_lu ->> 'tva', coalesce(v_f.fournisseur_lu ->> 'siren', v_four.siren))
             else 'Le numéro de TVA est bien celui du SIREN du fournisseur.' end,
        'NON_CONFORME', '{}'::jsonb, v_f.fournisseur_lu ->> 'tva');
    end if;

    v_regime_ter := private.filed_regime_territorial(v_f.client_id, v_f.entite_id);
    select coalesce(array_agg(distinct t.taux), '{}') into v_taux_fr from public.filed_taux_tva t;
    select coalesce(array_agg(distinct t.taux), '{}') into v_taux_ok from public.filed_taux_tva t
    where v_regime_ter is null or t.regime = v_regime_ter;

    if v_regime in ('normal', 'mixte') then
      if v_regime_ter = 'sans_tva' then
        perform private.filed_poser_resultat(v_f, 'tva.taux', 'attention', true,
          'TVA facturée à une société d''un territoire où la TVA française ne s''applique pas (Guyane, Mayotte, collectivité à fiscalité propre) : à vérifier.',
          'TX_TVA_ERR', jsonb_build_object('territoire', v_regime_ter), 'territoire');
      elsif exists (select 1 from public.filed_factures_tva t where t.facture_id = v_f.id and t.taux is not null) then
        select array_agg(distinct t.taux::text order by t.taux::text) into v_hors from public.filed_factures_tva t
        where t.facture_id = v_f.id and t.taux > 0 and not (t.taux = any (v_taux_fr));
        if v_hors is not null then
          perform private.filed_poser_resultat(v_f, 'tva.taux', 'bloquant', true,
            'Taux de TVA qui n''existe pas en France : ' || array_to_string(v_hors, ' %, ') || ' %.', 'TX_TVA_ERR',
            jsonb_build_object('taux', to_jsonb(v_hors)), array_to_string(v_hors, ','));
        else
          select array_agg(distinct t.taux::text order by t.taux::text) into v_hors from public.filed_factures_tva t
          where t.facture_id = v_f.id and t.taux > 0 and not (t.taux = any (v_taux_ok));
          perform private.filed_poser_resultat(v_f, 'tva.taux', 'attention', v_hors is not null,
            case when v_hors is null then 'Chaque taux de TVA est un taux légal du territoire de la société.'
                 else 'Taux légal ailleurs en France, pas dans le territoire de la société : ' || array_to_string(v_hors, ' %, ') || ' %.' end,
            'TX_TVA_ERR', jsonb_build_object('territoire', v_regime_ter, 'taux', to_jsonb(v_hors)),
            coalesce(array_to_string(v_hors, ','), ''));
        end if;
        select sum(t.montant) into v_somme from public.filed_factures_tva t where t.facture_id = v_f.id;
        if v_somme is not null then
          perform private.filed_poser_resultat(v_f, 'tva.ventilation', 'attention', abs(v_somme - v_f.montant_tva) > v_tol,
            case when abs(v_somme - v_f.montant_tva) > v_tol
                 then format('La ventilation fait %s de TVA pour un total de %s.', private.filed_montant_texte(v_somme),
                             private.filed_montant_texte(v_f.montant_tva))
                 else 'La ventilation de la TVA égale son total.' end,
            'CALCUL_ERR', jsonb_build_object('somme', v_somme, 'tva', v_f.montant_tva));
        end if;
      elsif v_f.montant_ht <> 0 then
        -- Sans ventilation : le taux qui redonne la TVA au centime près, ligne par ligne arrondie.
        v_tol_taux := least(1.00, greatest(0.02, 0.005 * greatest(v_nb_lignes, 1)));
        v_taux_trouve := null;
        foreach v_taux in array v_taux_fr loop
          if abs(round(v_f.montant_ht * v_taux / 100, 2) - v_f.montant_tva) <= v_tol_taux then
            if v_taux_trouve is null or v_taux = any (v_taux_ok) then
              v_taux_trouve := v_taux;
            end if;
          end if;
        end loop;
        if v_taux_trouve is not null and v_taux_trouve = any (v_taux_ok) then
          perform private.filed_poser_resultat(v_f, 'tva.taux', 'bloquant', false,
            format('TVA au taux légal de %s %%.', replace(trim(trailing '.' from trim(trailing '0' from v_taux_trouve::text)), '.', ',')),
            'TX_TVA_ERR', jsonb_build_object('taux', v_taux_trouve, 'territoire', v_regime_ter), v_taux_trouve::text);
        elsif v_taux_trouve is not null then
          perform private.filed_poser_resultat(v_f, 'tva.taux', 'attention', true,
            format('TVA au taux de %s %%, légal ailleurs en France mais pas dans le territoire de la société.',
                   replace(trim(trailing '.' from trim(trailing '0' from v_taux_trouve::text)), '.', ',')),
            'TX_TVA_ERR', jsonb_build_object('taux', v_taux_trouve, 'territoire', v_regime_ter), v_taux_trouve::text);
        elsif v_f.montant_tva / v_f.montant_ht * 100 between (select min(x) from unnest(v_taux_ok) x) - 0.01
                                                         and (select max(x) from unnest(v_taux_ok) x) + 0.01 then
          perform private.filed_poser_resultat(v_f, 'tva.taux', 'attention', true,
            format('Taux moyen de %s %% : plusieurs taux probables, que la pièce ne détaille pas.',
                   replace(round(v_f.montant_tva / v_f.montant_ht * 100, 2)::text, '.', ',')),
            'TX_TVA_ERR', jsonb_build_object('taux_moyen', round(v_f.montant_tva / v_f.montant_ht * 100, 3)),
            round(v_f.montant_tva / v_f.montant_ht * 100, 3)::text);
        else
          perform private.filed_poser_resultat(v_f, 'tva.taux', 'bloquant', true,
            format('Taux moyen de %s %% : aucun taux légal ne redonne cette TVA.',
                   replace(round(v_f.montant_tva / v_f.montant_ht * 100, 2)::text, '.', ',')),
            'TX_TVA_ERR', jsonb_build_object('taux_moyen', round(v_f.montant_tva / v_f.montant_ht * 100, 3)),
            round(v_f.montant_tva / v_f.montant_ht * 100, 3)::text);
        end if;
      end if;
    end if;

    if v_regime = 'sans_tva' and v_f.montant_ht <> 0 then
      perform private.filed_poser_resultat(v_f, 'tva.sans_mention', 'attention', true,
        'Aucune TVA, sans mention d''exonération, d''autoliquidation ou de franchise : à vérifier.', 'TX_TVA_ERR');
    end if;
    if v_four.regime_tva = 'autoliquidation_btp' then
      perform private.filed_poser_resultat(v_f, 'tva.autoliquidation_attendue', 'bloquant', v_f.montant_tva <> 0,
        case when v_f.montant_tva <> 0
             then 'Sous-traitant du bâtiment : sa facture se fait hors taxes avec la mention « autoliquidation » (CGI, art. 283-2 nonies). La TVA facturée est une anomalie.'
             else 'Facture de sous-traitant hors taxes : la TVA sera autoliquidée.' end,
        'TX_TVA_ERR', '{}'::jsonb, v_f.montant_tva::text);
    end if;
    if v_regime in ('autoliquidation', 'intracom', 'hors_ue') then
      perform private.filed_poser_resultat(v_f, 'tva.regime', 'info', true,
        case v_regime
          when 'autoliquidation' then 'TVA due par l''acheteur (autoliquidation) : elle sera déclarée et déduite à l''écriture.'
          when 'intracom' then 'Fournisseur de l''Union européenne, sans TVA : acquisition ou service intracommunautaire, TVA autoliquidée.'
          else 'Fournisseur hors de l''Union, sans TVA : TVA autoliquidée à l''écriture, ou payée à l''importation.' end);
    end if;
  end if;

  -- ── Les dates ──
  if v_f.date_emission is not null then
    perform private.filed_poser_resultat(v_f, 'date.future', 'bloquant', v_f.date_emission > v_auj + 1,
      case when v_f.date_emission > v_auj + 1
           then format('Date d''émission dans le futur (%s) : erreur de lecture ou de saisie.', to_char(v_f.date_emission, 'DD/MM/YYYY'))
           else 'Date d''émission passée.' end,
      'NON_CONFORME', '{}'::jsonb, v_f.date_emission::text);
    if v_f.date_emission < v_auj - 365 then
      perform private.filed_poser_resultat(v_f, 'date.ancienne', 'attention', true,
        format('Pièce émise le %s, reçue le %s : plus d''un an d''écart, l''exercice est à vérifier.',
               to_char(v_f.date_emission, 'DD/MM/YYYY'), to_char(v_f.date_reception, 'DD/MM/YYYY')));
    end if;
    if v_f.echeance_lue is not null and v_f.echeance_lue < v_f.date_emission then
      perform private.filed_poser_resultat(v_f, 'date.echeance', 'attention', true,
        'Échéance antérieure à la date d''émission : à vérifier.', 'MODPAI_ERR');
    end if;
  end if;

  -- ── Le cadre de facturation (règle G1.02) ──
  if upper(coalesce(v_f.cadre_facturation, '')) in ('B2', 'S2', 'M2') then
    perform private.filed_poser_resultat(v_f, 'cadre.deja_payee', 'info', true,
      format('Facture déjà payée (cadre %s) : elle ne se paie pas une seconde fois.', upper(v_f.cadre_facturation)));
  end if;

  -- ── Le rapprochement (lot F3) : la commande, la réception, l'avoir ──
  perform private.filed_rapprocher_facture(v_f.id);

  -- ── L'état ──
  select count(*) filter (where c.resultat = 'anomalie' and c.gravite = 'bloquant'),
         count(*) filter (where c.resultat = 'anomalie' and c.gravite = 'attention'),
         bool_or(c.resultat = 'anomalie' and c.famille = 'lecture'),
         coalesce(array_agg(c.code order by c.code) filter (where c.resultat = 'anomalie' and c.gravite <> 'info'), '{}')
  into v_bloquants, v_attention, v_lecture, v_anomalies
  from public.filed_controles c where c.facture_id = v_f.id;

  v_statut := case when coalesce(v_lecture, false) then 'a_completer'
                   when v_ecartee is not null then 'ecartee'
                   when v_bloquants > 0 then 'bloquee'
                   else 'a_valider' end;

  if v_statut is distinct from v_f.statut or v_anomalies is distinct from v_f.anomalies then
    select string_agg(c.message, ' ' order by c.code) into v_message
    from public.filed_controles c
    where c.facture_id = v_f.id and c.resultat = 'anomalie' and c.gravite = 'bloquant';
    perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text,
      'controlee',
      case v_statut
        when 'a_completer' then 'À compléter. ' || coalesce(v_message, '')
        when 'bloquee' then 'Bloquée. ' || coalesce(v_message, '')
        when 'ecartee' then 'Écartée : doublon exact d''une pièce reçue plus tôt.'
        else 'Contrôlée : prête à valider' || case when v_attention > 0 then format(', avec %s point(s) d''attention.', v_attention) else '.' end end,
      jsonb_build_object('statut', v_statut, 'anomalies', to_jsonb(v_anomalies), 'version', v_f.version));
    perform private.filed_journaliser(v_f.client_id, 'filed.controles', 'filed_facture', v_f.id::text,
      jsonb_build_object('statut', v_statut, 'version', v_f.version, 'anomalies', to_jsonb(v_anomalies)), v_f.entite_id);
  end if;

  update public.filed_factures
     set statut = v_statut, doublon_de = v_ecartee, anomalies = v_anomalies, nb_bloquants = v_bloquants,
         nb_attention = v_attention, controle_le = now(), maj_le = now()
   where id = v_f.id;
  return v_statut;
end $$;


--
-- Name: filed_corriger_facture(uuid, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_corriger_facture(p_facture uuid, p_valeurs jsonb, p_motif text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_f public.filed_factures;
  v_piece uuid;
  k text;
  x jsonb;
  v_norme jsonb;
  v_champs text[] := '{}';
  v_statut text;
begin
  v_f := private.filed_exiger_facture(p_facture, array['gerant', 'admin', 'valideur', 'collaborateur']);
  if p_valeurs is null or jsonb_typeof(p_valeurs) <> 'object' or p_valeurs = '{}'::jsonb then
    raise exception 'Rien à corriger.' using errcode = '22023';
  end if;
  select d.piece_id into v_piece from public.filed_documents d where d.id = v_f.document_id;
  for k, x in select * from jsonb_each(p_valeurs) loop
    v_norme := case
      when k in ('numero', 'devise', 'fournisseur.nom', 'fournisseur.pays', 'acheteur.nom', 'commande.reference',
                 'livraison.reference', 'contrat.reference', 'facture_origine.reference', 'acheteur.reference',
                 'cadre_facturation', 'type_code', 'fournisseur.id_legal')
        then case when private.filed_texte(x) is not null then to_jsonb(left(private.filed_texte(x), 200)) end
      when k in ('date', 'echeance', 'facture_origine.date', 'livraison.date')
        then case when private.filed_date(x) is not null then to_jsonb(private.filed_date(x)::text) end
      when k in ('montant_ht', 'montant_tva', 'montant_ttc', 'net_a_payer', 'montant_prepaye')
        then case when private.filed_nombre(x) is not null then to_jsonb(round(private.filed_nombre(x), 2)::text) end
      when k in ('fournisseur.siren', 'acheteur.siren')
        then case when private.filed_siren_valide(private.filed_texte(x)) then to_jsonb(private.filed_texte(x)) end
      when k in ('fournisseur.siret', 'acheteur.siret')
        then case when private.filed_texte(x) ~ '^[0-9]{14}$' and private.filed_siren_valide(left(private.filed_texte(x), 9))
                  then to_jsonb(private.filed_texte(x)) end
      when k in ('fournisseur.tva', 'acheteur.tva')
        then case when upper(regexp_replace(coalesce(private.filed_texte(x), ''), '[\s.\-]', '', 'g')) ~ '^[A-Z]{2}[0-9A-Z]{2,13}$'
                   and (upper(private.filed_texte(x)) not like 'FR%' or private.filed_tva_fr_valide(private.filed_texte(x)))
                  then to_jsonb(upper(regexp_replace(private.filed_texte(x), '[\s.\-]', '', 'g'))) end
      when k = 'fournisseur.iban'
        then case when private.filed_iban_valide(private.filed_texte(x))
                  then to_jsonb(upper(regexp_replace(private.filed_texte(x), '\s', '', 'g'))) end
      when k in ('lignes', 'tva.ventilation') then case when jsonb_typeof(x) = 'array' then x end
      when k in ('mention.autoliquidation', 'mention.franchise_293b')
        then case when private.filed_booleen(x) is not null then to_jsonb(private.filed_booleen(x)) end
      else null end;
    if v_norme is null then
      raise exception 'Valeur refusée pour « % » : champ inconnu ou valeur illisible (une clé de SIREN, de TVA ou d''IBAN fausse est refusée).', k
        using errcode = '22023';
    end if;
    delete from public.pieces_valeurs v where v.piece_id = v_piece and v.champ = k and v.source = 'humain';
    insert into public.pieces_valeurs (client_id, piece_id, champ, valeur, texte, source, confiance, verifiee, controle)
    values (v_f.client_id, v_piece, k, v_norme, 'Saisi par une personne', 'humain', 1, true, left(nullif(btrim(p_motif), ''), 300));
    v_champs := array_append(v_champs, k);
  end loop;
  perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'corrigee',
    'Corrigée par une personne : ' || array_to_string(v_champs, ', ') || coalesce(' (' || nullif(btrim(p_motif), '') || ')', '') || '.',
    jsonb_build_object('champs', to_jsonb(v_champs)));
  v_statut := private.filed_integrer_facture(v_f.document_id);
  return v_statut;
end $_$;


--
-- Name: filed_fournisseurs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_fournisseurs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    code text NOT NULL,
    nom text NOT NULL,
    nom_normalise text NOT NULL,
    siren text,
    siret text,
    tva text,
    id_etranger text,
    pays text,
    statut text DEFAULT 'a_confirmer'::text NOT NULL,
    source text NOT NULL,
    document_origine uuid,
    regime_tva text,
    confirme_le timestamp with time zone,
    confirme_par uuid,
    motif text,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT filed_fournisseurs_code_check CHECK ((code ~ '^[A-Z0-9][A-Z0-9_.-]{0,29}$'::text)),
    CONSTRAINT filed_fournisseurs_id_etranger_check CHECK (((char_length(id_etranger) >= 1) AND (char_length(id_etranger) <= 60))),
    CONSTRAINT filed_fournisseurs_identifie CHECK (((siren IS NOT NULL) OR (tva IS NOT NULL) OR (id_etranger IS NOT NULL) OR (nom_normalise <> ''::text))),
    CONSTRAINT filed_fournisseurs_motif_check CHECK ((char_length(motif) <= 500)),
    CONSTRAINT filed_fournisseurs_nom_check CHECK (((char_length(btrim(nom)) >= 1) AND (char_length(btrim(nom)) <= 200))),
    CONSTRAINT filed_fournisseurs_pays_check CHECK ((pays ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT filed_fournisseurs_regime_tva_check CHECK ((regime_tva = ANY (ARRAY['normal'::text, 'autoliquidation_btp'::text, 'franchise'::text, 'exonere'::text]))),
    CONSTRAINT filed_fournisseurs_siren_check CHECK ((siren ~ '^[0-9]{9}$'::text)),
    CONSTRAINT filed_fournisseurs_siret_check CHECK ((siret ~ '^[0-9]{14}$'::text)),
    CONSTRAINT filed_fournisseurs_source_check CHECK ((source = ANY (ARRAY['facture'::text, 'piece'::text, 'saisie'::text, 'import'::text]))),
    CONSTRAINT filed_fournisseurs_statut_check CHECK ((statut = ANY (ARRAY['a_confirmer'::text, 'actif'::text, 'bloque'::text, 'refuse'::text]))),
    CONSTRAINT filed_fournisseurs_tva_check CHECK ((tva ~ '^[A-Z]{2}[0-9A-Z]{2,13}$'::text))
);


--
-- Name: filed_creer_fournisseur(uuid, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_creer_fournisseur(p_client uuid, p_identite jsonb, p_source text, p_document uuid DEFAULT NULL::uuid) RETURNS public.filed_fournisseurs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_fournisseurs;
  v_nom text;
  v_numero integer;
  v_pays text;
begin
  v_nom := coalesce(nullif(btrim(p_identite ->> 'nom'), ''),
                    'Fournisseur ' || coalesce('SIREN ' || (p_identite ->> 'siren'), 'TVA ' || (p_identite ->> 'tva'),
                                               p_identite ->> 'id_etranger', 'sans nom'));
  v_pays := coalesce(p_identite ->> 'pays',
                     case when p_identite ? 'siren' then 'FR'
                          when p_identite ? 'tva' then replace(left(p_identite ->> 'tva', 2), 'EL', 'GR') end);
  v_numero := private.filed_prochain_numero(p_client, 'fournisseur', 0::smallint);
  insert into public.filed_fournisseurs (client_id, code, nom, nom_normalise, siren, siret, tva, id_etranger, pays, statut,
                                         source, document_origine, regime_tva, confirme_le, confirme_par)
  values (p_client, coalesce(nullif(upper(btrim(p_identite ->> 'code')), ''), 'F' || lpad(v_numero::text, 5, '0')),
          left(v_nom, 200), private.filed_normaliser_nom(v_nom), p_identite ->> 'siren', p_identite ->> 'siret',
          p_identite ->> 'tva', p_identite ->> 'id_etranger', v_pays,
          case when p_source = 'import' then 'actif' else 'a_confirmer' end, p_source, p_document,
          nullif(p_identite ->> 'regime_tva', ''),
          case when p_source = 'import' then now() end, case when p_source = 'import' then (select auth.uid()) end)
  returning * into v_f;

  if p_source <> 'import' then
    perform private.filed_deposer_demande(p_client, null, 'filed.valider_fournisseur', 'filed_fournisseur', v_f.id::text,
      'Nouveau fournisseur : ' || private.filed_libelle_fournisseur(v_f)
        || coalesce(', IBAN ' || private.filed_masquer_iban(p_identite ->> 'iban'), ''),
      null,
      jsonb_build_object('fournisseur', v_f.id, 'nom', v_f.nom, 'siren', v_f.siren, 'tva', v_f.tva, 'pays', v_f.pays,
                         'iban', case when p_identite ? 'iban' then private.filed_masquer_iban(p_identite ->> 'iban') end,
                         'iban_empreinte', case when p_identite ? 'iban'
                                                then encode(sha256(convert_to(p_identite ->> 'iban', 'UTF8')), 'hex') end,
                         'document', p_document, 'source', p_source),
      'filed:fournisseur:' || v_f.id::text);
    perform private.filed_historiser(p_client, null, 'filed_fournisseur', v_f.id::text, 'cree',
      'Fournisseur nouveau, né d''une pièce : une personne le confirme avant tout paiement.',
      jsonb_build_object('document', p_document, 'code', v_f.code));
  end if;
  return v_f;
end $$;


--
-- Name: filed_date(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_date(p jsonb) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare v text := private.filed_texte(p);
begin
  if v is null or v !~ '^\d{4}-\d{2}-\d{2}$' then
    return null;
  end if;
  return v::date;
exception when others then
  return null;
end $_$;


--
-- Name: filed_deposer_demande(uuid, uuid, text, text, text, text, numeric, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_deposer_demande(p_client uuid, p_entite uuid, p_type text, p_objet_type text, p_objet_id text, p_resume text, p_montant numeric, p_payload jsonb, p_cle text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  insert into public.demandes_validation (client_id, entite_id, module, type_action, objet_type, objet_id, resume,
                                          montant, payload, cle_idempotence)
  values (p_client, p_entite, 'filed', p_type, p_objet_type, p_objet_id, left(p_resume, 500), p_montant,
          coalesce(p_payload, '{}'::jsonb), p_cle)
  on conflict (client_id, cle_idempotence) do nothing
  returning id into v_id;
  if v_id is null then
    select d.id into v_id from public.demandes_validation d where d.client_id = p_client and d.cle_idempotence = p_cle;
  end if;
  return v_id;
end $$;


--
-- Name: filed_deposer_piece(uuid, uuid, text, text, bigint, text, text, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_deposer_piece(p_client uuid, p_document uuid, p_nom_fichier text, p_mime text, p_octets bigint, p_sha256 text, p_chemin text, p_entite uuid DEFAULT NULL::uuid, p_source text DEFAULT 'depot'::text, p_expediteur text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entite uuid;
  v_fuseau text;
  v_uid uuid;
  v_annee smallint;
  v_numero integer;
  v_piece uuid;
  v_original public.filed_documents;
  v_doc public.filed_documents;
begin
  if p_client is null or p_document is null then
    raise exception 'Organisation et document sont obligatoires.' using errcode = '22023';
  end if;
  -- D'abord qui agit, pour ne rien dire d'une organisation à qui n'en est pas.
  v_uid := private.filed_exiger_acteur(p_client, array['gerant', 'admin', 'valideur', 'collaborateur'], null);
  select e.id, e.fuseau into v_entite, v_fuseau from public.entites e
  where e.client_id = p_client and (case when p_entite is null then e.principale else e.id = p_entite end);
  if v_entite is null then
    raise exception 'Société introuvable dans cette organisation.' using errcode = '22023';
  end if;
  if v_uid is not null and not private.perimetre_couvre(v_uid, p_client, v_entite) then
    raise exception 'Cette société est hors de votre périmètre.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.filed_reglages r where r.client_id = p_client and r.entite_id is null and r.actif) then
    raise exception 'FILED n''est pas installé pour cette organisation.' using errcode = '55000';
  end if;
  if p_chemin is null or not starts_with(p_chemin, p_client::text || '/filed_document/' || p_document::text || '/')
     or char_length(p_chemin) <= char_length(p_client::text || '/filed_document/' || p_document::text || '/') then
    raise exception 'Le fichier se range à %/filed_document/%/…', p_client, p_document using errcode = '22023';
  end if;
  if p_source = 'export' then
    raise exception 'Un export se relève par la brique B1 : il n''est pas une pièce à lire.' using errcode = '22023';
  end if;
  if coalesce(p_source, '') not in ('depot', 'courriel', 'connecteur', 'api') then
    raise exception 'Source inconnue : %.', coalesce(p_source, 'vide') using errcode = '22023';
  end if;

  v_annee := extract(year from now() at time zone coalesce(v_fuseau, 'Europe/Paris'))::smallint;
  v_numero := private.filed_prochain_numero(p_client, 'reception', v_annee);

  select d.* into v_original from public.filed_documents d
  where d.client_id = p_client and d.sha256 = lower(p_sha256) and d.etat <> 'doublon'
  order by d.recu_le, d.numero_reception limit 1;

  insert into public.pieces (client_id, module, objet_type, objet_id, source, expediteur, depose_par,
                             nom_fichier, mime, octets, sha256, chemin, statut)
  values (p_client, 'filed', 'filed_document', p_document::text, p_source, p_expediteur, v_uid,
          p_nom_fichier, p_mime, p_octets, lower(p_sha256), p_chemin, 'recue')
  returning id into v_piece;

  insert into public.filed_documents (id, client_id, entite_id, annee_reception, numero_reception, piece_id, source,
                                      expediteur, depose_par, nom_fichier, sha256, etat, doublon_de, motif, traite_le)
  values (p_document, p_client, v_entite, v_annee, v_numero, v_piece, p_source, p_expediteur, v_uid,
          p_nom_fichier, lower(p_sha256),
          case when v_original.id is null then 'en_lecture' else 'doublon' end,
          v_original.id,
          case when v_original.id is null then null
               else left(format('Même fichier que la pièce %s, reçue le %s : écartée, elle reste consultable.',
                                v_original.reference,
                                to_char(v_original.recu_le at time zone coalesce(v_fuseau, 'Europe/Paris'), 'DD/MM/YYYY')), 500) end,
          case when v_original.id is null then null else now() end)
  returning * into v_doc;

  perform private.filed_historiser(p_client, v_doc.id, 'filed_document', v_doc.id::text, 'recu',
    format('Pièce reçue (%s), enregistrée sous le numéro %s.',
           case p_source when 'depot' then 'dépôt' when 'courriel' then 'e-mail' when 'connecteur' then 'connecteur'
                         else 'API' end, v_doc.reference),
    jsonb_build_object('reference', v_doc.reference, 'source', p_source));
  if v_original.id is not null then
    perform private.filed_historiser(p_client, v_doc.id, 'filed_document', v_doc.id::text, 'doublon', v_doc.motif,
      jsonb_build_object('doublon_de', v_original.id, 'reference_originale', v_original.reference));
  end if;

  return jsonb_build_object('document', v_doc.id, 'reference', v_doc.reference, 'piece', v_piece,
                            'etat', v_doc.etat, 'doublon_de', v_doc.doublon_de);
end $$;


--
-- Name: filed_commandes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_commandes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid NOT NULL,
    document_id uuid,
    fournisseur_id uuid,
    numero text NOT NULL,
    numero_normalise text NOT NULL,
    date_commande date,
    devise text DEFAULT 'EUR'::text NOT NULL,
    montant_ht numeric(14,2),
    statut text DEFAULT 'ouverte'::text NOT NULL,
    source text NOT NULL,
    reference_externe text,
    note text,
    fournisseur_lu jsonb DEFAULT '{}'::jsonb NOT NULL,
    motif text,
    cree_par uuid,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT filed_commandes_devise_check CHECK ((devise ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT filed_commandes_montant_ht_check CHECK ((montant_ht >= (0)::numeric)),
    CONSTRAINT filed_commandes_motif_check CHECK ((char_length(motif) <= 500)),
    CONSTRAINT filed_commandes_note_check CHECK ((char_length(note) <= 500)),
    CONSTRAINT filed_commandes_numero_check CHECK (((char_length(btrim(numero)) >= 1) AND (char_length(btrim(numero)) <= 60))),
    CONSTRAINT filed_commandes_numero_normalise_check CHECK ((numero_normalise <> ''::text)),
    CONSTRAINT filed_commandes_reference_externe_check CHECK ((char_length(reference_externe) <= 100)),
    CONSTRAINT filed_commandes_source_check CHECK ((source = ANY (ARRAY['piece'::text, 'import'::text, 'saisie'::text]))),
    CONSTRAINT filed_commandes_statut_check CHECK ((statut = ANY (ARRAY['ouverte'::text, 'soldee'::text, 'annulee'::text])))
);


--
-- Name: filed_ecrire_commande(uuid, uuid, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_ecrire_commande(p_client uuid, p_entite uuid, p_source text, p_donnees jsonb, p_document uuid DEFAULT NULL::uuid, p_par uuid DEFAULT NULL::uuid) RETURNS public.filed_commandes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_c public.filed_commandes;
  v_numero text := left(nullif(btrim(p_donnees ->> 'numero'), ''), 60);
  v_normalise text := private.filed_normaliser_numero(p_donnees ->> 'numero');
  v_fournisseur uuid;
  v_lignes jsonb := case when jsonb_typeof(p_donnees -> 'lignes') = 'array' then p_donnees -> 'lignes' else '[]'::jsonb end;
  v_nb integer;
  v_remplacer boolean;
  v_devise text := upper(coalesce(nullif(btrim(p_donnees ->> 'devise'), ''), 'EUR'));
begin
  if v_numero is null or v_normalise is null then
    raise exception 'Une commande a un numéro.' using errcode = '22023';
  end if;
  if v_devise !~ '^[A-Z]{3}$' then
    v_devise := 'EUR';
  end if;
  v_fournisseur := private.filed_fournisseur_du_bon(p_client, p_donnees, p_source, p_document);

  perform pg_advisory_xact_lock(hashtextextended('filed.commande:' || p_client::text || ':' || v_normalise, 0));
  select * into v_c from public.filed_commandes
  where client_id = p_client and entite_id = p_entite and numero_normalise = v_normalise for update;

  if v_c.id is null then
    insert into public.filed_commandes (client_id, entite_id, document_id, fournisseur_id, numero, numero_normalise,
                                        date_commande, devise, montant_ht, source, reference_externe, note,
                                        fournisseur_lu, cree_par)
    values (p_client, p_entite, p_document, v_fournisseur, v_numero, v_normalise,
            private.filed_date(p_donnees -> 'date'), v_devise, private.filed_nombre(p_donnees -> 'montant_ht'),
            p_source, left(nullif(btrim(p_donnees ->> 'reference_externe'), ''), 100),
            left(nullif(btrim(p_donnees ->> 'note'), ''), 500),
            coalesce(p_donnees -> 'fournisseur', '{}'::jsonb), p_par)
    returning * into v_c;
    v_remplacer := true;
    perform private.filed_historiser(p_client, p_document, 'filed_commande', v_c.id::text, 'creee',
      format('Commande %s%s, %s.', v_numero, coalesce(' du ' || to_char(v_c.date_commande, 'DD/MM/YYYY'), ''),
             case p_source when 'piece' then 'lue sur un bon de commande' when 'import' then 'reprise du système d''achats'
                           else 'saisie par une personne' end),
      jsonb_build_object('source', p_source, 'document', p_document));
  else
    -- La reprise et la saisie sont la source de vérité ; un bon lu complète sans écraser,
    -- sauf s'il est relu.
    v_remplacer := p_source <> 'piece' or v_c.document_id = p_document
                   or not exists (select 1 from public.filed_commandes_lignes l where l.commande_id = v_c.id);
    update public.filed_commandes
       set document_id = coalesce(document_id, p_document),
           fournisseur_id = case when p_source <> 'piece' then coalesce(v_fournisseur, fournisseur_id)
                                 else coalesce(fournisseur_id, v_fournisseur) end,
           date_commande = case when p_source <> 'piece' then coalesce(private.filed_date(p_donnees -> 'date'), date_commande)
                                else coalesce(date_commande, private.filed_date(p_donnees -> 'date')) end,
           montant_ht = case when p_source <> 'piece' then coalesce(private.filed_nombre(p_donnees -> 'montant_ht'), montant_ht)
                             else coalesce(montant_ht, private.filed_nombre(p_donnees -> 'montant_ht')) end,
           devise = case when p_source <> 'piece' then v_devise else devise end,
           reference_externe = coalesce(left(nullif(btrim(p_donnees ->> 'reference_externe'), ''), 100), reference_externe),
           note = coalesce(left(nullif(btrim(p_donnees ->> 'note'), ''), 500), note),
           source = case when p_source <> 'piece' then p_source else source end,
           maj_le = now()
     where id = v_c.id
    returning * into v_c;
    perform private.filed_historiser(p_client, p_document, 'filed_commande', v_c.id::text, 'mise_a_jour',
      format('Commande %s mise à jour (%s)%s.', v_numero,
             case p_source when 'piece' then 'bon de commande lu' when 'import' then 'reprise du système d''achats'
                           else 'saisie par une personne' end,
             case when v_remplacer then ', lignes remplacées' else ', lignes conservées' end),
      jsonb_build_object('source', p_source, 'document', p_document));
  end if;

  if v_remplacer then
    delete from public.filed_commandes_lignes where commande_id = v_c.id;
    insert into public.filed_commandes_lignes (client_id, commande_id, rang, numero, reference, reference_acheteur, gtin,
                                               designation, designation_normalisee, quantite, unite, prix_unitaire,
                                               montant_ht, source)
    select p_client, v_c.id, e.rang::smallint, left(private.filed_texte(e.l -> 'numero'), 60),
           left(private.filed_texte(e.l -> 'reference'), 100), left(private.filed_texte(e.l -> 'reference_acheteur'), 100),
           left(private.filed_texte(e.l -> 'gtin'), 40), left(private.filed_texte(e.l -> 'designation'), 500),
           private.filed_normaliser(private.filed_texte(e.l -> 'designation')),
           coalesce(private.filed_nombre(e.l -> 'quantite'), 0), left(private.filed_texte(e.l -> 'unite'), 20),
           coalesce(private.filed_nombre(e.l -> 'prix_unitaire'), private.filed_nombre(e.l -> 'prix')),
           coalesce(private.filed_nombre(e.l -> 'montant_ht'),
                    round(coalesce(private.filed_nombre(e.l -> 'quantite'), 0)
                          * coalesce(private.filed_nombre(e.l -> 'prix_unitaire'), private.filed_nombre(e.l -> 'prix')), 2)),
           case when p_source = 'piece' and coalesce(p_donnees ->> 'lignes_source', '') in ('xml', 'regle', 'ia', 'humain', 'tableur')
                then p_donnees ->> 'lignes_source' when p_source = 'piece' then 'regle' else p_source end
    from jsonb_array_elements(v_lignes) with ordinality as e(l, rang)
    where e.rang <= 5000 and jsonb_typeof(e.l) = 'object'
      and coalesce(private.filed_nombre(e.l -> 'quantite'), 0) >= 0;
    get diagnostics v_nb = row_count;
    if v_c.montant_ht is null and v_nb > 0 then
      update public.filed_commandes c set montant_ht = s.total
      from (select sum(l.montant_ht) as total from public.filed_commandes_lignes l where l.commande_id = v_c.id) s
      where c.id = v_c.id and s.total is not null
      returning c.* into v_c;
    end if;
  end if;
  perform private.filed_recontroler_commande(v_c.id);
  return v_c;
end $_$;


--
-- Name: filed_receptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_receptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid NOT NULL,
    document_id uuid,
    commande_id uuid,
    fournisseur_id uuid,
    numero text,
    numero_normalise text,
    date_reception date,
    source text NOT NULL,
    statut text DEFAULT 'enregistree'::text NOT NULL,
    commande_lue text,
    fournisseur_lu jsonb DEFAULT '{}'::jsonb NOT NULL,
    note text,
    motif text,
    cree_par uuid,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT filed_receptions_commande_lue_check CHECK ((char_length(commande_lue) <= 100)),
    CONSTRAINT filed_receptions_motif_check CHECK ((char_length(motif) <= 500)),
    CONSTRAINT filed_receptions_note_check CHECK ((char_length(note) <= 500)),
    CONSTRAINT filed_receptions_numero_check CHECK ((char_length(numero) <= 60)),
    CONSTRAINT filed_receptions_source_check CHECK ((source = ANY (ARRAY['piece'::text, 'saisie'::text, 'import'::text]))),
    CONSTRAINT filed_receptions_statut_check CHECK ((statut = ANY (ARRAY['enregistree'::text, 'annulee'::text])))
);


--
-- Name: filed_ecrire_reception(uuid, uuid, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_ecrire_reception(p_client uuid, p_entite uuid, p_source text, p_donnees jsonb, p_document uuid DEFAULT NULL::uuid, p_par uuid DEFAULT NULL::uuid) RETURNS public.filed_receptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_r public.filed_receptions;
  v_numero text := left(nullif(btrim(p_donnees ->> 'numero'), ''), 60);
  v_fournisseur uuid;
  v_commande public.filed_commandes;
  v_cmd_lue text := left(nullif(btrim(p_donnees ->> 'commande'), ''), 100);
  v_lignes jsonb := case when jsonb_typeof(p_donnees -> 'lignes') = 'array' then p_donnees -> 'lignes' else '[]'::jsonb end;
begin
  v_fournisseur := private.filed_fournisseur_du_bon(p_client, p_donnees, p_source, p_document);

  -- La commande : désignée, sinon citée ; d'abord celle de la société, sinon celle du fournisseur.
  if coalesce(p_donnees ->> 'commande_id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select * into v_commande from public.filed_commandes
    where client_id = p_client and id = (p_donnees ->> 'commande_id')::uuid;
    if v_commande.id is null then
      raise exception 'Commande introuvable dans cette organisation.' using errcode = 'P0002';
    end if;
  elsif private.filed_normaliser_numero(v_cmd_lue) is not null then
    select c.* into v_commande from public.filed_commandes c
    where c.client_id = p_client and c.numero_normalise = private.filed_normaliser_numero(v_cmd_lue)
      and c.statut <> 'annulee'
      and (v_fournisseur is null or c.fournisseur_id is null or c.fournisseur_id = v_fournisseur)
    order by (c.entite_id = p_entite) desc, (c.fournisseur_id = v_fournisseur) desc nulls last, c.cree_le desc
    limit 1;
  end if;
  if v_fournisseur is null and v_commande.id is not null then
    v_fournisseur := v_commande.fournisseur_id;
  end if;

  if p_document is not null then
    select * into v_r from public.filed_receptions where document_id = p_document for update;
  end if;
  if v_r.id is null then
    insert into public.filed_receptions (client_id, entite_id, document_id, commande_id, fournisseur_id, numero, numero_normalise,
                                         date_reception, source, commande_lue, fournisseur_lu, note, cree_par)
    values (p_client, p_entite, p_document, v_commande.id, v_fournisseur, v_numero, private.filed_normaliser_numero(v_numero),
            private.filed_date(p_donnees -> 'date'), p_source, v_cmd_lue, coalesce(p_donnees -> 'fournisseur', '{}'::jsonb),
            left(nullif(btrim(p_donnees ->> 'note'), ''), 500), p_par)
    returning * into v_r;
    perform private.filed_historiser(p_client, p_document, 'filed_reception', v_r.id::text, 'creee',
      format('Réception %s%s, %s%s.', coalesce(v_numero, 'sans numéro'),
             coalesce(' du ' || to_char(v_r.date_reception, 'DD/MM/YYYY'), ''),
             case p_source when 'piece' then 'lue sur un bon de livraison' else 'saisie par une personne' end,
             case when v_commande.id is not null then ' pour la commande ' || v_commande.numero
                  when v_cmd_lue is not null then ' pour une commande inconnue (' || v_cmd_lue || ')' else '' end),
      jsonb_build_object('source', p_source, 'document', p_document, 'commande', v_commande.id));
  else
    update public.filed_receptions
       set commande_id = coalesce(v_commande.id, commande_id), fournisseur_id = coalesce(v_fournisseur, fournisseur_id),
           numero = coalesce(v_numero, numero), numero_normalise = coalesce(private.filed_normaliser_numero(v_numero), numero_normalise),
           date_reception = coalesce(private.filed_date(p_donnees -> 'date'), date_reception),
           commande_lue = coalesce(v_cmd_lue, commande_lue), maj_le = now()
     where id = v_r.id
    returning * into v_r;
  end if;

  delete from public.filed_receptions_lignes where reception_id = v_r.id;
  insert into public.filed_receptions_lignes (client_id, reception_id, commande_ligne_id, rang, reference, designation,
                                              designation_normalisee, quantite, unite, methode, source)
  select p_client, v_r.id, c.id, e.rang::smallint, left(private.filed_texte(e.l -> 'reference'), 100),
         left(private.filed_texte(e.l -> 'designation'), 500), private.filed_normaliser(private.filed_texte(e.l -> 'designation')),
         coalesce(private.filed_nombre(e.l -> 'quantite'), 0), left(private.filed_texte(e.l -> 'unite'), 20),
         case when c.id is not null then 'commande_ligne' end,
         case when p_source = 'piece' and coalesce(p_donnees ->> 'lignes_source', '') in ('xml', 'regle', 'ia', 'humain', 'tableur')
              then p_donnees ->> 'lignes_source' when p_source = 'piece' then 'regle' else p_source end
  from jsonb_array_elements(v_lignes) with ordinality as e(l, rang)
  left join public.filed_commandes_lignes c
    on c.commande_id = v_r.commande_id and private.filed_texte(e.l -> 'commande_ligne') is not null
   and (c.rang::text = private.filed_texte(e.l -> 'commande_ligne')
        or private.filed_normaliser_numero(c.numero) = private.filed_normaliser_numero(private.filed_texte(e.l -> 'commande_ligne')))
  where e.rang <= 5000 and jsonb_typeof(e.l) = 'object';
  perform private.filed_apparier_reception(v_r.id);
  perform private.filed_recontroler_reception(v_r.id);
  return v_r;
end $_$;


--
-- Name: filed_enregistrer_commande(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_enregistrer_commande(p_client uuid, p_entite uuid, p_commande jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entite uuid := coalesce(p_entite, private.filed_entite_de(p_client, '{}'::jsonb));
  v_c public.filed_commandes;
begin
  perform private.filed_exiger_acteur(p_client, array['gerant', 'admin', 'valideur', 'collaborateur'], v_entite);
  v_c := private.filed_ecrire_commande(p_client, v_entite, 'saisie', p_commande, null, (select auth.uid()));
  return v_c.id;
end $$;


--
-- Name: filed_enregistrer_reception(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_enregistrer_reception(p_client uuid, p_entite uuid, p_reception jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entite uuid := coalesce(p_entite, private.filed_entite_de(p_client, '{}'::jsonb));
  v_r public.filed_receptions;
begin
  perform private.filed_exiger_acteur(p_client, array['gerant', 'admin', 'valideur', 'collaborateur'], v_entite);
  if jsonb_typeof(p_reception -> 'lignes') is distinct from 'array' or jsonb_array_length(p_reception -> 'lignes') = 0 then
    raise exception 'Une réception dit ce qui a été reçu : au moins une ligne.' using errcode = '22023';
  end if;
  v_r := private.filed_ecrire_reception(p_client, v_entite, 'saisie', p_reception, null, (select auth.uid()));
  return v_r.id;
end $$;


--
-- Name: filed_entite_de(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_entite_de(p_client uuid, p_donnees jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id uuid;
begin
  if coalesce(p_donnees ->> 'entite', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select e.id into v_id from public.entites e where e.client_id = p_client and e.id = (p_donnees ->> 'entite')::uuid;
  elsif nullif(btrim(p_donnees ->> 'entite_siren'), '') is not null then
    select e.id into v_id from public.entites e where e.client_id = p_client and e.siren = btrim(p_donnees ->> 'entite_siren');
  else
    select e.id into v_id from public.entites e where e.client_id = p_client and e.principale;
  end if;
  if v_id is null then
    raise exception 'Société introuvable dans cette organisation.' using errcode = 'P0002';
  end if;
  return v_id;
end $_$;


--
-- Name: filed_etat_de(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_etat_de(p_nature text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_nature is null then 'a_classer'
    when p_nature in ('facture', 'avoir', 'bon_commande', 'bon_livraison') then 'a_traiter'
    else 'classe'
  end
$$;


--
-- Name: filed_executer_decision(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_executer_decision(p_charge jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_d public.demandes_validation;
  v_decideur uuid;
  v_commentaire text;
  v_four public.filed_fournisseurs;
  v_ib public.filed_fournisseurs_ibans;
  r record;
begin
  if coalesce(p_charge ->> 'demande', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return 'sans_demande';
  end if;
  select * into v_d from public.demandes_validation where id = (p_charge ->> 'demande')::uuid for update;
  if not found then
    return 'demande_effacee';
  end if;
  if v_d.module <> 'filed' then
    return 'autre_module';
  end if;
  if v_d.statut not in ('approuvee', 'rejetee', 'expiree') then
    return 'deja_traitee';
  end if;
  select a.user_id, a.commentaire into v_decideur, v_commentaire from public.approbations a
  where a.demande_id = v_d.id order by a.decide_le desc limit 1;

  if v_d.type_action = 'filed.valider_fournisseur' then
    select * into v_four from public.filed_fournisseurs
    where client_id = v_d.client_id and id::text = v_d.objet_id for update;
    if not found then
      return 'fournisseur_efface';
    end if;
    if v_d.statut = 'approuvee' and v_d.politique_id is not null then
      -- Ne doit jamais arriver (actions_sans_accord) : la base le refuse encore ici.
      update public.demandes_validation set statut = 'echec_execution',
             motif_echec = 'Un fournisseur nouveau n''est jamais validé d''office par un accord permanent.' where id = v_d.id;
      return 'refuse_accord';
    end if;
    if v_d.statut = 'approuvee' then
      if v_four.statut = 'a_confirmer' then
        update public.filed_fournisseurs set statut = 'actif', confirme_le = now(), confirme_par = v_decideur, maj_le = now()
        where id = v_four.id;
        -- L'IBAN que la personne a vu dans la demande se valide avec le fournisseur.
        update public.filed_fournisseurs_ibans set statut = 'valide', decide_le = now(), decide_par = v_decideur
        where fournisseur_id = v_four.id and statut = 'propose'
          and empreinte = v_d.payload ->> 'iban_empreinte';
        -- Un autre IBAN proposé entre-temps part, lui, à la file.
        for r in select i.id, i.iban_masque from public.filed_fournisseurs_ibans i
                 where i.fournisseur_id = v_four.id and i.statut = 'propose'
        loop
          perform private.filed_deposer_demande(v_four.client_id, null, 'filed.valider_iban', 'filed_iban', r.id::text,
            format('Nouvel IBAN pour %s : %s', private.filed_libelle_fournisseur(v_four), r.iban_masque), null,
            jsonb_build_object('fournisseur', v_four.id, 'iban', r.iban_masque), 'filed:iban:' || r.id::text);
        end loop;
        perform private.filed_historiser(v_four.client_id, null, 'filed_fournisseur', v_four.id::text, 'confirme',
          'Fournisseur confirmé par une personne.', jsonb_build_object('demande', v_d.id, 'par', v_decideur));
      end if;
      update public.demandes_validation set statut = 'executee' where id = v_d.id;
      perform private.filed_recontroler_fournisseur(v_four.id);
      return 'fournisseur_confirme';
    elsif v_d.statut = 'rejetee' then
      update public.filed_fournisseurs set statut = 'refuse', motif = left(coalesce(v_commentaire, 'Refusé par une personne.'), 500),
             confirme_le = now(), confirme_par = v_decideur, maj_le = now()
      where id = v_four.id;
      update public.filed_fournisseurs_ibans set statut = 'refuse', decide_le = now(), decide_par = v_decideur,
             motif = 'Refusé avec le fournisseur.'
      where fournisseur_id = v_four.id and statut = 'propose';
      perform private.lever_alerte_module(v_four.client_id, 'filed', 'critique',
        left(format('Fournisseur refusé : %s. Ses factures restent bloquées.', v_four.nom), 200),
        jsonb_build_object('fournisseur', v_four.id, 'demande', v_d.id), 'fournisseur_refuse:' || v_four.id::text, true, null);
      perform private.filed_historiser(v_four.client_id, null, 'filed_fournisseur', v_four.id::text, 'refuse',
        'Fournisseur refusé par une personne' || coalesce(' : ' || v_commentaire, '.'), jsonb_build_object('demande', v_d.id));
      perform private.filed_recontroler_fournisseur(v_four.id);
      return 'fournisseur_refuse';
    end if;
    return 'expiree';
  end if;

  if v_d.type_action = 'filed.valider_iban' then
    select * into v_ib from public.filed_fournisseurs_ibans
    where client_id = v_d.client_id and id::text = v_d.objet_id for update;
    if not found then
      return 'iban_efface';
    end if;
    if v_d.statut = 'approuvee' and v_d.politique_id is not null then
      update public.demandes_validation set statut = 'echec_execution',
             motif_echec = 'Un IBAN nouveau n''est jamais validé d''office par un accord permanent.' where id = v_d.id;
      return 'refuse_accord';
    end if;
    if v_d.statut = 'approuvee' then
      if v_ib.statut = 'propose' then
        update public.filed_fournisseurs_ibans set statut = 'valide', decide_le = now(), decide_par = v_decideur
        where id = v_ib.id;
        perform private.filed_historiser(v_ib.client_id, null, 'filed_fournisseur', v_ib.fournisseur_id::text, 'iban_valide',
          format('IBAN %s validé par une personne.', v_ib.iban_masque), jsonb_build_object('demande', v_d.id, 'par', v_decideur));
      end if;
      update public.demandes_validation set statut = 'executee' where id = v_d.id;
      perform private.filed_recontroler_fournisseur(v_ib.fournisseur_id);
      return 'iban_valide';
    elsif v_d.statut = 'rejetee' then
      update public.filed_fournisseurs_ibans set statut = 'refuse', decide_le = now(), decide_par = v_decideur,
             motif = left(coalesce(v_commentaire, 'Refusé par une personne.'), 500)
      where id = v_ib.id;
      select * into v_four from public.filed_fournisseurs where id = v_ib.fournisseur_id;
      perform private.lever_alerte_module(v_ib.client_id, 'filed', 'critique',
        left(format('Changement d''IBAN refusé pour %s : tentative de fraude possible.', v_four.nom), 200),
        jsonb_build_object('fournisseur', v_four.id, 'iban', v_ib.iban_masque, 'demande', v_d.id),
        'iban_refuse:' || v_ib.id::text, true, null);
      perform private.filed_historiser(v_ib.client_id, null, 'filed_fournisseur', v_ib.fournisseur_id::text, 'iban_refuse',
        format('IBAN %s refusé par une personne', v_ib.iban_masque) || coalesce(' : ' || v_commentaire, '.'),
        jsonb_build_object('demande', v_d.id));
      perform private.filed_recontroler_fournisseur(v_ib.fournisseur_id);
      return 'iban_refuse';
    end if;
    return 'expiree';
  end if;

  return 'type_inconnu';
end $_$;


--
-- Name: filed_exiger_acteur(uuid, text[], uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_exiger_acteur(p_client uuid, p_roles text[], p_entite uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
begin
  if v_uid is not null then
    if not exists (select 1 from public.comptes c
                   where c.user_id = v_uid and c.client_id = p_client and c.role = any (p_roles)) then
      raise exception 'Votre rôle ne permet pas ce geste dans FILED.' using errcode = '42501';
    end if;
    if p_entite is not null and not private.perimetre_couvre(v_uid, p_client, p_entite) then
      raise exception 'Cette société est hors de votre périmètre.' using errcode = '42501';
    end if;
    return v_uid;
  end if;
  if v_role = 'service_role' then
    return null;
  end if;
  raise exception 'Seule une personne de l''organisation, ou le serveur, agit dans FILED.' using errcode = '42501';
end $$;


--
-- Name: filed_factures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_factures (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid NOT NULL,
    document_id uuid NOT NULL,
    nature text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    numero text,
    numero_normalise text,
    date_emission date,
    date_reception date NOT NULL,
    echeance_lue date,
    devise text DEFAULT 'EUR'::text NOT NULL,
    montant_ht numeric(14,2),
    montant_tva numeric(14,2),
    montant_ttc numeric(14,2),
    net_a_payer numeric(14,2),
    montant_prepaye numeric(14,2),
    montants_calcules text[] DEFAULT '{}'::text[] NOT NULL,
    type_code text,
    cadre_facturation text,
    regime_tva text,
    fournisseur_id uuid,
    fournisseur_identification text,
    fournisseur_force uuid,
    fournisseur_lu jsonb DEFAULT '{}'::jsonb NOT NULL,
    acheteur_lu jsonb DEFAULT '{}'::jsonb NOT NULL,
    iban text,
    refs jsonb DEFAULT '{}'::jsonb NOT NULL,
    mentions jsonb DEFAULT '{}'::jsonb NOT NULL,
    champs_douteux jsonb DEFAULT '[]'::jsonb NOT NULL,
    empreinte_donnees text,
    statut text DEFAULT 'a_completer'::text NOT NULL,
    doublon_de uuid,
    anomalies text[] DEFAULT '{}'::text[] NOT NULL,
    nb_bloquants smallint DEFAULT 0 NOT NULL,
    nb_attention smallint DEFAULT 0 NOT NULL,
    controle_le timestamp with time zone,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    commande_id uuid,
    commande_force uuid,
    avoir_de uuid,
    CONSTRAINT filed_factures_cadre_facturation_check CHECK ((char_length(cadre_facturation) <= 10)),
    CONSTRAINT filed_factures_devise_check CHECK ((devise ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT filed_factures_fournisseur_identification_check CHECK ((fournisseur_identification = ANY (ARRAY['siren'::text, 'tva'::text, 'id_etranger'::text, 'nom'::text, 'creation'::text, 'humain'::text]))),
    CONSTRAINT filed_factures_iban_check CHECK ((iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$'::text)),
    CONSTRAINT filed_factures_nature_check CHECK ((nature = ANY (ARRAY['facture'::text, 'avoir'::text]))),
    CONSTRAINT filed_factures_numero_check CHECK ((char_length(numero) <= 60)),
    CONSTRAINT filed_factures_regime_tva_check CHECK ((regime_tva = ANY (ARRAY['normal'::text, 'mixte'::text, 'autoliquidation'::text, 'intracom'::text, 'hors_ue'::text, 'franchise'::text, 'exonere'::text, 'sans_tva'::text]))),
    CONSTRAINT filed_factures_statut_check CHECK ((statut = ANY (ARRAY['a_completer'::text, 'bloquee'::text, 'a_valider'::text, 'ecartee'::text]))),
    CONSTRAINT filed_factures_type_code_check CHECK ((char_length(type_code) <= 10)),
    CONSTRAINT filed_factures_version_check CHECK ((version >= 1))
);


--
-- Name: filed_exiger_facture(uuid, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_exiger_facture(p_facture uuid, p_roles text[]) RETURNS public.filed_factures
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_f public.filed_factures;
begin
  select * into v_f from public.filed_factures where id = p_facture;
  if not found then
    raise exception 'Facture introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_f.client_id, p_roles, v_f.entite_id);
  if (select auth.uid()) is not null
     and not private.voit_objet(v_f.client_id, 'filed_document', v_f.document_id::text) then
    raise exception 'Facture introuvable.' using errcode = 'P0002';
  end if;
  if v_f.statut not in ('a_completer', 'bloquee', 'a_valider', 'ecartee') then
    raise exception 'Cette facture est décidée (%) : elle ne se corrige plus.', v_f.statut using errcode = '55000';
  end if;
  return v_f;
end $$;


--
-- Name: filed_fournisseur_du_bon(uuid, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_fournisseur_du_bon(p_client uuid, p_donnees jsonb, p_source text, p_document uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_id uuid;
  v_ident jsonb := coalesce(p_donnees -> 'fournisseur', '{}'::jsonb);
  v_f public.filed_fournisseurs;
begin
  if coalesce(p_donnees ->> 'fournisseur_id', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select f.id into v_id from public.filed_fournisseurs f
    where f.client_id = p_client and f.id = (p_donnees ->> 'fournisseur_id')::uuid;
    if v_id is null then
      raise exception 'Fournisseur introuvable dans cette organisation.' using errcode = 'P0002';
    end if;
    return v_id;
  end if;
  if nullif(btrim(p_donnees ->> 'fournisseur_code'), '') is not null then
    select f.id into v_id from public.filed_fournisseurs f
    where f.client_id = p_client and f.code = upper(btrim(p_donnees ->> 'fournisseur_code'));
    if v_id is null then
      raise exception 'Fournisseur au code « % » introuvable.', upper(btrim(p_donnees ->> 'fournisseur_code')) using errcode = 'P0002';
    end if;
    return v_id;
  end if;
  if jsonb_typeof(v_ident) <> 'object' or v_ident = '{}'::jsonb then
    return null;
  end if;
  v_id := private.filed_reconnaitre_fournisseur(p_client, v_ident);
  if v_id is null and p_source = 'piece' and (v_ident ? 'siren' or v_ident ? 'tva' or v_ident ? 'id_etranger') then
    perform pg_advisory_xact_lock(hashtextextended('filed.fournisseur:' || p_client::text, 0));
    v_id := private.filed_reconnaitre_fournisseur(p_client, v_ident);
    if v_id is null then
      v_f := private.filed_creer_fournisseur(p_client, v_ident - 'iban', 'piece', p_document);
      v_id := v_f.id;
    end if;
  elsif v_id is null and p_source <> 'piece' then
    raise exception 'Fournisseur inconnu : donnez son code, ou son SIREN s''il est au référentiel.' using errcode = 'P0002';
  end if;
  return v_id;
end $_$;


--
-- Name: filed_historique_immuable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_historique_immuable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and (
       old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '')
       or coalesce(current_setting('omega.effacement_objet', true), '') = 'oui') then
    return old;
  end if;
  raise exception 'L''historique d''un document ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: filed_historiser(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_historiser(p_client uuid, p_document uuid, p_objet_type text, p_objet_id text, p_etape text, p_message text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_acteur record;
begin
  select * into v_acteur from private.acteur_courant();
  insert into public.filed_historique (client_id, document_id, objet_type, objet_id, etape, message, detail,
                                       acteur_type, acteur_id, acteur_libelle)
  values (p_client, p_document, p_objet_type, p_objet_id, p_etape, left(p_message, 500), coalesce(p_detail, '{}'::jsonb),
          v_acteur.acteur_type, v_acteur.acteur_id,
          case when v_acteur.acteur_type = 'systeme' then 'FILED' else v_acteur.acteur_libelle end);
end $$;


--
-- Name: filed_iban_valide(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_iban_valide(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v text := upper(regexp_replace(coalesce(p, ''), '\s', '', 'g'));
  r text;
  c text;
  n integer := 0;
begin
  if v !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$' or (left(v, 2) = 'FR' and length(v) <> 27) then
    return false;
  end if;
  r := substr(v, 5) || left(v, 4);
  for i in 1 .. length(r) loop
    c := substr(r, i, 1);
    if c between '0' and '9' then
      n := (n * 10 + c::integer) % 97;
    else
      n := (n * 100 + ascii(c) - 55) % 97;
    end if;
  end loop;
  return n = 1;
end $_$;


--
-- Name: filed_identite_lue(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_identite_lue(p_v jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_siren text;
  v_siret text;
  v_tva text;
begin
  if coalesce((p_v -> 'fournisseur.siren' ->> 'sure')::boolean, false)
     and private.filed_siren_valide(private.filed_texte(p_v -> 'fournisseur.siren' -> 'valeur')) then
    v_siren := private.filed_texte(p_v -> 'fournisseur.siren' -> 'valeur');
  end if;
  if coalesce((p_v -> 'fournisseur.siret' ->> 'sure')::boolean, false)
     and private.filed_texte(p_v -> 'fournisseur.siret' -> 'valeur') ~ '^[0-9]{14}$' then
    v_siret := private.filed_texte(p_v -> 'fournisseur.siret' -> 'valeur');
    if v_siren is null and private.filed_siren_valide(left(v_siret, 9)) then
      v_siren := left(v_siret, 9);
    end if;
  end if;
  if coalesce((p_v -> 'fournisseur.tva' ->> 'sure')::boolean, false) then
    v_tva := upper(regexp_replace(coalesce(private.filed_texte(p_v -> 'fournisseur.tva' -> 'valeur'), ''), '[\s.\-]', '', 'g'));
    if v_tva !~ '^[A-Z]{2}[0-9A-Z]{2,13}$' or (v_tva like 'FR%' and not private.filed_tva_fr_valide(v_tva)) then
      v_tva := null;
    end if;
    if v_siren is null and v_tva like 'FR%' then
      v_siren := right(v_tva, 9);
    end if;
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'nom', left(private.filed_texte(p_v -> 'fournisseur.nom' -> 'valeur'), 200),
    'siren', v_siren, 'siret', v_siret, 'tva', v_tva,
    'pays', case when upper(private.filed_texte(p_v -> 'fournisseur.pays' -> 'valeur')) ~ '^[A-Z]{2}$'
                 then upper(private.filed_texte(p_v -> 'fournisseur.pays' -> 'valeur')) end));
end $_$;


--
-- Name: filed_immuable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_immuable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and (
       old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '')
       or coalesce(current_setting('omega.effacement_objet', true), '') = 'oui') then
    return old;
  end if;
  raise exception 'Cette trace ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: filed_importer_commandes(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_importer_commandes(p_client uuid, p_commandes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  x jsonb;
  v_rang integer := 0;
  v_ecrites integer := 0;
  v_refus jsonb := '[]'::jsonb;
  v_entite uuid;
begin
  perform private.filed_exiger_acteur(p_client, array['gerant', 'admin'], null);
  if jsonb_typeof(p_commandes) is distinct from 'array' then
    raise exception 'Une liste de commandes est attendue.' using errcode = '22023';
  end if;
  for x in select * from jsonb_array_elements(p_commandes) loop
    v_rang := v_rang + 1;
    begin
      v_entite := private.filed_entite_de(p_client, x);
      perform private.filed_ecrire_commande(p_client, v_entite, 'import', x, null, (select auth.uid()));
      v_ecrites := v_ecrites + 1;
    exception when others then
      v_refus := v_refus || jsonb_build_object('rang', v_rang, 'numero', x ->> 'numero', 'motif', left(sqlerrm, 200));
    end;
  end loop;
  perform private.filed_journaliser(p_client, 'filed.import_commandes', 'filed_commandes', p_client::text,
    jsonb_build_object('ecrites', v_ecrites, 'refusees', jsonb_array_length(v_refus)));
  return jsonb_build_object('ecrites', v_ecrites, 'refusees', v_refus);
end $$;


--
-- Name: filed_importer_fournisseurs(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_importer_fournisseurs(p_client uuid, p_fournisseurs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  x jsonb;
  v_rang integer := 0;
  v_siren text;
  v_tva text;
  v_etr text;
  v_iban text;
  v_nom text;
  v_f public.filed_fournisseurs;
  v_crees integer := 0;
  v_connus integer := 0;
  v_ibans integer := 0;
  v_refus jsonb := '[]'::jsonb;
begin
  perform private.filed_exiger_acteur(p_client, array['gerant', 'admin'], null);
  if jsonb_typeof(p_fournisseurs) is distinct from 'array' then
    raise exception 'Une liste de fournisseurs est attendue.' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('filed.fournisseur:' || p_client::text, 0));
  for x in select * from jsonb_array_elements(p_fournisseurs) loop
    v_rang := v_rang + 1;
    v_nom := nullif(btrim(x ->> 'nom'), '');
    v_siren := nullif(regexp_replace(coalesce(x ->> 'siren', ''), '\s', '', 'g'), '');
    v_tva := nullif(upper(regexp_replace(coalesce(x ->> 'tva', ''), '[\s.\-]', '', 'g')), '');
    v_etr := nullif(btrim(x ->> 'id_etranger'), '');
    v_iban := nullif(upper(regexp_replace(coalesce(x ->> 'iban', ''), '\s', '', 'g')), '');
    if v_nom is null then
      v_refus := v_refus || jsonb_build_object('rang', v_rang, 'motif', 'nom absent');
      continue;
    end if;
    if v_siren is not null and not private.filed_siren_valide(v_siren) then
      v_refus := v_refus || jsonb_build_object('rang', v_rang, 'nom', v_nom, 'motif', 'SIREN à la clé fausse');
      continue;
    end if;
    if v_tva is not null and (v_tva !~ '^[A-Z]{2}[0-9A-Z]{2,13}$' or (v_tva like 'FR%' and not private.filed_tva_fr_valide(v_tva))) then
      v_refus := v_refus || jsonb_build_object('rang', v_rang, 'nom', v_nom, 'motif', 'numéro de TVA faux');
      continue;
    end if;
    if v_iban is not null and not private.filed_iban_valide(v_iban) then
      v_refus := v_refus || jsonb_build_object('rang', v_rang, 'nom', v_nom, 'motif', 'IBAN à la clé fausse');
      continue;
    end if;
    if v_siren is null and v_tva like 'FR%' then
      v_siren := right(v_tva, 9);
    end if;
    v_f := null;
    select * into v_f from public.filed_fournisseurs f
    where f.client_id = p_client
      and ((v_siren is not null and f.siren = v_siren) or (v_tva is not null and f.tva = v_tva)
           or (v_etr is not null and f.id_etranger = v_etr)
           or (nullif(upper(btrim(x ->> 'code')), '') is not null and f.code = upper(btrim(x ->> 'code'))))
    limit 1;
    begin
      if v_f.id is null then
        v_f := private.filed_creer_fournisseur(p_client, jsonb_strip_nulls(jsonb_build_object(
          'nom', v_nom, 'siren', v_siren, 'siret', nullif(regexp_replace(coalesce(x ->> 'siret', ''), '\s', '', 'g'), ''),
          'tva', v_tva, 'id_etranger', v_etr, 'pays', nullif(upper(btrim(x ->> 'pays')), ''),
          'code', nullif(upper(btrim(x ->> 'code')), ''), 'regime_tva', nullif(x ->> 'regime_tva', ''))), 'import', null);
        v_crees := v_crees + 1;
      else
        v_connus := v_connus + 1;
      end if;
      if v_iban is not null then
        perform private.filed_proposer_iban(v_f.id, v_iban, 'import', null, 'Repris du référentiel de l''organisation');
        v_ibans := v_ibans + 1;
      end if;
    exception when others then
      -- Une ligne qui ne s'écrit pas (code déjà pris, valeur hors format) est refusée seule.
      v_refus := v_refus || jsonb_build_object('rang', v_rang, 'nom', v_nom, 'motif', left(sqlerrm, 200));
    end;
  end loop;
  perform private.filed_journaliser(p_client, 'filed.import_fournisseurs', 'filed_fournisseurs', p_client::text,
    jsonb_build_object('crees', v_crees, 'connus', v_connus, 'ibans', v_ibans, 'refuses', jsonb_array_length(v_refus)));
  return jsonb_build_object('crees', v_crees, 'connus', v_connus, 'ibans', v_ibans, 'refuses', v_refus);
end $_$;


--
-- Name: filed_installer(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_installer(p_client uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_fuseau text;
begin
  perform private.filed_exiger_acteur(p_client, array[]::text[]);  -- le serveur seul
  if not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  insert into public.filed_reglages (client_id, entite_id, actif) values (p_client, null, true)
  on conflict (client_id, entite_id) do update set actif = true, maj_le = now()
  returning id into v_id;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.principale;
  -- Chaque moteur bat toutes les cinq minutes au plus : trente minutes de silence lèvent l'alerte.
  perform private.regler_battement(p_client, 'filed_reception', interval '30 minutes', null, coalesce(v_fuseau, 'Europe/Paris'));
  perform private.regler_battement(p_client, 'filed_factures', interval '30 minutes', null, coalesce(v_fuseau, 'Europe/Paris'));
  perform private.filed_journaliser(p_client, 'filed.installation', 'filed_reglages', v_id::text, '{}'::jsonb);
  return v_id;
end $$;


--
-- Name: filed_integrer_commande(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_integrer_commande(p_document uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_doc public.filed_documents;
  v jsonb;
  v_c public.filed_commandes;
begin
  select * into v_doc from public.filed_documents where id = p_document for update;
  if not found or v_doc.nature <> 'bon_commande' then
    return 'hors_commande';
  end if;
  v := private.filed_valeurs(v_doc.piece_id);
  if private.filed_texte(v -> 'numero' -> 'valeur') is null then
    perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'a_completer',
      'Bon de commande sans numéro lisible : une personne le complète.', '{}'::jsonb);
    return 'sans_numero';
  end if;
  v_c := private.filed_ecrire_commande(v_doc.client_id, v_doc.entite_id, 'piece', jsonb_strip_nulls(jsonb_build_object(
    'numero', private.filed_texte(v -> 'numero' -> 'valeur'),
    'date', v -> 'date' -> 'valeur',
    'fournisseur', private.filed_identite_lue(v),
    'lignes', v -> 'lignes' -> 'valeur',
    'lignes_source', v -> 'lignes' ->> 'source')), v_doc.id, null);
  update public.filed_documents set etat = 'integre', traite_le = now() where id = v_doc.id and etat <> 'integre';
  perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'integree',
    format('Bon de commande %s : commande %s, %s ligne(s).', v_c.numero, v_c.id,
           (select count(*) from public.filed_commandes_lignes l where l.commande_id = v_c.id)),
    jsonb_build_object('commande', v_c.id));
  return 'commande:' || v_c.id::text;
end $$;


--
-- Name: filed_integrer_facture(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_integrer_facture(p_document uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_doc public.filed_documents;
  v_f public.filed_factures;
  v jsonb;
  v_ent public.entites;
  v_numero text;
  v_date date;
  v_ech date;
  v_devise text;
  v_ht numeric;
  v_tva numeric;
  v_ttc numeric;
  v_net numeric;
  v_prep numeric;
  v_calcules text[] := '{}';
  v_siren text;
  v_siret text;
  v_tva_four text;
  v_four jsonb;
  v_ach jsonb;
  v_ach_siren text;
  v_iban text;
  v_refs jsonb;
  v_mentions jsonb;
  v_douteux jsonb;
  v_empreinte text;
  v_nouvelle boolean := false;
  v_changee boolean := false;
  v_statut text;
begin
  select * into v_doc from public.filed_documents where id = p_document for update;
  if not found or v_doc.nature not in ('facture', 'avoir') then
    return 'hors_facture';
  end if;
  select * into v_f from public.filed_factures where document_id = p_document for update;
  if found and v_f.statut not in ('a_completer', 'bloquee', 'a_valider', 'ecartee') then
    perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'relue_sans_effet',
      'Relue : la facture est déjà décidée, sa lecture ne la change plus.', jsonb_build_object('statut', v_f.statut));
    return v_f.statut;
  end if;
  select * into v_ent from public.entites where id = v_doc.entite_id;

  v := private.filed_valeurs(v_doc.piece_id);

  v_numero := left(private.filed_texte(v -> 'numero' -> 'valeur'), 60);
  v_date := private.filed_date(v -> 'date' -> 'valeur');
  v_ech := private.filed_date(v -> 'echeance' -> 'valeur');
  v_devise := upper(coalesce(private.filed_texte(v -> 'devise' -> 'valeur'), 'EUR'));
  if v_devise !~ '^[A-Z]{3}$' then
    v_devise := 'EUR';
  end if;
  v_ht := private.filed_nombre(v -> 'montant_ht' -> 'valeur');
  v_tva := private.filed_nombre(v -> 'montant_tva' -> 'valeur');
  v_ttc := private.filed_nombre(v -> 'montant_ttc' -> 'valeur');
  v_net := private.filed_nombre(v -> 'net_a_payer' -> 'valeur');
  v_prep := private.filed_nombre(v -> 'montant_prepaye' -> 'valeur');
  if v_doc.nature = 'avoir' then
    -- Un avoir se garde en montants positifs : son sens est dans sa nature.
    v_ht := abs(v_ht); v_tva := abs(v_tva); v_ttc := abs(v_ttc); v_net := abs(v_net);
  end if;

  v_mentions := jsonb_strip_nulls(jsonb_build_object(
    'autoliquidation', coalesce(private.filed_booleen(v -> 'mention.autoliquidation' -> 'valeur'),
                                case when exists (select 1 from public.pieces_pages pg where pg.piece_id = v_doc.piece_id
                                                  and private.filed_normaliser(pg.texte) ~ '\mauto ?liquidation\M') then true end),
    'franchise_293b', coalesce(private.filed_booleen(v -> 'mention.franchise_293b' -> 'valeur'),
                               case when exists (select 1 from public.pieces_pages pg where pg.piece_id = v_doc.piece_id
                                                 and private.filed_normaliser(pg.texte) ~ '\m293 ?b\M') then true end)));

  -- Les montants que la pièce ne donne pas, et qui se déduisent des autres.
  if v_tva is null and v_ht is not null and v_ttc is not null and v_ht = v_ttc then
    v_tva := 0; v_calcules := array_append(v_calcules, 'TVA nulle (HT égal au TTC)');
  elsif v_tva is null and v_ttc is not null
        and (coalesce((v_mentions ->> 'franchise_293b')::boolean, false) or coalesce((v_mentions ->> 'autoliquidation')::boolean, false)) then
    v_tva := 0; v_calcules := array_append(v_calcules, 'TVA nulle (mention sur la pièce)');
  end if;
  if v_ht is null and v_tva is not null and v_ttc is not null then
    v_ht := v_ttc - v_tva; v_calcules := array_append(v_calcules, 'HT = TTC − TVA');
  end if;

  -- L'identité du fournisseur : seules les valeurs sûres (vérifiées par le code,
  -- ou saisies par une personne) servent à le reconnaître.
  if coalesce((v -> 'fournisseur.siren' ->> 'sure')::boolean, false)
     and private.filed_siren_valide(private.filed_texte(v -> 'fournisseur.siren' -> 'valeur')) then
    v_siren := private.filed_texte(v -> 'fournisseur.siren' -> 'valeur');
  end if;
  if coalesce((v -> 'fournisseur.siret' ->> 'sure')::boolean, false)
     and private.filed_texte(v -> 'fournisseur.siret' -> 'valeur') ~ '^[0-9]{14}$' then
    v_siret := private.filed_texte(v -> 'fournisseur.siret' -> 'valeur');
    if v_siren is null and private.filed_siren_valide(left(v_siret, 9)) then
      v_siren := left(v_siret, 9);
    end if;
  end if;
  if coalesce((v -> 'fournisseur.tva' ->> 'sure')::boolean, false) then
    v_tva_four := upper(regexp_replace(coalesce(private.filed_texte(v -> 'fournisseur.tva' -> 'valeur'), ''), '[\s.\-]', '', 'g'));
    if v_tva_four !~ '^[A-Z]{2}[0-9A-Z]{2,13}$' or (v_tva_four like 'FR%' and not private.filed_tva_fr_valide(v_tva_four)) then
      v_tva_four := null;
    end if;
    if v_siren is null and v_tva_four like 'FR%' then
      v_siren := right(v_tva_four, 9);
    end if;
  end if;
  v_four := jsonb_strip_nulls(jsonb_build_object(
    'nom', left(private.filed_texte(v -> 'fournisseur.nom' -> 'valeur'), 200),
    'siren', v_siren, 'siret', v_siret, 'tva', v_tva_four,
    'id_etranger', case when v_siren is null and v_tva_four is null
                        then left(private.filed_texte(v -> 'fournisseur.id_legal' -> 'valeur'), 60) end,
    'pays', upper(nullif(private.filed_texte(v -> 'fournisseur.pays' -> 'valeur'), ''))));
  if v_four ? 'pays' and (v_four ->> 'pays') !~ '^[A-Z]{2}$' then
    v_four := v_four - 'pays';
  end if;

  v_iban := upper(regexp_replace(coalesce(private.filed_texte(v -> 'fournisseur.iban' -> 'valeur'), ''), '\s', '', 'g'));
  if v_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$' then
    v_iban := null;
  end if;

  if coalesce((v -> 'acheteur.siren' ->> 'sure')::boolean, false)
     and private.filed_siren_valide(private.filed_texte(v -> 'acheteur.siren' -> 'valeur')) then
    v_ach_siren := private.filed_texte(v -> 'acheteur.siren' -> 'valeur');
  elsif coalesce((v -> 'acheteur.siret' ->> 'sure')::boolean, false)
        and private.filed_siren_valide(left(private.filed_texte(v -> 'acheteur.siret' -> 'valeur'), 9)) then
    v_ach_siren := left(private.filed_texte(v -> 'acheteur.siret' -> 'valeur'), 9);
  elsif coalesce((v -> 'acheteur.tva' ->> 'sure')::boolean, false)
        and private.filed_tva_fr_valide(private.filed_texte(v -> 'acheteur.tva' -> 'valeur')) then
    v_ach_siren := right(upper(regexp_replace(private.filed_texte(v -> 'acheteur.tva' -> 'valeur'), '[\s.\-]', '', 'g')), 9);
  end if;
  v_ach := jsonb_strip_nulls(jsonb_build_object(
    'nom', left(private.filed_texte(v -> 'acheteur.nom' -> 'valeur'), 200), 'siren', v_ach_siren,
    'tva', upper(private.filed_texte(v -> 'acheteur.tva' -> 'valeur')),
    'pays', upper(private.filed_texte(v -> 'acheteur.pays' -> 'valeur'))));

  v_refs := jsonb_strip_nulls(jsonb_build_object(
    'commande', left(private.filed_texte(v -> 'commande.reference' -> 'valeur'), 100),
    'livraison', left(private.filed_texte(v -> 'livraison.reference' -> 'valeur'), 100),
    'contrat', left(private.filed_texte(v -> 'contrat.reference' -> 'valeur'), 100),
    'facture_origine', left(private.filed_texte(v -> 'facture_origine.reference' -> 'valeur'), 100),
    'facture_origine_date', private.filed_date(v -> 'facture_origine.date' -> 'valeur'),
    'acheteur', left(private.filed_texte(v -> 'acheteur.reference' -> 'valeur'), 100),
    'livraison_date', private.filed_date(v -> 'livraison.date' -> 'valeur')));

  -- Ce qui compte et reste à vérifier sur la pièce.
  select coalesce(jsonb_agg(jsonb_build_object('champ', c.libelle, 'controle', v -> c.champ ->> 'controle') order by c.rang), '[]'::jsonb)
  into v_douteux
  from (values (1, 'numero', 'numéro'), (2, 'date', 'date'), (3, 'montant_ht', 'HT'), (4, 'montant_tva', 'TVA'),
               (5, 'montant_ttc', 'TTC')) as c(rang, champ, libelle)
  where v ? c.champ and not coalesce((v -> c.champ ->> 'sure')::boolean, false);

  v_empreinte := encode(sha256(convert_to(jsonb_build_object(
    'numero', v_numero, 'date', v_date, 'echeance', v_ech, 'devise', v_devise, 'ht', v_ht, 'tva', v_tva, 'ttc', v_ttc,
    'net', v_net, 'prepaye', v_prep, 'fournisseur', v_four, 'acheteur', v_ach, 'iban', v_iban, 'refs', v_refs,
    'mentions', v_mentions, 'douteux', v_douteux, 'lignes', v -> 'lignes' -> 'valeur',
    'ventilation', v -> 'tva.ventilation' -> 'valeur', 'cadre', v -> 'cadre_facturation' -> 'valeur',
    'type', v -> 'type_code' -> 'valeur')::text, 'UTF8')), 'hex');

  if v_f.id is null then
    insert into public.filed_factures (client_id, entite_id, document_id, nature, numero, numero_normalise, date_emission,
                                       date_reception, echeance_lue, devise, montant_ht, montant_tva, montant_ttc,
                                       net_a_payer, montant_prepaye, montants_calcules, type_code, cadre_facturation,
                                       fournisseur_lu, acheteur_lu, iban, refs, mentions, champs_douteux, empreinte_donnees)
    values (v_doc.client_id, v_doc.entite_id, v_doc.id, v_doc.nature, v_numero, private.filed_normaliser_numero(v_numero),
            v_date, (v_doc.recu_le at time zone coalesce(v_ent.fuseau, 'Europe/Paris'))::date, v_ech, v_devise,
            v_ht, v_tva, v_ttc, v_net, v_prep, v_calcules,
            left(private.filed_texte(v -> 'type_code' -> 'valeur'), 10),
            upper(left(private.filed_texte(v -> 'cadre_facturation' -> 'valeur'), 10)),
            v_four, v_ach, v_iban, v_refs, v_mentions, v_douteux, v_empreinte)
    returning * into v_f;
    v_nouvelle := true;
  elsif v_f.empreinte_donnees is distinct from v_empreinte or v_f.nature <> v_doc.nature then
    update public.filed_factures
       set nature = v_doc.nature, version = version + 1, numero = v_numero,
           numero_normalise = private.filed_normaliser_numero(v_numero), date_emission = v_date, echeance_lue = v_ech,
           devise = v_devise, montant_ht = v_ht, montant_tva = v_tva, montant_ttc = v_ttc, net_a_payer = v_net,
           montant_prepaye = v_prep, montants_calcules = v_calcules,
           type_code = left(private.filed_texte(v -> 'type_code' -> 'valeur'), 10),
           cadre_facturation = upper(left(private.filed_texte(v -> 'cadre_facturation' -> 'valeur'), 10)),
           fournisseur_lu = v_four, acheteur_lu = v_ach, iban = v_iban, refs = v_refs, mentions = v_mentions,
           champs_douteux = v_douteux, empreinte_donnees = v_empreinte, maj_le = now()
     where id = v_f.id
    returning * into v_f;
    v_changee := true;
  end if;

  if v_nouvelle or v_changee then
    delete from public.filed_factures_lignes where facture_id = v_f.id;
    insert into public.filed_factures_lignes (client_id, facture_id, document_id, rang, numero, reference_vendeur,
                                              reference_acheteur, gtin, designation, quantite, unite, prix_unitaire,
                                              prix_brut, remise, montant_ht, taux_tva, categorie_tva, commande_ligne, source)
    select v_f.client_id, v_f.id, v_f.document_id, e.rang::smallint,
           left(private.filed_texte(e.l -> 'numero'), 60), left(private.filed_texte(e.l -> 'reference_vendeur'), 100),
           left(private.filed_texte(e.l -> 'reference_acheteur'), 100), left(private.filed_texte(e.l -> 'gtin'), 40),
           left(private.filed_texte(e.l -> 'designation'), 500),
           case when v_doc.nature = 'avoir' then abs(private.filed_nombre(e.l -> 'quantite')) else private.filed_nombre(e.l -> 'quantite') end,
           left(private.filed_texte(e.l -> 'unite'), 20), private.filed_nombre(e.l -> 'prix_unitaire'),
           private.filed_nombre(e.l -> 'prix_brut'), private.filed_nombre(e.l -> 'remise'),
           case when v_doc.nature = 'avoir' then abs(private.filed_nombre(e.l -> 'montant')) else private.filed_nombre(e.l -> 'montant') end,
           private.filed_nombre(e.l -> 'taux_tva'), left(upper(private.filed_texte(e.l -> 'categorie_tva')), 5),
           left(private.filed_texte(e.l -> 'commande_ligne'), 60),
           case when v -> 'lignes' ->> 'source' in ('xml', 'regle', 'ia', 'humain', 'tableur') then v -> 'lignes' ->> 'source' else 'regle' end
    from jsonb_array_elements(case when jsonb_typeof(v -> 'lignes' -> 'valeur') = 'array' then v -> 'lignes' -> 'valeur'
                                   else '[]'::jsonb end) with ordinality as e(l, rang)
    where e.rang <= 5000 and jsonb_typeof(e.l) = 'object';

    delete from public.filed_factures_tva where facture_id = v_f.id;
    insert into public.filed_factures_tva (client_id, facture_id, document_id, categorie, taux, base, montant, motif, source)
    select v_f.client_id, v_f.id, v_f.document_id, left(upper(private.filed_texte(e.t -> 'categorie')), 5),
           private.filed_nombre(e.t -> 'taux'),
           case when v_doc.nature = 'avoir' then abs(private.filed_nombre(e.t -> 'base')) else private.filed_nombre(e.t -> 'base') end,
           case when v_doc.nature = 'avoir' then abs(private.filed_nombre(e.t -> 'montant')) else private.filed_nombre(e.t -> 'montant') end,
           left(private.filed_texte(e.t -> 'motif'), 300),
           case when v -> 'tva.ventilation' ->> 'source' in ('xml', 'regle', 'ia', 'humain', 'tableur')
                then v -> 'tva.ventilation' ->> 'source' else 'regle' end
    from jsonb_array_elements(case when jsonb_typeof(v -> 'tva.ventilation' -> 'valeur') = 'array'
                                   then v -> 'tva.ventilation' -> 'valeur' else '[]'::jsonb end) as e(t)
    where jsonb_typeof(e.t) = 'object';
  end if;

  perform private.filed_resoudre_fournisseur(v_f.id);

  update public.filed_documents set etat = 'integre', traite_le = now() where id = v_doc.id and etat <> 'integre';
  if v_nouvelle then
    perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'integree',
      format('%s %s du %s, %s TTC.', case v_doc.nature when 'avoir' then 'Avoir' else 'Facture' end,
             coalesce(v_numero, 'sans numéro'), coalesce(to_char(v_date, 'DD/MM/YYYY'), 'date inconnue'),
             private.filed_montant_texte(v_ttc)),
      jsonb_build_object('facture', v_f.id, 'version', 1));
  elsif v_changee then
    perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'mise_a_jour',
      format('Relue ou corrigée : version %s.', v_f.version), jsonb_build_object('facture', v_f.id, 'version', v_f.version));
  end if;

  v_statut := private.filed_controler_facture(v_f.id);
  return v_statut;
end $_$;


--
-- Name: filed_integrer_piece(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_integrer_piece(p_piece uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_doc public.filed_documents;
  v_p public.pieces;
  v_nature text;
  v_etat text;
  v_motif text;
begin
  select * into v_doc from public.filed_documents where piece_id = p_piece for update;
  if not found then
    return 'hors_filed';
  end if;
  if v_doc.etat = 'doublon' then
    return 'doublon';
  end if;
  select * into v_p from public.pieces where id = p_piece;
  if v_p.statut not in ('lue', 'a_verifier', 'a_classer', 'rejetee', 'echec') then
    return 'pas_encore_lue';
  end if;

  if v_doc.nature_source = 'humain' then
    v_nature := v_doc.nature;
    v_etat := private.filed_etat_de(v_nature);
    v_motif := case when v_p.statut in ('rejetee', 'echec')
                    then coalesce(v_p.motif, 'La pièce n''a pas pu être lue.') end;
  elsif v_p.statut in ('rejetee', 'echec') then
    v_nature := null;
    v_etat := 'illisible';
    v_motif := coalesce(v_p.motif, 'La pièce n''a pas pu être lue.');
  elsif v_p.statut = 'a_classer' then
    v_nature := null;
    v_etat := 'a_classer';
    v_motif := coalesce(v_p.motif, 'Type incertain : une personne le tranche.');
  else
    v_nature := private.filed_nature_de(v_p.type_piece);
    v_etat := private.filed_etat_de(v_nature);
    v_motif := case when v_nature is null then coalesce(v_p.motif, 'Type non reconnu : une personne le tranche.') end;
  end if;

  -- Une facture, un avoir, un bon de commande ou de livraison passe tout de
  -- suite à son moteur, dans la même transaction : son document est « integre ».
  if v_nature in ('facture', 'avoir', 'bon_commande', 'bon_livraison') then
    v_etat := 'integre';
  end if;

  if not (v_doc.etat is not distinct from v_etat and v_doc.nature is not distinct from v_nature
          and v_doc.motif is not distinct from v_motif) then
    update public.filed_documents
       set etat = v_etat, nature = v_nature,
           nature_source = case when v_nature is null then null
                                when v_doc.nature_source = 'humain' then 'humain' else 'lecteur' end,
           motif = v_motif, lu_le = coalesce(v_p.lue_le, now()), traite_le = now()
     where id = v_doc.id;
    perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text,
      case v_etat when 'illisible' then 'illisible' when 'a_classer' then 'a_classer' else 'lu' end,
      case v_etat
        when 'illisible' then 'Pièce illisible : ' || v_motif
        when 'a_classer' then 'À classer : ' || v_motif
        when 'classe' then 'Lue et rangée : ' || private.filed_libelle_nature(v_nature) || '.'
        else 'Lue : ' || private.filed_libelle_nature(v_nature) || '.' end,
      jsonb_build_object('statut_lecture', v_p.statut, 'type_piece', v_p.type_piece, 'nature', v_nature,
                         'version_lecteur', v_p.version_lecteur));
  end if;

  if v_nature in ('facture', 'avoir') then
    return 'facture:' || private.filed_integrer_facture(v_doc.id);
  elsif v_nature = 'bon_commande' then
    return private.filed_integrer_commande(v_doc.id);
  elsif v_nature = 'bon_livraison' then
    return private.filed_integrer_reception(v_doc.id);
  end if;
  return v_etat;
end $$;


--
-- Name: filed_integrer_reception(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_integrer_reception(p_document uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_doc public.filed_documents;
  v jsonb;
  v_r public.filed_receptions;
begin
  select * into v_doc from public.filed_documents where id = p_document for update;
  if not found or v_doc.nature <> 'bon_livraison' then
    return 'hors_reception';
  end if;
  v := private.filed_valeurs(v_doc.piece_id);
  v_r := private.filed_ecrire_reception(v_doc.client_id, v_doc.entite_id, 'piece', jsonb_strip_nulls(jsonb_build_object(
    'numero', private.filed_texte(v -> 'numero' -> 'valeur'),
    'date', v -> 'date' -> 'valeur',
    'commande', private.filed_texte(v -> 'commande.reference' -> 'valeur'),
    'fournisseur', private.filed_identite_lue(v),
    'lignes', v -> 'lignes' -> 'valeur',
    'lignes_source', v -> 'lignes' ->> 'source')), v_doc.id, null);
  update public.filed_documents set etat = 'integre', traite_le = now() where id = v_doc.id and etat <> 'integre';
  perform private.filed_historiser(v_doc.client_id, v_doc.id, 'filed_document', v_doc.id::text, 'integree',
    format('Bon de livraison %s : réception %s, %s ligne(s)%s.', coalesce(v_r.numero, 'sans numéro'), v_r.id,
           (select count(*) from public.filed_receptions_lignes l where l.reception_id = v_r.id),
           case when v_r.commande_id is null then ', sans commande connue' else '' end),
    jsonb_build_object('reception', v_r.id, 'commande', v_r.commande_id));
  return 'reception:' || v_r.id::text;
end $$;


--
-- Name: filed_journaliser(uuid, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_journaliser(p_client uuid, p_action text, p_objet_type text, p_objet_id text, p_donnees jsonb DEFAULT '{}'::jsonb, p_entite uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_avant text := current_setting('omega.module', true);
  v_id bigint;
begin
  perform set_config('omega.module', 'filed', true);
  v_id := private.journaliser(p_client, p_action, p_objet_type, p_objet_id, coalesce(p_donnees, '{}'::jsonb), p_entite);
  perform set_config('omega.module', coalesce(v_avant, ''), true);
  return v_id;
end $$;


--
-- Name: filed_levable(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_levable(p_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_code in ('montant.coherence', 'montant.signe', 'doublon.exact', 'doublon.probable', 'iban.partage',
                    'fournisseur.siren', 'tva.numero_siren', 'tva.taux', 'tva.autoliquidation_attendue',
                    'destinataire.societe', 'date.future',
                    'rapprochement.commande', 'rapprochement.commande_inconnue', 'rapprochement.commande_fermee',
                    'rapprochement.prix', 'rapprochement.quantite', 'rapprochement.deja_facture',
                    'rapprochement.reception', 'rapprochement.lignes', 'rapprochement.montant',
                    'avoir.origine', 'avoir.montant', 'avoir.quantite')
$$;


--
-- Name: filed_lever_anomalie(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_lever_anomalie(p_facture uuid, p_code text, p_motif text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_c public.filed_controles;
begin
  v_f := private.filed_exiger_facture(p_facture, array['gerant', 'admin', 'valideur']);
  if not private.filed_levable(p_code) then
    raise exception 'Cette anomalie ne se lève pas d''un motif : elle se corrige, ou se décide par la file.' using errcode = '22023';
  end if;
  if nullif(btrim(p_motif), '') is null or char_length(btrim(p_motif)) < 3 then
    raise exception 'Une levée dit pourquoi.' using errcode = '22023';
  end if;
  select * into v_c from public.filed_controles c
  where c.facture_id = v_f.id and c.code = p_code and c.resultat = 'anomalie'
  order by c.cree_le desc limit 1;
  if not found then
    raise exception 'Aucune anomalie « % » en cours sur cette facture.', p_code using errcode = 'P0002';
  end if;
  insert into public.filed_levees (client_id, facture_id, document_id, code, cle, motif, leve_par)
  values (v_f.client_id, v_f.id, v_f.document_id, p_code, v_c.cle, left(btrim(p_motif), 500), (select auth.uid()))
  on conflict (facture_id, code, cle) do nothing;
  perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'levee',
    format('Anomalie levée (%s) : %s', v_c.message, left(btrim(p_motif), 300)),
    jsonb_build_object('code', p_code, 'cle', v_c.cle));
  return private.filed_controler_facture(v_f.id);
end $$;


--
-- Name: filed_libelle_fournisseur(public.filed_fournisseurs); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_libelle_fournisseur(p_f public.filed_fournisseurs) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_f.nom || coalesce(' (SIREN ' || p_f.siren || ')', ' (TVA ' || p_f.tva || ')', '')
$$;


--
-- Name: filed_libelle_nature(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_libelle_nature(p_nature text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_nature
    when 'facture' then 'facture' when 'avoir' then 'avoir' when 'bon_commande' then 'bon de commande'
    when 'bon_livraison' then 'bon de livraison' when 'devis' then 'devis' when 'releve' then 'relevé'
    when 'contrat' then 'contrat' when 'attestation_assurance' then 'attestation d''assurance'
    else 'autre document' end
$$;


--
-- Name: filed_luhn(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_luhn(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  s integer := 0;
  d integer;
  n integer;
begin
  if p is null or p !~ '^[0-9]+$' then
    return false;
  end if;
  n := length(p);
  for i in 0 .. n - 1 loop
    d := substr(p, n - i, 1)::integer;
    if i % 2 = 1 then
      d := d * 2;
      if d > 9 then
        d := d - 9;
      end if;
    end if;
    s := s + d;
  end loop;
  return s % 10 = 0;
end $_$;


--
-- Name: filed_masquer_iban(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_masquer_iban(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select left(p, 4) || ' •••• ' || right(p, 4)
$$;


--
-- Name: filed_montant_texte(numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_montant_texte(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p is null then '—'
              else replace(replace(to_char(p, 'FM999G999G999G990D00'), ',', ' '), '.', ',') || ' €' end
$$;


--
-- Name: filed_nature_de(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_nature_de(p_type_piece text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_type_piece is null then null
    when p_type_piece in ('facture', 'avoir', 'bon_commande', 'bon_livraison', 'devis', 'releve', 'contrat',
                          'attestation_assurance') then p_type_piece
    else 'autre'
  end
$$;


--
-- Name: filed_nombre(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_nombre(p jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v text;
  n numeric;
begin
  v := case jsonb_typeof(p) when 'number' then p::text when 'string' then p #>> '{}' else null end;
  if v is null then
    return null;
  end if;
  -- Les espaces, y compris l'insécable (160) et la fine insécable (8239) des montants français.
  v := replace(regexp_replace(v, '[\s' || chr(160) || chr(8239) || ']', '', 'g'), ',', '.');
  if v !~ '^[-+]?[0-9]+(\.[0-9]+)?$' then
    return null;
  end if;
  n := v::numeric;
  return case when abs(n) < 1e12 then n end;
end $_$;


--
-- Name: filed_normaliser(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_normaliser(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select btrim(regexp_replace(
    translate(replace(replace(lower(coalesce(p, '')), 'œ', 'oe'), 'æ', 'ae'),
              'àâäáãåçéèêëíìîïñóòôöõúùûüýÿ', 'aaaaaaceeeeiiiinooooouuuuyy'),
    '[^a-z0-9]+', ' ', 'g'))
$$;


--
-- Name: filed_normaliser_nom(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_normaliser_nom(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select btrim(regexp_replace(regexp_replace(private.filed_normaliser(p),
    '\m(sas|sasu|sarl|eurl|sa|sci|snc|scop|scp|selarl|selas|sel|eirl|ei|gie|sca|scs|ltd|llc|gmbh|ag|bv|nv|spa|srl|inc|plc)\M',
    ' ', 'g'), '\s+', ' ', 'g'))
$$;


--
-- Name: filed_normaliser_numero(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_normaliser_numero(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^0-9A-Za-z]', '', 'g')), '')
$$;


--
-- Name: filed_pays_ue(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_pays_ue(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(upper(p) = any (array['AT', 'BE', 'BG', 'CY', 'CZ', 'DE', 'DK', 'EE', 'EL', 'GR', 'ES', 'FI', 'HR', 'HU',
                                        'IE', 'IT', 'LT', 'LU', 'LV', 'MT', 'NL', 'PL', 'PT', 'RO', 'SE', 'SI', 'SK', 'XI']), false)
$$;


--
-- Name: filed_poser_resultat(public.filed_factures, text, text, boolean, text, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_poser_resultat(p_f public.filed_factures, p_code text, p_gravite text, p_anomalie boolean, p_message text, p_motif text DEFAULT NULL::text, p_preuve jsonb DEFAULT '{}'::jsonb, p_cle text DEFAULT ''::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_levee uuid;
  v_resultat text;
begin
  if coalesce(p_anomalie, false) and private.filed_levable(p_code) then
    select l.id into v_levee from public.filed_levees l
    where l.facture_id = p_f.id and l.code = p_code and l.cle = coalesce(p_cle, '');
  end if;
  v_resultat := case when not coalesce(p_anomalie, false) then 'ok' when v_levee is not null then 'levee' else 'anomalie' end;
  insert into public.filed_controles (client_id, facture_id, document_id, version, code, gravite, resultat, message,
                                      motif_officiel, preuve, cle, levee_id)
  values (p_f.client_id, p_f.id, p_f.document_id, p_f.version, p_code, p_gravite, v_resultat, left(p_message, 500),
          p_motif, coalesce(p_preuve, '{}'::jsonb), coalesce(p_cle, ''), v_levee)
  on conflict (facture_id, code, cle) do update
    set gravite = excluded.gravite, resultat = excluded.resultat, message = excluded.message,
        motif_officiel = excluded.motif_officiel, preuve = excluded.preuve, levee_id = excluded.levee_id,
        version = excluded.version, cree_le = now();
  return v_resultat = 'anomalie';
end $$;


--
-- Name: filed_prochain_numero(uuid, text, smallint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_prochain_numero(p_client uuid, p_nature text, p_annee smallint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v integer;
begin
  insert into public.filed_compteurs as c (client_id, nature, annee, dernier)
  values (p_client, p_nature, p_annee, 1)
  on conflict (client_id, nature, annee) do update set dernier = c.dernier + 1
  returning c.dernier into v;
  return v;
end $$;


--
-- Name: filed_fournisseurs_ibans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_fournisseurs_ibans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    fournisseur_id uuid NOT NULL,
    iban text NOT NULL,
    iban_masque text NOT NULL,
    empreinte text NOT NULL,
    statut text DEFAULT 'propose'::text NOT NULL,
    source text NOT NULL,
    document_id uuid,
    propose_par uuid,
    propose_le timestamp with time zone DEFAULT now() NOT NULL,
    decide_le timestamp with time zone,
    decide_par uuid,
    motif text,
    CONSTRAINT filed_fournisseurs_ibans_empreinte_check CHECK ((empreinte ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT filed_fournisseurs_ibans_iban_check CHECK ((iban ~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$'::text)),
    CONSTRAINT filed_fournisseurs_ibans_motif_check CHECK ((char_length(motif) <= 500)),
    CONSTRAINT filed_fournisseurs_ibans_source_check CHECK ((source = ANY (ARRAY['facture'::text, 'saisie'::text, 'import'::text]))),
    CONSTRAINT filed_fournisseurs_ibans_statut_check CHECK ((statut = ANY (ARRAY['propose'::text, 'valide'::text, 'refuse'::text, 'revoque'::text])))
);


--
-- Name: filed_proposer_iban(uuid, text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_proposer_iban(p_fournisseur uuid, p_iban text, p_source text, p_document uuid DEFAULT NULL::uuid, p_motif text DEFAULT NULL::text) RETURNS public.filed_fournisseurs_ibans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_fournisseurs;
  v_ib public.filed_fournisseurs_ibans;
  v_iban text := upper(regexp_replace(coalesce(p_iban, ''), '\s', '', 'g'));
begin
  select * into v_f from public.filed_fournisseurs where id = p_fournisseur;
  select * into v_ib from public.filed_fournisseurs_ibans
  where client_id = v_f.client_id and fournisseur_id = v_f.id and iban = v_iban;
  if found then
    return v_ib;
  end if;
  insert into public.filed_fournisseurs_ibans (client_id, fournisseur_id, iban, iban_masque, empreinte, statut, source,
                                               document_id, propose_par, decide_le, decide_par, motif)
  values (v_f.client_id, v_f.id, v_iban, private.filed_masquer_iban(v_iban),
          encode(sha256(convert_to(v_iban, 'UTF8')), 'hex'),
          case when p_source = 'import' then 'valide' else 'propose' end, p_source, p_document, (select auth.uid()),
          case when p_source = 'import' then now() end, case when p_source = 'import' then (select auth.uid()) end,
          left(p_motif, 500))
  returning * into v_ib;

  if p_source <> 'import' and v_f.statut = 'actif' then
    perform private.filed_deposer_demande(v_f.client_id, null, 'filed.valider_iban', 'filed_iban', v_ib.id::text,
      format('Nouvel IBAN pour %s : %s', private.filed_libelle_fournisseur(v_f), v_ib.iban_masque), null,
      jsonb_build_object('fournisseur', v_f.id, 'iban', v_ib.iban_masque, 'empreinte', v_ib.empreinte,
                         'document', p_document, 'source', p_source),
      'filed:iban:' || v_ib.id::text);
    perform private.lever_alerte_module(v_f.client_id, 'filed', 'attention',
      left(format('Nouvel IBAN pour %s : à vérifier auprès du fournisseur avant tout paiement', v_f.nom), 200),
      jsonb_build_object('fournisseur', v_f.id, 'iban', v_ib.iban_masque, 'document', p_document),
      'iban:' || v_ib.id::text, true, null);
    perform private.filed_historiser(v_f.client_id, null, 'filed_fournisseur', v_f.id::text, 'iban_propose',
      format('Nouvel IBAN proposé (%s) : une personne le vérifie avant tout paiement.', v_ib.iban_masque),
      jsonb_build_object('iban', v_ib.iban_masque, 'document', p_document, 'source', p_source));
  end if;
  return v_ib;
end $$;


--
-- Name: filed_proposer_iban_fournisseur(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_proposer_iban_fournisseur(p_fournisseur uuid, p_iban text, p_motif text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_fournisseurs;
  v_ib public.filed_fournisseurs_ibans;
begin
  select * into v_f from public.filed_fournisseurs where id = p_fournisseur;
  if not found then
    raise exception 'Fournisseur introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_f.client_id, array['gerant', 'admin', 'valideur', 'collaborateur'], null);
  if not private.filed_iban_valide(p_iban) then
    raise exception 'IBAN faux : sa clé ne tombe pas juste.' using errcode = '22023';
  end if;
  if nullif(btrim(p_motif), '') is null then
    raise exception 'Dites d''où vient cet IBAN (lettre du fournisseur, appel…).' using errcode = '22023';
  end if;
  v_ib := private.filed_proposer_iban(v_f.id, p_iban, 'saisie', null, p_motif);
  return v_ib.id;
end $$;


--
-- Name: filed_quantite_texte(numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_quantite_texte(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p is null then '—'
              else replace(rtrim(rtrim(to_char(p, 'FM999999999990.999999'), '0'), '.'), '.', ',') end
$$;


--
-- Name: filed_rapprocher_facture(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_rapprocher_facture(p_facture uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_reglage public.filed_reglages;
  v_tol numeric;
  v_cmd public.filed_commandes;
  v_cmd_source text;
  v_ref_cmd text;
  v_origine public.filed_factures;
  v_recep public.filed_receptions;
  v_sens smallint := 1;
  v_nb_lignes integer;
  v_l public.filed_factures_lignes;
  v_cl public.filed_commandes_lignes;
  v_ql public.filed_receptions_lignes;
  v_methode text;
  v_a_reception boolean := false;
  v_mode text := 'aucun';
  v_nb_app integer := 0;
  v_nb_sans integer := 0;
  v_sans text[] := '{}';
  v_tot_prix numeric := 0;
  v_tot_qte numeric := 0;
  v_tot_deja numeric := 0;
  v_tot_non_recu numeric := 0;
  v_ecart_montant numeric;
  v_deja_montant numeric;
  v_restant_montant numeric;
  v_tol_montant numeric;
  v_gravite_cmd text;
  v_avoirs numeric;
  v_precedent jsonb;
  v_resume jsonb;
  v_non_recu numeric;
begin
  select * into v_f from public.filed_factures where id = p_facture;
  if not found then
    return;
  end if;
  v_reglage := private.filed_reglage(v_f.client_id, v_f.entite_id);
  v_tol := coalesce(v_reglage.tolerance_totaux, 0.05);
  select to_jsonb(x) - 'id' - 'cree_le' - 'version' - 'preuve' into v_precedent
  from public.filed_rapprochements x where x.facture_id = v_f.id;
  delete from public.filed_rapprochements_lignes where facture_id = v_f.id;
  delete from public.filed_rapprochements where facture_id = v_f.id;
  select count(*) into v_nb_lignes from public.filed_factures_lignes l where l.facture_id = v_f.id;

  -- ── L'avoir et la facture qu'il corrige ──
  if v_f.nature = 'avoir' then
    v_sens := -1;
    if v_f.refs ? 'facture_origine' and v_f.fournisseur_id is not null then
      select e.* into v_origine from public.filed_factures e
      where e.client_id = v_f.client_id and e.nature = 'facture' and e.id <> v_f.id
        and e.fournisseur_id = v_f.fournisseur_id and e.statut <> 'ecartee'
        and e.numero_normalise = private.filed_normaliser_numero(v_f.refs ->> 'facture_origine')
      order by (e.date_emission = private.filed_date(v_f.refs -> 'facture_origine_date')) desc nulls last, e.date_emission desc
      limit 1;
    end if;
    update public.filed_factures set avoir_de = v_origine.id where id = v_f.id;
    perform private.filed_poser_resultat(v_f, 'avoir.origine', 'attention', v_origine.id is null,
      case when v_origine.id is not null
             then format('Avoir sur la facture %s du %s.', v_origine.numero, coalesce(to_char(v_origine.date_emission, 'DD/MM/YYYY'), '?'))
           when v_f.refs ? 'facture_origine'
             then format('Avoir sur une facture inconnue (%s) : elle n''est pas passée par FILED, ou le numéro est mal lu.', v_f.refs ->> 'facture_origine')
           else 'Avoir sans facture d''origine citée : une personne le rattache.' end,
      'REF_CT_ABSENT', jsonb_strip_nulls(jsonb_build_object('facture_origine', v_f.refs ->> 'facture_origine', 'facture', v_origine.id)),
      coalesce(private.filed_normaliser_numero(v_f.refs ->> 'facture_origine'), ''));
    if v_origine.id is not null and v_f.montant_ttc is not null and v_origine.montant_ttc is not null then
      select coalesce(sum(a.montant_ttc), 0) into v_avoirs from public.filed_factures a
      where a.avoir_de = v_origine.id and a.nature = 'avoir' and a.statut <> 'ecartee' and a.id <> v_f.id;
      perform private.filed_poser_resultat(v_f, 'avoir.montant', 'bloquant', v_avoirs + v_f.montant_ttc > v_origine.montant_ttc + v_tol,
        case when v_avoirs + v_f.montant_ttc > v_origine.montant_ttc + v_tol
             then format('Les avoirs sur la facture %s font %s pour une facture de %s : %s de trop.', v_origine.numero,
                         private.filed_montant_texte(v_avoirs + v_f.montant_ttc), private.filed_montant_texte(v_origine.montant_ttc),
                         private.filed_montant_texte(v_avoirs + v_f.montant_ttc - v_origine.montant_ttc))
             else format('L''avoir tient dans la facture %s : %s sur %s, avoirs précédents compris.', v_origine.numero,
                         private.filed_montant_texte(v_avoirs + v_f.montant_ttc), private.filed_montant_texte(v_origine.montant_ttc)) end,
        'MONTANT_ERR', jsonb_build_object('facture', v_origine.id, 'avoirs', v_avoirs + v_f.montant_ttc, 'facture_ttc', v_origine.montant_ttc),
        v_origine.id::text);
    end if;
  end if;

  -- ── La commande : désignée, celle de la facture corrigée, citée, ou celle du bon de livraison cité ──
  v_ref_cmd := nullif(btrim(v_f.refs ->> 'commande'), '');
  if v_f.commande_force is not null then
    select * into v_cmd from public.filed_commandes where id = v_f.commande_force;
    v_cmd_source := 'humain';
  elsif v_sens = -1 and v_origine.commande_id is not null then
    select * into v_cmd from public.filed_commandes where id = v_origine.commande_id;
    v_cmd_source := 'avoir';
  elsif private.filed_normaliser_numero(v_ref_cmd) is not null then
    select c.* into v_cmd from public.filed_commandes c
    where c.client_id = v_f.client_id and c.numero_normalise = private.filed_normaliser_numero(v_ref_cmd)
    order by (c.fournisseur_id = v_f.fournisseur_id) desc nulls last, (c.entite_id = v_f.entite_id) desc, c.cree_le desc
    limit 1;
    if v_cmd.id is not null then
      v_cmd_source := 'reference';
    end if;
  end if;
  if private.filed_normaliser_numero(v_f.refs ->> 'livraison') is not null then
    select rc.* into v_recep from public.filed_receptions rc
    where rc.client_id = v_f.client_id and rc.statut = 'enregistree'
      and rc.numero_normalise = private.filed_normaliser_numero(v_f.refs ->> 'livraison')
      and (v_f.fournisseur_id is null or rc.fournisseur_id is null or rc.fournisseur_id = v_f.fournisseur_id)
      and (v_cmd.id is null or rc.commande_id is null or rc.commande_id = v_cmd.id)
    order by (rc.entite_id = v_f.entite_id) desc, rc.cree_le desc
    limit 1;
    if v_cmd.id is null and v_recep.commande_id is not null then
      select * into v_cmd from public.filed_commandes where id = v_recep.commande_id;
      v_cmd_source := 'reference';
    end if;
  end if;
  update public.filed_factures set commande_id = v_cmd.id where id = v_f.id;

  v_gravite_cmd := case when coalesce(v_reglage.commande_exigee, false) and v_sens = 1
                             and coalesce(v_f.montant_ht, v_f.montant_ttc, 0) >= coalesce(v_reglage.commande_exigee_des_ht, 0)
                        then 'bloquant' else 'info' end;
  if v_cmd.id is null then
    if private.filed_normaliser_numero(v_ref_cmd) is not null then
      perform private.filed_poser_resultat(v_f, 'rapprochement.commande_inconnue',
        case when v_gravite_cmd = 'bloquant' then 'bloquant' else 'attention' end, true,
        format('Commande citée (%s) inconnue de FILED : elle n''a pas été reprise du système d''achats, ou le numéro est mal lu.', v_ref_cmd),
        'CMD_EJ_ERR', jsonb_build_object('commande_lue', v_ref_cmd), private.filed_normaliser_numero(v_ref_cmd));
    else
      perform private.filed_poser_resultat(v_f, 'rapprochement.commande', v_gravite_cmd, true,
        case when v_gravite_cmd = 'bloquant'
             then 'Sans commande, alors que l''organisation en exige une : achat hors commande, à justifier.'
             else 'Sans commande : rien à rapprocher.' end,
        'CMD_EJ_ERR');
    end if;
  else
    perform private.filed_poser_resultat(v_f, 'rapprochement.commande', 'info', false,
      format('Commande %s%s.', v_cmd.numero,
             case v_cmd_source when 'humain' then ', désignée par une personne' when 'avoir' then ', celle de la facture corrigée'
                               else '' end),
      null, jsonb_build_object('commande', v_cmd.id, 'source', v_cmd_source));
    if v_cmd.fournisseur_id is not null and v_f.fournisseur_id is not null and v_cmd.fournisseur_id <> v_f.fournisseur_id then
      perform private.filed_poser_resultat(v_f, 'rapprochement.fournisseur', 'bloquant', true,
        format('La commande %s a été passée à un autre fournisseur (%s).', v_cmd.numero,
               (select private.filed_libelle_fournisseur(x) from public.filed_fournisseurs x where x.id = v_cmd.fournisseur_id)),
        'CREANCIER_ERR', jsonb_build_object('commande', v_cmd.id, 'fournisseur_commande', v_cmd.fournisseur_id), v_cmd.id::text);
    end if;
    if v_cmd.statut <> 'ouverte' and v_sens = 1 then
      perform private.filed_poser_resultat(v_f, 'rapprochement.commande_fermee', 'bloquant', true,
        format('Commande %s %s : plus rien ne se facture dessus.', v_cmd.numero,
               case v_cmd.statut when 'soldee' then 'soldée' else 'annulée' end),
        'CMD_EJ_ERR', jsonb_build_object('commande', v_cmd.id, 'statut', v_cmd.statut), v_cmd.id::text);
    end if;
  end if;

  -- ── Ligne à ligne ──
  if v_cmd.id is not null and v_nb_lignes > 0 then
    v_mode := 'lignes';
    v_a_reception := exists (select 1 from public.filed_receptions rc where rc.commande_id = v_cmd.id and rc.statut = 'enregistree');
    for v_l in select l.* from public.filed_factures_lignes l where l.facture_id = v_f.id order by l.rang loop
      v_cl := null;
      v_methode := null;
      select c.* into v_cl from public.filed_appariements a join public.filed_commandes_lignes c on c.id = a.commande_ligne_id
      where a.facture_ligne_id = v_l.id and c.commande_id = v_cmd.id;
      if v_cl.id is not null then
        v_methode := 'humain';
      end if;
      if v_cl.id is null and nullif(btrim(v_l.commande_ligne), '') is not null then
        select c.* into v_cl from public.filed_commandes_lignes c
        where c.commande_id = v_cmd.id
          and (c.rang::text = btrim(v_l.commande_ligne)
               or private.filed_normaliser_numero(c.numero) = private.filed_normaliser_numero(v_l.commande_ligne))
          and not exists (select 1 from public.filed_rapprochements_lignes x where x.facture_id = v_f.id and x.commande_ligne_id = c.id)
        order by c.rang limit 1;
        if v_cl.id is not null then
          v_methode := 'commande_ligne';
        end if;
      end if;
      if v_cl.id is null then
        select c.* into v_cl from public.filed_commandes_lignes c
        where c.commande_id = v_cmd.id
          and not exists (select 1 from public.filed_rapprochements_lignes x where x.facture_id = v_f.id and x.commande_ligne_id = c.id)
          and ((private.filed_normaliser_numero(v_l.gtin) is not null
                and private.filed_normaliser_numero(v_l.gtin) = private.filed_normaliser_numero(c.gtin))
            or (private.filed_normaliser_numero(v_l.reference_vendeur) is not null
                and private.filed_normaliser_numero(v_l.reference_vendeur)
                    in (private.filed_normaliser_numero(c.reference), private.filed_normaliser_numero(c.reference_acheteur)))
            or (private.filed_normaliser_numero(v_l.reference_acheteur) is not null
                and private.filed_normaliser_numero(v_l.reference_acheteur)
                    in (private.filed_normaliser_numero(c.reference_acheteur), private.filed_normaliser_numero(c.reference))))
        order by c.rang limit 1;
        if v_cl.id is not null then
          v_methode := case when private.filed_normaliser_numero(v_l.gtin) is not null
                                 and private.filed_normaliser_numero(v_l.gtin) = private.filed_normaliser_numero(v_cl.gtin)
                            then 'gtin' else 'reference' end;
        end if;
      end if;
      if v_cl.id is null and coalesce(private.filed_normaliser(v_l.designation), '') <> '' then
        select c.* into v_cl from public.filed_commandes_lignes c
        where c.commande_id = v_cmd.id and c.designation_normalisee = private.filed_normaliser(v_l.designation)
          and not exists (select 1 from public.filed_rapprochements_lignes x where x.facture_id = v_f.id and x.commande_ligne_id = c.id)
          and (select count(*) from public.filed_commandes_lignes c2
               where c2.commande_id = v_cmd.id and c2.designation_normalisee = private.filed_normaliser(v_l.designation)) = 1;
        if v_cl.id is not null then
          v_methode := 'designation';
        end if;
      end if;
      if v_cl.id is null then
        insert into public.filed_rapprochements_lignes (client_id, facture_id, document_id, facture_ligne_id, methode, sens,
                                                        quantite, prix_facture, resultat)
        values (v_f.client_id, v_f.id, v_f.document_id, v_l.id, 'aucune', v_sens, v_l.quantite, v_l.prix_unitaire, 'sans_commande');
      else
        perform private.filed_rapprocher_ligne(v_f, v_l, v_cl, v_methode, v_sens, v_reglage, v_a_reception);
      end if;
    end loop;

    -- Une seule ligne facturée sans ligne, une seule ligne commandée libre : c'est elle.
    if (select count(*) from public.filed_rapprochements_lignes x where x.facture_id = v_f.id and x.methode = 'aucune') = 1
       and (select count(*) from public.filed_commandes_lignes c where c.commande_id = v_cmd.id
            and not exists (select 1 from public.filed_rapprochements_lignes x
                            where x.facture_id = v_f.id and x.commande_ligne_id = c.id)) = 1 then
      select l.* into v_l from public.filed_factures_lignes l
      join public.filed_rapprochements_lignes x on x.facture_ligne_id = l.id
      where x.facture_id = v_f.id and x.methode = 'aucune';
      select c.* into v_cl from public.filed_commandes_lignes c where c.commande_id = v_cmd.id
        and not exists (select 1 from public.filed_rapprochements_lignes x where x.facture_id = v_f.id and x.commande_ligne_id = c.id);
      delete from public.filed_rapprochements_lignes where facture_id = v_f.id and facture_ligne_id = v_l.id;
      perform private.filed_rapprocher_ligne(v_f, v_l, v_cl, 'seule', v_sens, v_reglage, v_a_reception);
    end if;

    select count(*) filter (where x.methode <> 'aucune'), count(*) filter (where x.methode = 'aucune'),
           coalesce(sum(x.ecart_prix), 0), coalesce(sum(x.ecart_quantite_montant), 0),
           coalesce(sum(round(x.quantite * coalesce(x.prix_commande, x.prix_facture, 0), 2)) filter (where x.resultat = 'deja_facture'), 0),
           coalesce(sum(x.non_recu_montant), 0),
           coalesce(array_agg(format('ligne %s (%s)', l.rang, coalesce(left(l.designation, 60), l.reference_vendeur, '?')) order by l.rang)
                    filter (where x.methode = 'aucune'), '{}')
    into v_nb_app, v_nb_sans, v_tot_prix, v_tot_qte, v_tot_deja, v_tot_non_recu, v_sans
    from public.filed_rapprochements_lignes x left join public.filed_factures_lignes l on l.id = x.facture_ligne_id
    where x.facture_id = v_f.id;

    perform private.filed_poser_resultat(v_f, 'rapprochement.lignes', 'attention', v_nb_sans > 0,
      case when v_nb_sans = 0 then 'Chaque ligne facturée a sa ligne de commande.'
           else format('%s ligne(s) facturée(s) sans ligne de commande : %s.', v_nb_sans, array_to_string(v_sans, ', ')) end,
      'ART_ERR', jsonb_build_object('sans_commande', to_jsonb(v_sans), 'appariees', v_nb_app));
    if not exists (select 1 from public.filed_controles c where c.facture_id = v_f.id and c.code = 'rapprochement.prix' and c.resultat = 'anomalie') then
      perform private.filed_poser_resultat(v_f, 'rapprochement.prix', 'bloquant', false, 'Chaque prix facturé est le prix commandé.');
    end if;
    if not exists (select 1 from public.filed_controles c where c.facture_id = v_f.id
                   and c.code in ('rapprochement.quantite', 'rapprochement.deja_facture') and c.resultat = 'anomalie') then
      perform private.filed_poser_resultat(v_f, 'rapprochement.quantite', 'bloquant', false, 'Aucune ligne facturée au-delà de la commande.');
    end if;
    if (v_a_reception or coalesce(v_reglage.reception_exigee, false)) and v_sens = 1
       and not exists (select 1 from public.filed_controles c where c.facture_id = v_f.id and c.code = 'rapprochement.reception' and c.resultat = 'anomalie') then
      perform private.filed_poser_resultat(v_f, 'rapprochement.reception', 'bloquant', false, 'Chaque ligne facturée a été reçue.');
    end if;

  -- ── Les totaux, quand la facture n'a pas de lignes ──
  elsif v_cmd.id is not null then
    v_mode := 'totaux';
    select coalesce(sum(case when f2.nature = 'avoir' then -f2.montant_ht else f2.montant_ht end), 0) into v_deja_montant
    from public.filed_factures f2
    where f2.commande_id = v_cmd.id and f2.id <> v_f.id and f2.statut <> 'ecartee' and f2.montant_ht is not null;
    if v_sens = 1 then
      if v_cmd.montant_ht is null or v_f.montant_ht is null then
        perform private.filed_poser_resultat(v_f, 'rapprochement.montant', 'info', true,
          'Commande sans montant, ou facture sans HT : les totaux ne se comparent pas.', null,
          jsonb_build_object('commande', v_cmd.id, 'commande_ht', v_cmd.montant_ht, 'facture_ht', v_f.montant_ht));
      else
        v_restant_montant := v_cmd.montant_ht - v_deja_montant;
        v_ecart_montant := v_f.montant_ht - v_restant_montant;
        v_tol_montant := greatest(coalesce(v_reglage.ecart_prix_montant, 0.05), v_cmd.montant_ht * coalesce(v_reglage.ecart_prix_pct, 0) / 100);
        perform private.filed_poser_resultat(v_f, 'rapprochement.montant', 'bloquant', v_ecart_montant > v_tol_montant,
          case when v_ecart_montant > v_tol_montant
               then format('Facture de %s HT pour %s restant à facturer sur la commande %s (%s commandé(s), %s déjà facturé(s)) : %s de trop.',
                           private.filed_montant_texte(v_f.montant_ht), private.filed_montant_texte(v_restant_montant), v_cmd.numero,
                           private.filed_montant_texte(v_cmd.montant_ht), private.filed_montant_texte(v_deja_montant),
                           private.filed_montant_texte(v_ecart_montant))
               else format('Facture de %s HT sur %s restant à facturer (commande %s de %s HT).',
                           private.filed_montant_texte(v_f.montant_ht), private.filed_montant_texte(v_restant_montant), v_cmd.numero,
                           private.filed_montant_texte(v_cmd.montant_ht)) end,
          'MONTANT_ERR', jsonb_build_object('commande', v_cmd.id, 'commande_ht', v_cmd.montant_ht, 'deja_facture', v_deja_montant,
                                            'restant', v_restant_montant, 'facture_ht', v_f.montant_ht, 'ecart', v_ecart_montant),
          v_cmd.id::text);
      end if;
    end if;

  -- ── Le bon de livraison seul, sans commande connue ──
  elsif v_recep.id is not null and v_nb_lignes > 0 and v_sens = 1 then
    v_mode := 'reception';
    for v_l in select l.* from public.filed_factures_lignes l where l.facture_id = v_f.id order by l.rang loop
      v_ql := null;
      select q.* into v_ql from public.filed_receptions_lignes q
      where q.reception_id = v_recep.id
        and not exists (select 1 from public.filed_rapprochements_lignes x where x.facture_id = v_f.id and x.reception_ligne_id = q.id)
        and ((private.filed_normaliser_numero(q.reference) is not null
              and private.filed_normaliser_numero(q.reference) in (private.filed_normaliser_numero(v_l.reference_vendeur),
                                                                    private.filed_normaliser_numero(v_l.reference_acheteur),
                                                                    private.filed_normaliser_numero(v_l.gtin)))
          or (coalesce(q.designation_normalisee, '') <> '' and q.designation_normalisee = private.filed_normaliser(v_l.designation)))
      order by q.rang limit 1;
      v_non_recu := case when v_ql.id is null then null else greatest(coalesce(v_l.quantite, 1) - v_ql.quantite, 0) end;
      insert into public.filed_rapprochements_lignes (client_id, facture_id, document_id, facture_ligne_id, reception_ligne_id, methode,
                                                      sens, quantite, prix_facture, quantite_recue, non_recu, non_recu_montant, resultat)
      values (v_f.client_id, v_f.id, v_f.document_id, v_l.id, v_ql.id,
              case when v_ql.id is null then 'aucune'
                   when private.filed_normaliser_numero(v_ql.reference) is not null
                        and private.filed_normaliser_numero(v_ql.reference) in (private.filed_normaliser_numero(v_l.reference_vendeur),
                              private.filed_normaliser_numero(v_l.reference_acheteur), private.filed_normaliser_numero(v_l.gtin))
                        then 'reference' else 'designation' end,
              1, v_l.quantite, v_l.prix_unitaire, v_ql.quantite, v_non_recu,
              round(coalesce(v_non_recu, 0) * coalesce(v_l.prix_unitaire, 0), 2),
              case when v_ql.id is null then 'sans_commande' when v_non_recu > 0.0000005 then 'non_recu' else 'ok' end);
      if v_non_recu > 0.0000005 then
        perform private.filed_poser_resultat(v_f, 'rapprochement.reception',
          case when coalesce(v_reglage.reception_exigee, false) then 'bloquant' else 'attention' end, true,
          format('ligne %s (%s) : %s facturé(s) pour %s reçu(s) sur le bon %s : %s non reçu(s), soit %s.',
                 v_l.rang, coalesce(left(v_l.designation, 60), v_l.reference_vendeur, '?'), private.filed_quantite_texte(v_l.quantite),
                 private.filed_quantite_texte(v_ql.quantite), coalesce(v_recep.numero, '?'), private.filed_quantite_texte(v_non_recu),
                 private.filed_montant_texte(round(v_non_recu * coalesce(v_l.prix_unitaire, 0), 2))),
          'LIVR_INCOMP', jsonb_build_object('reception', v_recep.id, 'reception_ligne', v_ql.id, 'facture_ligne', v_l.id,
                                            'quantite', v_l.quantite, 'recu', v_ql.quantite, 'non_recu', v_non_recu),
          v_ql.id::text);
      end if;
    end loop;
    select count(*) filter (where x.methode <> 'aucune'), count(*) filter (where x.methode = 'aucune'),
           coalesce(sum(x.non_recu_montant), 0),
           coalesce(array_agg(format('ligne %s (%s)', l.rang, coalesce(left(l.designation, 60), l.reference_vendeur, '?')) order by l.rang)
                    filter (where x.methode = 'aucune'), '{}')
    into v_nb_app, v_nb_sans, v_tot_non_recu, v_sans
    from public.filed_rapprochements_lignes x left join public.filed_factures_lignes l on l.id = x.facture_ligne_id
    where x.facture_id = v_f.id;
    perform private.filed_poser_resultat(v_f, 'rapprochement.lignes', 'attention', v_nb_sans > 0,
      case when v_nb_sans = 0 then format('Chaque ligne facturée figure sur le bon de livraison %s.', coalesce(v_recep.numero, '?'))
           else format('%s ligne(s) facturée(s) absente(s) du bon de livraison %s : %s.', v_nb_sans, coalesce(v_recep.numero, '?'),
                       array_to_string(v_sans, ', ')) end,
      'LIVR_INCOMP', jsonb_build_object('reception', v_recep.id, 'sans_reception', to_jsonb(v_sans)));
    if not exists (select 1 from public.filed_controles c where c.facture_id = v_f.id and c.code = 'rapprochement.reception' and c.resultat = 'anomalie') then
      perform private.filed_poser_resultat(v_f, 'rapprochement.reception', 'bloquant', false,
        format('Chaque ligne facturée a été reçue (bon %s).', coalesce(v_recep.numero, '?')));
    end if;
  end if;

  -- ── Ce que le rapprochement a trouvé ──
  insert into public.filed_rapprochements (client_id, facture_id, document_id, version, commande_id, commande_source, reception_id, mode,
                                           nb_lignes, nb_appariees, nb_sans_commande, ecart_prix, ecart_quantite, deja_facture,
                                           non_recu, ecart_montant, preuve)
  values (v_f.client_id, v_f.id, v_f.document_id, v_f.version, v_cmd.id, v_cmd_source, v_recep.id, v_mode,
          v_nb_lignes, v_nb_app, v_nb_sans, v_tot_prix, v_tot_qte, v_tot_deja, v_tot_non_recu, v_ecart_montant,
          jsonb_strip_nulls(jsonb_build_object('commande', v_cmd.numero, 'reception', v_recep.numero, 'facture_origine', v_origine.numero,
                                               'deja_facture_montant', v_deja_montant)));
  select to_jsonb(x) - 'id' - 'cree_le' - 'version' - 'preuve' into v_resume from public.filed_rapprochements x where x.facture_id = v_f.id;
  if v_resume is distinct from v_precedent then
    perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'rapprochee',
      case v_mode
        when 'lignes' then format('Rapprochée à la commande %s : %s ligne(s) sur %s appariée(s)%s.', v_cmd.numero, v_nb_app, v_nb_lignes,
          case when v_tot_prix <> 0 or v_tot_qte <> 0 or v_tot_deja <> 0 or v_tot_non_recu <> 0
               then format(' ; écarts : prix %s, quantité %s, déjà facturé %s, non reçu %s',
                           private.filed_montant_texte(v_tot_prix), private.filed_montant_texte(v_tot_qte),
                           private.filed_montant_texte(v_tot_deja), private.filed_montant_texte(v_tot_non_recu))
               else ', sans écart' end)
        when 'totaux' then format('Rapprochée à la commande %s sur les totaux%s.', v_cmd.numero,
          case when v_ecart_montant > 0 then ' : ' || private.filed_montant_texte(v_ecart_montant) || ' au-delà du reste à facturer' else '' end)
        when 'reception' then format('Rapprochée au bon de livraison %s : %s ligne(s) sur %s retrouvée(s).', coalesce(v_recep.numero, '?'), v_nb_app, v_nb_lignes)
        else case when v_sens = -1 and v_origine.id is not null then format('Avoir rattaché à la facture %s.', v_origine.numero)
                  else 'Sans commande ni bon de livraison connus : rien à rapprocher.' end end,
      jsonb_strip_nulls(jsonb_build_object('mode', v_mode, 'commande', v_cmd.id, 'reception', v_recep.id, 'facture_origine', v_origine.id)));
  end if;
end $$;


--
-- Name: filed_commandes_lignes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_commandes_lignes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    commande_id uuid NOT NULL,
    rang smallint NOT NULL,
    numero text,
    reference text,
    reference_acheteur text,
    gtin text,
    designation text,
    designation_normalisee text,
    quantite numeric(18,6) NOT NULL,
    unite text,
    prix_unitaire numeric(18,6),
    montant_ht numeric(14,2),
    source text NOT NULL,
    CONSTRAINT filed_commandes_lignes_designation_check CHECK ((char_length(designation) <= 500)),
    CONSTRAINT filed_commandes_lignes_gtin_check CHECK ((char_length(gtin) <= 40)),
    CONSTRAINT filed_commandes_lignes_numero_check CHECK ((char_length(numero) <= 60)),
    CONSTRAINT filed_commandes_lignes_prix_unitaire_check CHECK ((prix_unitaire >= (0)::numeric)),
    CONSTRAINT filed_commandes_lignes_quantite_check CHECK ((quantite >= (0)::numeric)),
    CONSTRAINT filed_commandes_lignes_rang_check CHECK ((rang >= 1)),
    CONSTRAINT filed_commandes_lignes_reference_acheteur_check CHECK ((char_length(reference_acheteur) <= 100)),
    CONSTRAINT filed_commandes_lignes_reference_check CHECK ((char_length(reference) <= 100)),
    CONSTRAINT filed_commandes_lignes_source_check CHECK ((source = ANY (ARRAY['xml'::text, 'regle'::text, 'ia'::text, 'humain'::text, 'tableur'::text, 'import'::text, 'saisie'::text]))),
    CONSTRAINT filed_commandes_lignes_unite_check CHECK ((char_length(unite) <= 20))
);


--
-- Name: filed_factures_lignes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_factures_lignes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    facture_id uuid NOT NULL,
    document_id uuid NOT NULL,
    rang smallint NOT NULL,
    numero text,
    reference_vendeur text,
    reference_acheteur text,
    gtin text,
    designation text,
    quantite numeric(18,6),
    unite text,
    prix_unitaire numeric(18,6),
    prix_brut numeric(18,6),
    remise numeric(14,2),
    montant_ht numeric(14,2),
    taux_tva numeric(6,3),
    categorie_tva text,
    commande_ligne text,
    source text NOT NULL,
    CONSTRAINT filed_factures_lignes_categorie_tva_check CHECK ((char_length(categorie_tva) <= 5)),
    CONSTRAINT filed_factures_lignes_commande_ligne_check CHECK ((char_length(commande_ligne) <= 60)),
    CONSTRAINT filed_factures_lignes_designation_check CHECK ((char_length(designation) <= 500)),
    CONSTRAINT filed_factures_lignes_gtin_check CHECK ((char_length(gtin) <= 40)),
    CONSTRAINT filed_factures_lignes_numero_check CHECK ((char_length(numero) <= 60)),
    CONSTRAINT filed_factures_lignes_rang_check CHECK ((rang >= 1)),
    CONSTRAINT filed_factures_lignes_reference_acheteur_check CHECK ((char_length(reference_acheteur) <= 100)),
    CONSTRAINT filed_factures_lignes_reference_vendeur_check CHECK ((char_length(reference_vendeur) <= 100)),
    CONSTRAINT filed_factures_lignes_source_check CHECK ((source = ANY (ARRAY['xml'::text, 'regle'::text, 'ia'::text, 'humain'::text, 'tableur'::text]))),
    CONSTRAINT filed_factures_lignes_unite_check CHECK ((char_length(unite) <= 20))
);


--
-- Name: filed_rapprochements_lignes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_rapprochements_lignes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    facture_id uuid NOT NULL,
    document_id uuid NOT NULL,
    facture_ligne_id uuid,
    commande_ligne_id uuid,
    reception_ligne_id uuid,
    methode text NOT NULL,
    sens smallint DEFAULT 1 NOT NULL,
    quantite numeric(18,6),
    prix_facture numeric(18,6),
    prix_commande numeric(18,6),
    ecart_prix_unitaire numeric(18,6),
    ecart_prix numeric(14,2) DEFAULT 0 NOT NULL,
    quantite_commandee numeric(18,6),
    deja_facture numeric(18,6),
    quantite_recue numeric(18,6),
    ecart_quantite numeric(18,6),
    ecart_quantite_montant numeric(14,2) DEFAULT 0 NOT NULL,
    non_recu numeric(18,6),
    non_recu_montant numeric(14,2) DEFAULT 0 NOT NULL,
    resultat text NOT NULL,
    CONSTRAINT filed_rapprochements_lignes_methode_check CHECK ((methode = ANY (ARRAY['humain'::text, 'commande_ligne'::text, 'reference'::text, 'gtin'::text, 'designation'::text, 'seule'::text, 'totaux'::text, 'aucune'::text]))),
    CONSTRAINT filed_rapprochements_lignes_resultat_check CHECK ((resultat = ANY (ARRAY['ok'::text, 'ecart_prix'::text, 'ecart_quantite'::text, 'deja_facture'::text, 'non_recu'::text, 'sans_commande'::text, 'avoir_trop'::text]))),
    CONSTRAINT filed_rapprochements_lignes_sens_check CHECK ((sens = ANY (ARRAY[1, '-1'::integer])))
);


--
-- Name: filed_reglages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.filed_reglages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid,
    actif boolean DEFAULT true NOT NULL,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    tolerance_totaux numeric(8,2) DEFAULT 0.05 NOT NULL,
    doublon_fenetre_jours smallint DEFAULT 3 NOT NULL,
    seuil_mentions_ht numeric(14,2) DEFAULT 150 NOT NULL,
    ecart_prix_pct numeric(6,3) DEFAULT 0 NOT NULL,
    ecart_prix_montant numeric(14,2) DEFAULT 0.05 NOT NULL,
    ecart_quantite_pct numeric(6,3) DEFAULT 0 NOT NULL,
    commande_exigee boolean DEFAULT false NOT NULL,
    commande_exigee_des_ht numeric(14,2) DEFAULT 0 NOT NULL,
    reception_exigee boolean DEFAULT false NOT NULL,
    CONSTRAINT filed_reglages_commande_exigee_des_ht_check CHECK ((commande_exigee_des_ht >= (0)::numeric)),
    CONSTRAINT filed_reglages_doublon_fenetre_jours_check CHECK (((doublon_fenetre_jours >= 0) AND (doublon_fenetre_jours <= 60))),
    CONSTRAINT filed_reglages_ecart_prix_montant_check CHECK (((ecart_prix_montant >= (0)::numeric) AND (ecart_prix_montant <= (1000)::numeric))),
    CONSTRAINT filed_reglages_ecart_prix_pct_check CHECK (((ecart_prix_pct >= (0)::numeric) AND (ecart_prix_pct <= (100)::numeric))),
    CONSTRAINT filed_reglages_ecart_quantite_pct_check CHECK (((ecart_quantite_pct >= (0)::numeric) AND (ecart_quantite_pct <= (100)::numeric))),
    CONSTRAINT filed_reglages_seuil_mentions_ht_check CHECK ((seuil_mentions_ht >= (0)::numeric)),
    CONSTRAINT filed_reglages_tolerance_totaux_check CHECK (((tolerance_totaux >= (0)::numeric) AND (tolerance_totaux <= (5)::numeric)))
);


--
-- Name: filed_rapprocher_ligne(public.filed_factures, public.filed_factures_lignes, public.filed_commandes_lignes, text, smallint, public.filed_reglages, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_rapprocher_ligne(p_f public.filed_factures, p_l public.filed_factures_lignes, p_c public.filed_commandes_lignes, p_methode text, p_sens smallint, p_reglage public.filed_reglages, p_a_reception boolean) RETURNS public.filed_rapprochements_lignes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qte numeric := coalesce(p_l.quantite, 1);
  v_prix_f numeric;
  v_prix_c numeric := p_c.prix_unitaire;
  v_deja numeric;
  v_recu numeric;
  v_restant numeric;
  v_ecart_pu numeric;
  v_ecart_prix numeric := 0;
  v_ecart_qte numeric := 0;
  v_ecart_qte_montant numeric := 0;
  v_non_recu numeric := 0;
  v_non_recu_montant numeric := 0;
  v_prix_ok boolean := true;
  v_qte_ok boolean := true;
  v_resultat text := 'ok';
  v_libelle text;
  v_autres jsonb;
  v_x public.filed_rapprochements_lignes;
  v_preuve jsonb;
begin
  v_prix_f := coalesce(p_l.prix_unitaire, case when coalesce(p_l.quantite, 0) <> 0 then p_l.montant_ht / p_l.quantite end);
  select coalesce(sum(x.sens * x.quantite), 0), coalesce(jsonb_agg(distinct f2.numero) filter (where f2.numero is not null), '[]'::jsonb)
    into v_deja, v_autres
  from public.filed_rapprochements_lignes x join public.filed_factures f2 on f2.id = x.facture_id
  where x.commande_ligne_id = p_c.id and x.facture_id <> p_f.id and f2.statut <> 'ecartee';
  select coalesce(sum(q.quantite), 0) into v_recu
  from public.filed_receptions_lignes q join public.filed_receptions rc on rc.id = q.reception_id
  where q.commande_ligne_id = p_c.id and rc.statut = 'enregistree';
  v_restant := p_c.quantite - v_deja;
  v_libelle := format('ligne %s (%s)', p_l.rang, coalesce(left(p_l.designation, 60), p_l.reference_vendeur, p_l.numero, '?'));

  if p_sens = 1 then
    if v_prix_f is not null and v_prix_c is not null then
      v_ecart_pu := v_prix_f - v_prix_c;
      v_ecart_prix := round(v_ecart_pu * v_qte, 2);
      v_prix_ok := abs(v_ecart_pu) <= v_prix_c * coalesce(p_reglage.ecart_prix_pct, 0) / 100 + 0.0000005
                   or abs(v_ecart_prix) <= coalesce(p_reglage.ecart_prix_montant, 0.05);
    end if;
    v_ecart_qte := v_qte - v_restant;
    v_qte_ok := v_ecart_qte <= p_c.quantite * coalesce(p_reglage.ecart_quantite_pct, 0) / 100 + 0.0000005;
    v_ecart_qte_montant := round(greatest(v_ecart_qte, 0) * coalesce(v_prix_c, v_prix_f, 0), 2);
    if p_a_reception or coalesce(p_reglage.reception_exigee, false) then
      v_non_recu := greatest(v_deja + v_qte - v_recu, 0);
      v_non_recu_montant := round(v_non_recu * coalesce(v_prix_c, v_prix_f, 0), 2);
    end if;
    v_resultat := case when v_restant <= 0.0000005 then 'deja_facture'
                       when not v_qte_ok then 'ecart_quantite'
                       when not v_prix_ok then 'ecart_prix'
                       when v_non_recu > 0.0000005 then 'non_recu'
                       else 'ok' end;
  else
    -- Un avoir rend de la quantité : pas plus que ce qui a été facturé.
    v_ecart_qte := v_qte - greatest(v_deja, 0);
    v_resultat := case when v_ecart_qte > 0.0000005 then 'avoir_trop' else 'ok' end;
  end if;

  insert into public.filed_rapprochements_lignes (
    client_id, facture_id, document_id, facture_ligne_id, commande_ligne_id, methode, sens, quantite, prix_facture,
    prix_commande, ecart_prix_unitaire, ecart_prix, quantite_commandee, deja_facture, quantite_recue, ecart_quantite,
    ecart_quantite_montant, non_recu, non_recu_montant, resultat)
  values (p_f.client_id, p_f.id, p_f.document_id, p_l.id, p_c.id, p_methode, p_sens, v_qte, v_prix_f, v_prix_c, v_ecart_pu,
          v_ecart_prix, p_c.quantite, v_deja, v_recu, v_ecart_qte, v_ecart_qte_montant, v_non_recu, v_non_recu_montant,
          v_resultat)
  returning * into v_x;

  -- Les contrôles de la ligne, chacun avec sa preuve ; la clé est la ligne commandée.
  v_preuve := jsonb_build_object('facture_ligne', p_l.id, 'commande_ligne', p_c.id, 'rang', p_l.rang, 'quantite', v_qte,
                                 'commande', p_c.quantite, 'deja_facture', v_deja, 'recu', v_recu, 'prix_facture', v_prix_f,
                                 'prix_commande', v_prix_c, 'autres_factures', v_autres, 'methode', p_methode);
  if p_sens = 1 then
    if v_resultat = 'deja_facture' then
      perform private.filed_poser_resultat(p_f, 'rapprochement.deja_facture', 'bloquant', true,
        format('%s : déjà facturée en totalité (%s sur %s commandé(s)%s).', v_libelle, private.filed_quantite_texte(v_deja),
               private.filed_quantite_texte(p_c.quantite),
               case when v_autres <> '[]'::jsonb then ', par ' || (select string_agg(x, ', ') from jsonb_array_elements_text(v_autres) x) else '' end),
        'DOUBLON', v_preuve, p_c.id::text);
    elsif not v_qte_ok then
      perform private.filed_poser_resultat(p_f, 'rapprochement.quantite', 'bloquant', true,
        format('%s : %s facturé(s) pour %s restant à facturer (%s commandé(s), %s déjà facturé(s)) : %s de trop, soit %s.',
               v_libelle, private.filed_quantite_texte(v_qte), private.filed_quantite_texte(v_restant),
               private.filed_quantite_texte(p_c.quantite), private.filed_quantite_texte(v_deja),
               private.filed_quantite_texte(v_ecart_qte), private.filed_montant_texte(v_ecart_qte_montant)),
        'QTE_ERR', v_preuve || jsonb_build_object('ecart', v_ecart_qte, 'ecart_montant', v_ecart_qte_montant), p_c.id::text);
    end if;
    if not v_prix_ok then
      perform private.filed_poser_resultat(p_f, 'rapprochement.prix', case when v_ecart_pu > 0 then 'bloquant' else 'attention' end, true,
        format('%s : prix facturé %s au lieu de %s commandé, soit %s %s sur la ligne.', v_libelle,
               private.filed_montant_texte(v_prix_f), private.filed_montant_texte(v_prix_c),
               private.filed_montant_texte(abs(v_ecart_prix)), case when v_ecart_pu > 0 then 'de trop' else 'de moins' end),
        'PU_ERR', v_preuve || jsonb_build_object('ecart_unitaire', v_ecart_pu, 'ecart', v_ecart_prix), p_c.id::text);
    end if;
    if v_non_recu > 0.0000005 then
      perform private.filed_poser_resultat(p_f, 'rapprochement.reception',
        case when coalesce(p_reglage.reception_exigee, false) then 'bloquant' else 'attention' end, true,
        format('%s : %s facturé(s) au total pour %s reçu(s) : %s non reçu(s), soit %s.', v_libelle,
               private.filed_quantite_texte(v_deja + v_qte), private.filed_quantite_texte(v_recu),
               private.filed_quantite_texte(v_non_recu), private.filed_montant_texte(v_non_recu_montant)),
        'LIVR_INCOMP', v_preuve || jsonb_build_object('non_recu', v_non_recu, 'non_recu_montant', v_non_recu_montant), p_c.id::text);
    end if;
  elsif v_resultat = 'avoir_trop' then
    perform private.filed_poser_resultat(p_f, 'avoir.quantite', 'attention', true,
      format('%s : l''avoir rend %s alors que %s seulement ont été facturé(s) sur cette ligne commandée.', v_libelle,
             private.filed_quantite_texte(v_qte), private.filed_quantite_texte(greatest(v_deja, 0))),
      'MONTANT_ERR', v_preuve, p_c.id::text);
  end if;
  return v_x;
end $$;


--
-- Name: filed_rattacher_commande(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_rattacher_commande(p_facture uuid, p_commande uuid, p_motif text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_c public.filed_commandes;
begin
  v_f := private.filed_exiger_facture(p_facture, array['gerant', 'admin', 'valideur', 'collaborateur']);
  if p_commande is not null then
    select * into v_c from public.filed_commandes where id = p_commande and client_id = v_f.client_id;
    if not found then
      raise exception 'Commande introuvable dans cette organisation.' using errcode = 'P0002';
    end if;
  end if;
  update public.filed_factures set commande_force = p_commande, maj_le = now() where id = v_f.id;
  perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'commande_designee',
    case when p_commande is null then 'Commande laissée à FILED par une personne'
         else format('Commande désignée par une personne : %s', v_c.numero) end
      || coalesce(' (' || nullif(btrim(p_motif), '') || ')', '') || '.',
    jsonb_strip_nulls(jsonb_build_object('commande', p_commande)));
  return private.filed_controler_facture(v_f.id);
end $$;


--
-- Name: filed_rattacher_fournisseur(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_rattacher_fournisseur(p_facture uuid, p_fournisseur uuid, p_motif text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_four public.filed_fournisseurs;
  v_ancien public.filed_fournisseurs;
begin
  v_f := private.filed_exiger_facture(p_facture, array['gerant', 'admin', 'valideur', 'collaborateur']);
  select * into v_four from public.filed_fournisseurs where id = p_fournisseur and client_id = v_f.client_id;
  if not found then
    raise exception 'Fournisseur introuvable dans cette organisation.' using errcode = 'P0002';
  end if;
  if v_four.statut = 'refuse' then
    raise exception 'Ce fournisseur a été refusé par une personne.' using errcode = '55000';
  end if;

  -- Le fournisseur né de cette seule lecture, s'il n'est pas le bon, s'en va avec elle.
  if v_f.fournisseur_id is not null and v_f.fournisseur_id <> v_four.id then
    select * into v_ancien from public.filed_fournisseurs where id = v_f.fournisseur_id for update;
    if v_ancien.statut = 'a_confirmer' and v_ancien.document_origine = v_f.document_id
       and not exists (select 1 from public.filed_factures x where x.fournisseur_id = v_ancien.id and x.id <> v_f.id) then
      update public.filed_fournisseurs
         set statut = 'refuse', maj_le = now(),
             motif = left('Né d''une lecture : c''était ' || private.filed_libelle_fournisseur(v_four) || '.', 500)
       where id = v_ancien.id;
      update public.filed_fournisseurs_ibans set statut = 'revoque', decide_le = now(), motif = 'Fournisseur né d''une lecture, écarté.'
       where fournisseur_id = v_ancien.id and statut = 'propose';
      update public.demandes_validation set statut = 'annulee'
       where client_id = v_f.client_id and type_action = 'filed.valider_fournisseur'
         and objet_id = v_ancien.id::text and statut = 'en_attente';
      perform private.filed_historiser(v_f.client_id, null, 'filed_fournisseur', v_ancien.id::text, 'refuse',
        'Né d''une lecture, écarté : une personne a désigné ' || private.filed_libelle_fournisseur(v_four) || '.',
        jsonb_build_object('document', v_f.document_id, 'remplace_par', v_four.id));
    end if;
  end if;

  update public.filed_factures set fournisseur_force = v_four.id, empreinte_donnees = null, maj_le = now() where id = v_f.id;
  perform private.filed_historiser(v_f.client_id, v_f.document_id, 'filed_document', v_f.document_id::text, 'fournisseur_designe',
    format('Fournisseur désigné par une personne : %s%s.', private.filed_libelle_fournisseur(v_four),
           coalesce(' (' || nullif(btrim(p_motif), '') || ')', '')),
    jsonb_build_object('fournisseur', v_four.id));
  return private.filed_integrer_facture(v_f.document_id);
end $$;


--
-- Name: filed_reconnaitre_fournisseur(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_reconnaitre_fournisseur(p_client uuid, p_identite jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_n integer;
begin
  if p_identite ? 'siren' then
    select f.id into v_id from public.filed_fournisseurs f
    where f.client_id = p_client and f.siren = p_identite ->> 'siren' and f.statut <> 'refuse';
  end if;
  if v_id is null and p_identite ? 'tva' then
    select f.id into v_id from public.filed_fournisseurs f
    where f.client_id = p_client and f.tva = p_identite ->> 'tva' and f.statut <> 'refuse';
  end if;
  if v_id is null and p_identite ? 'id_etranger' then
    select f.id into v_id from public.filed_fournisseurs f
    where f.client_id = p_client and f.id_etranger = p_identite ->> 'id_etranger' and f.statut <> 'refuse';
  end if;
  if v_id is null and coalesce(private.filed_normaliser_nom(p_identite ->> 'nom'), '') <> '' then
    select count(*), min(f.id::text)::uuid into v_n, v_id from public.filed_fournisseurs f
    where f.client_id = p_client and f.nom_normalise = private.filed_normaliser_nom(p_identite ->> 'nom')
      and f.statut <> 'refuse';
    if v_n <> 1 then
      v_id := null;
    end if;
  end if;
  return v_id;
end $$;


--
-- Name: filed_recontroler_commande(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_recontroler_commande(p_commande uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_c public.filed_commandes;
  r record;
  n integer := 0;
begin
  select * into v_c from public.filed_commandes where id = p_commande;
  if not found then
    return 0;
  end if;
  for r in select f.id from public.filed_factures f
           where f.client_id = v_c.client_id and f.statut in ('a_completer', 'bloquee', 'a_valider')
             and (f.commande_id = v_c.id or f.commande_force = v_c.id
                  or (f.commande_id is null and private.filed_normaliser_numero(f.refs ->> 'commande') = v_c.numero_normalise))
           order by f.cree_le limit 500
  loop
    perform private.filed_controler_facture(r.id);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: filed_recontroler_fournisseur(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_recontroler_fournisseur(p_fournisseur uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  n integer := 0;
begin
  for r in select f.id from public.filed_factures f
           where f.fournisseur_id = p_fournisseur and f.statut in ('a_completer', 'bloquee', 'a_valider')
           order by f.cree_le limit 500
  loop
    perform private.filed_controler_facture(r.id);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: filed_recontroler_reception(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_recontroler_reception(p_reception uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public.filed_receptions;
  r record;
  n integer := 0;
begin
  select * into v_r from public.filed_receptions where id = p_reception;
  if not found then
    return 0;
  end if;
  if v_r.commande_id is not null then
    return private.filed_recontroler_commande(v_r.commande_id);
  end if;
  for r in select f.id from public.filed_factures f
           where f.client_id = v_r.client_id and f.statut in ('a_completer', 'bloquee', 'a_valider')
             and v_r.numero_normalise is not null
             and private.filed_normaliser_numero(f.refs ->> 'livraison') = v_r.numero_normalise
             and (v_r.fournisseur_id is null or f.fournisseur_id = v_r.fournisseur_id)
           order by f.cree_le limit 500
  loop
    perform private.filed_controler_facture(r.id);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: filed_regime_territorial(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_regime_territorial(p_client uuid, p_entite uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_iso text;
  v_calendrier text;
begin
  with recursive chaine (id, parent_id, territoire, rang) as (
    select e.id, e.parent_id, e.territoire, 0
    from public.entites e where e.client_id = p_client and e.id = p_entite
    union all
    select p.id, p.parent_id, p.territoire, c.rang + 1
    from chaine c join public.entites p on p.client_id = p_client and p.id = c.parent_id
    where c.territoire is null and c.rang < 32
  )
  select c.territoire into v_iso from chaine c where c.territoire is not null order by c.rang limit 1;
  if v_iso is null then
    return null;
  end if;
  if upper(v_iso) in ('FR-2A', 'FR-2B', 'FR-20R', 'FR-COR') then
    return 'corse';
  end if;
  v_calendrier := public.territoire_calendrier(v_iso);
  return case
    when v_calendrier in ('metropole', 'alsace-moselle') then 'metropole'
    when v_calendrier in ('guadeloupe', 'martinique', 'la-reunion') then 'dom'
    when v_calendrier is not null then 'sans_tva'
  end;
end $$;


--
-- Name: filed_reglage(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_reglage(p_client uuid, p_entite uuid) RETURNS public.filed_reglages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.* from public.filed_reglages r
  where r.client_id = p_client and (r.entite_id = p_entite or r.entite_id is null)
  order by (r.entite_id is not null) desc
  limit 1
$$;


--
-- Name: filed_regler_commande(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_regler_commande(p_commande uuid, p_statut text, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_c public.filed_commandes;
begin
  select * into v_c from public.filed_commandes where id = p_commande for update;
  if not found then
    raise exception 'Commande introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_c.client_id, array['gerant', 'admin', 'valideur'], v_c.entite_id);
  if p_statut not in ('ouverte', 'soldee', 'annulee') then
    raise exception 'Une commande est ouverte, soldée ou annulée.' using errcode = '22023';
  end if;
  if nullif(btrim(p_motif), '') is null then
    raise exception 'Dites pourquoi.' using errcode = '22023';
  end if;
  update public.filed_commandes set statut = p_statut, motif = left(btrim(p_motif), 500), maj_le = now() where id = v_c.id;
  perform private.filed_historiser(v_c.client_id, null, 'filed_commande', v_c.id::text, p_statut,
    format('Commande %s %s par une personne : %s', v_c.numero,
           case p_statut when 'soldee' then 'soldée' when 'annulee' then 'annulée' else 'rouverte' end, left(btrim(p_motif), 300)),
    '{}'::jsonb);
  perform private.filed_recontroler_commande(v_c.id);
end $$;


--
-- Name: filed_regler_fournisseur(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_regler_fournisseur(p_fournisseur uuid, p_reglages jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_f public.filed_fournisseurs;
begin
  select * into v_f from public.filed_fournisseurs where id = p_fournisseur for update;
  if not found then
    raise exception 'Fournisseur introuvable.' using errcode = 'P0002';
  end if;
  perform private.filed_exiger_acteur(v_f.client_id, array['gerant', 'admin', 'valideur'], null);
  if p_reglages ? 'iban' then
    raise exception 'Un IBAN se propose, puis se valide par une autre personne.' using errcode = '22023';
  end if;
  update public.filed_fournisseurs
     set nom = coalesce(left(nullif(btrim(p_reglages ->> 'nom'), ''), 200), nom),
         nom_normalise = private.filed_normaliser_nom(coalesce(nullif(btrim(p_reglages ->> 'nom'), ''), nom)),
         code = coalesce(nullif(upper(btrim(p_reglages ->> 'code')), ''), code),
         regime_tva = case when p_reglages ? 'regime_tva' then nullif(p_reglages ->> 'regime_tva', '') else regime_tva end,
         pays = coalesce(nullif(upper(btrim(p_reglages ->> 'pays')), ''), pays),
         maj_le = now()
   where id = v_f.id;
  perform private.filed_historiser(v_f.client_id, null, 'filed_fournisseur', v_f.id::text, 'regle',
    'Fournisseur réglé par une personne : ' || (select string_agg(k, ', ') from jsonb_object_keys(p_reglages) k) || '.',
    jsonb_build_object('champs', (select jsonb_agg(k) from jsonb_object_keys(p_reglages) k)));
  perform private.filed_recontroler_fournisseur(v_f.id);
end $$;


--
-- Name: filed_resoudre_fournisseur(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_resoudre_fournisseur(p_facture uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public.filed_factures;
  v_id uuid;
  v_methode text;
  v_ident jsonb;
  v_four public.filed_fournisseurs;
  v_n integer;
begin
  select * into v_f from public.filed_factures where id = p_facture for update;
  v_ident := v_f.fournisseur_lu;
  if v_f.fournisseur_force is not null then
    v_id := v_f.fournisseur_force;
    v_methode := 'humain';
  else
    if v_ident ? 'siren' then
      select f.id into v_id from public.filed_fournisseurs f
      where f.client_id = v_f.client_id and f.siren = v_ident ->> 'siren';
      v_methode := 'siren';
    end if;
    if v_id is null and v_ident ? 'tva' then
      select f.id into v_id from public.filed_fournisseurs f
      where f.client_id = v_f.client_id and f.tva = v_ident ->> 'tva';
      v_methode := 'tva';
    end if;
    if v_id is null and v_ident ? 'id_etranger' then
      select f.id into v_id from public.filed_fournisseurs f
      where f.client_id = v_f.client_id and f.id_etranger = v_ident ->> 'id_etranger';
      v_methode := 'id_etranger';
    end if;
    if v_id is null and coalesce(private.filed_normaliser_nom(v_ident ->> 'nom'), '') <> '' then
      select count(*), min(f.id::text)::uuid into v_n, v_id from public.filed_fournisseurs f
      where f.client_id = v_f.client_id and f.nom_normalise = private.filed_normaliser_nom(v_ident ->> 'nom')
        and (f.siren is null or not (v_ident ? 'siren') or f.siren = v_ident ->> 'siren')
        and (f.tva is null or not (v_ident ? 'tva') or f.tva = v_ident ->> 'tva');
      if v_n <> 1 then
        v_id := null;
      end if;
      v_methode := 'nom';
    end if;
    if v_id is null and (v_ident ?| array['siren', 'tva', 'id_etranger']
                         or coalesce(private.filed_normaliser_nom(v_ident ->> 'nom'), '') <> '') then
      -- Une seule création à la fois par organisation : deux factures du même
      -- fournisseur nouveau n'en créent pas deux.
      perform pg_advisory_xact_lock(hashtextextended('filed.fournisseur:' || v_f.client_id::text, 0));
      select f.id into v_id from public.filed_fournisseurs f
      where f.client_id = v_f.client_id
        and ((v_ident ? 'siren' and f.siren = v_ident ->> 'siren')
          or (v_ident ? 'tva' and f.tva = v_ident ->> 'tva')
          or (v_ident ? 'id_etranger' and f.id_etranger = v_ident ->> 'id_etranger'))
      limit 1;
      if v_id is null then
        v_four := private.filed_creer_fournisseur(v_f.client_id,
                    v_ident || case when v_f.iban is not null then jsonb_build_object('iban', v_f.iban) else '{}'::jsonb end,
                    'facture', v_f.document_id);
        v_id := v_four.id;
        v_methode := 'creation';
      else
        v_methode := case when v_ident ? 'siren' then 'siren' when v_ident ? 'tva' then 'tva' else 'id_etranger' end;
      end if;
    end if;
  end if;

  update public.filed_factures set fournisseur_id = v_id, fournisseur_identification = case when v_id is null then null else v_methode end
  where id = p_facture;

  if v_id is not null and v_f.iban is not null and private.filed_iban_valide(v_f.iban) then
    perform private.filed_proposer_iban(v_id, v_f.iban, 'facture', v_f.document_id);
  end if;
  return v_id;
end $$;


--
-- Name: filed_siren_valide(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_siren_valide(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select coalesce(p ~ '^[0-9]{9}$' and private.filed_luhn(p), false)
$_$;


--
-- Name: filed_tache(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_tache() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.filed_traiter(200)
$$;


--
-- Name: filed_texte(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_texte(p jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case jsonb_typeof(p)
    when 'string' then nullif(btrim(p #>> '{}'), '')
    when 'number' then p::text
    else null end
$$;


--
-- Name: filed_traiter(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_traiter(p_nombre integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  t public.travaux;
  r record;
  v_issue text;
  v_err text;
  n_faits integer := 0;
  n_decisions integer := 0;
  n_ignores integer := 0;
  n_rendus integer := 0;
  n_balayes integer := 0;
  n_battements integer := 0;
begin
  perform set_config('omega.module', 'filed', true);

  for t in select * from private.prendre_travaux(array['filed.integrer', 'filed.decision'],
                                                  greatest(1, least(coalesce(p_nombre, 200), 500)),
                                                  interval '5 minutes', 'filed')
  loop
    begin
      if t.genre = 'filed.decision' then
        v_issue := private.filed_executer_decision(t.charge);
        perform private.finir_travail(t.id, jsonb_build_object('issue', v_issue));
        n_decisions := n_decisions + 1;
      elsif coalesce(t.charge ->> 'module', 'filed') <> 'filed' then
        perform private.finir_travail(t.id, jsonb_build_object('ignore', 'pièce d''un autre module'));
        n_ignores := n_ignores + 1;
      elsif coalesce(t.charge ->> 'piece', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        perform private.finir_travail(t.id, jsonb_build_object('ignore', 'travail sans pièce'));
        n_ignores := n_ignores + 1;
      else
        v_issue := private.filed_integrer_piece((t.charge ->> 'piece')::uuid);
        perform private.finir_travail(t.id, jsonb_build_object('issue', v_issue));
        n_faits := n_faits + 1;
      end if;
    exception when others then
      get stacked diagnostics v_err = message_text;
      begin
        perform private.echouer_travail(t.id, 'FILED : ' || v_err);
      exception when others then
        raise warning 'FILED : travail % non rendu (%)', t.id, sqlerrm;
      end;
      n_rendus := n_rendus + 1;
    end;
  end loop;

  -- Les pièces au bout de leur lecture que l'événement n'a pas apportées, et
  -- les factures et avoirs reçus avant le moteur des factures.
  for r in
    select d.piece_id from public.filed_documents d join public.pieces p on p.id = d.piece_id
    where (d.etat = 'en_lecture' and p.statut in ('lue', 'a_verifier', 'a_classer', 'rejetee', 'echec'))
       or (d.etat = 'a_traiter' and d.nature in ('facture', 'avoir')
           and not exists (select 1 from public.filed_factures f where f.document_id = d.id))
       or (d.etat = 'a_traiter' and d.nature = 'bon_commande'
           and not exists (select 1 from public.filed_commandes c where c.document_id = d.id))
       or (d.etat = 'a_traiter' and d.nature = 'bon_livraison'
           and not exists (select 1 from public.filed_receptions rc where rc.document_id = d.id))
    order by d.recu_le
    limit 500
  loop
    begin
      perform private.filed_integrer_piece(r.piece_id);
      n_balayes := n_balayes + 1;
    exception when others then
      raise warning 'FILED : pièce % non intégrée (%)', r.piece_id, sqlerrm;
    end;
  end loop;

  -- La preuve de vie de chaque moteur, par organisation, toutes les cinq minutes au plus.
  for r in
    select g.client_id, m.moteur from public.filed_reglages g
    cross join (values ('filed_reception'), ('filed_factures')) as m(moteur)
    left join public.battements b on b.client_id = g.client_id and b.module = m.moteur
    where g.entite_id is null and g.actif and (b.dernier_le is null or b.dernier_le < now() - interval '5 minutes')
  loop
    perform private.battre(r.client_id, r.moteur, jsonb_build_object('source', 'omega-filed'), null);
    n_battements := n_battements + 1;
  end loop;

  return jsonb_build_object('travaux', n_faits, 'decisions', n_decisions, 'ignores', n_ignores, 'rendus', n_rendus,
                            'balayes', n_balayes, 'battements', n_battements);
end $_$;


--
-- Name: filed_tva_fr_valide(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_tva_fr_valide(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v text := upper(regexp_replace(coalesce(p, ''), '[\s.\-]', '', 'g'));
  m text[];
begin
  m := regexp_match(v, '^FR([0-9A-Z]{2})([0-9]{9})$');
  if m is null or not private.filed_siren_valide(m[2]) then
    return false;
  end if;
  if m[1] ~ '^[0-9]{2}$' then
    return m[1]::integer = (12 + 3 * (m[2]::bigint % 97)) % 97;
  end if;
  return true;
end $_$;


--
-- Name: filed_valeurs(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.filed_valeurs(p_piece uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with scalaires as (
    select distinct on (pv.champ) pv.champ, pv.valeur, pv.verifiee, pv.source, pv.texte, pv.page, pv.controle
    from public.pieces_valeurs pv
    where pv.piece_id = p_piece and pv.champ <> 'lignes'
    order by pv.champ, (pv.source = 'humain') desc, pv.cree_le desc, pv.id desc
  ), lignes as (
    select 'lignes'::text as champ,
           jsonb_agg(e.ligne order by pv.page nulls last, pv.cree_le, pv.id, e.n) as valeur,
           bool_and(pv.verifiee) as verifiee, min(pv.source) as source, null::text as texte,
           min(pv.page) as page, null::text as controle
    from public.pieces_valeurs pv
    cross join lateral jsonb_array_elements(case when jsonb_typeof(pv.valeur) = 'array' then pv.valeur
                                                 else '[]'::jsonb end) with ordinality as e(ligne, n)
    where pv.piece_id = p_piece and pv.champ = 'lignes'
      and (pv.source = 'humain'
           or not exists (select 1 from public.pieces_valeurs h
                          where h.piece_id = p_piece and h.champ = 'lignes' and h.source = 'humain'))
    having count(*) > 0
  )
  select coalesce(jsonb_object_agg(x.champ, jsonb_build_object(
      'valeur', x.valeur, 'sure', x.verifiee or x.source = 'humain', 'source', x.source,
      'texte', x.texte, 'page', x.page, 'controle', x.controle)), '{}'::jsonb)
  from (select * from scalaires union all select * from lignes) x
$$;


--
-- Name: finaliser_instantane(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finaliser_instantane(p_instantane uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET enable_nestloop TO 'off'
    SET work_mem TO '32MB'
    AS $$
declare
  i public.instantanes;
  j public.branchements_jeux;
  b public.branchements;
  c public.instantanes;
  v_complet boolean;
  v_fenetre jsonb;
  v_col text;
  v_du date;
  v_au date;
  v_base integer;
  v_absents integer := 0;
  v_ajouts integer := 0;
  v_modifs integer := 0;
  v_disp integer := 0;
  v_absentes text[];
  v_sensibles text[];
  v_raison text;
  v_garde jsonb;
begin
  select * into i from public.instantanes where id = p_instantane for update;
  select * into j from public.branchements_jeux where id = i.jeu_id;
  select * into b from public.branchements where id = i.branchement_id;

  -- Un export plus récent de ce jeu fait déjà l'état : celui-ci arrive trop tard.
  if exists (select 1 from public.instantanes k
             where k.jeu_id = j.id and k.id <> i.id and k.statut in ('applique', 'identique') and k.recu_le > i.recu_le) then
    update public.instantanes set statut = 'remplace', finalise_le = now(),
           motif = 'Un export plus récent de ce jeu est déjà appliqué.'
     where id = i.id;
    delete from public.instantanes_lignes where instantane_id = i.id;
    return 'remplace';
  end if;

  v_complet := coalesce(i.complet, j.complet);

  -- La copie exacte de l'export qui fait l'état : rien ne change.
  if not i.force and j.courant_id is not null then
    select * into c from public.instantanes where id = j.courant_id;
    if c.sha256 = i.sha256 and i.complet is null and i.fenetre is null and i.perimetre is null
       and c.complet is null and c.fenetre is null and c.perimetre is null
       and not exists (select 1 from public.jeux_lignes s where s.jeu_id = j.id and s.absences > 0) then
      update public.instantanes
         set statut = 'identique', base_id = c.id, lignes_base = j.lignes, ajouts = 0, modifications = 0,
             disparitions = 0, absences = 0, finalise_le = now()
       where id = i.id;
      delete from public.instantanes_lignes where instantane_id = i.id;
      perform private.confirmer_etat(j.id, i.recu_le);
      return 'identique';
    end if;
  end if;

  v_fenetre := private.fenetre_effective(i.id);
  v_col := v_fenetre ->> 'colonne';
  v_du := (v_fenetre ->> 'du')::date;
  v_au := (v_fenetre ->> 'au')::date;
  v_sensibles := private.codes_sensibles(j.colonnes);

  select count(*) into v_base from public.jeux_lignes s
  where s.jeu_id = j.id and private.dans_portee(s.valeurs, v_col, v_du, v_au, i.perimetre, b.fuseau);
  if v_complet then
    select count(*) into v_absents from public.jeux_lignes s
    where s.jeu_id = j.id and private.dans_portee(s.valeurs, v_col, v_du, v_au, i.perimetre, b.fuseau)
      and not exists (select 1 from public.instantanes_lignes l where l.instantane_id = i.id and l.cle = s.cle);
  end if;
  v_absentes := coalesce(array(select jsonb_array_elements_text(
    case when jsonb_typeof(i.format -> 'colonnes_absentes') = 'array' then i.format -> 'colonnes_absentes' else '[]'::jsonb end)), '{}');

  if not i.force then
    v_raison := case
      when i.lignes = 0 and v_base > 0 then 'vide'
      when cardinality(v_absentes) > 0 then 'colonnes'
      when v_complet and v_base > 0 and v_base - i.lignes >= j.perte_min and (v_base - i.lignes) > j.seuil_perte * v_base
        then 'perte'
      when v_complet and cardinality(j.cle) > 0 and v_base > 0 and v_absents >= j.perte_min and v_absents > j.seuil_perte * v_base
        then 'disparitions'
      when i.lignes > 0 and coalesce(i.anomalies, 0) > j.seuil_anomalies * i.lignes then 'anomalies'
    end;
  end if;
  v_garde := jsonb_strip_nulls(jsonb_build_object(
    'raison', v_raison, 'lignes', i.lignes, 'lignes_base', v_base, 'perte', greatest(v_base - i.lignes, 0),
    'absents', v_absents, 'anomalies', coalesce(i.anomalies, 0),
    'colonnes_absentes', case when cardinality(v_absentes) > 0 then to_jsonb(v_absentes) end,
    'complet', v_complet, 'fenetre', v_fenetre, 'perimetre', i.perimetre, 'seuil_perte', j.seuil_perte,
    'perte_min', j.perte_min, 'seuil_anomalies', j.seuil_anomalies, 'force', case when i.force then true end));

  if v_raison is not null then
    update public.instantanes
       set statut = 'douteux', base_id = j.courant_id, lignes_base = v_base, absences = v_absents, garde = v_garde,
           finalise_le = now(), motif = private.phrase_garde(v_garde)
     where id = i.id;
    update public.pieces set statut = 'a_verifier', motif = private.phrase_garde(v_garde) where id = i.piece_id;
    perform private.alerter_douteux(i.id);
    return 'douteux';
  end if;

  insert into public.instantanes_ecarts (client_id, instantane_id, jeu_id, cle, nature, avant, apres, champs, anomalies, n)
  select i.client_id, i.id, j.id, l.cle, 'ajout', null, l.valeurs, null, l.anomalies, l.n
  from public.instantanes_lignes l
  where l.instantane_id = i.id and not exists (select 1 from public.jeux_lignes s where s.jeu_id = j.id and s.cle = l.cle);
  get diagnostics v_ajouts = row_count;

  insert into public.instantanes_ecarts (client_id, instantane_id, jeu_id, cle, nature, avant, apres, champs, anomalies, n)
  select i.client_id, i.id, j.id, l.cle, 'modification', s.valeurs, l.valeurs,
         array(select distinct x from unnest(
                 private.champs_changes(s.valeurs, l.valeurs - v_sensibles, s.anomalies, nullif(l.anomalies - v_sensibles, '{}'::jsonb))
                 || array(select k from unnest(v_sensibles) k
                          where (private.empreintes_sensibles(j.id, l.valeurs, v_sensibles) -> k)
                                is distinct from (s.sensibles -> k))) x order by x),
         l.anomalies, l.n
  from public.instantanes_lignes l
  join public.jeux_lignes s on s.jeu_id = j.id and s.cle = l.cle
  where l.instantane_id = i.id and s.empreinte <> l.empreinte;
  get diagnostics v_modifs = row_count;

  if v_complet then
    insert into public.instantanes_ecarts (client_id, instantane_id, jeu_id, cle, nature, avant, apres, champs, anomalies, n)
    select i.client_id, i.id, j.id, s.cle, 'disparition', s.valeurs, null, null, null, null
    from public.jeux_lignes s
    where s.jeu_id = j.id and s.absences + 1 >= j.confirmer_disparition
      and private.dans_portee(s.valeurs, v_col, v_du, v_au, i.perimetre, b.fuseau)
      and not exists (select 1 from public.instantanes_lignes l where l.instantane_id = i.id and l.cle = s.cle);
    get diagnostics v_disp = row_count;
  end if;

  update public.instantanes
     set statut = 'a_appliquer', base_id = j.courant_id, lignes_base = v_base, ajouts = v_ajouts,
         modifications = v_modifs, disparitions = v_disp, absences = v_absents, garde = v_garde, finalise_le = now()
   where id = i.id;
  if not j.accuse then
    perform private.appliquer_instantane(i.id);
    return 'applique';
  end if;
  return 'a_appliquer';
end $$;


--
-- Name: finir_travail(bigint, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finir_travail(p_id bigint, p_resultat jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.travaux
     set etat = 'fait', resultat = p_resultat, fini_le = now(), verrou_jusqu_au = null
   where id = p_id and etat = 'en_cours';
  if not found then
    raise exception 'Travail introuvable ou pas en cours : %.', p_id using errcode = 'P0002';
  end if;
end $$;


--
-- Name: format_valide(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.format_valide(p_type text, p_format text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_type
    when 'decimal' then p_format in (',', '.')
    when 'date' then p_format in ('jj/mm/aaaa', 'mm/jj/aaaa', 'aaaa-mm-jj', 'aaaammjj')
    when 'dateheure' then p_format in ('jj/mm/aaaa', 'mm/jj/aaaa', 'aaaa-mm-jj', 'utc',
                                       'jj/mm/aaaa utc', 'mm/jj/aaaa utc', 'aaaa-mm-jj utc')
    else false end
$$;


--
-- Name: formater_montant(numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.formater_montant(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when p < 0 then '-' else '' end
      || regexp_replace(trunc(abs(round(p, 2)))::text, '(\d)(?=(\d{3})+$)', '\1 ', 'g')
      || ',' || lpad(((abs(round(p, 2)) * 100)::bigint % 100)::text, 2, '0') || ' €'
$_$;


--
-- Name: formater_variable(text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.formater_variable(p_type text, p_valeur jsonb, p_nom text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v text;
  n numeric;
begin
  if p_valeur is null or jsonb_typeof(p_valeur) = 'null' then
    raise exception 'La variable « % » manque.', p_nom using errcode = '22023';
  end if;
  v := case jsonb_typeof(p_valeur) when 'string' then p_valeur #>> '{}' else p_valeur::text end;
  if p_type = 'texte' then
    v := btrim(v);
    if char_length(v) not between 1 and 500 or v ~ '[[:cntrl:]]' or v ~ '\{\{|\}\}' then
      raise exception 'La variable « % » (texte) : de 1 à 500 caractères, sans caractère de contrôle ni accolades.', p_nom
        using errcode = '22023';
    end if;
    return v;
  elsif p_type = 'date' then
    if v !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'La variable « % » est une date AAAA-MM-JJ.', p_nom using errcode = '22023';
    end if;
    begin
      return to_char(v::date, 'DD/MM/YYYY');
    exception when others then
      raise exception 'La variable « % » n''est pas une date réelle.', p_nom using errcode = '22023';
    end;
  elsif p_type = 'heure' then
    if v !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      raise exception 'La variable « % » est une heure HH:MM.', p_nom using errcode = '22023';
    end if;
    return (left(v, 2)::int)::text || ' h' || case when right(v, 2) = '00' then '' else ' ' || right(v, 2) end;
  elsif p_type = 'montant' then
    begin
      n := v::numeric;
    exception when others then
      raise exception 'La variable « % » est un montant.', p_nom using errcode = '22023';
    end;
    if abs(n) >= 1e12 then
      raise exception 'La variable « % » : montant hors limites.', p_nom using errcode = '22023';
    end if;
    return private.formater_montant(n);
  elsif p_type = 'nombre' then
    if v !~ '^-?[0-9]{1,12}$' then
      raise exception 'La variable « % » est un nombre entier.', p_nom using errcode = '22023';
    end if;
    return v;
  elsif p_type = 'lien' then
    if v !~ '^https://[^[:space:]<>"]{3,2000}$' then
      raise exception 'La variable « % » est un lien https://.', p_nom using errcode = '22023';
    end if;
    return v;
  elsif p_type = 'reference' then
    if v !~ '^[A-Za-z0-9][A-Za-z0-9._/:#-]{0,79}$' then
      raise exception 'La variable « % » est une référence (lettres, chiffres, . _ / : # -).', p_nom using errcode = '22023';
    end if;
    return v;
  end if;
  raise exception 'Type de variable inconnu : %.', p_type using errcode = '22023';
end $_$;


--
-- Name: fuseau_du_numero(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.fuseau_du_numero(p_e164 text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_e164 ~ '^\+590' then '{"fuseau": "America/Guadeloupe", "territoire": null}'::jsonb
    when p_e164 ~ '^\+596' then '{"fuseau": "America/Martinique", "territoire": "martinique"}'::jsonb
    when p_e164 ~ '^\+594' then '{"fuseau": "America/Cayenne", "territoire": "guyane"}'::jsonb
    when p_e164 ~ '^\+262(269|639)' then '{"fuseau": "Indian/Mayotte", "territoire": "mayotte"}'::jsonb
    when p_e164 ~ '^\+262' then '{"fuseau": "Indian/Reunion", "territoire": "la-reunion"}'::jsonb
    when p_e164 ~ '^\+508' then '{"fuseau": "America/Miquelon", "territoire": "saint-pierre-et-miquelon"}'::jsonb
    when p_e164 ~ '^\+687' then '{"fuseau": "Pacific/Noumea", "territoire": "nouvelle-caledonie"}'::jsonb
    when p_e164 ~ '^\+689' then '{"fuseau": "Pacific/Tahiti", "territoire": "polynesie-francaise"}'::jsonb
    when p_e164 ~ '^\+681' then '{"fuseau": "Pacific/Wallis", "territoire": "wallis-et-futuna"}'::jsonb
    when p_e164 ~ '^\+33' then '{"fuseau": "Europe/Paris", "territoire": null}'::jsonb
  end
$$;


--
-- Name: gabarits_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gabarits_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid,
    module text NOT NULL,
    code text NOT NULL,
    langue text DEFAULT 'fr'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    canal text NOT NULL,
    libelle text NOT NULL,
    sujet text,
    corps text NOT NULL,
    variables jsonb DEFAULT '{}'::jsonb NOT NULL,
    transactionnel boolean DEFAULT true NOT NULL,
    donnees_sante boolean DEFAULT false NOT NULL,
    espacement boolean DEFAULT true NOT NULL,
    modele_externe text,
    statut text DEFAULT 'brouillon'::text NOT NULL,
    valide_le timestamp with time zone,
    valide_par text,
    retire_le timestamp with time zone,
    motif_retrait text,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT gabarits_messages_canal_check CHECK ((canal = ANY (ARRAY['email'::text, 'whatsapp'::text, 'sms'::text, 'lre'::text, 'appel'::text]))),
    CONSTRAINT gabarits_messages_code_check CHECK (((code ~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)+$'::text) AND (char_length(code) <= 100))),
    CONSTRAINT gabarits_messages_code_du_module CHECK (starts_with(code, (module || '.'::text))),
    CONSTRAINT gabarits_messages_corps_check CHECK (((char_length(corps) >= 1) AND (char_length(corps) <= 20000))),
    CONSTRAINT gabarits_messages_langue_check CHECK ((langue ~ '^[a-z]{2}$'::text)),
    CONSTRAINT gabarits_messages_libelle_check CHECK (((char_length(btrim(libelle)) >= 3) AND (char_length(btrim(libelle)) <= 120))),
    CONSTRAINT gabarits_messages_modele_externe_check CHECK (((char_length(modele_externe) >= 1) AND (char_length(modele_externe) <= 200))),
    CONSTRAINT gabarits_messages_module_check CHECK ((module ~ '^[a-z][a-z_]{1,29}$'::text)),
    CONSTRAINT gabarits_messages_motif_retrait_check CHECK ((char_length(motif_retrait) <= 300)),
    CONSTRAINT gabarits_messages_statut_check CHECK ((statut = ANY (ARRAY['brouillon'::text, 'valide'::text, 'retire'::text]))),
    CONSTRAINT gabarits_messages_sujet_check CHECK (((char_length(sujet) >= 1) AND (char_length(sujet) <= 300))),
    CONSTRAINT gabarits_messages_valide_par_check CHECK ((char_length(valide_par) <= 200)),
    CONSTRAINT gabarits_messages_variables_check CHECK ((jsonb_typeof(variables) = 'object'::text)),
    CONSTRAINT gabarits_messages_version_check CHECK ((version >= 1))
);


--
-- Name: gabarit_pour(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.gabarit_pour(p_client uuid, p_module text, p_code text, p_langue text) RETURNS public.gabarits_messages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select g.* from public.gabarits_messages g
  where g.code = p_code and g.module = p_module and g.statut = 'valide'
    and (g.client_id = p_client or g.client_id is null)
    and g.langue in (coalesce(p_langue, 'fr'), 'fr')
  order by (g.langue = coalesce(p_langue, 'fr')) desc, (g.client_id is not null) desc, g.version desc
  limit 1
$$;


--
-- Name: garder_chiffrement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_chiffrement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_chiffree boolean;
begin
  select p.chiffrement is not null into v_chiffree from public.pieces p where p.id = new.piece_id;
  if tg_table_name = 'pieces_pages' then
    if v_chiffree and (new.texte_chiffre is null or new.texte <> '') then
      raise exception 'Pièce chiffrée : une page ne s''écrit que chiffrée.' using errcode = '22023';
    elsif not v_chiffree and new.texte_chiffre is not null then
      raise exception 'Pièce en clair : aucune page chiffrée.' using errcode = '22023';
    end if;
  else
    if v_chiffree and new.chiffre is null then
      raise exception 'Pièce chiffrée : une valeur ne s''écrit que chiffrée.' using errcode = '22023';
    elsif not v_chiffree and new.chiffre is not null then
      raise exception 'Pièce en clair : aucune valeur chiffrée.' using errcode = '22023';
    end if;
  end if;
  return new;
end $$;


--
-- Name: garder_demande(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_demande() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (new.id, new.client_id, new.entite_id, new.module, new.type_action, new.objet_type, new.objet_id,
      new.resume, new.montant, new.devise, new.payload, new.demandeur_type, new.demandeur_id,
      new.approbations_requises, new.roles_autorises, new.equipe_id, new.politique_id, new.echeance,
      new.cle_idempotence, new.cree_le)
     is distinct from
     (old.id, old.client_id, old.entite_id, old.module, old.type_action, old.objet_type, old.objet_id,
      old.resume, old.montant, old.devise, old.payload, old.demandeur_type, old.demandeur_id,
      old.approbations_requises, old.roles_autorises, old.equipe_id, old.politique_id, old.echeance,
      old.cle_idempotence, old.cree_le)
  then
    raise exception 'Une demande de validation ne se modifie pas après sa création : seul son statut avance.'
      using errcode = '42501';
  end if;

  if new.statut is distinct from old.statut then
    if current_user = 'authenticated' then
      if not (old.statut = 'en_attente' and new.statut = 'annulee'
              and old.demandeur_id = (select auth.uid())) then
        raise exception 'Seul le demandeur annule une demande en attente ; le reste passe par les décisions.'
          using errcode = '42501';
      end if;
    elsif not (
         (old.statut = 'en_attente' and new.statut in ('approuvee', 'rejetee', 'expiree', 'annulee'))
      or (old.statut = 'approuvee' and new.statut in ('executee', 'echec_execution'))
      or (old.statut = 'echec_execution' and new.statut in ('executee', 'echec_execution'))
    ) then
      raise exception 'Passage de statut refusé : % vers %.', old.statut, new.statut using errcode = '23514';
    end if;

    if new.statut = 'approuvee' and (
      select count(*) from public.approbations a
      where a.demande_id = new.id and a.decision = 'approuve') < new.approbations_requises
    then
      raise exception 'Approbations insuffisantes : une demande n''est approuvée que par des personnes.'
        using errcode = '23514';
    end if;
    if new.statut = 'rejetee' and not exists (
      select 1 from public.approbations a where a.demande_id = new.id and a.decision = 'rejete')
    then
      raise exception 'Un rejet vient toujours d''une personne.' using errcode = '23514';
    end if;

    if new.statut in ('approuvee', 'rejetee', 'expiree', 'annulee') then
      new.decide_le := coalesce(new.decide_le, now());
    end if;
    if new.statut = 'executee' then
      new.execute_le := coalesce(new.execute_le, now());
    end if;
  end if;
  return new;
end $$;


--
-- Name: garder_envoi(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_envoi() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if private.effacement_en_cours(old.client_id) then
      return old;
    end if;
    raise exception 'Un envoi ne s''efface pas : ce qui est parti se prouve. Il part avec son objet ou son organisation.'
      using errcode = '42501';
  end if;
  if not private.ecrit_par_la_brique(tg_relid) then
    raise exception 'Un envoi s''écrit par les portes de la brique (preparer_envoi, annuler_envoi…), jamais directement.'
      using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    return new;
  end if;
  if (new.id, new.client_id, new.entite_id, new.module, new.objet_type, new.objet_id, new.canal,
      new.destinataire_adresse, new.destinataire_empreinte, new.destinataire_ref, new.destinataire_membre,
      new.destinataire_fuseau, new.destinataire_territoire, new.destinataire_professionnel, new.transactionnel,
      new.direct, new.adossee, new.suivi_id, new.rang, new.cle_idempotence, new.prepare_par, new.cree_le,
      new.echeance, new.pieces)
     is distinct from
     (old.id, old.client_id, old.entite_id, old.module, old.objet_type, old.objet_id, old.canal,
      old.destinataire_adresse, old.destinataire_empreinte, old.destinataire_ref, old.destinataire_membre,
      old.destinataire_fuseau, old.destinataire_territoire, old.destinataire_professionnel, old.transactionnel,
      old.direct, old.adossee, old.suivi_id, old.rang, old.cle_idempotence, old.prepare_par, old.cree_le,
      old.echeance, old.pieces)
  then
    raise exception 'Un envoi ne change ni de destinataire, ni d''objet, ni de canal, ni d''échéance.' using errcode = '42501';
  end if;
  if (new.sujet, new.corps, new.empreinte, new.variables, new.gabarit_id, new.donnees_sante, new.espacement)
     is distinct from
     (old.sujet, old.corps, old.empreinte, old.variables, old.gabarit_id, old.donnees_sante, old.espacement)
     and old.statut <> 'a_valider' then
    raise exception 'Le contenu d''un envoi décidé ne change plus.' using errcode = '42501';
  end if;
  if new.statut is distinct from old.statut then
    if new.statut = 'envoye' and coalesce(current_setting('omega.envois_ouvrier', true), '') <> 'oui' then
      raise exception '« envoye » est réservé à l''ouvrier d''envoi, ou à la personne qui exécute un envoi manuel.'
        using errcode = '42501';
    end if;
    if not (
         (old.statut = 'a_valider' and new.statut in ('pret', 'differe', 'bloque', 'refuse', 'expire', 'annule'))
      or (old.statut = 'differe' and new.statut in ('pret', 'bloque', 'expire', 'annule'))
      or (old.statut = 'pret' and new.statut in ('en_cours', 'differe', 'bloque', 'expire', 'annule'))
      or (old.statut = 'en_cours' and new.statut in ('envoye', 'pret', 'differe', 'bloque', 'echec', 'annule', 'expire'))
    ) then
      raise exception 'Passage refusé pour un envoi : % vers %.', old.statut, new.statut using errcode = '23514';
    end if;
  end if;
  new.maj_le := now();
  return new;
end $$;


--
-- Name: garder_par_les_portes(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_par_les_portes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if private.effacement_en_cours(old.client_id) then
      return old;
    end if;
    raise exception 'Une preuve de la brique d''envoi ne s''efface pas : elle part avec son organisation.' using errcode = '42501';
  end if;
  if not private.ecrit_par_la_brique(tg_relid) then
    raise exception 'Cette table s''écrit par les portes de la brique d''envoi (noter_consentement, noter_opposition…).'
      using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: garder_politique(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_politique() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (new.id, new.client_id, new.entite_id, new.module, new.type_action, new.libelle, new.plafond_operation,
      new.plafond_mensuel, new.nombre_mensuel, new.debut, new.fin, new.fuseau, new.demande_id, new.cree_par, new.cree_le)
     is distinct from
     (old.id, old.client_id, old.entite_id, old.module, old.type_action, old.libelle, old.plafond_operation,
      old.plafond_mensuel, old.nombre_mensuel, old.debut, old.fin, old.fuseau, old.demande_id, old.cree_par, old.cree_le)
  then
    raise exception 'Un accord permanent ne se retouche pas : révoquez-le et proposez-en un autre.' using errcode = '42501';
  end if;
  if new.statut is distinct from old.statut and not (
       (old.statut = 'a_valider' and new.statut in ('active', 'refusee', 'revoquee'))
    or (old.statut = 'active' and new.statut = 'revoquee')) then
    raise exception 'Passage refusé : % vers %.', old.statut, new.statut using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: garder_suivi(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_suivi() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if private.effacement_en_cours(old.client_id) then
      return old;
    end if;
    raise exception 'Un suivi ne s''efface pas : il part avec son objet ou son organisation.' using errcode = '42501';
  end if;
  if not private.ecrit_par_la_brique(tg_relid) then
    raise exception 'Un suivi s''écrit par ses portes (ouvrir_suivi, noter_promesse, clore_suivi…), jamais directement.'
      using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' then
    if (new.id, new.client_id, new.entite_id, new.module, new.objet_type, new.objet_id, new.attendu, new.nature, new.type_piece,
        new.tiers, new.tiers_nom, new.tiers_ref, new.depuis, new.ouvert_par, new.cle_idempotence, new.cree_le)
       is distinct from
       (old.id, old.client_id, old.entite_id, old.module, old.objet_type, old.objet_id, old.attendu, old.nature, old.type_piece,
        old.tiers, old.tiers_nom, old.tiers_ref, old.depuis, old.ouvert_par, old.cle_idempotence, old.cree_le)
    then
      raise exception 'Un suivi ne change ni d''objet, ni de tiers, ni d''attendu : on le clôt et on en ouvre un autre.'
        using errcode = '42501';
    end if;
    if old.date_promise_initiale is not null and new.date_promise_initiale is distinct from old.date_promise_initiale then
      raise exception 'La première date promise reste : c''est elle qui mesure les glissements.' using errcode = '42501';
    end if;
    if old.statut <> 'ouvert' and new.statut is distinct from old.statut then
      raise exception 'Un suivi clos ne se rouvre pas.' using errcode = '23514';
    end if;
    new.maj_le := now();
  end if;
  return new;
end $$;


--
-- Name: garder_un_gerant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.garder_un_gerant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.role = 'gerant' and (tg_op = 'DELETE' or new.role <> 'gerant') then
    if old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '')
       or not exists (select 1 from public.clients where id = old.client_id)
       or not exists (select 1 from auth.users where id = old.user_id) then
      return coalesce(new, old);
    end if;
    if not exists (select 1 from public.comptes c where c.client_id = old.client_id and c.role = 'gerant' and c.user_id <> old.user_id) then
      raise exception 'Une organisation garde toujours au moins un gérant.' using errcode = 'P0001', hint = 'Nommez un autre gérant avant de retirer celui-ci.';
    end if;
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: generer_jours_feries(integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.generer_jours_feries(p_de integer, p_a integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  insert into public.jours_feries (territoire, jour, libelle)
  select t.code,
         case when r.decalage_paques is null then make_date(an, r.mois, r.jour)
              else private.paques(an) + r.decalage_paques end,
         r.libelle
  from generate_series(p_de, p_a) an
  cross join public.territoires t
  join private.jours_feries_regles r on r.territoire in ('*', t.code)
  order by (r.territoire = '*') desc
  on conflict (territoire, jour) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: identique_au_courant(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.identique_au_courant(p_branchement uuid, p_jeu uuid, p_sha256 text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.id
  from public.branchements_jeux j
  join public.instantanes c on c.id = j.courant_id
  where j.branchement_id = p_branchement and j.actif and (p_jeu is null or j.id = p_jeu) and c.sha256 = p_sha256
    and c.complet is null and c.fenetre is null and c.perimetre is null
    and not exists (select 1 from public.instantanes k where k.jeu_id = j.id and k.statut in ('recu', 'en_lecture', 'lu', 'a_appliquer'))
    and not exists (select 1 from public.jeux_lignes s where s.jeu_id = j.id and s.absences > 0)
  limit 1
$$;


--
-- Name: jeu_vu(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.jeu_vu(p_jeu uuid, p_quand timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.branchements_jeux;
  v_module text;
begin
  update public.branchements_jeux
     set dernier_recu_le = greatest(coalesce(dernier_recu_le, p_quand), p_quand)
   where id = p_jeu
  returning * into j;
  select b.module into v_module from public.branchements b where b.id = j.branchement_id;
  perform private.fermer_alertes_releve(j.client_id, v_module, 'releve.muet.' || j.id::text, 'un fichier est arrivé');
  perform private.fermer_alertes_releve(j.client_id, v_module, 'releve.en_retard.' || j.id::text, 'un fichier est arrivé');
end $$;


--
-- Name: jour_en_toutes_lettres(date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.jour_en_toutes_lettres(p_jour date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (array['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'])[extract(isodow from p_jour)::int]
         || ' ' || to_char(p_jour, 'DD/MM/YYYY')
$$;


--
-- Name: journal_immuable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.journal_immuable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and old.client_id::text = current_setting('omega.effacement_client', true) then
    return old;
  end if;
  raise exception 'Le journal opposable ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: journal_sans_vidage(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.journal_sans_vidage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'Le journal opposable ne se vide pas.' using errcode = '42501';
end $$;


--
-- Name: journaliser(uuid, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.journaliser(p_client uuid, p_action text, p_objet_type text, p_objet_id text, p_donnees jsonb DEFAULT '{}'::jsonb, p_entite uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_acteur record; v_precedent bytea; v_id bigint;
  v_quand timestamptz := clock_timestamp();
  v_donnees jsonb := coalesce(p_donnees, '{}'::jsonb);
begin
  select * into v_acteur from private.acteur_courant();
  perform pg_advisory_xact_lock(hashtextextended('omega.journal:' || p_client::text, 0));
  select j.hash into v_precedent from public.journal_opposable j where j.client_id = p_client order by j.id desc limit 1;
  v_id := nextval(pg_get_serial_sequence('public.journal_opposable', 'id'));
  insert into public.journal_opposable (id, client_id, entite_id, survenu_le, acteur_type, acteur_id, acteur_libelle,
    action, objet_type, objet_id, donnees, hash_precedent, hash)
  values (v_id, p_client, p_entite, v_quand, v_acteur.acteur_type, v_acteur.acteur_id, v_acteur.acteur_libelle,
    p_action, p_objet_type, p_objet_id, v_donnees, v_precedent,
    private.empreinte_journal(v_precedent, v_id, p_client, p_entite, v_quand,
      v_acteur.acteur_type, v_acteur.acteur_id, v_acteur.acteur_libelle, p_action, p_objet_type, p_objet_id, v_donnees));
  return v_id;
end $$;


--
-- Name: journaliser_module(uuid, text, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.journaliser_module(p_client uuid, p_module text, p_action text, p_objet_type text, p_objet_id text, p_donnees jsonb DEFAULT '{}'::jsonb, p_entite uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id bigint;
begin
  if p_module is null or p_module !~ '^[a-z][a-z_]{1,29}$' then
    raise exception 'Module inconnu : %.', coalesce(p_module, 'vide') using errcode = '22023';
  end if;
  if p_action is null or p_action !~ ('^' || p_module || '\.[a-z][a-z0-9_.]{1,79}$') then
    raise exception 'Une action de module commence par son nom : « %.… ».', p_module using errcode = '22023';
  end if;
  perform set_config('omega.module', p_module, true);
  v_id := private.journaliser(p_client, p_action, p_objet_type, p_objet_id, coalesce(p_donnees, '{}'::jsonb), p_entite);
  perform set_config('omega.module', '', true);
  return v_id;
end $_$;


--
-- Name: lectures_immuables(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lectures_immuables() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and (
       old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '')
       or coalesce(current_setting('omega.purge_lectures', true), '') = 'oui') then
    return old;
  end if;
  raise exception 'Le journal des lectures ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: lectures_sans_vidage(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lectures_sans_vidage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'Le journal des lectures ne se vide pas.' using errcode = '42501';
end $$;


--
-- Name: lever_alerte(uuid, boolean, text, text, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lever_alerte(p_client uuid, p_interne boolean, p_niveau text, p_source text, p_titre text, p_detail jsonb DEFAULT '{}'::jsonb, p_cle text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  insert into public.alertes (client_id, interne, niveau, source, titre, detail, cle_regroupement)
  values (p_client, p_interne, p_niveau, p_source, p_titre, coalesce(p_detail, '{}'::jsonb), p_cle)
  on conflict do nothing returning id into v_id;
  return v_id;
end $$;


--
-- Name: lever_alerte_module(uuid, text, text, text, jsonb, text, boolean, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lever_alerte_module(p_client uuid, p_module text, p_niveau text, p_titre text, p_detail jsonb DEFAULT '{}'::jsonb, p_cle text DEFAULT NULL::text, p_pour_client boolean DEFAULT false, p_destinataire uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_id uuid;
begin
  if p_module is null or p_module !~ '^[a-z][a-z_]{1,29}$' then
    raise exception 'Module inconnu : %.', coalesce(p_module, 'vide') using errcode = '22023';
  end if;
  if p_destinataire is not null and not exists (
       select 1 from public.comptes c where c.user_id = p_destinataire and c.client_id = p_client) then
    raise exception 'Le destinataire n''est pas membre de l''organisation.' using errcode = '23503';
  end if;
  v_id := private.lever_alerte(p_client, not coalesce(p_pour_client, false), p_niveau, p_module, p_titre,
                               p_detail, case when p_cle is null then null else p_module || ':' || p_cle end);
  if v_id is not null and p_destinataire is not null then
    update public.alertes set destinataire_id = p_destinataire where id = v_id;
  end if;
  return v_id;
end $_$;


--
-- Name: lever_opposition(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lever_opposition(p_opposition uuid, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  o public.oppositions;
  v_uid uuid := (select auth.uid());
begin
  select * into o from public.oppositions where id = p_opposition;
  if o.id is null then
    raise exception 'Opposition introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is not null then
    if not private.a_un_role(o.client_id, array['gerant', 'admin']) then
      raise exception 'Seul un gérant ou un admin lève une opposition.' using errcode = '42501';
    end if;
  else
    perform private.exiger_ouvrier();
  end if;
  if nullif(btrim(p_motif), '') is null then
    raise exception 'Lever une opposition dit pourquoi.' using errcode = '22023';
  end if;
  update public.oppositions set levee_le = now(), levee_par = v_uid, motif_levee = left(p_motif, 300)
   where id = p_opposition and levee_le is null;
end $$;


--
-- Name: limite_requete(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.limite_requete() RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(nullif(current_setting('omega.releve_limite_requete', true), '')::integer, 20000)
$$;


--
-- Name: lire_point(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lire_point(p_point uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  p public.points_du_jour;
begin
  select * into p from public.points_du_jour x where x.id = p_point;
  if not found then
    raise exception 'Point introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is not null then
    if p.user_id <> v_uid and not private.a_un_role(p.client_id, array['gerant']) then
      raise exception 'Point introuvable.' using errcode = 'P0002';
    end if;
    if p.user_id = v_uid and p.ouvert_le is null then
      update public.points_du_jour set ouvert_le = now() where id = p.id;
    end if;
  elsif v_role not in ('service_role', 'postgres') then
    raise exception 'Point introuvable.' using errcode = 'P0002';
  end if;
  return private.point_en_json(p.id, v_uid);
end $$;


--
-- Name: lit_objet(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lit_objet(p_client uuid, p_type text, p_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.lit_objet_pour((select auth.uid()), p_client, p_type, p_id)
$$;


--
-- Name: lit_objet_pour(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lit_objet_pour(p_user uuid, p_client uuid, p_type text, p_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gardien regprocedure;
begin
  if p_type is not null and p_id is not null then
    select g.lit into v_gardien from private.gardiens_objets g where g.objet_type = p_type and g.lit is not null;
    if found then
      if not exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client) then
        return false;
      end if;
      return private.appeler_gardien(v_gardien, p_user, p_client, p_id);
    end if;
  end if;
  return private.voit_objet_pour(p_user, p_client, p_type, p_id);
end $$;


--
-- Name: loc_amender_contrat(uuid, text, timestamp with time zone, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_amender_contrat(p_contrat uuid, p_type text, p_retour_prevu_le timestamp with time zone DEFAULT NULL::timestamp with time zone, p_km_inclus integer DEFAULT NULL::integer, p_motif text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  c public.loc_contrats;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Un contrat s''amende par une personne connectée.' using errcode = '42501';
  end if;
  select * into c from public.loc_contrats where id = p_contrat for update;
  if not found
     or not exists (select 1 from public.comptes k where k.user_id = v_uid and k.client_id = c.client_id) then
    raise exception 'Contrat introuvable.' using errcode = 'P0002';
  end if;
  if not private.a_un_role(c.client_id, array['gerant', 'admin', 'valideur'])
     or not (private.voit_entite(c.client_id, c.entite_id)
             or (c.entite_retour_id is not null and private.voit_entite(c.client_id, c.entite_retour_id))) then
    raise exception 'Seul le chef d''agence ou la direction amende un contrat.' using errcode = '42501';
  end if;
  if c.statut = 'annule' then
    raise exception 'Ce contrat est annulé.' using errcode = '23514';
  end if;
  if p_type not in ('prolongation', 'restitution_decalee', 'retard_offert') then
    raise exception 'Amendement inconnu : %.', coalesce(p_type, 'vide') using errcode = '22023';
  end if;
  if p_type in ('prolongation', 'restitution_decalee')
     and (p_retour_prevu_le is null or p_retour_prevu_le <= c.depart_le) then
    raise exception 'Un nouveau retour prévu, après le départ, est requis.' using errcode = '22023';
  end if;
  if p_type = 'retard_offert' and p_retour_prevu_le is not null then
    raise exception 'Un retard offert ne déplace pas le retour prévu.' using errcode = '22023';
  end if;
  if p_km_inclus is not null and (p_km_inclus < 0 or p_type = 'retard_offert') then
    raise exception 'Forfait kilométrique refusé.' using errcode = '22023';
  end if;

  insert into public.loc_contrats_amendements (client_id, contrat_id, type, retour_prevu_le, km_inclus, sans_frais,
                                               origine, motif, accorde_par)
  values (c.client_id, c.id, p_type, p_retour_prevu_le, p_km_inclus, p_type in ('restitution_decalee', 'retard_offert'),
          'agence', left(p_motif, 500), v_uid)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: loc_annuler_attente(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_annuler_attente(p_client uuid, p_contrat uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p record;
  n integer := 0;
begin
  for p in select x.id, x.demande_id, x.entite_id from public.loc_propositions x
           where x.client_id = p_client and x.contrat_id = p_contrat and x.statut = 'a_valider' loop
    update public.demandes_validation set statut = 'annulee' where id = p.demande_id and statut = 'en_attente';
    update public.loc_propositions set statut = 'remplacee' where id = p.id;
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.demande_annulee', 'loc_propositions', p.id::text,
      jsonb_build_object('demande', p.demande_id, 'motif', 'nouveau calcul'), p.entite_id);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: loc_anonymiser(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_anonymiser(p_client uuid, p_locataire uuid, p_motif text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.loc_locataires
     set ref_source = null, nom = null, prenom = null, raison_sociale = null, siren = null, email = null,
         telephone = null, adresse = null, cle_rapprochement = null, anonymise_le = now()
   where client_id = p_client and id = p_locataire and anonymise_le is null;
  if not found then
    return false;
  end if;
  update public.loc_reservations set notes = null, vol = null
   where client_id = p_client and locataire_id = p_locataire and (notes is not null or vol is not null);
  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.locataire_anonymise', 'loc_locataires',
                                     p_locataire::text, jsonb_build_object('motif', p_motif));
  return true;
end $$;


--
-- Name: loc_anonymiser_locataire(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_anonymiser_locataire(p_locataire uuid, p_motif text DEFAULT 'demande'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  l public.loc_locataires;
begin
  if v_uid is null then
    raise exception 'Une anonymisation est décidée par une personne connectée.' using errcode = '42501';
  end if;
  select * into l from public.loc_locataires where id = p_locataire for update;
  if not found or not exists (select 1 from public.comptes c where c.user_id = v_uid and c.client_id = l.client_id) then
    raise exception 'Locataire introuvable.' using errcode = 'P0002';
  end if;
  if not private.a_un_role(l.client_id, array['gerant']) then
    raise exception 'Seul le gérant efface une personne.' using errcode = '42501';
  end if;
  if p_motif not in ('demande', 'decision_du_loueur') then
    raise exception 'Motif inconnu : %.', coalesce(p_motif, 'vide') using errcode = '22023';
  end if;
  if l.anonymise_le is not null then
    return jsonb_build_object('locataire', l.id, 'deja_anonyme', true);
  end if;
  if exists (select 1 from public.loc_contrats c
             where c.client_id = l.client_id and c.locataire_id = l.id and c.statut = 'ouvert')
     or exists (select 1 from public.loc_reservations r
                where r.client_id = l.client_id and r.locataire_id = l.id and r.statut in ('option', 'confirmee')
                  and r.disparue_le is null and r.depart_prevu_le > now()) then
    raise exception 'Une location est en cours ou à venir : l''anonymisation attendra sa fin.' using errcode = '55000';
  end if;
  perform private.loc_anonymiser(l.client_id, l.id, p_motif);
  return jsonb_build_object('locataire', l.id, 'deja_anonyme', false);
end $$;


--
-- Name: loc_appliquer_contrat(uuid, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_contrat(p_client uuid, p_ligne jsonb, p_ctx jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v jsonb := coalesce(p_ligne -> 'valeurs', '{}'::jsonb);
  v_lu_le timestamptz := coalesce((p_ctx ->> 'lu_le')::timestamptz, now());
  v_complement boolean := coalesce(p_ctx ->> 'priorite', 'source') = 'complement';
  v_numero text := private.loc_lire_texte(v, 'numero', 80);
  c public.loc_contrats;
  n public.loc_contrats;
  v_existe boolean;
  v_neuf jsonb := '{}'::jsonb;
  v_avert jsonb := '[]'::jsonb;
  v_agence record;
  v_retour record;
  v_texte text;
  v_code text;
  v_id uuid;
  v_km_precedent integer;
  k text;
begin
  if v_numero is null then
    raise exception 'Champ obligatoire manquant : numero.' using errcode = '22023';
  end if;
  select * into c from public.loc_contrats where client_id = p_client and numero = v_numero for update;
  v_existe := found;

  if coalesce(p_ligne ->> 'nature', 'ajout') = 'disparition' then
    if not v_existe or c.disparu_le is not null then
      return jsonb_build_object('effet', 'inchangee');
    end if;
    update public.loc_contrats set disparu_le = v_lu_le where id = c.id;
    return jsonb_build_object('effet', 'disparition', 'avertissements',
      jsonb_build_array(jsonb_build_object('code', 'contrat_disparu_du_logiciel', 'numero', v_numero)));
  end if;

  -- Les agences : le départ, puis le retour (fuseau de chacune pour ses heures).
  select * into v_agence from private.loc_resoudre_agence(p_client, v ->> 'agence',
    coalesce(c.entite_id, (p_ctx ->> 'entite')::uuid));
  if v_agence.entite_id is null then
    raise exception 'Champ obligatoire manquant : agence.' using errcode = '22023';
  end if;
  if private.loc_porte(p_ligne, 'agence') then
    v_neuf := v_neuf || jsonb_build_object('entite_id', v_agence.entite_id);
  end if;
  if private.loc_porte(p_ligne, 'agence_retour') and nullif(btrim(v ->> 'agence_retour'), '') is not null then
    select * into v_retour from private.loc_resoudre_agence(p_client, v ->> 'agence_retour', null);
    v_neuf := v_neuf || jsonb_build_object('entite_retour_id', v_retour.entite_id);
  else
    select * into v_retour from private.loc_resoudre_agence(p_client, null,
      coalesce(c.entite_retour_id, v_agence.entite_id));
  end if;

  -- Les heures, au fuseau de l'agence qui les vit.
  if private.loc_porte(p_ligne, 'depart_le') then
    v_neuf := v_neuf || jsonb_build_object('depart_le', private.loc_lire_instant(v, 'depart_le', v_agence.fuseau));
  end if;
  if private.loc_porte(p_ligne, 'retour_prevu_le') then
    v_neuf := v_neuf || jsonb_build_object('retour_prevu_le', private.loc_lire_instant(v, 'retour_prevu_le', v_retour.fuseau));
  end if;
  if private.loc_porte(p_ligne, 'retour_reel_le') then
    v_neuf := v_neuf || jsonb_build_object('retour_reel_le', private.loc_lire_instant(v, 'retour_reel_le', v_retour.fuseau));
  end if;
  foreach k in array array['depart_le', 'retour_prevu_le', 'retour_reel_le'] loop
    v_texte := private.loc_heure_douteuse(v ->> k, case k when 'depart_le' then v_agence.fuseau else v_retour.fuseau end);
    if v_texte is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'heure_' || v_texte, 'champ', k));
    end if;
  end loop;

  -- Les conditions signées.
  foreach k in array array['km_depart', 'km_retour', 'km_inclus', 'km_inclus_jour', 'seuil_charge_pct'] loop
    if private.loc_porte(p_ligne, k) then
      v_neuf := v_neuf || jsonb_build_object(k, private.loc_lire_entier(v, k));
    end if;
  end loop;
  if private.loc_porte(p_ligne, 'km_illimite') then
    v_neuf := v_neuf || jsonb_build_object('km_illimite', coalesce(private.loc_lire_booleen(v, 'km_illimite'), false));
  end if;
  if private.loc_porte(p_ligne, 'rachat_franchise') then
    v_neuf := v_neuf || jsonb_build_object('rachat_franchise', private.loc_lire_booleen(v, 'rachat_franchise'));
  end if;
  foreach k in array array['tarif_jour', 'franchise', 'franchise_reduite', 'depot'] loop
    if private.loc_porte(p_ligne, k) then
      v_neuf := v_neuf || jsonb_build_object(k || '_eur', private.loc_lire_decimal(v, k));
    end if;
  end loop;
  if private.loc_porte(p_ligne, 'politique_carburant') then
    v_code := private.loc_politique_carburant(v ->> 'politique_carburant');
    if v_code is null and nullif(btrim(v ->> 'politique_carburant'), '') is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'politique_inconnue', 'champ', 'politique_carburant'));
    elsif v_code is not null or p_ligne ? 'champs' then
      v_neuf := v_neuf || jsonb_build_object('politique_carburant', v_code);
    end if;
  end if;
  if private.loc_porte(p_ligne, 'options') then
    v_neuf := v_neuf || jsonb_build_object('options', to_jsonb(private.loc_options(v ->> 'options')));
  end if;
  if private.loc_porte(p_ligne, 'conditions_version') then
    v_neuf := v_neuf || jsonb_build_object('conditions_version', private.loc_lire_texte(v, 'conditions_version', 80));
  end if;
  if private.loc_porte(p_ligne, 'statut') then
    v_code := private.loc_statut_contrat(v ->> 'statut');
    if v_code is null and nullif(btrim(v ->> 'statut'), '') is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'statut_inconnu', 'champ', 'statut'));
    elsif v_code is not null then
      v_neuf := v_neuf || jsonb_build_object('statut', v_code);
    end if;
  end if;

  -- Ce que le contrat désigne : réservation, catégorie, véhicule, locataire.
  if private.loc_porte(p_ligne, 'reservation') then
    select r.id into v_id from public.loc_reservations r
    where r.client_id = p_client and r.ref_source = private.loc_lire_texte(v, 'reservation', 80);
    if v_id is null and nullif(btrim(v ->> 'reservation'), '') is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'reservation_inconnue', 'champ', 'reservation'));
    else
      v_neuf := v_neuf || jsonb_build_object('reservation_id', v_id);
    end if;
  end if;
  if private.loc_porte(p_ligne, 'categorie') then
    v_neuf := v_neuf || jsonb_build_object('categorie_id', private.loc_resoudre_categorie(p_client, v ->> 'categorie'));
  end if;
  if private.loc_porte(p_ligne, 'immatriculation') then
    v_neuf := v_neuf || jsonb_build_object('vehicule_id',
      private.loc_resoudre_vehicule(p_client, v ->> 'immatriculation', v_agence.entite_id,
        coalesce((v_neuf ->> 'categorie_id')::uuid, c.categorie_id)));
  end if;
  if exists (select 1 from jsonb_object_keys(v) x where x like 'locataire\_%') then
    v_id := private.loc_resoudre_locataire(p_client, v);
    if v_id is not null then
      v_neuf := v_neuf || jsonb_build_object('locataire_id', v_id);
    end if;
  end if;

  -- Les saisies humaines ne s'écrasent jamais ; un complément ne remplit que les vides.
  select f.p_avert, f.garder into v_avert, v_neuf
  from private.loc_filtrer(to_jsonb(c), v_neuf, coalesce(c.saisies, '{}'::jsonb), v_complement, v_avert) f;

  if not v_existe then
    c.id := gen_random_uuid();
    c.client_id := p_client;
    c.numero := v_numero;
    c.entite_id := v_agence.entite_id;
    c.statut := 'ouvert';
    c.source := coalesce(p_ctx ->> 'source', 'export');
    c.km_illimite := false;
    c.saisies := '{}'::jsonb;
    c.avertissements := '[]'::jsonb;
  end if;
  n := jsonb_populate_record(c, to_jsonb(c) || v_neuf);
  n.disparu_le := null;
  n.piece_id := coalesce(n.piece_id, (p_ctx ->> 'piece')::uuid);
  if n.retour_reel_le is not null and n.statut = 'ouvert' then
    n.statut := 'clos';
  end if;

  -- Les contrôles : l'essentiel rejette la ligne ; le douteux avertit, sans rien deviner.
  if n.depart_le is null or n.retour_prevu_le is null then
    raise exception 'Champ obligatoire manquant : %.',
      case when n.depart_le is null then 'depart_le' else 'retour_prevu_le' end using errcode = '22023';
  end if;
  if n.retour_prevu_le <= n.depart_le then
    raise exception 'Le retour prévu doit suivre le départ (retour_prevu_le).' using errcode = '22023';
  end if;
  if n.retour_reel_le is not null and n.retour_reel_le < n.depart_le then
    raise exception 'Le retour réel précède le départ (retour_reel_le).' using errcode = '22023';
  end if;
  if n.km_depart is not null and n.km_retour is not null and n.km_retour < n.km_depart then
    n.km_depart := c.km_depart;
    n.km_retour := c.km_retour;
    v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'kilometrage_incoherent', 'champ', 'km_retour'));
  end if;
  if n.politique_carburant = 'seuil' and n.seuil_charge_pct is null then
    n.politique_carburant := c.politique_carburant;
    v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'seuil_absent', 'champ', 'seuil_charge_pct'));
  end if;
  if n.seuil_charge_pct is not null and n.politique_carburant is distinct from 'seuil' then
    n.seuil_charge_pct := null;
  end if;
  if n.franchise_reduite_eur is not null and n.franchise_eur is not null and n.franchise_reduite_eur > n.franchise_eur then
    n.franchise_reduite_eur := c.franchise_reduite_eur;
    v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'franchise_reduite_superieure', 'champ', 'franchise_reduite'));
  end if;
  if n.vehicule_id is not null and n.km_depart is not null then
    select max(x.km_retour) into v_km_precedent from public.loc_contrats x
    where x.client_id = p_client and x.vehicule_id = n.vehicule_id and x.id <> n.id and x.depart_le < n.depart_le;
    if v_km_precedent is not null and n.km_depart < v_km_precedent then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'compteur_decroissant', 'champ', 'km_depart'));
    end if;
  end if;

  -- Un écart avec le PDF signé reste signalé tant qu'une personne ne l'a pas tranché.
  n.avertissements := v_avert || coalesce((
    select jsonb_agg(a) from jsonb_array_elements(c.avertissements) a
    where a ->> 'code' = 'ecart_avec_le_logiciel'
      and not exists (select 1 from jsonb_array_elements(v_avert) b
                      where b ->> 'code' = a ->> 'code' and b ->> 'champ' = a ->> 'champ')), '[]'::jsonb);

  if not v_existe then
    insert into public.loc_contrats (id, client_id, entite_id, entite_retour_id, numero, reservation_id, vehicule_id,
      categorie_id, locataire_id, depart_le, retour_prevu_le, retour_reel_le, km_depart, km_retour, km_inclus,
      km_inclus_jour, km_illimite, politique_carburant, seuil_charge_pct, tarif_jour_eur, franchise_eur,
      franchise_reduite_eur, rachat_franchise, options, depot_eur, conditions_version, statut, source, piece_id,
      avertissements)
    values (n.id, n.client_id, n.entite_id, n.entite_retour_id, n.numero, n.reservation_id, n.vehicule_id,
      n.categorie_id, n.locataire_id, n.depart_le, n.retour_prevu_le, n.retour_reel_le, n.km_depart, n.km_retour,
      n.km_inclus, n.km_inclus_jour, n.km_illimite, n.politique_carburant, n.seuil_charge_pct, n.tarif_jour_eur,
      n.franchise_eur, n.franchise_reduite_eur, n.rachat_franchise, n.options, n.depot_eur, n.conditions_version,
      n.statut, n.source, n.piece_id, n.avertissements);
  elsif (to_jsonb(n) - 'maj_le') <> (to_jsonb(c) - 'maj_le') then
    update public.loc_contrats
       set entite_id = n.entite_id, entite_retour_id = n.entite_retour_id, reservation_id = n.reservation_id,
           vehicule_id = n.vehicule_id, categorie_id = n.categorie_id, locataire_id = n.locataire_id,
           depart_le = n.depart_le, retour_prevu_le = n.retour_prevu_le, retour_reel_le = n.retour_reel_le,
           km_depart = n.km_depart, km_retour = n.km_retour, km_inclus = n.km_inclus, km_inclus_jour = n.km_inclus_jour,
           km_illimite = n.km_illimite, politique_carburant = n.politique_carburant,
           seuil_charge_pct = n.seuil_charge_pct, tarif_jour_eur = n.tarif_jour_eur, franchise_eur = n.franchise_eur,
           franchise_reduite_eur = n.franchise_reduite_eur, rachat_franchise = n.rachat_franchise,
           options = n.options, depot_eur = n.depot_eur, conditions_version = n.conditions_version,
           statut = n.statut, piece_id = n.piece_id, avertissements = n.avertissements, disparu_le = n.disparu_le
     where id = c.id;
  else
    return jsonb_build_object('effet', 'inchangee', 'avertissements', v_avert);
  end if;

  -- Ce que le contrat entraîne : la réservation est convertie ; le compteur du véhicule avance.
  if n.reservation_id is not null then
    update public.loc_reservations set statut = 'convertie'
     where client_id = p_client and id = n.reservation_id and statut in ('option', 'confirmee');
  end if;
  if n.vehicule_id is not null and n.km_retour is not null and n.retour_reel_le is not null then
    update public.loc_vehicules
       set km_dernier = n.km_retour, km_dernier_le = n.retour_reel_le
     where client_id = p_client and id = n.vehicule_id
       and (km_dernier_le is null or km_dernier_le < n.retour_reel_le);
  end if;
  return jsonb_build_object('effet', case when v_existe then 'modification' else 'creation' end,
                            'avertissements', v_avert);
end $$;


--
-- Name: loc_appliquer_decision(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_decision(p_charge jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.loc_propositions;
  d public.demandes_validation;
  v_demande uuid := (p_charge ->> 'demande')::uuid;
  v_statut text := p_charge ->> 'statut';
  v_tentative integer;
  v_nouvelle uuid;
  v_numero text;
  v_factures uuid[];
  v_envoi jsonb;
  v_erreur text;
begin
  if p_charge ->> 'objet_type' <> 'loc_propositions' or p_charge ->> 'objet_id' is null then
    return jsonb_build_object('statut', 'ignoree');
  end if;
  select * into p from public.loc_propositions where id = (p_charge ->> 'objet_id')::uuid for update;
  if not found then
    return jsonb_build_object('statut', 'proposition_introuvable');
  end if;
  if p.demande_id is distinct from v_demande then
    return jsonb_build_object('statut', 'demande_depassee', 'proposition', p.id);
  end if;
  select * into d from public.demandes_validation where id = v_demande;
  select c.numero into v_numero from public.loc_contrats c where c.id = p.contrat_id;

  if v_statut = 'approuvee' then
    update public.loc_propositions set statut = 'validee' where id = p.id;
    perform private.journaliser_module(p.client_id, 'tavaro', 'tavaro.proposition_validee', 'loc_propositions', p.id::text,
      jsonb_build_object('demande', v_demande, 'decideurs', p_charge -> 'decideurs', 'montant', p.total_ttc), p.entite_id);
    begin
      v_factures := private.loc_emettre_factures(p.client_id, p.id);
    exception when others then
      v_erreur := left(sqlstate || ' ' || sqlerrm, 500);
      update public.demandes_validation set statut = 'echec_execution', motif_echec = v_erreur where id = v_demande and statut = 'approuvee';
      perform private.lever_alerte_module(p.client_id, 'tavaro', 'critique',
        format('La facture du contrat %s (%s € TTC) n''a pas pu être émise.', coalesce(v_numero, '?'), replace(p.total_ttc::text, '.', ',')),
        jsonb_build_object('proposition', p.id, 'demande', v_demande, 'erreur', v_erreur), 'facture:echec:' || p.id::text, false, null);
      return jsonb_build_object('statut', 'validee', 'facturation', 'echec', 'erreur', v_erreur, 'proposition', p.id);
    end;
    -- Le courriel, adossé à la même décision : c'est son départ qui l'exécute.
    v_envoi := private.loc_envoyer_factures(p.client_id, p.id);
    if v_envoi ->> 'statut' in ('rien', 'non_regle', 'sans_adresse') then
      update public.demandes_validation set statut = 'executee', motif_echec = null
       where id = v_demande and statut in ('approuvee', 'echec_execution');
    end if;
    return jsonb_build_object('statut', 'facturee', 'proposition', p.id, 'factures', to_jsonb(v_factures), 'envoi', v_envoi);
  elsif v_statut = 'rejetee' then
    update public.loc_propositions set statut = 'refusee' where id = p.id;
    perform private.journaliser_module(p.client_id, 'tavaro', 'tavaro.proposition_refusee', 'loc_propositions', p.id::text,
      jsonb_build_object('demande', v_demande, 'decideurs', p_charge -> 'decideurs'), p.entite_id);
    return jsonb_build_object('statut', 'refusee', 'proposition', p.id);
  elsif v_statut = 'expiree' then
    v_tentative := coalesce((d.payload ->> 'tentative')::integer, 1);
    if v_tentative >= 2 then
      update public.loc_propositions set statut = 'expiree' where id = p.id;
      perform private.lever_alerte_module(p.client_id, 'tavaro', 'attention',
        format('La proposition de facture du contrat %s (%s € TTC) n''a pas été décidée deux jours de suite.',
               coalesce(v_numero, '?'), replace(p.total_ttc::text, '.', ',')),
        jsonb_build_object('proposition', p.id, 'demande', v_demande, 'montant', p.total_ttc, 'tentatives', v_tentative),
        'proposition_expiree:' || p.id::text, true, null);
      perform private.journaliser_module(p.client_id, 'tavaro', 'tavaro.proposition_expiree', 'loc_propositions', p.id::text,
        jsonb_build_object('demande', v_demande, 'tentatives', v_tentative), p.entite_id);
      return jsonb_build_object('statut', 'expiree', 'proposition', p.id);
    end if;
    v_nouvelle := private.loc_deposer_demande(p.client_id, p.id, v_tentative + 1);
    perform private.journaliser_module(p.client_id, 'tavaro', 'tavaro.demande_redeposee', 'loc_propositions', p.id::text,
      jsonb_build_object('demande_expiree', v_demande, 'demande', v_nouvelle, 'tentative', v_tentative + 1), p.entite_id);
    return jsonb_build_object('statut', 'redeposee', 'proposition', p.id, 'demande', v_nouvelle);
  end if;
  return jsonb_build_object('statut', 'ignoree');
end $$;


--
-- Name: loc_appliquer_plafond(numeric[], numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_plafond(p_montants numeric[], p_plafond numeric) RETURNS numeric[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_reste numeric := p_plafond;
  v_res numeric[] := '{}';
  m numeric;
  v numeric;
begin
  if p_plafond is null then
    return coalesce(p_montants, '{}');
  end if;
  foreach m in array coalesce(p_montants, '{}'::numeric[]) loop
    v := least(m, greatest(v_reste, 0));
    v_reste := v_reste - v;
    v_res := array_append(v_res, v);
  end loop;
  return v_res;
end $$;


--
-- Name: loc_appliquer_releve(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_releve(p_client uuid, p_nature text, p_lignes jsonb, p_ctx jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_cle text := nullif(btrim(p_ctx ->> 'cle'), '');
  v_lu_le timestamptz := coalesce((p_ctx ->> 'lu_le')::timestamptz, now());
  v_source text := coalesce(p_ctx ->> 'source', 'export');
  r public.loc_releves;
  v_ligne jsonb;
  v_res jsonb;
  v_i integer := 0;
  v_n integer;
  v_effets jsonb := '{"creation": 0, "modification": 0, "disparition": 0, "inchangee": 0}'::jsonb;
  v_rejetees integer := 0;
  v_erreurs jsonb := '[]'::jsonb;
  v_avert jsonb := '[]'::jsonb;
  v_etat text;
  v_interne boolean := false;
  v_id uuid;
begin
  if p_nature is null or p_nature not in ('flotte', 'reservations', 'contrats') then
    raise exception 'Nature de relevé inconnue : %.', coalesce(p_nature, 'vide') using errcode = '22023';
  end if;
  if v_cle is null then
    raise exception 'Un relevé porte sa clé : la même source ne s''applique qu''une fois.' using errcode = '22023';
  end if;
  if v_source not in ('export', 'pdf', 'comptoir', 'connecteur') then
    raise exception 'Source de relevé inconnue : %.', v_source using errcode = '22023';
  end if;
  if not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  if p_lignes is null or jsonb_typeof(p_lignes) <> 'array' then
    raise exception 'Les lignes d''un relevé forment une liste.' using errcode = '22023';
  end if;

  select * into r from public.loc_releves where client_id = p_client and cle = v_cle;
  if found then
    return jsonb_build_object('releve', r.id, 'deja_applique', true, 'lignes', r.lignes, 'creations', r.creations,
                              'modifications', r.modifications, 'disparitions', r.disparitions,
                              'inchangees', r.inchangees, 'rejetees', r.rejetees);
  end if;

  perform set_config('omega.module', 'tavaro', true);
  for v_ligne in select e from jsonb_array_elements(p_lignes) e loop
    v_i := v_i + 1;
    v_n := coalesce(case when (v_ligne ->> 'n') ~ '^[0-9]{1,9}$' then (v_ligne ->> 'n')::integer end, v_i);
    begin
      v_res := case p_nature
        when 'flotte' then private.loc_appliquer_vehicule(p_client, v_ligne, p_ctx)
        when 'reservations' then private.loc_appliquer_reservation(p_client, v_ligne, p_ctx)
        else private.loc_appliquer_contrat(p_client, v_ligne, p_ctx)
      end;
      v_effets := jsonb_set(v_effets, array[v_res ->> 'effet'], to_jsonb((v_effets ->> (v_res ->> 'effet'))::integer + 1));
      v_avert := v_avert || coalesce((select jsonb_agg(a || jsonb_build_object('n', v_n))
                                      from jsonb_array_elements(coalesce(v_res -> 'avertissements', '[]'::jsonb)) a), '[]'::jsonb);
      if jsonb_typeof(v_ligne -> 'anomalies') = 'object' then
        v_avert := v_avert || coalesce((select jsonb_agg(jsonb_build_object('n', v_n, 'code', 'anomalie_de_lecture', 'champ', k))
                                        from jsonb_object_keys(v_ligne -> 'anomalies') k), '[]'::jsonb);
      end if;
    exception when others then
      get stacked diagnostics v_etat = returned_sqlstate;
      v_rejetees := v_rejetees + 1;
      -- Nos motifs (22023) ne citent que des noms de champs ; les autres erreurs
      -- ne sont jamais recopiées (elles pourraient porter une valeur).
      v_erreurs := v_erreurs || jsonb_build_array(jsonb_build_object('n', v_n,
        'motif', case when v_etat = '22023' then left(sqlerrm, 200) else 'erreur de données (' || v_etat || ')' end));
      if v_etat not like '22%' and v_etat not like '23%' then
        v_interne := true;
      end if;
    end;
  end loop;

  insert into public.loc_releves (client_id, entite_id, nature, source, cle, instantane_id, releve_id, piece_id, lu_le,
                                  lignes, creations, modifications, disparitions, inchangees, rejetees, erreurs,
                                  avertissements)
  values (p_client, (p_ctx ->> 'entite')::uuid, p_nature, v_source, v_cle, (p_ctx ->> 'instantane')::uuid,
          (p_ctx ->> 'releve')::uuid, (p_ctx ->> 'piece')::uuid, v_lu_le, v_i,
          (v_effets ->> 'creation')::integer, (v_effets ->> 'modification')::integer,
          (v_effets ->> 'disparition')::integer, (v_effets ->> 'inchangee')::integer, v_rejetees,
          (select coalesce(jsonb_agg(e), '[]'::jsonb) from (select e from jsonb_array_elements(v_erreurs) e limit 500) x),
          (select coalesce(jsonb_agg(a), '[]'::jsonb) from (select a from jsonb_array_elements(v_avert) a limit 500) x))
  returning id into v_id;

  if v_rejetees > 0 then
    perform private.lever_alerte_module(p_client, 'tavaro', case when v_interne then 'critique' else 'attention' end,
      format('Relevé des %s : %s ligne(s) rejetée(s) sur %s', p_nature, v_rejetees, v_i),
      jsonb_build_object('releve', v_id, 'nature', p_nature, 'rejetees', v_rejetees), 'releve:rejets:' || p_nature, false);
  end if;
  if v_source in ('export', 'connecteur') then
    perform private.battre(p_client, 'tavaro_releve',
      jsonb_build_object('releve', v_id, 'nature', p_nature, 'lignes', v_i, 'rejetees', v_rejetees, 'lu_le', v_lu_le),
      null);
  end if;

  perform set_config('omega.module', '', true);
  return jsonb_build_object('releve', v_id, 'deja_applique', false, 'lignes', v_i,
                            'creations', (v_effets ->> 'creation')::integer,
                            'modifications', (v_effets ->> 'modification')::integer,
                            'disparitions', (v_effets ->> 'disparition')::integer,
                            'inchangees', (v_effets ->> 'inchangee')::integer, 'rejetees', v_rejetees,
                            'erreurs', v_erreurs, 'avertissements', v_avert);
end $_$;


--
-- Name: loc_appliquer_releve_b1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_releve_b1(p_charge jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b public.branchements;
  i record;
  v_nature text;
  v_lignes jsonb;
  v_res jsonb;
  v_bilan jsonb := '{}'::jsonb;
  v_appliques integer := 0;
  v_refuses integer := 0;
  v_lu_le timestamptz;
begin
  select * into b from public.branchements where id = (p_charge ->> 'branchement')::uuid;
  if not found or b.module <> 'tavaro' then
    raise exception 'Branchement introuvable ou étranger à Tavaro.' using errcode = 'P0002';
  end if;

  for i in
    select x.id, x.lignes, x.recu_le, x.lu_le, j.code
    from public.instantanes x join public.branchements_jeux j on j.id = x.jeu_id
    where x.releve_id = (p_charge ->> 'releve')::uuid and x.branchement_id = b.id and x.statut = 'a_appliquer'
    order by case j.code when 'flotte' then 1 when 'reservations' then 2 when 'contrats' then 3 else 9 end, x.recu_le
  loop
    v_nature := case i.code when 'flotte' then 'flotte' when 'reservations' then 'reservations' when 'contrats' then 'contrats' end;
    if v_nature is null then
      perform private.acquitter_instantane(i.id, 'douteux', 'Tavaro ne connaît pas le jeu « ' || i.code || ' ».');
      v_refuses := v_refuses + 1;
      v_bilan := v_bilan || jsonb_build_object(i.code, jsonb_build_object('douteux', 'jeu inconnu'));
      continue;
    end if;
    v_lu_le := coalesce(i.lu_le, i.recu_le, now());

    select coalesce(jsonb_agg(jsonb_build_object(
             'n', e.n, 'cle', e.cle, 'nature', e.nature,
             'valeurs', case when e.nature = 'disparition' then e.avant else e.apres end,
             'anomalies', e.anomalies)
             || case when e.nature = 'modification' then jsonb_build_object('champs', to_jsonb(e.champs)) else '{}'::jsonb end
           order by e.n, e.id), '[]'::jsonb)
    into v_lignes
    from public.instantanes_ecarts e where e.instantane_id = i.id;

    v_res := private.loc_appliquer_releve(b.client_id, v_nature, v_lignes,
      jsonb_build_object('cle', 'b1:' || i.id::text, 'source', 'export', 'instantane', i.id,
                         'releve', (p_charge ->> 'releve')::uuid, 'entite', b.entite_id, 'lu_le', v_lu_le));

    -- La garde de Tavaro : un export dont aucune ligne n'a pu entrer ne fait pas l'état.
    if (v_res ->> 'lignes')::integer > 0 and (v_res ->> 'rejetees')::integer = (v_res ->> 'lignes')::integer then
      perform private.acquitter_instantane(i.id, 'douteux',
        format('Tavaro n''a pu appliquer aucune des %s ligne(s) : %s', v_res ->> 'lignes',
               coalesce(v_res -> 'erreurs' -> 0 ->> 'motif', 'motif inconnu')));
      v_refuses := v_refuses + 1;
      v_bilan := v_bilan || jsonb_build_object(i.code, v_res - 'erreurs' - 'avertissements' || '{"douteux": true}'::jsonb);
      continue;
    end if;
    perform private.acquitter_instantane(i.id, 'applique');
    v_appliques := v_appliques + 1;
    v_bilan := v_bilan || jsonb_build_object(i.code, v_res - 'erreurs' - 'avertissements');
  end loop;

  return jsonb_build_object('releve', p_charge ->> 'releve', 'appliques', v_appliques, 'refuses', v_refuses, 'jeux', v_bilan);
end $$;


--
-- Name: loc_appliquer_reservation(uuid, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_reservation(p_client uuid, p_ligne jsonb, p_ctx jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v jsonb := coalesce(p_ligne -> 'valeurs', '{}'::jsonb);
  v_lu_le timestamptz := coalesce((p_ctx ->> 'lu_le')::timestamptz, now());
  v_ref text := private.loc_lire_texte(v, 'reference', 80);
  c public.loc_reservations;
  n public.loc_reservations;
  v_existe boolean;
  v_neuf jsonb := '{}'::jsonb;
  v_avert jsonb := '[]'::jsonb;
  v_agence record;
  v_retour record;
  v_statut text;
  v_heure text;
  k text;
begin
  if v_ref is null then
    raise exception 'Champ obligatoire manquant : reference.' using errcode = '22023';
  end if;
  select * into c from public.loc_reservations where client_id = p_client and ref_source = v_ref for update;
  v_existe := found;

  if coalesce(p_ligne ->> 'nature', 'ajout') = 'disparition' then
    if not v_existe or c.disparue_le is not null then
      return jsonb_build_object('effet', 'inchangee');
    end if;
    update public.loc_reservations set disparue_le = v_lu_le where id = c.id;
    return jsonb_build_object('effet', 'disparition');
  end if;

  select * into v_agence from private.loc_resoudre_agence(p_client, v ->> 'agence',
    coalesce(c.entite_id, (p_ctx ->> 'entite')::uuid));
  if v_agence.entite_id is null then
    raise exception 'Champ obligatoire manquant : agence.' using errcode = '22023';
  end if;
  if private.loc_porte(p_ligne, 'agence') then
    v_neuf := v_neuf || jsonb_build_object('entite_id', v_agence.entite_id);
  end if;
  select * into v_retour from private.loc_resoudre_agence(p_client, null, coalesce(c.entite_retour_id, v_agence.entite_id));
  if private.loc_porte(p_ligne, 'agence_retour') then
    if nullif(btrim(v ->> 'agence_retour'), '') is null then
      v_neuf := v_neuf || jsonb_build_object('entite_retour_id', null);
    else
      select * into v_retour from private.loc_resoudre_agence(p_client, v ->> 'agence_retour', null);
      v_neuf := v_neuf || jsonb_build_object('entite_retour_id', v_retour.entite_id);
    end if;
  end if;
  if private.loc_porte(p_ligne, 'depart_prevu_le') then
    v_neuf := v_neuf || jsonb_build_object('depart_prevu_le', private.loc_lire_instant(v, 'depart_prevu_le', v_agence.fuseau));
  end if;
  if private.loc_porte(p_ligne, 'retour_prevu_le') then
    v_neuf := v_neuf || jsonb_build_object('retour_prevu_le', private.loc_lire_instant(v, 'retour_prevu_le', v_retour.fuseau));
  end if;
  foreach k in array array['depart_prevu_le', 'retour_prevu_le'] loop
    v_heure := private.loc_heure_douteuse(v ->> k, case k when 'depart_prevu_le' then v_agence.fuseau else v_retour.fuseau end);
    if v_heure is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'heure_' || v_heure, 'champ', k));
    end if;
  end loop;
  if private.loc_porte(p_ligne, 'categorie') then
    v_neuf := v_neuf || jsonb_build_object('categorie_id', private.loc_resoudre_categorie(p_client, v ->> 'categorie'));
  end if;
  if private.loc_porte(p_ligne, 'immatriculation') then
    v_neuf := v_neuf || jsonb_build_object('vehicule_id',
      private.loc_resoudre_vehicule(p_client, v ->> 'immatriculation', v_agence.entite_id,
        coalesce((v_neuf ->> 'categorie_id')::uuid, c.categorie_id)));
  end if;
  if private.loc_porte(p_ligne, 'statut') then
    v_statut := private.loc_statut_reservation(v ->> 'statut');
    if v_statut is null and nullif(btrim(v ->> 'statut'), '') is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'statut_inconnu', 'champ', 'statut'));
    elsif v_statut is not null then
      v_neuf := v_neuf || jsonb_build_object('statut', v_statut);
    end if;
  end if;
  if private.loc_porte(p_ligne, 'canal') then
    v_neuf := v_neuf || jsonb_build_object('canal', lower(private.loc_lire_texte(v, 'canal', 60)));
  end if;
  if private.loc_porte(p_ligne, 'prepaye') then
    v_neuf := v_neuf || jsonb_build_object('prepaye', private.loc_lire_booleen(v, 'prepaye'));
  end if;
  if private.loc_porte(p_ligne, 'acompte') then
    v_neuf := v_neuf || jsonb_build_object('acompte_eur', private.loc_lire_decimal(v, 'acompte'));
  end if;
  if private.loc_porte(p_ligne, 'vol') then
    v_neuf := v_neuf || jsonb_build_object('vol', upper(private.loc_lire_texte(v, 'vol', 20)));
  end if;
  if private.loc_porte(p_ligne, 'notes') then
    v_neuf := v_neuf || jsonb_build_object('notes', private.loc_lire_texte(v, 'notes', 2000));
  end if;
  if exists (select 1 from jsonb_object_keys(v) x where x like 'locataire\_%') then
    v_neuf := v_neuf || jsonb_build_object('locataire_id', coalesce(private.loc_resoudre_locataire(p_client, v), c.locataire_id));
  end if;

  if not v_existe then
    c.id := gen_random_uuid();
    c.client_id := p_client;
    c.ref_source := v_ref;
    c.entite_id := v_agence.entite_id;
    c.statut := 'confirmee';
  end if;
  n := jsonb_populate_record(c, to_jsonb(c) || v_neuf);
  n.disparue_le := null;
  if n.depart_prevu_le is null or n.retour_prevu_le is null then
    raise exception 'Champ obligatoire manquant : %.',
      case when n.depart_prevu_le is null then 'depart_prevu_le' else 'retour_prevu_le' end using errcode = '22023';
  end if;
  if n.retour_prevu_le <= n.depart_prevu_le then
    raise exception 'Le retour prévu doit suivre le départ (retour_prevu_le).' using errcode = '22023';
  end if;

  if not v_existe then
    insert into public.loc_reservations (id, client_id, entite_id, ref_source, canal, categorie_id, vehicule_id,
                                         locataire_id, entite_retour_id, depart_prevu_le, retour_prevu_le, statut,
                                         prepaye, acompte_eur, vol, notes)
    values (n.id, n.client_id, n.entite_id, n.ref_source, n.canal, n.categorie_id, n.vehicule_id, n.locataire_id,
            n.entite_retour_id, n.depart_prevu_le, n.retour_prevu_le, n.statut, n.prepaye, n.acompte_eur, n.vol, n.notes);
    return jsonb_build_object('effet', 'creation', 'avertissements', v_avert);
  end if;
  if (to_jsonb(n) - 'maj_le') = (to_jsonb(c) - 'maj_le') then
    return jsonb_build_object('effet', 'inchangee', 'avertissements', v_avert);
  end if;
  update public.loc_reservations
     set entite_id = n.entite_id, canal = n.canal, categorie_id = n.categorie_id, vehicule_id = n.vehicule_id,
         locataire_id = n.locataire_id, entite_retour_id = n.entite_retour_id, depart_prevu_le = n.depart_prevu_le,
         retour_prevu_le = n.retour_prevu_le, statut = n.statut, prepaye = n.prepaye, acompte_eur = n.acompte_eur,
         vol = n.vol, notes = n.notes, disparue_le = n.disparue_le
   where id = c.id;
  return jsonb_build_object('effet', 'modification', 'avertissements', v_avert);
end $$;


--
-- Name: loc_appliquer_vehicule(uuid, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_appliquer_vehicule(p_client uuid, p_ligne jsonb, p_ctx jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v jsonb := coalesce(p_ligne -> 'valeurs', '{}'::jsonb);
  v_lu_le timestamptz := coalesce((p_ctx ->> 'lu_le')::timestamptz, now());
  v_plaque record;
  c public.loc_vehicules;
  n public.loc_vehicules;
  v_existe boolean;
  v_neuf jsonb := '{}'::jsonb;
  v_avert jsonb := '[]'::jsonb;
  v_agence record;
  v_km integer;
  v_km_le timestamptz;
begin
  select * into v_plaque from private.loc_plaque(v ->> 'immatriculation');
  if v_plaque.plaque is null then
    raise exception 'Champ obligatoire manquant : immatriculation.' using errcode = '22023';
  end if;
  select * into c from public.loc_vehicules where client_id = p_client and immatriculation = v_plaque.plaque for update;
  v_existe := found;

  if coalesce(p_ligne ->> 'nature', 'ajout') = 'disparition' then
    if not v_existe or c.disparu_le is not null then
      return jsonb_build_object('effet', 'inchangee');
    end if;
    update public.loc_vehicules set disparu_le = v_lu_le where id = c.id;
    perform private.lever_alerte_module(p_client, 'tavaro', 'attention',
      'Des véhicules ne figurent plus dans le fichier de flotte : à sortir ou à expliquer',
      jsonb_build_object('vehicule', c.id), 'releve:vehicules_disparus', true);
    return jsonb_build_object('effet', 'disparition');
  end if;

  if private.loc_porte(p_ligne, 'agence') then
    select * into v_agence from private.loc_resoudre_agence(p_client, v ->> 'agence', null);
    v_neuf := v_neuf || jsonb_build_object('entite_id', v_agence.entite_id);
  end if;
  if private.loc_porte(p_ligne, 'categorie') then
    v_neuf := v_neuf || jsonb_build_object('categorie_id', private.loc_resoudre_categorie(p_client, v ->> 'categorie'));
  end if;
  if private.loc_porte(p_ligne, 'vin') then
    if upper(regexp_replace(coalesce(v ->> 'vin', ''), '\s', '', 'g')) ~ '^[A-HJ-NPR-Z0-9]{17}$' then
      v_neuf := v_neuf || jsonb_build_object('vin', upper(regexp_replace(v ->> 'vin', '\s', '', 'g')));
    elsif nullif(btrim(v ->> 'vin'), '') is not null then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'vin_illisible', 'plaque', v_plaque.plaque));
    end if;
  end if;
  if private.loc_porte(p_ligne, 'modele') then
    v_neuf := v_neuf || jsonb_build_object('modele', private.loc_lire_texte(v, 'modele', 120));
  end if;
  if private.loc_porte(p_ligne, 'energie') then
    v_neuf := v_neuf || jsonb_build_object('energie', private.loc_energie(v ->> 'energie'));
    if private.loc_energie(v ->> 'energie') = 'autre' then
      v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'energie_inconnue', 'plaque', v_plaque.plaque));
    end if;
  end if;
  if private.loc_porte(p_ligne, 'reservoir_l') then
    v_neuf := v_neuf || jsonb_build_object('reservoir_l', private.loc_lire_decimal(v, 'reservoir_l'));
  end if;
  if private.loc_porte(p_ligne, 'batterie_kwh') then
    v_neuf := v_neuf || jsonb_build_object('batterie_kwh', private.loc_lire_decimal(v, 'batterie_kwh'));
  end if;
  if private.loc_porte(p_ligne, 'mise_en_circulation') then
    v_neuf := v_neuf || jsonb_build_object('mise_en_circulation', private.loc_lire_date(v, 'mise_en_circulation'));
  end if;
  if private.loc_porte(p_ligne, 'ref') then
    v_neuf := v_neuf || jsonb_build_object('ref_source', private.loc_lire_texte(v, 'ref', 80));
  end if;

  if not v_existe then
    c.id := gen_random_uuid();
    c.client_id := p_client;
    c.immatriculation := v_plaque.plaque;
    c.format_plaque := v_plaque.format;
    c.statut := 'actif';
    c.entite_id := (p_ctx ->> 'entite')::uuid;
  end if;
  n := jsonb_populate_record(c, to_jsonb(c) || v_neuf);
  if v_existe and c.statut = 'a_confirmer' then
    n.statut := 'actif';
  elsif v_existe and c.statut = 'sorti' then
    v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'vehicule_sorti_present', 'plaque', v_plaque.plaque));
  end if;
  if v_plaque.format <> 'siv' then
    v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'plaque_' || v_plaque.format, 'plaque', v_plaque.plaque));
  end if;
  v_km := private.loc_lire_entier(v, 'km');
  if v_km is not null then
    v_km_le := coalesce(private.loc_lire_instant(v, 'km_le',
                 coalesce((select e.fuseau from public.entites e where e.client_id = p_client and e.id = n.entite_id),
                          'Europe/Paris'), false), v_lu_le);
    if n.km_dernier_le is null or v_km_le >= n.km_dernier_le then
      if n.km_dernier is not null and v_km < n.km_dernier then
        v_avert := v_avert || jsonb_build_array(jsonb_build_object('code', 'compteur_decroissant', 'plaque', v_plaque.plaque));
      end if;
      n.km_dernier := v_km;
      n.km_dernier_le := v_km_le;
    end if;
  end if;
  n.disparu_le := null;

  if not v_existe then
    insert into public.loc_vehicules (id, client_id, entite_id, immatriculation, format_plaque, vin, modele, categorie_id,
                                      energie, reservoir_l, batterie_kwh, mise_en_circulation, statut, km_dernier,
                                      km_dernier_le, ref_source)
    values (n.id, n.client_id, n.entite_id, n.immatriculation, n.format_plaque, n.vin, n.modele, n.categorie_id,
            n.energie, n.reservoir_l, n.batterie_kwh, n.mise_en_circulation, n.statut, n.km_dernier,
            n.km_dernier_le, n.ref_source);
    return jsonb_build_object('effet', 'creation', 'avertissements', v_avert);
  end if;
  if (to_jsonb(n) - 'maj_le') = (to_jsonb(c) - 'maj_le') then
    return jsonb_build_object('effet', 'inchangee', 'avertissements', v_avert);
  end if;
  update public.loc_vehicules
     set entite_id = n.entite_id, vin = n.vin, modele = n.modele, categorie_id = n.categorie_id, energie = n.energie,
         reservoir_l = n.reservoir_l, batterie_kwh = n.batterie_kwh, mise_en_circulation = n.mise_en_circulation,
         statut = n.statut, km_dernier = n.km_dernier, km_dernier_le = n.km_dernier_le, ref_source = n.ref_source,
         disparu_le = n.disparu_le
   where id = c.id;
  return jsonb_build_object('effet', 'modification', 'avertissements', v_avert);
end $_$;


--
-- Name: loc_arrondir(numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_arrondir(p numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select round(p, 2)
$$;


--
-- Name: loc_bareme_en_vigueur(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_bareme_en_vigueur(p_client uuid, p_date date) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select b.id from public.loc_baremes b
  where b.client_id = p_client and b.statut = 'publie' and b.date_effet <= p_date
  order by b.date_effet desc limit 1
$$;


--
-- Name: loc_calc_carburant(text, integer, integer, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_calc_carburant(p_politique text, p_depart_8 integer, p_retour_8 integer, p_reservoir_l numeric, p_prix_huitieme numeric, p_prix_litre numeric, p_frais_service numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_manquant integer;
  v_litres numeric;
  v_montant numeric;
begin
  if p_depart_8 not between 0 and 8 or p_retour_8 not between 0 and 8 then
    raise exception 'Un niveau de carburant se compte en huitièmes, de 0 à 8.' using errcode = '22023';
  end if;
  if p_politique = 'prepaye' then
    return jsonb_build_object('montant_ht', 0, 'motif', 'prepaye', 'a_verifier', false);
  elsif p_politique = 'seuil' then
    return jsonb_build_object('montant_ht', 0, 'motif', 'voir_charge', 'a_verifier', false);
  elsif coalesce(p_politique, '') not in ('plein_contre_plein', 'meme_niveau') then
    return jsonb_build_object('montant_ht', 0, 'motif', 'politique_inconnue', 'a_verifier', true);
  end if;
  if p_depart_8 is null or p_retour_8 is null then
    return jsonb_build_object('montant_ht', 0, 'motif', 'niveau_inconnu', 'a_verifier', true);
  end if;
  v_manquant := greatest(0, p_depart_8 - p_retour_8);
  if v_manquant = 0 then
    return jsonb_build_object('manquant', 0, 'montant_ht', 0, 'motif', 'niveau_rendu_suffisant', 'a_verifier', false);
  end if;
  if p_prix_huitieme is not null then
    return jsonb_build_object('manquant', v_manquant, 'unite', 'huitieme', 'quantite', v_manquant,
                              'prix_unitaire', p_prix_huitieme, 'montant_ht', round(v_manquant * p_prix_huitieme, 2),
                              'a_verifier', false);
  elsif p_prix_litre is not null then
    if p_reservoir_l is null or p_reservoir_l <= 0 then
      return jsonb_build_object('manquant', v_manquant, 'montant_ht', 0, 'motif', 'reservoir_inconnu', 'a_verifier', true);
    end if;
    v_litres := round(v_manquant * p_reservoir_l / 8, 2);
    v_montant := round(v_litres * p_prix_litre, 2) + coalesce(p_frais_service, 0);
    return jsonb_build_object('manquant', v_manquant, 'unite', 'litre', 'quantite', v_litres,
                              'prix_unitaire', p_prix_litre, 'frais_service', coalesce(p_frais_service, 0),
                              'montant_ht', round(v_montant, 2), 'a_verifier', false);
  end if;
  return jsonb_build_object('manquant', v_manquant, 'montant_ht', 0, 'motif', 'poste_absent_du_bareme', 'a_verifier', true);
end $$;


--
-- Name: loc_calc_charge(integer, integer, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_calc_charge(p_seuil_pct integer, p_retour_pct integer, p_forfait numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_seuil_pct is null or p_retour_pct is null then
    return jsonb_build_object('montant_ht', 0, 'motif', 'niveau_inconnu', 'a_verifier', true);
  end if;
  if p_retour_pct >= p_seuil_pct then
    return jsonb_build_object('montant_ht', 0, 'motif', 'charge_suffisante', 'a_verifier', false);
  end if;
  if p_forfait is null then
    return jsonb_build_object('montant_ht', 0, 'motif', 'poste_absent_du_bareme', 'a_verifier', true);
  end if;
  return jsonb_build_object('unite', 'forfait', 'quantite', 1, 'prix_unitaire', p_forfait,
                            'montant_ht', round(p_forfait, 2), 'a_verifier', false);
end $$;


--
-- Name: loc_calc_km(integer, integer, integer, integer, boolean, integer, numeric, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_calc_km(p_km_depart integer, p_km_retour integer, p_km_inclus integer, p_km_inclus_jour integer, p_km_illimite boolean, p_jours integer, p_heures numeric, p_prix_km numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_parcourus integer;
  v_inclus integer;
  v_dep integer;
begin
  if coalesce(p_km_illimite, false) then
    return jsonb_build_object('montant_ht', 0, 'motif', 'illimite', 'a_verifier', false);
  end if;
  if p_km_depart is null or p_km_retour is null then
    return jsonb_build_object('montant_ht', 0, 'motif', 'compteur_inconnu', 'a_verifier', true);
  end if;
  if p_km_retour < p_km_depart then
    return jsonb_build_object('montant_ht', 0, 'motif', 'compteur_decroissant', 'a_verifier', true);
  end if;
  v_parcourus := p_km_retour - p_km_depart;
  if p_heures is not null and p_heures > 0 and v_parcourus / p_heures > 150 then
    return jsonb_build_object('parcourus', v_parcourus, 'montant_ht', 0, 'motif', 'kilometrage_implausible', 'a_verifier', true);
  end if;
  v_inclus := coalesce(p_km_inclus, p_km_inclus_jour * greatest(p_jours, 1));
  if v_inclus is null then
    return jsonb_build_object('parcourus', v_parcourus, 'montant_ht', 0, 'motif', 'forfait_inconnu', 'a_verifier', true);
  end if;
  v_dep := greatest(0, v_parcourus - v_inclus);
  if v_dep = 0 then
    return jsonb_build_object('parcourus', v_parcourus, 'inclus', v_inclus, 'depassement', 0, 'montant_ht', 0,
                              'motif', 'dans_le_forfait', 'a_verifier', false);
  end if;
  if p_prix_km is null then
    return jsonb_build_object('parcourus', v_parcourus, 'inclus', v_inclus, 'depassement', v_dep, 'montant_ht', 0,
                              'motif', 'poste_absent_du_bareme', 'a_verifier', true);
  end if;
  return jsonb_build_object('parcourus', v_parcourus, 'inclus', v_inclus, 'depassement', v_dep, 'unite', 'km',
                            'quantite', v_dep, 'prix_unitaire', p_prix_km, 'montant_ht', round(v_dep * p_prix_km, 2),
                            'a_verifier', false);
end $$;


--
-- Name: loc_calc_retard(timestamp with time zone, timestamp with time zone, text, integer, numeric, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_calc_retard(p_retour_prevu timestamp with time zone, p_retour_reel timestamp with time zone, p_fuseau text, p_tolerance_min integer, p_prix_jour numeric, p_offert boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_min integer;
  v_jours integer;
begin
  if p_retour_reel is null then
    return jsonb_build_object('montant_ht', 0, 'motif', 'retour_inconnu', 'a_verifier', true);
  end if;
  if p_retour_prevu is null then
    return jsonb_build_object('montant_ht', 0, 'motif', 'retour_prevu_inconnu', 'a_verifier', true);
  end if;
  if p_fuseau is null then
    raise exception 'Fuseau de l''agence manquant.' using errcode = '22023';
  end if;
  v_min := round(extract(epoch from ((p_retour_reel at time zone p_fuseau) - (p_retour_prevu at time zone p_fuseau))) / 60)::integer;
  if coalesce(p_offert, false) then
    return jsonb_build_object('retard_min', v_min, 'montant_ht', 0, 'motif', 'retard_offert', 'a_verifier', false);
  end if;
  if v_min <= 0 then
    return jsonb_build_object('retard_min', v_min, 'montant_ht', 0, 'motif', 'rendu_a_l_heure', 'a_verifier', false);
  end if;
  if v_min <= coalesce(p_tolerance_min, 0) then
    return jsonb_build_object('retard_min', v_min, 'montant_ht', 0, 'motif', 'dans_la_tolerance', 'a_verifier', false);
  end if;
  v_jours := ceil(v_min / 1440.0);
  if p_prix_jour is null then
    return jsonb_build_object('retard_min', v_min, 'jours', v_jours, 'montant_ht', 0, 'motif', 'tarif_inconnu', 'a_verifier', true);
  end if;
  return jsonb_build_object('retard_min', v_min, 'jours', v_jours, 'unite', 'jour_entame', 'quantite', v_jours,
                            'prix_unitaire', p_prix_jour, 'montant_ht', round(v_jours * p_prix_jour, 2), 'a_verifier', false);
end $$;


--
-- Name: loc_chiffrer_et_soumettre(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_chiffrer_et_soumettre(p_client uuid, p_contrat uuid, p_retour jsonb, p_source text, p_par uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_prop uuid;
begin
  if exists (select 1 from public.loc_propositions x where x.client_id = p_client and x.contrat_id = p_contrat and x.statut = 'facturee') then
    raise exception 'Ce contrat est déjà facturé : une correction passe par un avoir.' using errcode = '55000';
  end if;
  perform private.loc_annuler_attente(p_client, p_contrat);
  v_prop := private.loc_chiffrer_retour(p_client, p_contrat, p_retour, p_source, p_par);
  if (select x.statut from public.loc_propositions x where x.id = v_prop) = 'calculee' then
    perform private.deposer_travail(p_client, 'tavaro', 'tavaro.deposer_demande', jsonb_build_object('proposition', v_prop),
                                    'tavaro:deposer:' || v_prop::text, 0::smallint);
  end if;
  return v_prop;
end $$;


--
-- Name: loc_chiffrer_retour(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_chiffrer_retour(p_client uuid, p_contrat uuid, p_retour jsonb, p_source text, p_par uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.loc_contrats;
  v public.loc_vehicules;
  lb public.loc_bareme_lignes;
  lb2 public.loc_bareme_lignes;
  v_fuseau text;
  v_tol integer;
  v_bareme uuid;
  v_taux numeric;
  v_prop uuid;
  v_version integer;
  v_rang integer := 0;
  v_avert jsonb := '[]'::jsonb;
  v_bloque boolean := false;
  v_hors boolean := false;
  v_non_contra boolean;
  v_retour_reel timestamptz;
  v_retour_prevu timestamptz;
  v_km_retour integer;
  v_dep8 integer;
  v_ret8 integer;
  v_charge integer;
  v_jours integer;
  v_heures numeric;
  v_plafond numeric;
  r_retard jsonb;
  r_km jsonb;
  r_carb jsonb;
  d jsonb;
  v_code text;
  v_preuves jsonb;
  v_quantite numeric;
  v_montant numeric;
  v_statut_ligne text;
  v_calcul jsonb;
  v_dommages numeric[] := '{}';
  v_plafonnes numeric[];
  v_ids uuid[] := '{}';
  v_i integer;
  v_nb_lignes integer;
  v_total_ht numeric;
  v_total_tva numeric;
  v_total_ttc numeric;
  v_statut text;
begin
  -- Le contrat, ses conditions, son agence.
  select * into c from public.loc_contrats where client_id = p_client and id = p_contrat for update;
  if not found then
    raise exception 'Contrat introuvable.' using errcode = 'P0002';
  end if;
  if c.statut = 'annule' then
    raise exception 'Ce contrat est annulé : rien à facturer.' using errcode = '23514';
  end if;
  if exists (select 1 from public.loc_propositions p where p.client_id = p_client and p.contrat_id = c.id and p.statut in ('a_valider', 'validee')) then
    raise exception 'Une proposition de ce contrat est déjà à la validation ou validée : elle ne se recalcule pas.' using errcode = '55000';
  end if;
  if p_retour is null or jsonb_typeof(p_retour) <> 'object' then
    raise exception 'Les valeurs du retour sont illisibles.' using errcode = '22023';
  end if;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = c.entite_id;
  v_tol := coalesce((select g.tolerance_retard_min from public.loc_reglages g where g.client_id = p_client), 59);
  if c.vehicule_id is not null then
    select * into v from public.loc_vehicules x where x.client_id = p_client and x.id = c.vehicule_id;
  end if;
  v_bareme := private.loc_bareme_en_vigueur(p_client, (c.depart_le at time zone v_fuseau)::date);
  v_taux := private.loc_taux_tva(p_client, c.entite_id, null);

  -- Les valeurs du retour.
  begin
    v_retour_reel := coalesce((p_retour ->> 'retour_reel_le')::timestamptz, c.retour_reel_le);
    v_km_retour := coalesce((p_retour ->> 'km_retour')::integer, c.km_retour);
    v_dep8 := (p_retour ->> 'carburant_depart_8')::integer;
    v_ret8 := (p_retour ->> 'carburant_retour_8')::integer;
    v_charge := (p_retour ->> 'charge_retour_pct')::integer;
    v_non_contra := coalesce((p_retour ->> 'non_contradictoire')::boolean, false);
  exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow or invalid_datetime_format then
    raise exception 'Une valeur du retour est illisible : %.', sqlerrm using errcode = '22023';
  end;
  v_retour_prevu := private.loc_retour_prevu_amende(c.id);
  v_jours := greatest(1, ceil(extract(epoch from ((v_retour_prevu at time zone v_fuseau) - (c.depart_le at time zone v_fuseau))) / 86400.0))::integer;
  v_heures := case when v_retour_reel is not null then extract(epoch from (v_retour_reel - c.depart_le)) / 3600.0 end;

  -- La proposition, nouvelle version ; les précédentes non décidées sont remplacées.
  select coalesce(max(p.version), 0) + 1 into v_version from public.loc_propositions p where p.client_id = p_client and p.contrat_id = c.id;
  update public.loc_propositions set statut = 'remplacee'
   where client_id = p_client and contrat_id = c.id and statut in ('calculee', 'preuve_manquante', 'rien_a_facturer');
  insert into public.loc_propositions (client_id, entite_id, contrat_id, version, source, bareme_id, non_contradictoire, entrees, calculee_par)
  values (p_client, c.entite_id, c.id, v_version, p_source, v_bareme, v_non_contra,
          p_retour - 'dommages' - 'postes' - 'preuves', p_par)
  returning id into v_prop;

  if v_bareme is null then
    v_avert := v_avert || jsonb_build_object('poste', 'bareme', 'code', 'bareme_absent', 'bloquant', true,
      'detail', 'Aucun barème en vigueur à la date du départ : la direction doit en publier un.');
    v_bloque := true;
  else
    -- 1. Carburant, ou charge.
    if c.politique_carburant = 'seuil' then
      lb := private.loc_ligne_bareme(v_bareme, 'CHARGE_SOUS_SEUIL', c.categorie_id);
      r_carb := private.loc_calc_charge(c.seuil_charge_pct, v_charge, lb.prix_eur);
      if (r_carb ->> 'montant_ht')::numeric > 0 then
        v_rang := v_rang + 1;
        perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'frais', 'carburant', lb.code, lb.libelle, lb.id, 'forfait', 1, lb.prix_eur,
          (r_carb ->> 'montant_ht')::numeric, lb.regime_tva, private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), 'chiffree',
          r_carb, p_retour -> 'preuves' -> 'carburant', false);
      end if;
    else
      lb := private.loc_ligne_bareme_par(v_bareme, 'carburant', 'huitieme', c.categorie_id);
      lb2 := private.loc_ligne_bareme_par(v_bareme, 'carburant', 'litre', c.categorie_id);
      r_carb := private.loc_calc_carburant(c.politique_carburant, v_dep8, v_ret8, v.reservoir_l, lb.prix_eur, lb2.prix_eur,
                  (private.loc_ligne_bareme(v_bareme, 'CARBURANT_SERVICE', c.categorie_id)).prix_eur);
      if (r_carb ->> 'montant_ht')::numeric > 0 then
        v_rang := v_rang + 1;
        if r_carb ->> 'unite' = 'huitieme' then
          perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'frais', 'carburant', lb.code, lb.libelle, lb.id, 'huitieme',
            (r_carb ->> 'quantite')::numeric, lb.prix_eur, (r_carb ->> 'montant_ht')::numeric, lb.regime_tva,
            private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), 'chiffree', r_carb, p_retour -> 'preuves' -> 'carburant', false);
        else
          perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'frais', 'carburant', lb2.code, lb2.libelle, lb2.id, 'litre',
            (r_carb ->> 'quantite')::numeric, lb2.prix_eur, (r_carb ->> 'montant_ht')::numeric - coalesce((r_carb ->> 'frais_service')::numeric, 0),
            lb2.regime_tva, private.loc_taux_tva(p_client, c.entite_id, lb2.taux_tva), 'chiffree', r_carb - 'frais_service',
            p_retour -> 'preuves' -> 'carburant', false);
          if coalesce((r_carb ->> 'frais_service')::numeric, 0) > 0 then
            lb := private.loc_ligne_bareme(v_bareme, 'CARBURANT_SERVICE', c.categorie_id);
            v_rang := v_rang + 1;
            perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'frais', 'carburant', lb.code, lb.libelle, lb.id, 'forfait', 1, lb.prix_eur,
              lb.prix_eur, lb.regime_tva, private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), 'chiffree', '{}'::jsonb,
              p_retour -> 'preuves' -> 'carburant', false);
          end if;
        end if;
      end if;
    end if;
    if (r_carb ->> 'a_verifier')::boolean then
      v_avert := v_avert || jsonb_build_object('poste', 'carburant', 'code', r_carb ->> 'motif',
        'bloquant', r_carb ->> 'motif' <> 'poste_absent_du_bareme');
      v_bloque := v_bloque or r_carb ->> 'motif' <> 'poste_absent_du_bareme';
    end if;

    -- 2. Kilomètres.
    lb := private.loc_ligne_bareme_par(v_bareme, 'kilometres', 'km', c.categorie_id);
    r_km := private.loc_calc_km(c.km_depart, v_km_retour, c.km_inclus, c.km_inclus_jour, c.km_illimite, v_jours, v_heures, lb.prix_eur);
    if (r_km ->> 'montant_ht')::numeric > 0 then
      v_rang := v_rang + 1;
      perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'frais', 'kilometres', lb.code, lb.libelle, lb.id, 'km',
        (r_km ->> 'quantite')::numeric, lb.prix_eur, (r_km ->> 'montant_ht')::numeric, lb.regime_tva,
        private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), 'chiffree', r_km, p_retour -> 'preuves' -> 'km', false);
    end if;
    if (r_km ->> 'a_verifier')::boolean then
      v_avert := v_avert || jsonb_build_object('poste', 'kilometres', 'code', r_km ->> 'motif',
        'bloquant', r_km ->> 'motif' <> 'poste_absent_du_bareme');
      v_bloque := v_bloque or r_km ->> 'motif' <> 'poste_absent_du_bareme';
    end if;

    -- 3. Retard, en heure locale, au tarif du contrat (ou au prix de la ligne).
    lb := private.loc_ligne_bareme_par(v_bareme, 'retard', 'jour_entame', c.categorie_id);
    r_retard := private.loc_calc_retard(v_retour_prevu, v_retour_reel, v_fuseau, v_tol, coalesce(lb.prix_eur, c.tarif_jour_eur),
                                        private.loc_retard_offert(c.id));
    if (r_retard ->> 'montant_ht')::numeric > 0 then
      if lb.id is null then
        v_avert := v_avert || jsonb_build_object('poste', 'retard', 'code', 'poste_absent_du_bareme', 'bloquant', false);
      else
        v_rang := v_rang + 1;
        perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'frais', 'retard', lb.code, lb.libelle, lb.id, 'jour_entame',
          (r_retard ->> 'quantite')::numeric, (r_retard ->> 'prix_unitaire')::numeric, (r_retard ->> 'montant_ht')::numeric, lb.regime_tva,
          private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), 'chiffree', r_retard, p_retour -> 'preuves' -> 'retard', false);
      end if;
    elsif (r_retard ->> 'a_verifier')::boolean then
      v_avert := v_avert || jsonb_build_object('poste', 'retard', 'code', r_retard ->> 'motif', 'bloquant', true);
      v_bloque := true;
    end if;

    -- 4. Dommages confirmés : au barème de la catégorie, sur devis, ou au prix de l'agence (hors barème).
    v_plafond := private.loc_plafond_franchise(c.franchise_eur, c.franchise_reduite_eur, c.rachat_franchise);
    for d in select * from jsonb_array_elements(coalesce(p_retour -> 'dommages', '[]'::jsonb)) loop
      v_code := upper(btrim(d ->> 'code'));
      v_preuves := coalesce(d -> 'preuves', '[]'::jsonb);
      v_quantite := coalesce(nullif(d ->> 'quantite', '')::numeric, 1);
      lb := private.loc_ligne_bareme(v_bareme, v_code, c.categorie_id);
      if lb.id is null then
        if nullif(d ->> 'prix_eur', '') is not null then
          v_hors := true;
          v_rang := v_rang + 1;
          perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'dommage', 'dommage', v_code, coalesce(d ->> 'libelle', v_code), null, 'forfait',
            v_quantite, (d ->> 'prix_eur')::numeric, v_quantite * (d ->> 'prix_eur')::numeric, coalesce(d ->> 'regime_tva', 'hors_champ'),
            v_taux, case when jsonb_array_length(v_preuves) = 0 then 'preuve_manquante' else 'chiffree' end,
            jsonb_build_object('hors_bareme', true, 'prix_agence', (d ->> 'prix_eur')::numeric), v_preuves, true);
        else
          v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'poste_absent_du_bareme', 'bloquant', false);
          continue;
        end if;
      else
        v_calcul := jsonb_build_object('ligne', lb.code, 'unite', lb.unite);
        if jsonb_array_length(v_preuves) = 0 then
          v_statut_ligne := 'preuve_manquante'; v_montant := 0;
          v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'preuve_absente', 'bloquant', true);
          v_bloque := true;
        elsif lb.unite = 'devis' then
          if nullif(d ->> 'devis_eur', '') is not null then
            v_statut_ligne := 'chiffree'; v_montant := (d ->> 'devis_eur')::numeric; v_calcul := v_calcul || '{"devis": true}'::jsonb;
          else
            v_statut_ligne := 'a_chiffrer'; v_montant := 0;
            v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'devis_attendu', 'bloquant', false);
          end if;
        else
          v_statut_ligne := 'chiffree'; v_montant := v_quantite * lb.prix_eur;
        end if;
        if v_statut_ligne = 'chiffree' and v_plafond is null then
          v_statut_ligne := 'a_chiffrer';
          v_calcul := v_calcul || jsonb_build_object('motif', 'franchise_inconnue', 'montant_bareme', round(v_montant, 2));
          v_montant := 0;
        end if;
        v_rang := v_rang + 1;
        perform private.loc_poser_ligne(p_client, v_prop, v_rang, 'dommage', lb.famille, lb.code, coalesce(d ->> 'libelle', lb.libelle), lb.id, lb.unite,
          v_quantite, lb.prix_eur, v_montant, lb.regime_tva, private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), v_statut_ligne,
          v_calcul, v_preuves, false);
      end if;
      if jsonb_array_length(v_preuves) = 0 and lb.id is null then
        v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'preuve_absente', 'bloquant', true);
        v_bloque := true;
      end if;
    end loop;
    if v_plafond is null and exists (select 1 from public.loc_proposition_lignes l where l.proposition_id = v_prop and l.nature = 'dommage') then
      v_avert := v_avert || jsonb_build_object('poste', 'dommages', 'code', 'franchise_inconnue', 'bloquant', true,
        'detail', 'La franchise du contrat (ou son rachat) est inconnue : à compléter avant de chiffrer un dommage.');
      v_bloque := true;
    end if;
    if v_non_contra and exists (select 1 from public.loc_proposition_lignes l where l.proposition_id = v_prop and l.nature = 'dommage') then
      v_hors := true;
      v_avert := v_avert || jsonb_build_object('poste', 'dommages', 'code', 'etat_des_lieux_non_contradictoire', 'bloquant', false,
        'detail', 'Le client n''a pas signé le retour : les dommages vont à la direction, hors barème.');
    end if;

    -- 5. Les autres postes : nettoyage, clés, frais, ou un prix saisi par l'agence.
    for d in select * from jsonb_array_elements(coalesce(p_retour -> 'postes', '[]'::jsonb)) loop
      v_code := upper(btrim(d ->> 'code'));
      v_preuves := coalesce(d -> 'preuves', '[]'::jsonb);
      v_quantite := coalesce(nullif(d ->> 'quantite', '')::numeric, 1);
      lb := private.loc_ligne_bareme(v_bareme, v_code, c.categorie_id);
      v_statut_ligne := case when jsonb_array_length(v_preuves) = 0 then 'preuve_manquante' else 'chiffree' end;
      if v_statut_ligne = 'preuve_manquante' and (lb.id is not null or nullif(d ->> 'prix_eur', '') is not null) then
        v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'preuve_absente', 'bloquant', true);
        v_bloque := true;
      end if;
      if lb.id is null then
        if nullif(d ->> 'prix_eur', '') is not null then
          v_hors := true;
          v_rang := v_rang + 1;
          perform private.loc_poser_ligne(p_client, v_prop, v_rang, coalesce(nullif(d ->> 'nature', ''), 'frais'),
            case when d ->> 'nature' = 'dommage' then 'dommage' else 'autre' end, v_code, coalesce(d ->> 'libelle', v_code), null, 'forfait',
            v_quantite, (d ->> 'prix_eur')::numeric, v_quantite * (d ->> 'prix_eur')::numeric,
            coalesce(d ->> 'regime_tva', case when d ->> 'nature' = 'dommage' then 'hors_champ' else 'taxable' end),
            v_taux, v_statut_ligne, jsonb_build_object('hors_bareme', true, 'prix_agence', (d ->> 'prix_eur')::numeric), v_preuves, true);
        else
          v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'poste_absent_du_bareme', 'bloquant', false);
        end if;
        continue;
      end if;
      v_calcul := jsonb_build_object('ligne', lb.code, 'unite', lb.unite);
      if lb.unite = 'devis' and v_statut_ligne = 'chiffree' then
        if nullif(d ->> 'devis_eur', '') is not null then
          v_montant := (d ->> 'devis_eur')::numeric; v_calcul := v_calcul || '{"devis": true}'::jsonb;
        else
          v_statut_ligne := 'a_chiffrer'; v_montant := 0;
          v_avert := v_avert || jsonb_build_object('poste', v_code, 'code', 'devis_attendu', 'bloquant', false);
        end if;
      else
        v_montant := v_quantite * coalesce(lb.prix_eur, 0);
      end if;
      v_rang := v_rang + 1;
      perform private.loc_poser_ligne(p_client, v_prop, v_rang, lb.nature, lb.famille, lb.code, coalesce(d ->> 'libelle', lb.libelle), lb.id, lb.unite,
        v_quantite, lb.prix_eur, v_montant, lb.regime_tva, private.loc_taux_tva(p_client, c.entite_id, lb.taux_tva), v_statut_ligne,
        v_calcul, v_preuves, false);
    end loop;

    -- 6. Le plafond de franchise sur les dommages chiffrés, dans l'ordre des lignes.
    if v_plafond is not null then
      select coalesce(array_agg(l.montant_ttc order by l.rang), '{}'), coalesce(array_agg(l.id order by l.rang), '{}')
        into v_dommages, v_ids
      from public.loc_proposition_lignes l where l.proposition_id = v_prop and l.nature = 'dommage' and l.statut = 'chiffree';
      v_plafonnes := private.loc_appliquer_plafond(v_dommages, v_plafond);
      for v_i in 1 .. coalesce(array_length(v_ids, 1), 0) loop
        if v_plafonnes[v_i] <> v_dommages[v_i] then
          update public.loc_proposition_lignes l
             set montant_ttc = v_plafonnes[v_i],
                 montant_ht = case when l.regime_tva = 'taxable' and l.taux_tva > 0 then round(v_plafonnes[v_i] / (1 + l.taux_tva / 100), 2) else v_plafonnes[v_i] end,
                 montant_tva = v_plafonnes[v_i] - case when l.regime_tva = 'taxable' and l.taux_tva > 0 then round(v_plafonnes[v_i] / (1 + l.taux_tva / 100), 2) else v_plafonnes[v_i] end,
                 plafonnee = true,
                 calcul = l.calcul || jsonb_build_object('montant_bareme_ttc', v_dommages[v_i], 'plafond', v_plafond)
           where l.id = v_ids[v_i];
        end if;
      end loop;
    end if;
  end if;

  -- 7. Les totaux, le statut.
  select count(*), coalesce(sum(montant_ht), 0), coalesce(sum(montant_tva), 0), coalesce(sum(montant_ttc), 0)
    into v_nb_lignes, v_total_ht, v_total_tva, v_total_ttc
  from public.loc_proposition_lignes where proposition_id = v_prop;
  v_statut := case when v_nb_lignes = 0 and not v_bloque then 'rien_a_facturer'
                   when v_bloque then 'preuve_manquante'
                   else 'calculee' end;
  update public.loc_propositions p
     set statut = v_statut, hors_bareme = v_hors, avertissements = v_avert, plafond_eur = v_plafond,
         calcul_retard = r_retard, calcul_km = r_km, calcul_carburant = r_carb,
         total_ht = v_total_ht, total_tva = v_total_tva, total_ttc = v_total_ttc,
         total_frais_ttc = coalesce((select sum(l.montant_ttc) from public.loc_proposition_lignes l where l.proposition_id = v_prop and l.nature = 'frais'), 0),
         total_dommages_ttc = coalesce((select sum(l.montant_ttc) from public.loc_proposition_lignes l where l.proposition_id = v_prop and l.nature = 'dommage'), 0)
   where p.id = v_prop;

  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.proposition_calculee', 'loc_propositions', v_prop::text,
    jsonb_build_object('contrat', c.id, 'numero', c.numero, 'version', v_version, 'statut', v_statut, 'hors_bareme', v_hors,
                       'lignes', v_nb_lignes, 'total_ttc', v_total_ttc, 'source', p_source), c.entite_id);
  perform private.battre(p_client, 'tavaro_facturation', jsonb_build_object('proposition', v_prop, 'statut', v_statut), interval '1 day');
  return v_prop;
end $$;


--
-- Name: loc_chiffrer_retour_agence(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_chiffrer_retour_agence(p_contrat uuid, p_retour jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  c public.loc_contrats;
begin
  if v_uid is null then
    raise exception 'Un retour se chiffre par une personne connectée.' using errcode = '42501';
  end if;
  select * into c from public.loc_contrats where id = p_contrat;
  if not found or not exists (select 1 from public.comptes k where k.user_id = v_uid and k.client_id = c.client_id) then
    raise exception 'Contrat introuvable.' using errcode = 'P0002';
  end if;
  if not private.a_un_role(c.client_id, array['gerant', 'admin', 'valideur', 'collaborateur'])
     or not (private.voit_entite(c.client_id, c.entite_id)
             or (c.entite_retour_id is not null and private.voit_entite(c.client_id, c.entite_retour_id))) then
    raise exception 'Ce contrat n''est pas dans votre périmètre.' using errcode = '42501';
  end if;
  return private.loc_chiffrer_et_soumettre(c.client_id, c.id, p_retour, 'saisie', v_uid);
end $$;


--
-- Name: loc_cle_rapprochement(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_cle_rapprochement(p_client uuid, p_numero_permis text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_num text := upper(regexp_replace(coalesce(p_numero_permis, ''), '[^0-9A-Za-z]', '', 'g'));
  v_cle bytea;
begin
  if v_num = '' or p_client is null then
    return null;
  end if;
  select k.cle into v_cle from private.loc_cles k where k.client_id = p_client;
  if v_cle is null then
    insert into private.loc_cles (client_id, cle)
    values (p_client, sha256(convert_to(gen_random_uuid()::text || gen_random_uuid()::text || clock_timestamp()::text, 'UTF8')))
    on conflict (client_id) do nothing;
    select k.cle into v_cle from private.loc_cles k where k.client_id = p_client;
  end if;
  return encode(private.loc_hmac(v_cle, convert_to(v_num, 'UTF8')), 'hex');
end $$;


--
-- Name: loc_code(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_code(p_brut text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(upper(regexp_replace(btrim(coalesce(p_brut, '')), '\s+', ' ', 'g')), '')
$$;


--
-- Name: loc_completer_contrat(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_completer_contrat(p_contrat uuid, p_valeurs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  c public.loc_contrats;
  v_cle text;
  v_val jsonb;
  v_permis text[] := array['km_inclus', 'km_inclus_jour', 'km_illimite', 'politique_carburant', 'seuil_charge_pct',
                           'tarif_jour_eur', 'franchise_eur', 'franchise_reduite_eur', 'rachat_franchise',
                           'depot_eur', 'conditions_version'];
  v_saisies jsonb;
begin
  if v_uid is null then
    raise exception 'Un contrat se complète par une personne connectée.' using errcode = '42501';
  end if;
  select * into c from public.loc_contrats where id = p_contrat for update;
  if not found
     or not exists (select 1 from public.comptes k where k.user_id = v_uid and k.client_id = c.client_id) then
    raise exception 'Contrat introuvable.' using errcode = 'P0002';
  end if;
  if not private.a_un_role(c.client_id, array['gerant', 'admin', 'valideur', 'collaborateur'])
     or not (private.voit_entite(c.client_id, c.entite_id)
             or (c.entite_retour_id is not null and private.voit_entite(c.client_id, c.entite_retour_id))) then
    raise exception 'Ce contrat n''est pas dans votre périmètre.' using errcode = '42501';
  end if;
  if c.statut = 'annule' then
    raise exception 'Ce contrat est annulé.' using errcode = '23514';
  end if;
  if p_valeurs is null or jsonb_typeof(p_valeurs) <> 'object' or p_valeurs = '{}'::jsonb then
    raise exception 'Rien à compléter.' using errcode = '22023';
  end if;

  v_saisies := c.saisies;
  for v_cle, v_val in select * from jsonb_each(p_valeurs) loop
    if not (v_cle = any (v_permis)) then
      raise exception 'Seules les conditions du contrat se complètent ici (pas « % »).', v_cle using errcode = '22023';
    end if;
    begin
      case v_cle
        when 'km_inclus' then c.km_inclus := (v_val #>> '{}')::integer;
        when 'km_inclus_jour' then c.km_inclus_jour := (v_val #>> '{}')::integer;
        when 'km_illimite' then c.km_illimite := (v_val #>> '{}')::boolean;
        when 'politique_carburant' then c.politique_carburant := v_val #>> '{}';
        when 'seuil_charge_pct' then c.seuil_charge_pct := (v_val #>> '{}')::smallint;
        when 'tarif_jour_eur' then c.tarif_jour_eur := (v_val #>> '{}')::numeric;
        when 'franchise_eur' then c.franchise_eur := (v_val #>> '{}')::numeric;
        when 'franchise_reduite_eur' then c.franchise_reduite_eur := (v_val #>> '{}')::numeric;
        when 'rachat_franchise' then c.rachat_franchise := (v_val #>> '{}')::boolean;
        when 'depot_eur' then c.depot_eur := (v_val #>> '{}')::numeric;
        when 'conditions_version' then c.conditions_version := left(v_val #>> '{}', 80);
      end case;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'Valeur illisible pour « % ».', v_cle using errcode = '22023';
    end;
    v_saisies := v_saisies || jsonb_build_object(v_cle, jsonb_build_object('par', v_uid, 'le', now()));
  end loop;

  begin
    update public.loc_contrats
       set km_inclus = c.km_inclus, km_inclus_jour = c.km_inclus_jour, km_illimite = coalesce(c.km_illimite, false),
           politique_carburant = c.politique_carburant, seuil_charge_pct = c.seuil_charge_pct,
           tarif_jour_eur = c.tarif_jour_eur, franchise_eur = c.franchise_eur,
           franchise_reduite_eur = c.franchise_reduite_eur, rachat_franchise = c.rachat_franchise,
           depot_eur = c.depot_eur, conditions_version = c.conditions_version, saisies = v_saisies,
           -- une saisie tranche l'écart entre le PDF et le logiciel sur ce champ
           avertissements = coalesce((select jsonb_agg(a) from jsonb_array_elements(c.avertissements) a
                                      where not (a ->> 'code' = 'ecart_avec_le_logiciel' and p_valeurs ? (a ->> 'champ'))),
                                     '[]'::jsonb)
     where id = c.id;
  exception when check_violation then
    raise exception 'Condition refusée : %.', sqlerrm using errcode = '22023';
  end;

  return (select jsonb_build_object('contrat', x.id, 'km_inclus', x.km_inclus, 'km_inclus_jour', x.km_inclus_jour,
                                    'km_illimite', x.km_illimite, 'politique_carburant', x.politique_carburant,
                                    'seuil_charge_pct', x.seuil_charge_pct, 'tarif_jour_eur', x.tarif_jour_eur,
                                    'franchise_eur', x.franchise_eur, 'franchise_reduite_eur', x.franchise_reduite_eur,
                                    'rachat_franchise', x.rachat_franchise, 'depot_eur', x.depot_eur,
                                    'conditions_version', x.conditions_version)
          from public.loc_contrats x where x.id = c.id);
end $$;


--
-- Name: loc_confirmer_purge_pieces(uuid, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_confirmer_purge_pieces(p_client uuid, p_pieces uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dues uuid[];
  v_n integer;
  v_octets bigint;
begin
  if p_pieces is null or cardinality(p_pieces) = 0 then
    return jsonb_build_object('pieces', 0, 'octets', 0);
  end if;
  select coalesce(array_agg((e ->> 'piece')::uuid), '{}') into v_dues
  from jsonb_array_elements(private.loc_pieces_a_purger(p_client)) e;
  if exists (select 1 from unnest(p_pieces) x where not (x = any (v_dues))) then
    raise exception 'Une pièce demandée n''a pas fini sa durée de conservation.' using errcode = '22023';
  end if;
  if exists (select 1 from public.pieces p join storage.objects o on o.bucket_id = 'omega-clients' and o.name = p.chemin
             where p.client_id = p_client and p.id = any (p_pieces)) then
    raise exception 'Des fichiers sont encore au stockage : le serveur les efface d''abord.' using errcode = '55000';
  end if;
  select count(*), coalesce(sum(p.octets), 0) into v_n, v_octets
  from public.pieces p where p.client_id = p_client and p.id = any (p_pieces);
  delete from public.pieces p where p.client_id = p_client and p.id = any (p_pieces);
  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.pieces_purgees', 'pieces', null,
    jsonb_build_object('pieces', v_n, 'octets', v_octets,
                       'empreinte', encode(sha256(convert_to(array_to_string(
                         array(select x::text from unnest(p_pieces) x order by 1), ','), 'UTF8')), 'hex')));
  return jsonb_build_object('pieces', v_n, 'octets', v_octets);
end $$;


--
-- Name: loc_conservation_locataires(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_conservation_locataires(p_client uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  update public.loc_locataires l
     set conserver_jusqu_au = x.jusqu_au
    from (
      select l2.id,
             ((coalesce(greatest(
                 (select max(coalesce(c.retour_reel_le, c.retour_prevu_le)) from public.loc_contrats c
                  where c.client_id = l2.client_id and c.locataire_id = l2.id),
                 (select max(r.retour_prevu_le) from public.loc_reservations r
                  where r.client_id = l2.client_id and r.locataire_id = l2.id)), l2.cree_le) at time zone 'UTC')::date
              + make_interval(years => coalesce(g.duree_contrats_ans, 5)))::date as jusqu_au
      from public.loc_locataires l2
      left join public.loc_reglages g on g.client_id = l2.client_id
      where l2.anonymise_le is null and (p_client is null or l2.client_id = p_client)
    ) x
   where l.id = x.id and l.conserver_jusqu_au is distinct from x.jusqu_au;
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: loc_decision_avoir(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_decision_avoir(p_charge jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  a public.loc_avoirs;
  v_demande uuid := (p_charge ->> 'demande')::uuid;
  v_statut text := p_charge ->> 'statut';
  v_erreur text;
  v_ref text;
  v_envoi jsonb;
begin
  if p_charge ->> 'objet_type' <> 'loc_avoirs' or p_charge ->> 'objet_id' is null then
    return jsonb_build_object('statut', 'ignoree');
  end if;
  select * into a from public.loc_avoirs where id = (p_charge ->> 'objet_id')::uuid for update;
  if not found then
    return jsonb_build_object('statut', 'avoir_introuvable');
  end if;
  if a.demande_id is distinct from v_demande then
    return jsonb_build_object('statut', 'demande_depassee', 'avoir', a.id);
  end if;
  if a.statut <> 'a_valider' then
    return jsonb_build_object('statut', 'deja_traite', 'avoir', a.id);
  end if;

  if v_statut = 'approuvee' then
    begin
      perform private.loc_emettre_avoir(a.client_id, a.id);
    exception when others then
      v_erreur := left(sqlstate || ' ' || sqlerrm, 500);
      update public.demandes_validation set statut = 'echec_execution', motif_echec = v_erreur where id = v_demande and statut = 'approuvee';
      perform private.lever_alerte_module(a.client_id, 'tavaro', 'critique',
        format('L''avoir de %s € sur la facture %s n''a pas pu être émis.', replace(a.montant_ttc::text, '.', ','), a.facture_reference),
        jsonb_build_object('avoir', a.id, 'demande', v_demande, 'erreur', v_erreur), 'avoir:echec:' || a.id::text, false, null);
      return jsonb_build_object('statut', 'a_valider', 'emission', 'echec', 'erreur', v_erreur, 'avoir', a.id);
    end;
    select x.reference into v_ref from public.loc_avoirs x where x.id = a.id;
    -- Le courriel, adossé à la même décision : c'est son départ qui l'exécute.
    v_envoi := private.loc_envoyer_avoir(a.client_id, a.id);
    if v_envoi ->> 'statut' in ('rien', 'non_regle', 'sans_adresse') then
      update public.demandes_validation set statut = 'executee', motif_echec = null
       where id = v_demande and statut in ('approuvee', 'echec_execution');
    end if;
    return jsonb_build_object('statut', 'emis', 'avoir', a.id, 'reference', v_ref, 'envoi', v_envoi);
  elsif v_statut = 'rejetee' then
    update public.loc_avoirs set statut = 'refuse' where id = a.id;
    perform private.lever_alerte_module(a.client_id, 'tavaro', 'attention',
      format('La direction a refusé l''avoir de %s € sur la facture %s (contrat %s).', replace(a.montant_ttc::text, '.', ','), a.facture_reference, a.contrat_numero),
      jsonb_build_object('avoir', a.id, 'demande', v_demande, 'decideurs', p_charge -> 'decideurs'), 'avoir:refuse:' || a.id::text, true, null);
    perform private.journaliser_module(a.client_id, 'tavaro', 'tavaro.avoir_refuse', 'loc_avoirs', a.id::text,
      jsonb_build_object('demande', v_demande, 'decideurs', p_charge -> 'decideurs', 'montant_ttc', a.montant_ttc), a.entite_id);
    return jsonb_build_object('statut', 'refuse', 'avoir', a.id);
  elsif v_statut in ('expiree', 'annulee') then
    update public.loc_avoirs set statut = case v_statut when 'expiree' then 'expire' else 'annule' end where id = a.id;
    if v_statut = 'expiree' then
      perform private.lever_alerte_module(a.client_id, 'tavaro', 'attention',
        format('L''avoir de %s € sur la facture %s n''a pas été décidé en 48 heures : redemandez-le s''il reste dû.',
               replace(a.montant_ttc::text, '.', ','), a.facture_reference),
        jsonb_build_object('avoir', a.id, 'demande', v_demande), 'avoir:expire:' || a.id::text, true, null);
    end if;
    perform private.journaliser_module(a.client_id, 'tavaro', 'tavaro.avoir_' || case v_statut when 'expiree' then 'expire' else 'annule' end,
      'loc_avoirs', a.id::text, jsonb_build_object('demande', v_demande, 'montant_ttc', a.montant_ttc), a.entite_id);
    return jsonb_build_object('statut', case v_statut when 'expiree' then 'expire' else 'annule' end, 'avoir', a.id);
  end if;
  return jsonb_build_object('statut', 'ignoree');
end $$;


--
-- Name: loc_demander_avoir(uuid, text, numeric, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_demander_avoir(p_facture uuid, p_motif text, p_montant_ttc numeric DEFAULT NULL::numeric, p_maintenant timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  f public.loc_factures := private.loc_facture_de_l_agence(p_facture);
  v_uid uuid := (select auth.uid());
  v_motif text := left(btrim(p_motif), 500);
  v_deja numeric;
  v_reste numeric;
  v_ttc numeric;
  v_ht numeric;
  v_tva numeric;
  v_total boolean;
  v_lignes jsonb;
  v_avoir uuid;
  v_demande uuid;
  v_resume text;
begin
  if f.statut = 'avoir' then
    raise exception 'Cette facture est déjà annulée par un avoir.' using errcode = '23514';
  end if;
  if exists (select 1 from public.loc_avoirs a where a.client_id = f.client_id and a.facture_id = f.id and a.statut = 'a_valider') then
    raise exception 'Un avoir attend déjà la décision de la direction sur cette facture.' using errcode = '55000';
  end if;
  if v_motif is null or char_length(v_motif) < 3 then
    raise exception 'Un avoir a un motif : ce que la facture avait de faux.' using errcode = '22023';
  end if;
  select coalesce(sum(a.montant_ttc), 0) into v_deja from public.loc_avoirs a where a.client_id = f.client_id and a.facture_id = f.id and a.statut = 'emis';
  v_reste := f.total_ttc - v_deja;
  if v_reste <= 0 then
    raise exception 'Cette facture est déjà entièrement créditée.' using errcode = '23514';
  end if;
  v_ttc := coalesce(p_montant_ttc, v_reste);
  if v_ttc <= 0 or v_ttc > v_reste or v_ttc <> round(v_ttc, 2) then
    raise exception 'Le montant d''un avoir est entre 0,01 et %s € (ce qui reste de la facture), au centime.', replace(v_reste::text, '.', ',')
      using errcode = '22023';
  end if;
  v_total := v_ttc = f.total_ttc;
  if v_total then
    v_ht := f.total_ht;
    v_tva := f.total_tva;
    select coalesce(jsonb_agg(jsonb_build_object('rang', l.rang, 'code', l.code, 'libelle', l.libelle, 'quantite', l.quantite, 'prix_unitaire', l.prix_unitaire,
                                                 'montant_ht', l.montant_ht, 'regime_tva', l.regime_tva, 'taux_tva', l.taux_tva, 'montant_tva', l.montant_tva,
                                                 'montant_ttc', l.montant_ttc) order by l.rang), '[]'::jsonb)
      into v_lignes
    from public.loc_facture_lignes l where l.client_id = f.client_id and l.facture_id = f.id;
  else
    -- Au prorata de la facture : la même part de TVA que la facture entière.
    v_ht := round(v_ttc * f.total_ht / f.total_ttc, 2);
    v_tva := v_ttc - v_ht;
    v_lignes := jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'rang', 1, 'code', 'AVOIR_PARTIEL', 'libelle', format('Avoir partiel sur la facture %s', f.reference), 'quantite', 1, 'prix_unitaire', v_ht,
      'montant_ht', v_ht, 'regime_tva', case when f.total_tva > 0 then 'taxable' else 'hors_champ' end,
      'taux_tva', case when f.total_tva > 0 and f.total_ht > 0 then round(f.total_tva / f.total_ht * 100, 2) end,
      'montant_tva', v_tva, 'montant_ttc', v_ttc)));
  end if;

  insert into public.loc_avoirs (client_id, entite_id, entite_emettrice_id, facture_id, facture_reference, contrat_id, contrat_numero, motif, total,
                                 montant_ht, montant_tva, montant_ttc, lignes, demande_par)
  values (f.client_id, f.entite_id, f.entite_emettrice_id, f.id, f.reference, f.contrat_id, f.contrat_numero, v_motif, v_total,
          v_ht, v_tva, v_ttc, v_lignes, v_uid)
  returning id into v_avoir;

  perform private.loc_regles_par_defaut(f.client_id);
  -- Le résumé entre au journal opposable : le montant et la facture, jamais le motif (un texte libre).
  v_resume := format('Avoir de %s € TTC sur la facture %s (contrat %s), %s', replace(v_ttc::text, '.', ','), f.reference, f.contrat_numero,
                     case when v_total then 'annulation complète' else 'partiel' end);
  insert into public.demandes_validation (client_id, entite_id, module, type_action, objet_type, objet_id, resume, montant, payload, echeance, cle_idempotence)
  values (f.client_id, f.entite_id, 'tavaro', 'avoir.emettre', 'loc_avoirs', v_avoir::text, left(v_resume, 500), v_ttc,
          jsonb_build_object('avoir', v_avoir, 'facture', f.id, 'reference', f.reference, 'contrat', f.contrat_numero, 'montant_ttc', v_ttc,
                             'total', v_total, 'motif', v_motif, 'facture_ttc', f.total_ttc, 'deja_credite', v_deja, 'lignes', v_lignes),
          p_maintenant + interval '48 hours', 'tavaro:avoir:' || v_avoir::text)
  returning id into v_demande;
  update public.loc_avoirs set demande_id = v_demande where id = v_avoir;
  perform private.journaliser_module(f.client_id, 'tavaro', 'tavaro.avoir_demande', 'loc_avoirs', v_avoir::text,
    jsonb_build_object('facture', f.id, 'reference', f.reference, 'montant_ttc', v_ttc, 'total', v_total, 'demande', v_demande, 'contrat', f.contrat_numero),
    f.entite_id);
  return v_avoir;
end $$;


--
-- Name: loc_deposer_demande(uuid, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_deposer_demande(p_client uuid, p_proposition uuid, p_tentative integer DEFAULT 1, p_maintenant timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.loc_propositions;
  c public.loc_contrats;
  v_fuseau text;
  v_type text;
  v_resume text;
  v_demande uuid;
  v_nb integer;
  v_echeance timestamptz;
begin
  select * into p from public.loc_propositions where client_id = p_client and id = p_proposition for update;
  if not found then
    raise exception 'Proposition introuvable.' using errcode = 'P0002';
  end if;
  if p.statut = 'a_valider' and exists (select 1 from public.demandes_validation d where d.id = p.demande_id and d.statut = 'en_attente') then
    return p.demande_id;
  end if;
  if p.statut not in ('calculee', 'a_valider') then
    return null;
  end if;
  select * into c from public.loc_contrats where client_id = p_client and id = p.contrat_id;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = p.entite_id;
  perform private.loc_regles_par_defaut(p_client);
  v_type := case when p.hors_bareme then 'facture.envoyer_hors_bareme' else 'facture.envoyer' end;
  select count(*) into v_nb from public.loc_proposition_lignes l where l.proposition_id = p.id;
  v_resume := format('Facturer le retour du contrat %s : %s € TTC (frais %s, dommages %s)%s', c.numero,
                     replace(p.total_ttc::text, '.', ','), replace(p.total_frais_ttc::text, '.', ','), replace(p.total_dommages_ttc::text, '.', ','),
                     case when p.hors_bareme then ' — hors barème' else '' end);
  v_echeance := private.loc_echeance_locale(v_fuseau, p_maintenant);
  insert into public.demandes_validation (client_id, entite_id, module, type_action, objet_type, objet_id, resume, montant, payload,
                                          echeance, cle_idempotence)
  values (p_client, p.entite_id, 'tavaro', v_type, 'loc_propositions', p.id::text, left(v_resume, 500), p.total_ttc,
          jsonb_build_object('proposition', p.id, 'contrat', c.id, 'numero', c.numero, 'version', p.version, 'tentative', p_tentative,
                             'total_ttc', p.total_ttc, 'total_frais_ttc', p.total_frais_ttc, 'total_dommages_ttc', p.total_dommages_ttc,
                             'lignes', v_nb, 'hors_bareme', p.hors_bareme, 'non_contradictoire', p.non_contradictoire,
                             'avertissements', p.avertissements),
          v_echeance, 'tavaro:proposition:' || p.id::text || ':t' || p_tentative)
  returning id into v_demande;
  update public.loc_propositions set statut = 'a_valider', demande_id = v_demande where id = p.id;
  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.demande_deposee', 'loc_propositions', p.id::text,
    jsonb_build_object('demande', v_demande, 'type_action', v_type, 'montant', p.total_ttc, 'tentative', p_tentative, 'echeance', v_echeance),
    p.entite_id);
  return v_demande;
end $$;


--
-- Name: loc_deposer_points(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_deposer_points(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_jour date;
  v_items jsonb;
  v_n integer;
  v_montant numeric;
  n integer := 0;
begin
  -- Chaque agence, pour ses valideurs : le chef d'agence.
  for r in
    select a.client_id, a.entite_id, e.fuseau
    from public.loc_agences a
    join public.entites e on e.client_id = a.client_id and e.id = a.entite_id
    where exists (select 1 from public.loc_reglages g where g.client_id = a.client_id)
    order by a.client_id, a.entite_id
  loop
    begin
      v_jour := (p_maintenant at time zone coalesce(r.fuseau, 'UTC'))::date;
      v_items := private.loc_section_facturation(r.client_id, r.entite_id, v_jour);
      perform private.deposer_section(r.client_id, 'tavaro', v_jour, null, 'valideur', 'Facturation des retours', v_items,
                                      r.entite_id, null, false, null, false, 20);
      n := n + 1;
    exception when others then
      perform private.lever_alerte_module(r.client_id, 'tavaro', 'attention',
        'La section « Facturation des retours » du point du matin n''a pas pu être déposée pour une agence.',
        jsonb_build_object('entite', r.entite_id, 'erreur', left(sqlstate || ' ' || sqlerrm, 300)), 'point:depot:' || r.entite_id::text, false, null);
    end;
  end loop;
  -- La direction : le réseau, agence par agence, et les avoirs qui attendent sa décision.
  for r in
    select k.id as client_id, e.fuseau
    from public.clients k
    join public.entites e on e.client_id = k.id and e.principale
    where exists (select 1 from public.loc_reglages g where g.client_id = k.id)
  loop
    begin
      v_jour := (p_maintenant at time zone coalesce(r.fuseau, 'UTC'))::date;
      perform private.deposer_section(r.client_id, 'tavaro', v_jour, null, 'gerant', 'Facturation des retours, réseau',
                                      private.loc_section_reseau(r.client_id, v_jour), null, null, false, null, false, 20);
      select count(*), coalesce(sum(a.montant_ttc), 0) into v_n, v_montant
      from public.loc_avoirs a where a.client_id = r.client_id and a.statut = 'a_valider';
      v_items := case when v_n > 0
                      then jsonb_build_array(jsonb_build_object('gabarit', 'tavaro.avoirs_a_decider', 'valeurs', jsonb_build_object('n', v_n, 'montant', v_montant),
                                                               'lien', '/tavaro/avoirs', 'gravite', 'attention'))
                      else '[]'::jsonb end;
      perform private.deposer_section(r.client_id, 'tavaro', v_jour, null, 'gerant', 'Avoirs à décider', v_items, null, null, false, null, false, 25);
      perform private.battre(r.client_id, 'tavaro_matin', jsonb_build_object('jour', v_jour, 'avoirs', v_n), interval '1 day');
      n := n + 1;
    exception when others then
      perform private.lever_alerte_module(r.client_id, 'tavaro', 'attention',
        'Les sections de la direction du point du matin n''ont pas pu être déposées.',
        jsonb_build_object('erreur', left(sqlstate || ' ' || sqlerrm, 300)), 'point:depot:direction', false, null);
    end;
  end loop;
  return n;
end $$;


--
-- Name: loc_echeance_locale(text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_echeance_locale(p_fuseau text, p_maintenant timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_local timestamp;
begin
  if p_fuseau is null then
    raise exception 'Fuseau de l''agence manquant.' using errcode = '22023';
  end if;
  v_local := p_maintenant at time zone p_fuseau;
  if v_local::time >= time '22:00' then
    return (v_local::date + 1 + time '23:59:59') at time zone p_fuseau;
  end if;
  return (v_local::date + time '23:59:59') at time zone p_fuseau;
end $$;


--
-- Name: loc_emettre_avoir(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_emettre_avoir(p_client uuid, p_avoir uuid, p_maintenant timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  a public.loc_avoirs;
  f public.loc_factures;
  d public.demandes_validation;
  v_fuseau text;
  v_annee integer;
  v_numero integer;
  v_ref text;
  v_credite numeric;
begin
  select * into a from public.loc_avoirs where client_id = p_client and id = p_avoir for update;
  if not found then
    raise exception 'Avoir introuvable.' using errcode = 'P0002';
  end if;
  if a.statut <> 'a_valider' then
    raise exception 'Seul un avoir en attente s''émet (statut : %).', a.statut using errcode = '23514';
  end if;
  select * into d from public.demandes_validation where id = a.demande_id;
  if not found or d.statut not in ('approuvee', 'echec_execution') then
    raise exception 'Aucun avoir sans demande approuvée par la direction.' using errcode = '23514';
  end if;
  select * into f from public.loc_factures where client_id = p_client and id = a.facture_id for update;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = a.entite_id;
  v_annee := extract(year from (p_maintenant at time zone v_fuseau))::integer;
  v_numero := private.loc_numero_serie(p_client, a.entite_emettrice_id, 'AV', v_annee);
  v_ref := format('AV-%s-%s', v_annee, lpad(v_numero::text, 6, '0'));
  update public.loc_avoirs
     set statut = 'emis', annee = v_annee, numero = v_numero, reference = v_ref, emis_le = p_maintenant,
         date_avoir = (p_maintenant at time zone v_fuseau)::date, emetteur = f.emetteur, destinataire = f.destinataire,
         mentions = jsonb_strip_nulls(jsonb_build_object(
           'mandat', f.mentions ->> 'mandat',
           'objet', format('Avoir %s la facture %s du %s', case when a.total then 'annulant' else 'partiel sur' end, f.reference, to_char(f.date_facture, 'DD/MM/YYYY')),
           'motif', a.motif, 'contrat', f.contrat_numero,
           'nature_operations', f.mentions ->> 'nature_operations',
           'tva', f.mentions ->> 'tva',
           'option_debits', f.mentions ->> 'option_debits',
           'mentions_manquantes', f.mentions -> 'mentions_manquantes'))
   where id = a.id;
  -- La facture est annulée quand ses avoirs la couvrent ; une facture réglée garde son règlement (l'avoir vaut remboursement).
  select coalesce(sum(x.montant_ttc), 0) into v_credite from public.loc_avoirs x where x.client_id = p_client and x.facture_id = f.id and x.statut = 'emis';
  if v_credite >= f.total_ttc and f.statut in ('emise', 'envoyee', 'litige') then
    update public.loc_factures set statut = 'avoir' where id = f.id;
  end if;
  -- La demande n'est pas close ici : c'est le départ du courriel qui l'exécute.
  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.avoir_emis', 'loc_avoirs', a.id::text,
    jsonb_build_object('reference', v_ref, 'montant_ttc', a.montant_ttc, 'total', a.total, 'facture', f.id, 'facture_reference', f.reference,
                       'facture_statut', case when v_credite >= f.total_ttc then 'creditee' else 'partiellement_creditee' end,
                       'demande', a.demande_id, 'contrat', f.contrat_numero), a.entite_id);
  perform private.battre(p_client, 'tavaro_facturation', jsonb_build_object('avoir', a.id, 'facture', f.id), interval '1 day');
  return a.id;
end $$;


--
-- Name: loc_emettre_factures(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_emettre_factures(p_client uuid, p_proposition uuid, p_maintenant timestamp with time zone DEFAULT now()) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.loc_propositions;
  c public.loc_contrats;
  l public.loc_locataires;
  d public.demandes_validation;
  v_fuseau text;
  v_societe uuid;
  v_nom text;
  v_siren text;
  v_reglages public.loc_reglages;
  v_emetteur jsonb;
  v_destinataire jsonb;
  v_manquantes text[] := '{}';
  v_pro boolean;
  v_retour timestamptz;
  v_annee integer;
  v_date date;
  v_nature text;
  v_numero integer;
  v_ref text;
  v_facture uuid;
  v_factures uuid[] := '{}';
  v_ht numeric;
  v_tva numeric;
  v_ttc numeric;
  v_taxable boolean;
  v_rang integer;
  li record;
begin
  select * into p from public.loc_propositions where client_id = p_client and id = p_proposition for update;
  if not found then
    raise exception 'Proposition introuvable.' using errcode = 'P0002';
  end if;
  if p.statut <> 'validee' then
    raise exception 'Seule une proposition validée se facture (statut : %).', p.statut using errcode = '23514';
  end if;
  select * into d from public.demandes_validation where id = p.demande_id;
  if not found or d.statut not in ('approuvee', 'echec_execution') then
    raise exception 'Aucune facture sans demande approuvée.' using errcode = '23514';
  end if;
  select * into c from public.loc_contrats where client_id = p_client and id = p.contrat_id;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = p.entite_id;
  select e.id, e.siren into v_societe, v_siren from public.entites e where e.client_id = p_client and e.principale;
  select k.nom, coalesce(v_siren, k.siren) into v_nom, v_siren from public.clients k where k.id = p_client;
  select * into v_reglages from public.loc_reglages g where g.client_id = p_client;
  if c.locataire_id is not null then
    select * into l from public.loc_locataires x where x.client_id = p_client and x.id = c.locataire_id;
  end if;
  -- La restitution : ce que le retour chiffré a donné, sinon le contrat.
  v_retour := coalesce((p.entrees ->> 'retour_reel_le')::timestamptz, c.retour_reel_le);

  -- L'émetteur : l'organisation, sa société principale, ses réglages.
  v_emetteur := jsonb_strip_nulls(jsonb_build_object('nom', v_nom, 'siren', v_siren)
                || coalesce(v_reglages.emetteur, '{}'::jsonb));
  if v_siren is null then v_manquantes := array_append(v_manquantes, 'siren_emetteur'); end if;
  if v_emetteur ->> 'adresse' is null then v_manquantes := array_append(v_manquantes, 'adresse_emetteur'); end if;

  -- Le destinataire : le locataire du contrat, tel qu'il est connu.
  v_pro := l.id is not null and l.type = 'professionnel';
  if l.id is null or l.anonymise_le is not null then
    v_destinataire := jsonb_build_object('type', 'inconnu');
    v_manquantes := array_append(v_manquantes, 'client');
  else
    v_destinataire := jsonb_strip_nulls(jsonb_build_object(
      'type', l.type, 'nom', nullif(btrim(concat_ws(' ', l.prenom, l.nom)), ''), 'raison_sociale', l.raison_sociale,
      'siren', l.siren, 'adresse', l.adresse, 'email', l.email));
    if v_pro and l.siren is null then v_manquantes := array_append(v_manquantes, 'siren_client'); end if;
    if l.adresse is null then v_manquantes := array_append(v_manquantes, 'adresse_client'); end if;
    if v_pro and l.raison_sociale is null then v_manquantes := array_append(v_manquantes, 'raison_sociale_client'); end if;
    if not v_pro and l.nom is null then v_manquantes := array_append(v_manquantes, 'nom_client'); end if;
  end if;

  v_annee := extract(year from (p_maintenant at time zone v_fuseau))::integer;
  v_date := (p_maintenant at time zone v_fuseau)::date;

  for v_nature in select x from unnest(array['frais', 'dommages']) x loop
    select coalesce(sum(montant_ht), 0), coalesce(sum(montant_tva), 0), coalesce(sum(montant_ttc), 0),
           bool_or(regime_tva = 'taxable')
      into v_ht, v_tva, v_ttc, v_taxable
    from public.loc_proposition_lignes pl
    where pl.proposition_id = p.id and pl.statut = 'chiffree' and pl.montant_ttc > 0
      and pl.nature = case v_nature when 'frais' then 'frais' else 'dommage' end;
    continue when v_ttc <= 0;

    v_numero := private.loc_numero_facture(p_client, v_societe, v_annee);
    v_ref := format('FA-%s-%s', v_annee, lpad(v_numero::text, 6, '0'));
    insert into public.loc_factures (client_id, entite_id, entite_emettrice_id, contrat_id, contrat_numero, proposition_id, demande_id, nature,
                                     annee, numero, reference, emise_le, date_facture, echeance_le, a_debiter_avant,
                                     total_ht, total_tva, total_ttc, emetteur, destinataire, mentions)
    values (p_client, p.entite_id, v_societe, c.id, c.numero, p.id, p.demande_id, v_nature,
            v_annee, v_numero, v_ref, p_maintenant, v_date,
            v_date + case when v_pro then coalesce(v_reglages.echeance_pro_jours, 30) else 0 end,
            case when v_retour is not null then (v_retour at time zone v_fuseau)::date + 10 end,
            v_ht, v_tva, v_ttc, v_emetteur, v_destinataire,
            jsonb_strip_nulls(jsonb_build_object(
              'mandat', format('Facture établie par Omega au nom et pour le compte de %s.', v_nom),
              'objet', case v_nature when 'frais' then 'Frais complémentaires de location' else 'Dommages constatés à la restitution' end,
              'contrat', c.numero,
              'nature_operations', case when v_taxable then 'prestations_de_services' else 'hors_champ' end,
              'option_debits', case when v_taxable and coalesce(v_reglages.tva_sur_debits, false)
                                    then 'Option pour le paiement de la taxe d''après les débits' end,
              'restitution', case when v_retour is not null then to_char(v_retour at time zone v_fuseau, 'DD/MM/YYYY à HH24:MI') end,
              'tva', case when v_taxable then null else 'Indemnité hors du champ de la TVA (BOI-TVA-BASE-10-10-50, § 300).' end,
              'penalites', case when v_pro then 'En cas de retard de paiement : pénalités au taux de la BCE majoré de 10 points, et indemnité forfaitaire de recouvrement de 40 € (C. com. L441-10).' end,
              'debit', case when v_retour is not null then format('À débiter avant le %s en cas de débit sur la carte enregistrée [à vérifier : délai Visa].',
                                                                  to_char((v_retour at time zone v_fuseau)::date + 10, 'DD/MM/YYYY')) end,
              'mentions_manquantes', case when cardinality(v_manquantes) > 0 then to_jsonb(v_manquantes) end)))
    returning id into v_facture;

    v_rang := 0;
    for li in select * from public.loc_proposition_lignes pl
              where pl.proposition_id = p.id and pl.statut = 'chiffree' and pl.montant_ttc > 0
                and pl.nature = case v_nature when 'frais' then 'frais' else 'dommage' end
              order by pl.rang loop
      v_rang := v_rang + 1;
      insert into public.loc_facture_lignes (client_id, facture_id, rang, code, libelle, famille, unite, quantite, prix_unitaire, montant_ht,
                                             regime_tva, taux_tva, montant_tva, montant_ttc, bareme_ligne_id, proposition_ligne_id, preuves)
      values (p_client, v_facture, v_rang, li.code, li.libelle, li.famille, li.unite, li.quantite, li.prix_unitaire, li.montant_ht,
              li.regime_tva, li.taux_tva, li.montant_tva, li.montant_ttc, li.bareme_ligne_id, li.id, li.preuves);
    end loop;

    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.facture_emise', 'loc_factures', v_facture::text,
      jsonb_build_object('reference', v_ref, 'nature', v_nature, 'total_ttc', v_ttc, 'lignes', v_rang, 'contrat', c.id, 'numero_contrat', c.numero,
                         'proposition', p.id, 'demande', p.demande_id, 'mentions_manquantes', to_jsonb(v_manquantes)), p.entite_id);
    v_factures := array_append(v_factures, v_facture);
  end loop;

  update public.loc_propositions set statut = 'facturee' where id = p.id;
  -- La demande n'est pas close ici : c'est le départ du courriel (lot 1 e) qui l'exécute.
  if cardinality(v_manquantes) > 0 and cardinality(v_factures) > 0 then
    perform private.lever_alerte_module(p_client, 'tavaro', 'attention',
      format('Facture %s émise avec des mentions manquantes : %s. Complétez la fiche du loueur ou du client.',
             (select f.reference from public.loc_factures f where f.id = v_factures[1]), array_to_string(v_manquantes, ', ')),
      jsonb_build_object('factures', to_jsonb(v_factures), 'manquantes', to_jsonb(v_manquantes), 'contrat', c.numero),
      'facture:mentions_manquantes:' || p.id::text, true, null);
  end if;
  perform private.battre(p_client, 'tavaro_facturation', jsonb_build_object('proposition', p.id, 'factures', cardinality(v_factures)), interval '1 day');
  return v_factures;
end $$;


--
-- Name: loc_energie(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_energie(p_brute text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when c = '' then null
    when c in ('ES', 'ESSENCE', 'SP95', 'SP98', 'E10', 'SANSPLOMB', 'SUPER', 'PETROL', 'GASOLINE') then 'essence'
    when c in ('GO', 'GAZOLE', 'DIESEL', 'GASOIL') then 'diesel'
    when c in ('EL', 'ELECTRIQUE', 'ELECTRICITE', 'ELECTRIC', 'EV', 'BEV', '100ELECTRIQUE') then 'electrique'
    when c in ('EH', 'GH', 'HYBRIDE', 'HYBRID', 'HEV', 'MHEV', 'FULLHYBRID', 'MILDHYBRID',
               'HYBRIDENONRECHARGEABLE', 'HYBRIDEESSENCE', 'HYBRIDEDIESEL') then 'hybride'
    when c in ('EE', 'GL', 'PHEV', 'HYBRIDERECHARGEABLE', 'PLUGIN', 'PLUGINHYBRID', 'HYBRIDEPLUGIN') then 'hybride_rechargeable'
    when c in ('GP', 'EG', 'GPL', 'LPG') then 'gpl'
    when c in ('GN', 'EN', 'GNV', 'CNG', 'GAZNATUREL') then 'gnv'
    when c in ('FE', 'E85', 'SUPERETHANOL', 'FLEXFUEL', 'ETHANOL') then 'superethanol'
    when c in ('H2', 'HYDROGENE', 'HYDROGEN') then 'hydrogene'
    else 'autre'
  end
  from (select upper(regexp_replace(
                 translate(coalesce(p_brute, ''),
                           'àâäáãéèêëíìîïóòôöõúùûüçÀÂÄÁÃÉÈÊËÍÌÎÏÓÒÔÖÕÚÙÛÜÇ',
                           'aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'),
                 '[^0-9A-Za-z]', '', 'g')) as c) x
$$;


--
-- Name: loc_envoi_issue(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_envoi_issue(p_charge jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.loc_propositions;
  a public.loc_avoirs;
  e public.envois;
  v_type text := p_charge ->> 'objet_type';
  v_issue text := split_part(coalesce(p_charge ->> 'evenement', ''), '.', 2);
  v_n integer;
  v_refs text;
  v_quoi text;
  v_numero text;
  v_client uuid;
  v_entite uuid;
  v_objet uuid;
begin
  if v_type not in ('loc_propositions', 'loc_avoirs') or p_charge ->> 'envoi' is null
     or v_issue not in ('envoye', 'bloque', 'refuse', 'annule', 'expire', 'echec', 'non_remis') then
    return jsonb_build_object('statut', 'ignoree');
  end if;
  select * into e from public.envois where id = (p_charge ->> 'envoi')::uuid;
  if e.id is null then
    return jsonb_build_object('statut', 'introuvable');
  end if;

  if v_type = 'loc_avoirs' then
    select * into a from public.loc_avoirs where id = (p_charge ->> 'objet_id')::uuid;
    if a.id is null or a.client_id <> e.client_id then
      return jsonb_build_object('statut', 'introuvable');
    end if;
    v_client := a.client_id; v_entite := a.entite_id; v_objet := a.id;
    v_quoi := 'de l''avoir ' || coalesce(a.reference, '?');
    v_numero := a.contrat_numero;
    if v_issue = 'envoye' then
      update public.loc_avoirs set envoye_le = coalesce(envoye_le, now()) where id = a.id and envoi_id = e.id;
      perform private.journaliser_module(v_client, 'tavaro', 'tavaro.avoir_envoye', 'loc_avoirs', a.id::text,
        jsonb_build_object('envoi', e.id, 'reference', a.reference, 'mode', e.mode, 'contrat', v_numero), v_entite);
      return jsonb_build_object('statut', 'envoyee', 'avoir', a.id);
    end if;
  else
    select * into p from public.loc_propositions where id = (p_charge ->> 'objet_id')::uuid;
    if p.id is null or e.client_id <> p.client_id then
      return jsonb_build_object('statut', 'introuvable');
    end if;
    v_client := p.client_id; v_entite := p.entite_id; v_objet := p.id;
    select count(*)::int, string_agg(x.reference, ' et ' order by x.numero) into v_n, v_refs
    from public.loc_factures x where x.client_id = p.client_id and x.envoi_id = e.id;
    v_quoi := case when v_n > 1 then 'des factures ' else 'de la facture ' end || coalesce(v_refs, '?');
    select x.numero into v_numero from public.loc_contrats x where x.id = p.contrat_id;
    if v_issue = 'envoye' then
      update public.loc_factures set statut = 'envoyee' where client_id = p.client_id and envoi_id = e.id and statut = 'emise';
      perform private.journaliser_module(v_client, 'tavaro', 'tavaro.facture_envoyee', 'loc_propositions', p.id::text,
        jsonb_build_object('envoi', e.id, 'factures', v_refs, 'mode', e.mode, 'contrat', v_numero), v_entite);
      return jsonb_build_object('statut', 'envoyee', 'factures', v_n);
    end if;
  end if;

  perform private.lever_alerte_module(v_client, 'tavaro', case when v_issue = 'echec' then 'critique' else 'attention' end,
    case when v_issue = 'non_remis'
      then format('Le courriel %s (contrat %s) n''a pas été remis%s. Envoyez-le autrement.', v_quoi, coalesce(v_numero, '?'),
                  coalesce(' (' || e.motif || ')', ''))
      else format('Le courriel %s (contrat %s) n''est pas parti%s. Envoyez-le vous-même.', v_quoi, coalesce(v_numero, '?'),
                  coalesce(' (' || e.motif || ')', '')) end,
    jsonb_build_object('objet_type', v_type, 'objet', v_objet, 'envoi', e.id, 'issue', v_issue, 'verrou', e.verrou, 'motif', e.motif),
    case when v_type = 'loc_avoirs' then 'avoir:envoi_' else 'facture:envoi_' end || v_issue || ':' || v_objet::text, true, null);
  perform private.journaliser_module(v_client, 'tavaro', case when v_type = 'loc_avoirs' then 'tavaro.avoir_envoi_' else 'tavaro.facture_envoi_' end || v_issue,
    v_type, v_objet::text, jsonb_build_object('envoi', e.id, 'verrou', e.verrou, 'contrat', v_numero), v_entite);
  return jsonb_build_object('statut', v_issue);
end $$;


--
-- Name: loc_envoyer_avoir(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_envoyer_avoir(p_client uuid, p_avoir uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  a public.loc_avoirs;
  f public.loc_factures;
  l public.loc_locataires;
  v_nom_loueur text;
  v_client_nom text;
  v_pro boolean;
  v_agence text;
  v_sujet text;
  v_corps text;
  v_envoi uuid;
  v_statut text;
  v_verrou text;
  v_erreur text;
begin
  select * into a from public.loc_avoirs where client_id = p_client and id = p_avoir;
  if not found or a.statut <> 'emis' then
    return jsonb_build_object('statut', 'rien');
  end if;
  select * into f from public.loc_factures where client_id = p_client and id = a.facture_id;
  select e.nom into v_agence from public.entites e where e.client_id = p_client and e.id = a.entite_id;
  v_nom_loueur := a.emetteur ->> 'nom';
  v_pro := a.destinataire ->> 'type' = 'professionnel';
  v_client_nom := coalesce(a.destinataire ->> 'raison_sociale', a.destinataire ->> 'nom');

  if (private.reglages_envois_effectifs(p_client, 'tavaro') ->> 'mode') is null then
    perform private.lever_alerte_module(p_client, 'tavaro', 'attention',
      format('Le courriel de l''avoir %s (contrat %s) n''est pas parti : l''envoi par courriel n''est pas réglé pour votre organisation. Envoyez-le vous-même.',
             a.reference, a.contrat_numero),
      jsonb_build_object('avoir', a.id, 'reference', a.reference, 'contrat', a.contrat_numero), 'avoir:envoi_non_regle:' || a.id::text, true, null);
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.avoir_envoi_non_regle', 'loc_avoirs', a.id::text,
      jsonb_build_object('reference', a.reference, 'contrat', a.contrat_numero), a.entite_id);
    return jsonb_build_object('statut', 'non_regle');
  end if;

  select x.* into l from public.loc_locataires x
  where x.client_id = p_client and x.id = (select c.locataire_id from public.loc_contrats c where c.client_id = p_client and c.id = a.contrat_id);
  if l.id is null or l.anonymise_le is not null or nullif(btrim(l.email), '') is null then
    perform private.lever_alerte_module(p_client, 'tavaro', 'attention',
      format('Le courriel de l''avoir %s (contrat %s) n''est pas parti : le locataire n''a pas d''adresse de courriel. Envoyez-le vous-même.', a.reference, a.contrat_numero),
      jsonb_build_object('avoir', a.id, 'reference', a.reference, 'contrat', a.contrat_numero), 'avoir:sans_adresse:' || a.id::text, true, null);
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.avoir_envoi_sans_adresse', 'loc_avoirs', a.id::text,
      jsonb_build_object('reference', a.reference, 'contrat', a.contrat_numero), a.entite_id);
    return jsonb_build_object('statut', 'sans_adresse');
  end if;

  v_sujet := format('%s : votre avoir %s sur la facture %s — location %s', v_nom_loueur, a.reference, f.reference, a.contrat_numero);
  v_corps := format(E'Bonjour %s,\n\n%s vous adresse l''avoir suivant, qui corrige la facture %s du %s :\n\n',
                    v_client_nom, v_nom_loueur, f.reference, to_char(f.date_facture, 'DD/MM/YYYY'))
    || private.loc_texte_avoir(a, f) || E'\n'
    || format(E'Pour toute question, écrivez à l''agence %s.\n\n', v_agence)
    || coalesce(a.mentions ->> 'mandat', '') || E'\n'
    || v_nom_loueur
    || case when a.emetteur ->> 'siren' is not null then ' — SIREN ' || (a.emetteur ->> 'siren') else '' end
    || case when a.emetteur ->> 'adresse' is not null then ' — ' || (a.emetteur ->> 'adresse') else '' end || E'\n';

  begin
    v_envoi := private.preparer_envoi(p_client, 'tavaro', 'loc_avoirs', a.id::text, 'email',
      jsonb_build_object('adresse', l.email, 'nom', v_client_nom, 'ref', l.id::text, 'professionnel', v_pro, 'langue', 'fr'),
      null, '{}'::jsonb, v_sujet, v_corps, null::uuid[], 'tavaro:avoir_courriel:' || a.id::text, a.entite_id, true, false, null::timestamptz,
      jsonb_build_object('demande', a.demande_id));
  exception when others then
    v_erreur := left(sqlstate || ' ' || sqlerrm, 500);
    update public.demandes_validation set statut = 'echec_execution', motif_echec = v_erreur where id = a.demande_id and statut = 'approuvee';
    perform private.lever_alerte_module(p_client, 'tavaro', 'critique',
      format('Le courriel de l''avoir %s (contrat %s) n''a pas pu être préparé. Envoyez-le vous-même.', a.reference, a.contrat_numero),
      jsonb_build_object('avoir', a.id, 'reference', a.reference, 'erreur', v_erreur), 'avoir:envoi_echec:' || a.id::text, true, null);
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.avoir_envoi_echec', 'loc_avoirs', a.id::text,
      jsonb_build_object('reference', a.reference, 'erreur', v_erreur), a.entite_id);
    return jsonb_build_object('statut', 'echec', 'erreur', v_erreur);
  end;

  update public.loc_avoirs set envoi_id = v_envoi where id = a.id and envoi_id is null;
  select e.statut, e.verrou into v_statut, v_verrou from public.envois e where e.id = v_envoi;
  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.avoir_envoi_prepare', 'loc_avoirs', a.id::text,
    jsonb_build_object('envoi', v_envoi, 'statut', v_statut, 'verrou', v_verrou, 'reference', a.reference, 'demande', a.demande_id, 'contrat', a.contrat_numero), a.entite_id);
  return jsonb_build_object('statut', 'prepare', 'envoi', v_envoi, 'envoi_statut', v_statut, 'verrou', v_verrou);
end $$;


--
-- Name: loc_envoyer_factures(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_envoyer_factures(p_client uuid, p_proposition uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.loc_propositions;
  c public.loc_contrats;
  l public.loc_locataires;
  f public.loc_factures;
  v_n integer;
  v_refs text;
  v_quoi text;
  v_nom_loueur text;
  v_client_nom text;
  v_pro boolean;
  v_agence text;
  v_restitution text;
  v_sujet text;
  v_corps text;
  v_envoi uuid;
  v_statut text;
  v_verrou text;
  v_erreur text;
begin
  select * into p from public.loc_propositions where client_id = p_client and id = p_proposition;
  if not found or p.statut <> 'facturee' then
    return jsonb_build_object('statut', 'rien');
  end if;
  select count(*)::int, string_agg(x.reference, ' et ' order by x.numero) into v_n, v_refs
  from public.loc_factures x where x.client_id = p_client and x.proposition_id = p.id;
  if v_n = 0 then
    return jsonb_build_object('statut', 'rien');
  end if;
  select * into f from public.loc_factures x where x.client_id = p_client and x.proposition_id = p.id order by x.numero limit 1;
  select * into c from public.loc_contrats where client_id = p_client and id = p.contrat_id;
  select e.nom into v_agence from public.entites e where e.client_id = p_client and e.id = p.entite_id;
  v_quoi := case when v_n > 1 then 'des factures ' else 'de la facture ' end || v_refs;
  v_nom_loueur := f.emetteur ->> 'nom';
  v_pro := f.destinataire ->> 'type' = 'professionnel';
  v_client_nom := coalesce(f.destinataire ->> 'raison_sociale', f.destinataire ->> 'nom');

  -- Sans réglage d'envoi pour l'organisation, rien ne passe par B4 : la facture s'envoie à la main.
  if (private.reglages_envois_effectifs(p_client, 'tavaro') ->> 'mode') is null then
    perform private.lever_alerte_module(p_client, 'tavaro', 'attention',
      format('Le courriel %s (contrat %s) n''est pas parti : l''envoi par courriel n''est pas réglé pour votre organisation. Envoyez-la vous-même.',
             v_quoi, c.numero),
      jsonb_build_object('proposition', p.id, 'contrat', c.numero, 'factures', v_refs), 'facture:envoi_non_regle:' || p.id::text, true, null);
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.facture_envoi_non_regle', 'loc_propositions', p.id::text,
      jsonb_build_object('factures', v_refs, 'contrat', c.numero), p.entite_id);
    return jsonb_build_object('statut', 'non_regle');
  end if;

  if c.locataire_id is not null then
    select * into l from public.loc_locataires x where x.client_id = p_client and x.id = c.locataire_id;
  end if;
  if l.id is null or l.anonymise_le is not null or nullif(btrim(l.email), '') is null then
    perform private.lever_alerte_module(p_client, 'tavaro', 'attention',
      format('Le courriel %s (contrat %s) n''est pas parti : le locataire n''a pas d''adresse de courriel. Envoyez-la vous-même.', v_quoi, c.numero),
      jsonb_build_object('proposition', p.id, 'contrat', c.numero, 'factures', v_refs), 'facture:sans_adresse:' || p.id::text, true, null);
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.facture_envoi_sans_adresse', 'loc_propositions', p.id::text,
      jsonb_build_object('factures', v_refs, 'contrat', c.numero), p.entite_id);
    return jsonb_build_object('statut', 'sans_adresse');
  end if;

  -- Le texte, au nom du loueur.
  v_restitution := f.mentions ->> 'restitution';
  v_sujet := format('%s : %s %s — location %s', v_nom_loueur, case when v_n > 1 then 'vos factures' else 'votre facture' end, v_refs, c.numero);
  v_corps := format(E'Bonjour %s,\n\nÀ la suite de la restitution du véhicule de la location %s%s, %s vous adresse %s :\n\n',
                    v_client_nom, c.numero, case when v_restitution is not null then ' le ' || v_restitution else '' end, v_nom_loueur,
                    case when v_n > 1 then 'les factures suivantes' else 'la facture suivante' end);
  for f in select * from public.loc_factures x where x.client_id = p_client and x.proposition_id = p.id order by x.numero loop
    v_corps := v_corps || private.loc_texte_facture(f) || E'\n';
  end loop;
  v_corps := v_corps
    || format(E'Les photos datées du départ et du retour et l''état des lieux sont à votre disposition sur simple demande à l''agence %s. Une contestation écrite adressée à l''agence suspend le recouvrement.\n\n', v_agence)
    || coalesce(f.mentions ->> 'mandat', '') || E'\n'
    || v_nom_loueur
    || case when f.emetteur ->> 'siren' is not null then ' — SIREN ' || (f.emetteur ->> 'siren') else '' end
    || case when f.emetteur ->> 'adresse' is not null then ' — ' || (f.emetteur ->> 'adresse') else '' end || E'\n';

  begin
    v_envoi := private.preparer_envoi(p_client, 'tavaro', 'loc_propositions', p.id::text, 'email',
      jsonb_build_object('adresse', l.email, 'nom', v_client_nom, 'ref', l.id::text, 'professionnel', v_pro, 'langue', 'fr'),
      null, '{}'::jsonb, v_sujet, v_corps, null::uuid[], 'tavaro:facture:' || p.id::text, p.entite_id, true, false, null::timestamptz,
      jsonb_build_object('demande', p.demande_id));
  exception when others then
    v_erreur := left(sqlstate || ' ' || sqlerrm, 500);
    update public.demandes_validation set statut = 'echec_execution', motif_echec = v_erreur where id = p.demande_id and statut = 'approuvee';
    perform private.lever_alerte_module(p_client, 'tavaro', 'critique',
      format('Le courriel %s (contrat %s) n''a pas pu être préparé. Envoyez-la vous-même.', v_quoi, c.numero),
      jsonb_build_object('proposition', p.id, 'contrat', c.numero, 'factures', v_refs, 'erreur', v_erreur), 'facture:envoi_echec:' || p.id::text, true, null);
    perform private.journaliser_module(p_client, 'tavaro', 'tavaro.facture_envoi_echec', 'loc_propositions', p.id::text,
      jsonb_build_object('factures', v_refs, 'erreur', v_erreur), p.entite_id);
    return jsonb_build_object('statut', 'echec', 'erreur', v_erreur);
  end;

  update public.loc_factures set envoi_id = v_envoi where client_id = p_client and proposition_id = p.id and envoi_id is null;
  select e.statut, e.verrou into v_statut, v_verrou from public.envois e where e.id = v_envoi;
  perform private.journaliser_module(p_client, 'tavaro', 'tavaro.facture_envoi_prepare', 'loc_propositions', p.id::text,
    jsonb_build_object('envoi', v_envoi, 'statut', v_statut, 'verrou', v_verrou, 'factures', v_refs, 'demande', p.demande_id, 'contrat', c.numero), p.entite_id);
  return jsonb_build_object('statut', 'prepare', 'envoi', v_envoi, 'envoi_statut', v_statut, 'verrou', v_verrou);
end $$;


--
-- Name: loc_eur(numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_eur(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select replace(to_char(p, 'FM999999990.00'), '.', ',') || ' €'
$$;


--
-- Name: loc_exiger_demande_approuvee(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_exiger_demande_approuvee() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  d public.demandes_validation;
  v_statut text;
begin
  select * into d from public.demandes_validation where id = new.demande_id;
  if not found or d.client_id <> new.client_id or d.module <> 'tavaro' or d.objet_type <> 'loc_propositions'
     or d.objet_id <> new.proposition_id::text or d.statut not in ('approuvee', 'executee') then
    raise exception 'Aucune facture sans demande approuvée sur sa proposition.' using errcode = '23514';
  end if;
  select p.statut into v_statut from public.loc_propositions p where p.client_id = new.client_id and p.id = new.proposition_id;
  if v_statut is null or v_statut not in ('validee', 'facturee') then
    raise exception 'La proposition de cette facture n''est pas validée (%).', coalesce(v_statut, 'introuvable') using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: loc_factures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loc_factures (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid NOT NULL,
    entite_emettrice_id uuid NOT NULL,
    contrat_id uuid NOT NULL,
    contrat_numero text NOT NULL,
    proposition_id uuid NOT NULL,
    demande_id uuid NOT NULL,
    nature text NOT NULL,
    annee smallint NOT NULL,
    numero integer NOT NULL,
    reference text NOT NULL,
    emise_le timestamp with time zone DEFAULT now() NOT NULL,
    date_facture date NOT NULL,
    echeance_le date NOT NULL,
    a_debiter_avant date,
    statut text DEFAULT 'emise'::text NOT NULL,
    total_ht numeric(12,2) NOT NULL,
    total_tva numeric(12,2) NOT NULL,
    total_ttc numeric(12,2) NOT NULL,
    emetteur jsonb NOT NULL,
    destinataire jsonb NOT NULL,
    mentions jsonb DEFAULT '{}'::jsonb NOT NULL,
    regle_le timestamp with time zone,
    mode_reglement text,
    litige_motif text,
    envoi_id uuid,
    pdf_piece_id uuid,
    pdf_sha256 text,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT loc_factures_litige_motif_check CHECK ((char_length(litige_motif) <= 500)),
    CONSTRAINT loc_factures_mode_reglement_check CHECK ((mode_reglement = ANY (ARRAY['depot'::text, 'comptoir'::text, 'virement'::text, 'carte'::text, 'autre'::text]))),
    CONSTRAINT loc_factures_nature_check CHECK ((nature = ANY (ARRAY['frais'::text, 'dommages'::text]))),
    CONSTRAINT loc_factures_numero_check CHECK ((numero >= 1)),
    CONSTRAINT loc_factures_pdf_sha256_check CHECK ((pdf_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT loc_factures_reference_check CHECK ((reference ~ '^FA-[0-9]{4}-[0-9]{6}$'::text)),
    CONSTRAINT loc_factures_reglement CHECK (((statut = 'reglee'::text) = ((regle_le IS NOT NULL) AND (mode_reglement IS NOT NULL)))),
    CONSTRAINT loc_factures_statut_check CHECK ((statut = ANY (ARRAY['emise'::text, 'envoyee'::text, 'reglee'::text, 'litige'::text, 'avoir'::text]))),
    CONSTRAINT loc_factures_total_ht_check CHECK ((total_ht >= (0)::numeric)),
    CONSTRAINT loc_factures_total_ttc_check CHECK ((total_ttc >= (0)::numeric)),
    CONSTRAINT loc_factures_total_tva_check CHECK ((total_tva >= (0)::numeric))
);


--
-- Name: loc_facture_de_l_agence(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_facture_de_l_agence(p_facture uuid) RETURNS public.loc_factures
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  f public.loc_factures;
begin
  if v_uid is null then
    raise exception 'Ce geste se fait par une personne connectée.' using errcode = '42501';
  end if;
  select * into f from public.loc_factures where id = p_facture;
  if not found or not exists (select 1 from public.comptes k where k.user_id = v_uid and k.client_id = f.client_id) then
    raise exception 'Facture introuvable.' using errcode = 'P0002';
  end if;
  if not private.a_un_role(f.client_id, array['gerant', 'admin', 'valideur', 'collaborateur'])
     or not private.voit_entite(f.client_id, f.entite_id) then
    raise exception 'Cette facture n''est pas dans votre périmètre.' using errcode = '42501';
  end if;
  return f;
end $$;


--
-- Name: loc_filtrer(jsonb, jsonb, jsonb, boolean, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_filtrer(p_actuel jsonb, p_neuf jsonb, p_saisies jsonb, p_complement boolean, INOUT p_avert jsonb, OUT garder jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  k text;
  v jsonb;
begin
  garder := '{}'::jsonb;
  for k, v in select * from jsonb_each(p_neuf) loop
    if p_saisies ? k then
      if (p_actuel -> k) is distinct from v and v <> 'null'::jsonb then
        p_avert := p_avert || jsonb_build_array(jsonb_build_object('code', 'saisie_protegee', 'champ', k));
      end if;
    elsif p_complement and coalesce(p_actuel -> k, 'null'::jsonb) <> 'null'::jsonb then
      if (p_actuel -> k) is distinct from v and v <> 'null'::jsonb then
        p_avert := p_avert || jsonb_build_array(jsonb_build_object('code', 'ecart_avec_le_logiciel', 'champ', k));
      end if;
    else
      garder := garder || jsonb_build_object(k, v);
    end if;
  end loop;
end $$;


--
-- Name: loc_garder_avoir(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_garder_avoir() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Un avoir ne s''efface pas.' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.statut <> 'a_valider' then
      raise exception 'Un avoir naît en attente de la direction.' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.statut = 'emis' and old.statut <> 'emis' then
    if not exists (select 1 from public.demandes_validation d
                   where d.id = new.demande_id and d.client_id = new.client_id and d.module = 'tavaro' and d.type_action = 'avoir.emettre'
                     and d.objet_type = 'loc_avoirs' and d.objet_id = new.id::text and d.statut in ('approuvee', 'executee')) then
      raise exception 'Aucun avoir sans demande approuvée par la direction.' using errcode = '23514';
    end if;
  end if;
  if old.statut = 'emis'
     and (new.id, new.client_id, new.entite_id, new.entite_emettrice_id, new.facture_id, new.facture_reference, new.contrat_id, new.contrat_numero,
          new.motif, new.total, new.montant_ht, new.montant_tva, new.montant_ttc, new.lignes, new.statut, new.demande_id, new.demande_par,
          new.annee, new.numero, new.reference, new.emis_le, new.date_avoir, new.emetteur, new.destinataire, new.mentions, new.cree_le)
         is distinct from
         (old.id, old.client_id, old.entite_id, old.entite_emettrice_id, old.facture_id, old.facture_reference, old.contrat_id, old.contrat_numero,
          old.motif, old.total, old.montant_ht, old.montant_tva, old.montant_ttc, old.lignes, old.statut, old.demande_id, old.demande_par,
          old.annee, old.numero, old.reference, old.emis_le, old.date_avoir, old.emetteur, old.destinataire, old.mentions, old.cree_le) then
    raise exception 'Un avoir émis ne se modifie pas : seules ses pièces avancent.' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: loc_garder_facture(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loc_garder_facture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Une facture émise ne s''efface pas : un avoir la corrige.' using errcode = '42501';
  end if;
  if (new.id, new.client_id, new.entite_id, new.entite_emettrice_id, new.contrat_id, new.contrat_numero, new.proposition_id, new.demande_id,
      new.nature, new.annee, new.numero, new.reference, new.emise_le, new.date_facture, new.echeance_le, new.a_debiter_avant,
      new.total_ht, new.total_tva, new.total_ttc, new.emetteur, new.destinataire, new.mentions, new.cree_le)
     is distinct from
     (old.id, old.client_id, old.entite_id, old.entite_emettrice_id, old.contrat_id, old.contrat_numero, old.proposition_id, old.demande_id,
      old.nature, old.annee, old.numero, old.reference, old.emise_le, old.date_facture, old.echeance_le, old.a_debiter_avant,
      old.total_ht, old.total_tva, old.total_ttc, old.emetteur, old.destinataire, old.mentions, old.cree_le) then
    raise exception 'Une facture émise ne se modifie pas : seuls son règlement, son litige et ses pièces avancent.' using errcode = '42501';
  end if;
  return new;
end $$;


