$$;


--
-- Name: lorani_ligne_du_point(public.lorani_permis, public.lorani_projets, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_ligne_du_point(p public.lorani_permis, p_projet public.lorani_projets, p_jour date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c jsonb := p.calcul;
  v_titre text := private.lorani_titre_permis(p, p_projet);
  v_dp boolean := p.type_autorisation = 'dp';
  v_impl jsonb := p.calcul -> 'decision_implicite';
  v_effet text;
  v_d date;
  v_n integer;
  v_gravite text;
  v_texte text;
begin
  if not p.actif or not p_projet.actif then
    return null;
  end if;
  -- Des dates lues sur les courriers attendent un membre : elles passent avant le reste, sauf une décision implicite.
  if p.etat <> 'decision_a_confirmer' then
    select count(*)::integer into v_n from public.lorani_permis_dates_lues l
    where l.client_id = p.client_id and l.permis_id = p.id and l.statut = 'proposee';
    if v_n > 0 then
      return jsonb_build_object(
        'texte', left(format('%s : %s sur les courriers de la mairie, à confirmer ou à écarter.', v_titre,
                             case when v_n = 1 then 'une date lue' else v_n || ' dates lues' end), 300),
        'lien', private.lorani_lien_permis(p.id), 'gravite', 'attention',
        'objet_type', 'lorani_projet', 'objet_id', p.projet_id::text, '_rang', 2, '_date', null);
    end if;
  end if;
  v_effet := case when c #>> '{regime,silence}' = 'rejet'
                  then case when v_dp then 'opposition tacite' else 'rejet implicite' end
                  else case when v_dp then 'non-opposition tacite' else 'permis tacite' end end;
  case p.etat
    when 'decision_a_confirmer' then
      v_d := (v_impl ->> 'date')::date;
      v_gravite := case when v_impl ->> 'nature' = 'tacite' then 'attention' else 'critique' end;
      v_texte := format('%s : %s le %s si aucune décision ne vous a été notifiée. À confirmer, ou saisir la décision reçue.',
        v_titre,
        case when v_impl ->> 'nature' = 'tacite'
             then case when v_dp then 'non-opposition tacite' else 'permis tacite né' end
             else case when v_dp then 'opposition tacite' else 'rejet implicite' end end,
        to_char(v_d, 'DD/MM/YYYY'));
    when 'pieces_demandees' then
      v_d := (select (s ->> 'date')::date from jsonb_array_elements(c -> 'etapes') s where s ->> 'nature' = 'pieces' limit 1);
      v_gravite := case when v_d - p_jour <= 3 then 'critique' when v_d - p_jour <= 10 then 'attention' else 'info' end;
      v_texte := format('%s : pièces manquantes à faire recevoir par la mairie au plus tard le %s (%s), sinon %s.',
        v_titre, to_char(v_d, 'DD/MM/YYYY'), private.lorani_quand(v_d - p_jour),
        case when v_dp then 'opposition tacite' else 'rejet tacite' end);
    when 'accorde' then
      if p.date_affichage is null then
        v_d := (select (s ->> 'date')::date from jsonb_array_elements(c -> 'etapes') s where s ->> 'nature' = 'affichage' limit 1);
        v_gravite := case when p_jour > v_d then 'attention' else 'info' end;
        v_texte := format('%s : affichage du permis sur le terrain %s, puis sa date à saisir : le recours des tiers ne court qu''à partir de lui.',
          v_titre, case when p_jour > v_d then 'en retard' else 'à faire d''ici le ' || to_char(v_d, 'DD/MM/YYYY') end);
      elsif (c ->> 'date_purge')::date <= p_jour + 30 then
        v_d := (c ->> 'date_purge')::date;
        v_gravite := 'info';
        v_texte := format('%s : purgé à l''issue du %s ; chantier sans risque de retrait ni de recours des tiers dès le %s.',
          v_titre, to_char(v_d, 'DD/MM/YYYY'), to_char(v_d + 1, 'DD/MM/YYYY'));
      else
        return null;
      end if;
    when 'recours_en_cours' then
      v_gravite := 'info';
      v_texte := format('%s : un recours est en cours ; pas de purge avant son issue, à saisir ici.', v_titre);
    when 'completude', 'instruction' then
      v_d := (c ->> 'date_decision_attendue')::date;
      if v_d is null or v_d > p_jour + 30 then
        return null;
      end if;
      v_gravite := 'info';
      v_texte := format('%s : %sdécision de la mairie attendue au plus tard le %s (%s) ; sans réponse, %s le %s.',
        v_titre,
        case when p.etat = 'completude'
             then format('sans demande de pièces d''ici le %s, ', to_char(
                    (select (s ->> 'date')::date from jsonb_array_elements(c -> 'etapes') s where s ->> 'nature' = 'completude' limit 1),
                    'DD/MM/YYYY'))
             else '' end,
        to_char(v_d, 'DD/MM/YYYY'), private.lorani_quand(v_d - p_jour), v_effet, to_char(v_d + 1, 'DD/MM/YYYY'));
    when 'purge' then
      v_d := (c ->> 'date_purge')::date;
      if v_d is null or v_d < p_jour - 8 then
        return null;
      end if;
      v_gravite := 'info';
      v_texte := format('%s : purgé depuis le %s ; le chantier peut démarrer sans risque de retrait ni de recours des tiers.',
        v_titre, to_char(v_d + 1, 'DD/MM/YYYY'));
    else
      return null;
  end case;
  return jsonb_build_object(
    'texte', left(v_texte, 300), 'lien', private.lorani_lien_permis(p.id), 'gravite', v_gravite,
    'objet_type', 'lorani_projet', 'objet_id', p.projet_id::text,
    '_rang', case v_gravite when 'critique' then 1 when 'attention' then 2 else 3 end, '_date', v_d);
end $$;


--
-- Name: lorani_lire_piece(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_lire_piece(p_piece uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.pieces;
  v_projet public.lorani_projets;
  x public.lorani_permis;
  v_valeurs jsonb;
  v_props jsonb;
  e jsonb;
  v_numero text;
  v_permis uuid;
  v_verifiee boolean;
  v_citations jsonb;
  v_id uuid;
  n integer := 0;
begin
  select * into p from public.pieces where id = p_piece;
  if not found then
    return jsonb_build_object('ignore', 'pièce introuvable');
  end if;
  if p.module <> 'lorani' or p.objet_type is distinct from 'lorani_projet' then
    return jsonb_build_object('ignore', 'pièce hors d''un dossier de Lorani');
  end if;
  if p.chiffrement is not null then
    return jsonb_build_object('ignore', 'pièce chiffrée');
  end if;
  if p.statut not in ('lue', 'a_verifier') then
    return jsonb_build_object('ignore', 'pièce non lue');
  end if;
  select * into v_projet from public.lorani_projets pr where pr.client_id = p.client_id and pr.id::text = p.objet_id;
  if not found then
    return jsonb_build_object('ignore', 'dossier introuvable');
  end if;

  v_valeurs := private.lorani_valeurs_de_piece(p.id);
  v_props := private.lorani_propositions(p.type_piece, v_valeurs);
  if jsonb_array_length(v_props) = 0 then
    if p.type_piece = 'lorani_arrete' and v_valeurs #>> '{decision,valeur}' = 'sursis' then
      perform private.lever_alerte_module(p.client_id, 'lorani', 'attention',
        left(format('« %s » : arrêté de sursis à statuer reçu. Le calendrier ne le calcule pas : à voir avec votre conseil.',
                    left(v_projet.nom, 80)), 200),
        jsonb_build_object('projet', v_projet.id, 'piece', p.id, 'lien', '/secteurs/architectes/permis'),
        'lecture:sursis:' || p.id, true, private.lorani_chef_de_projet(p.client_id, v_projet.id));
    end if;
    return jsonb_build_object('piece', p.id, 'type_piece', p.type_piece, 'propositions', 0);
  end if;

  -- Le permis visé : celui dont le numéro concorde, sinon le seul permis en cours du dossier.
  v_numero := private.lorani_numero_dossier(v_valeurs #>> '{numero_dossier,valeur}');
  if v_numero is not null then
    select x2.id into v_permis from public.lorani_permis x2
    where x2.client_id = p.client_id and x2.projet_id = v_projet.id and x2.actif
      and private.lorani_numero_dossier(x2.numero) = v_numero
    order by x2.cree_le limit 1;
  end if;
  if v_permis is null then
    select case when count(*) = 1 then min(x2.id::text)::uuid end into v_permis
    from public.lorani_permis x2
    where x2.client_id = p.client_id and x2.projet_id = v_projet.id and x2.actif
      and (v_numero is null or x2.numero is null or private.lorani_numero_dossier(x2.numero) = v_numero);
  end if;

  for e in select * from jsonb_array_elements(v_props) loop
    if v_permis is not null then
      select * into x from public.lorani_permis where id = v_permis;
      continue when private.lorani_deja_saisi(x, e ->> 'nature', e -> 'valeurs');
    end if;
    v_verifiee := not exists (select 1 from jsonb_array_elements_text(e -> 'champs') c
                              where v_valeurs ? c and jsonb_typeof(v_valeurs -> c) = 'object'
                                and not coalesce((v_valeurs #>> array[c, 'verifiee'])::boolean, false))
                  and not exists (select 1 from jsonb_array_elements_text(e -> 'champs') c,
                                                jsonb_array_elements(case jsonb_typeof(v_valeurs -> c) when 'array'
                                                                          then v_valeurs -> c else '[]'::jsonb end) r
                                  where not coalesce((r ->> 'verifiee')::boolean, false));
    select coalesce(jsonb_agg(jsonb_build_object('champ', c, 'texte', r ->> 'texte', 'page', (r ->> 'page')::integer,
                                                 'verifiee', coalesce((r ->> 'verifiee')::boolean, false))), '[]'::jsonb)
      into v_citations
    from jsonb_array_elements_text(e -> 'champs') c,
         jsonb_array_elements(case jsonb_typeof(v_valeurs -> c) when 'array' then v_valeurs -> c
                                   when 'object' then jsonb_build_array(v_valeurs -> c) else '[]'::jsonb end) r;

    v_id := null;
    insert into public.lorani_permis_dates_lues (client_id, entite_id, projet_id, permis_id, piece_id, type_piece, nature,
                                                 proposition, citations, verifiee)
    values (p.client_id, v_projet.entite_id, v_projet.id, v_permis, p.id, p.type_piece, e ->> 'nature',
            e -> 'valeurs', v_citations, v_verifiee)
    on conflict (client_id, piece_id, nature) do update
      set permis_id = excluded.permis_id, type_piece = excluded.type_piece, proposition = excluded.proposition,
          citations = excluded.citations, verifiee = excluded.verifiee, maj_le = now()
      where lorani_permis_dates_lues.statut = 'proposee'
    returning id into v_id;
    if v_id is not null then
      n := n + 1;
      perform private.lever_alerte_module(p.client_id, 'lorani', 'info',
        left(format('« %s » : %s lu%s sur %s, à confirmer.', left(v_projet.nom, 80),
          case e ->> 'nature' when 'depot' then 'date de dépôt' when 'delai_notifie' then 'délai d''instruction notifié'
                              when 'demande_pieces' then 'demande de pièces' when 'decision' then 'décision de la mairie'
                              when 'decision_tacite' then 'permis tacite' else 'premier jour d''affichage' end,
          case when e ->> 'nature' in ('depot', 'demande_pieces', 'decision') then 'e' else '' end,
          case p.type_piece when 'lorani_recepisse_depot' then 'le récépissé de dépôt'
                            when 'lorani_lettre_delai' then 'la lettre de la mairie'
                            when 'lorani_demande_pieces' then 'la demande de pièces'
                            when 'lorani_arrete' then 'l''arrêté'
                            when 'lorani_certificat_tacite' then 'le certificat'
                            else 'le constat d''affichage' end), 200),
        jsonb_build_object('projet', v_projet.id, 'permis', v_permis, 'piece', p.id, 'proposition', v_id,
                           'lien', '/secteurs/architectes/permis'),
        'lecture:' || v_id, true, private.lorani_chef_de_projet(p.client_id, v_projet.id));
    end if;
  end loop;
  return jsonb_strip_nulls(jsonb_build_object('piece', p.id, 'type_piece', p.type_piece, 'propositions', n,
                                              'permis', v_permis));
end $$;


--
-- Name: lorani_mesurer_calendrier(uuid, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_mesurer_calendrier(p_client uuid, p_du date, p_au date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'client', p_client, 'du', p_du, 'au', p_au,
    'rappels_j10', jsonb_build_object(
      'attendus', coalesce((select sum(r.base) from private.lorani_rappels_j10(p_client, p_du, p_au) r), 0),
      'partis', coalesce((select sum(r.partis) from private.lorani_rappels_j10(p_client, p_du, p_au) r), 0)),
    'dates_completes', jsonb_build_object(
      'permis', coalesce((select sum(d.en_cours) from private.lorani_dates_completes(p_client) d), 0),
      'complets', coalesce((select sum(d.complets) from private.lorani_dates_completes(p_client) d), 0)))
$$;


--
-- Name: lorani_numero_dossier(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_numero_dossier(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^0-9A-Za-z]', '', 'g')), '')
$$;


--
-- Name: lorani_ouvrir_projet_au_createur(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_ouvrir_projet_au_createur() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := (select auth.uid());
begin
  -- Seulement pour un membre de l'organisation : pour tout autre, la politique refuse l'insertion.
  if v_uid is not null
     and exists (select 1 from public.comptes c where c.user_id = v_uid and c.client_id = new.client_id)
     and not private.a_un_role(new.client_id, array['gerant']) then
    insert into public.acces_objets (client_id, objet_type, objet_id, user_id, niveau)
    values (new.client_id, 'lorani_projet', new.id::text, v_uid, 'ecriture')
    on conflict do nothing;
  end if;
  return new;
end $$;


--
-- Name: lorani_permis_a_recalculer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_permis_a_recalculer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.lorani_recalculer_permis(new.id, case tg_op when 'INSERT' then 'creation' else 'saisie' end);
  return null;
end $$;


--
-- Name: lorani_poser_echeances(public.lorani_permis, public.lorani_projets, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_poser_echeances(p public.lorani_permis, p_projet public.lorani_projets, p_calcul jsonb, p_raison text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e jsonb;
  l public.lorani_permis_echeances;
  d public.delais;
  v_existe boolean;
  v_pose boolean;
  v_sig text;
  v_delai uuid;
  v_n integer;
  v_rappels integer[];
  v_resp uuid := private.lorani_chef_de_projet(p.client_id, p.projet_id);
  v_natures text[] := '{}';
  v_jour date := (p_calcul ->> 'aujourdhui')::date;
  v_libelle text;
  v_cle text;
  v_poses integer := 0;
  v_annules integer := 0;
  v_tenus integer := 0;
  v_motif_fin text;
begin
  for e in select * from jsonb_array_elements(coalesce(p_calcul -> 'echeances', '[]'::jsonb)) loop
    v_natures := v_natures || (e ->> 'nature');
    v_rappels := array(select (x #>> '{}')::integer from jsonb_array_elements(coalesce(e -> 'rappels', '[]'::jsonb)) x);
    v_sig := concat_ws('|', e ->> 'nature', coalesce(e ->> 'regle', ''), coalesce(e ->> 'depart', ''), coalesce(e ->> 'date', ''),
                       coalesce(e ->> 'notifiee', ''), p_projet.territoire, array_to_string(v_rappels, ','),
                       coalesce(v_resp::text, ''));
    v_pose := false;
    select * into l from public.lorani_permis_echeances x where x.permis_id = p.id and x.nature = e ->> 'nature' and x.courante;
    v_existe := found;
    if v_existe and l.signature is distinct from v_sig then
      select * into d from public.delais where id = l.delai_id;
      if found and d.statut in ('ouvert', 'depasse') then
        perform private.clore_delai(d.id, 'annule', left(format('Recalculé (%s) : la base du calcul a changé.', p_raison), 300));
        v_annules := v_annules + 1;
      end if;
      update public.lorani_permis_echeances set courante = false where id = l.id;
      v_existe := false;
    end if;
    if not v_existe then
      select count(*)::integer + 1 into v_n from public.lorani_permis_echeances x
      where x.permis_id = p.id and x.nature = e ->> 'nature';
      v_libelle := left(format('%s « %s » : %s', upper(p.type_autorisation), left(p_projet.nom, 80), e ->> 'libelle'), 200);
      v_cle := format('lorani:permis:%s:%s:%s', p.id, e ->> 'nature', v_n);
      if e ? 'regle' then
        v_delai := private.poser_delai(p.client_id, 'lorani', 'lorani_projet', p.projet_id::text, v_libelle,
          e ->> 'regle', (e ->> 'depart')::date, p_projet.territoire, v_rappels, v_resp, e ->> 'action', v_cle);
        if e ? 'notifiee' then
          perform private.notifier_delai(v_delai, (e ->> 'notifiee')::date, left(e ->> 'source_notification', 300));
        end if;
      else
        v_delai := private.poser_delai_date(p.client_id, 'lorani', 'lorani_projet', p.projet_id::text, v_libelle,
          (e ->> 'date')::date, left(e ->> 'source', 300), p_projet.territoire, v_rappels, v_resp, e ->> 'action', v_cle);
      end if;
      insert into public.lorani_permis_echeances (client_id, projet_id, permis_id, nature, delai_id, signature)
      values (p.client_id, p.projet_id, p.id, e ->> 'nature', v_delai, v_sig)
      returning * into l;
      v_poses := v_poses + 1;
      v_pose := true;
    end if;

    select * into d from public.delais where id = l.delai_id;
    if d.statut in ('ouvert', 'depasse') and (
         e ->> 'statut' = 'tenu'
         or (coalesce((e ->> 'information')::boolean, false) and (d.statut = 'depasse' or d.echeance < v_jour))) then
      perform private.clore_delai(d.id, 'tenu', null);
      v_tenus := v_tenus + 1;
      update public.alertes
         set acquittee_le = now(), detail = detail || jsonb_build_object('resolution', 'échéance tenue')
       where client_id = p.client_id and cle_regroupement like format('lorani:permis:%s:%s:%%', p.id, e ->> 'nature')
         and acquittee_le is null;
    end if;
  end loop;

  v_motif_fin := case p_calcul ->> 'etat'
    when 'classe' then 'Permis classé' when 'annule' then 'Permis annulé ou retiré' when 'refuse' then 'Permis refusé'
    when 'rejete' then 'Demande rejetée' when 'hors_catalogue' then 'Territoire hors du catalogue'
    else 'Échéance sans objet' end;
  for l in select * from public.lorani_permis_echeances x
           where x.permis_id = p.id and x.courante and not (x.nature = any (v_natures)) loop
    select * into d from public.delais where id = l.delai_id;
    if found and d.statut in ('ouvert', 'depasse') then
      perform private.clore_delai(d.id, 'annule', left(format('%s (%s).', v_motif_fin, p_raison), 300));
      v_annules := v_annules + 1;
    end if;
    update public.lorani_permis_echeances set courante = false where id = l.id;
  end loop;

  return jsonb_build_object('poses', v_poses, 'annules', v_annules, 'tenus', v_tenus);
end $$;


--
-- Name: lorani_preparer_projet(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_preparer_projet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if new.entite_id is null then
    select e.id into new.entite_id from public.entites e where e.client_id = new.client_id and e.principale;
  end if;
  new.nom := btrim(new.nom);
  new.reference := nullif(btrim(new.reference), '');
  new.commune := nullif(btrim(new.commune), '');
  new.parcelles := coalesce((select array_agg(upper(regexp_replace(btrim(p), '\s+', ' ', 'g')) order by o)
                             from unnest(new.parcelles) with ordinality as u(p, o)
                             where nullif(btrim(p), '') is not null), '{}');
  if exists (select 1 from unnest(new.parcelles) p where p !~ '^[0-9A-Z ]{2,24}$') then
    raise exception 'Référence cadastrale illisible : « % ».',
      (select p from unnest(new.parcelles) p where p !~ '^[0-9A-Z ]{2,24}$' limit 1)
      using errcode = '22023', hint = 'Écrire la section et le numéro, par exemple « AB 123 ».';
  end if;
  new.territoire := coalesce(public.lorani_territoire_du_lieu(new.code_insee, new.code_postal),
                             new.territoire,
                             private.territoire_de_entite(new.client_id, new.entite_id));
  if tg_op = 'UPDATE' then
    new.maj_le := now();
  end if;
  return new;
end $_$;


--
-- Name: lorani_preparer_recours(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_preparer_recours() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.lorani_permis;
begin
  select * into p from public.lorani_permis where client_id = new.client_id and id = new.permis_id;
  if not found then
    raise exception 'Permis introuvable dans cette organisation.' using errcode = '23503';
  end if;
  new.projet_id := p.projet_id;
  new.entite_id := p.entite_id;
  new.auteur := nullif(btrim(new.auteur), '');
  if p.decision is null or p.decision not in ('favorable', 'tacite') then
    raise exception 'Un recours se saisit contre un permis accordé, exprès ou tacite confirmé.' using errcode = '22023';
  end if;
  if new.date_recours < p.date_decision then
    raise exception 'Le recours (%) ne peut précéder la décision (%).',
      to_char(new.date_recours, 'DD/MM/YYYY'), to_char(p.date_decision, 'DD/MM/YYYY') using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' then
    new.maj_le := now();
  end if;
  return new;
end $$;


--
-- Name: lorani_projet_a_recalculer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_projet_a_recalculer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record;
begin
  for r in select x.id from public.lorani_permis x where x.client_id = new.client_id and x.projet_id = new.id loop
    perform private.lorani_recalculer_permis(r.id, 'dossier modifié');
  end loop;
  return null;
end $$;


--
-- Name: lorani_propositions(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_propositions(p_type text, p_valeurs jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v jsonb := coalesce(p_valeurs, '{}'::jsonb);
  v_date date;
  v_decision text;
  v_pieces jsonb;
begin
  if p_type = 'lorani_recepisse_depot' then
    v_date := private.lorani_date_lue(v #>> '{date_depot,valeur}');
    if v_date is not null then
      return jsonb_build_array(jsonb_build_object(
        'nature', 'depot', 'champs', jsonb_build_array('date_depot', 'numero_dossier'),
        'valeurs', jsonb_strip_nulls(jsonb_build_object(
          'date_depot', v_date, 'numero', private.lorani_numero_dossier(v #>> '{numero_dossier,valeur}')))));
    end if;
  elsif p_type = 'lorani_lettre_delai' then
    v_date := private.lorani_date_lue(v #>> '{date_lettre,valeur}');
    if (case when v #>> '{delai_mois,valeur}' ~ '^\d{1,2}$'
             then (v #>> '{delai_mois,valeur}')::integer between 1 and 24 else false end) then
      return jsonb_build_array(jsonb_build_object(
        'nature', 'delai_notifie', 'champs', jsonb_build_array('delai_mois', 'date_lettre'),
        'valeurs', jsonb_strip_nulls(jsonb_build_object(
          'delai_notifie_mois', (v #>> '{delai_mois,valeur}')::integer, 'date_notification_delai', v_date))));
    end if;
  elsif p_type = 'lorani_demande_pieces' then
    v_date := private.lorani_date_lue(v #>> '{date_lettre,valeur}');
    if v_date is not null then
      -- Chaque pièce une fois, dans l'ordre de la lettre.
      select coalesce(jsonb_agg(jsonb_build_object('code', y.code) order by y.rang), '[]'::jsonb)
        into v_pieces
      from (select x.code, min(x.rang) as rang
            from (select upper(regexp_replace(e.valeur #>> '{valeur}', '\s', '', 'g')) as code, e.rang
                  from jsonb_array_elements(case jsonb_typeof(v -> 'pieces') when 'array' then v -> 'pieces'
                                                 when 'object' then jsonb_build_array(v -> 'pieces')
                                                 else '[]'::jsonb end) with ordinality as e(valeur, rang)
                  where e.valeur #>> '{valeur}' ~* '^\s*(PC|PA|PD|DP|CU)\s*\d{1,2}(\s*-?\s*\d{1,2})?\s*$') x
            group by x.code) y;
      return jsonb_build_array(jsonb_build_object(
        'nature', 'demande_pieces', 'champs', jsonb_build_array('date_lettre', 'pieces'),
        'valeurs', jsonb_build_object('date_demande_pieces', v_date, 'pieces', v_pieces)));
    end if;
  elsif p_type = 'lorani_arrete' then
    v_date := private.lorani_date_lue(v #>> '{date_decision,valeur}');
    v_decision := case v #>> '{decision,valeur}'
      when 'accorde' then 'favorable' when 'non_opposition' then 'favorable'
      when 'refuse' then 'defavorable' when 'opposition' then 'defavorable' end;
    if v_date is not null and v_decision is not null then
      return jsonb_build_array(jsonb_build_object(
        'nature', 'decision', 'champs', jsonb_build_array('decision', 'date_decision'),
        'valeurs', jsonb_build_object('decision', v_decision, 'date_decision', v_date)));
    end if;
  elsif p_type = 'lorani_certificat_tacite' then
    v_date := private.lorani_date_lue(v #>> '{date_tacite,valeur}');
    if v_date is not null then
      return jsonb_build_array(jsonb_build_object(
        'nature', 'decision_tacite', 'champs', jsonb_build_array('date_tacite'),
        'valeurs', jsonb_build_object('date_decision', v_date)));
    end if;
  elsif p_type = 'lorani_constat_affichage' then
    v_date := private.lorani_date_lue(v #>> '{date_constat,valeur}');
    if v_date is not null and coalesce(v #>> '{passage,valeur}', '1') = '1' then
      return jsonb_build_array(jsonb_build_object(
        'nature', 'affichage', 'champs', jsonb_build_array('date_constat'),
        'valeurs', jsonb_build_object('date_affichage', v_date)));
    end if;
  end if;
  return '[]'::jsonb;
end $_$;


--
-- Name: lorani_quand(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_quand(p_jours integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_jours < 0 then 'dépassé' when p_jours = 0 then 'aujourd''hui' when p_jours = 1 then 'demain'
              else format('dans %s jours', p_jours) end
$$;


--
-- Name: lorani_rappels_j10(uuid, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_rappels_j10(p_client uuid, p_du date, p_au date) RETURNS TABLE(entite_id uuid, jour date, base integer, partis integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.entite_id, d.echeance - 10, count(*)::integer, count(*) filter (where 10 = any (d.rappels_faits))::integer
  from public.lorani_permis_echeances e
  join public.lorani_permis x on x.client_id = e.client_id and x.id = e.permis_id
  join public.delais d on d.client_id = e.client_id and d.id = e.delai_id
  join public.territoires t on t.code = d.territoire
  where e.client_id = p_client and e.nature = 'pieces' and 10 = any (d.rappels)
    and d.echeance - 10 between p_du and p_au
    and (d.cree_le at time zone t.fuseau)::date <= d.echeance - 10
    and (d.clos_le is null or (d.clos_le at time zone t.fuseau)::date > d.echeance - 10 or 10 = any (d.rappels_faits))
  group by x.entite_id, d.echeance - 10
$$;


--
-- Name: lorani_recalculer_permis(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_recalculer_permis(p_permis uuid, p_raison text DEFAULT 'recalcul'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.lorani_permis;
  v_projet public.lorani_projets;
  v_calcul jsonb;
  v_bilan jsonb;
  v_ancien text;
begin
  -- Un dossier qu'on efface ne se recalcule pas.
  if coalesce(current_setting('omega.effacement_objet', true), '') = 'oui'
     or coalesce(current_setting('omega.effacement_client', true), '') <> '' then
    return null;
  end if;
  select * into p from public.lorani_permis where id = p_permis for update;
  if not found then
    return null;
  end if;
  select * into v_projet from public.lorani_projets where client_id = p.client_id and id = p.projet_id;
  v_ancien := p.etat;
  v_calcul := public.lorani_calendrier_permis(
    to_jsonb(p) || jsonb_build_object(
      'territoire', v_projet.territoire,
      'actif', p.actif and v_projet.actif,
      'recours', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'nature', r.nature, 'date_recours', r.date_recours,
                                                                'issue', r.issue, 'date_issue', r.date_issue)
                                            order by r.date_recours, r.id)
                           from public.lorani_permis_recours r where r.permis_id = p.id), '[]'::jsonb)));
  v_bilan := private.lorani_poser_echeances(p, v_projet, v_calcul, p_raison);

  update public.lorani_permis
     set etat = v_calcul ->> 'etat', silence = v_calcul #>> '{regime,silence}',
         date_decision_attendue = (v_calcul ->> 'date_decision_attendue')::date,
         date_purge = (v_calcul ->> 'date_purge')::date, calcul = v_calcul, calcule_le = now()
   where id = p.id;

  if (v_bilan ->> 'poses')::integer + (v_bilan ->> 'annules')::integer + (v_bilan ->> 'tenus')::integer > 0
     or v_ancien is distinct from v_calcul ->> 'etat' then
    perform private.journaliser_module(p.client_id, 'lorani', 'lorani.echeances_recalculees', 'lorani_permis', p.id::text,
      jsonb_build_object('raison', p_raison, 'version', v_calcul ->> 'version', 'etat', v_calcul ->> 'etat') || v_bilan,
      p.entite_id);
  end if;

  -- Une affaire close ferme ses alertes ; puis ce qui est arrivé seul se signale.
  if v_calcul ->> 'etat' in ('classe', 'annule', 'refuse', 'rejete', 'purge', 'hors_catalogue') then
    update public.alertes
       set acquittee_le = now(), detail = detail || jsonb_build_object('resolution', 'permis : ' || (v_calcul ->> 'etat'))
     where client_id = p.client_id and cle_regroupement like format('lorani:permis:%s:%%', p.id) and acquittee_le is null;
  end if;
  if p_raison in ('evenement', 'passage quotidien') and v_ancien is distinct from v_calcul ->> 'etat' then
    perform private.lorani_alerter_transition(p, v_projet, v_calcul);
  end if;
  return v_calcul;
end $$;


--
-- Name: lorani_recours_a_recalculer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_recours_a_recalculer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    perform private.lorani_recalculer_permis(old.permis_id, 'recours');
  else
    perform private.lorani_recalculer_permis(new.permis_id, 'recours');
  end if;
  return null;
end $$;


--
-- Name: lorani_suivre_entite_projet(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_suivre_entite_projet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.lorani_lots set entite_id = new.entite_id where client_id = new.client_id and projet_id = new.id;
  update public.lorani_intervenants set entite_id = new.entite_id where client_id = new.client_id and projet_id = new.id;
  update public.lorani_membres_projet set entite_id = new.entite_id where client_id = new.client_id and projet_id = new.id;
  return null;
end $$;


--
-- Name: lorani_titre_permis(public.lorani_permis, public.lorani_projets); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_titre_permis(p public.lorani_permis, p_projet public.lorani_projets) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select format('%s « %s »', upper(p.type_autorisation), left(p_projet.nom, 60))
$$;


--
-- Name: lorani_valeurs_de_piece(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_valeurs_de_piece(p_piece uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with lues as (
    select pv.id, pv.champ, pv.valeur #>> '{}' as valeur, (pv.verifiee or pv.source = 'humain') as verifiee,
           pv.texte, pv.page, pv.boite, pv.source = 'humain' as humain, pv.cree_le
    from public.pieces_valeurs pv
    where pv.piece_id = p_piece and pv.chiffre is null
  ), simples as (
    select distinct on (l.champ) l.champ,
           jsonb_build_object('valeur', l.valeur, 'verifiee', l.verifiee, 'texte', l.texte, 'page', l.page) as v
    from lues l
    where l.champ <> 'pieces'
    order by l.champ, l.humain desc, l.verifiee desc, l.cree_le desc, l.id
  ), repetes as (
    select l.champ,
           jsonb_agg(jsonb_build_object('valeur', l.valeur, 'verifiee', l.verifiee, 'texte', l.texte, 'page', l.page)
                     order by l.page nulls last, (l.boite ->> 'y1')::numeric desc nulls last,
                              (l.boite ->> 'x0')::numeric nulls last, l.id) as v
    from lues l
    where l.champ = 'pieces'
      and (l.humain or not exists (select 1 from lues h where h.champ = 'pieces' and h.humain))
    group by l.champ
  )
  select coalesce(jsonb_object_agg(x.champ, x.v), '{}'::jsonb)
  from (select * from simples union all select * from repetes) x
$$;


--
-- Name: lorani_voit_projet(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_voit_projet(p_client uuid, p_entite uuid, p_projet uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_client in (select private.mes_clients())
     and private.perimetre_couvre((select auth.uid()), p_client, p_entite)
     and private.voit_objet(p_client, 'lorani_projet', p_projet::text)
$$;


--
-- Name: lorani_voit_projet_pour(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lorani_voit_projet_pour(p_user uuid, p_client uuid, p_entite uuid, p_projet uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client)
     and private.perimetre_couvre(p_user, p_client, p_entite)
     and private.voit_objet_pour(p_user, p_client, 'lorani_projet', p_projet::text)
$$;


--
-- Name: marquer_envoi_manuel(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.marquer_envoi_manuel(p_envoi uuid, p_issue text, p_compte_rendu text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
  v_uid uuid := (select auth.uid());
begin
  select * into e from public.envois where id = p_envoi for update;
  if e.id is null then
    raise exception 'Envoi introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is not null then
    perform private.exiger_acteur_envoi(e.client_id, e.entite_id, e.objet_type, e.objet_id);
  else
    perform private.exiger_ouvrier();
  end if;
  if e.fournisseur is distinct from 'manuel' then
    raise exception 'Cet envoi part par l''ouvrier d''envoi : rien à noter à la main.' using errcode = '42501';
  end if;
  if e.statut <> 'en_cours' then
    raise exception 'Ouvrez d''abord l''envoi (commencer_envoi) : ses verrous sont relus au moment d''agir.'
      using errcode = '55000';
  end if;
  if p_issue is null or p_issue not in ('envoye', 'joint', 'message_laisse', 'sans_reponse', 'occupe', 'faux_numero',
                                        'adresse_invalide', 'abandonne') then
    raise exception 'Issue inconnue : envoye, joint, message_laisse, sans_reponse, occupe, faux_numero, adresse_invalide ou abandonne.'
      using errcode = '22023';
  end if;

  if p_issue in ('envoye', 'joint', 'message_laisse') then
    perform set_config('omega.envois_ouvrier', 'oui', true);
    update public.envois
       set statut = 'envoye', envoye_le = now(), clos_le = now(), bail_jusqu_au = null,
           compte_rendu = left(nullif(btrim(p_compte_rendu), ''), 300),
           motif = case p_issue when 'joint' then 'Appel : joint.' when 'message_laisse' then 'Appel : message laissé.'
                                else 'Envoyé à la main.' end
     where id = p_envoi
    returning * into e;
    perform set_config('omega.envois_ouvrier', '', true);
    perform private.clore_demande_envoi(e, true, null);
    perform private.publier_envoi(e, 'envoye');
    return 'envoye';
  elsif p_issue in ('sans_reponse', 'occupe') then
    if e.essais >= 3 then
      update public.envois
         set statut = 'echec', clos_le = now(), bail_jusqu_au = null, compte_rendu = left(nullif(btrim(p_compte_rendu), ''), 300),
             motif = 'Pas de réponse après trois tentatives.'
       where id = p_envoi
      returning * into e;
      perform private.clore_demande_envoi(e, false, e.motif);
      perform private.publier_envoi(e, 'echec');
      return 'echec';
    end if;
    update public.envois
       set statut = 'differe', verrou = 'RAPPEL', reprise_le = now() + interval '2 hours', bail_jusqu_au = null,
           compte_rendu = left(nullif(btrim(p_compte_rendu), ''), 300),
           motif = 'Pas de réponse : nouvelle tentative dans deux heures.'
     where id = p_envoi;
    return 'differe';
  elsif p_issue in ('faux_numero', 'adresse_invalide') then
    update public.envois
       set statut = 'echec', clos_le = now(), bail_jusqu_au = null, compte_rendu = left(nullif(btrim(p_compte_rendu), ''), 300),
           motif = 'Numéro ou adresse erroné.'
     where id = p_envoi
    returning * into e;
    perform private.clore_demande_envoi(e, false, e.motif);
    perform private.publier_envoi(e, 'echec');
    if e.mode = 'reel' then
      perform private.opposer(e.client_id, 'invalide', e.destinataire_adresse, e.canal, null, null,
                              'Signalé à l''exécution manuelle.', 'client', v_uid);
    end if;
    return 'echec';
  end if;
  perform private.clore_envoi(p_envoi, 'annule', 'ANNULE', 'Abandonné par la personne qui devait l''exécuter.');
  return 'annule';
end $$;


--
-- Name: mes_clients(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mes_clients() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.client_id from public.comptes c where c.user_id = (select auth.uid())
$$;


--
-- Name: mesure_agregat(uuid, text, smallint, text, text, date, date, uuid, boolean, uuid, boolean, text, text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_agregat(p_client uuid, p_code text, p_version smallint, p_agregation text, p_mode text, p_du date, p_au date, p_lecteur uuid, p_par_entite boolean DEFAULT false, p_entite uuid DEFAULT NULL::uuid, p_par_objet boolean DEFAULT false, p_objet_type text DEFAULT NULL::text, p_objet_id text DEFAULT NULL::text, p_grains text[] DEFAULT NULL::text[]) RETURNS TABLE(valeur numeric, numerateur numeric, base numeric, nb integer, jours integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with lignes as (
    select m.*
    from public.mesures m
    where m.client_id = p_client and m.indicateur = p_code and m.version = p_version and m.mode = p_mode
      and (p_mode = 'a_blanc'
           or (m.periode_type <> 'libre'
               and (case when m.periode_type = 'semaine' then m.debut + 3 else m.debut end) between p_du and p_au))
      and (p_grains is null or m.periode_type = any (p_grains))
      and (p_lecteur is null or private.perimetre_couvre(p_lecteur, p_client, m.entite_id))
      and (not p_par_entite or m.entite_id is not distinct from p_entite)
      and (not p_par_objet or (m.objet_type is not distinct from p_objet_type and m.objet_id is not distinct from p_objet_id))
  ), derniers as (
    select distinct on (l.entite_id, l.objet_type, l.objet_id) l.valeur, l.base
    from lignes l
    order by l.entite_id, l.objet_type, l.objet_id, l.debut desc, l.fin desc
  )
  select case p_agregation
           when 'somme' then (select sum(l.valeur) from lignes l)
           when 'moyenne' then (select sum(l.numerateur) / nullif(sum(l.base), 0) from lignes l)
           else (select sum(d.valeur) from derniers d) end,
         (select sum(l.numerateur) from lignes l),
         case when p_agregation = 'dernier' then (select sum(d.base) from derniers d)
              else (select sum(l.base) from lignes l) end,
         (select count(*)::integer from lignes l),
         (select count(distinct j.jour)::integer
          from lignes l cross join lateral generate_series(l.debut::timestamp, l.fin::timestamp, interval '1 day') as j(jour))
$$;


--
-- Name: mesure_garder_indicateur(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_garder_indicateur() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Un indicateur ne s''efface pas : on retire sa version du service.' using errcode = '42501';
  end if;
  if (new.code, new.version, new.libelle, new.definition, new.formule, new.unite, new.sens, new.agregation,
      new.decimales, new.source, new.cree_le)
     is distinct from
     (old.code, old.version, old.libelle, old.definition, old.formule, old.unite, old.sens, old.agregation,
      old.decimales, old.source, old.cree_le) then
    raise exception 'Une version d''indicateur ne se modifie pas : on en publie une nouvelle.' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: mesure_mois_de(text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_mois_de(p_periode_type text, p_debut date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select date_trunc('month', case when p_periode_type = 'semaine' then p_debut + 3 else p_debut end)::date
$$;


--
-- Name: mesure_perimer(uuid, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_perimer(p_client uuid, p_mode text, p_periode_type text, p_debut date) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.rapports_du_mois r set perime = true
  where r.client_id = p_client and not r.perime
    and (p_mode = 'a_blanc'
         or r.mois between private.mesure_mois_de(p_periode_type, p_debut)
                       and (private.mesure_mois_de(p_periode_type, p_debut) + interval '11 months')::date)
$$;


--
-- Name: mesure_perimer_rapports(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_perimer_rapports() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform private.mesure_perimer(old.client_id, old.mode, old.periode_type, old.debut);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform private.mesure_perimer(new.client_id, new.mode, new.periode_type, new.debut);
  end if;
  return null;
end $$;


--
-- Name: mesure_texte(numeric, text, integer, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_texte(p numeric, p_unite text, p_decimales integer, p_ecart boolean DEFAULT false) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p is null then null else
    case when p_ecart and round(p * case when p_unite = '%' then 100 else 1 end, coalesce(p_decimales, 0)) > 0 then '+' else '' end
    || private.point_nombre_fr(p * case when p_unite = '%' then 100 else 1 end, p_decimales)
    || case p_unite
         when '%' then chr(160) || case when p_ecart then 'pt' else '%' end
         when 'euros' then chr(160) || '€'
         when 'jours' then chr(160) || 'j'
         when 'heures' then chr(160) || 'h'
         when 'minutes' then chr(160) || 'min'
         else '' end
  end
$$;


--
-- Name: mesure_verdict(numeric, text, text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_verdict(p_ecart numeric, p_sens text, p_unite text, p_decimales integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_ecart is null then null
    when abs(p_ecart) * case when p_unite = '%' then 100 else 1 end < 0.5 * power(10::numeric, -coalesce(p_decimales, 0)) then 'egal'
    when (p_ecart > 0) = (p_sens = 'hausse') then 'mieux'
    else 'moins_bien' end
$$;


--
-- Name: mesure_visible(uuid, text, smallint, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesure_visible(p_client uuid, p_code text, p_version smallint, p_entite uuid, p_objet_type text, p_objet_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.perimetre_couvre((select auth.uid()), p_client, p_entite)
     and exists (
       select 1 from public.indicateurs i
       where i.code = p_code and i.version = p_version
         and case when p_objet_id is null
                  then i.droit_lecture is null or private.a_le_droit(p_client, i.droit_lecture)
                  else (coalesce(i.droit_detail, i.droit_lecture) is null
                        or private.a_le_droit(p_client, coalesce(i.droit_detail, i.droit_lecture)))
                       and private.voit_objet(p_client, p_objet_type, p_objet_id) end)
$$;


--
-- Name: mesurer_suivis(uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesurer_suivis(p_client uuid, p_module text, p_du timestamp with time zone, p_au timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'ouverts', count(*) filter (where s.statut = 'ouvert'),
    'clos', count(*) filter (where s.statut <> 'ouvert'),
    'recus', count(*) filter (where s.statut = 'recu'),
    'expires', count(*) filter (where s.statut = 'expire'),
    'part_recue', case when count(*) filter (where s.statut <> 'ouvert') = 0 then null
                       else round(100.0 * count(*) filter (where s.statut = 'recu') / count(*) filter (where s.statut <> 'ouvert'), 1) end,
    'age_median_jours', percentile_cont(0.5) within group (order by extract(epoch from (coalesce(s.clos_le, p_au) - s.depuis)) / 86400),
    'glissements_moyens', round(avg(s.glissements), 2),
    'relances_par_suivi', round(avg(s.relances), 2),
    'sans_aucune_relance', count(*) filter (where s.statut = 'recu' and s.relances = 0))
  from public.suivis s
  where s.client_id = p_client and s.module = p_module and s.depuis >= p_du and s.depuis < p_au
$$;


--
-- Name: mesures_tache(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mesures_tache(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c record;
  r record;
  v_fuseau text;
  v_local timestamp;
  v_jour_revolu date;
  v_dernier date;
  v_jour date;
  v_mois date;
  v_contenu jsonb;
  v_nb integer;
  v_mieux integer;
  v_silences integer;
  v_clients integer := 0;
  v_rapports integer := 0;
  v_points integer := 0;
  v_erreurs integer := 0;
begin
  for c in
    select cl.id, cl.nom from public.clients cl
    where exists (select 1 from public.mesures m where m.client_id = cl.id)
       or exists (select 1 from public.points_reglages pr where pr.client_id = cl.id)
    order by cl.id
  loop
    begin
      -- Sans territoire connu, le mois se clôt à l'heure universelle : une mesure
      -- arrivée ensuite périme le rapport, qui se refait.
      v_fuseau := coalesce((select t.fuseau from public.territoires t where t.code = private.point_territoire_client(c.id)),
                           'UTC');
      v_local := p_maintenant at time zone v_fuseau;

      v_jour_revolu := null;
      if exists (select 1 from public.points_reglages pr where pr.client_id = c.id) then
        select min((p_maintenant at time zone r2.fuseau)::date) - 1 into v_jour_revolu
        from public.comptes co
        cross join lateral private.point_reglage(co.client_id, co.user_id) r2
        where co.client_id = c.id and r2.pose and r2.fuseau is not null;
      end if;
      if v_jour_revolu is not null then
        select max(m.debut) into v_dernier
        from public.mesures m
        where m.client_id = c.id and m.indicateur = 'point_du_matin.ponctualite' and m.version = 1
          and m.mode = 'reel' and m.periode_type = 'jour' and m.entite_id is null and m.objet_id is null;
        for v_jour in
          select g::date
          from generate_series(greatest(coalesce(v_dernier + 1, v_jour_revolu), v_jour_revolu - 6)::timestamp,
                               v_jour_revolu::timestamp, interval '1 day') g
        loop
          v_points := v_points + private.point_mesurer_jour(c.id, v_jour, p_maintenant);
        end loop;
      end if;

      v_mois := (date_trunc('month', v_local) - interval '1 month')::date;
      if v_local >= date_trunc('month', v_local) + interval '5 hours'
         and not exists (select 1 from public.rapports_du_mois x where x.client_id = c.id and x.mois = v_mois)
         and exists (select 1 from public.mesures m
                     where m.client_id = c.id and m.mode = 'reel'
                       and private.mesure_mois_de(m.periode_type, m.debut) = v_mois) then
        v_contenu := private.construire_rapport_du_mois(c.id, v_mois);
        v_rapports := v_rapports + 1;
        -- Les indicateurs mesurés dans le mois ; ceux qui se sont tus lèvent l'alerte.
        v_nb := (select count(*) from jsonb_array_elements(v_contenu -> 'indicateurs') x
                 where (x ->> 'mesure_ce_mois')::boolean);
        v_mieux := (select count(*) from jsonb_array_elements(v_contenu -> 'indicateurs') x
                    where x #>> '{ecart,verdict}' = 'mieux');
        v_silences := jsonb_array_length(v_contenu -> 'non_mesures');
        if v_silences > 0 then
          perform private.lever_alerte(c.id, true, 'attention', 'mesure',
            format('%s indicateur%s sans mesure en %s chez %s', v_silences, case when v_silences > 1 then 's' else '' end,
                   private.point_mois_fr(v_mois), c.nom),
            jsonb_build_object('mois', to_char(v_mois, 'YYYY-MM'), 'indicateurs', v_contenu -> 'non_mesures'),
            'mesure_silence:' || to_char(v_mois, 'YYYY-MM'));
        end if;
        if exists (select 1 from public.points_reglages pr where pr.client_id = c.id and pr.user_id is null and pr.actif) then
          perform private.deposer_section(c.id, 'mesure', v_local::date, null, 'gerant', 'Rapport du mois',
            jsonb_build_array(jsonb_build_object(
              'texte', format('Le rapport %s est prêt : %s indicateur%s%s.', private.point_de_mois_fr(v_mois), v_nb,
                              case when v_nb > 1 then 's' else '' end,
                              case when v_mieux > 0 then format(', dont %s en progrès sur la situation de départ', v_mieux)
                                   else '' end),
              'lien', '/mesure/' || to_char(v_mois, 'YYYY-MM'), 'gravite', 'info')),
            null, null, false, null, false, 10);
        end if;
      end if;

      for r in select x.mois from public.rapports_du_mois x where x.client_id = c.id and x.perime order by x.mois loop
        perform private.construire_rapport_du_mois(c.id, r.mois);
        v_rapports := v_rapports + 1;
      end loop;

      perform private.battre(c.id, 'mesure_rapports', jsonb_build_object('passage', p_maintenant), interval '2 hours');
      v_clients := v_clients + 1;
    exception when others then
      v_erreurs := v_erreurs + 1;
      perform private.lever_alerte(c.id, true, 'critique', 'mesure', format('La mesure échoue chez %s', c.nom),
        jsonb_build_object('erreur', left(sqlerrm, 300)), 'mesure_tache');
    end;
  end loop;
  return jsonb_build_object('clients', v_clients, 'rapports', v_rapports, 'mesures_du_point', v_points, 'erreurs', v_erreurs);
end $$;


--
-- Name: motif_valide(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.motif_valide(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p is null then
    return true;
  end if;
  if char_length(p) not between 1 and 300 then
    return false;
  end if;
  perform ('' ~* p);
  return true;
exception when others then
  return false;
end $$;


--
-- Name: options_valides(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.options_valides(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    return false;
  end if;
  if exists (select 1 from jsonb_object_keys(p) x
             where x not in ('separateur', 'encodage', 'decimal', 'format_date', 'feuille', 'ligne_entetes', 'pied')) then
    return false;
  end if;
  return (not (p ? 'separateur') or (jsonb_typeof(p -> 'separateur') = 'string' and char_length(p ->> 'separateur') = 1
                                      and p ->> 'separateur' !~ '[[:alnum:]"'']'))
     and (not (p ? 'encodage') or p ->> 'encodage' in ('utf-8', 'utf-8-sig', 'utf-16', 'cp1252', 'iso-8859-15', 'latin-1'))
     and (not (p ? 'decimal') or p ->> 'decimal' in (',', '.'))
     and (not (p ? 'format_date') or p ->> 'format_date' in ('jj/mm/aaaa', 'mm/jj/aaaa', 'aaaa-mm-jj', 'aaaammjj'))
     and (not (p ? 'feuille') or (jsonb_typeof(p -> 'feuille') = 'string' and char_length(p ->> 'feuille') between 1 and 100))
     and (not (p ? 'ligne_entetes') or (jsonb_typeof(p -> 'ligne_entetes') = 'number'
                                        and (p ->> 'ligne_entetes') ~ '^[0-9]{1,4}$'
                                        and (p ->> 'ligne_entetes')::integer between 1 and 1000))
     and (not (p ? 'pied') or jsonb_typeof(p -> 'pied') = 'boolean');
end $_$;


--
-- Name: plages_valides(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.plages_valides(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  e jsonb;
  j jsonb;
begin
  if p is null then
    return true;
  end if;
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) = 0 then
    return false;
  end if;
  for e in select * from jsonb_array_elements(p) loop
    if jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'jours') is distinct from 'array'
       or jsonb_array_length(e -> 'jours') = 0
       or coalesce(e ->> 'debut', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or coalesce(e ->> 'fin', '') !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$'
       or (e ->> 'debut')::time >= (e ->> 'fin')::time then
      return false;
    end if;
    for j in select * from jsonb_array_elements(e -> 'jours') loop
      if jsonb_typeof(j) <> 'number' or j::text !~ '^[1-7]$' then
        return false;
      end if;
    end loop;
  end loop;
  return true;
end $_$;


--
-- Name: modeles_jeux; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.modeles_jeux (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    module text,
    logiciel text,
    code text NOT NULL,
    version smallint DEFAULT 1 NOT NULL,
    libelle text NOT NULL,
    motif_fichier text,
    entetes text[] DEFAULT '{}'::text[] NOT NULL,
    colonnes jsonb DEFAULT '{}'::jsonb NOT NULL,
    cle text[] DEFAULT '{}'::text[] NOT NULL,
    complet boolean DEFAULT true NOT NULL,
    fenetre jsonb,
    confirmer_disparition smallint DEFAULT 1 NOT NULL,
    seuil_perte numeric(4,3) DEFAULT 0.2 NOT NULL,
    perte_min integer DEFAULT 1 NOT NULL,
    seuil_anomalies numeric(4,3) DEFAULT 0.05 NOT NULL,
    options jsonb DEFAULT '{}'::jsonb NOT NULL,
    accuse boolean DEFAULT true NOT NULL,
    rythme interval,
    plages jsonb,
    attendu jsonb,
    source text,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT modeles_jeux_attendu_check CHECK (private.attendu_valide(attendu)),
    CONSTRAINT modeles_jeux_code_check CHECK ((code ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT modeles_jeux_coherent CHECK (private.declaration_coherente(colonnes, cle, fenetre, entetes)),
    CONSTRAINT modeles_jeux_colonnes_check CHECK (private.colonnes_valides(colonnes)),
    CONSTRAINT modeles_jeux_confirmer_disparition_check CHECK (((confirmer_disparition >= 1) AND (confirmer_disparition <= 10))),
    CONSTRAINT modeles_jeux_fenetre_check CHECK (private.fenetre_jeu_valide(fenetre)),
    CONSTRAINT modeles_jeux_libelle_check CHECK (((char_length(btrim(libelle)) >= 1) AND (char_length(btrim(libelle)) <= 200))),
    CONSTRAINT modeles_jeux_logiciel_check CHECK ((logiciel ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT modeles_jeux_module_check CHECK ((module ~ '^[a-z][a-z_]{1,29}$'::text)),
    CONSTRAINT modeles_jeux_motif_fichier_check CHECK (private.motif_valide(motif_fichier)),
    CONSTRAINT modeles_jeux_options_check CHECK (private.options_valides(options)),
    CONSTRAINT modeles_jeux_perte_min_check CHECK ((perte_min >= 1)),
    CONSTRAINT modeles_jeux_plages_check CHECK (private.plages_valides(plages)),
    CONSTRAINT modeles_jeux_rythme_check CHECK ((rythme >= '00:05:00'::interval)),
    CONSTRAINT modeles_jeux_seuil_anomalies_check CHECK (((seuil_anomalies >= (0)::numeric) AND (seuil_anomalies <= (1)::numeric))),
    CONSTRAINT modeles_jeux_seuil_perte_check CHECK (((seuil_perte >= (0)::numeric) AND (seuil_perte <= (1)::numeric))),
    CONSTRAINT modeles_jeux_source_check CHECK ((char_length(source) <= 400)),
    CONSTRAINT modeles_jeux_version_check CHECK ((version >= 1))
);


--
-- Name: modele_pour(text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.modele_pour(p_module text, p_logiciel text, p_code text) RETURNS public.modeles_jeux
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.* from public.modeles_jeux m
  where m.code = p_code and (m.module is null or m.module = p_module) and (m.logiciel is null or m.logiciel = p_logiciel)
  order by (m.module is not null and m.logiciel is not null) desc, (m.logiciel is not null) desc,
           (m.module is not null) desc, m.version desc
  limit 1
$$;


--
-- Name: modifier_demande(uuid, text, numeric, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.modifier_demande(p_demande uuid, p_resume text DEFAULT NULL::text, p_montant numeric DEFAULT NULL::numeric, p_payload jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.demandes_validation;
  v_resume text;
  v_montant numeric(14,2);
  v_payload jsonb;
  v_modifs jsonb := '[]'::jsonb;
  v_trace jsonb := '[]'::jsonb;
  v_cle text;
  v_nouvelle uuid;
begin
  if v_uid is null then
    raise exception 'Une modification est toujours faite par une personne connectée.' using errcode = '42501';
  end if;

  select * into v_d from public.demandes_validation where id = p_demande for update;
  if not found then
    raise exception 'Demande introuvable.' using errcode = 'P0002';
  end if;
  if not private.voit_objet_pour(v_uid, v_d.client_id, v_d.objet_type, v_d.objet_id)
     or not exists (select 1 from public.comptes c where c.user_id = v_uid and c.client_id = v_d.client_id) then
    raise exception 'Demande introuvable.' using errcode = 'P0002';
  end if;
  if v_d.statut <> 'en_attente' then
    raise exception 'Cette demande n''est plus en attente (%).', v_d.statut using errcode = '23514';
  end if;
  if v_d.demandeur_id = v_uid then
    raise exception 'Vous avez déposé cette demande : annulez-la et déposez-en une autre.' using errcode = '42501';
  end if;
  perform private.exiger_decideur(v_d, v_uid);

  v_resume := coalesce(nullif(btrim(p_resume), ''), v_d.resume);
  v_montant := coalesce(p_montant, v_d.montant);
  v_payload := v_d.payload || coalesce(p_payload, '{}'::jsonb);

  if v_resume is distinct from v_d.resume then
    v_modifs := v_modifs || jsonb_build_array(jsonb_build_object('champ', 'resume', 'avant', v_d.resume, 'apres', v_resume));
    v_trace := v_trace || jsonb_build_array(jsonb_build_object('champ', 'resume', 'avant', v_d.resume, 'apres', v_resume));
  end if;
  if v_montant is distinct from v_d.montant then
    v_modifs := v_modifs || jsonb_build_array(jsonb_build_object('champ', 'montant', 'avant', v_d.montant, 'apres', v_montant));
    v_trace := v_trace || jsonb_build_array(jsonb_build_object('champ', 'montant', 'avant', v_d.montant, 'apres', v_montant));
  end if;
  for v_cle in select jsonb_object_keys(coalesce(p_payload, '{}'::jsonb)) loop
    if (v_d.payload -> v_cle) is distinct from (v_payload -> v_cle) then
      v_modifs := v_modifs || jsonb_build_array(jsonb_build_object(
        'champ', 'payload.' || v_cle, 'avant', v_d.payload -> v_cle, 'apres', v_payload -> v_cle));
      -- Le contenu préparé n'entre pas au journal : seulement le nom du champ.
      v_trace := v_trace || jsonb_build_array(jsonb_build_object('champ', 'payload.' || v_cle));
    end if;
  end loop;
  if v_modifs = '[]'::jsonb then
    raise exception 'Aucune modification : la demande est identique.' using errcode = '22023';
  end if;

  insert into public.demandes_validation (
    client_id, entite_id, module, type_action, objet_type, objet_id, resume, montant, devise,
    payload, echeance, cle_idempotence)
  values (
    v_d.client_id, v_d.entite_id, v_d.module, v_d.type_action, v_d.objet_type, v_d.objet_id, v_resume, v_montant,
    v_d.devise, v_payload || jsonb_build_object('remplace', v_d.id, 'modifications', v_modifs),
    v_d.echeance, 'remplace:' || v_d.id::text)
  returning id into v_nouvelle;

  update public.demandes_validation set statut = 'annulee' where id = v_d.id;

  perform private.journaliser(
    v_d.client_id, 'demandes_validation.remplacement', 'demandes_validation', v_d.id::text,
    jsonb_build_object('nouvelle', v_nouvelle, 'modifications', v_trace), v_d.entite_id);
  return v_nouvelle;
end $$;


--
-- Name: normaliser_adresse(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normaliser_adresse(p_canal text, p_adresse text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case (select c.adresse from private.canaux_envoi c where c.canal = p_canal)
    when 'email' then private.normaliser_email(p_adresse)
    when 'telephone' then private.normaliser_telephone(p_adresse) end
$$;


--
-- Name: normaliser_email(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normaliser_email(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case
    when char_length(btrim(p)) <= 254
     and lower(btrim(p)) ~ '^[a-z0-9._%+''-]+@[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\.[a-z]{2,}$'
    then lower(btrim(p)) end
$_$;


--
-- Name: normaliser_telephone(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normaliser_telephone(p text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v text := regexp_replace(coalesce(p, ''), '[[:space:].()/-]', '', 'g');
begin
  if v ~ '^00[1-9]' then
    v := '+' || substr(v, 3);
  end if;
  if v ~ '^0[1-9][0-9]{8}$' then
    v := case
      when v ~ '^0(590|690|691)' then '+590' || substr(v, 2)   -- Guadeloupe, Saint-Martin, Saint-Barthélemy
      when v ~ '^0(596|696|697)' then '+596' || substr(v, 2)   -- Martinique
      when v ~ '^0(594|694)' then '+594' || substr(v, 2)       -- Guyane
      when v ~ '^0(262|692|693|269|639)' then '+262' || substr(v, 2)  -- La Réunion, Mayotte
      else '+33' || substr(v, 2) end;
  end if;
  if v !~ '^\+[1-9][0-9]{6,14}$' then
    return null;
  end if;
  return v;
end $_$;


--
-- Name: noter_capacite(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_capacite(p_branchement uuid, p_domaine text, p_capacite jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b public.branchements;
  v jsonb;
begin
  select * into b from public.branchements where id = p_branchement for update;
  if not found then
    raise exception 'Branchement introuvable.' using errcode = 'P0002';
  end if;
  perform private.exiger_gestion_releve(b.client_id, b.entite_id);
  if p_capacite is null or jsonb_typeof(p_capacite) <> 'object' then
    raise exception 'Une capacité se note en objet : lecture, action, tenue, mesure, note.' using errcode = '22023';
  end if;
  v := coalesce(b.capacites -> p_domaine, '{}'::jsonb) || p_capacite;
  if p_capacite ? 'tenue' and not (p_capacite ? 'mesure_le') then
    v := v || jsonb_build_object('mesure_le', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  end if;
  update public.branchements set capacites = capacites || jsonb_build_object(p_domaine, v), maj_le = now()
   where id = b.id;
  return v;
end $$;


--
-- Name: noter_consentement(uuid, text, text, text, text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_consentement(p_client uuid, p_canal text, p_adresse text, p_source text, p_portee text DEFAULT 'transactionnel'::text, p_preuve text DEFAULT NULL::text, p_piece uuid DEFAULT NULL::uuid, p_module text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_adresse text := private.normaliser_adresse(p_canal, p_adresse);
  v_uid uuid;
  v_id uuid;
begin
  if p_canal is null or p_canal not in ('email', 'whatsapp', 'sms', 'lre', 'appel') then
    raise exception 'Canal inconnu : %.', coalesce(p_canal, 'vide') using errcode = '22023';
  end if;
  if v_adresse is null then
    raise exception 'Adresse invalide pour le canal %.', p_canal using errcode = '22023';
  end if;
  v_uid := private.exiger_reglage_destinataire(p_client, v_adresse);
  if p_portee is null or p_portee not in ('transactionnel', 'tout') then
    raise exception 'Portée inconnue : transactionnel ou tout.' using errcode = '22023';
  end if;
  if p_source is null or p_source not in ('formulaire', 'ecrit', 'oral', 'contrat', 'message', 'import') then
    raise exception 'Source inconnue : formulaire, ecrit, oral, contrat, message ou import.' using errcode = '22023';
  end if;
  if p_source in ('oral', 'import') and nullif(btrim(p_preuve), '') is null and p_piece is null then
    raise exception 'Un accord oral ou importé dit sa preuve : qui l''a recueilli, quand, comment.' using errcode = '22023';
  end if;
  select k.id into v_id from public.consentements k
  where k.client_id = p_client and k.canal = p_canal and k.adresse = v_adresse and k.portee = p_portee and k.retire_le is null;
  if v_id is null then
    insert into public.consentements (client_id, canal, adresse, adresse_empreinte, portee, source, preuve, piece_id, module, recueilli_par)
    values (p_client, p_canal, v_adresse, private.empreinte_adresse(p_client, v_adresse), p_portee, p_source,
            left(p_preuve, 300), p_piece, p_module, v_uid)
    returning id into v_id;
  end if;
  -- Un nouvel accord de la personne lève sa désinscription de ce canal (pas un import).
  if p_source <> 'import' then
    update public.oppositions
       set levee_le = now(), levee_par = v_uid, motif_levee = 'Nouvel accord du destinataire.'
     where client_id = p_client and adresse = v_adresse and type = 'desinscription' and canal = p_canal and levee_le is null;
  end if;
  return v_id;
end $$;


--
-- Name: noter_evenement_suivi(public.suivis, text, date, uuid, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_evenement_suivi(p_s public.suivis, p_type text, p_date date DEFAULT NULL::date, p_envoi uuid DEFAULT NULL::uuid, p_detail jsonb DEFAULT '{}'::jsonb, p_par uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.suivis_evenements (client_id, suivi_id, type, date_promise, envoi_id, detail, par)
  values (p_s.client_id, p_s.id, p_type, p_date, p_envoi, coalesce(p_detail, '{}'::jsonb), p_par);
end $$;


--
-- Name: noter_opposition(uuid, text, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_opposition(p_client uuid, p_type text, p_adresse text DEFAULT NULL::text, p_canal text DEFAULT NULL::text, p_ref text DEFAULT NULL::text, p_jusqu_au timestamp with time zone DEFAULT NULL::timestamp with time zone, p_motif text DEFAULT NULL::text, p_source text DEFAULT 'demande'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid;
  v_adresse text;
begin
  v_adresse := case when p_adresse is null then null
                    when p_canal is not null then private.normaliser_adresse(p_canal, p_adresse)
                    when p_adresse like '%@%' then private.normaliser_email(p_adresse)
                    else private.normaliser_telephone(p_adresse) end;
  v_uid := private.exiger_reglage_destinataire(p_client, v_adresse);
  if p_source is null or p_source not in ('message', 'demande', 'client', 'rebond', 'plainte', 'systeme') then
    raise exception 'Source inconnue : message, demande, client, rebond, plainte ou systeme.' using errcode = '22023';
  end if;
  return private.opposer(p_client, p_type, p_adresse, p_canal, p_ref, p_jusqu_au, p_motif, p_source, v_uid);
end $$;


--
-- Name: noter_promesse(uuid, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_promesse(p_suivi uuid, p_date date, p_source text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s public.suivis;
  v_uid uuid := (select auth.uid());
  v_type text;
  v_precedente date;
begin
  s := private.charger_suivi(p_suivi);
  if s.statut <> 'ouvert' then
    raise exception 'Ce suivi est clos (%).', s.statut using errcode = '55000';
  end if;
  v_precedente := s.date_promise;
  if p_date is null then
    raise exception 'Une promesse porte une date.' using errcode = '22023';
  end if;
  if p_date < (s.depuis at time zone 'UTC')::date - 1 then
    raise exception 'La date promise ne précède pas le début du suivi.' using errcode = '22023';
  end if;
  if s.date_promise is null then
    v_type := 'promesse';
    update public.suivis set date_promise = p_date, date_promise_initiale = p_date, dernier_signe_le = now() where id = s.id
    returning * into s;
  elsif p_date = s.date_promise then
    return;   -- la même date redite n'est pas un glissement
  else
    v_type := 'glissement';
    update public.suivis set date_promise = p_date, glissements = glissements + 1, dernier_signe_le = now() where id = s.id
    returning * into s;
  end if;
  -- La relance suivante attend la nouvelle date, mais un plan épuisé le reste.
  update public.suivis set prochaine_relance_le = case when prochaine_relance_le is null then null
    else private.prochaine_relance(s, coalesce(s.derniere_relance_le, s.depuis)) end where id = s.id;
  perform private.noter_evenement_suivi(s, v_type, p_date, null,
    jsonb_build_object('source', left(p_source, 200), 'glissements', s.glissements,
                       'precedente', case when v_type = 'glissement' then v_precedente end), v_uid);
end $$;


--
-- Name: noter_remise(text, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_remise(p_fournisseur text, p_reference text, p_evenement text, p_detail jsonb DEFAULT '{}'::jsonb, p_survenu_le timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  e public.envois;
begin
  perform private.exiger_ouvrier();
  if p_evenement is null or p_evenement not in ('remis', 'rebond_temporaire', 'rebond', 'plainte', 'refuse') then
    raise exception 'Événement de remise inconnu : remis, rebond_temporaire, rebond, plainte ou refuse.' using errcode = '22023';
  end if;
  select * into e from public.envois x
  where x.fournisseur = p_fournisseur and x.reference_externe = p_reference
  order by x.cree_le desc limit 1;
  if e.id is null then
    return false;
  end if;
  -- Le détail du fournisseur, sans contenu : un code et une raison courte.
  insert into public.envois_evenements (client_id, envoi_id, type, survenu_le, detail)
  values (e.client_id, e.id, p_evenement, coalesce(p_survenu_le, now()),
          jsonb_strip_nulls(jsonb_build_object('code', left(p_detail ->> 'code', 100), 'raison', left(p_detail ->> 'raison', 300))));
  update public.envois set remise = p_evenement, remise_le = coalesce(p_survenu_le, now())
   where id = e.id and (remise is null or private.rang_remise(p_evenement) >= private.rang_remise(remise));
  if p_evenement in ('rebond', 'plainte', 'refuse') then
    perform private.publier_envoi(e, 'non_remis');
  end if;
  if e.mode = 'reel' and p_evenement in ('rebond', 'plainte') then
    perform private.opposer(e.client_id, case p_evenement when 'rebond' then 'invalide' else 'desinscription' end,
      e.destinataire_adresse, e.canal, null, null,
      case p_evenement when 'rebond' then 'Rebond définitif signalé par le fournisseur.'
                       else 'Le destinataire a signalé le message comme indésirable.' end,
      case p_evenement when 'rebond' then 'rebond' else 'plainte' end, null);
  end if;
  return true;
end $$;


--
-- Name: noter_signe(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.noter_signe(p_suivi uuid, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s public.suivis;
  v_uid uuid := (select auth.uid());
begin
  s := private.charger_suivi(p_suivi);
  if s.statut <> 'ouvert' then
    raise exception 'Ce suivi est clos (%).', s.statut using errcode = '55000';
  end if;
  update public.suivis set dernier_signe_le = now(),
    prochaine_relance_le = case when prochaine_relance_le is null then null else private.prochaine_relance(s, now()) end
  where id = s.id returning * into s;
  perform private.noter_evenement_suivi(s, 'signe', null, null, jsonb_build_object('detail', left(p_detail, 300)), v_uid);
end $$;


--
-- Name: notifier_delai(uuid, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notifier_delai(p_delai uuid, p_echeance date, p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  d public.delais;
  v_aujourdhui date;
begin
  select * into d from public.delais where id = p_delai for update;
  if not found then
    raise exception 'Délai introuvable.' using errcode = 'P0002';
  end if;
  perform private.exiger_ecriture_delai(d.client_id, d.objet_type, d.objet_id);
  perform private.exiger_porte_du_module(d.module);
  if p_echeance is null or nullif(btrim(p_source), '') is null then
    raise exception 'La date notifiée et sa source sont nécessaires.' using errcode = '22023';
  end if;
  if d.statut in ('tenu', 'annule') then
    raise exception 'Ce délai est clos.' using errcode = '55000';
  end if;
  select (now() at time zone t.fuseau)::date into v_aujourdhui from public.territoires t where t.code = d.territoire;
  update public.delais
     set echeance_notifiee = p_echeance, source_notification = p_source, rappels_faits = '{}',
         statut = case when p_echeance >= v_aujourdhui then 'ouvert' else statut end, maj_le = now()
   where id = p_delai;
end $$;


--
-- Name: opposer(uuid, text, text, text, text, timestamp with time zone, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.opposer(p_client uuid, p_type text, p_adresse text, p_canal text, p_ref text, p_jusqu_au timestamp with time zone, p_motif text, p_source text, p_par uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_adresse text;
  v_id uuid;
  v_code text := case p_type when 'invalide' then 'ADRESSE_INVALIDE' when 'desinscription' then 'DESINSCRIT' else 'PAUSE' end;
  r record;
begin
  if p_type is null or p_type not in ('desinscription', 'pause', 'invalide') then
    raise exception 'Opposition inconnue : desinscription, pause ou invalide.' using errcode = '22023';
  end if;
  if p_canal is not null and p_canal not in ('email', 'whatsapp', 'sms', 'lre', 'appel') then
    raise exception 'Canal inconnu : %.', p_canal using errcode = '22023';
  end if;
  if p_adresse is not null then
    v_adresse := case when p_canal is not null then private.normaliser_adresse(p_canal, p_adresse)
                      when p_adresse like '%@%' then private.normaliser_email(p_adresse)
                      else private.normaliser_telephone(p_adresse) end;
    if v_adresse is null then
      raise exception 'Adresse invalide.' using errcode = '22023';
    end if;
  elsif nullif(btrim(p_ref), '') is null then
    raise exception 'Une opposition vise une adresse ou une référence.' using errcode = '22023';
  end if;
  if p_type = 'pause' and (p_jusqu_au is null or p_jusqu_au <= now()) then
    raise exception 'Une pause court jusqu''à une date future.' using errcode = '22023';
  end if;

  select o.id into v_id from public.oppositions o
  where o.client_id = p_client and o.type = p_type and o.levee_le is null
    and o.adresse is not distinct from v_adresse and o.ref is not distinct from nullif(btrim(p_ref), '')
    and o.canal is not distinct from p_canal
    and (p_type <> 'pause' or o.jusqu_au > now())
  limit 1;
  if v_id is not null then
    if p_type = 'pause' then
      update public.oppositions set jusqu_au = greatest(jusqu_au, p_jusqu_au) where id = v_id;
    end if;
  else
    insert into public.oppositions (client_id, type, canal, adresse, adresse_empreinte, ref, jusqu_au, motif, source, cree_par)
    values (p_client, p_type, p_canal, v_adresse, private.empreinte_adresse(p_client, v_adresse), nullif(btrim(p_ref), ''),
            case when p_type = 'pause' then p_jusqu_au end, left(p_motif, 300), p_source, p_par)
    returning id into v_id;
  end if;

  for r in
    select e.id from public.envois e
    where e.client_id = p_client and e.statut in ('a_valider', 'differe', 'pret')
      and ((v_adresse is not null and e.destinataire_adresse = v_adresse)
           or (nullif(btrim(p_ref), '') is not null and e.destinataire_ref = btrim(p_ref)))
      and (p_canal is null or e.canal = p_canal)
      and not (p_type = 'desinscription' and e.canal = 'lre')
  loop
    perform private.clore_envoi(r.id, 'bloque', v_code, case p_type
      when 'invalide' then 'Cette adresse ne reçoit pas les messages (rebond, numéro erroné).'
      when 'desinscription' then 'Cette personne a demandé à ne plus recevoir de messages.'
      else 'Cette personne est en pause : une réponse attend d''être traitée.' end);
  end loop;
  return v_id;
end $$;


--
-- Name: ouvert_a(jsonb, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ouvert_a(p_plages jsonb, p_fuseau text, p_territoire text, p_feries boolean, p_instant timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if not private.dans_plages(p_plages, p_instant at time zone p_fuseau) then
    return false;
  end if;
  if p_feries or p_territoire is null then
    return true;
  end if;
  return not public.jour_ferie((p_instant at time zone p_fuseau)::date, p_territoire);
end $$;


--
-- Name: ouvrir_suivi(uuid, text, text, text, jsonb, text, timestamp with time zone, jsonb, timestamp with time zone, text, text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ouvrir_suivi(p_client uuid, p_module text, p_objet_type text, p_objet_id text, p_tiers jsonb, p_attendu text, p_depuis timestamp with time zone DEFAULT now(), p_plan jsonb DEFAULT '{}'::jsonb, p_echeance timestamp with time zone DEFAULT NULL::timestamp with time zone, p_nature text DEFAULT 'reponse'::text, p_type_piece text DEFAULT NULL::text, p_territoire text DEFAULT NULL::text, p_entite uuid DEFAULT NULL::uuid, p_cle text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid;
  v_id uuid;
  v_plan jsonb;
  v_dest jsonb;
  v_territoire text;
  s public.suivis;
begin
  v_uid := private.exiger_acteur_suivi(p_client, p_entite, p_objet_type, p_objet_id);
  if p_module is null or p_module !~ '^[a-z][a-z_]{1,29}$' then
    raise exception 'Module inconnu : %.', coalesce(p_module, 'vide') using errcode = '22023';
  end if;
  if p_objet_type is null or p_objet_id is null then
    raise exception 'Un suivi porte sur un objet : type et identifiant.' using errcode = '22023';
  end if;
  if nullif(btrim(p_attendu), '') is null then
    raise exception 'Un suivi dit ce qu''on attend.' using errcode = '22023';
  end if;
  if p_nature is null or p_nature not in ('piece', 'reponse', 'paiement', 'livraison', 'signature', 'autre') then
    raise exception 'Nature inconnue : piece, reponse, paiement, livraison, signature ou autre.' using errcode = '22023';
  end if;
  if p_type_piece is not null and p_nature <> 'piece' then
    raise exception 'Un type de pièce ne vaut que pour une pièce attendue.' using errcode = '22023';
  end if;
  if p_depuis is null or p_depuis > now() + interval '1 day' then
    raise exception 'Le suivi commence à une date passée ou d''aujourd''hui.' using errcode = '22023';
  end if;
  if p_echeance is not null and p_echeance <= now() then
    raise exception 'L''échéance d''un suivi est dans le futur.' using errcode = '22023';
  end if;
  if p_cle is not null then
    select x.id into v_id from public.suivis x where x.client_id = p_client and x.module = p_module and x.cle_idempotence = p_cle;
    if found then
      return v_id;
    end if;
  end if;
  v_plan := private.plan_de_relance(p_plan, p_module);
  -- Le tiers est un destinataire de B4 : vérifié maintenant, pour ne pas découvrir à la relance qu'il est injoignable.
  v_dest := private.resoudre_destinataire(p_client, v_plan ->> 'canal', p_tiers, p_entite);
  v_territoire := coalesce(p_territoire, v_dest ->> 'territoire');
  if v_territoire is not null and not exists (select 1 from public.territoires t where t.code = v_territoire) then
    raise exception 'Territoire inconnu : %.', v_territoire using errcode = '22023';
  end if;

  insert into public.suivis (client_id, entite_id, module, objet_type, objet_id, attendu, nature, type_piece, tiers, tiers_nom,
                             tiers_ref, depuis, echeance, territoire, plan, ouvert_par, cle_idempotence)
  values (p_client, p_entite, p_module, p_objet_type, p_objet_id, btrim(p_attendu), p_nature, p_type_piece,
          p_tiers || jsonb_build_object('fuseau', v_dest ->> 'fuseau'), v_dest ->> 'nom', v_dest ->> 'ref', p_depuis, p_echeance,
          v_territoire, v_plan, v_uid, p_cle)
  returning * into s;
  update public.suivis set prochaine_relance_le = private.prochaine_relance(s, s.depuis) where id = s.id returning * into s;
  perform private.noter_evenement_suivi(s, 'ouverture', null, null,
    jsonb_build_object('nature', s.nature, 'plan', jsonb_build_object('cadence', v_plan ->> 'cadence', 'max', v_plan ->> 'max',
                                                                     'canal', v_plan ->> 'canal')), v_uid);
  return s.id;
end $_$;


--
-- Name: paques(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.paques(p_annee integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  a int := p_annee % 19; b int := p_annee / 100; c int := p_annee % 100; d int := b / 4; e int := b % 4;
  f int := (b + 8) / 25; g int := (b - f + 1) / 3; h int := (19 * a + b - d - g + 15) % 30;
  i int := c / 4; k int := c % 4; l int := (32 + 2 * e + 2 * i - h - k) % 7; m int := (a + 11 * h + 22 * l) / 451;
begin
  return make_date(p_annee, (h + l - 7 * m + 114) / 31, ((h + l - 7 * m + 114) % 31) + 1);
end $$;


--
-- Name: perimetre_couvre(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perimetre_couvre(p_user uuid, p_client uuid, p_entite uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client
      and (p_entite is null or c.perimetre_total or exists (select 1 from public.comptes_entites ce
        where ce.user_id = p_user and ce.client_id = p_client and ce.entite_id = p_entite)))
$$;


--
-- Name: phrase_garde(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.phrase_garde(g jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select left(case g ->> 'raison'
    when 'vide' then format('export vide, alors que l''état comptait %s lignes', g ->> 'lignes_base')
    when 'colonnes' then 'colonnes absentes : '
      || (select string_agg(c, ', ') from jsonb_array_elements_text(g -> 'colonnes_absentes') c)
    when 'perte' then format('%s lignes au lieu de %s, %s %% de moins (seuil : %s %%)', g ->> 'lignes', g ->> 'lignes_base',
      round(100.0 * (g ->> 'perte')::numeric / nullif((g ->> 'lignes_base')::numeric, 0)),
      round(100 * (g ->> 'seuil_perte')::numeric))
    when 'disparitions' then format('%s lignes sur %s ont disparu (seuil : %s %%)', g ->> 'absents', g ->> 'lignes_base',
      round(100 * (g ->> 'seuil_perte')::numeric))
    when 'anomalies' then format('%s lignes sur %s ont une valeur illisible (seuil : %s %%)', g ->> 'anomalies', g ->> 'lignes',
      round(100 * (g ->> 'seuil_anomalies')::numeric))
    when 'module' then format('refusé par %s : %s', upper(g ->> 'source'), g ->> 'detail')
    else 'relevé douteux' end, 500)
$$;


--
-- Name: plan_de_relance(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.plan_de_relance(p_plan jsonb, p_module text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  p jsonb := coalesce(p_plan, '{}'::jsonb);
  v_cle text;
  v_cadence interval;
  v_premiere interval;
  v_max integer;
  v_canal text;
begin
  if jsonb_typeof(p) <> 'object' then
    raise exception 'Le plan de relance est un objet JSON.' using errcode = '22023';
  end if;
  for v_cle in select jsonb_object_keys(p) loop
    if v_cle not in ('cadence', 'premiere', 'max', 'canal', 'gabarit', 'variables', 'transactionnel', 'jours_ouvres') then
      raise exception 'Clé inconnue dans le plan de relance : « % ».', v_cle using errcode = '22023';
    end if;
  end loop;
  begin
    v_cadence := coalesce((p ->> 'cadence')::interval, interval '3 days');
    v_premiere := coalesce((p ->> 'premiere')::interval, v_cadence);
  exception when others then
    raise exception 'La cadence et la première relance sont des durées : « 3 days », « 1 week »…' using errcode = '22023';
  end;
  if v_cadence < interval '1 day' or v_cadence > interval '90 days' or v_premiere < interval '0' or v_premiere > interval '180 days' then
    raise exception 'La cadence va d''un jour à quatre-vingt-dix jours ; la première relance, de zéro à cent quatre-vingts jours.'
      using errcode = '22023';
  end if;
  v_max := coalesce((p ->> 'max')::integer, 3);
  if v_max < 0 or v_max > 20 then
    raise exception 'Le nombre de relances va de 0 à 20.' using errcode = '22023';
  end if;
  v_canal := coalesce(p ->> 'canal', 'email');
  if v_canal not in ('email', 'whatsapp', 'sms', 'lre', 'appel') then
    raise exception 'Canal de relance inconnu : %.', v_canal using errcode = '22023';
  end if;
  if p ? 'gabarit' then
    if (p ->> 'gabarit') !~ ('^' || p_module || '\.[a-z0-9_.]+$') then
      raise exception 'Le gabarit de relance porte le préfixe du module : « %.… ».', p_module using errcode = '22023';
    end if;
  end if;
  if p ? 'variables' and jsonb_typeof(p -> 'variables') <> 'object' then
    raise exception 'Les variables du gabarit forment un objet JSON.' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'cadence', v_cadence::text, 'premiere', v_premiere::text, 'max', v_max, 'canal', v_canal,
    'gabarit', p ->> 'gabarit', 'variables', coalesce(p -> 'variables', '{}'::jsonb),
    'transactionnel', coalesce((p ->> 'transactionnel')::boolean, true),
    'jours_ouvres', coalesce((p ->> 'jours_ouvres')::boolean, true));
end $_$;


--
-- Name: point_adressee(uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_adressee(p_user uuid, p_client uuid, p_destinataire uuid, p_role text, p_equipe uuid, p_entite uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (p_destinataire = p_user
     or (p_role is not null and exists (select 1 from public.comptes c
                                        where c.client_id = p_client and c.user_id = p_user and c.role = p_role))
     or (p_equipe is not null and private.dans_equipe(p_user, p_equipe)))
    and private.perimetre_couvre(p_user, p_client, p_entite), false)
$$;


--
-- Name: point_assembler(uuid, uuid, date, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_assembler(p_client uuid, p_user uuid, p_jour date, p_maintenant timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_prevu timestamptz;
  v_sections jsonb;
  v_motifs jsonb;
  v_nb_sections integer;
  v_nb_items integer;
  v_nb_critiques integer;
  v_statut text;
  v_id uuid;
begin
  v_prevu := private.point_du(p_client, p_user, p_jour);
  if v_prevu is null then
    return null;
  end if;
  select * into r from private.point_reglage(p_client, p_user);
  v_sections := private.point_composer(p_client, p_user, p_jour);
  v_motifs := private.point_motifs(p_client, p_user, p_jour, p_maintenant);
  select count(*), coalesce(sum(jsonb_array_length(x -> 'lignes')), 0),
         coalesce(sum((select count(*) from jsonb_array_elements(x -> 'lignes') y where y ->> 'gravite' = 'critique')), 0)
    into v_nb_sections, v_nb_items, v_nb_critiques
  from jsonb_array_elements(v_sections) x;
  v_statut := case when v_nb_sections = 0 and jsonb_array_length(v_motifs) = 0 and r.si_vide = 'rien'
                   then 'vide' else 'pret' end;

  insert into public.points_du_jour (client_id, user_id, jour, territoire, fuseau, heure, prevu_le, du_le, assemble_le,
                                     statut, canal, contenu, incomplet, motifs, nb_sections, nb_items, nb_critiques,
                                     empreinte)
  values (p_client, p_user, p_jour, r.territoire, r.fuseau, r.heure, v_prevu,
          private.point_devenu_du(v_prevu, r.horaire_depuis, p_maintenant), p_maintenant, v_statut,
          r.canal, r.contenu, jsonb_array_length(v_motifs) > 0, v_motifs, v_nb_sections, v_nb_items, v_nb_critiques,
          encode(sha256(convert_to(jsonb_build_object('sections', v_sections, 'motifs', v_motifs)::text, 'UTF8')), 'hex'))
  on conflict (client_id, user_id, jour) do nothing
  returning id into v_id;
  if v_id is null then
    return null;
  end if;

  insert into public.points_du_jour_lignes (client_id, point_id, section_rang, rang, section_id, module, entite_id,
                                            entite_nom, titre, sante, section_incomplete, donnees_du, texte, lien, gravite,
                                            objet_type, objet_id, gabarit, gabarit_version, valeurs)
  select p_client, v_id, s.n, coalesce((l.v ->> 'rang')::smallint, 0), (s.v ->> 'section_id')::uuid, s.v ->> 'module',
         (s.v ->> 'entite_id')::uuid, s.v ->> 'entite_nom', s.v ->> 'titre', (s.v ->> 'sante')::boolean,
         (s.v ->> 'incomplete')::boolean, (s.v ->> 'donnees_du')::timestamptz,
         l.v ->> 'texte', l.v ->> 'lien', l.v ->> 'gravite', l.v ->> 'objet_type', l.v ->> 'objet_id',
         l.v ->> 'gabarit', (l.v ->> 'gabarit_version')::smallint, nullif(l.v -> 'valeurs', 'null'::jsonb)
  from jsonb_array_elements(v_sections) with ordinality as s(v, n)
  left join lateral jsonb_array_elements(s.v -> 'lignes') as l(v) on true;
  return v_id;
end $$;


--
-- Name: point_b4_present(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_b4_present() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'preparer_envoi'
      and p.proargnames @> array['p_client', 'p_module', 'p_objet_type', 'p_objet_id', 'p_canal', 'p_destinataire',
                                 'p_sujet', 'p_corps', 'p_cle_idempotence', 'p_transactionnel', 'p_donnees_sante',
                                 'p_echeance'])
$$;


--
-- Name: point_composer(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_composer(p_client uuid, p_user uuid, p_jour date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with horizon as (
    select coalesce((select r.delais_horizon from private.point_reglage(p_client, p_user) r), 7) as jours
  ), sections as (
    select s.*, en.nom as entite_nom
    from public.points_sections s
    left join public.entites en on en.client_id = s.client_id and en.id = s.entite_id
    where s.client_id = p_client and s.jour = p_jour
      and private.point_adressee(p_user, p_client, s.destinataire, s.role, s.equipe_id, s.entite_id)
  ), lignes as (
    select i.section_id,
           jsonb_agg(jsonb_build_object(
             'rang', i.rang, 'texte', i.texte, 'lien', i.lien, 'gravite', i.gravite,
             'objet_type', i.objet_type, 'objet_id', i.objet_id, 'gabarit', i.gabarit,
             'gabarit_version', i.gabarit_version, 'valeurs', i.valeurs) order by i.rang) as lignes
    from public.points_items i
    join sections s on s.id = i.section_id
    where i.objet_type is null or private.voit_objet_pour(p_user, p_client, i.objet_type, i.objet_id)
    group by i.section_id
  ), deposees as (
    select s.ordre, s.module, s.entite_nom, s.titre,
           jsonb_build_object(
             'section_id', s.id, 'module', s.module, 'entite_id', s.entite_id, 'entite_nom', s.entite_nom,
             'titre', s.titre, 'sante', s.sante, 'incomplete', s.incomplete, 'donnees_du', s.donnees_du,
             'ordre', s.ordre, 'lignes', coalesce(l.lignes, '[]'::jsonb)) as section
    from sections s
    left join lignes l on l.section_id = s.id
    where s.nb_items = 0 or l.lignes is not null
  ), delais as (
    select d.id, d.module, d.echeance, d.objet_type, d.objet_id,
           row_number() over (partition by d.module order by d.echeance, d.cree_le, d.id) as rang,
           case when exists (select 1 from private.objets_chiffres oc where oc.objet_type = d.objet_type)
                then private.point_rendre_gabarit(case when d.echeance < p_jour then 'point_du_matin.delai_depasse'
                                                       else 'point_du_matin.delai_proche' end,
                                                  1, jsonb_build_object('jour', d.echeance))
                else left(regexp_replace(
                       d.libelle || ' : '
                       || case when d.echeance < p_jour then 'dépassé depuis le ' || private.point_date_fr(d.echeance, false)
                               when d.echeance = p_jour then 'échéance aujourd''hui'
                               else 'échéance le ' || private.point_date_fr(d.echeance, false) end
                       || coalesce('. ' || d.action_attendue, ''), '[[:cntrl:]]', ' ', 'g'), 300) end as texte,
           case when d.echeance <= p_jour then 'critique'
                when d.echeance <= p_jour + 2 then 'attention'
                else 'info' end as gravite
    from public.delais d, horizon h
    where d.client_id = p_client and d.statut in ('ouvert', 'depasse') and h.jours > 0
      and d.echeance <= p_jour + h.jours
      and (d.responsable = p_user
           or (d.responsable is null and exists (select 1 from public.comptes c
                                                 where c.client_id = p_client and c.user_id = p_user and c.role = 'gerant')))
      and private.voit_objet_pour(p_user, p_client, d.objet_type, d.objet_id)
  ), delais_sections as (
    select 5::smallint as ordre, d.module, null::text as entite_nom, 'Délais à tenir'::text as titre,
           jsonb_build_object(
             'section_id', null, 'module', d.module, 'entite_id', null, 'entite_nom', null,
             'titre', 'Délais à tenir', 'sante', private.point_module_sante(d.module), 'incomplete', false,
             'donnees_du', null, 'ordre', 5,
             'lignes', jsonb_agg(jsonb_build_object(
               'rang', d.rang, 'texte', d.texte, 'lien', '/delais/' || d.id, 'gravite', d.gravite,
               'objet_type', d.objet_type, 'objet_id', d.objet_id,
               'gabarit', case when d.echeance < p_jour then 'point_du_matin.delai_depasse'
                               else 'point_du_matin.delai_proche' end,
               'gabarit_version', 1, 'valeurs', jsonb_build_object('jour', d.echeance)) order by d.rang)) as section
    from delais d
    group by d.module
  )
  select coalesce(jsonb_agg(u.section order by u.ordre, u.module, u.entite_nom nulls first, u.titre), '[]'::jsonb)
  from (select * from deposees union all select * from delais_sections) u
$$;


--
-- Name: point_date_fr(date, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_date_fr(p date, p_annee boolean DEFAULT true) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (array['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'])[extract(isodow from p)::int]
         || ' ' || extract(day from p)::int || case when extract(day from p)::int = 1 then 'er' else '' end
         || ' ' || (array['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre',
                          'octobre', 'novembre', 'décembre'])[extract(month from p)::int]
         || case when p_annee then ' ' || extract(year from p)::int else '' end
$$;


--
-- Name: point_de_mois_fr(date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_de_mois_fr(p date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when extract(month from p)::int in (4, 8, 10) then 'd''' else 'de ' end || private.point_mois_fr(p)
$$;


--
-- Name: point_devenu_du(timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_devenu_du(p_prevu timestamp with time zone, p_depuis timestamp with time zone, p_maintenant timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_depuis > p_prevu and p_depuis <= p_maintenant then p_depuis else p_prevu end
$$;


--
-- Name: point_du(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_du(p_client uuid, p_user uuid, p_jour date) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
begin
  if p_jour is null then
    return null;
  end if;
  select * into r from private.point_reglage(p_client, p_user);
  if not found or not r.pose or not r.actif or r.territoire is null then
    return null;
  end if;
  if not (extract(isodow from p_jour)::smallint = any (r.jours)) then
    return null;
  end if;
  if r.sauf_feries and r.complet and public.jour_ferie(p_jour, r.territoire) then
    return null;
  end if;
  return (p_jour + r.heure) at time zone r.fuseau;
end $$;


--
-- Name: point_en_json(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_en_json(p_point uuid, p_lecteur uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', p.id, 'jour', p.jour, 'statut', p.statut, 'heure', substr(p.heure::text, 1, 5), 'fuseau', p.fuseau,
    'territoire', p.territoire, 'prevu_le', p.prevu_le, 'du_le', coalesce(p.du_le, p.prevu_le),
    'assemble_le', p.assemble_le, 'incomplet', p.incomplet,
    'motifs', p.motifs, 'canal', p.canal, 'contenu', p.contenu, 'ouvert_le', p.ouvert_le, 'envoi_id', p.envoi_id,
    'version', p.version, 'expurge_le', p.expurge_le,
    'sections', coalesce((
      select jsonb_agg(jsonb_build_object(
               'rang', sec.section_rang, 'module', sec.module, 'nom_module', private.point_nom_module(sec.module),
               'entite_id', sec.entite_id, 'entite_nom', sec.entite_nom, 'titre', sec.titre, 'sante', sec.sante,
               'incomplete', sec.incomplete, 'donnees_du', sec.donnees_du, 'lignes', sec.lignes)
             order by sec.section_rang)
      from (
        select l.section_rang, (array_agg(l.module))[1] as module, (array_agg(l.entite_id))[1] as entite_id,
               (array_agg(l.entite_nom))[1] as entite_nom, (array_agg(l.titre))[1] as titre, bool_or(l.sante) as sante,
               bool_or(l.section_incomplete) as incomplete, max(l.donnees_du) as donnees_du,
               coalesce(jsonb_agg(jsonb_build_object('rang', l.rang, 'texte', l.texte, 'lien', l.lien,
                                                     'gravite', l.gravite, 'objet_type', l.objet_type,
                                                     'objet_id', l.objet_id) order by l.rang)
                          filter (where l.rang > 0), '[]'::jsonb) as lignes
        from public.points_du_jour_lignes l
        where l.point_id = p.id
          and (p_lecteur is null or l.objet_type is null
               or private.voit_objet_pour(p_lecteur, p.client_id, l.objet_type, l.objet_id))
        group by l.section_rang) sec), '[]'::jsonb))
  from public.points_du_jour p
  where p.id = p_point
$$;


--
-- Name: point_gabarit_valide(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_gabarit_valide(p_texte text, p_champs jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_cle text;
  v_type text;
  v_m text[];
  v_utilises text[] := '{}';
begin
  if p_texte is null or p_champs is null or jsonb_typeof(p_champs) <> 'object' then
    return false;
  end if;
  for v_cle, v_type in select e.key, e.value #>> '{}' from jsonb_each(p_champs) e loop
    if v_cle !~ '^[a-z][a-z0-9_]{0,30}$' or jsonb_typeof(p_champs -> v_cle) <> 'string'
       or v_type not in ('entier', 'nombre', 'montant', 'pourcentage', 'heure', 'date') then
      return false;
    end if;
  end loop;
  for v_m in select regexp_matches(p_texte, '\{([a-z][a-z0-9_]{0,30})(\|[^|{}]*\|[^|{}]*)?\}', 'g') loop
    if not (p_champs ? v_m[1]) or (v_m[2] is not null and (p_champs ->> v_m[1]) not in ('entier', 'nombre')) then
      return false;
    end if;
    v_utilises := v_utilises || v_m[1];
  end loop;
  if regexp_replace(p_texte, '\{([a-z][a-z0-9_]{0,30})(\|[^|{}]*\|[^|{}]*)?\}', '', 'g') ~ '[{}|]' then
    return false;
  end if;
  return not exists (select 1 from jsonb_object_keys(p_champs) k where not (k = any (v_utilises)));
end $_$;


--
-- Name: point_garder_reglage(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_garder_reglage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if tg_op = 'UPDATE' and (new.client_id, new.user_id) is distinct from (old.client_id, old.user_id) then
    raise exception 'Un réglage ne change pas de titulaire.' using errcode = '42501';
  end if;
  -- Le retrait d'un réglage voisin déplace l'horaire (point_horaire_retire) :
  -- seul l'instant bouge, ni l'auteur ni le reste.
  if tg_op = 'UPDATE' and current_setting('omega.point_horaire', true) = 'retrait'
     and (to_jsonb(new) - 'horaire_depuis') = (to_jsonb(old) - 'horaire_depuis') then
    return new;
  end if;
  new.maj_le := now();
  new.maj_par := v_uid;
  if tg_op = 'INSERT'
     or (new.actif, new.heure, new.territoire, new.jours, new.sauf_feries)
        is distinct from (old.actif, old.heure, old.territoire, old.jours, old.sauf_feries) then
    new.horaire_depuis := now();
  else
    new.horaire_depuis := old.horaire_depuis;
  end if;
  if v_uid is not null
     and (new.conservation_jours is distinct from (case when tg_op = 'UPDATE' then old.conservation_jours end)
          or new.donnees_sante is distinct from (case when tg_op = 'UPDATE' then old.donnees_sante end))
     and not private.a_un_role(new.client_id, array['gerant']) then
    raise exception 'Seul le gérant règle la conservation du point et les données de santé.' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: point_heure_fr(time without time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_heure_fr(p time without time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select extract(hour from p)::int || chr(160) || 'h'
         || case when extract(minute from p)::int = 0 then ''
                 else chr(160) || lpad(extract(minute from p)::int::text, 2, '0') end
$$;


--
-- Name: point_horaire_retire(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_horaire_retire() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return null;
  end if;
  perform set_config('omega.point_horaire', 'retrait', true);
  update public.points_reglages r set horaire_depuis = now()
  where r.client_id = old.client_id
    and case when old.user_id is null then r.user_id is not null else r.user_id is null end;
  perform set_config('omega.point_horaire', '', true);
  return null;
end $$;


--
-- Name: point_instant_fr(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_instant_fr(p timestamp with time zone, p_fuseau text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select to_char(p at time zone p_fuseau, 'DD/MM') || ' à ' || private.point_heure_fr((p at time zone p_fuseau)::time)
$$;


--
-- Name: point_lien_valide(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_lien_valide(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select coalesce(char_length(p) between 1 and 500
                  and p ~ '^/[A-Za-z0-9._~%!$&''()*+,;=:@/?#-]*$'
                  and p !~ '^//' and p !~ '(^|/)\.\.(/|$|\?|#)', false)
$_$;


--
-- Name: point_marquer_expurge(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_marquer_expurge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('omega.effacement_objet', true), '') = 'oui' then
    update public.points_du_jour set expurge_le = now() where id = old.point_id and expurge_le is null;
  end if;
  return null;
end $$;


--
-- Name: point_mesurer_jour(uuid, date, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_mesurer_jour(p_client uuid, p_jour date, p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dus integer;
  v_a_l_heure integer;
  v_non_vides integer;
  v_ouverts integer;
  n integer := 0;
begin
  if exists (select 1 from public.mesures m
             where m.client_id = p_client and m.indicateur = 'point_du_matin.ponctualite' and m.version = 1
               and m.mode = 'reel' and m.periode_type = 'jour' and m.debut = p_jour
               and m.entite_id is null and m.objet_id is null) then
    return 0;
  end if;
  select count(*) into v_dus
  from (select co.user_id
        from public.comptes co
        cross join lateral private.point_reglage(co.client_id, co.user_id) r
        cross join lateral (select private.point_du(p_client, co.user_id, p_jour) as prevu) x
        where co.client_id = p_client and x.prevu is not null
          and private.point_devenu_du(x.prevu, r.horaire_depuis, p_maintenant) + interval '5 minutes'
              <= least(((p_jour + 1) + time '00:00') at time zone r.fuseau, p_maintenant)
        union
        select p.user_id from public.points_du_jour p where p.client_id = p_client and p.jour = p_jour) d;
  select count(*) filter (where p.assemble_le <= coalesce(p.du_le, p.prevu_le) + interval '5 minutes'),
         count(*) filter (where p.statut <> 'vide'),
         count(*) filter (where p.statut <> 'vide' and p.ouvert_le is not null
                                and (p.ouvert_le at time zone p.fuseau)::date = p_jour)
    into v_a_l_heure, v_non_vides, v_ouverts
  from public.points_du_jour p
  where p.client_id = p_client and p.jour = p_jour;
  if v_dus > 0 then
    perform private.enregistrer_mesure(p_client, 'point_du_matin.ponctualite', 1, 'jour', p_jour, null, v_dus, 'reel', v_a_l_heure);
    n := n + 1;
  end if;
  if v_non_vides > 0 then
    perform private.enregistrer_mesure(p_client, 'point_du_matin.ouverture', 1, 'jour', p_jour, null, v_non_vides, 'reel', v_ouverts);
    n := n + 1;
  end if;
  return n;
end $$;


--
-- Name: point_module_sante(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_module_sante(p_module text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_module in ('tiroma'), false)
$$;


--
-- Name: point_mois_fr(date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_mois_fr(p date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select (array['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre',
                'octobre', 'novembre', 'décembre'])[extract(month from p)::int] || ' ' || extract(year from p)::int
$$;


--
-- Name: point_motifs(uuid, uuid, date, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_motifs(p_client uuid, p_user uuid, p_jour date, p_maintenant timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with nourriciers as (
    select distinct s.module
    from public.points_sections s
    where s.client_id = p_client and s.jour between p_jour - 14 and p_jour
      and private.point_adressee(p_user, p_client, s.destinataire, s.role, s.equipe_id, s.entite_id)
  ), muets as (
    select n.module, min(b.dernier_le) as dernier_le
    from public.battements b
    join nourriciers n on b.module = n.module or b.module like n.module || '\_%'
    where b.client_id = p_client and b.actif
      and (exists (select 1 from public.alertes a
                   where a.client_id = p_client and a.cle_regroupement = 'battement:' || b.module
                     and a.acquittee_le is null)
           or (private.debut_plage_courante(b.plages, b.fuseau, p_maintenant) is not null
               and greatest(b.dernier_le, private.debut_plage_courante(b.plages, b.fuseau, p_maintenant))
                   + b.attendu_toutes * 1.5 < p_maintenant))
    group by n.module
  ), incompletes as (
    select s.module, max(s.donnees_du) as donnees_du
    from public.points_sections s
    where s.client_id = p_client and s.jour = p_jour and s.incomplete
      and private.point_adressee(p_user, p_client, s.destinataire, s.role, s.equipe_id, s.entite_id)
    group by s.module
  )
  select coalesce(jsonb_agg(x.motif order by x.module, x.raison), '[]'::jsonb)
  from (
    select m.module, 'module_muet' as raison,
           jsonb_build_object('raison', 'module_muet', 'module', m.module, 'depuis', m.dernier_le) as motif
    from muets m
    union all
    select i.module, 'section_incomplete',
           jsonb_build_object('raison', 'section_incomplete', 'module', i.module, 'donnees_du', i.donnees_du)
    from incompletes i
  ) x
$$;


--
-- Name: point_nom_module(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_nom_module(p_module text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_module
    when 'filed' then 'FILED' when 'cashd' then 'CASHD' when 'offload' then 'OFFLOAD' when 'reput' then 'REPUT'
    when 'point_du_matin' then 'Point du matin' when 'mesure' then 'Mesure'
    else initcap(replace(p_module, '_', ' ')) end
$$;


--
-- Name: point_nombre_fr(numeric, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_nombre_fr(p numeric, p_decimales integer DEFAULT 0) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_d integer := greatest(0, least(coalesce(p_decimales, 0), 6));
  v_r numeric;
  v_ent text;
  v_dec text;
begin
  if p is null then
    return null;
  end if;
  v_r := round(p, v_d);
  v_ent := split_part(abs(v_r)::text, '.', 1);
  v_dec := split_part(abs(v_r)::text, '.', 2);
  v_ent := regexp_replace(v_ent, '(\d)(?=(\d{3})+$)', '\1' || chr(160), 'g');
  return case when v_r < 0 then '−' else '' end || v_ent || case when v_dec <> '' then ',' || v_dec else '' end;
end $_$;


--
-- Name: point_reglage(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_reglage(p_client uuid, p_user uuid) RETURNS TABLE(pose boolean, actif boolean, heure time without time zone, territoire text, fuseau text, complet boolean, jours smallint[], sauf_feries boolean, canal text, contenu text, si_vide text, delais_horizon integer, donnees_sante boolean, conservation_jours integer, horaire_depuis timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select o.id is not null or p.id is not null,
         coalesce(p.actif, o.actif, false),
         coalesce(p.heure, o.heure, time '07:00'),
         t.code,
         t.fuseau,
         t.complet,
         coalesce(p.jours, o.jours, '{1,2,3,4,5}'::smallint[]),
         coalesce(p.sauf_feries, o.sauf_feries, true),
         coalesce(p.canal, o.canal, 'email'),
         case when p.contenu = 'signal' or o.contenu = 'signal' then 'signal' else 'complet' end,
         coalesce(p.si_vide, o.si_vide, 'rien'),
         coalesce(p.delais_horizon, o.delais_horizon, 7),
         coalesce(o.donnees_sante, false)
           or exists (select 1 from public.points_sections s
                      where s.client_id = p_client and private.point_module_sante(s.module)),
         coalesce(o.conservation_jours, 400),
         greatest(o.horaire_depuis, p.horaire_depuis)
  from (select 1) as un
  left join public.points_reglages o on o.client_id = p_client and o.user_id is null
  left join public.points_reglages p on p.client_id = p_client and p.user_id = p_user and p_user is not null
  left join public.territoires t on t.code = coalesce(
    p.territoire,
    (select case when count(distinct x.code) = 1 and bool_and(x.code is not null) then min(x.code) end
     from (select private.territoire_de_entite(p_client, ce.entite_id) as code
           from public.comptes_entites ce
           join public.comptes c on c.client_id = ce.client_id and c.user_id = ce.user_id and not c.perimetre_total
           where ce.client_id = p_client and ce.user_id = p_user) x),
    private.point_territoire_client(p_client))
$$;


--
-- Name: point_remettre(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_remettre(p_point uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  p public.points_du_jour;
  v_rendu jsonb;
  v_regle_sujet text;
  v_longueur integer;
  v_corps text;
  v_envoi uuid;
  v_statut text;
  v_verrou text;
  v_motif text;
  v_nom text;
begin
  select * into p from public.points_du_jour x where x.id = p_point for update;
  if not found then
    raise exception 'Point introuvable.' using errcode = 'P0002';
  end if;
  if p.statut not in ('pret', 'echec') or not private.point_b4_present() then
    return p.statut;
  end if;
  v_rendu := private.point_rendre(p.id);
  select c.nom into v_nom from public.clients c where c.id = p.client_id;
  begin
    if to_regclass('private.canaux_envoi') is not null then
      execute 'select c.sujet, c.longueur_max from private.canaux_envoi c where c.canal = $1'
        into v_regle_sujet, v_longueur using p.canal;
    end if;
    v_corps := v_rendu ->> 'corps';
    if char_length(v_corps) > coalesce(v_longueur, 4096) then
      v_corps := v_rendu ->> 'corps_court';
    end if;
    -- Le message ne porte aucune donnée de santé en clair : le gabarit fermé
    -- les a laissées dans l'espace. Un message de service, un par jour au
    -- membre : le moteur l'exempte de l'espacement entre messages.
    execute 'select public.preparer_envoi(p_client => $1, p_module => $2, p_objet_type => $3, p_objet_id => $4, '
         || 'p_canal => $5, p_destinataire => $6, p_sujet => $7, p_corps => $8, p_cle_idempotence => $9, '
         || 'p_transactionnel => true, p_donnees_sante => false, p_echeance => $10, p_options => $11)'
      into v_envoi
      using p.client_id, 'point_du_matin'::text, 'point_du_jour'::text, p.id::text, p.canal,
            jsonb_build_object('membre', p.user_id, 'territoire', p.territoire),
            case when v_regle_sujet = 'interdit' or (v_regle_sujet is null and p.canal <> 'email') then null
                 else v_rendu ->> 'sujet' end,
            v_corps,
            'point_du_matin:' || p.id || ':' || p.version,
            ((p.jour + 1) + time '00:00') at time zone p.fuseau,
            case when (select auth.uid()) is null then '{"espacement": false}'::jsonb else '{}'::jsonb end;
    if to_regclass('public.envois') is not null then
      execute 'select e.statut, e.verrou, e.motif from public.envois e where e.id = $1'
        into v_statut, v_verrou, v_motif using v_envoi;
    end if;
    if v_statut = 'bloque' then
      v_motif := left(coalesce(v_verrou, 'BLOQUE') || ' : ' || coalesce(v_motif, 'envoi retenu par B4'), 300);
      update public.points_du_jour set statut = 'echec', envoi_id = v_envoi, motif_echec = v_motif where id = p.id;
      perform private.lever_alerte(p.client_id, true, 'critique', 'point_du_matin',
        format('Le point du matin ne part pas chez %s', v_nom),
        jsonb_build_object('point', p.id, 'jour', p.jour, 'envoi', v_envoi, 'verrou', v_verrou, 'motif', v_motif),
        'point_remise:' || p.id);
      return 'echec';
    end if;
    update public.points_du_jour set statut = 'remis', envoi_id = v_envoi, remis_le = now(), motif_echec = null
    where id = p.id;
    update public.alertes a set acquittee_le = now(), detail = a.detail || jsonb_build_object('resolution', 'remis')
    where a.client_id = p.client_id and a.cle_regroupement = 'point_remise:' || p.id and a.acquittee_le is null;
    return 'remis';
  exception when others then
    update public.points_du_jour set statut = 'echec', motif_echec = left(sqlerrm, 300) where id = p.id;
    perform private.lever_alerte(p.client_id, true, 'critique', 'point_du_matin',
      format('Le point du matin ne part pas chez %s', v_nom),
      jsonb_build_object('point', p.id, 'jour', p.jour, 'erreur', left(sqlerrm, 300)),
      'point_remise:' || p.id);
    return 'echec';
  end;
end $_$;


--
-- Name: point_rendre(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_rendre(p_point uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.points_du_jour;
  v_client text;
  v_espace text := coalesce((select g.valeur from private.reglages g where g.cle = 'espace_url'), 'https://app.omegaai.fr/espace');
  v_lien text;
  v_signal_tout boolean;
  v_modules text[];
  v_marque text;
  v_sujet text;
  v_motifs text[];
  v_blocs text;
  v_signal boolean;
  v_entete text;
  v_pied text;
  v_corps text;
  v_court text;
begin
  select * into p from public.points_du_jour x where x.id = p_point;
  if not found then
    raise exception 'Point introuvable.' using errcode = 'P0002';
  end if;
  select c.nom into v_client from public.clients c where c.id = p.client_id;
  v_lien := v_espace || '/point/' || p.id;
  v_signal_tout := p.contenu = 'signal' or p.canal = 'whatsapp'
                   or (select r.donnees_sante from private.point_reglage(p.client_id, p.user_id) r);
  v_modules := array(select distinct x.module from public.points_du_jour_lignes x where x.point_id = p.id order by 1);
  v_marque := case when cardinality(v_modules) = 1 then private.point_nom_module(v_modules[1]) else 'Omega' end;
  v_sujet := v_marque || ' · ' || v_client || ' — point du ' || private.point_date_fr(p.jour, false);

  v_motifs := array(
    select case m ->> 'raison'
             when 'module_muet' then private.point_nom_module(m ->> 'module') || ' ne donne plus de nouvelles depuis le '
                                     || private.point_instant_fr((m ->> 'depuis')::timestamptz, p.fuseau)
             else private.point_nom_module(m ->> 'module') || ' signale des données incomplètes'
                  || coalesce(' (données du ' || private.point_instant_fr((m ->> 'donnees_du')::timestamptz, p.fuseau) || ')', '')
           end
    from jsonb_array_elements(p.motifs) m);

  with lignes as (
    select x.*, (v_signal_tout or x.sante) as en_signal
    from public.points_du_jour_lignes x where x.point_id = p.id
  ), clairs as (
    select l.section_rang as pos,
           private.point_nom_module((array_agg(l.module))[1]) || ' · ' || (array_agg(l.titre))[1]
             || coalesce(' — ' || (array_agg(l.entite_nom))[1], '')
             || case when max(l.donnees_du) is not null and (max(l.donnees_du) at time zone p.fuseau)::date < p.jour
                     then ' (données du ' || private.point_instant_fr(max(l.donnees_du), p.fuseau) || ')' else '' end
             || E'\n' || coalesce(string_agg(
                  '- ' || case l.gravite when 'critique' then 'Urgent : ' when 'attention' then 'À voir : ' else '' end
                  || l.texte || ' — ' || v_espace || l.lien, E'\n' order by l.rang) filter (where l.rang > 0),
                  '- Rien à signaler.') as bloc
    from lignes l
    where not l.en_signal
    group by l.section_rang
  ), signaux as (
    select min(l.section_rang) as pos, l.module, l.entite_id, (array_agg(l.entite_nom))[1] as entite_nom,
           count(*) filter (where l.rang > 0) as n,
           count(*) filter (where l.gravite = 'critique') as c,
           array_agg(case when l.gabarit is not null
                          then private.point_rendre_gabarit(l.gabarit, l.gabarit_version, l.valeurs) end
                     order by l.section_rang, l.rang)
             filter (where l.gabarit is not null) as rendus
    from lignes l
    where l.en_signal
    group by l.module, l.entite_id
  ), signaux_textes as (
    select g.pos,
           private.point_nom_module(g.module) || coalesce(' · ' || g.entite_nom, '') || ' : '
           || case when g.n = 0 then 'rien à signaler.'
                   else g.n || ' point' || case when g.n > 1 then 's' else '' end
                        || case when g.c > 0 then ', dont ' || g.c || ' urgent' || case when g.c > 1 then 's' else '' end
                                else '' end
                        || case when coalesce(cardinality(g.rendus), 0) > 0
                                then ' : ' || array_to_string(g.rendus[1:6], ', ')
                                     || case when g.n > least(cardinality(g.rendus), 6)
                                             then ', et ' || (g.n - least(cardinality(g.rendus), 6)) || ' autre'
                                                  || case when g.n - least(cardinality(g.rendus), 6) > 1 then 's' else '' end
                                             else '' end
                                else '' end
                        || '.' end as bloc
    from signaux g
  )
  select string_agg(b.bloc, E'\n\n' order by b.pos), coalesce(bool_or(b.signal), false)
    into v_blocs, v_signal
  from (select c.pos, c.bloc, false as signal from clairs c
        union all
        select t.pos, t.bloc, true from signaux_textes t) b;

  v_entete := 'Bonjour,' || E'\n\n' || 'Voici votre point du ' || private.point_date_fr(p.jour) || '.'
              || case when p.version > 1 then ' Il vous est renvoyé (envoi n° ' || p.version || ').' else '' end;
  v_pied := E'\n\n' || 'Ouvrir le point : ' || v_lien || E'\n\n' || '— ' || v_marque;
  v_corps := v_entete;
  if cardinality(v_motifs) > 0 then
    v_corps := v_corps || E'\n\n' || 'Ce point est incomplet : ' || array_to_string(v_motifs, ' ; ') || '.';
  end if;
  v_corps := v_corps || E'\n\n' || coalesce(v_blocs, 'Rien à signaler ce matin.');
  if v_signal then
    v_corps := v_corps || E'\n\n' || 'Le détail reste dans votre espace, derrière votre connexion.';
  end if;
  v_corps := v_corps || v_pied;
  v_court := v_entete || E'\n\n'
             || case when p.nb_items = 0 then 'Rien à signaler ce matin.'
                     else p.nb_items || ' point' || case when p.nb_items > 1 then 's' else '' end
                          || case when p.nb_critiques > 0
                                  then ', dont ' || p.nb_critiques || ' urgent' || case when p.nb_critiques > 1 then 's' else '' end
                                  else '' end || '.' end
             || case when cardinality(v_motifs) > 0 then ' Ce point est incomplet.' else '' end
             || v_pied;
  return jsonb_build_object('sujet', v_sujet, 'corps', v_corps, 'corps_court', v_court, 'lien', v_lien, 'signal', v_signal);
end $$;


--
-- Name: point_rendre_gabarit(text, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_rendre_gabarit(p_code text, p_version integer, p_valeurs jsonb) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  g public.points_gabarits;
  v_texte text;
  v_m text[];
  v_rendu text;
  v_attendus text;
begin
  select * into g from public.points_gabarits x where x.code = p_code and x.version = p_version;
  if not found then
    raise exception 'Gabarit inconnu : % (version %).', coalesce(p_code, 'vide'), coalesce(p_version::text, '?')
      using errcode = '22023';
  end if;
  if p_valeurs is null or jsonb_typeof(p_valeurs) <> 'object'
     or exists (select 1 from jsonb_object_keys(p_valeurs) k where not (g.champs ? k))
     or exists (select 1 from jsonb_object_keys(g.champs) k where not (p_valeurs ? k)) then
    select string_agg(k, ', ' order by k) into v_attendus from jsonb_object_keys(g.champs) k;
    raise exception 'Le gabarit % attend exactement ces valeurs : %.', p_code, coalesce(v_attendus, 'aucune')
      using errcode = '22023';
  end if;
  v_texte := g.texte;
  for v_m in select regexp_matches(g.texte, '(\{([a-z][a-z0-9_]{0,30})(?:\|([^|{}]*)\|([^|{}]*))?\})', 'g') loop
    v_rendu := private.point_valeur_fr(p_valeurs -> v_m[2], g.champs ->> v_m[2]);
    if v_rendu is null then
      raise exception 'La valeur « % » du gabarit % n''est pas du type %.', v_m[2], p_code, g.champs ->> v_m[2]
        using errcode = '22023';
    end if;
    if v_m[3] is not null then
      v_rendu := v_rendu || chr(160)
                 || case when abs((p_valeurs ->> v_m[2])::numeric) >= 2 then v_m[4] else v_m[3] end;
    end if;
    v_texte := replace(v_texte, v_m[1], v_rendu);
  end loop;
  return v_texte;
end $$;


--
-- Name: point_territoire_client(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_territoire_client(p_client uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select r.territoire from public.points_reglages r where r.client_id = p_client and r.user_id is null),
    (select private.territoire_de_entite(e.client_id, e.id) from public.entites e
     where e.client_id = p_client and e.principale))
$$;


--
-- Name: point_valeur_fr(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.point_valeur_fr(p_valeur jsonb, p_type text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v numeric;
  t text;
begin
  if p_valeur is null then
    return null;
  end if;
  if p_type in ('entier', 'nombre', 'montant', 'pourcentage') then
    if jsonb_typeof(p_valeur) <> 'number' then
      return null;
    end if;
    v := (p_valeur #>> '{}')::numeric;
    if abs(v) >= 1000000000000 then
      return null;
    end if;
    return case p_type
      when 'entier' then case when v = trunc(v) then private.point_nombre_fr(v, 0) end
      when 'nombre' then private.point_nombre_fr(v, case when v = trunc(v) then 0 else 1 end)
      when 'montant' then private.point_nombre_fr(v, case when v = trunc(v) then 0 else 2 end) || chr(160) || '€'
      else private.point_nombre_fr(v * 100, 0) || chr(160) || '%' end;
  end if;
  if jsonb_typeof(p_valeur) <> 'string' then
    return null;
  end if;
  t := p_valeur #>> '{}';
  if p_type = 'heure' then
    if t !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      return null;
    end if;
    return private.point_heure_fr(t::time);
  elsif p_type = 'date' then
    if t !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      return null;
    end if;
    begin
      return to_char(t::date, 'DD/MM');
    exception when others then
      return null;
    end;
  end if;
  return null;
end $_$;


--
-- Name: points_assembler(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.points_assembler(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c record;
  m record;
  v_id uuid;
  v_etat text;
  v_nb integer;
  v_clients integer := 0;
  v_assembles integer := 0;
  v_remis integer := 0;
  v_echecs integer := 0;
  v_erreurs integer := 0;
  v_perimes integer;
begin
  -- Un point prêt d'un jour révolu ne partira plus.
  update public.points_du_jour p set statut = 'perime'
  where p.statut in ('pret', 'echec') and p.jour < (p_maintenant at time zone p.fuseau)::date;
  get diagnostics v_perimes = row_count;

  for c in
    select cl.id, cl.nom from public.clients cl
    where exists (select 1 from public.points_reglages r where r.client_id = cl.id)
    order by cl.id
  loop
    begin
      v_nb := 0;
      for m in select * from private.points_manquants(c.id, p_maintenant) loop
        begin
          v_id := private.point_assembler(c.id, m.user_id, m.jour, p_maintenant);
          if v_id is not null then
            v_nb := v_nb + 1;
            v_etat := private.point_remettre(v_id);
            if v_etat = 'remis' then
              v_remis := v_remis + 1;
            elsif v_etat = 'echec' then
              v_echecs := v_echecs + 1;
            end if;
          end if;
        exception when others then
          v_erreurs := v_erreurs + 1;
          perform private.lever_alerte(c.id, true, 'critique', 'point_du_matin',
            format('L''assemblage du point du matin échoue chez %s', c.nom),
            jsonb_build_object('jour', m.jour, 'erreur', left(sqlerrm, 300)), 'point_assemblage:' || m.jour);
        end;
      end loop;
      v_assembles := v_assembles + v_nb;

      -- Les points du jour que l'envoi n'a pas encore pris se remettent : prêts
      -- (l'envoi vient d'être branché, un renvoi est demandé) ou en échec sans
      -- envoi ; l'alerte ouverte ne se répète pas. Un envoi que B4 retient
      -- attend qu'on lève son verrou, puis un renvoi.
      if private.point_b4_present() then
        for m in
          select p.id from public.points_du_jour p
          where p.client_id = c.id and p.jour = (p_maintenant at time zone p.fuseau)::date
            and (p.statut = 'pret' or (p.statut = 'echec' and p.envoi_id is null))
        loop
          if private.point_remettre(m.id) = 'remis' then
            v_remis := v_remis + 1;
          end if;
        end loop;
      end if;

      -- Plus aucun point en retard : l'alerte d'échéance se ferme.
      if not exists (select 1 from private.points_manquants(c.id, p_maintenant)) then
        update public.alertes a
           set acquittee_le = now(), detail = a.detail || jsonb_build_object('resolution', 'les points sont prêts')
         where a.client_id = c.id and a.acquittee_le is null and a.source = 'point_du_matin'
           and (a.cle_regroupement like 'point\_retard:%' or a.cle_regroupement like 'point\_retard\_client:%');
      end if;

      perform private.battre(c.id, 'point_du_matin_assemblage',
        jsonb_build_object('assembles', v_nb, 'passage', p_maintenant), interval '1 hour');
      v_clients := v_clients + 1;
    exception when others then
      v_erreurs := v_erreurs + 1;
      perform private.lever_alerte(c.id, true, 'critique', 'point_du_matin',
        format('L''assemblage du point du matin échoue chez %s', c.nom),
        jsonb_build_object('erreur', left(sqlerrm, 300)), 'point_assemblage');
    end;
  end loop;
  return jsonb_build_object('clients', v_clients, 'assembles', v_assembles, 'remis', v_remis,
                            'echecs', v_echecs, 'erreurs', v_erreurs, 'perimes', v_perimes);
end $$;


--
-- Name: points_controler(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.points_controler(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c record;
  v_nb integer;
  v_jour date;
  v_prevu timestamptz;
  v_du timestamptz;
  n integer := 0;
begin
  for c in
    select cl.id, cl.nom from public.clients cl
    where exists (select 1 from public.points_reglages r where r.client_id = cl.id)
  loop
    begin
      select count(*), min(m.jour), min(m.prevu_le), min(m.du_le) into v_nb, v_jour, v_prevu, v_du
      from private.points_manquants(c.id, p_maintenant) m
      where m.du_le + interval '10 minutes' <= p_maintenant;
      if v_nb > 0 then
        if private.lever_alerte(c.id, true, 'critique', 'point_du_matin',
             format('Le point du matin n''est pas prêt chez %s (%s destinataire%s)', c.nom, v_nb,
                    case when v_nb > 1 then 's' else '' end),
             jsonb_build_object('jour', v_jour, 'prevu_le', v_prevu, 'du_le', v_du, 'manquants', v_nb),
             'point_retard:' || v_jour) is not null then
          n := n + 1;
        end if;
        perform private.lever_alerte(c.id, false, 'attention', 'point_du_matin',
          'Votre point du matin a du retard : l''équipe d''Omega est prévenue.',
          jsonb_build_object('jour', v_jour), 'point_retard_client:' || v_jour);
      end if;
      -- Un territoire inconnu ne se suppose pas : on le demande.
      select count(*) into v_nb
      from public.comptes co
      cross join lateral private.point_reglage(co.client_id, co.user_id) r
      where co.client_id = c.id and r.pose and r.actif and r.territoire is null;
      if v_nb > 0 then
        if private.lever_alerte(c.id, true, 'attention', 'point_du_matin',
             format('Le point du matin de %s membre%s chez %s attend son territoire : le poser dans le réglage',
                    v_nb, case when v_nb > 1 then 's' else '' end, c.nom),
             jsonb_build_object('membres', v_nb), 'point_sans_territoire') is not null then
          n := n + 1;
        end if;
      end if;
    exception when others then
      perform private.lever_alerte(c.id, true, 'critique', 'point_du_matin',
        format('Le contrôle du point du matin échoue chez %s', c.nom),
        jsonb_build_object('erreur', left(sqlerrm, 300)), 'point_controle');
    end;
  end loop;

  -- Des sections attendent chez une organisation sans réglage : personne ne les recevrait.
  for c in
    select s.client_id, cl.nom, count(*) as nb, min(s.jour) as jour
    from public.points_sections s
    join public.clients cl on cl.id = s.client_id
    where s.jour >= (p_maintenant at time zone 'UTC')::date - 1
      and not exists (select 1 from public.points_reglages r where r.client_id = s.client_id)
    group by s.client_id, cl.nom
  loop
    if private.lever_alerte(c.client_id, true, 'attention', 'point_du_matin',
         format('Des sections du point du matin attendent chez %s, sans réglage : personne ne les recevra', c.nom),
         jsonb_build_object('sections', c.nb, 'jour', c.jour), 'point_sans_reglage:' || c.jour) is not null then
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: points_manquants(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.points_manquants(p_client uuid, p_maintenant timestamp with time zone) RETURNS TABLE(user_id uuid, jour date, prevu_le timestamp with time zone, du_le timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.membre, x.jour_local, x.prevu, private.point_devenu_du(x.prevu, x.depuis, p_maintenant)
  from (
    select co.user_id as membre, (p_maintenant at time zone r.fuseau)::date as jour_local,
           private.point_du(co.client_id, co.user_id, (p_maintenant at time zone r.fuseau)::date) as prevu,
           r.horaire_depuis as depuis
    from public.comptes co
    cross join lateral private.point_reglage(co.client_id, co.user_id) r
    where co.client_id = p_client and r.pose and r.actif
  ) x
  where x.prevu is not null and x.prevu <= p_maintenant
    and not exists (select 1 from public.points_du_jour pj
                    where pj.client_id = p_client and pj.user_id = x.membre and pj.jour = x.jour_local)
$$;


--
-- Name: points_purger(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.points_purger(p_maintenant timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n1 integer;
  n2 integer;
begin
  delete from public.points_du_jour p
  where p.jour < (p_maintenant at time zone 'UTC')::date
                 - coalesce((select r.conservation_jours from public.points_reglages r
                             where r.client_id = p.client_id and r.user_id is null), 400);
  get diagnostics n1 = row_count;
  delete from public.points_sections s where s.jour < (p_maintenant at time zone 'UTC')::date - 35;
  get diagnostics n2 = row_count;
  return n1 + n2;
end $$;


--
-- Name: politique_couvrante(uuid, text, text, uuid, numeric, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.politique_couvrante(p_client uuid, p_module text, p_type text, p_entite uuid, p_montant numeric, p_instant timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_debut_mois timestamptz;
  v_cumul numeric;
  v_nombre integer;
begin
  if p_type = 'politique.activer'
     or exists (select 1 from private.actions_sans_accord a where a.module = p_module and a.type_action = p_type) then
    return null;
  end if;
  for r in
    select p.id, p.fuseau, p.plafond_mensuel, p.nombre_mensuel
    from public.politiques p
    where p.client_id = p_client and p.module = p_module and p.type_action = p_type
      and p.statut = 'active' and p_instant >= p.debut and p_instant < p.fin
      and (p.entite_id is null or p.entite_id is not distinct from p_entite)
      and ((p.plafond_operation is null and p_montant is null)
           or (p.plafond_operation is not null and p_montant is not null and p_montant <= p.plafond_operation))
    order by (p.entite_id is not null) desc, p.plafond_operation asc nulls last, p.id
    for update
  loop
    v_debut_mois := date_trunc('month', p_instant at time zone r.fuseau) at time zone r.fuseau;
    select coalesce(sum(d.montant), 0), count(*) into v_cumul, v_nombre
    from public.demandes_validation d
    where d.politique_id = r.id and d.cree_le >= v_debut_mois and d.statut in ('approuvee', 'executee');
    if (r.plafond_mensuel is null or v_cumul + coalesce(p_montant, 0) <= r.plafond_mensuel)
       and (r.nombre_mensuel is null or v_nombre + 1 <= r.nombre_mensuel) then
      return r.id;
    end if;
  end loop;
  return null;
end $$;


--
-- Name: poser_delai(uuid, text, text, text, text, text, date, text, integer[], uuid, text, text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.poser_delai(p_client uuid, p_module text, p_objet_type text, p_objet_id text, p_libelle text, p_regle text, p_depart date, p_territoire text, p_rappels integer[] DEFAULT '{7,2,0}'::integer[], p_responsable uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_cle text DEFAULT NULL::text, p_augmentation_mois integer DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_calcul jsonb;
begin
  perform private.exiger_ecriture_delai(p_client, p_objet_type, p_objet_id);
  perform private.exiger_porte_du_module(p_module);
  if p_cle is not null then
    select d.id into v_id from public.delais d where d.client_id = p_client and d.module = p_module and d.cle_idempotence = p_cle;
    if found then
      return v_id;
    end if;
  end if;
  v_calcul := public.echeance_de(p_regle, p_depart, p_territoire, p_augmentation_mois);
  insert into public.delais (client_id, module, objet_type, objet_id, libelle, territoire, regle_code, regle_version, depart,
                             echeance_calculee, calcul, rappels, responsable, action_attendue, cle_idempotence)
  values (p_client, p_module, p_objet_type, p_objet_id, p_libelle, p_territoire, p_regle, (v_calcul ->> 'version')::smallint,
          p_depart, (v_calcul ->> 'echeance')::date, v_calcul, private.rappels_propres(p_rappels), p_responsable, p_action, p_cle)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: poser_delai_date(uuid, text, text, text, text, date, text, text, integer[], uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.poser_delai_date(p_client uuid, p_module text, p_objet_type text, p_objet_id text, p_libelle text, p_echeance date, p_source text, p_territoire text, p_rappels integer[] DEFAULT '{7,2,0}'::integer[], p_responsable uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_cle text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
begin
  perform private.exiger_ecriture_delai(p_client, p_objet_type, p_objet_id);
  perform private.exiger_porte_du_module(p_module);
  if p_echeance is null or nullif(btrim(p_source), '') is null then
    raise exception 'Une date et sa source (l''acte, le courrier, la saisie) sont nécessaires.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.territoires t where t.code = p_territoire) then
    raise exception 'Territoire inconnu : %.', coalesce(p_territoire, 'vide') using errcode = '22023';
  end if;
  if p_cle is not null then
    select d.id into v_id from public.delais d where d.client_id = p_client and d.module = p_module and d.cle_idempotence = p_cle;
    if found then
      return v_id;
    end if;
  end if;
  insert into public.delais (client_id, module, objet_type, objet_id, libelle, territoire, echeance_notifiee,
                             source_notification, rappels, responsable, action_attendue, cle_idempotence)
  values (p_client, p_module, p_objet_type, p_objet_id, p_libelle, p_territoire, p_echeance, p_source,
          private.rappels_propres(p_rappels), p_responsable, p_action, p_cle)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: prendre_travaux(text[], integer, interval, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prendre_travaux(p_genres text[], p_nombre integer DEFAULT 5, p_bail interval DEFAULT '00:10:00'::interval, p_ouvrier text DEFAULT NULL::text) RETURNS SETOF public.travaux
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return query
  with choisis as (
    select t.id from public.travaux t
    where t.genre = any (p_genres)
      and ((t.etat = 'a_faire' and t.prochain_le <= now())
           or (t.etat = 'en_cours' and t.verrou_jusqu_au < now()))
    order by t.priorite desc, t.prochain_le, t.id
    limit greatest(1, least(p_nombre, 100))
    for update skip locked
  )
  update public.travaux t
     set etat = 'en_cours', essais = t.essais + 1, verrou_jusqu_au = now() + p_bail,
         pris_par = left(p_ouvrier, 120), erreur = null
    from choisis
   where t.id = choisis.id
  returning t.*;
end $$;


--
-- Name: preparer_approbation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_approbation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_d public.demandes_validation;
  v_uid uuid := (select auth.uid());
  v_decideur uuid;
  v_delegation uuid;
begin
  if v_uid is null then
    raise exception 'Une décision est toujours prise par une personne connectée.' using errcode = '42501';
  end if;

  -- Verrou sur la demande : deux décisions simultanées ne se croisent pas.
  select * into v_d from public.demandes_validation where id = new.demande_id for update;
  if not found then
    raise exception 'Demande introuvable.' using errcode = 'P0002';
  end if;
  if v_d.statut <> 'en_attente' then
    raise exception 'Cette demande n''est plus en attente (%).', v_d.statut using errcode = '23514';
  end if;
  if v_d.echeance is not null and v_d.echeance <= now() then
    raise exception 'L''échéance de cette demande est passée.' using errcode = '23514';
  end if;

  new.user_id := v_uid;
  new.client_id := v_d.client_id;
  new.decide_le := now();
  v_decideur := coalesce(new.au_nom_de, v_uid);

  if new.au_nom_de is not null then
    select dl.id into v_delegation
    from public.delegations dl
    where dl.client_id = v_d.client_id
      and dl.delegant = new.au_nom_de
      and dl.delegataire = v_uid
      and dl.revoquee_le is null
      and now() >= dl.debut and now() < dl.fin
      and (dl.entite_id is null or dl.entite_id is not distinct from v_d.entite_id)
      and (dl.module is null or dl.module = v_d.module)
    order by dl.fin desc
    limit 1;
    if v_delegation is null then
      raise exception 'Aucune délégation en cours ne vous permet de décider au nom de cette personne.'
        using errcode = '42501';
    end if;
    new.delegation_id := v_delegation;
  else
    new.delegation_id := null;
  end if;

  if v_d.demandeur_id is not null and (v_uid = v_d.demandeur_id or v_decideur = v_d.demandeur_id) then
    raise exception 'Le demandeur ne décide pas de sa propre demande.' using errcode = '42501';
  end if;

  perform private.exiger_decideur(v_d, v_decideur);
  -- La personne qui clique doit aussi voir l'objet, même quand elle agit par délégation.
  if not private.voit_objet_pour(v_uid, v_d.client_id, v_d.objet_type, v_d.objet_id) then
    raise exception 'Vous n''avez pas accès à l''objet de cette demande.' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: preparer_delegation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_delegation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.cree_par := coalesce((select auth.uid()), new.cree_par);
  new.revoquee_le := null;
  if not exists (select 1 from public.comptes c where c.user_id = new.delegant and c.client_id = new.client_id
      and c.role in ('gerant', 'admin', 'valideur')) then
    raise exception 'Seul un compte qui décide peut déléguer son droit de décider.' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: preparer_demande(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_demande() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_regle public.regles_validation;
  v_uid uuid := (select auth.uid());
  v_politique uuid;
begin
  new.statut := 'en_attente';
  new.cree_le := now();
  new.decide_le := null;
  new.execute_le := null;
  new.motif_echec := null;
  new.politique_id := null;
  if v_uid is not null then
    new.demandeur_type := 'utilisateur';
    new.demandeur_id := v_uid;
  else
    new.demandeur_type := 'systeme';
    new.demandeur_id := null;
  end if;

  -- La règle la plus précise l'emporte : type d'action, puis entité, puis
  -- seuil. Une activation d'accord ne suit que les règles écrites pour elle.
  select r.* into v_regle
  from public.regles_validation r
  where r.client_id = new.client_id
    and r.module = new.module
    and r.actif
    and ((r.type_action is null and new.type_action <> 'politique.activer') or r.type_action = new.type_action)
    and (r.entite_id is null or r.entite_id = new.entite_id)
    and coalesce(new.montant, 0) >= r.montant_min
    and (r.montant_max is null or coalesce(new.montant, 0) < r.montant_max)
  order by (r.type_action is not null) desc, (r.entite_id is not null) desc,
           r.montant_min desc, r.approbations_requises desc
  limit 1;

  if found then
    new.regle_id := v_regle.id;
    new.approbations_requises := v_regle.approbations_requises;
    new.roles_autorises := v_regle.roles_autorises;
    new.equipe_id := v_regle.equipe_id;
  else
    new.regle_id := null;
    new.approbations_requises := 1;
    -- Sans règle écrite pour elle, une activation d'accord revient au gérant.
    new.roles_autorises := case when new.type_action = 'politique.activer'
                                then array['gerant'] else array['gerant', 'admin', 'valideur'] end;
    new.equipe_id := null;
  end if;

  -- Un accord permanent actif, dans ses bornes : la demande est approuvée d'office.
  v_politique := private.politique_couvrante(new.client_id, new.module, new.type_action, new.entite_id,
                                             new.montant, now());
  if v_politique is not null then
    new.statut := 'approuvee';
    new.decide_le := now();
    new.politique_id := v_politique;
    new.approbations_requises := 0;
  end if;
  return new;
end $$;


--
-- Name: preparer_effacement(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_effacement(p_client uuid, p_objet_type text DEFAULT NULL::text, p_objet_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cle text := p_client::text || coalesce('/' || p_objet_type || '/' || p_objet_id, '');
  v_liste jsonb;
  v_manifeste jsonb;
begin
  if not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  if (p_objet_type is null) <> (p_objet_id is null) then
    raise exception 'Un objet se désigne par son type et son identifiant.' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('bucket', f.bucket, 'nom', f.nom, 'octets', f.octets,
                                               'empreinte', f.empreinte) order by f.bucket, f.nom), '[]'::jsonb)
  into v_liste
  from private.fichiers_de(p_client, p_objet_type, p_objet_id) f;

  v_manifeste := jsonb_build_object(
    'nombre', jsonb_array_length(v_liste),
    'octets', (select coalesce(sum((e ->> 'octets')::bigint), 0) from jsonb_array_elements(v_liste) e),
    'empreinte_sha256', encode(sha256(convert_to(v_liste::text, 'UTF8')), 'hex'),
    'prepare_le', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));

  insert into private.manifestes_effacement (cle, manifeste) values (v_cle, v_manifeste)
  on conflict (cle) do update set manifeste = excluded.manifeste, cree_le = now();
  return jsonb_build_object('manifeste', v_manifeste, 'fichiers', v_liste);
end $$;


--
-- Name: preparer_envoi(uuid, text, text, text, text, jsonb, text, jsonb, text, text, uuid[], text, uuid, boolean, boolean, timestamp with time zone, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_envoi(p_client uuid, p_module text, p_objet_type text, p_objet_id text, p_canal text, p_destinataire jsonb, p_gabarit text DEFAULT NULL::text, p_variables jsonb DEFAULT '{}'::jsonb, p_sujet text DEFAULT NULL::text, p_corps text DEFAULT NULL::text, p_pieces uuid[] DEFAULT NULL::uuid[], p_cle_idempotence text DEFAULT NULL::text, p_entite uuid DEFAULT NULL::uuid, p_transactionnel boolean DEFAULT false, p_donnees_sante boolean DEFAULT false, p_echeance timestamp with time zone DEFAULT NULL::timestamp with time zone, p_options jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid;
  v_id uuid;
  v_opt jsonb := coalesce(p_options, '{}'::jsonb);
  v_cle text;
  v_direct boolean;
  v_demande uuid;
begin
  v_uid := private.exiger_acteur_envoi(p_client, p_entite, p_objet_type, p_objet_id);
  if nullif(btrim(p_cle_idempotence), '') is null then
    raise exception 'Une clé d''idempotence est obligatoire : rejouer ne doit jamais envoyer deux fois.' using errcode = '22023';
  end if;
  select e.id into v_id from public.envois e where e.client_id = p_client and e.cle_idempotence = btrim(p_cle_idempotence);
  if v_id is not null then
    return v_id;
  end if;
  if jsonb_typeof(v_opt) <> 'object' then
    raise exception 'Les options forment un objet JSON.' using errcode = '22023';
  end if;
  for v_cle in select jsonb_object_keys(v_opt) loop
    if v_cle not in ('direct', 'repondre_a', 'demande', 'espacement') then
      raise exception 'Option inconnue : « % » (direct, repondre_a, demande, espacement).', v_cle using errcode = '22023';
    end if;
  end loop;
  if (v_opt ? 'direct' and jsonb_typeof(v_opt -> 'direct') <> 'boolean')
     or (v_opt ? 'espacement' and jsonb_typeof(v_opt -> 'espacement') <> 'boolean') then
    raise exception 'Les options direct et espacement valent true ou false.' using errcode = '22023';
  end if;
  v_direct := coalesce((v_opt ->> 'direct')::boolean, false);
  if v_direct then
    if v_uid is null then
      raise exception 'Un moteur ne se passe jamais de la validation : un accord permanent peut couvrir ses envois.'
        using errcode = '42501';
    end if;
    if not private.a_le_droit(p_client, 'envois.direct') then
      raise exception 'Envoyer sans validation demande le droit « envois.direct », accordé par le gérant.' using errcode = '42501';
    end if;
    if v_opt ? 'demande' then
      raise exception 'Direct, ou adossé à une décision : pas les deux.' using errcode = '22023';
    end if;
  end if;
  if v_opt ? 'espacement' and v_uid is not null then
    raise exception 'Seul un moteur règle l''espacement d''un texte libre.' using errcode = '42501';
  end if;
  if v_opt ? 'demande' then
    begin
      v_demande := (v_opt ->> 'demande')::uuid;
    exception when others then
      raise exception 'L''option demande est l''identifiant d''une demande de validation.' using errcode = '22023';
    end;
  end if;
  begin
    return private.creer_envoi(
      p_client, p_module, p_objet_type, p_objet_id, p_canal, p_destinataire, p_gabarit, p_variables, p_sujet, p_corps,
      p_pieces, btrim(p_cle_idempotence), p_entite, p_transactionnel, p_donnees_sante, p_echeance,
      v_direct, v_opt ->> 'repondre_a', v_demande, (v_opt ->> 'espacement')::boolean, v_uid, null, null);
  exception when unique_violation then
    -- Deux appels simultanés avec la même clé : le second rend le premier.
    select e.id into v_id from public.envois e where e.client_id = p_client and e.cle_idempotence = btrim(p_cle_idempotence);
    if v_id is null then
      raise;
    end if;
    return v_id;
  end;
end $$;


--
-- Name: preparer_expediteur(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_expediteur() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f private.fournisseurs_envoi;
begin
  select * into v_f from private.fournisseurs_envoi f where f.fournisseur = new.fournisseur;
  if v_f.fournisseur is null then
    raise exception 'Fournisseur inconnu : %.', new.fournisseur using errcode = '22023';
  end if;
  if v_f.canal is not null and v_f.canal <> new.canal then
    raise exception 'Le fournisseur % porte le canal %, pas %.', new.fournisseur, v_f.canal, new.canal using errcode = '22023';
  end if;
  if v_f.automatique and new.canal in ('email', 'lre') then
    new.identite := private.normaliser_email(new.identite);
    if new.identite is null then
      raise exception 'L''identité d''un expéditeur de courriel est une adresse valide.' using errcode = '22023';
    end if;
  end if;
  if new.repondre_a is not null then
    new.repondre_a := private.normaliser_email(new.repondre_a);
    if new.repondre_a is null then
      raise exception 'Adresse de réponse invalide.' using errcode = '22023';
    end if;
  end if;
  if new.fournisseur = 'meta_whatsapp' and nullif(new.parametres ->> 'phone_number_id', '') is null then
    raise exception 'WhatsApp Cloud API : parametres.phone_number_id est nécessaire.' using errcode = '22023';
  end if;
  if new.fournisseur = 'ar24' and nullif(new.parametres ->> 'id_utilisateur', '') is null then
    raise exception 'AR24 : parametres.id_utilisateur (le compte expéditeur) est nécessaire.' using errcode = '22023';
  end if;
  if new.fournisseur in ('gmail', 'microsoft') and new.secret_nom is null then
    raise exception 'Une boîte déléguée garde son jeton dans le coffre : secret_nom est nécessaire.' using errcode = '22023';
  end if;
  if new.statut = 'actif' and (tg_op = 'INSERT' or old.statut is distinct from 'actif') then
    new.verifie_le := coalesce(new.verifie_le, now());
  end if;
  new.maj_le := now();
  return new;
end $$;


--
-- Name: preparer_gabarit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_gabarit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_canal private.canaux_envoi;
  v_cle text;
  v_type text;
  v_utilisees text[];
begin
  if tg_op = 'DELETE' then
    if old.statut = 'brouillon' or (old.client_id is not null and private.effacement_en_cours(old.client_id)) then
      return old;
    end if;
    raise exception 'Un gabarit validé ne s''efface pas : retirez-le.' using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' and old.statut <> 'brouillon' then
    -- Un gabarit validé ne se retouche plus : seul son retrait est possible, une fois.
    if (new.id, new.client_id, new.module, new.code, new.langue, new.version, new.canal, new.libelle, new.sujet, new.corps,
        new.variables, new.transactionnel, new.donnees_sante, new.espacement, new.modele_externe, new.valide_le,
        new.valide_par, new.cree_le)
       is distinct from
       (old.id, old.client_id, old.module, old.code, old.langue, old.version, old.canal, old.libelle, old.sujet, old.corps,
        old.variables, old.transactionnel, old.donnees_sante, old.espacement, old.modele_externe, old.valide_le,
        old.valide_par, old.cree_le)
       or old.statut = 'retire'
       or new.statut not in ('valide', 'retire') then
      raise exception 'Un gabarit validé ne se retouche pas : retirez-le et créez une nouvelle version.' using errcode = '42501';
    end if;
    if new.statut = 'retire' then
      new.retire_le := coalesce(new.retire_le, now());
    end if;
    return new;
  end if;

  if new.statut = 'retire' then
    raise exception 'Un gabarit naît brouillon ou validé.' using errcode = '22023';
  end if;

  select * into v_canal from private.canaux_envoi c where c.canal = new.canal;
  for v_cle, v_type in select e.key, e.value #>> '{}' from jsonb_each(new.variables) e loop
    if v_cle !~ '^[a-z][a-z0-9_]{0,39}$' or v_cle in ('organisation', 'entite') then
      raise exception 'Nom de variable refusé : « % » (organisation et entite sont fournies par la base).', v_cle
        using errcode = '22023';
    end if;
    if v_type is null or v_type not in ('texte', 'date', 'heure', 'montant', 'nombre', 'lien', 'reference') then
      raise exception 'Type de variable inconnu pour « % » : texte, date, heure, montant, nombre, lien ou reference.', v_cle
        using errcode = '22023';
    end if;
  end loop;

  if regexp_replace(coalesce(new.sujet, '') || ' ' || new.corps, '\{\{[a-z][a-z0-9_]{0,39}\}\}', '', 'g') ~ '\{\{|\}\}' then
    raise exception 'Une variable s''écrit {{nom}}, en minuscules, sans espace.' using errcode = '22023';
  end if;
  v_utilisees := private.variables_du_texte(coalesce(new.sujet, '') || ' ' || new.corps);
  select x into v_cle from unnest(v_utilisees) x
  where x not in ('organisation', 'entite') and not (new.variables ? x) limit 1;
  if v_cle is not null then
    raise exception 'La variable {{%}} n''est pas déclarée dans le gabarit.', v_cle using errcode = '22023';
  end if;

  if v_canal.sujet = 'obligatoire' and new.sujet is null then
    raise exception 'Un gabarit de % porte un sujet.', lower(v_canal.libelle) using errcode = '22023';
  end if;
  if v_canal.sujet = 'interdit' and new.sujet is not null then
    raise exception 'Un gabarit de % n''a pas de sujet.', v_canal.libelle using errcode = '22023';
  end if;
  if char_length(new.corps) > v_canal.longueur_max then
    raise exception 'Gabarit trop long pour le canal % : % caractères au plus.', v_canal.libelle, v_canal.longueur_max
      using errcode = '22023';
  end if;
  if new.canal = 'whatsapp' and new.modele_externe is null then
    raise exception 'Un gabarit WhatsApp nomme le modèle approuvé par Meta (modele_externe).' using errcode = '22023';
  end if;
  -- Contexte de santé : sans données de santé déclarées, un gabarit est fermé (aucun texte libre).
  if not new.donnees_sante
     and exists (select 1 from private.modules_envois m where m.module = new.module and m.sante)
     and exists (select 1 from jsonb_each_text(new.variables) e where e.value = 'texte') then
    raise exception 'Module de santé : un gabarit sans données de santé n''a que des variables typées, jamais de texte libre.'
      using errcode = '22023';
  end if;

  if new.statut = 'valide' then
    if nullif(btrim(new.valide_par), '') is null then
      raise exception 'Un gabarit est validé par une personne nommée : qui valide ?' using errcode = '22023';
    end if;
    new.valide_le := coalesce(new.valide_le, now());
  else
    new.valide_le := null;
    new.valide_par := null;
  end if;
  return new;
end $_$;


--
-- Name: preparer_politique(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_politique() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from private.actions_sans_accord a where a.module = new.module and a.type_action = new.type_action) then
    raise exception 'Cette action ne se donne jamais par accord permanent : une personne décide chaque fois.'
      using errcode = '42501';
  end if;
  new.statut := 'a_valider';
  new.cree_par := (select auth.uid());
  new.cree_le := now();
  new.active_le := null;
  new.revoquee_le := null;
  new.revoquee_par := null;
  new.motif_revocation := null;
  new.demande_id := gen_random_uuid();
  if new.fin <= now() then
    raise exception 'Un accord permanent finit dans le futur.' using errcode = '22023';
  end if;
  return new;
end $$;


--
-- Name: preparer_rattachement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_rattachement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.objet_id is null and new.objet_id is not null and new.statut = 'a_rattacher' then
    new.statut := 'recue';
  end if;
  return new;
end $$;


--
-- Name: preparer_reglages_envois(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preparer_reglages_envois() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is not null then
    if new.mode = 'reel' and (tg_op = 'INSERT' or old.mode is distinct from 'reel')
       and not private.a_un_role(new.client_id, array['gerant']) then
      raise exception 'Le passage en réel se décide par un gérant : c''est la bascule écrite.' using errcode = '42501';
    end if;
    if tg_op = 'INSERT' then
      if new.sante is not null then
        raise exception 'Le contexte de santé se règle par Omega.' using errcode = '42501';
      end if;
    elsif new.sante is distinct from old.sante then
      raise exception 'Le contexte de santé se règle par Omega.' using errcode = '42501';
    end if;
  end if;
  if new.essai_adresse is not null then
    new.essai_adresse := private.normaliser_email(new.essai_adresse);
    if new.essai_adresse is null then
      raise exception 'Adresse d''essai invalide.' using errcode = '22023';
    end if;
  end if;
  if not private.plages_valides(new.plages) then
    raise exception 'Plages invalides : [{"jours":[1,…,7],"debut":"08:00","fin":"19:00"}], heure locale.' using errcode = '22023';
  end if;
  new.maj_le := now();
  new.maj_par := v_uid;
  return new;
end $$;


--
-- Name: prochaine_ouverture(jsonb, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prochaine_ouverture(p_plages jsonb, p_fuseau text, p_territoire text, p_feries boolean, p_instant timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_local timestamp := p_instant at time zone p_fuseau;
  v_jour date;
  v_candidat timestamp;
  v_meilleur timestamp;
  e jsonb;
begin
  if private.ouvert_a(p_plages, p_fuseau, p_territoire, p_feries, p_instant) then
    return p_instant;
  end if;
  for i in 0..15 loop
    v_jour := v_local::date + i;
    if not p_feries and p_territoire is not null then
      continue when public.jour_ferie(v_jour, p_territoire);
    end if;
    v_meilleur := null;
    for e in select x from jsonb_array_elements(p_plages) x loop
      if (e -> 'jours') @> to_jsonb(extract(isodow from v_jour)::int) then
        v_candidat := greatest(v_local, v_jour + (e ->> 'debut')::time);
        if v_candidat < v_jour + (e ->> 'fin')::time and (v_meilleur is null or v_candidat < v_meilleur) then
          v_meilleur := v_candidat;
        end if;
      end if;
    end loop;
    if v_meilleur is not null then
      return v_meilleur at time zone p_fuseau;
    end if;
  end loop;
  return null;
end $$;


--
-- Name: prochaine_relance(public.suivis, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prochaine_relance(p_s public.suivis, p_depart timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_pas interval;
  v_t timestamptz;
  v_jour date;
  v_fuseau text;
begin
  if p_s.relances >= (p_s.plan ->> 'max')::integer then
    return null;
  end if;
  v_pas := case when p_s.relances = 0 then (p_s.plan ->> 'premiere')::interval else (p_s.plan ->> 'cadence')::interval end;
  v_t := p_depart + v_pas;
  v_fuseau := coalesce((select t.fuseau from public.territoires t where t.code = p_s.territoire), p_s.tiers ->> 'fuseau', 'Europe/Paris');
  if p_s.date_promise is not null then
    -- On laisse passer le jour promis : la relance vient au lendemain, pas le jour même.
    v_t := greatest(v_t, ((p_s.date_promise + 1) + time '08:00') at time zone v_fuseau);
  end if;
  if (p_s.plan ->> 'jours_ouvres')::boolean and p_s.territoire is not null
     and (select t.complet from public.territoires t where t.code = p_s.territoire) then
    v_jour := (v_t at time zone v_fuseau)::date;
    for i in 1..30 loop
      exit when public.jour_ouvre(v_jour, p_s.territoire);
      v_jour := v_jour + 1;
    end loop;
    if v_jour <> (v_t at time zone v_fuseau)::date then
      v_t := (v_jour + time '08:00') at time zone v_fuseau;
    end if;
  end if;
  return v_t;
end $$;


--
-- Name: publier_decision(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.publier_decision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.type_action = 'politique.activer' then
    return null;
  end if;
  if (tg_op = 'INSERT' and new.statut = 'approuvee')
     or (tg_op = 'UPDATE' and old.statut = 'en_attente' and new.statut in ('approuvee', 'rejetee', 'expiree')) then
    perform private.publier_evenement(new.client_id, 'demande.decidee.' || new.module,
      jsonb_build_object(
        'demande', new.id, 'statut', new.statut, 'type_action', new.type_action,
        'objet_type', new.objet_type, 'objet_id', new.objet_id, 'entite', new.entite_id,
        'politique', new.politique_id, 'decide_le', new.decide_le,
        'decideurs', (select coalesce(jsonb_agg(jsonb_build_object('user', a.user_id, 'au_nom_de', a.au_nom_de,
                                                                   'decision', a.decision) order by a.decide_le), '[]'::jsonb)
                      from public.approbations a where a.demande_id = new.id)),
      new.id::text || ':' || new.statut);
  end if;
  return null;
end $$;


--
-- Name: publier_envoi(public.envois, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.publier_envoi(p_e public.envois, p_issue text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.publier_evenement(p_e.client_id, 'envoi.' || p_issue || '.' || p_e.module,
    jsonb_build_object('envoi', p_e.id, 'module', p_e.module, 'objet_type', p_e.objet_type, 'objet_id', p_e.objet_id,
                       'canal', p_e.canal, 'mode', p_e.mode, 'statut', p_e.statut, 'verrou', p_e.verrou,
                       'suivi', p_e.suivi_id, 'rang', p_e.rang),
    p_e.id::text || ':' || p_issue);
end $$;


--
-- Name: publier_evenement(uuid, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.publier_evenement(p_client uuid, p_evenement text, p_charge jsonb DEFAULT '{}'::jsonb, p_cle text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record; n integer := 0;
begin
  for r in select a.module, a.genre from private.abonnements a where a.evenement = p_evenement loop
    perform private.deposer_travail(p_client, r.module, r.genre,
      coalesce(p_charge, '{}'::jsonb) || jsonb_build_object('evenement', p_evenement),
      case when p_cle is null then null else p_evenement || ':' || p_cle end, 0::smallint);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: publier_releve(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.publier_releve(p_releve uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b public.branchements;
  v_charge jsonb;
  v_n integer;
begin
  if p_releve is null
     or exists (select 1 from public.instantanes i where i.releve_id = p_releve and i.statut in ('recu', 'en_lecture', 'lu'))
     or not exists (select 1 from public.instantanes i
                    where i.releve_id = p_releve and i.statut in ('a_appliquer', 'applique') and i.publie_le is null) then
    return 0;
  end if;
  select x.* into b from public.branchements x join public.releves r on r.branchement_id = x.id where r.id = p_releve;
  select count(*) into v_n from public.instantanes i where i.releve_id = p_releve and i.publie_le is not null;
  v_charge := jsonb_build_object('releve', p_releve, 'branchement', b.id, 'module', b.module, 'logiciel', b.logiciel,
    'entite', b.entite_id, 'instantanes', (
      select jsonb_agg(jsonb_build_object('instantane', i.id, 'jeu', j.code, 'statut', i.statut, 'lignes', i.lignes,
                                          'ajouts', i.ajouts, 'modifications', i.modifications,
                                          'disparitions', i.disparitions, 'force', i.force)
                       order by j.code nulls last, i.recu_le)
      from public.instantanes i left join public.branchements_jeux j on j.id = i.jeu_id
      where i.releve_id = p_releve));
  update public.instantanes set publie_le = now()
   where releve_id = p_releve and statut in ('a_appliquer', 'applique') and publie_le is null;
  return private.publier_evenement(b.client_id, 'releve.pret.' || b.module, v_charge, p_releve::text || ':' || v_n::text);
end $$;


--
-- Name: purger_lectures(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purger_lectures() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  perform set_config('omega.purge_lectures', 'oui', true);
  delete from public.lectures l
  where l.lu_le < now() - make_interval(days => coalesce(
          (select r.retention_lectures_jours from public.reglages_client r where r.client_id = l.client_id), 365));
  get diagnostics n = row_count;
  perform set_config('omega.purge_lectures', '', true);
  return n;
end $$;


--
-- Name: purger_releves(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purger_releves(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET enable_nestloop TO 'off'
    SET work_mem TO '32MB'
    AS $$
declare
  r record;
  v_lignes integer;
  v_ecarts integer;
  v_etat integer := 0;
  v_n integer;
begin
  delete from public.instantanes_lignes l using public.instantanes i
  where i.id = l.instantane_id
    and (i.statut in ('applique', 'identique', 'remplace', 'ecarte', 'a_classer', 'rejete', 'echec')
         or (i.statut = 'douteux' and i.finalise_le < p_maintenant - interval '35 days'));
  get diagnostics v_lignes = row_count;

  delete from public.instantanes_ecarts e using public.instantanes i
  where i.id = e.instantane_id and i.statut <> 'a_appliquer' and e.cree_le < p_maintenant - interval '35 days';
  get diagnostics v_ecarts = row_count;

  for r in
    select j.id, j.fenetre, b.fuseau from public.branchements_jeux j join public.branchements b on b.id = j.branchement_id
    where j.fenetre ? 'du'
  loop
    delete from public.jeux_lignes s
    where s.jeu_id = r.id
      and private.date_de(s.valeurs ->> (r.fenetre ->> 'colonne'), r.fuseau)
          < (p_maintenant at time zone r.fuseau)::date + (r.fenetre ->> 'du')::integer - 1;
    get diagnostics v_n = row_count;
    if v_n > 0 then
      update public.branchements_jeux set lignes = (select count(*) from public.jeux_lignes s where s.jeu_id = r.id)
       where id = r.id;
      v_etat := v_etat + v_n;
    end if;
  end loop;
  return jsonb_build_object('lignes', v_lignes, 'ecarts', v_ecarts, 'etat', v_etat);
end $$;


--
-- Name: purger_travaux(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purger_travaux() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  delete from public.travaux where etat = 'fait' and fini_le < now() - interval '30 days';
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: rang_niveau(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rang_niveau(p text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p when 'info' then 1 when 'attention' then 2 when 'critique' then 3 end
$$;


--
-- Name: rang_remise(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rang_remise(p text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p when 'remis' then 1 when 'rebond_temporaire' then 2 when 'refuse' then 3 when 'rebond' then 4
                when 'plainte' then 5 else 0 end
$$;


--
-- Name: rappels_propres(integer[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rappels_propres(p_rappels integer[]) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from unnest(coalesce(p_rappels, '{}')) x where x is null or x < 0 or x > 3650) then
    raise exception 'Un rappel se compte en jours avant l''échéance, de 0 à 3650.' using errcode = '22023';
  end if;
  return coalesce((select array_agg(distinct x order by x desc) from unnest(p_rappels) x), '{}');
end $$;


--
-- Name: rapport_du_mois(uuid, date, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rapport_du_mois(p_client uuid, p_mois date, p_lecteur uuid, p_detail boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m0 date := date_trunc('month', p_mois)::date;
  v_m1 date := (date_trunc('month', p_mois) + interval '1 month')::date - 1;
  v_p0 date := (date_trunc('month', p_mois) - interval '1 month')::date;
  v_h0 date := (date_trunc('month', p_mois) - interval '11 months')::date;
  v_nom text;
  i public.indicateurs;
  a_mois record;
  a_prec record;
  a_dep record;
  v_dep_valeur numeric;
  v_prec_valeur numeric;
  v_dep_du date;
  v_dep_au date;
  v_ecart numeric;
  v_rel numeric;
  v_hist jsonb;
  v_sem jsonb;
  v_ent jsonb;
  v_det jsonb;
  v_detail_permis boolean;
  v_bloc jsonb;
  v_indicateurs jsonb := '[]'::jsonb;
  v_silence jsonb := '[]'::jsonb;
  v_codes text[] := '{}';
  v_empreinte text;
begin
  if p_mois is null then
    raise exception 'Un mois est nécessaire.' using errcode = '22023';
  end if;
  select c.nom into v_nom from public.clients c where c.id = p_client;
  if v_nom is null then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;

  for i in
    select ind.* from public.indicateurs ind
    where exists (
        select 1 from public.mesures m
        where m.client_id = p_client and m.indicateur = ind.code and m.version = ind.version
          and (m.mode = 'a_blanc' or private.mesure_mois_de(m.periode_type, m.debut) between v_h0 and v_m0)
          and (p_lecteur is null or private.perimetre_couvre(p_lecteur, p_client, m.entite_id)))
      and (p_lecteur is null or ind.droit_lecture is null
           or private.a_le_droit_pour(p_lecteur, p_client, ind.droit_lecture))
    order by split_part(ind.code, '.', 1), ind.libelle, ind.version
  loop
    select * into a_mois from private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'reel', v_m0, v_m1, p_lecteur);
    select * into a_prec from private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'reel', v_p0, v_m0 - 1, p_lecteur);
    select * into a_dep from private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'a_blanc', null, null, p_lecteur);
    select min(m.debut), max(m.fin) into v_dep_du, v_dep_au
    from public.mesures m
    where m.client_id = p_client and m.indicateur = i.code and m.version = i.version and m.mode = 'a_blanc'
      and (p_lecteur is null or private.perimetre_couvre(p_lecteur, p_client, m.entite_id));

    -- Une somme se compare à durée égale : départ et mois précédent sont
    -- ramenés aux jours mesurés du mois.
    v_dep_valeur := case
      when a_dep.nb = 0 then null
      when i.agregation = 'somme' and a_dep.jours > 0 then
        a_dep.valeur / a_dep.jours * case when a_mois.jours > 0 then a_mois.jours else v_m1 - v_m0 + 1 end
      when i.agregation = 'somme' then null
      else a_dep.valeur end;
    v_prec_valeur := case
      when a_prec.nb = 0 then null
      when i.agregation = 'somme' and a_mois.jours > 0 and a_prec.jours > 0 then a_prec.valeur / a_prec.jours * a_mois.jours
      else a_prec.valeur end;
    v_ecart := case when a_mois.nb > 0 and v_dep_valeur is not null then a_mois.valeur - v_dep_valeur end;
    v_rel := case when v_ecart is not null and v_dep_valeur <> 0 then v_ecart / abs(v_dep_valeur) end;

    select coalesce(jsonb_agg(jsonb_build_object(
             'mois', to_char(h.mois, 'YYYY-MM'), 'libelle', private.point_mois_fr(h.mois),
             'valeur', a.valeur, 'texte', private.mesure_texte(a.valeur, i.unite, i.decimales)) order by h.mois), '[]'::jsonb)
      into v_hist
    from (select g::date as mois from generate_series(v_h0::timestamp, v_m0::timestamp, interval '1 month') g) h
    cross join lateral private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'reel', h.mois,
                                              (h.mois + interval '1 month')::date - 1, p_lecteur) a;

    select coalesce(jsonb_agg(jsonb_build_object(
             'du', b.du, 'au', b.au, 'valeur', a.valeur, 'texte', private.mesure_texte(a.valeur, i.unite, i.decimales),
             'base', a.base) order by b.du), '[]'::jsonb)
      into v_sem
    from (select distinct date_trunc('week', d)::date as lundi
          from generate_series(v_m0::timestamp, v_m1::timestamp, interval '1 day') d) w
    cross join lateral (select greatest(w.lundi, v_m0) as du, least(w.lundi + 6, v_m1) as au) b
    cross join lateral private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'reel', b.du, b.au, p_lecteur,
                                              p_grains => array['jour', 'semaine']) a
    where a.nb > 0;

    select coalesce(jsonb_agg(jsonb_build_object(
             'entite_id', e.entite_id, 'nom', coalesce(en.nom, v_nom), 'valeur', a.valeur,
             'texte', private.mesure_texte(a.valeur, i.unite, i.decimales), 'base', a.base)
             order by e.entite_id is not null, en.nom), '[]'::jsonb)
      into v_ent
    from (select distinct m.entite_id from public.mesures m
          where m.client_id = p_client and m.indicateur = i.code and m.version = i.version and m.mode = 'reel'
            and m.periode_type <> 'libre'
            and (case when m.periode_type = 'semaine' then m.debut + 3 else m.debut end) between v_m0 and v_m1
            and (p_lecteur is null or private.perimetre_couvre(p_lecteur, p_client, m.entite_id))) e
    left join public.entites en on en.client_id = p_client and en.id = e.entite_id
    cross join lateral private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'reel', v_m0, v_m1, p_lecteur,
                                              p_par_entite => true, p_entite => e.entite_id) a;

    v_detail_permis := coalesce(p_detail, true)
                       and (p_lecteur is null or coalesce(i.droit_detail, i.droit_lecture) is null
                            or private.a_le_droit_pour(p_lecteur, p_client, coalesce(i.droit_detail, i.droit_lecture)));
    v_det := null;
    if v_detail_permis then
      select coalesce(jsonb_agg(jsonb_build_object(
               'objet_type', o.objet_type, 'objet_id', o.objet_id, 'libelle', o.libelle, 'valeur', a.valeur,
               'texte', private.mesure_texte(a.valeur, i.unite, i.decimales), 'base', a.base)
               order by o.libelle, o.objet_id), '[]'::jsonb)
        into v_det
      from (select m.objet_type, m.objet_id,
                   (array_agg(m.objet_libelle order by m.debut desc) filter (where m.objet_libelle is not null))[1] as libelle
            from public.mesures m
            where m.client_id = p_client and m.indicateur = i.code and m.version = i.version and m.mode = 'reel'
              and m.objet_id is not null and m.periode_type <> 'libre'
              and (case when m.periode_type = 'semaine' then m.debut + 3 else m.debut end) between v_m0 and v_m1
              and (p_lecteur is null or (private.perimetre_couvre(p_lecteur, p_client, m.entite_id)
                                         and private.voit_objet_pour(p_lecteur, p_client, m.objet_type, m.objet_id)))
            group by m.objet_type, m.objet_id) o
      cross join lateral private.mesure_agregat(p_client, i.code, i.version, i.agregation, 'reel', v_m0, v_m1, p_lecteur,
                                                p_par_objet => true, p_objet_type => o.objet_type, p_objet_id => o.objet_id) a;
    end if;

    v_bloc := jsonb_build_object(
      'code', i.code, 'version', i.version, 'module', split_part(i.code, '.', 1), 'libelle', i.libelle,
      'definition', i.definition, 'formule', i.formule, 'unite', i.unite, 'sens', i.sens,
      'agregation', i.agregation, 'decimales', i.decimales, 'mesure_ce_mois', a_mois.nb > 0,
      'mois', case when a_mois.nb > 0 then jsonb_build_object(
                'valeur', a_mois.valeur, 'texte', private.mesure_texte(a_mois.valeur, i.unite, i.decimales),
                'numerateur', a_mois.numerateur, 'base', a_mois.base, 'nb_mesures', a_mois.nb,
                'jours_mesures', a_mois.jours) end,
      'depart', case when a_dep.nb > 0 then jsonb_build_object(
                  'valeur', v_dep_valeur, 'texte', private.mesure_texte(v_dep_valeur, i.unite, i.decimales),
                  'du', v_dep_du, 'au', v_dep_au, 'nb_mesures', a_dep.nb,
                  'ramene_aux_jours_du_mois', i.agregation = 'somme') end,
      'ecart', case when v_ecart is not null then jsonb_build_object(
                 'valeur', v_ecart, 'texte', private.mesure_texte(v_ecart, i.unite, i.decimales, true),
                 'relatif', v_rel,
                 'relatif_texte', case when v_rel is not null then
                                    case when round(v_rel * 100) > 0 then '+' else '' end
                                    || private.point_nombre_fr(v_rel * 100, 0) || chr(160) || '%' end,
                 'verdict', private.mesure_verdict(v_ecart, i.sens, i.unite, i.decimales)) end,
      'precedent', case when a_prec.nb > 0 then jsonb_build_object(
                     'mois', to_char(v_p0, 'YYYY-MM'), 'valeur', a_prec.valeur,
                     'texte', private.mesure_texte(a_prec.valeur, i.unite, i.decimales),
                     'evolution', case when a_mois.nb > 0
                                       then private.mesure_verdict(a_mois.valeur - v_prec_valeur, i.sens, i.unite, i.decimales) end) end,
      'historique', v_hist, 'semaines', v_sem, 'entites', v_ent)
      || case when v_detail_permis then jsonb_build_object('detail', v_det) else '{}'::jsonb end;

    v_indicateurs := v_indicateurs || jsonb_build_array(v_bloc);
    v_codes := v_codes || (i.code || '#' || i.version);
    if a_mois.nb = 0 and a_prec.nb > 0 then
      v_silence := v_silence || jsonb_build_array(jsonb_build_object('code', i.code, 'version', i.version, 'libelle', i.libelle));
    end if;
  end loop;

  -- L'empreinte des mesures lues : le même mois reconstruit sur les mêmes mesures a la même.
  select encode(sha256(convert_to(coalesce(string_agg(
           m.id::text || ':' || m.valeur::text || ':' || coalesce(m.numerateur::text, '') || ':' || coalesce(m.base::text, ''),
           '|' order by m.id), ''), 'UTF8')), 'hex')
    into v_empreinte
  from public.mesures m
  where m.client_id = p_client and (m.indicateur || '#' || m.version) = any (v_codes)
    and (m.mode = 'a_blanc' or private.mesure_mois_de(m.periode_type, m.debut) between v_h0 and v_m0)
    and (p_lecteur is null or private.perimetre_couvre(p_lecteur, p_client, m.entite_id));

  return jsonb_build_object(
    'client', jsonb_build_object('id', p_client, 'nom', v_nom),
    'mois', to_char(v_m0, 'YYYY-MM'), 'libelle', private.point_mois_fr(v_m0), 'du', v_m0, 'au', v_m1,
    'indicateurs', v_indicateurs, 'non_mesures', v_silence, 'empreinte', v_empreinte);
end $$;


--
-- Name: rapport_du_mois_pour(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rapport_du_mois_pour(p_client uuid, p_mois date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
begin
  if v_uid is not null then
    if not exists (select 1 from public.comptes c where c.user_id = v_uid and c.client_id = p_client) then
      raise exception 'Organisation introuvable.' using errcode = '42501';
    end if;
    return private.rapport_du_mois(p_client, p_mois, v_uid);
  elsif v_role in ('service_role', 'postgres') then
    return private.rapport_du_mois(p_client, p_mois, null);
  end if;
  raise exception 'Le rapport se lit par un membre de l''organisation, ou par le serveur.' using errcode = '42501';
end $$;


--
-- Name: rattacher_membre(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rattacher_membre(p_client uuid, p_email text, p_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role_session text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  v_membre uuid;
begin
  if p_role is null or p_role not in ('gerant', 'admin', 'valideur', 'collaborateur', 'lecteur') then
    raise exception 'Rôle inconnu : %.', coalesce(p_role, 'vide') using errcode = '22023';
  end if;

  if v_uid is null then
    if v_role_session <> 'service_role' then
      raise exception 'Seul un gérant ou un administrateur ajoute un membre.' using errcode = '42501';
    end if;
  elsif not private.a_un_role(p_client, array['gerant', 'admin']) then
    raise exception 'Seul un gérant ou un administrateur ajoute un membre.' using errcode = '42501';
  elsif p_role = 'gerant' and not private.a_un_role(p_client, array['gerant']) then
    raise exception 'Seul un gérant nomme un autre gérant.' using errcode = '42501';
  end if;

  select u.id into v_membre
  from auth.users u
  where lower(u.email) = lower(btrim(p_email))
  limit 1;
  if v_membre is null then
    raise exception 'Aucun compte pour cette adresse.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.comptes c where c.client_id = p_client and c.user_id = v_membre) then
    raise exception 'Cette personne est déjà membre de l''organisation.' using errcode = '23505';
  end if;

  insert into public.comptes (user_id, client_id, role) values (v_membre, p_client, p_role);
  return v_membre;
end $$;


--
-- Name: recevoir_releve(uuid, jsonb, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.recevoir_releve(p_branchement uuid, p_fichiers jsonb, p_canal text DEFAULT 'depot'::text, p_cle text DEFAULT NULL::text, p_expediteur text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  b public.branchements;
  j public.branchements_jeux;
  f jsonb;
  v_releve uuid;
  v_rel uuid;
  v_par_jeu jsonb := '{}'::jsonb;
  v_prefixe text;
  v_piece uuid;
  v_courant uuid;
  v_id uuid;
  v_jeu uuid;
  v_recu timestamptz;
  v_statut text;
  v_res jsonb := '[]'::jsonb;
begin
  select * into b from public.branchements where id = p_branchement;
  if not found then
    raise exception 'Branchement introuvable.' using errcode = 'P0002';
  end if;
  if b.statut <> 'actif' then
    raise exception 'Le branchement « % » est %.', b.libelle, b.statut using errcode = '55000';
  end if;
  if p_fichiers is null or jsonb_typeof(p_fichiers) <> 'array' or jsonb_array_length(p_fichiers) = 0 then
    raise exception 'Un relevé porte au moins un fichier.' using errcode = '22023';
  end if;
  if p_cle is not null then
    select r.id into v_releve from public.releves r where r.branchement_id = b.id and r.cle = p_cle;
    if found then
      return private.resume_releve(v_releve) || jsonb_build_object('deja_recu', true);
    end if;
  end if;

  insert into public.releves (client_id, branchement_id, canal, cle, expediteur)
  values (b.client_id, b.id, p_canal, p_cle, left(p_expediteur, 320))
  returning id into v_releve;
  -- Le rangement du socle : <client>/branchement/<id>/… (l'effacement de l'objet le suit).
  v_prefixe := b.client_id::text || '/branchement/' || b.id::text || '/';

  for f in select * from jsonb_array_elements(p_fichiers) loop
    if jsonb_typeof(f) <> 'object' or coalesce(f ->> 'sha256', '') !~ '^[0-9a-f]{64}$'
       or nullif(btrim(f ->> 'nom_fichier'), '') is null or not starts_with(coalesce(f ->> 'chemin', ''), v_prefixe) then
      raise exception 'Fichier mal décrit : nom, empreinte SHA-256 et chemin sous « % » sont nécessaires.', v_prefixe
        using errcode = '22023';
    end if;
    j := null;
    if f ->> 'jeu' is not null then
      select * into j from public.branchements_jeux x where x.branchement_id = b.id and x.code = f ->> 'jeu';
      if not found or not j.actif then
        raise exception 'Jeu inconnu ou inactif pour ce branchement : %.', f ->> 'jeu' using errcode = '22023';
      end if;
    end if;
    if f -> 'fenetre' is not null and f -> 'fenetre' <> 'null'::jsonb
       and not (f -> 'fenetre' ? 'colonne') and (j.id is null or j.fenetre is null) then
      raise exception 'Une fenêtre de fichier nomme sa colonne, ou suit celle de son jeu.' using errcode = '22023';
    end if;
    if f -> 'perimetre' is not null and f -> 'perimetre' <> 'null'::jsonb and j.id is not null and j.colonnes <> '{}'::jsonb
       and exists (select 1 from jsonb_object_keys(f -> 'perimetre') k
                   where not (j.colonnes ? k) or j.colonnes -> k -> 'sensible' = 'true'::jsonb) then
      raise exception 'Un périmètre ne porte que sur des colonnes déclarées et non sensibles.' using errcode = '22023';
    end if;

    -- Le même contenu déjà en cours sur ce branchement : on ne le lit pas deux fois.
    select i.id, i.statut into v_id, v_statut from public.instantanes i
    where i.branchement_id = b.id and i.sha256 = f ->> 'sha256' and i.statut in ('recu', 'en_lecture', 'lu', 'a_appliquer')
      and (j.id is null or i.jeu_id is null or i.jeu_id = j.id)
    order by i.recu_le desc
    limit 1;
    if found then
      v_res := v_res || jsonb_build_array(jsonb_build_object('instantane', v_id, 'nom_fichier', f ->> 'nom_fichier',
                                                             'statut', v_statut, 'deja_recu', true));
      continue;
    end if;

    -- La pièce : une par contenu et par branchement ; elle ne passe jamais par le lecteur de pièces.
    select p.id into v_piece from public.pieces p
    where p.client_id = b.client_id and p.module = b.module and p.objet_type = 'branchement'
      and p.objet_id = b.id::text and p.sha256 = f ->> 'sha256';
    if not found then
      insert into public.pieces (client_id, module, objet_type, objet_id, source, expediteur, nom_fichier, mime, octets,
                                 sha256, chemin, statut, type_piece, confiance_type, methode)
      values (b.client_id, b.module, 'branchement', b.id::text, 'export', left(p_expediteur, 320), left(f ->> 'nom_fichier', 255),
              left(coalesce(nullif(f ->> 'mime', ''), 'application/octet-stream'), 120), coalesce((f ->> 'octets')::bigint, 0),
              f ->> 'sha256', f ->> 'chemin', 'en_lecture', 'export', 1, 'tableur')
      returning id into v_piece;
    end if;

    -- Un seul export par jeu dans un relevé : le second fait son propre relevé.
    v_rel := v_releve;
    if j.id is not null then
      if v_par_jeu ? j.id::text then
        insert into public.releves (client_id, branchement_id, canal, expediteur)
        values (b.client_id, b.id, p_canal, left(p_expediteur, 320))
        returning id into v_rel;
      end if;
      v_par_jeu := v_par_jeu || jsonb_build_object(j.id::text, v_rel);
    end if;

    v_courant := case when f -> 'complet' is null and f -> 'fenetre' is null and f -> 'perimetre' is null
                      then private.identique_au_courant(b.id, j.id, f ->> 'sha256') end;
    if v_courant is not null then
      -- Copie exacte de l'état : rien à lire, l'état est confirmé.
      insert into public.instantanes (client_id, releve_id, branchement_id, jeu_id, piece_id, nom_fichier, sha256, octets,
                                      statut, base_id, lignes, lignes_base, ajouts, modifications, disparitions, absences,
                                      lu_le, finalise_le)
      select b.client_id, v_rel, b.id, c.jeu_id, v_piece, left(f ->> 'nom_fichier', 255), f ->> 'sha256',
             (f ->> 'octets')::bigint, 'identique', c.id, c.lignes, x.lignes, 0, 0, 0, 0, now(), now()
      from public.instantanes c join public.branchements_jeux x on x.id = c.jeu_id
      where c.id = v_courant
      returning id, jeu_id, statut, recu_le into v_id, v_jeu, v_statut, v_recu;
      perform private.jeu_vu(v_jeu, v_recu);
      perform private.confirmer_etat(v_jeu, v_recu);
    else
      insert into public.instantanes (client_id, releve_id, branchement_id, jeu_id, piece_id, nom_fichier, sha256, octets,
                                      complet, fenetre, perimetre)
      values (b.client_id, v_rel, b.id, j.id, v_piece, left(f ->> 'nom_fichier', 255), f ->> 'sha256', (f ->> 'octets')::bigint,
              (f ->> 'complet')::boolean, nullif(f -> 'fenetre', 'null'::jsonb), nullif(f -> 'perimetre', 'null'::jsonb))
      returning id, statut, recu_le into v_id, v_statut, v_recu;
      perform private.deposer_travail(b.client_id, b.module, 'releve.lire', jsonb_build_object('instantane', v_id),
                                      'instantane:' || v_id::text, 0::smallint);
      if j.id is not null then
        perform private.jeu_vu(j.id, v_recu);
      end if;
    end if;
    v_res := v_res || jsonb_build_array(jsonb_build_object('instantane', v_id, 'nom_fichier', f ->> 'nom_fichier',
                                                           'statut', v_statut));
  end loop;
  return jsonb_build_object('releve', v_releve, 'instantanes', v_res);
end $_$;


--
-- Name: reglages_envois_effectifs(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reglages_envois_effectifs(p_client uuid, p_module text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.reglages_envois;
  m public.reglages_envois;
begin
  select * into c from public.reglages_envois r where r.client_id = p_client and r.module is null;
  select * into m from public.reglages_envois r where r.client_id = p_client and r.module = p_module;
  return jsonb_build_object(
    'mode', case when c.mode = 'coupe' or m.mode = 'coupe' then 'coupe'
                 when m.mode is null then null
                 when c.mode = 'essai' or m.mode = 'essai' then 'essai'
                 else 'reel' end,
    'essai_adresse', coalesce(m.essai_adresse, c.essai_adresse),
    'plages', coalesce(m.plages, c.plages, '[{"jours":[1,2,3,4,5],"debut":"08:00","fin":"19:00"}]'::jsonb),
    'feries', coalesce(m.feries, c.feries, false),
    'delai_min', coalesce(m.delai_min, c.delai_min, interval '3 days'),
    'plafond_destinataire_jour', coalesce(m.plafond_destinataire_jour, c.plafond_destinataire_jour, 5),
    'plafond_jour', coalesce(m.plafond_jour, 200),
    'plafond_jour_organisation', coalesce(c.plafond_jour, 500),
    'fenetre_doublon', coalesce(m.fenetre_doublon, c.fenetre_doublon, interval '7 days'),
    'canaux_organisation', to_jsonb(c.canaux),
    'canaux_module', to_jsonb(m.canaux),
    'pause_reponse', coalesce(m.pause_reponse, c.pause_reponse, interval '14 days'),
    'pause_sensible', coalesce(m.pause_sensible, c.pause_sensible, interval '30 days'),
    'sante', coalesce(c.sante, false) or coalesce(m.sante, false));
end $$;


--
-- Name: regler_battement(uuid, text, interval, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.regler_battement(p_client uuid, p_module text, p_attendu interval, p_plages jsonb DEFAULT NULL::jsonb, p_fuseau text DEFAULT 'Europe/Paris'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.battements as b (client_id, module, attendu_toutes, plages, fuseau)
  values (p_client, p_module, p_attendu, p_plages, p_fuseau)
  on conflict (client_id, module) do update
    set attendu_toutes = excluded.attendu_toutes, plages = excluded.plages, fuseau = excluded.fuseau;
end $$;


--
-- Name: regler_branchement(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.regler_branchement(p_branchement uuid, p_reglages jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b public.branchements;
  p jsonb := coalesce(p_reglages, '{}'::jsonb);
begin
  select * into b from public.branchements where id = p_branchement for update;
  if not found then
    raise exception 'Branchement introuvable.' using errcode = 'P0002';
  end if;
  perform private.exiger_gestion_releve(b.client_id, b.entite_id);
  if jsonb_typeof(p) <> 'object' or exists (select 1 from jsonb_object_keys(p) k where k not in ('libelle', 'statut', 'voie', 'fuseau')) then
    raise exception 'Réglages possibles : libelle, statut, voie, fuseau.' using errcode = '22023';
  end if;
  update public.branchements set
    libelle = coalesce(p ->> 'libelle', libelle),
    statut = coalesce(p ->> 'statut', statut),
    voie = coalesce(p ->> 'voie', voie),
    fuseau = coalesce(p ->> 'fuseau', fuseau),
    maj_le = now()
  where id = b.id;
end $$;


--
-- Name: relancer_suivi(public.suivis, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.relancer_suivi(p_s public.suivis, p_maintenant timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s public.suivis := p_s;
  v_envoi uuid;
  v_vars jsonb;
  v_rang smallint := p_s.relances + 1;
begin
  if s.plan ->> 'gabarit' is null then
    -- Sans gabarit, le module relance à sa façon : il est prévenu, rien ne part d'ici.
    update public.suivis
       set relances = relances + 1, derniere_relance_le = p_maintenant
     where id = s.id returning * into s;
    update public.suivis set prochaine_relance_le = private.prochaine_relance(s, p_maintenant) where id = s.id returning * into s;
    perform private.noter_evenement_suivi(s, 'relance', s.date_promise, null, jsonb_build_object('rang', v_rang, 'par_le_module', true));
    perform private.publier_evenement(s.client_id, 'suivi.relance.' || s.module,
      jsonb_build_object('suivi', s.id, 'module', s.module, 'objet_type', s.objet_type, 'objet_id', s.objet_id,
                         'rang', v_rang, 'attendu', s.attendu, 'tiers', s.tiers, 'date_promise', s.date_promise,
                         'glissements', s.glissements, 'envoi', null),
      s.id::text || ':relance:' || v_rang::text);
    return null;
  end if;

  v_vars := coalesce(s.plan -> 'variables', '{}'::jsonb);
  v_envoi := private.creer_envoi(
    s.client_id, s.module, s.objet_type, s.objet_id, s.plan ->> 'canal', s.tiers,
    s.plan ->> 'gabarit', v_vars, null, null, null,
    'suivi:' || s.id::text || ':' || v_rang::text, s.entite_id,
    (s.plan ->> 'transactionnel')::boolean, false,
    greatest(p_maintenant, now()) + least((s.plan ->> 'cadence')::interval, interval '7 days'),
    false, null, null, null, null, s.id, v_rang);
  update public.suivis
     set relances = relances + 1, derniere_relance_le = p_maintenant
   where id = s.id returning * into s;
  update public.suivis set prochaine_relance_le = private.prochaine_relance(s, p_maintenant) where id = s.id returning * into s;
  perform private.noter_evenement_suivi(s, 'relance', s.date_promise, v_envoi,
    jsonb_build_object('rang', v_rang, 'canal', s.plan ->> 'canal', 'gabarit', s.plan ->> 'gabarit'));
  perform private.publier_evenement(s.client_id, 'suivi.relance.' || s.module,
    jsonb_build_object('suivi', s.id, 'module', s.module, 'objet_type', s.objet_type, 'objet_id', s.objet_id,
                       'rang', v_rang, 'attendu', s.attendu, 'date_promise', s.date_promise, 'glissements', s.glissements,
                       'envoi', v_envoi, 'envoi_statut', (select e.statut from public.envois e where e.id = v_envoi)),
    s.id::text || ':relance:' || v_rang::text);
  return v_envoi;
end $$;


--
-- Name: rendre_gabarit(public.gabarits_messages, jsonb, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rendre_gabarit(p_g public.gabarits_messages, p_variables jsonb, p_client uuid, p_entite uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vars jsonb := coalesce(p_variables, '{}'::jsonb);
  v_valeurs jsonb := '{}'::jsonb;
  v_sujet text := p_g.sujet;
  v_corps text := p_g.corps;
  v_cle text;
  v_type text;
  v_libre boolean := false;
begin
  if jsonb_typeof(v_vars) <> 'object' then
    raise exception 'Les variables d''un gabarit forment un objet JSON.' using errcode = '22023';
  end if;
  for v_cle in select jsonb_object_keys(v_vars) loop
    if not (p_g.variables ? v_cle) then
      raise exception 'Variable inconnue du gabarit % : « % ».', p_g.code, v_cle using errcode = '22023';
    end if;
  end loop;
  for v_cle, v_type in select e.key, e.value #>> '{}' from jsonb_each(p_g.variables) e loop
    v_valeurs := v_valeurs || jsonb_build_object(v_cle, private.formater_variable(v_type, v_vars -> v_cle, v_cle));
    v_libre := v_libre or v_type = 'texte';
  end loop;
  v_valeurs := v_valeurs || jsonb_build_object(
    'organisation', coalesce((select c.nom from public.clients c where c.id = p_client), ''),
    'entite', coalesce((select e.nom from public.entites e where e.client_id = p_client and e.id = p_entite),
                       (select e.nom from public.entites e where e.client_id = p_client and e.principale), ''));
  for v_cle in select jsonb_object_keys(v_valeurs) loop
    v_sujet := replace(v_sujet, '{{' || v_cle || '}}', v_valeurs ->> v_cle);
    v_corps := replace(v_corps, '{{' || v_cle || '}}', v_valeurs ->> v_cle);
  end loop;
  return jsonb_build_object(
    'sujet', v_sujet, 'corps', v_corps, 'texte_libre', v_libre,
    'parametres', (select coalesce(jsonb_agg(v_valeurs -> x.nom order by x.n), '[]'::jsonb)
                   from unnest(private.variables_du_texte(p_g.corps)) with ordinality as x(nom, n)));
end $$;


--
-- Name: renvoyer_point(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.renvoyer_point(p_point uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  p public.points_du_jour;
  v_etat text;
begin
  select * into p from public.points_du_jour x where x.id = p_point for update;
  if not found then
    raise exception 'Point introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is not null then
    if p.user_id <> v_uid and not private.a_un_role(p.client_id, array['gerant', 'admin']) then
      raise exception 'Point introuvable.' using errcode = 'P0002';
    end if;
  elsif v_role not in ('service_role', 'postgres') then
    raise exception 'Point introuvable.' using errcode = 'P0002';
  end if;
  if p.statut in ('vide', 'perime') then
    raise exception 'Ce point ne se renvoie pas (%).', p.statut using errcode = '22023';
  end if;
  if not private.point_b4_present() then
    raise exception 'L''envoi n''est pas encore branché : le point reste prêt, lisible dans l''espace.' using errcode = '55000';
  end if;
  if p.jour < (now() at time zone p.fuseau)::date then
    raise exception 'Le point d''un jour passé ne se renvoie pas : il se lit dans l''espace.' using errcode = '22023';
  end if;
  update public.points_du_jour set statut = 'pret', version = version + 1, envoi_id = null, remis_le = null, motif_echec = null
  where id = p.id;
  if v_uid is not null then
    return null;
  end if;
  v_etat := private.point_remettre(p.id);
  if v_etat <> 'remis' then
    raise exception 'Le renvoi a échoué : %.', coalesce((select x.motif_echec from public.points_du_jour x where x.id = p.id), v_etat)
      using errcode = '55000';
  end if;
  return (select x.envoi_id from public.points_du_jour x where x.id = p.id);
end $$;


--
-- Name: resoudre_destinataire(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resoudre_destinataire(p_client uuid, p_canal text, p_destinataire jsonb, p_entite uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  d jsonb := p_destinataire;
  v_forme text := (select c.adresse from private.canaux_envoi c where c.canal = p_canal);
  v_cle text;
  v_membre uuid;
  v_email text;
  v_tel text;
  v_adresse text;
  v_manque text;
  v_fuseau text;
  v_territoire text;
  v_entite uuid;
  v_fuseau_entite text;
  v_territoire_entite text;
  v_numero jsonb;
begin
  if d is null or jsonb_typeof(d) <> 'object' then
    raise exception 'Le destinataire est un objet JSON : {"membre": …} ou {"adresse": …}.' using errcode = '22023';
  end if;
  for v_cle in select jsonb_object_keys(d) loop
    if v_cle not in ('membre', 'adresse', 'nom', 'ref', 'fuseau', 'territoire', 'professionnel', 'langue') then
      raise exception 'Clé inconnue dans le destinataire : « % ».', v_cle using errcode = '22023';
    end if;
  end loop;
  if (d ? 'membre') = (d ? 'adresse') then
    raise exception 'Le destinataire est un membre de l''organisation ou une adresse, l''un ou l''autre.' using errcode = '22023';
  end if;

  if d ? 'membre' then
    begin
      v_membre := (d ->> 'membre')::uuid;
    exception when others then
      raise exception 'Le membre se désigne par son identifiant.' using errcode = '22023';
    end;
    if not exists (select 1 from public.comptes c where c.client_id = p_client and c.user_id = v_membre) then
      raise exception 'Ce membre n''appartient pas à l''organisation.' using errcode = '22023';
    end if;
    select u.email, u.phone into v_email, v_tel from auth.users u where u.id = v_membre;
    v_adresse := case v_forme
      when 'email' then private.normaliser_email(v_email)
      else private.normaliser_telephone(case when nullif(v_tel, '') is null then null else '+' || ltrim(v_tel, '+') end) end;
    if v_adresse is null then
      v_manque := case v_forme when 'email' then 'Ce membre n''a pas d''adresse électronique valide.'
                               else 'Ce membre n''a pas de numéro de téléphone valide.' end;
    end if;
  else
    v_adresse := private.normaliser_adresse(p_canal, d ->> 'adresse');
    if v_adresse is null then
      raise exception 'Adresse invalide pour le canal %.', p_canal using errcode = '22023';
    end if;
  end if;

  -- Le fuseau et le calendrier du destinataire, dans cet ordre : ceux que l'on
  -- donne ; sinon ceux que dit son numéro (l'outre-mer a son indicatif) ;
  -- sinon ceux de l'entité qui écrit. Le calendrier de l'entité ne vaut que si
  -- le destinataire est à la même heure. Jamais la métropole supposée.
  select e.id, e.fuseau into v_entite, v_fuseau_entite from public.entites e
  where e.client_id = p_client and (e.id = p_entite or (p_entite is null and e.principale));
  v_territoire_entite := private.territoire_de_entite(p_client, v_entite);
  if d ? 'territoire' then
    select t.code, t.fuseau into v_territoire, v_fuseau from public.territoires t where t.code = d ->> 'territoire';
    if v_territoire is null then
      raise exception 'Territoire inconnu : %.', d ->> 'territoire' using errcode = '22023';
    end if;
  end if;
  if d ? 'fuseau' then
    if not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = d ->> 'fuseau') then
      raise exception 'Fuseau horaire inconnu : %.', d ->> 'fuseau' using errcode = '22023';
    end if;
    v_fuseau := d ->> 'fuseau';
    v_territoire := coalesce(v_territoire, private.territoire_du_fuseau(v_fuseau));
  end if;
  if v_fuseau is null and v_forme = 'telephone' and v_adresse is not null then
    v_numero := private.fuseau_du_numero(v_adresse);
    v_fuseau := v_numero ->> 'fuseau';
    v_territoire := v_numero ->> 'territoire';
  end if;
  if v_fuseau is null then
    v_fuseau := coalesce(v_fuseau_entite, 'Europe/Paris');
  end if;
  if v_territoire is null
     and (select t.fuseau from public.territoires t where t.code = v_territoire_entite) = v_fuseau then
    v_territoire := v_territoire_entite;
  end if;
  if d ? 'langue' and coalesce(d ->> 'langue', '') !~ '^[a-z]{2}$' then
    raise exception 'La langue du destinataire s''écrit en deux lettres (fr, en…).' using errcode = '22023';
  end if;
  if d ? 'professionnel' and jsonb_typeof(d -> 'professionnel') <> 'boolean' then
    raise exception '« professionnel » vaut true ou false.' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'adresse', v_adresse,
    'nom', left(nullif(btrim(d ->> 'nom'), ''), 200),
    'ref', left(nullif(btrim(d ->> 'ref'), ''), 200),
    'membre', v_membre,
    'fuseau', v_fuseau,
    'territoire', v_territoire,
    'professionnel', coalesce((d ->> 'professionnel')::boolean, v_membre is not null),
    'langue', coalesce(d ->> 'langue', 'fr'),
    'manque', v_manque);
end $_$;


--
-- Name: resume_releve(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resume_releve(p_releve uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object('releve', p_releve, 'instantanes', coalesce((
    select jsonb_agg(jsonb_build_object('instantane', i.id, 'nom_fichier', i.nom_fichier, 'statut', i.statut,
                                        'jeu', (select j.code from public.branchements_jeux j where j.id = i.jeu_id))
                     order by i.recu_le, i.nom_fichier)
    from public.instantanes i
    where i.releve_id = p_releve), '[]'::jsonb))
$$;


--
-- Name: retirer_consentement(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.retirer_consentement(p_consentement uuid, p_motif text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  k public.consentements;
begin
  select * into k from public.consentements where id = p_consentement;
  if k.id is null then
    raise exception 'Accord introuvable.' using errcode = 'P0002';
  end if;
  perform private.exiger_reglage_destinataire(k.client_id, k.adresse);
  update public.consentements set retire_le = now(), motif_retrait = left(coalesce(p_motif, 'Retiré.'), 300)
   where id = p_consentement and retire_le is null;
end $$;


--
-- Name: retirer_gabarit(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.retirer_gabarit(p_gabarit uuid, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.exiger_ouvrier();
  if nullif(btrim(p_motif), '') is null then
    raise exception 'Retirer un gabarit dit pourquoi.' using errcode = '22023';
  end if;
  update public.gabarits_messages set statut = 'retire', retire_le = now(), motif_retrait = left(p_motif, 300)
   where id = p_gabarit and statut = 'valide';
  if not found then
    raise exception 'Gabarit introuvable, ou pas validé.' using errcode = 'P0002';
  end if;
end $$;


--
-- Name: retirer_section(uuid, text, date, uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.retirer_section(p_client uuid, p_module text, p_jour date, p_destinataire uuid, p_role text, p_titre text, p_entite uuid DEFAULT NULL::uuid, p_equipe uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n integer;
begin
  delete from public.points_sections s
  where s.client_id = p_client and s.module = p_module and s.jour = p_jour
    and s.destinataire is not distinct from p_destinataire and s.role is not distinct from p_role
    and s.equipe_id is not distinct from p_equipe and s.entite_id is not distinct from p_entite
    and s.titre = btrim(p_titre);
  get diagnostics n = row_count;
  return n > 0;
end $$;


--
-- Name: revoquer_accords_interdits(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.revoquer_accords_interdits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.politiques
     set statut = 'revoquee', revoquee_le = now(),
         motif_revocation = left('Action réservée à une décision par personne : ' || new.motif, 500)
   where module = new.module and type_action = new.type_action and statut in ('a_valider', 'active');
  return null;
end $$;


--
-- Name: revoquer_politique(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.revoquer_politique(p_politique uuid, p_motif text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
  v_p public.politiques;
begin
  select * into v_p from public.politiques where id = p_politique for update;
  if not found or (v_uid is not null and not exists (
        select 1 from public.comptes c where c.user_id = v_uid and c.client_id = v_p.client_id)) then
    raise exception 'Accord introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is not null then
    if not private.a_un_role(v_p.client_id, array['gerant', 'admin']) then
      raise exception 'Seul un gérant ou un administrateur révoque un accord permanent.' using errcode = '42501';
    end if;
  elsif v_role <> 'service_role' then
    raise exception 'Seul un gérant ou un administrateur révoque un accord permanent.' using errcode = '42501';
  end if;
  if v_p.statut not in ('a_valider', 'active') then
    raise exception 'Cet accord n''est plus en vigueur (%).', v_p.statut using errcode = '23514';
  end if;

  update public.politiques
     set statut = 'revoquee', revoquee_le = now(), revoquee_par = v_uid, motif_revocation = left(p_motif, 500)
   where id = p_politique;
  update public.demandes_validation set statut = 'annulee'
   where id = v_p.demande_id and statut = 'en_attente';
end $$;


--
-- Name: secret_expediteur(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.secret_expediteur(p_envoi uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_nom text;
begin
  perform private.exiger_ouvrier();
  select x.secret_nom into v_nom
  from public.envois e join public.expediteurs x on x.client_id = e.client_id and x.id = e.expediteur_id
  where e.id = p_envoi and e.statut = 'en_cours' and e.mode = 'reel';
  if v_nom is null then
    return null;
  end if;
  return (select s.decrypted_secret from vault.decrypted_secrets s where s.name = v_nom limit 1);
end $$;


--
-- Name: signature_releve(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.signature_releve(p_par text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_entetes jsonb;
  v_nom text;
begin
  if v_uid is not null then
    return coalesce((select u.email from auth.users u where u.id = v_uid), v_uid::text);
  end if;
  begin
    v_entetes := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    v_entetes := null;
  end;
  v_nom := coalesce(nullif(btrim(p_par), ''), nullif(current_setting('omega.operateur', true), ''),
                    nullif(v_entetes ->> 'x-omega-operateur', ''));
  if v_nom is null then
    raise exception 'Une décision sur un relevé est toujours signée : qui tranche ?' using errcode = '22023';
  end if;
  perform set_config('omega.operateur', left(v_nom, 120), true);
  return 'operateur ' || left(v_nom, 120);
end $$;


--
-- Name: signer_acquittement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.signer_acquittement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.acquittee_le is distinct from old.acquittee_le then new.acquittee_par := (select auth.uid()); end if;
  return new;
end $$;


--
-- Name: suivis_piece_recue(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.suivis_piece_recue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s public.suivis;
  r record;
begin
  if new.objet_id is null or new.statut not in ('recue', 'lue', 'a_verifier', 'a_classer', 'en_lecture') then
    return null;
  end if;
  if tg_op = 'UPDATE' and old.objet_id is not distinct from new.objet_id and old.statut = new.statut then
    return null;
  end if;
  for s in
    select x.* from public.suivis x
    where x.client_id = new.client_id and x.objet_type = new.objet_type and x.objet_id = new.objet_id
      and x.statut = 'ouvert' and x.nature = 'piece'
      and (x.type_piece is null or x.type_piece = new.type_piece)
    order by (x.type_piece is not null) desc, x.depuis
    for update skip locked
  loop
    -- Une pièce typée clôt le suivi qui attend ce type ; une pièce sans type
    -- encore lue ne clôt qu'un suivi qui n'exige aucun type.
    if s.type_piece is not null and new.type_piece is null then
      continue;
    end if;
    update public.suivis
       set statut = 'recu', issue = 'Pièce reçue.', piece_id = new.id, clos_le = now(), prochaine_relance_le = null
     where id = s.id returning * into s;
    for r in select e.id from public.envois e where e.suivi_id = s.id and e.statut in ('a_valider', 'differe', 'pret') loop
      perform private.clore_envoi(r.id, 'annule', 'ANNULE', 'La pièce attendue est arrivée : la relance n''a plus lieu d''être.');
    end loop;
    perform private.noter_evenement_suivi(s, 'cloture', null, null,
      jsonb_build_object('issue', 'piece_recue', 'statut', 'recu', 'piece', new.id, 'relances', s.relances,
                         'glissements', s.glissements, 'age_jours', extract(day from (now() - s.depuis))));
    perform private.publier_evenement(s.client_id, 'suivi.clos.' || s.module,
      jsonb_build_object('suivi', s.id, 'module', s.module, 'objet_type', s.objet_type, 'objet_id', s.objet_id,
                         'statut', 'recu', 'issue', 'piece_recue', 'piece', new.id, 'relances', s.relances, 'glissements', s.glissements),
      s.id::text || ':clos');
    exit;   -- une pièce ne clôt qu'un suivi
  end loop;
  return null;
end $$;


--
-- Name: suivre_activation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.suivre_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.type_action <> 'politique.activer' or new.objet_type is distinct from 'politique'
     or new.statut is not distinct from old.statut then
    return null;
  end if;
  if new.statut = 'approuvee' then
    update public.politiques set statut = 'active', active_le = now()
    where id = new.objet_id::uuid and client_id = new.client_id and statut = 'a_valider';
    update public.demandes_validation set statut = 'executee' where id = new.id;
  elsif new.statut in ('rejetee', 'expiree', 'annulee') then
    update public.politiques set statut = case when new.statut = 'annulee' then 'revoquee' else 'refusee' end
    where id = new.objet_id::uuid and client_id = new.client_id and statut = 'a_valider';
  end if;
  return null;
end $$;


--
-- Name: tableau_texte(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tableau_texte(p jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p is null or p = 'null'::jsonb then
    return null;
  end if;
  if jsonb_typeof(p) <> 'array' or exists (select 1 from jsonb_array_elements(p) e where jsonb_typeof(e) <> 'string') then
    raise exception 'Une liste de textes est attendue : %.', left(p::text, 80) using errcode = '22023';
  end if;
  return array(select jsonb_array_elements_text(p));
end $$;


--
-- Name: tache_chien_de_garde(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tache_chien_de_garde() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_alertes integer; v_files integer; v_expirees integer; v_envoyees integer;
begin
  v_alertes := private.controler_battements();
  v_files := private.controler_travaux();
  v_expirees := private.expirer_demandes();
  v_envoyees := private.envoyer_alertes();
  return jsonb_build_object('alertes_levees', v_alertes, 'files_en_retard', v_files,
                            'demandes_expirees', v_expirees, 'alertes_envoyees', v_envoyees);
end $$;


--
-- Name: tache_envois(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tache_envois(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  e public.envois;
  v_expires integer := 0;
  v_repris integer := 0;
  v_liberes integer := 0;
  v_confies integer := 0;
begin
  -- L'échéance passée : l'envoi n'a plus lieu d'être.
  for r in
    select x.id from public.envois x
    where (x.statut in ('a_valider', 'differe', 'pret') and x.echeance <= p_maintenant)
       or (x.statut = 'en_cours' and x.bail_jusqu_au < p_maintenant and x.echeance <= p_maintenant)
    order by x.echeance limit 1000
  loop
    if private.clore_envoi(r.id, 'expire', 'ECHEANCE', 'L''échéance de cet envoi est passée avant son départ.') then
      v_expires := v_expires + 1;
    end if;
  end loop;
  -- L'heure est venue pour les envois différés.
  for r in
    select x.id from public.envois x
    where x.statut = 'differe' and x.reprise_le <= p_maintenant
    order by x.reprise_le limit 1000
  loop
    perform private.envoi_valide(r.id, p_maintenant);
    v_repris := v_repris + 1;
  end loop;
  -- Un envoi manuel ouvert puis laissé redevient à faire.
  update public.envois set statut = 'pret', bail_jusqu_au = null
   where statut = 'en_cours' and fournisseur = 'manuel' and bail_jusqu_au < p_maintenant;
  get diagnostics v_liberes = row_count;
  -- Un envoi prêt chez un fournisseur branché a toujours son travail.
  for e in
    select x.* from public.envois x
    join private.fournisseurs_envoi f on f.fournisseur = x.fournisseur and f.automatique and f.branche
    where x.statut = 'pret'
      and not exists (select 1 from public.travaux t
                      where t.genre = 'envois.' || x.fournisseur and t.cle = 'envoi:' || x.id::text
                        and t.etat in ('a_faire', 'en_cours'))
    limit 1000
  loop
    perform private.confier_envoi(e);
    v_confies := v_confies + 1;
  end loop;
  return jsonb_build_object('expires', v_expires, 'repris', v_repris, 'liberes', v_liberes, 'confies', v_confies);
end $$;


--
-- Name: tamila_ajouter_audience(uuid, timestamp with time zone, text, text, text, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_ajouter_audience(p_dossier uuid, p_date_heure timestamp with time zone, p_nature text DEFAULT 'audience'::text, p_juridiction text DEFAULT NULL::text, p_chambre text DEFAULT NULL::text, p_avocat uuid DEFAULT NULL::uuid, p_heure_connue boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_id uuid;
begin
  v_d := private.tamila_dossier_ecrit(p_dossier, false);
  if p_date_heure is null then
    raise exception 'La date de l''audience est nécessaire.' using errcode = '22023';
  end if;
  if p_avocat is not null and not private.tamila_est_avocat(p_avocat, v_d.client_id) then
    raise exception 'L''avocat de l''audience est un avocat du cabinet.' using errcode = '22023';
  end if;
  insert into public.tamila_audiences (client_id, dossier_id, date_heure, heure_connue, nature, juridiction, chambre, avocat_id,
                                       source, cree_par)
  values (v_d.client_id, p_dossier, p_date_heure, coalesce(p_heure_connue, true), coalesce(p_nature, 'audience'),
          coalesce(p_juridiction, v_d.juridiction), p_chambre, p_avocat, case when v_uid is null then 'agenda' else 'saisie' end, v_uid)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: tamila_ajouter_membre(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_ajouter_membre(p_dossier uuid, p_user uuid, p_role text DEFAULT 'intervenant'::text, p_jusqu_au timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_role_cible text;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null or not found or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Ce dossier ne vous est pas ouvert.' using errcode = '42501';
  end if;
  if not private.tamila_gere_dossier_pour(v_uid, p_dossier) then
    raise exception 'Seul le responsable du dossier, ou un associé, y ajoute quelqu''un.' using errcode = '42501';
  end if;
  if p_role is null or p_role not in ('responsable', 'intervenant', 'lecteur') then
    raise exception 'Rôle inconnu : %.', coalesce(p_role, 'vide') using errcode = '22023';
  end if;
  select c.role into v_role_cible from public.comptes c where c.user_id = p_user and c.client_id = v_d.client_id;
  if v_role_cible is null then
    raise exception 'Cette personne n''est pas membre du cabinet.' using errcode = '23503';
  end if;
  if exists (select 1 from public.tamila_murailles m
             where m.dossier_id = p_dossier and m.user_id = p_user and m.leve_le is null) then
    raise exception 'Une muraille écarte cette personne du dossier.' using errcode = '42501';
  end if;
  if v_role_cible = 'lecteur' and p_role <> 'lecteur' then
    raise exception 'Un stagiaire entre dans un dossier en lecteur.' using errcode = '22023';
  end if;
  if p_role = 'responsable' and v_role_cible not in ('gerant', 'admin', 'valideur') then
    raise exception 'Le responsable d''un dossier est un avocat.' using errcode = '22023';
  end if;
  if p_jusqu_au is not null and p_jusqu_au <= now() then
    raise exception 'Un accès borné finit dans le futur.' using errcode = '22023';
  end if;
  insert into public.tamila_dossiers_membres (client_id, dossier_id, user_id, role_dossier, jusqu_au, ajoute_par)
  values (v_d.client_id, p_dossier, p_user, p_role, p_jusqu_au, v_uid)
  on conflict (dossier_id, user_id) do update
    set role_dossier = excluded.role_dossier, jusqu_au = excluded.jusqu_au, ajoute_par = excluded.ajoute_par;
end $$;


--
-- Name: tamila_ajouter_partie(uuid, bytea, text, text, text, bytea); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_ajouter_partie(p_dossier uuid, p_nom bytea, p_qualite text, p_residence text DEFAULT 'inconnue'::text, p_role_procedure text DEFAULT NULL::text, p_courriels bytea DEFAULT NULL::bytea) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_id uuid;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier;
  if v_uid is null or not found or not private.tamila_ecrit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Vous n''écrivez pas dans ce dossier.' using errcode = '42501';
  end if;
  insert into public.tamila_parties (client_id, dossier_id, nom_chiffre, qualite, role_procedure, residence,
                                     courriels_chiffres, cree_par)
  values (v_d.client_id, p_dossier, p_nom, p_qualite, p_role_procedure, coalesce(p_residence, 'inconnue'),
          p_courriels, v_uid)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: tamila_annuler_cloture(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_annuler_cloture(p_dossier uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null or not found or not private.a_un_role(v_d.client_id, array['gerant'])
     or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Seul un gérant annule une clôture.' using errcode = '42501';
  end if;
  if v_d.statut <> 'clos' then
    raise exception 'Ce dossier n''est pas clos.' using errcode = '55000';
  end if;
  if v_d.effacement_prevu_le <= now() then
    raise exception 'L''échéance est passée : l''effacement est en cours.' using errcode = '55000';
  end if;
  update public.tamila_dossiers
     set statut = v_d.statut_avant_cloture, clos_le = null, demande_cloture_id = null, statut_avant_cloture = null,
         effacement_prevu_le = case when v_d.statut_avant_cloture = 'audit' then private.tamila_echeance_effacement(
             v_d.audit_fin_le, (select r.conservation_audit_jours from public.tamila_reglages r where r.client_id = v_d.client_id),
             private.tamila_fuseau(v_d.client_id, v_d.entite_id)) end
   where id = p_dossier;
end $$;


--
-- Name: tamila_annuler_confirmation(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_annuler_confirmation(p_delai uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.demandes_validation d set statut = 'annulee'
   where d.id = (select t.demande_id from public.tamila_delais t where t.id = p_delai) and d.statut = 'en_attente';
end $$;


--
-- Name: tamila_annuler_delai(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_annuler_delai(p_delai uuid, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  v_uid uuid := (select auth.uid());
  t public.tamila_delais;
begin
  select * into t from public.tamila_delais where id = p_delai;
  if v_uid is null or not found then
    raise exception 'Un délai s''annule par un avocat du dossier.' using errcode = '42501';
  end if;
  perform private.tamila_dossier_ecrit(t.dossier_id, true);
  select * into t from public.tamila_delais where id = p_delai for update;
  if t.statut in ('clos', 'annule') then
    raise exception 'Ce délai est déjà clos ou annulé.' using errcode = '55000';
  end if;
  if p_motif is null or p_motif not in ('desistement', 'caducite_prononcee', 'irrecevabilite_prononcee', 'radiation',
                                        'procedure_changee', 'erreur', 'doublon', 'autre') then
    raise exception 'Motif d''annulation inconnu : %.', coalesce(p_motif, 'vide') using errcode = '22023';
  end if;
  perform private.tamila_annuler_confirmation(t.id);
  update public.tamila_delais set statut = 'annule', motif_annulation = p_motif, annule_par = v_uid, annule_le = now()
   where id = t.id;
  if (select d.statut from public.delais d where d.id = t.delai_id) in ('ouvert', 'depasse') then
    v_porte := private.tamila_ouvrir_porte();
    perform private.clore_delai(t.delai_id, 'annule', 'Annulé par un avocat : ' || private.tamila_libelle(p_motif) || '.');
    perform private.tamila_fermer_porte(v_porte);
  end if;
  perform private.journaliser_module(t.client_id, 'tamila', 'tamila.delai.annule', 'tamila_dossier', t.dossier_id::text,
    jsonb_build_object('delai', t.id, 'motif', p_motif));
end $$;


--
-- Name: tamila_appliquer_avis(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_appliquer_avis(p_avis uuid, p_uid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public.tamila_avis;
  v_d public.tamila_dossiers;
  v_a public.tamila_appels;
  v_raisons text[] := '{}';
  v_delais uuid[] := '{}';
  v_audience uuid;
  v_oriente boolean := false;
  v_interrompus integer := 0;
  v_statut text;
  v_effet text;
  v_role text;
  r record;
begin
  select * into v from public.tamila_avis where id = p_avis for update;
  select * into v_d from public.tamila_dossiers where id = v.dossier_id;
  select * into v_a from public.tamila_appels where dossier_id = v.dossier_id for update;

  if v.rg_concorde is false then
    update public.tamila_avis set statut = 'a_verifier', effet = 'rg_different' where id = v.id;
    perform private.lever_alerte_module(v.client_id, 'tamila', 'critique',
      'Un avis RPVA ne porte pas le n° RG de son dossier : rattachez-le au bon dossier',
      jsonb_build_object('avis', v.id, 'dossier', v.dossier_id, 'type', v.type_avis), 'avis_rg:' || v.id::text, true,
      v_d.responsable_id);
    return jsonb_build_object('avis', v.id, 'statut', 'a_verifier', 'effet', 'rg_different', 'delais', '[]'::jsonb);
  end if;
  if v.rg_concorde is null then
    v_raisons := v_raisons || 'rg_non_verifie'::text;
  end if;
  if v.confiance = 'modele' then
    v_raisons := v_raisons || 'type_propose_par_modele'::text;
    perform private.lever_alerte_module(v.client_id, 'tamila', 'attention', 'Avis RPVA sans gabarit : type proposé par le modèle',
      jsonb_build_object('avis', v.id, 'type', v.type_avis), 'gabarit_manquant:' || v.type_avis, false, null);
  end if;

  if v.type_avis = 'rpva_accuse_depot' then
    update public.tamila_avis set statut = 'a_rattacher', effet = 'preuve_a_rattacher' where id = v.id;
    perform private.lever_alerte_module(v.client_id, 'tamila', 'attention',
      'Un accusé de dépôt RPVA est arrivé : rattachez-le au délai qu''il éteint',
      jsonb_build_object('avis', v.id, 'dossier', v.dossier_id, 'depose_le', v.depose_le), 'avis_depot:' || v.id::text, true,
      v_d.responsable_id);
    return jsonb_build_object('avis', v.id, 'statut', 'a_rattacher', 'effet', 'preuve_a_rattacher', 'delais', '[]'::jsonb);
  end if;

  begin
    if v.type_avis = 'rpva_avis_audience' then
      if v.date_audience is not null then
        insert into public.tamila_audiences (client_id, dossier_id, avis_id, date_heure, heure_connue, nature, source, cree_par)
        values (v.client_id, v.dossier_id, v.id, v.date_audience, coalesce(v.heure_audience_connue, false), 'audience', 'avis', p_uid)
        returning id into v_audience;
      end if;
    else
      if v_a.id is null and v.type_avis = 'rpva_declaration_appel' then
        v_role := case v.partie_visee when 'appelant' then 'appelant' when 'intime' then 'intime' end;
        if v_role is not null and v_d.territoire in ('metropole', 'alsace-moselle', 'guadeloupe', 'martinique', 'guyane',
             'la-reunion', 'mayotte', 'saint-barthelemy', 'saint-martin', 'saint-pierre-et-miquelon') then
          insert into public.tamila_appels (client_id, dossier_id, introduit_le, role_client, territoire, cree_par)
          values (v.client_id, v.dossier_id, v.date_avis, v_role, v_d.territoire, p_uid)
          returning * into v_a;
        end if;
      end if;
      if v_a.id is null then
        v_effet := case when v.type_avis = 'rpva_declaration_appel' and v.partie_visee in ('appelant', 'intime')
                        then 'juridiction_a_preciser' else 'appel_a_declarer' end;
        update public.tamila_avis set statut = 'sans_effet', effet = v_effet where id = v.id;
        perform private.lever_alerte_module(v.client_id, 'tamila', 'attention',
          case v_effet when 'juridiction_a_preciser'
               then 'Un avis RPVA est arrivé : précisez la cour d''appel du dossier pour que Tamila en calcule les délais'
               else 'Un avis RPVA est arrivé : déclarez l''appel du dossier pour que Tamila en calcule les délais' end,
          jsonb_build_object('avis', v.id, 'dossier', v.dossier_id, 'type', v.type_avis), 'avis_appel:' || v.dossier_id::text,
          true, v_d.responsable_id);
        return jsonb_build_object('avis', v.id, 'statut', 'sans_effet', 'effet', v_effet, 'delais', '[]'::jsonb);
      end if;

      if v.type_avis = 'rpva_declaration_appel' then
        v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'declaration_appel', v.date_avis, v.id, v_raisons, p_uid, false);
      elsif v.type_avis = 'rpva_avis_902' then
        v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'avis_signifier_declaration', v.date_avis, v.id, v_raisons,
                                                       p_uid, false);
      elsif v.type_avis = 'rpva_avis_fixation' then
        if v_a.procedure <> 'bref_delai' then
          perform private.tamila_orienter(v_a.id, 'bref_delai');
          select * into v_a from public.tamila_appels where id = v_a.id;
          v_oriente := true;
        end if;
        v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'avis_fixation_bref_delai', v.date_avis, v.id, v_raisons,
                                                       p_uid, false);
        if v.date_audience is not null then
          insert into public.tamila_audiences (client_id, dossier_id, avis_id, date_heure, heure_connue, nature, juridiction,
                                               source, cree_par)
          values (v.client_id, v.dossier_id, v.id, v.date_audience, coalesce(v.heure_audience_connue, false), 'plaidoiries',
                  v_d.juridiction, 'avis', p_uid)
          returning id into v_audience;
        end if;
      elsif v.type_avis = 'rpva_ordonnance_mee' then
        if v_a.procedure = 'a_orienter' then
          perform private.tamila_orienter(v_a.id, 'mise_en_etat');
          v_oriente := true;
        end if;
        if v.date_limite is not null then
          v_delais := array[private.tamila_poser_date_fixee(v_d, v_a.territoire, v.date_limite, 'autre', 'ordonnance', v.id,
                                                            v_raisons, p_uid, false)];
        end if;
      elsif v.type_avis = 'rpva_conclusions' then
        -- Les conclusions de l'appelant notifiées à l'intimé : 909 (906-2 à bref délai),
        -- pour les premières seulement (celles de l'art. 908).
        if v.partie_visee = 'appelant' and v_a.role_client = 'intime' and coalesce(v.rang, 1) = 1 then
          v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'notification_conclusions_appelant', v.date_avis, v.id,
            v_raisons || case when v.rang is null then array['rang_a_verifier'] else '{}'::text[] end, p_uid, false);
        end if;
      elsif v.type_avis = 'rpva_appel_incident' then
        v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'notification_appel_incident', v.date_avis, v.id, v_raisons,
                                                       p_uid, false);
      elsif v.type_avis = 'rpva_intervention' then
        if v_a.role_client = 'intervenant_force' then
          v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'notification_intervention_forcee', v.date_avis, v.id,
                                                         v_raisons, p_uid, false);
        elsif v_a.role_client = 'intervenant_volontaire' then
          v_delais := private.tamila_appliquer_evenement(v_d, v_a, 'intervention_volontaire', v.date_avis, v.id, v_raisons,
                                                         p_uid, false);
        end if;
      elsif v.type_avis = 'rpva_interruption' then
        for r in
          select t.id from public.tamila_delais t join public.tamila_regles_procedure p on p.code = t.regle_code
          where t.dossier_id = v.dossier_id and t.statut in ('a_confirmer', 'confirme', 'rejete') and p.interruptible
          order by t.echeance_retenue
        loop
          perform private.tamila_interrompre(r.id, 'a_preciser', v.date_avis);
          v_interrompus := v_interrompus + 1;
        end loop;
      end if;
      if v.date_cloture_previsible is not null then
        update public.tamila_appels set cloture_previsible_le = v.date_cloture_previsible, maj_le = now() where id = v_a.id;
      end if;
    end if;
  exception when others then
    update public.tamila_avis set statut = 'a_verifier', effet = 'erreur' where id = v.id;
    perform private.lever_alerte_module(v.client_id, 'tamila', 'critique',
      'Un avis RPVA n''a pas pu être appliqué : vérifiez les délais du dossier',
      jsonb_build_object('avis', v.id, 'dossier', v.dossier_id, 'type', v.type_avis, 'erreur', left(sqlerrm, 300)),
      'avis_erreur:' || v.id::text, true, v_d.responsable_id);
    return jsonb_build_object('avis', v.id, 'statut', 'a_verifier', 'effet', 'erreur', 'erreur', left(sqlerrm, 300),
                              'delais', '[]'::jsonb);
  end;

  v_effet := case when cardinality(v_delais) > 0 then 'delais_poses'
                  when v_interrompus > 0 then 'delais_interrompus'
                  when v_audience is not null then 'audience_ajoutee'
                  when v_oriente then 'procedure_orientee'
                  else 'aucun_delai' end;
  v_statut := case when v_effet = 'aucun_delai' then 'sans_effet' else 'applique' end;
  update public.tamila_avis set statut = v_statut, effet = v_effet where id = v.id;
  return jsonb_build_object('avis', v.id, 'statut', v_statut, 'effet', v_effet, 'delais', to_jsonb(v_delais),
                            'audience', v_audience, 'interrompus', v_interrompus);
end $$;


--
-- Name: tamila_chiffre_valide(bytea); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_chiffre_valide(p bytea) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p is null or (octet_length(p) >= 29 and get_byte(p, 0) = 1)
$$;


--
-- Name: tamila_appels; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tamila_appels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    dossier_id uuid NOT NULL,
    introduit_le date NOT NULL,
    regime text GENERATED ALWAYS AS (
CASE
    WHEN (introduit_le >= '2024-09-01'::date) THEN 'cpc'::text
    ELSE 'cpc2017'::text
END) STORED NOT NULL,
    procedure text DEFAULT 'a_orienter'::text NOT NULL,
    role_client text NOT NULL,
    territoire text NOT NULL,
    cloture_previsible_le date,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    cree_par uuid,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tamila_appels_introduit_le_check CHECK ((introduit_le >= '2017-09-01'::date)),
    CONSTRAINT tamila_appels_procedure_check CHECK ((procedure = ANY (ARRAY['a_orienter'::text, 'mise_en_etat'::text, 'bref_delai'::text]))),
    CONSTRAINT tamila_appels_role_client_check CHECK ((role_client = ANY (ARRAY['appelant'::text, 'intime'::text, 'intervenant_force'::text, 'intervenant_volontaire'::text]))),
    CONSTRAINT tamila_appels_territoire_check CHECK ((territoire = ANY (ARRAY['metropole'::text, 'alsace-moselle'::text, 'guadeloupe'::text, 'martinique'::text, 'guyane'::text, 'la-reunion'::text, 'mayotte'::text, 'saint-barthelemy'::text, 'saint-martin'::text, 'saint-pierre-et-miquelon'::text])))
);


--
-- Name: tamila_dossiers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tamila_dossiers (
    id uuid NOT NULL,
    client_id uuid NOT NULL,
    entite_id uuid NOT NULL,
    reference_chiffree bytea,
    intitule_chiffre bytea,
    numero_rg_chiffre bytea,
    matiere text,
    juridiction text,
    territoire text,
    mode text DEFAULT 'contentieux'::text NOT NULL,
    statut text NOT NULL,
    perso boolean DEFAULT false NOT NULL,
    proprietaire_perso uuid,
    responsable_id uuid,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    cree_par uuid,
    demande_ouverture_id uuid,
    ouvert_le timestamp with time zone,
    ouvert_par uuid,
    audit_fin_le timestamp with time zone,
    clos_le timestamp with time zone,
    demande_cloture_id uuid,
    statut_avant_cloture text,
    effacement_prevu_le timestamp with time zone,
    efface_le timestamp with time zone,
    motif_effacement text,
    CONSTRAINT tamila_dossiers_audit CHECK (((statut <> 'audit'::text) OR (audit_fin_le IS NOT NULL))),
    CONSTRAINT tamila_dossiers_contenu CHECK ((((statut = 'efface'::text) = ((reference_chiffree IS NULL) AND (intitule_chiffre IS NULL))) AND ((statut <> 'efface'::text) OR ((numero_rg_chiffre IS NULL) AND (juridiction IS NULL))))),
    CONSTRAINT tamila_dossiers_intitule_chiffre_check CHECK (private.tamila_chiffre_valide(intitule_chiffre)),
    CONSTRAINT tamila_dossiers_juridiction_check CHECK (((char_length(juridiction) >= 1) AND (char_length(juridiction) <= 120))),
    CONSTRAINT tamila_dossiers_matiere_check CHECK ((matiere ~ '^[a-z][a-z0-9_]{1,40}$'::text)),
    CONSTRAINT tamila_dossiers_mode_check CHECK ((mode = ANY (ARRAY['contentieux'::text, 'dommage_corporel'::text]))),
    CONSTRAINT tamila_dossiers_motif_effacement_check CHECK ((motif_effacement = ANY (ARRAY['cloture'::text, 'fin_audit'::text, 'ouverture_refusee'::text]))),
    CONSTRAINT tamila_dossiers_numero_rg_chiffre_check CHECK (private.tamila_chiffre_valide(numero_rg_chiffre)),
    CONSTRAINT tamila_dossiers_perso CHECK ((perso = (proprietaire_perso IS NOT NULL))),
    CONSTRAINT tamila_dossiers_reference_chiffree_check CHECK (private.tamila_chiffre_valide(reference_chiffree)),
    CONSTRAINT tamila_dossiers_statut_avant_cloture_check CHECK ((statut_avant_cloture = ANY (ARRAY['ouvert'::text, 'audit'::text]))),
    CONSTRAINT tamila_dossiers_statut_check CHECK ((statut = ANY (ARRAY['attente'::text, 'ouvert'::text, 'audit'::text, 'clos'::text, 'efface'::text, 'refuse'::text])))
);


--
-- Name: tamila_appliquer_evenement(public.tamila_dossiers, public.tamila_appels, text, date, uuid, text[], uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_appliquer_evenement(p_dossier public.tamila_dossiers, p_appel public.tamila_appels, p_evenement text, p_date date, p_avis uuid, p_raisons text[], p_uid uuid, p_sauf_echus boolean) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_residence text := private.tamila_residence_client(p_dossier.id, p_appel.territoire);
  v_ids uuid[] := '{}';
begin
  for r in
    select p.code from public.tamila_regles_procedure p
    where p.regime = p_appel.regime and p.evenement = p_evenement and p_appel.procedure = any (p.procedures)
      and (p.partie in ('destinataire', 'toutes') or p.partie = p_appel.role_client)
    order by p.code
  loop
    -- Un appel déclaré après coup n'entre pas avec des délais déjà échus.
    continue when p_sauf_echus and (private.tamila_calculer_delai(r.code, p_date, p_appel.territoire, v_residence) ->> 'echeance')::date
                                    < private.tamila_aujourdhui(p_appel.territoire);
    v_ids := v_ids || private.tamila_poser(p_dossier, p_appel, r.code, p_date, v_residence, p_avis, p_raisons, p_uid);
  end loop;
  return v_ids;
end $$;


--
-- Name: tamila_augmentation(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_augmentation(p_territoire text, p_residence text, OUT mois integer, OUT motif text, OUT incertain text) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_residence is null or p_residence not in (
       'metropole', 'alsace-moselle', 'guadeloupe', 'martinique', 'guyane', 'la-reunion', 'mayotte', 'saint-barthelemy',
       'saint-martin', 'saint-pierre-et-miquelon', 'nouvelle-caledonie', 'polynesie-francaise', 'wallis-et-futuna', 'taaf',
       'etranger', 'inconnue') then
    raise exception 'Résidence inconnue : %.', coalesce(p_residence, 'vide') using errcode = '22023';
  end if;
  if p_residence = 'inconnue' then
    mois := null; motif := 'domicile_inconnu'; incertain := 'domicile_inconnu';
  elsif p_residence = 'etranger' then
    if p_territoire in ('metropole', 'alsace-moselle') then
      mois := 2; motif := 'etranger';
    else
      -- Hors de la collectivité (un mois) ou à l'étranger (deux) : un mois, à confirmer.
      mois := 1; motif := 'etranger_devant_outre_mer'; incertain := 'etranger_devant_outre_mer';
    end if;
  elsif p_territoire in ('metropole', 'alsace-moselle') then
    if p_residence in ('guadeloupe', 'guyane', 'martinique', 'la-reunion', 'mayotte', 'saint-barthelemy', 'saint-martin',
                       'saint-pierre-et-miquelon', 'polynesie-francaise', 'wallis-et-futuna', 'nouvelle-caledonie', 'taaf') then
      mois := 1; motif := 'outre_mer_devant_metropole';
    else
      mois := 0; motif := 'aucune';
    end if;
  elsif p_territoire in ('guadeloupe', 'guyane', 'martinique', 'la-reunion', 'mayotte', 'saint-barthelemy', 'saint-martin',
                         'saint-pierre-et-miquelon', 'wallis-et-futuna') and p_residence <> p_territoire then
    mois := 1; motif := 'hors_collectivite';
  else
    mois := 0; motif := 'aucune';
  end if;
end $$;


--
-- Name: tamila_aujourdhui(text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_aujourdhui(p_territoire text, p_instant timestamp with time zone DEFAULT now()) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select (p_instant at time zone coalesce((select t.fuseau from public.territoires t where t.code = p_territoire), 'Europe/Paris'))::date
$$;


--
-- Name: tamila_avis_lu(uuid, uuid, uuid, text, jsonb, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_avis_lu(p_client uuid, p_dossier uuid, p_piece uuid, p_type text, p_valeurs jsonb, p_confiance text DEFAULT 'gabarit'::text, p_rg_concorde boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_existant uuid;
  v_fuseau text;
  v_id uuid;
  v_date_avis date;
  v_audience timestamptz;
  v_cloture date;
  v_limite date;
  v_partie text;
  v_rang smallint;
  v_depose timestamptz;
  v_texte text;
begin
  v_d := private.tamila_dossier_ecrit(p_dossier, false);
  if v_d.client_id <> p_client then
    raise exception 'Ce dossier n''est pas celui de ce cabinet.' using errcode = '42501';
  end if;
  if v_d.statut not in ('ouvert', 'audit') then
    raise exception 'Les avis d''un dossier se lisent quand il est ouvert.' using errcode = '55000';
  end if;
  if p_type is null or p_type not in ('rpva_avis_fixation', 'rpva_avis_902', 'rpva_declaration_appel', 'rpva_conclusions',
       'rpva_appel_incident', 'rpva_intervention', 'rpva_ordonnance_mee', 'rpva_avis_audience', 'rpva_accuse_depot',
       'rpva_interruption') then
    raise exception 'Type d''avis inconnu : %.', coalesce(p_type, 'vide') using errcode = '22023';
  end if;
  if v_uid is not null then
    p_confiance := 'saisie';
  elsif p_confiance is null or p_confiance not in ('gabarit', 'modele') then
    raise exception 'Confiance inconnue : %.', coalesce(p_confiance, 'vide') using errcode = '22023';
  end if;
  if p_piece is not null then
    select a.id into v_existant from public.tamila_avis a where a.piece_id = p_piece;
    if v_existant is not null then
      return (select jsonb_build_object('avis', a.id, 'statut', a.statut, 'effet', a.effet, 'deja_lu', true,
                                        'delais', coalesce((select jsonb_agg(t.id) from public.tamila_delais t where t.avis_id = a.id),
                                                           '[]'::jsonb))
              from public.tamila_avis a where a.id = v_existant);
    end if;
    if not exists (select 1 from public.pieces pc
                   where pc.id = p_piece and pc.client_id = p_client and pc.objet_type = 'tamila_dossier'
                     and pc.objet_id = p_dossier::text) then
      raise exception 'Cette pièce n''est pas dans le dossier.' using errcode = '22023';
    end if;
  end if;
  select tr.fuseau into v_fuseau from public.territoires tr
   where tr.code = coalesce((select a.territoire from public.tamila_appels a where a.dossier_id = p_dossier), v_d.territoire, 'metropole');
  p_valeurs := coalesce(p_valeurs, '{}'::jsonb);
  begin
    v_date_avis := (p_valeurs ->> 'date_avis')::date;
    v_texte := p_valeurs ->> 'date_audience';
    if v_texte is not null then
      v_audience := v_texte::timestamp at time zone v_fuseau;
    end if;
    v_cloture := (p_valeurs ->> 'date_cloture_previsible')::date;
    v_limite := (p_valeurs ->> 'date_limite')::date;
    if p_valeurs ->> 'depose_le' is not null then
      v_depose := (p_valeurs ->> 'depose_le')::timestamp at time zone v_fuseau;
    end if;
  exception when others then
    raise exception 'Une date de l''avis est illisible.' using errcode = '22023';
  end;
  if v_date_avis is null then
    raise exception 'La date de l''avis est nécessaire.' using errcode = '22023';
  end if;
  v_partie := case when p_valeurs ->> 'partie_visee' in ('appelant', 'intime', 'intervenant') then p_valeurs ->> 'partie_visee' end;
  v_rang := case when p_valeurs ->> 'rang' ~ '^[1-9][0-9]?$' then (p_valeurs ->> 'rang')::smallint end;
  if p_type = 'rpva_accuse_depot' and v_depose is null then
    raise exception 'Un accusé de dépôt porte sa date de dépôt.' using errcode = '22023';
  end if;

  insert into public.tamila_avis (client_id, dossier_id, piece_id, type_avis, date_avis, date_audience, heure_audience_connue,
    date_cloture_previsible, date_limite, partie_visee, rang, depose_le, confiance, rg_concorde, cree_par)
  values (p_client, p_dossier, p_piece, p_type, v_date_avis, v_audience,
    case when v_texte is not null then char_length(v_texte) > 10 end, v_cloture, v_limite, v_partie, v_rang, v_depose,
    p_confiance, p_rg_concorde, v_uid)
  returning id into v_id;
  return private.tamila_appliquer_avis(v_id, v_uid);
end $_$;


--
-- Name: tamila_balayer_decisions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_balayer_decisions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record; n integer := 0;
begin
  for r in
    select d.id from public.demandes_validation d
    where d.module = 'tamila' and d.type_action in ('ouvrir_dossier', 'cloturer_dossier', 'lever_muraille', 'confirmer_delai')
      and (d.statut = 'approuvee' or (d.statut = 'rejetee' and d.decide_le > now() - interval '2 days'))
    order by d.cree_le
  loop
    perform private.tamila_executer_demande(r.id);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: tamila_brute_augmentee(integer, text, date, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_brute_augmentee(p_quantite integer, p_unite text, p_depart date, p_mois integer, OUT brute date, OUT d_un_bloc date) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_unite = 'mois' then
    d_un_bloc := public.ajouter_mois(p_depart, p_quantite + p_mois);
    brute := least(d_un_bloc, public.ajouter_mois(public.ajouter_mois(p_depart, p_quantite), p_mois));
  elsif p_unite = 'jours' then
    brute := public.ajouter_mois(p_depart, p_mois) + p_quantite;
    d_un_bloc := brute;
  else
    raise exception 'Unité non prise en charge : %.', coalesce(p_unite, 'vide') using errcode = '22023';
  end if;
end $$;


--
-- Name: tamila_calculer_delai(text, date, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_calculer_delai(p_regle text, p_depart date, p_territoire text, p_residence text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  p public.tamila_regles_procedure;
  g public.regles_delais;
  v_base jsonb;
  v_b5 jsonb;
  v_aug record;
  v_mois integer := 0;
  v_motif text;
  v_incertain text;
  v_brute date;
  v_un_bloc date;
  v_echeance date;
  v_raisons text[] := '{}';
  v_autres jsonb := '[]'::jsonb;
  v_art text;
  v_detail text;
  v_source text;
  e jsonb;
begin
  select * into p from public.tamila_regles_procedure where code = p_regle;
  if not found then
    raise exception 'Règle de procédure inconnue : %.', coalesce(p_regle, 'vide') using errcode = '22023';
  end if;
  if p_territoire in ('nouvelle-caledonie', 'polynesie-francaise', 'wallis-et-futuna') then
    raise exception 'Cette juridiction applique la procédure civile locale : Tamila n''y calcule pas les délais.'
      using errcode = '22023', hint = 'Saisir la date fixée (tamila_poser_date).';
  end if;
  if p_territoire is null or p_territoire not in ('metropole', 'alsace-moselle', 'guadeloupe', 'martinique', 'guyane',
       'la-reunion', 'mayotte', 'saint-barthelemy', 'saint-martin', 'saint-pierre-et-miquelon') then
    raise exception 'Territoire inconnu : %.', coalesce(p_territoire, 'vide') using errcode = '22023';
  end if;
  if p_depart is null then
    raise exception 'Le départ du délai est nécessaire.' using errcode = '22023';
  end if;
  select * into v_aug from private.tamila_augmentation(p_territoire, p_residence);

  -- B5 : la version en vigueur au départ, la date brute et sa prorogation.
  v_base := public.echeance_de(p_regle, p_depart, p_territoire);
  select * into g from public.regles_delais where code = p_regle and version = (v_base ->> 'version')::smallint;
  v_art := case p.regime when 'cpc' then 'art. 915-4' else 'art. 911-2 ancien' end;
  if p.augmentable then
    v_mois := coalesce(v_aug.mois, 0);
    v_motif := v_aug.motif;
    v_incertain := v_aug.incertain;
    if v_incertain is not null then
      v_raisons := array[v_incertain];
    end if;
  else
    v_motif := 'non_augmentable';
  end if;

  select b.brute, b.d_un_bloc into v_brute, v_un_bloc
  from private.tamila_brute_augmentee(g.quantite, g.unite, p_depart, v_mois) b;
  v_echeance := public.proroger(v_brute, p_territoire);
  -- B5 porte l'augmentation (lot 16) ; la référence de Tamila la recalcule et les deux doivent concorder.
  v_b5 := public.echeance_de(p_regle, p_depart, p_territoire, v_mois);
  if v_echeance <> (v_b5 ->> 'echeance')::date or (v_mois = 0 and v_brute <> (v_b5 ->> 'brute')::date) then
    raise exception 'Le calcul de Tamila et celui de B5 divergent pour % au %.', p_regle, p_depart using errcode = 'XX000';
  end if;

  -- Les autres dates possibles, montrées avec la date retenue (la plus proche).
  if v_un_bloc <> v_brute then
    v_un_bloc := public.proroger(v_un_bloc, p_territoire);
    if v_un_bloc <> v_echeance then
      v_raisons := v_raisons || 'fin_de_mois_augmentation'::text;
      v_autres := v_autres || jsonb_build_object('motif', 'd_un_bloc', 'echeance', v_un_bloc);
    end if;
  end if;
  if v_incertain = 'domicile_inconnu' then
    v_autres := v_autres
      || jsonb_build_object('motif', 'un_mois_de_plus', 'echeance', public.proroger(
           (select b.brute from private.tamila_brute_augmentee(g.quantite, g.unite, p_depart, 1) b), p_territoire))
      || jsonb_build_object('motif', 'deux_mois_de_plus', 'echeance', public.proroger(
           (select b.brute from private.tamila_brute_augmentee(g.quantite, g.unite, p_depart, 2) b), p_territoire));
  elsif v_incertain = 'etranger_devant_outre_mer' then
    v_autres := v_autres
      || jsonb_build_object('motif', 'deux_mois_de_plus', 'echeance', public.proroger(
           (select b.brute from private.tamila_brute_augmentee(g.quantite, g.unite, p_depart, 2) b), p_territoire));
  end if;
  v_autres := coalesce((select jsonb_agg(x order by (x ->> 'motif') collate "C") from jsonb_array_elements(v_autres) x),
                       '[]'::jsonb);
  if ('fin_de_mois_augmentation' = any (v_raisons)) <> coalesce((v_b5 ->> 'a_confirmer')::boolean, false)
     or ('fin_de_mois_augmentation' = any (v_raisons)
         and v_un_bloc is distinct from (v_b5 ->> 'lecture_d_un_bloc')::date) then
    raise exception 'La fin de mois de Tamila et celle de B5 divergent pour % au %.', p_regle, p_depart using errcode = 'XX000';
  end if;
  v_raisons := array(select r from unnest(v_raisons) r order by r collate "C");

  v_source := case when v_mois > 0 then
    'Augmentation ' || case v_mois when 1 then 'd''un mois' else 'de deux mois' end || ' (' || v_art || ' : '
    || case v_motif
         when 'outre_mer_devant_metropole' then 'partie demeurant outre-mer devant une juridiction de métropole'
         when 'hors_collectivite' then 'partie qui ne demeure pas dans la collectivité de la juridiction'
         when 'etranger' then 'partie demeurant à l''étranger'
         else 'partie demeurant à l''étranger devant une juridiction d''outre-mer, à confirmer' end || ').' end;

  v_detail := g.quantite::text || case g.unite when 'mois' then ' mois' else case when g.quantite > 1 then ' jours' else ' jour' end end
    || ' à compter du ' || private.jour_en_toutes_lettres(p_depart) || ' (CPC, art. ' || p.article
    || case when p.regime = 'cpc2017' then ', dans sa rédaction antérieure au 01/09/2024' else '' end || ')'
    || case v_motif
         when 'outre_mer_devant_metropole' then ', augmentés d''un mois (partie demeurant outre-mer devant une juridiction de métropole, ' || v_art || ')'
         when 'hors_collectivite' then ', augmentés d''un mois (partie qui ne demeure pas dans la collectivité de la juridiction, ' || v_art || ')'
         when 'etranger' then ', augmentés de deux mois (partie demeurant à l''étranger, ' || v_art || ')'
         when 'etranger_devant_outre_mer' then ', augmentés d''un mois (partie demeurant à l''étranger devant une juridiction d''outre-mer, ' || v_art || ')'
         when 'domicile_inconnu' then ', sans augmentation retenue : domicile de la partie à préciser (' || v_art || ')'
         when 'non_augmentable' then ', délai que l''' || v_art || ' n''augmente pas'
         else '' end
    || case when g.unite = 'jours' and v_mois > 0 then ', les mois d''abord, puis les jours (art. 641, al. 3)' else '' end
    || ' : ' || private.jour_en_toutes_lettres(v_brute)
    || case when v_echeance <> v_brute then ', prorogé au ' || private.jour_en_toutes_lettres(v_echeance) || ' (art. 642)' else '' end
    || '.'
    || case when 'domicile_inconnu' = any (v_raisons)
            then ' À confirmer : le domicile de la partie est inconnu ; la date la plus proche est retenue.' else '' end
    || case when 'etranger_devant_outre_mer' = any (v_raisons)
            then ' À confirmer : devant une juridiction d''outre-mer, une partie à l''étranger a un mois (hors de la collectivité) ou deux (à l''étranger) ; un mois est retenu.' else '' end
    || case when 'fin_de_mois_augmentation' = any (v_raisons)
            then ' À confirmer : fin de mois ; calculé d''un bloc, le délai finirait plus tard ; la date la plus proche est retenue.' else '' end;
  for e in select * from jsonb_array_elements(v_autres) loop
    v_detail := v_detail || ' ' || case e ->> 'motif' when 'd_un_bloc' then 'Calculé d''un bloc'
                                                       when 'un_mois_de_plus' then 'Avec un mois de plus'
                                                       else 'Avec deux mois de plus' end
                || ' : ' || private.jour_en_toutes_lettres((e ->> 'echeance')::date) || '.';
  end loop;

  return jsonb_build_object(
    'echeance', v_echeance, 'brute', v_brute, 'base', (v_base ->> 'echeance')::date,
    'regle', p.code, 'version', g.version, 'regime', p.regime, 'article', p.article, 'acte', p.acte, 'sanction', p.sanction,
    'libelle', g.libelle, 'source', g.source_texte, 'source_url', g.source_url,
    'territoire', p_territoire, 'residence', p_residence, 'depart', p_depart,
    'augmentation_mois', v_mois, 'motif_augmentation', v_motif, 'source_augmentation', v_source,
    'raisons', to_jsonb(v_raisons), 'alternatives', v_autres, 'detail', v_detail);
end $$;


--
-- Name: tamila_changer_audience(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_changer_audience(p_audience uuid, p_statut text, p_renvoi_le timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  a public.tamila_audiences;
  v_id uuid;
begin
  select * into a from public.tamila_audiences where id = p_audience;
  if not found then
    raise exception 'Audience introuvable.' using errcode = '42501';
  end if;
  perform private.tamila_dossier_ecrit(a.dossier_id, false);
  if a.statut <> 'prevue' then
    raise exception 'Cette audience n''est plus prévue.' using errcode = '55000';
  end if;
  if p_statut is null or p_statut not in ('renvoyee', 'tenue', 'annulee') then
    raise exception 'Statut inconnu : %.', coalesce(p_statut, 'vide') using errcode = '22023';
  end if;
  if p_statut = 'renvoyee' then
    if p_renvoi_le is null or p_renvoi_le <= a.date_heure then
      raise exception 'Un renvoi porte une date postérieure à l''audience.' using errcode = '22023';
    end if;
    insert into public.tamila_audiences (client_id, dossier_id, avis_id, date_heure, heure_connue, nature, juridiction, chambre,
                                         avocat_id, source, cree_par)
    values (a.client_id, a.dossier_id, a.avis_id, p_renvoi_le, a.heure_connue, a.nature, a.juridiction, a.chambre, a.avocat_id,
            case when v_uid is null then 'agenda' else 'saisie' end, v_uid)
    returning id into v_id;
  end if;
  update public.tamila_audiences set statut = p_statut, renvoyee_a = v_id, maj_le = now() where id = a.id;
  return coalesce(v_id, a.id);
end $$;


--
-- Name: tamila_cle_detruite(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_cle_detruite(p_dossier uuid, p_preuve jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_k public.tamila_cles;
begin
  if (select auth.uid()) is not null or private.tamila_role_session() <> 'service_role' then
    raise exception 'La destruction d''une clé est faite par le serveur, au coffre à clés.' using errcode = '42501';
  end if;
  select * into v_k from public.tamila_cles where dossier_id = p_dossier for update;
  if not found then
    raise exception 'Clé introuvable.' using errcode = 'P0002';
  end if;
  if v_k.statut <> 'desactivee' or v_k.destruction_prevue_le > now() then
    raise exception 'Cette clé ne se détruit pas encore : elle est désactivée à l''effacement, détruite sept jours après.'
      using errcode = '55000';
  end if;
  update public.tamila_cles
     set statut = 'detruite', detruite_le = now(), preuve = coalesce(p_preuve, '{}'::jsonb),
         enveloppe = '\x00000000000000000000000000000000'::bytea
   where id = v_k.id;
end $$;


--
-- Name: tamila_consulter(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_consulter(p_dossier uuid, p_contexte text DEFAULT 'dossier'::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
begin
  if v_uid is null then
    raise exception 'Une lecture est tracée au nom d''une personne connectée.' using errcode = '42501';
  end if;
  if p_contexte is null or p_contexte !~ '^[a-z][a-z0-9_.]{1,40}$' then
    raise exception 'Le contexte d''une lecture est un code (dossier, piece, export…), jamais un texte libre.'
      using errcode = '22023';
  end if;
  select * into v_d from public.tamila_dossiers where id = p_dossier;
  if not found or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Ce dossier ne vous est pas ouvert.' using errcode = '42501';
  end if;
  if v_d.statut not in ('attente', 'ouvert', 'audit', 'clos') then
    raise exception 'Ce dossier n''a plus de contenu.' using errcode = '55000';
  end if;
  perform private.tracer_lecture(v_d.client_id, 'tamila_dossier', p_dossier::text, p_contexte);
  return now() + interval '30 minutes';
end $_$;


--
-- Name: tamila_controler_delais(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_controler_delais(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  w public.travaux;
  r record;
  v_ok boolean;
  v_depasses integer := 0;
  v_48h integer := 0;
  v_j8 integer := 0;
  v_destinataires uuid[];
begin
  -- 1. Les dépassements publiés par B5 (delai.depasse.tamila).
  for w in select * from private.prendre_travaux(array['tamila.delai_depasse'], 200, interval '5 minutes', 'tamila-delais') loop
    begin
      v_ok := false;
      for r in
        update public.tamila_delais t set depasse_le = p_maintenant
         where t.delai_id = private.tamila_uuid(w.charge ->> 'delai') and t.statut in ('a_confirmer', 'confirme', 'rejete')
           and t.depasse_le is null
        returning t.id, t.client_id, t.dossier_id, t.echeance_retenue, t.responsable_id
      loop
        perform private.lever_alerte_module(r.client_id, 'tamila', 'critique', 'Délai de procédure dépassé sans acte déposé',
          jsonb_build_object('delai', r.id, 'dossier', r.dossier_id, 'echeance', r.echeance_retenue),
          'delai_depasse:' || r.id::text, true, r.responsable_id);
        v_ok := true;
        v_depasses := v_depasses + 1;
      end loop;
      perform private.finir_travail(w.id, jsonb_build_object('depasse', v_ok));
    exception when others then
      perform private.echouer_travail(w.id, left(sqlerrm, 500));
    end;
  end loop;

  -- 2. Quarante-huit heures sans confirmation : l'avocat responsable est avisé.
  for r in
    select t.id, t.client_id, t.dossier_id, t.echeance_retenue, t.responsable_id from public.tamila_delais t
    where t.statut in ('a_confirmer', 'rejete') and t.relance_48h_le is null and t.cree_le <= p_maintenant - interval '48 hours'
    for update of t skip locked
  loop
    perform private.lever_alerte_module(r.client_id, 'tamila', 'attention', 'Délai de procédure à confirmer depuis 48 heures',
      jsonb_build_object('delai', r.id, 'dossier', r.dossier_id, 'echeance', r.echeance_retenue),
      'delai_48h:' || r.id::text, true, r.responsable_id);
    update public.tamila_delais set relance_48h_le = p_maintenant where id = r.id;
    v_48h := v_48h + 1;
  end loop;

  -- 3. À huit jours, toujours pas confirmé : un courriel par Tamila à l'avocat
  --    et aux associés qui voient le dossier, et une alerte critique.
  for r in
    select t.id, t.client_id, t.dossier_id, t.echeance_retenue, t.responsable_id from public.tamila_delais t
    join public.territoires tr on tr.code = t.territoire
    where t.statut in ('a_confirmer', 'rejete') and t.relance_j8_le is null
      and t.echeance_retenue - (p_maintenant at time zone tr.fuseau)::date <= 8
    for update of t skip locked
  loop
    select array_agg(distinct u.id order by u.id) into v_destinataires from (
      select r.responsable_id as id where r.responsable_id is not null
      union
      select c.user_id from public.comptes c
      where c.client_id = r.client_id and c.role in ('gerant', 'admin')
        and private.tamila_voit_dossier_pour(c.user_id, r.client_id, r.dossier_id::text)) u;
    perform private.deposer_travail(r.client_id, 'tamila', 'tamila.courriel',
      jsonb_build_object('modele', 'delai_non_confirme_j8', 'delai', r.id, 'dossier', r.dossier_id,
                         'echeance', r.echeance_retenue, 'destinataires', to_jsonb(coalesce(v_destinataires, '{}'::uuid[]))),
      'tamila:j8:' || r.id::text, 5::smallint);
    perform private.lever_alerte_module(r.client_id, 'tamila', 'critique', 'Délai de procédure non confirmé à huit jours ou moins',
      jsonb_build_object('delai', r.id, 'dossier', r.dossier_id, 'echeance', r.echeance_retenue),
      'delai_j8:' || r.id::text, true, r.responsable_id);
    update public.tamila_delais set relance_j8_le = p_maintenant where id = r.id;
    v_j8 := v_j8 + 1;
  end loop;

  -- 4. Le battement de chaque cabinet, même sans rien à faire.
  for r in select g.client_id from public.tamila_reglages g loop
    perform private.battre(r.client_id, 'tamila_delais',
      jsonb_build_object('depasses', v_depasses, 'relances_48h', v_48h, 'relances_j8', v_j8), null);
  end loop;
  return jsonb_build_object('depasses', v_depasses, 'relances_48h', v_48h, 'relances_j8', v_j8);
end $$;


--
-- Name: tamila_convertir_audit(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_convertir_audit(p_dossier uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null or not found or not private.a_un_role(v_d.client_id, array['gerant'])
     or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Seul un gérant convertit un audit en dossier ordinaire.' using errcode = '42501';
  end if;
  if v_d.statut <> 'audit' then
    raise exception 'Ce dossier n''est pas un audit en cours.' using errcode = '55000';
  end if;
  update public.tamila_dossiers set statut = 'ouvert', effacement_prevu_le = null where id = p_dossier;
end $$;


--
-- Name: tamila_corriger_delai(uuid, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_corriger_delai(p_delai uuid, p_echeance date, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  v_uid uuid := (select auth.uid());
  t public.tamila_delais;
  v_b5 public.delais;
  v_nouveau uuid;
  v_source text;
begin
  select * into t from public.tamila_delais where id = p_delai;
  if v_uid is null or not found then
    raise exception 'Une date se corrige par un avocat du dossier.' using errcode = '42501';
  end if;
  perform private.tamila_dossier_ecrit(t.dossier_id, true);
  select * into t from public.tamila_delais where id = p_delai for update;
  if t.statut not in ('a_confirmer', 'rejete', 'confirme', 'interrompu') then
    raise exception 'Ce délai est clos ou annulé.' using errcode = '55000';
  end if;
  if p_motif is null or p_motif not in ('calcul_errone', 'date_notifiee', 'delai_modifie_par_le_juge',
                                        'reprise_apres_interruption', 'autre') then
    raise exception 'Motif de correction inconnu : %.', coalesce(p_motif, 'vide') using errcode = '22023';
  end if;
  if p_echeance is null then
    raise exception 'La date corrigée est nécessaire.' using errcode = '22023';
  end if;
  v_source := 'Date saisie par un avocat : ' || private.tamila_libelle(p_motif) || '.';
  select * into v_b5 from public.delais where id = t.delai_id;
  if v_b5.statut in ('ouvert', 'depasse') then
    v_porte := private.tamila_ouvrir_porte();
    perform private.notifier_delai(t.delai_id, p_echeance, v_source);
    perform private.tamila_fermer_porte(v_porte);
  else
    -- Le délai de B5 a été clos (interruption) : un nouveau porte la date.
    v_porte := private.tamila_ouvrir_porte();
    v_nouveau := private.poser_delai_date(t.client_id, 'tamila', 'tamila_dossier', t.dossier_id::text, v_b5.libelle, p_echeance,
      v_source, t.territoire, '{7,2,0}', t.responsable_id, v_b5.action_attendue,
      'tamila:' || t.id::text || ':' || extract(epoch from clock_timestamp())::bigint::text);
    perform private.tamila_fermer_porte(v_porte);
  end if;
  perform private.tamila_annuler_confirmation(t.id);
  update public.tamila_delais
     set statut = 'confirme', echeance_retenue = p_echeance, confirmation = 'saisie', confirme_par = v_uid, confirme_le = now(),
         motif_correction = p_motif, delai_id = coalesce(v_nouveau, delai_id),
         depasse_le = case when p_echeance >= private.tamila_aujourdhui(t.territoire) then null else depasse_le end
   where id = t.id;
  perform private.journaliser_module(t.client_id, 'tamila', 'tamila.delai.corrige', 'tamila_dossier', t.dossier_id::text,
    jsonb_build_object('delai', t.id, 'echeance', p_echeance, 'avant', t.echeance_retenue, 'motif', p_motif));
end $$;


--
-- Name: tamila_creer_dossier(uuid, uuid, bytea, bytea, text, text, bytea, bytea, text, text, text, text, boolean, date, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_creer_dossier(p_client uuid, p_dossier uuid, p_reference bytea, p_intitule bytea, p_cle_fournisseur text, p_cle_reference text, p_cle_enveloppe bytea, p_numero_rg bytea DEFAULT NULL::bytea, p_matiere text DEFAULT NULL::text, p_juridiction text DEFAULT NULL::text, p_territoire text DEFAULT NULL::text, p_mode text DEFAULT 'contentieux'::text, p_perso boolean DEFAULT false, p_audit_fin date DEFAULT NULL::date, p_responsable uuid DEFAULT NULL::uuid, p_entite uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_role text;
  v_role_resp text;
  v_entite uuid;
  v_fuseau text;
  v_statut text;
  v_responsable uuid;
  v_audit_fin timestamptz;
  v_demande uuid;
begin
  if v_uid is null then
    raise exception 'Un dossier s''ouvre par une personne connectée.' using errcode = '42501';
  end if;
  select c.role into v_role from public.comptes c where c.user_id = v_uid and c.client_id = p_client;
  if v_role is null or v_role = 'lecteur' then
    raise exception 'Vous ne pouvez pas ouvrir de dossier dans ce cabinet.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.tamila_reglages r where r.client_id = p_client) then
    raise exception 'Tamila n''est pas installé pour ce cabinet.' using errcode = '55000';
  end if;
  if p_dossier is null then
    raise exception 'L''identifiant du dossier est donné par le serveur, avec sa clé.' using errcode = '22023';
  end if;
  if coalesce(p_perso, false) and v_role <> 'valideur' then
    raise exception 'La clientèle personnelle est celle d''un avocat collaborateur (RIN, art. 14).' using errcode = '42501';
  end if;
  if p_audit_fin is not null and v_role not in ('gerant', 'admin') then
    raise exception 'Un audit s''ouvre par un associé, contrat d''audit signé.' using errcode = '42501';
  end if;
  if coalesce(p_perso, false) and p_audit_fin is not null then
    raise exception 'Un audit n''est pas une clientèle personnelle.' using errcode = '22023';
  end if;

  v_entite := coalesce(p_entite, (select e.id from public.entites e where e.client_id = p_client and e.principale));
  if not private.perimetre_couvre(v_uid, p_client, v_entite) then
    raise exception 'Cette entité est hors de votre périmètre.' using errcode = '42501';
  end if;
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = v_entite;
  if v_fuseau is null then
    raise exception 'Entité introuvable.' using errcode = 'P0002';
  end if;

  if p_responsable is not null and p_responsable <> v_uid then
    if coalesce(p_perso, false) then
      raise exception 'Le titulaire d''une clientèle personnelle en est le responsable.' using errcode = '22023';
    end if;
    select c.role into v_role_resp from public.comptes c where c.user_id = p_responsable and c.client_id = p_client;
    if v_role_resp is null or v_role_resp not in ('gerant', 'admin', 'valideur') then
      raise exception 'Le responsable d''un dossier est un avocat du cabinet.' using errcode = '22023';
    end if;
    v_responsable := p_responsable;
  elsif v_role = 'collaborateur' then
    raise exception 'Désignez l''avocat responsable du dossier.' using errcode = '22023';
  else
    v_responsable := v_uid;
  end if;

  v_statut := case when v_role = 'collaborateur' then 'attente'
                   when p_audit_fin is not null then 'audit'
                   else 'ouvert' end;
  if p_audit_fin is not null then
    v_audit_fin := (p_audit_fin + time '23:59:59') at time zone v_fuseau;
  end if;

  insert into public.tamila_dossiers (
    id, client_id, entite_id, reference_chiffree, intitule_chiffre, numero_rg_chiffre, matiere, juridiction,
    territoire, mode, statut, perso, proprietaire_perso, responsable_id, cree_par, ouvert_le, ouvert_par,
    audit_fin_le, effacement_prevu_le)
  values (
    p_dossier, p_client, v_entite, p_reference, p_intitule, p_numero_rg, p_matiere, p_juridiction,
    p_territoire, coalesce(p_mode, 'contentieux'), v_statut, coalesce(p_perso, false),
    case when p_perso then v_uid end, v_responsable, v_uid,
    case when v_statut <> 'attente' then now() end, case when v_statut <> 'attente' then v_uid end,
    v_audit_fin,
    case when v_audit_fin is not null then private.tamila_echeance_effacement(v_audit_fin,
      (select r.conservation_audit_jours from public.tamila_reglages r where r.client_id = p_client), v_fuseau) end);

  insert into public.tamila_cles (client_id, dossier_id, fournisseur, reference, enveloppe)
  values (p_client, p_dossier, p_cle_fournisseur, p_cle_reference, p_cle_enveloppe);

  insert into public.tamila_dossiers_membres (client_id, dossier_id, user_id, role_dossier, ajoute_par)
  values (p_client, p_dossier, v_responsable, 'responsable', v_uid);

  if v_role = 'collaborateur' then
    insert into public.tamila_dossiers_membres (client_id, dossier_id, user_id, role_dossier, ajoute_par)
    values (p_client, p_dossier, v_uid, 'intervenant', v_uid);
    insert into public.demandes_validation (client_id, entite_id, module, type_action, objet_type, objet_id,
                                            resume, payload, cle_idempotence)
    values (p_client, v_entite, 'tamila', 'ouvrir_dossier', 'tamila_dossier', p_dossier::text,
            'Ouverture d''un dossier à la lecture',
            jsonb_build_object('dossier_id', p_dossier, 'initiateur', v_uid, 'responsable', v_responsable),
            'tamila:ouvrir:' || p_dossier::text)
    returning id into v_demande;
    update public.tamila_dossiers set demande_ouverture_id = v_demande where id = p_dossier;
    perform private.tamila_executer_demande(v_demande);
  end if;
  return p_dossier;
end $$;


--
-- Name: tamila_decider(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_decider(p_demande uuid, p_decision text, p_commentaire text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.demandes_validation;
begin
  select * into v_d from public.demandes_validation where id = p_demande;
  if v_uid is null or not found or v_d.module <> 'tamila' then
    raise exception 'Demande introuvable.' using errcode = 'P0002';
  end if;
  if not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, v_d.objet_id) then
    raise exception 'Vous n''avez pas accès au dossier de cette demande.' using errcode = '42501';
  end if;
  insert into public.approbations (demande_id, decision, commentaire) values (p_demande, p_decision, p_commentaire);
  return coalesce(private.tamila_executer_demande(p_demande),
                  (select d.statut from public.demandes_validation d where d.id = p_demande));
end $$;


--
-- Name: tamila_declarer_acte(uuid, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_declarer_acte(p_delai uuid, p_depose_le date, p_piece uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  v_uid uuid := (select auth.uid());
  t public.tamila_delais;
  v_d public.tamila_dossiers;
begin
  select * into t from public.tamila_delais where id = p_delai;
  if not found then
    raise exception 'Délai introuvable.' using errcode = '42501';
  end if;
  if v_uid is null and p_piece is null then
    raise exception 'Le serveur clôt un délai sur un accusé de dépôt seulement.' using errcode = '42501';
  end if;
  v_d := private.tamila_dossier_ecrit(t.dossier_id, p_piece is null);
  select * into t from public.tamila_delais where id = p_delai for update;
  if t.statut not in ('a_confirmer', 'confirme', 'rejete', 'interrompu') then
    raise exception 'Ce délai est déjà clos ou annulé.' using errcode = '55000';
  end if;
  if p_depose_le is null or p_depose_le < date '2017-09-01'
     or p_depose_le > greatest(private.tamila_aujourdhui(t.territoire), private.tamila_aujourdhui('metropole')) then
    raise exception 'La date du dépôt est un jour passé, ou aujourd''hui.' using errcode = '22023';
  end if;
  if p_piece is not null and not exists (
       select 1 from public.pieces pc
       where pc.id = p_piece and pc.client_id = t.client_id and pc.objet_type = 'tamila_dossier' and pc.objet_id = t.dossier_id::text) then
    raise exception 'Cette pièce n''est pas dans le dossier du délai.' using errcode = '22023';
  end if;
  perform private.tamila_annuler_confirmation(t.id);
  update public.tamila_delais
     set statut = 'clos', acte_depose_le = p_depose_le, motif_cloture = case when p_piece is null then 'declaration' else 'accuse_rpva' end,
         preuve_piece_id = p_piece, clos_par = v_uid, clos_le = now()
   where id = t.id;
  if (select d.statut from public.delais d where d.id = t.delai_id) in ('ouvert', 'depasse') then
    v_porte := private.tamila_ouvrir_porte();
    perform private.clore_delai(t.delai_id, 'tenu', null);
    perform private.tamila_fermer_porte(v_porte);
  end if;
  if p_piece is not null then
    update public.tamila_avis set statut = 'applique', effet = 'delai_clos' where piece_id = p_piece and statut = 'a_rattacher';
  end if;
  if p_depose_le > t.echeance_retenue then
    perform private.lever_alerte_module(t.client_id, 'tamila', 'critique', 'Acte déposé après l''échéance du délai',
      jsonb_build_object('delai', t.id, 'dossier', t.dossier_id, 'echeance', t.echeance_retenue, 'depose_le', p_depose_le),
      'delai_hors_delai:' || t.id::text, true, t.responsable_id);
  end if;
  perform private.journaliser_module(t.client_id, 'tamila', 'tamila.delai.clos', 'tamila_dossier', t.dossier_id::text,
    jsonb_build_object('delai', t.id, 'motif', case when p_piece is null then 'declaration' else 'accuse_rpva' end,
                       'depose_le', p_depose_le, 'piece', p_piece));
end $$;


--
-- Name: tamila_declarer_appel(uuid, date, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_declarer_appel(p_dossier uuid, p_introduit_le date, p_role text, p_procedure text DEFAULT 'a_orienter'::text, p_territoire text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_a public.tamila_appels;
  v_territoire text;
  v_nouveau boolean := false;
begin
  v_d := private.tamila_dossier_ecrit(p_dossier, false);
  if p_role is null or p_role not in ('appelant', 'intime', 'intervenant_force', 'intervenant_volontaire') then
    raise exception 'Rôle du client inconnu : %.', coalesce(p_role, 'vide') using errcode = '22023';
  end if;
  if p_procedure is null or p_procedure not in ('a_orienter', 'mise_en_etat', 'bref_delai') then
    raise exception 'Procédure inconnue : %.', coalesce(p_procedure, 'vide') using errcode = '22023';
  end if;
  v_territoire := coalesce(p_territoire, v_d.territoire);
  if v_territoire in ('nouvelle-caledonie', 'polynesie-francaise', 'wallis-et-futuna') then
    raise exception 'Cette cour applique la procédure civile locale : Tamila n''y calcule pas les délais ; saisissez les dates fixées.'
      using errcode = '22023';
  end if;
  if v_territoire is null or v_territoire not in ('metropole', 'alsace-moselle', 'guadeloupe', 'martinique', 'guyane',
       'la-reunion', 'mayotte', 'saint-barthelemy', 'saint-martin', 'saint-pierre-et-miquelon') then
    raise exception 'Précisez le siège de la cour d''appel : son calendrier proroge les délais.' using errcode = '22023';
  end if;
  if p_introduit_le is null or p_introduit_le < date '2017-09-01' then
    raise exception 'Tamila calcule les délais des appels introduits depuis le 01/09/2017 ; pour un appel plus ancien, saisissez les dates.'
      using errcode = '22023';
  end if;
  if p_introduit_le > greatest(private.tamila_aujourdhui(v_territoire), private.tamila_aujourdhui('metropole')) then
    raise exception 'Un appel ne s''introduit pas dans le futur.' using errcode = '22023';
  end if;

  select * into v_a from public.tamila_appels where dossier_id = p_dossier for update;
  if found then
    if v_a.introduit_le <> p_introduit_le and exists (
         select 1 from public.tamila_delais t where t.appel_id = v_a.id and t.nature = 'regle' and t.statut <> 'annule') then
      raise exception 'Des délais sont posés sur cet appel : annulez-les avant de changer sa date.' using errcode = '55000';
    end if;
    update public.tamila_appels
       set introduit_le = p_introduit_le, role_client = p_role, territoire = v_territoire, maj_le = now()
     where id = v_a.id;
    perform private.tamila_orienter(v_a.id, p_procedure);
  else
    insert into public.tamila_appels (client_id, dossier_id, introduit_le, procedure, role_client, territoire, cree_par)
    values (v_d.client_id, p_dossier, p_introduit_le, p_procedure, p_role, v_territoire, v_uid)
    returning * into v_a;
    v_nouveau := true;
  end if;
  select * into v_a from public.tamila_appels where dossier_id = p_dossier;
  -- La déclaration d'appel fait courir ses délais (908 pour l'appelant), sauf ceux déjà échus.
  if v_nouveau then
    perform private.tamila_appliquer_evenement(v_d, v_a, 'declaration_appel', p_introduit_le, null, '{}', v_uid, true);
  end if;
  perform private.tamila_rejouer_avis(p_dossier, v_uid);
  return v_a.id;
end $$;


--
-- Name: tamila_demander_cloture(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_demander_cloture(p_dossier uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_demande uuid;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null or not found or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Ce dossier ne vous est pas ouvert.' using errcode = '42501';
  end if;
  if v_d.statut not in ('ouvert', 'audit') then
    raise exception 'Ce dossier n''est pas ouvert.' using errcode = '55000';
  end if;
  if not private.tamila_gere_dossier_pour(v_uid, p_dossier) then
    raise exception 'Seul le responsable du dossier, ou un associé, en demande la clôture.' using errcode = '42501';
  end if;
  select d.id into v_demande from public.demandes_validation d
   where d.client_id = v_d.client_id and d.module = 'tamila' and d.type_action = 'cloturer_dossier'
     and d.objet_id = p_dossier::text and d.statut = 'en_attente';
  if v_demande is not null then
    return v_demande;
  end if;
  v_demande := private.tamila_deposer_demande_systeme(v_d.client_id, v_d.entite_id, 'cloturer_dossier', p_dossier,
    'Clôture d''un dossier et effacement de son contenu',
    jsonb_build_object('dossier_id', p_dossier, 'initiateur', v_uid),
    'tamila:cloture:' || p_dossier::text || ':' || extract(epoch from clock_timestamp())::bigint::text);
  perform private.tamila_executer_demande(v_demande);
  return v_demande;
end $$;


--
-- Name: tamila_demander_export(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_demander_export(p_dossier uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_id uuid;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier;
  if v_uid is null or not found or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Ce dossier ne vous est pas ouvert.' using errcode = '42501';
  end if;
  if not private.tamila_lit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Exporter est une lecture : tracez-la d''abord (consulter le dossier).' using errcode = '42501';
  end if;
  if v_d.statut not in ('attente', 'ouvert', 'audit', 'clos') then
    raise exception 'Ce dossier n''a plus de contenu.' using errcode = '55000';
  end if;
  insert into public.tamila_exports (client_id, dossier_id, demande_par) values (v_d.client_id, p_dossier, v_uid)
  returning id into v_id;
  perform private.deposer_travail(v_d.client_id, 'tamila', 'tamila.exporter',
    jsonb_build_object('export', v_id, 'dossier', p_dossier), 'tamila:exporter:' || v_id::text, 3::smallint);
  return v_id;
end $$;


--
-- Name: tamila_demander_export_cabinet(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_demander_export_cabinet(p_client uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid;
begin
  if v_uid is null or not private.a_un_role(p_client, array['gerant']) then
    raise exception 'L''export de tous les dossiers est réservé au gérant.' using errcode = '42501';
  end if;
  insert into public.tamila_exports (client_id, dossier_id, demande_par) values (p_client, null, v_uid)
  returning id into v_id;
  perform private.deposer_travail(p_client, 'tamila', 'tamila.exporter',
    jsonb_build_object('export', v_id, 'cabinet', true), 'tamila:exporter:' || v_id::text, 3::smallint);
  -- Les autres associés sont prévenus.
  perform private.lever_alerte_module(p_client => p_client, p_module => 'tamila', p_niveau => 'attention',
    p_titre => 'Un gérant a demandé l''export de tous les dossiers',
    p_detail => jsonb_build_object('export', v_id, 'demandeur', v_uid),
    p_cle => 'export_cabinet:' || v_id::text, p_pour_client => true);
  return v_id;
end $$;


--
-- Name: tamila_demander_levee_muraille(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_demander_levee_muraille(p_muraille uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_m public.tamila_murailles;
  v_d public.tamila_dossiers;
  v_demande uuid;
begin
  select * into v_m from public.tamila_murailles where id = p_muraille for update;
  if v_uid is null or not found then
    raise exception 'Muraille introuvable.' using errcode = '42501';
  end if;
  if v_m.user_id = v_uid then
    raise exception 'La personne écartée ne demande pas elle-même la levée.' using errcode = '42501';
  end if;
  select * into v_d from public.tamila_dossiers where id = v_m.dossier_id;
  if not private.a_un_role(v_m.client_id, array['gerant'])
     or not private.tamila_voit_dossier_pour(v_uid, v_m.client_id, v_m.dossier_id::text) then
    raise exception 'Seul un gérant demande la levée d''une muraille.' using errcode = '42501';
  end if;
  if v_m.leve_le is not null then
    raise exception 'Cette muraille est déjà levée.' using errcode = '55000';
  end if;
  select d.id into v_demande from public.demandes_validation d
   where d.client_id = v_m.client_id and d.module = 'tamila' and d.type_action = 'lever_muraille'
     and d.statut = 'en_attente' and d.payload ->> 'muraille_id' = v_m.id::text;
  if v_demande is not null then
    return v_demande;
  end if;
  v_demande := private.tamila_deposer_demande_systeme(v_m.client_id, v_d.entite_id, 'lever_muraille', v_m.dossier_id,
    'Levée d''une muraille sur un dossier',
    jsonb_build_object('dossier_id', v_m.dossier_id, 'muraille_id', v_m.id, 'initiateur', v_uid),
    'tamila:lever:' || v_m.id::text || ':' || extract(epoch from clock_timestamp())::bigint::text);
  update public.tamila_murailles set demande_levee_id = v_demande where id = v_m.id;
  perform private.tamila_executer_demande(v_demande);
  return v_demande;
end $$;


--
-- Name: tamila_deposer_confirmation(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_deposer_confirmation(p_delai uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t public.tamila_delais;
  v_d public.tamila_dossiers;
  v_article text;
  v_demande uuid;
begin
  select * into t from public.tamila_delais where id = p_delai;
  select * into v_d from public.tamila_dossiers where id = t.dossier_id;
  select p.article into v_article from public.tamila_regles_procedure p where p.code = t.regle_code;
  v_demande := private.tamila_deposer_demande_systeme(t.client_id, v_d.entite_id, 'confirmer_delai', t.dossier_id,
    'Confirmer un délai de procédure : ' || coalesce('CPC, art. ' || v_article, 'date fixée par le juge')
      || ', échéance le ' || to_char(t.echeance_retenue, 'DD/MM/YYYY'),
    jsonb_build_object('delai_id', t.id, 'echeance', t.echeance_retenue, 'regle', t.regle_code, 'depart', t.depart,
                       'acte', t.acte, 'raisons', to_jsonb(t.raisons)),
    'tamila:confirmer:' || t.id::text);
  update public.tamila_delais set demande_id = v_demande where id = t.id;
  return v_demande;
end $$;


--
-- Name: tamila_deposer_demande_systeme(uuid, uuid, text, uuid, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_deposer_demande_systeme(p_client uuid, p_entite uuid, p_type text, p_dossier uuid, p_resume text, p_payload jsonb, p_cle text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_claims text := current_setting('request.jwt.claims', true);
  v_sub text := current_setting('request.jwt.claim.sub', true);
  v_id uuid;
begin
  perform set_config('request.jwt.claims', '', true);
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('omega.module', 'tamila', true);
  insert into public.demandes_validation (client_id, entite_id, module, type_action, objet_type, objet_id,
                                          resume, payload, cle_idempotence)
  values (p_client, p_entite, 'tamila', p_type, 'tamila_dossier', p_dossier::text, p_resume, p_payload, p_cle)
  returning id into v_id;
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  perform set_config('omega.module', '', true);
  return v_id;
end $$;


--
-- Name: tamila_dossier_ecrit(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_dossier_ecrit(p_dossier uuid, p_avocat boolean) RETURNS public.tamila_dossiers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null then
    if private.tamila_role_session() not in ('service_role', 'postgres') then
      raise exception 'Seul un membre du dossier, ou le serveur, fait ce geste.' using errcode = '42501';
    end if;
    if not found then
      raise exception 'Dossier introuvable.' using errcode = 'P0002';
    end if;
  else
    if not found or not private.tamila_ecrit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
      raise exception 'Vous n''écrivez pas dans ce dossier.' using errcode = '42501';
    end if;
    if p_avocat and not private.tamila_est_avocat(v_uid, v_d.client_id) then
      raise exception 'Ce geste revient à un avocat du dossier.' using errcode = '42501';
    end if;
  end if;
  if v_d.statut not in ('attente', 'ouvert', 'audit') then
    raise exception 'Ce dossier n''est pas ouvert.' using errcode = '55000';
  end if;
  return v_d;
end $$;


--
-- Name: tamila_echeance_effacement(timestamp with time zone, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_echeance_effacement(p_depuis timestamp with time zone, p_jours integer, p_fuseau text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select greatest(p_depuis,
    ((((p_depuis at time zone p_fuseau)::date + p_jours) + time '03:00') at time zone p_fuseau))
$$;


--
-- Name: tamila_echec_demande(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_echec_demande(p_demande uuid, p_motif text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.demandes_validation set statut = 'echec_execution', motif_echec = p_motif where id = p_demande;
  return 'echec_execution';
end $$;


--
-- Name: tamila_ecrit_dossier_pour(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_ecrit_dossier_pour(p_user uuid, p_client uuid, p_objet_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select true
    from public.tamila_dossiers d
    join public.comptes c on c.client_id = d.client_id and c.user_id = p_user
    where d.id = private.tamila_uuid(p_objet_id)
      and d.client_id = p_client
      and d.statut in ('attente', 'ouvert', 'audit')
      and c.role <> 'lecteur'
      and private.tamila_voit_dossier_pour(p_user, p_client, p_objet_id)
      and (exists (select 1 from public.tamila_dossiers_membres dm
                   where dm.dossier_id = d.id and dm.user_id = p_user
                     and dm.role_dossier in ('responsable', 'intervenant')
                     and (dm.jusqu_au is null or dm.jusqu_au > now()))
           or (d.perso and d.proprietaire_perso = p_user)
           or (not d.perso and c.role in ('gerant', 'admin')))
  ), false)
$$;


--
-- Name: tamila_effacer_dossier(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_effacer_dossier(p_dossier uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_d public.tamila_dossiers;
  v_demande public.demandes_validation;
  v_motif text;
  v_pieces integer;
  v_pages integer;
  v_octets bigint;
  v_manifeste jsonb;
  v_export text;
  v_socle jsonb;
  v_preuve public.tamila_effacements;
begin
  if (select auth.uid()) is not null or private.tamila_role_session() <> 'service_role' then
    raise exception 'L''effacement d''un dossier est fait par le serveur, à son échéance.' using errcode = '42501';
  end if;
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if not found then
    raise exception 'Dossier introuvable.' using errcode = 'P0002';
  end if;
  if v_d.statut = 'efface' then
    select * into v_preuve from public.tamila_effacements where dossier_id = p_dossier;
    return jsonb_build_object('dossier', p_dossier, 'deja_efface', true, 'preuve', to_jsonb(v_preuve));
  end if;

  if v_d.statut = 'clos' then
    select * into v_demande from public.demandes_validation where id = v_d.demande_cloture_id;
    if not found or v_demande.type_action <> 'cloturer_dossier' or v_demande.statut <> 'executee'
       or v_demande.politique_id is not null then
      raise exception 'Aucune clôture approuvée pour ce dossier.' using errcode = '55000';
    end if;
    v_motif := 'cloture';
  elsif v_d.statut = 'audit' then
    v_motif := 'fin_audit';
  elsif v_d.statut = 'refuse' then
    v_motif := 'ouverture_refusee';
  else
    raise exception 'Ce dossier n''est pas clos : aucune clôture approuvée.' using errcode = '55000';
  end if;
  if v_d.effacement_prevu_le is null or v_d.effacement_prevu_le > now() then
    raise exception 'L''échéance de l''effacement n''est pas atteinte.' using errcode = '55000';
  end if;
  select m.manifeste into v_manifeste from private.manifestes_effacement m
   where m.cle = v_d.client_id::text || '/tamila_dossier/' || v_d.id::text;
  if v_manifeste is null then
    raise exception 'La liste des fichiers n''est pas préparée (preparer_effacement) : rien ne s''efface sans elle.'
      using errcode = '55000';
  end if;

  select count(*), coalesce(sum(p.nb_pages), 0), coalesce(sum(p.octets), 0) into v_pieces, v_pages, v_octets
  from public.pieces p
  where p.client_id = v_d.client_id and p.objet_type = 'tamila_dossier' and p.objet_id = v_d.id::text;
  select e.empreinte_manifeste into v_export from public.tamila_exports e
   where e.dossier_id = v_d.id and e.empreinte_manifeste is not null
   order by e.pret_le desc nulls last limit 1;

  perform set_config('omega.tamila_effacement', v_d.id::text, true);
  v_socle := private.effacer_objet(v_d.client_id, 'tamila_dossier', v_d.id::text, v_d.id::text, 'tamila.' || v_motif);
  perform set_config('omega.tamila_effacement', '', true);

  update public.tamila_dossiers
     set statut = 'efface', reference_chiffree = null, intitule_chiffre = null, numero_rg_chiffre = null,
         juridiction = null, efface_le = now(), motif_effacement = v_motif
   where id = v_d.id;

  insert into public.tamila_effacements (client_id, dossier_id, motif, demande_id, effacement_objet_id, pieces, pages,
                                         octets, fichiers, empreinte_fichiers, empreinte_export)
  values (v_d.client_id, v_d.id, v_motif, case when v_motif = 'cloture' then v_demande.id end,
          (select o.id from public.effacements_objets o
           where o.client_id = v_d.client_id and o.objet_type = 'tamila_dossier' and o.objet_id = v_d.id::text
           order by o.efface_le desc limit 1),
          v_pieces, v_pages, v_octets, coalesce((v_manifeste ->> 'nombre')::integer, 0),
          v_manifeste ->> 'empreinte_sha256', v_export)
  returning * into v_preuve;

  update public.tamila_cles
     set statut = 'desactivee', desactivee_le = now(), destruction_prevue_le = now() + interval '7 days'
   where dossier_id = v_d.id and statut = 'active';

  return jsonb_build_object('dossier', v_d.id, 'preuve', to_jsonb(v_preuve), 'socle', v_socle);
end $$;


--
-- Name: tamila_est_avocat(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_est_avocat(p_user uuid, p_client uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.comptes c
                 where c.user_id = p_user and c.client_id = p_client and c.role in ('gerant', 'admin', 'valideur'))
$$;


--
-- Name: tamila_executer_confirmation(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_executer_confirmation(p_demande uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  v_d public.demandes_validation;
  t public.tamila_delais;
  v_decideur uuid;
  v_echeance date;
  v_modifie boolean;
begin
  select * into v_d from public.demandes_validation where id = p_demande for update;
  if not found or v_d.module <> 'tamila' or v_d.type_action <> 'confirmer_delai' then
    return null;
  end if;
  if v_d.statut not in ('approuvee', 'rejetee') then
    return v_d.statut;
  end if;
  select * into t from public.tamila_delais
   where id = private.tamila_uuid(v_d.payload ->> 'delai_id') and client_id = v_d.client_id and dossier_id::text = v_d.objet_id
   for update;

  if v_d.statut = 'rejetee' then
    -- Rejeté : le délai reste dans la liste ; un avocat saisit la bonne date, ou l'annule.
    if found and t.statut = 'a_confirmer' and t.demande_id = v_d.id then
      update public.tamila_delais set statut = 'rejete' where id = t.id;
      perform private.journaliser_module(t.client_id, 'tamila', 'tamila.delai.rejete', 'tamila_dossier', t.dossier_id::text,
        jsonb_build_object('delai', t.id, 'demande', v_d.id));
    end if;
    return 'rejetee';
  end if;

  if not found then
    return private.tamila_echec_demande(v_d.id, 'Délai introuvable.');
  end if;
  if v_d.politique_id is not null then
    return private.tamila_echec_demande(v_d.id, 'Chaque délai est confirmé par un avocat : un accord permanent ne le couvre pas.');
  end if;
  if exists (select 1 from public.approbations a
             where a.demande_id = v_d.id and a.decision = 'approuve'
               and not (private.tamila_est_avocat(coalesce(a.au_nom_de, a.user_id), v_d.client_id)
                        and private.tamila_voit_dossier_pour(coalesce(a.au_nom_de, a.user_id), v_d.client_id, v_d.objet_id)
                        and private.tamila_voit_dossier_pour(a.user_id, v_d.client_id, v_d.objet_id))) then
    return private.tamila_echec_demande(v_d.id, 'Un délai est confirmé par un avocat qui a accès au dossier.');
  end if;
  if t.statut <> 'a_confirmer'
     or not (t.demande_id = v_d.id or t.demande_id::text is not distinct from (v_d.payload ->> 'remplace')) then
    return private.tamila_echec_demande(v_d.id, 'Ce délai n''attend plus cette confirmation.');
  end if;
  begin
    v_echeance := (v_d.payload ->> 'echeance')::date;
  exception when others then
    v_echeance := null;
  end;
  if v_echeance is null then
    return private.tamila_echec_demande(v_d.id, 'La date à confirmer est illisible.');
  end if;
  v_modifie := v_d.payload ? 'remplace';
  select coalesce(a.au_nom_de, a.user_id) into v_decideur
  from public.approbations a where a.demande_id = v_d.id and a.decision = 'approuve'
  order by a.decide_le desc limit 1;

  if v_echeance <> t.echeance_retenue then
    if (select d.statut from public.delais d where d.id = t.delai_id) not in ('ouvert', 'depasse') then
      return private.tamila_echec_demande(v_d.id, 'Le délai de B5 a été clos hors de Tamila : saisir la date (tamila_corriger_delai).');
    end if;
    v_porte := private.tamila_ouvrir_porte();
    perform private.notifier_delai(t.delai_id, v_echeance, 'Date modifiée par un avocat avant sa confirmation.');
    perform private.tamila_fermer_porte(v_porte);
  end if;
  update public.tamila_delais
     set statut = 'confirme', echeance_retenue = v_echeance, confirme_par = v_decideur, confirme_le = now(),
         confirmation = case when v_modifie then 'modification' else 'approbation' end, demande_id = v_d.id
   where id = t.id;
  update public.demandes_validation set statut = 'executee' where id = v_d.id;
  perform private.journaliser_module(t.client_id, 'tamila', 'tamila.delai.confirme', 'tamila_dossier', t.dossier_id::text,
    jsonb_build_object('delai', t.id, 'echeance', v_echeance, 'par', v_decideur,
                       'confirmation', case when v_modifie then 'modification' else 'approbation' end));
  return 'executee';
end $$;


--
-- Name: tamila_executer_demande(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_executer_demande(p_demande uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_d public.demandes_validation;
  v_dossier public.tamila_dossiers;
  v_decideur uuid;
  v_nouvelle uuid;
begin
  select * into v_d from public.demandes_validation where id = p_demande for update;
  if not found or v_d.module <> 'tamila' then
    return null;
  end if;
  if v_d.type_action = 'confirmer_delai' then
    return private.tamila_executer_confirmation(p_demande);
  end if;
  select * into v_dossier from public.tamila_dossiers
   where id = private.tamila_uuid(v_d.objet_id) and client_id = v_d.client_id for update;

  if v_d.statut = 'approuvee' then
    if v_d.type_action not in ('ouvrir_dossier', 'cloturer_dossier', 'lever_muraille') then
      return v_d.statut;  -- un autre moteur de Tamila l'exécute
    end if;
    -- Une personne pour chaque décision qui engage : jamais un accord permanent.
    if v_d.politique_id is not null and v_d.type_action in ('cloturer_dossier', 'lever_muraille') then
      update public.demandes_validation
         set statut = 'echec_execution',
             motif_echec = 'Cette décision revient à une personne : un accord permanent ne la couvre pas.'
       where id = v_d.id;
      return 'echec_execution';
    end if;
    -- Chaque approbation vient d'une personne qui voit le dossier.
    if exists (select 1 from public.approbations a
               where a.demande_id = v_d.id and a.decision = 'approuve'
                 and not (private.tamila_voit_dossier_pour(coalesce(a.au_nom_de, a.user_id), v_d.client_id, v_d.objet_id)
                          and private.tamila_voit_dossier_pour(a.user_id, v_d.client_id, v_d.objet_id))) then
      update public.demandes_validation
         set statut = 'echec_execution',
             motif_echec = 'Une approbation vient d''une personne qui n''a pas accès au dossier.'
       where id = v_d.id;
      return 'echec_execution';
    end if;
    if v_dossier.id is null then
      update public.demandes_validation set statut = 'echec_execution', motif_echec = 'Dossier introuvable.' where id = v_d.id;
      return 'echec_execution';
    end if;
    select coalesce(a.au_nom_de, a.user_id) into v_decideur
    from public.approbations a where a.demande_id = v_d.id and a.decision = 'approuve'
    order by a.decide_le desc limit 1;

    if v_d.type_action = 'ouvrir_dossier' then
      if v_dossier.statut <> 'attente' then
        update public.demandes_validation set statut = 'echec_execution',
               motif_echec = 'Le dossier n''attend plus son ouverture.' where id = v_d.id;
        return 'echec_execution';
      end if;
      update public.tamila_dossiers set statut = 'ouvert', ouvert_le = now(), ouvert_par = v_decideur
       where id = v_dossier.id;
      -- Les pièces tenues pendant l'attente partent à la lecture.
      update public.pieces set statut = 'recue'
       where client_id = v_d.client_id and module = 'tamila' and objet_type = 'tamila_dossier'
         and objet_id = v_dossier.id::text and statut = 'a_rattacher';
    elsif v_d.type_action = 'cloturer_dossier' then
      if v_dossier.statut not in ('ouvert', 'audit') then
        update public.demandes_validation set statut = 'echec_execution',
               motif_echec = 'Le dossier n''est plus ouvert.' where id = v_d.id;
        return 'echec_execution';
      end if;
      update public.tamila_dossiers
         set statut = 'clos', statut_avant_cloture = v_dossier.statut, clos_le = now(), demande_cloture_id = v_d.id,
             effacement_prevu_le = private.tamila_echeance_effacement(now(),
               (select r.delai_cloture_jours from public.tamila_reglages r where r.client_id = v_d.client_id),
               private.tamila_fuseau(v_dossier.client_id, v_dossier.entite_id))
       where id = v_dossier.id;
    else -- lever_muraille
      update public.tamila_murailles set leve_le = now(), leve_par = v_decideur
       where id = private.tamila_uuid(v_d.payload ->> 'muraille_id') and dossier_id = v_dossier.id and leve_le is null;
      if not found then
        update public.demandes_validation set statut = 'echec_execution',
               motif_echec = 'La muraille est déjà levée.' where id = v_d.id;
        return 'echec_execution';
      end if;
    end if;
    update public.demandes_validation set statut = 'executee' where id = v_d.id;
    return 'executee';

  elsif v_d.statut = 'rejetee' and v_d.type_action = 'ouvrir_dossier' and v_dossier.id is not null
        and v_dossier.statut = 'attente' and v_dossier.demande_ouverture_id = v_d.id then
    if exists (select 1 from public.approbations a
               where a.demande_id = v_d.id and a.decision = 'rejete'
                 and not private.tamila_voit_dossier_pour(coalesce(a.au_nom_de, a.user_id), v_d.client_id, v_d.objet_id)) then
      -- Un refus venu de qui ne voit pas le dossier est écarté : la demande repart.
      v_nouvelle := private.tamila_deposer_demande_systeme(v_d.client_id, v_d.entite_id, 'ouvrir_dossier', v_dossier.id,
        v_d.resume, v_d.payload || jsonb_build_object('remplace', v_d.id),
        'tamila:ouvrir:' || v_dossier.id::text || ':' || extract(epoch from clock_timestamp())::bigint::text);
      update public.tamila_dossiers set demande_ouverture_id = v_nouvelle where id = v_dossier.id;
      perform private.journaliser_module(v_d.client_id, 'tamila', 'tamila.decision.ecartee', 'demandes_validation',
        v_d.id::text, jsonb_build_object('nouvelle', v_nouvelle));
      return 'rejetee';
    end if;
    -- Refusé : le dossier n'a jamais été lu ; il part à l'effacement dès la prochaine ronde.
    update public.tamila_dossiers set statut = 'refuse', effacement_prevu_le = now() where id = v_dossier.id;
    return 'rejetee';
  end if;
  return v_d.statut;
end $$;


--
-- Name: tamila_export_echec(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_export_echec(p_export uuid, p_motif text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is not null or private.tamila_role_session() <> 'service_role' then
    raise exception 'Un échec d''export est déclaré par le serveur.' using errcode = '42501';
  end if;
  update public.tamila_exports set statut = 'echec', motif_echec = p_motif where id = p_export and statut = 'a_preparer';
  if not found then
    raise exception 'Cet export n''est pas en préparation.' using errcode = '55000';
  end if;
end $$;


--
-- Name: tamila_export_pret(uuid, text, bigint, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_export_pret(p_export uuid, p_chemin text, p_octets bigint, p_empreinte text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_e public.tamila_exports;
begin
  if (select auth.uid()) is not null or private.tamila_role_session() <> 'service_role' then
    raise exception 'Une archive est déclarée prête par le serveur.' using errcode = '42501';
  end if;
  select * into v_e from public.tamila_exports where id = p_export for update;
  if not found or v_e.statut <> 'a_preparer' then
    raise exception 'Cet export n''est pas en préparation.' using errcode = '55000';
  end if;
  if not starts_with(p_chemin, v_e.client_id::text || case when v_e.dossier_id is null then '/tamila/exports/'
                                 else '/tamila_dossier/' || v_e.dossier_id::text || '/exports/' end) then
    raise exception 'L''archive se range sous le cabinet et son dossier.' using errcode = '22023';
  end if;
  update public.tamila_exports
     set statut = 'pret', chemin = p_chemin, octets = p_octets, empreinte_manifeste = p_empreinte, pret_le = now(),
         expire_le = now() + make_interval(days => (select r.conservation_exports_jours from public.tamila_reglages r
                                                    where r.client_id = v_e.client_id))
   where id = p_export;
end $$;


--
-- Name: tamila_export_purge(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_export_purge(p_export uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_e public.tamila_exports;
begin
  if (select auth.uid()) is not null or private.tamila_role_session() <> 'service_role' then
    raise exception 'La purge d''une archive est faite par le serveur.' using errcode = '42501';
  end if;
  select * into v_e from public.tamila_exports where id = p_export for update;
  if not found or v_e.statut not in ('expire', 'echec') then
    raise exception 'Cette archive n''est pas à purger.' using errcode = '55000';
  end if;
  if v_e.chemin is not null and exists (
       select 1 from storage.objects o join private.buckets_locataires b on b.bucket = o.bucket_id
       where o.name = v_e.chemin) then
    raise exception 'Le fichier de l''archive est encore au coffre : le serveur l''efface d''abord.' using errcode = '55000';
  end if;
  update public.tamila_exports set purge_le = now() where id = p_export;
end $$;


--
-- Name: tamila_fermer_porte(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_fermer_porte(p_avant text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  perform set_config('omega.delai_module', coalesce(p_avant, ''), true);
end $$;


--
-- Name: tamila_fuseau(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_fuseau(p_client uuid, p_entite uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select e.fuseau from public.entites e where e.client_id = p_client and e.id = p_entite), 'Europe/Paris')
$$;


--
-- Name: tamila_garder_cle(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_garder_cle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '') then
      return old;
    end if;
    raise exception 'Une clé de dossier ne se supprime pas : elle se détruit au coffre, et la preuve reste.'
      using errcode = '42501';
  end if;
  if (new.id, new.client_id, new.dossier_id, new.fournisseur, new.reference, new.algorithme, new.creee_le)
     is distinct from (old.id, old.client_id, old.dossier_id, old.fournisseur, old.reference, old.algorithme, old.creee_le) then
    raise exception 'Une clé de dossier ne se retouche pas.' using errcode = '42501';
  end if;
  if new.statut is distinct from old.statut and not (
       (old.statut = 'active' and new.statut = 'desactivee')
    or (old.statut = 'desactivee' and new.statut = 'detruite')) then
    raise exception 'Passage refusé : % vers %.', old.statut, new.statut using errcode = '23514';
  end if;
  if new.enveloppe is distinct from old.enveloppe and new.statut <> 'detruite' then
    raise exception 'L''enveloppe d''une clé ne change qu''à sa destruction.' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: tamila_garder_delai(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_garder_delai() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '')
     or coalesce(current_setting('omega.effacement_objet', true), '') = 'oui' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Un délai de procédure ne se retire pas : il se clôt sur l''acte déposé, ou s''annule avec son motif.'
      using errcode = '42501';
  end if;
  if old.statut in ('clos', 'annule') then
    raise exception 'Ce délai est clos : il ne change plus.' using errcode = '55000';
  end if;
  if (new.id, new.client_id, new.dossier_id, new.nature, new.regle_code, new.regle_version, new.depart, new.territoire,
      new.echeance_calculee, new.cree_le, new.cree_par)
     is distinct from
     (old.id, old.client_id, old.dossier_id, old.nature, old.regle_code, old.regle_version, old.depart, old.territoire,
      old.echeance_calculee, old.cree_le, old.cree_par) then
    raise exception 'Le calcul d''un délai ne se retouche pas : l''avocat corrige la date retenue.' using errcode = '42501';
  end if;
  if new.statut is distinct from old.statut and not (
       (old.statut = 'a_confirmer' and new.statut in ('confirme', 'rejete', 'interrompu', 'clos', 'annule'))
    or (old.statut = 'rejete' and new.statut in ('confirme', 'interrompu', 'clos', 'annule'))
    or (old.statut = 'confirme' and new.statut in ('interrompu', 'clos', 'annule'))
    or (old.statut = 'interrompu' and new.statut in ('confirme', 'clos', 'annule'))) then
    raise exception 'Passage refusé : % vers %.', old.statut, new.statut using errcode = '23514';
  end if;
  new.maj_le := now();
  return new;
end $$;


--
-- Name: tamila_garder_dossier(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_garder_dossier() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return old;
  end if;
  if coalesce(current_setting('omega.tamila_effacement', true), '') = old.id::text then
    return null;
  end if;
  raise exception 'Un dossier Tamila ne s''efface que par sa clôture approuvée, à son échéance.'
    using errcode = '42501';
end $$;


--
-- Name: tamila_gere_dossier_pour(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_gere_dossier_pour(p_user uuid, p_dossier uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select true
    from public.tamila_dossiers d
    join public.comptes c on c.client_id = d.client_id and c.user_id = p_user
    where d.id = p_dossier
      and d.statut in ('attente', 'ouvert', 'audit')
      and private.tamila_voit_dossier_pour(p_user, d.client_id, d.id::text)
      and (exists (select 1 from public.tamila_dossiers_membres dm
                   where dm.dossier_id = d.id and dm.user_id = p_user and dm.role_dossier = 'responsable'
                     and (dm.jusqu_au is null or dm.jusqu_au > now()))
           or (d.perso and d.proprietaire_perso = p_user)
           or (not d.perso and c.role in ('gerant', 'admin')))
  ), false)
$$;


--
-- Name: tamila_installer(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_installer(p_client uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_fuseau text;
begin
  if not exists (select 1 from public.clients where id = p_client) then
    raise exception 'Cabinet introuvable.' using errcode = 'P0002';
  end if;
  if v_uid is null then
    if private.tamila_role_session() not in ('service_role', 'postgres') then
      raise exception 'Seul un gérant, ou Omega, installe Tamila.' using errcode = '42501';
    end if;
  elsif not private.a_un_role(p_client, array['gerant']) then
    raise exception 'Seul un gérant, ou Omega, installe Tamila.' using errcode = '42501';
  end if;

  insert into public.tamila_reglages (client_id) values (p_client) on conflict (client_id) do nothing;

  -- La clôture revient aux associés ; la levée d'une muraille, au gérant ; la
  -- confirmation d'un délai, à un avocat.
  insert into public.regles_validation (client_id, module, type_action, roles_autorises, approbations_requises)
  select p_client, 'tamila', t.type_action, t.roles, 1
  from (values ('cloturer_dossier', array['gerant', 'admin']), ('lever_muraille', array['gerant']),
               ('confirmer_delai', array['gerant', 'admin', 'valideur'])) t(type_action, roles)
  where not exists (select 1 from public.regles_validation r
                    where r.client_id = p_client and r.module = 'tamila' and r.type_action = t.type_action);

  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.principale;
  perform private.regler_battement(p_client, 'tamila_coffre', interval '2 hours', null, coalesce(v_fuseau, 'Europe/Paris'));
  perform private.regler_battement(p_client, 'tamila_delais', interval '2 hours', null, coalesce(v_fuseau, 'Europe/Paris'));
end $$;


--
-- Name: tamila_interrompre(uuid, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_interrompre(p_delai uuid, p_motif text, p_depuis date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  t public.tamila_delais;
begin
  select * into t from public.tamila_delais where id = p_delai for update;
  if t.statut not in ('a_confirmer', 'confirme', 'rejete') then
    raise exception 'Ce délai ne court pas : il ne s''interrompt pas.' using errcode = '55000';
  end if;
  if t.nature <> 'regle' or not exists (select 1 from public.tamila_regles_procedure p
                                        where p.code = t.regle_code and p.interruptible) then
    raise exception 'Seuls les délais pour conclure s''interrompent (art. 915-3 ; ancien art. 910-2).' using errcode = '22023';
  end if;
  if p_motif is null or p_motif not in ('mediation', 'conciliation', 'procedure_participative', 'mise_en_etat_simplifiee',
                                        'audience_reglement_amiable', 'a_preciser') then
    raise exception 'Cause d''interruption inconnue : %.', coalesce(p_motif, 'vide') using errcode = '22023';
  end if;
  if p_depuis is null or p_depuis > greatest(private.tamila_aujourdhui(t.territoire), private.tamila_aujourdhui('metropole')) then
    raise exception 'L''interruption part d''une date passée ou du jour.' using errcode = '22023';
  end if;
  perform private.tamila_annuler_confirmation(t.id);
  update public.tamila_delais set statut = 'interrompu', interrompu_le = p_depuis, motif_interruption = p_motif where id = t.id;
  if (select d.statut from public.delais d where d.id = t.delai_id) in ('ouvert', 'depasse') then
    v_porte := private.tamila_ouvrir_porte();
    perform private.clore_delai(t.delai_id, 'annule',
      'Interrompu (CPC, art. 915-3) : ' || private.tamila_libelle(p_motif) || ' ; l''avocat saisit la nouvelle échéance.');
    perform private.tamila_fermer_porte(v_porte);
  end if;
  perform private.journaliser_module(t.client_id, 'tamila', 'tamila.delai.interrompu', 'tamila_dossier', t.dossier_id::text,
    jsonb_build_object('delai', t.id, 'motif', p_motif, 'depuis', p_depuis));
end $$;


--
-- Name: tamila_interrompre_delai(uuid, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_interrompre_delai(p_delai uuid, p_motif text, p_depuis date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t public.tamila_delais;
begin
  select * into t from public.tamila_delais where id = p_delai;
  if not found then
    raise exception 'Délai introuvable.' using errcode = '42501';
  end if;
  perform private.tamila_dossier_ecrit(t.dossier_id, true);
  perform private.tamila_interrompre(p_delai, p_motif, p_depuis);
end $$;


--
-- Name: tamila_libelle(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_libelle(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p
    when 'signifier_declaration' then 'Signifier la déclaration d''appel'
    when 'conclure' then 'Remettre ses conclusions au greffe et les notifier'
    when 'signifier_conclusions' then 'Signifier les conclusions aux parties non constituées'
    when 'autre' then 'Accomplir l''acte fixé par le juge'
    when 'calcul_errone' then 'calcul à reprendre'
    when 'date_notifiee' then 'date notifiée par le greffe'
    when 'delai_modifie_par_le_juge' then 'délai modifié par le juge (art. 911, al. 2, et 906-2, al. 6)'
    when 'reprise_apres_interruption' then 'reprise après interruption'
    when 'desistement' then 'désistement'
    when 'caducite_prononcee' then 'caducité prononcée'
    when 'irrecevabilite_prononcee' then 'irrecevabilité prononcée'
    when 'radiation' then 'radiation'
    when 'procedure_changee' then 'la procédure a changé'
    when 'erreur' then 'délai posé par erreur'
    when 'doublon' then 'doublon'
    when 'mediation' then 'médiation'
    when 'conciliation' then 'conciliation'
    when 'procedure_participative' then 'convention de procédure participative'
    when 'mise_en_etat_simplifiee' then 'convention de mise en état simplifiée'
    when 'audience_reglement_amiable' then 'audience de règlement amiable'
    when 'a_preciser' then 'cause à préciser'
    else p end
$$;


--
-- Name: tamila_lieu_conservation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_lieu_conservation() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select r.valeur from private.reglages r where r.cle = 'tamila_lieu_conservation'),
                  'non renseigné')
$$;


--
-- Name: tamila_lit_dossier_pour(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_lit_dossier_pour(p_user uuid, p_client uuid, p_objet_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.tamila_voit_dossier_pour(p_user, p_client, p_objet_id)
     and exists (select 1 from public.lectures l
                 where l.client_id = p_client and l.objet_type = 'tamila_dossier' and l.objet_id = p_objet_id
                   and l.user_id = p_user and l.lu_le > now() - interval '30 minutes')
$$;


--
-- Name: tamila_modifier_partie(uuid, bytea, text, text, text, bytea); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_modifier_partie(p_partie uuid, p_nom bytea DEFAULT NULL::bytea, p_qualite text DEFAULT NULL::text, p_residence text DEFAULT NULL::text, p_role_procedure text DEFAULT NULL::text, p_courriels bytea DEFAULT NULL::bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_p public.tamila_parties;
begin
  select * into v_p from public.tamila_parties where id = p_partie for update;
  if v_uid is null or not found or not private.tamila_ecrit_dossier_pour(v_uid, v_p.client_id, v_p.dossier_id::text) then
    raise exception 'Vous n''écrivez pas dans ce dossier.' using errcode = '42501';
  end if;
  update public.tamila_parties
     set nom_chiffre = coalesce(p_nom, nom_chiffre), qualite = coalesce(p_qualite, qualite),
         residence = coalesce(p_residence, residence), role_procedure = coalesce(p_role_procedure, role_procedure),
         courriels_chiffres = coalesce(p_courriels, courriels_chiffres)
   where id = p_partie;
end $$;


--
-- Name: tamila_orienter(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_orienter(p_appel uuid, p_procedure text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_procedure is null or p_procedure not in ('a_orienter', 'mise_en_etat', 'bref_delai') then
    raise exception 'Procédure inconnue : %.', coalesce(p_procedure, 'vide') using errcode = '22023';
  end if;
  update public.tamila_appels set procedure = p_procedure, maj_le = now() where id = p_appel and procedure <> p_procedure;
  update public.tamila_delais t
     set raisons = array(select r from (select distinct r from unnest(t.raisons || 'procedure_changee'::text) r) x
                         order by r collate "C")
    from public.tamila_regles_procedure p
   where t.appel_id = p_appel and t.regle_code = p.code and not (p_procedure = any (p.procedures))
     and t.statut in ('a_confirmer', 'confirme', 'rejete') and not ('procedure_changee' = any (t.raisons));
end $$;


--
-- Name: tamila_orienter_appel(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_orienter_appel(p_dossier uuid, p_procedure text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_a public.tamila_appels;
begin
  perform private.tamila_dossier_ecrit(p_dossier, false);
  select * into v_a from public.tamila_appels where dossier_id = p_dossier for update;
  if not found then
    raise exception 'Déclarez d''abord l''appel du dossier.' using errcode = 'P0002';
  end if;
  perform private.tamila_orienter(v_a.id, p_procedure);
end $$;


--
-- Name: tamila_ouvrir_porte(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_ouvrir_porte() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_avant text := current_setting('omega.delai_module', true);
begin
  perform set_config('omega.delai_module', 'tamila', true);
  return v_avant;
end $$;


--
-- Name: tamila_poser(public.tamila_dossiers, public.tamila_appels, text, date, text, uuid, text[], uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_poser(p_dossier public.tamila_dossiers, p_appel public.tamila_appels, p_regle text, p_depart date, p_residence text, p_avis uuid, p_raisons text[], p_uid uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  p public.tamila_regles_procedure;
  v_calcul jsonb;
  v_echeance date;
  v_b5 uuid;
  v_id uuid;
begin
  select * into p from public.tamila_regles_procedure where code = p_regle;
  if not found then
    raise exception 'Règle de procédure inconnue : %.', coalesce(p_regle, 'vide') using errcode = '22023';
  end if;
  if p.regime <> p_appel.regime then
    raise exception 'La règle % est celle des appels introduits %, l''appel du dossier a été introduit le % (décret n° 2023-1391, art. 16).',
      p_regle, case p.regime when 'cpc' then 'depuis le 01/09/2024' else 'avant le 01/09/2024' end,
      to_char(p_appel.introduit_le, 'DD/MM/YYYY') using errcode = '22023';
  end if;
  if not (p_appel.procedure = any (p.procedures)) then
    raise exception 'La règle % vaut pour la procédure %, l''appel est en procédure « % » : déclarez d''abord son orientation.',
      p_regle, array_to_string(p.procedures, ' ou '), p_appel.procedure using errcode = '22023';
  end if;
  if p_depart is null or p_depart < p_appel.introduit_le then
    raise exception 'Un délai de l''appel ne part pas avant la déclaration d''appel (%).', to_char(p_appel.introduit_le, 'DD/MM/YYYY')
      using errcode = '22023';
  end if;
  v_calcul := private.tamila_calculer_delai(p_regle, p_depart, p_appel.territoire, p_residence);
  v_echeance := (v_calcul ->> 'echeance')::date;

  -- Le délai de B5 : la règle, l'augmentation (lot 16), son calcul et ses rappels.
  v_porte := private.tamila_ouvrir_porte();
  v_b5 := private.poser_delai(p_dossier.client_id, 'tamila', 'tamila_dossier', p_dossier.id::text,
    p.libelle_court || ' (CPC, art. ' || p.article || ')', p_regle, p_depart, p_appel.territoire, '{7,2,0}',
    p_dossier.responsable_id, private.tamila_libelle(p.acte),
    'tamila:' || p_dossier.id::text || ':' || p_regle || ':' || p_depart::text,
    (v_calcul ->> 'augmentation_mois')::integer);
  perform private.tamila_fermer_porte(v_porte);
  select t.id into v_id from public.tamila_delais t where t.delai_id = v_b5;
  if v_id is not null then
    return v_id;
  end if;
  if (select d.echeance from public.delais d where d.id = v_b5) <> v_echeance then
    raise exception 'B5 et Tamila divergent pour % au % : le délai n''est pas posé.', p_regle, p_depart using errcode = 'XX000';
  end if;

  insert into public.tamila_delais (client_id, dossier_id, appel_id, avis_id, delai_id, nature, regle_code, regle_version, acte,
    depart, territoire, residence, augmentation_mois, motif_augmentation, echeance_calculee, echeance_retenue, raisons, calcul,
    statut, responsable_id, cree_par)
  values (p_dossier.client_id, p_dossier.id, p_appel.id, p_avis, v_b5, 'regle', p_regle, (v_calcul ->> 'version')::smallint,
    p.acte, p_depart, p_appel.territoire, p_residence, (v_calcul ->> 'augmentation_mois')::smallint,
    v_calcul ->> 'motif_augmentation', v_echeance, v_echeance,
    array(select r from (select distinct r from unnest(array(select jsonb_array_elements_text(v_calcul -> 'raisons'))
                                                        || coalesce(p_raisons, '{}')) r) x
          order by r collate "C"),
    v_calcul, 'a_confirmer', p_dossier.responsable_id, p_uid)
  returning id into v_id;
  perform private.tamila_deposer_confirmation(v_id);
  return v_id;
end $$;


--
-- Name: tamila_poser_date(uuid, date, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_poser_date(p_dossier uuid, p_echeance date, p_acte text DEFAULT 'autre'::text, p_source text DEFAULT 'saisie'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
begin
  v_d := private.tamila_dossier_ecrit(p_dossier, false);
  return private.tamila_poser_date_fixee(v_d,
    coalesce((select a.territoire from public.tamila_appels a where a.dossier_id = p_dossier), v_d.territoire, 'metropole'),
    p_echeance, p_acte, p_source, null, '{}', v_uid,
    v_uid is not null and private.tamila_est_avocat(v_uid, v_d.client_id));
end $$;


--
-- Name: tamila_poser_date_fixee(public.tamila_dossiers, text, date, text, text, uuid, text[], uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_poser_date_fixee(p_dossier public.tamila_dossiers, p_territoire text, p_echeance date, p_acte text, p_source text, p_avis uuid, p_raisons text[], p_uid uuid, p_confirme boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_porte text;
  v_b5 uuid;
  v_id uuid;
begin
  if p_echeance is null then
    raise exception 'La date fixée est nécessaire.' using errcode = '22023';
  end if;
  if p_acte is null or p_acte not in ('signifier_declaration', 'conclure', 'signifier_conclusions', 'autre') then
    raise exception 'Acte inconnu : %.', coalesce(p_acte, 'vide') using errcode = '22023';
  end if;
  if p_source is null or p_source not in ('calendrier_de_procedure', 'ordonnance', 'avis', 'saisie') then
    raise exception 'Source inconnue : %.', coalesce(p_source, 'vide') using errcode = '22023';
  end if;
  v_porte := private.tamila_ouvrir_porte();
  v_b5 := private.poser_delai_date(p_dossier.client_id, 'tamila', 'tamila_dossier', p_dossier.id::text,
    'Date fixée par le juge : ' || lower(private.tamila_libelle(p_acte)), p_echeance,
    case p_source when 'calendrier_de_procedure' then 'Calendrier de procédure'
                  when 'ordonnance' then 'Ordonnance du conseiller de la mise en état'
                  when 'avis' then 'Avis du greffe' else 'Saisie au dossier' end,
    p_territoire, '{7,2,0}', p_dossier.responsable_id, private.tamila_libelle(p_acte),
    'tamila:' || p_dossier.id::text || ':date:' || p_echeance::text || ':' || p_acte || ':' || coalesce(p_avis::text, 'saisie'));
  perform private.tamila_fermer_porte(v_porte);
  select t.id into v_id from public.tamila_delais t where t.delai_id = v_b5;
  if v_id is not null then
    return v_id;
  end if;
  insert into public.tamila_delais (client_id, dossier_id, appel_id, avis_id, delai_id, nature, acte, territoire, echeance_retenue,
    raisons, source_date, statut, confirme_par, confirme_le, confirmation, responsable_id, cree_par)
  values (p_dossier.client_id, p_dossier.id, (select a.id from public.tamila_appels a where a.dossier_id = p_dossier.id), p_avis,
    v_b5, 'date_fixee', p_acte, p_territoire, p_echeance, coalesce(p_raisons, '{}'), p_source,
    case when p_confirme then 'confirme' else 'a_confirmer' end,
    case when p_confirme then p_uid end, case when p_confirme then now() end, case when p_confirme then 'saisie' end,
    p_dossier.responsable_id, p_uid)
  returning id into v_id;
  if not p_confirme then
    perform private.tamila_deposer_confirmation(v_id);
  end if;
  return v_id;
end $$;


--
-- Name: tamila_poser_delai(uuid, text, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_poser_delai(p_dossier uuid, p_regle text, p_depart date, p_residence text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_d public.tamila_dossiers;
  v_a public.tamila_appels;
begin
  v_d := private.tamila_dossier_ecrit(p_dossier, false);
  select * into v_a from public.tamila_appels where dossier_id = p_dossier;
  if not found then
    raise exception 'Déclarez d''abord l''appel du dossier : sa date fixe le régime des délais.' using errcode = 'P0002';
  end if;
  return private.tamila_poser(v_d, v_a, p_regle, p_depart,
    coalesce(p_residence, private.tamila_residence_client(p_dossier, v_a.territoire)), null, '{}', (select auth.uid()));
end $$;


--
-- Name: tamila_poser_muraille(uuid, uuid, bytea); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_poser_muraille(p_dossier uuid, p_user uuid, p_motif bytea DEFAULT NULL::bytea) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_id uuid;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null or not found or not private.a_un_role(v_d.client_id, array['gerant'])
     or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Seul un gérant pose une muraille, sur un dossier qu''il voit.' using errcode = '42501';
  end if;
  if p_user = v_uid then
    raise exception 'Un gérant ne se met pas lui-même derrière une muraille : un autre gérant la pose.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = v_d.client_id) then
    raise exception 'Cette personne n''est pas membre du cabinet.' using errcode = '23503';
  end if;
  if v_d.perso and p_user = v_d.proprietaire_perso then
    raise exception 'Le titulaire d''une clientèle personnelle ne s''écarte pas de son dossier.' using errcode = '22023';
  end if;
  select m.id into v_id from public.tamila_murailles m
   where m.dossier_id = p_dossier and m.user_id = p_user and m.leve_le is null;
  if v_id is not null then
    return v_id;
  end if;
  if exists (select 1 from public.tamila_dossiers_membres dm
             where dm.dossier_id = p_dossier and dm.user_id = p_user and dm.role_dossier = 'responsable')
     and not exists (select 1 from public.tamila_dossiers_membres o
                     where o.dossier_id = p_dossier and o.user_id <> p_user and o.role_dossier = 'responsable'
                       and (o.jusqu_au is null or o.jusqu_au > now())) then
    raise exception 'Cette personne est le seul responsable du dossier : désignez-en un autre d''abord.' using errcode = '23514';
  end if;
  delete from public.tamila_dossiers_membres where dossier_id = p_dossier and user_id = p_user;
  if v_d.responsable_id = p_user then
    update public.tamila_dossiers
       set responsable_id = (select o.user_id from public.tamila_dossiers_membres o
                             where o.dossier_id = p_dossier and o.role_dossier = 'responsable'
                             order by o.ajoute_le limit 1)
     where id = p_dossier;
  end if;
  insert into public.tamila_murailles (client_id, dossier_id, user_id, motif_chiffre, pose_par)
  values (v_d.client_id, p_dossier, p_user, p_motif, v_uid)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: tamila_preuves_immuables(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_preuves_immuables() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return old;
  end if;
  raise exception 'La preuve d''un effacement ne se modifie pas et ne s''efface pas.' using errcode = '42501';
end $$;


--
-- Name: tamila_registre_hors_vue(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_registre_hors_vue(p_client uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := (select auth.uid());
begin
  if v_uid is null or not private.a_un_role(p_client, array['gerant', 'admin']) then
    raise exception 'Ce compte revient aux associés.' using errcode = '42501';
  end if;
  return (select count(*)::integer from public.tamila_dossiers d
          where d.client_id = p_client and d.statut in ('attente', 'ouvert', 'audit', 'clos')
            and not private.tamila_voit_dossier_pour(v_uid, p_client, d.id::text));
end $$;


--
-- Name: tamila_rejouer_avis(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_rejouer_avis(p_dossier uuid, p_uid uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r record; n integer := 0;
begin
  for r in
    select a.id from public.tamila_avis a
    where a.dossier_id = p_dossier and a.statut = 'sans_effet' and a.effet in ('appel_a_declarer', 'juridiction_a_preciser')
    order by a.date_avis, a.cree_le
  loop
    perform private.tamila_appliquer_avis(r.id, p_uid);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: tamila_residence_client(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_residence_client(p_dossier uuid, p_territoire text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select 'inconnue'::text from public.tamila_parties pt
     where pt.dossier_id = p_dossier and pt.qualite = 'client' and pt.residence = 'inconnue' limit 1),
    (select pt.residence from public.tamila_parties pt
     cross join lateral private.tamila_augmentation(p_territoire, pt.residence) a
     where pt.dossier_id = p_dossier and pt.qualite = 'client'
     order by a.mois, pt.residence limit 1),
    'inconnue')
$$;


--
-- Name: tamila_retirer_membre(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_retirer_membre(p_dossier uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_d public.tamila_dossiers;
  v_m public.tamila_dossiers_membres;
begin
  select * into v_d from public.tamila_dossiers where id = p_dossier for update;
  if v_uid is null or not found or not private.tamila_voit_dossier_pour(v_uid, v_d.client_id, p_dossier::text) then
    raise exception 'Ce dossier ne vous est pas ouvert.' using errcode = '42501';
  end if;
  if p_user <> v_uid and not private.tamila_gere_dossier_pour(v_uid, p_dossier) then
    raise exception 'Seul le responsable du dossier, ou un associé, en retire quelqu''un.' using errcode = '42501';
  end if;
  select * into v_m from public.tamila_dossiers_membres where dossier_id = p_dossier and user_id = p_user;
  if not found then
    raise exception 'Cette personne n''est pas membre du dossier.' using errcode = 'P0002';
  end if;
  if v_d.perso and p_user = v_d.proprietaire_perso then
    raise exception 'Le titulaire d''une clientèle personnelle reste membre de son dossier.' using errcode = '23514';
  end if;
  if v_m.role_dossier = 'responsable' and not exists (
       select 1 from public.tamila_dossiers_membres o
       where o.dossier_id = p_dossier and o.user_id <> p_user and o.role_dossier = 'responsable'
         and (o.jusqu_au is null or o.jusqu_au > now())) then
    raise exception 'Le dossier garde toujours un responsable : désignez-en un autre d''abord.' using errcode = '23514';
  end if;
  delete from public.tamila_dossiers_membres where id = v_m.id;
  if v_d.responsable_id = p_user then
    update public.tamila_dossiers
       set responsable_id = (select o.user_id from public.tamila_dossiers_membres o
                             where o.dossier_id = p_dossier and o.role_dossier = 'responsable'
                             order by o.ajoute_le limit 1)
     where id = p_dossier;
  end if;
end $$;


--
-- Name: tamila_retirer_partie(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_retirer_partie(p_partie uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_p public.tamila_parties;
begin
  select * into v_p from public.tamila_parties where id = p_partie for update;
  if v_uid is null or not found or not private.tamila_ecrit_dossier_pour(v_uid, v_p.client_id, v_p.dossier_id::text) then
    raise exception 'Vous n''écrivez pas dans ce dossier.' using errcode = '42501';
  end if;
  delete from public.tamila_parties where id = p_partie;
end $$;


--
-- Name: tamila_role_session(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_role_session() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(nullif(current_setting('role', true), 'none'), session_user::text)
$$;


--
-- Name: tamila_tache_horaire(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_tache_horaire(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_effacements integer := 0;
  v_retards integer := 0;
  v_cles integer := 0;
  v_exports integer := 0;
  v_acces integer := 0;
  v_decisions integer := 0;
begin
  -- Les décisions qu'aucun événement n'aurait portées.
  v_decisions := private.tamila_balayer_decisions();

  -- Les effacements échus partent à l'ouvrier ; échus depuis plus de 24 h, une alerte critique.
  for r in
    select d.id, d.client_id, d.effacement_prevu_le from public.tamila_dossiers d
    where d.statut in ('clos', 'audit', 'refuse') and d.effacement_prevu_le <= p_maintenant
  loop
    perform private.deposer_travail(r.client_id, 'tamila', 'tamila.effacer_dossier',
      jsonb_build_object('dossier', r.id), 'tamila:effacer:' || r.id::text, 5::smallint);
    v_effacements := v_effacements + 1;
    if r.effacement_prevu_le < p_maintenant - interval '24 hours' then
      perform private.lever_alerte_module(p_client => r.client_id, p_module => 'tamila', p_niveau => 'critique',
        p_titre => 'Effacement de dossier en retard de plus de 24 heures',
        p_detail => jsonb_build_object('dossier', r.id, 'echeance', r.effacement_prevu_le),
        p_cle => 'effacement_retard:' || r.id::text, p_pour_client => false);
      v_retards := v_retards + 1;
    end if;
  end loop;

  -- Les clés désactivées depuis sept jours se détruisent au coffre.
  for r in
    select k.dossier_id, k.client_id from public.tamila_cles k
    where k.statut = 'desactivee' and k.destruction_prevue_le <= p_maintenant
  loop
    perform private.deposer_travail(r.client_id, 'tamila', 'tamila.detruire_cle',
      jsonb_build_object('dossier', r.dossier_id), 'tamila:cle:' || r.dossier_id::text, 5::smallint);
    v_cles := v_cles + 1;
  end loop;

  -- Les archives échues se purgent.
  for r in
    update public.tamila_exports set statut = 'expire'
     where statut = 'pret' and expire_le <= p_maintenant
    returning id, client_id, chemin
  loop
    perform private.deposer_travail(r.client_id, 'tamila', 'tamila.purger_export',
      jsonb_build_object('export', r.id, 'chemin', r.chemin), 'tamila:purger:' || r.id::text, 0::smallint);
    v_exports := v_exports + 1;
  end loop;

  -- Les accès bornés échus sont retirés (journalisés comme toute sortie).
  delete from public.tamila_dossiers_membres where jusqu_au is not null and jusqu_au <= p_maintenant;
  get diagnostics v_acces = row_count;

  -- Le battement de chaque cabinet, même sans rien à faire.
  for r in select g.client_id from public.tamila_reglages g loop
    perform private.battre(r.client_id, 'tamila_coffre',
      jsonb_build_object('effacements_dus', v_effacements, 'cles_a_detruire', v_cles), null);
  end loop;

  return jsonb_build_object('effacements', v_effacements, 'retards', v_retards, 'cles', v_cles,
                            'exports', v_exports, 'acces_retires', v_acces, 'decisions_rattrapees', v_decisions);
end $$;


--
-- Name: tamila_telecharger_export(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_telecharger_export(p_export uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_e public.tamila_exports;
begin
  select * into v_e from public.tamila_exports where id = p_export for update;
  if v_uid is null or not found
     or (v_e.dossier_id is null and not private.a_un_role(v_e.client_id, array['gerant']))
     or (v_e.dossier_id is not null and not private.tamila_voit_dossier_pour(v_uid, v_e.client_id, v_e.dossier_id::text)) then
    raise exception 'Cet export ne vous est pas ouvert.' using errcode = '42501';
  end if;
  if v_e.statut <> 'pret' or v_e.expire_le <= now() then
    raise exception 'Cette archive n''est pas disponible.' using errcode = '55000';
  end if;
  if v_e.dossier_id is not null then
    perform private.tracer_lecture(v_e.client_id, 'tamila_dossier', v_e.dossier_id::text, 'export.telechargement');
  end if;
  update public.tamila_exports set telechargements = telechargements + 1, telecharge_le = now() where id = p_export;
  return v_e.chemin;
end $$;


--
-- Name: tamila_traiter_decisions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_traiter_decisions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r public.travaux;
  v text;
  n integer := 0;
begin
  for r in select * from private.prendre_travaux(array['tamila.decision'], 100, interval '5 minutes', 'tamila-base') loop
    begin
      v := private.tamila_executer_demande(private.tamila_uuid(r.charge ->> 'demande'));
      perform private.finir_travail(r.id, jsonb_build_object('statut', v));
    exception when others then
      perform private.echouer_travail(r.id, left(sqlerrm, 500));
    end;
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: tamila_uuid(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_uuid(p text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  return p::uuid;
exception when invalid_text_representation then
  return null;
end $$;


--
-- Name: tamila_voit_dossier_pour(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tamila_voit_dossier_pour(p_user uuid, p_client uuid, p_objet_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select true
    from public.tamila_dossiers d
    join public.comptes c on c.client_id = d.client_id and c.user_id = p_user
    where d.id = private.tamila_uuid(p_objet_id)
      and d.client_id = p_client
      and not exists (select 1 from public.tamila_murailles m
                      where m.dossier_id = d.id and m.user_id = p_user and m.leve_le is null)
      and (exists (select 1 from public.tamila_dossiers_membres dm
                   where dm.dossier_id = d.id and dm.user_id = p_user
                     and (dm.jusqu_au is null or dm.jusqu_au > now()))
           or (d.perso and d.proprietaire_perso = p_user)
           or (not d.perso and c.role in ('gerant', 'admin')
               and private.perimetre_couvre(p_user, d.client_id, d.entite_id)))
  ), false)
$$;


--
-- Name: terminer_lecture(uuid, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.terminer_lecture(p_instantane uuid, p_resultat jsonb, p_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  b public.branchements;
  j public.branchements_jeux;
  v_statut text := p_resultat ->> 'statut';
  v_lignes integer;
  v_deposees integer;
  v_anomalies integer;
  v_releve uuid;
  v_motif text := left(p_resultat ->> 'motif', 500);
begin
  select * into i from public.instantanes where id = p_instantane for update;
  if not found then
    raise exception 'Instantané introuvable.' using errcode = 'P0002';
  end if;
  if i.statut <> 'en_lecture' then
    raise exception 'L''instantané n''est pas en lecture (statut %).', i.statut using errcode = '55000';
  end if;
  if v_statut is null or v_statut not in ('lu', 'a_classer', 'rejete', 'echec') then
    raise exception 'Statut de lecture inconnu : %.', coalesce(v_statut, 'vide') using errcode = '22023';
  end if;
  select * into b from public.branchements where id = i.branchement_id;
  v_releve := i.releve_id;

  if v_statut = 'lu' then
    select * into j from public.branchements_jeux where branchement_id = b.id and code = p_resultat ->> 'jeu';
    if not found then
      raise exception 'Jeu inconnu pour ce branchement : %.', coalesce(p_resultat ->> 'jeu', 'vide') using errcode = '22023';
    end if;
    if i.jeu_id is not null and i.jeu_id <> j.id then
      raise exception 'Cet export est rangé dans un autre jeu que « % ».', j.code using errcode = '22023';
    end if;
    v_lignes := (p_resultat ->> 'lignes')::integer;
    select count(*), count(*) filter (where l.anomalies is not null) into v_deposees, v_anomalies
    from public.instantanes_lignes l where l.instantane_id = i.id;
    if v_lignes is null or v_lignes <> v_deposees then
      raise exception 'Lignes annoncées (%) et lignes déposées (%) ne concordent pas.', coalesce(v_lignes::text, 'aucune'), v_deposees
        using errcode = '22023';
    end if;
    -- Un seul export par jeu dans un relevé : le second fait son propre relevé.
    if exists (select 1 from public.instantanes o where o.releve_id = i.releve_id and o.id <> i.id and o.jeu_id = j.id) then
      insert into public.releves (client_id, branchement_id, canal, expediteur, recu_le)
      select r.client_id, r.branchement_id, r.canal, r.expediteur, r.recu_le from public.releves r where r.id = i.releve_id
      returning id into v_releve;
    end if;
    update public.instantanes
       set statut = 'lu', jeu_id = j.id, releve_id = v_releve, lignes = v_lignes, anomalies = v_anomalies,
           colonnes = p_resultat -> 'colonnes', format = p_resultat -> 'format', motif = v_motif,
           version_releve = left(p_version, 40), lu_le = now()
     where id = i.id;
    update public.pieces set statut = 'lue', lue_le = now(), version_lecteur = left(p_version, 40), motif = null
     where id = i.piece_id and statut is distinct from 'lue';
    perform private.jeu_vu(j.id, i.recu_le);
    perform private.avancer_jeu(j.id, private.limite_requete());
  else
    delete from public.instantanes_lignes where instantane_id = i.id;
    v_motif := coalesce(v_motif, case v_statut when 'a_classer' then 'Aucun jeu de ce branchement ne reconnaît ce fichier.'
                                               when 'rejete' then 'Format non pris en charge.'
                                               else 'Fichier illisible.' end);
    update public.instantanes
       set statut = v_statut, colonnes = p_resultat -> 'colonnes', format = p_resultat -> 'format', motif = v_motif,
           version_releve = left(p_version, 40), lu_le = now(), finalise_le = now()
     where id = i.id;
    update public.pieces
       set statut = case v_statut when 'a_classer' then 'a_classer' when 'rejete' then 'rejetee' else 'echec' end,
           motif = v_motif, lue_le = now(), version_lecteur = left(p_version, 40)
     where id = i.piece_id;
    perform private.lever_alerte_module(b.client_id, b.module, 'attention',
      left(case v_statut when 'a_classer' then format('Export non reconnu (%s) : %s', b.libelle, i.nom_fichier)
                         else format('Export illisible (%s) : %s', b.libelle, i.nom_fichier) end, 200),
      jsonb_build_object('instantane', i.id, 'branchement', b.id, 'statut', v_statut, 'motif', left(v_motif, 300)),
      case v_statut when 'a_classer' then 'releve.a_classer.' else 'releve.illisible.' end || b.id::text, false, null);
  end if;
  perform private.publier_releve(v_releve);
  if v_releve <> i.releve_id then
    perform private.publier_releve(i.releve_id);
  end if;
  return (select jsonb_build_object('instantane', x.id, 'statut', x.statut,
                                    'jeu', (select y.code from public.branchements_jeux y where y.id = x.jeu_id),
                                    'lignes', x.lignes, 'ajouts', x.ajouts, 'modifications', x.modifications,
                                    'disparitions', x.disparitions, 'garde', x.garde)
          from public.instantanes x where x.id = i.id);
end $$;


--
-- Name: territoire_de_entite(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.territoire_de_entite(p_client uuid, p_entite uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive chaine (id, parent_id, territoire, rang) as (
    select e.id, e.parent_id, e.territoire, 0
    from public.entites e where e.client_id = p_client and e.id = p_entite
    union all
    select p.id, p.parent_id, p.territoire, c.rang + 1
    from chaine c join public.entites p on p.client_id = p_client and p.id = c.parent_id
    where c.territoire is null and c.rang < 32
  )
  select public.territoire_calendrier(c.territoire) from chaine c
  where c.territoire is not null
  order by c.rang limit 1
$$;


--
-- Name: territoire_du_fuseau(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.territoire_du_fuseau(p_fuseau text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select min(t.code) from public.territoires t where t.fuseau = p_fuseau having count(*) = 1
$$;


--
-- Name: tiroma_accorder_droits(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_accorder_droits(p_client uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.droits d
  where d.client_id = p_client and d.user_id = p_user
    and d.droit in ('tiroma.voir_sa_production', 'tiroma.voir_charge', 'tiroma.voir_production');
  delete from public.acces_objets a
  where a.client_id = p_client and a.user_id = p_user and a.objet_type = 'praticien';

  if not exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client) then
    return;
  end if;

  if exists (select 1 from public.tiroma_profils p
             where p.client_id = p_client and p.user_id = p_user and p.praticien_id is not null) then
    insert into public.objets_restreints (client_id, objet_type) values (p_client, 'praticien')
    on conflict (client_id, objet_type) do nothing;
    insert into public.droits (client_id, droit, user_id) values (p_client, 'tiroma.voir_sa_production', p_user)
    on conflict do nothing;
    insert into public.acces_objets (client_id, objet_type, objet_id, user_id, niveau)
    select distinct p_client, 'praticien', p.praticien_id::text, p_user, 'lecture'
    from public.tiroma_profils p
    where p.client_id = p_client and p.user_id = p_user and p.praticien_id is not null
    on conflict do nothing;
  end if;

  if exists (select 1 from public.tiroma_profils p
             where p.client_id = p_client and p.user_id = p_user and p.profil = 'direction') then
    insert into public.droits (client_id, droit, user_id)
    values (p_client, 'tiroma.voir_charge', p_user), (p_client, 'tiroma.voir_production', p_user)
    on conflict do nothing;
  end if;
end $$;


--
-- Name: tiroma_bornes_jour(date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_bornes_jour(p_jour date, p_fuseau text) RETURNS tstzrange
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select tstzrange(p_jour::timestamp at time zone p_fuseau, (p_jour + 1)::timestamp at time zone p_fuseau, '[)')
$$;


--
-- Name: tiroma_cabinets_ou(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_cabinets_ou(p_profils text[]) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.entite_id from private.tiroma_mes_cabinets() m where m.profil = any (p_profils)
$$;


--
-- Name: tiroma_cabinets_patients(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_cabinets_patients() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.entite_id from private.tiroma_mes_cabinets() m
  where m.profil in ('titulaire', 'assistante')
     or (m.profil = 'collaborateur' and m.perimetre = 'cabinet')
     or (m.profil = 'direction' and private.tiroma_droit_expres(m.client_id, 'tiroma.fiches_patients'))
$$;


--
-- Name: tiroma_cabinets_production(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_cabinets_production() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.entite_id from private.tiroma_mes_cabinets() m where m.profil = 'titulaire'
$$;


--
-- Name: tiroma_changer_mode(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_changer_mode(p_client uuid, p_entite uuid, p_mode text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_avant text; v_id uuid;
begin
  if p_mode is null or p_mode not in ('a_blanc', 'reel') then
    raise exception 'Le mode vaut a_blanc ou reel.' using errcode = '22023';
  end if;
  select k.mode, k.id into v_avant, v_id from public.tiroma_cabinets k
  where k.client_id = p_client and k.entite_id = p_entite for update;
  if not found then
    raise exception 'Cabinet introuvable.' using errcode = 'P0002';
  end if;
  if v_avant = p_mode then
    return;
  end if;
  update public.tiroma_cabinets set mode = p_mode, mode_depuis = now() where id = v_id;
end $$;


--
-- Name: tiroma_droit_expres(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_droit_expres(p_client uuid, p_droit text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.droits d
    where d.client_id = p_client and d.droit = p_droit
      and (d.user_id = (select auth.uid())
           or d.equipe_id in (select m.equipe_id from public.equipes_membres m
                              where m.user_id = (select auth.uid()) and m.client_id = p_client)))
$$;


--
-- Name: tiroma_empreinte_ref(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_empreinte_ref(p_client uuid, p_entite uuid, p_source_ref text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select encode(sha256(convert_to(p_client::text || '/' || p_entite::text || '/' || p_source_ref, 'UTF8')), 'hex')
$$;


--
-- Name: tiroma_enregistrer_mesures(uuid, uuid, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_enregistrer_mesures(p_client uuid, p_entite uuid, p_passage text, p_jour date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_mode text;
  r record;
  n integer := 0;
begin
  select k.mode into v_mode from public.tiroma_cabinets k where k.client_id = p_client and k.entite_id = p_entite;
  if v_mode is null then
    raise exception 'Cabinet introuvable.' using errcode = 'P0002';
  end if;
  for r in select * from private.tiroma_mesures(p_client, p_entite, p_passage, p_jour) loop
    perform public.enregistrer_mesure(
      p_client => p_client, p_indicateur => r.indicateur, p_version => r.version,
      p_periode_type => 'jour', p_periode_debut => r.jour,
      p_valeur => r.valeur, p_base => r.base, p_mode => v_mode, p_numerateur => r.numerateur,
      p_entite => p_entite, p_objet_type => r.objet_type, p_objet_id => r.objet_id, p_objet_libelle => r.objet_libelle);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: tiroma_est_titulaire(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_est_titulaire(p_client uuid, p_entite uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from private.tiroma_mes_cabinets() m
    where m.client_id = p_client and m.entite_id = p_entite and m.profil = 'titulaire')
$$;


--
-- Name: tiroma_evenements_immuables(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_evenements_immuables() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and (
       old.client_id::text = coalesce(current_setting('omega.effacement_client', true), '')
       or coalesce(current_setting('omega.effacement_objet', true), '') = 'oui'
       or coalesce(current_setting('omega.tiroma_moteur', true), '') = 'purge') then
    return old;
  end if;
  raise exception 'Les événements d''agenda ne se modifient pas et ne s''effacent pas.' using errcode = '42501';
end $$;


--
-- Name: tiroma_evenements_sans_vidage(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_evenements_sans_vidage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'Les événements d''agenda ne se vident pas.' using errcode = '42501';
end $$;


--
-- Name: tiroma_fermer_alerte(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_fermer_alerte(p_client uuid, p_cle text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.alertes
     set acquittee_le = now(), detail = detail || jsonb_build_object('resolution', 'la mesure est passée')
   where client_id = p_client and cle_regroupement = p_cle and acquittee_le is null
$$;


--
-- Name: tiroma_horloge(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_horloge(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  k record;
  v_local timestamp;
  v_jour date;
  d date;
  n integer;
  v_bilan jsonb := '{}'::jsonb;
begin
  for k in
    select c.id as cabinet_id, c.client_id, c.entite_id, e.fuseau
    from public.tiroma_cabinets c
    join public.entites e on e.client_id = c.client_id and e.id = c.entite_id
    where c.statut = 'actif'
    order by c.client_id, c.entite_id
  loop
    v_local := p_maintenant at time zone k.fuseau;
    v_jour := v_local::date;

    -- Le soir : la journée écoulée, et les deux précédentes si elles ont manqué.
    for d in select generate_series(v_jour - 2, v_jour, interval '1 day')::date loop
      continue when d = v_jour and v_local::time < time '23:30';
      continue when exists (select 1 from private.tiroma_passages p
                            where p.client_id = k.client_id and p.entite_id = k.entite_id
                              and p.tache = 'mesure_soir' and p.jour = d);
      begin
        n := private.tiroma_enregistrer_mesures(k.client_id, k.entite_id, 'soir', d);
        insert into private.tiroma_passages (client_id, entite_id, tache, jour, bilan)
        values (k.client_id, k.entite_id, 'mesure_soir', d, jsonb_build_object('mesures', n));
        perform private.journaliser_module(k.client_id, 'tiroma', 'tiroma.indicateurs_calcules', 'tiroma_cabinets',
          k.cabinet_id::text, jsonb_build_object('passage', 'soir', 'jour', d, 'version', 1, 'mesures', n), k.entite_id);
        perform private.battre(k.client_id, 'tiroma_mesure',
          jsonb_build_object('passage', 'soir', 'jour', d, 'mesures', n), interval '1 day');
        perform private.tiroma_fermer_alerte(k.client_id, 'tiroma:mesure:' || k.cabinet_id || ':soir');
        v_bilan := v_bilan || jsonb_build_object(k.cabinet_id::text || ':soir:' || d, n);
      exception when others then
        perform private.lever_alerte_module(k.client_id, 'tiroma', 'critique',
          'La mesure de Tiroma n''a pas pu se faire',
          jsonb_build_object('cabinet', k.cabinet_id, 'passage', 'soir', 'jour', d, 'erreur', left(sqlerrm, 200)),
          'mesure:' || k.cabinet_id || ':soir', false, null);
      end;
    end loop;

    -- Le matin : les chiffres prévus du jour.
    if v_local::time >= time '06:40' and not exists (
         select 1 from private.tiroma_passages p
         where p.client_id = k.client_id and p.entite_id = k.entite_id and p.tache = 'mesure_matin' and p.jour = v_jour) then
      begin
        n := private.tiroma_enregistrer_mesures(k.client_id, k.entite_id, 'matin', v_jour);
        insert into private.tiroma_passages (client_id, entite_id, tache, jour, bilan)
        values (k.client_id, k.entite_id, 'mesure_matin', v_jour, jsonb_build_object('mesures', n));
        perform private.journaliser_module(k.client_id, 'tiroma', 'tiroma.indicateurs_calcules', 'tiroma_cabinets',
          k.cabinet_id::text, jsonb_build_object('passage', 'matin', 'jour', v_jour, 'version', 1, 'mesures', n), k.entite_id);
        perform private.tiroma_fermer_alerte(k.client_id, 'tiroma:mesure:' || k.cabinet_id || ':matin');
        v_bilan := v_bilan || jsonb_build_object(k.cabinet_id::text || ':matin:' || v_jour, n);
      exception when others then
        perform private.lever_alerte_module(k.client_id, 'tiroma', 'critique',
          'La mesure de Tiroma n''a pas pu se faire',
          jsonb_build_object('cabinet', k.cabinet_id, 'passage', 'matin', 'jour', v_jour, 'erreur', left(sqlerrm, 200)),
          'mesure:' || k.cabinet_id || ':matin', false, null);
      end;
    end if;
  end loop;
  return v_bilan;
end $$;


--
-- Name: tiroma_installer_cabinet(uuid, uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_installer_cabinet(p_client uuid, p_entite uuid, p_logiciel text, p_perimetre text DEFAULT 'cabinet'::text, p_logiciel_version text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_fuseau text;
  v_territoire text;
  v_fuseau_territoire text;
  v_complet boolean;
begin
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = p_entite;
  if not found then
    raise exception 'Entité introuvable dans cette organisation.' using errcode = 'P0002';
  end if;
  v_territoire := private.territoire_de_entite(p_client, p_entite);
  if v_territoire is null then
    raise exception 'Le territoire du cabinet est inconnu : renseignez le code ISO de son entité (GP, FR-971, FR…).'
      using errcode = '22023', hint = 'Tiroma ne suppose jamais la métropole : les jours ouvrés en dépendent.';
  end if;
  select t.fuseau, t.complet into v_fuseau_territoire, v_complet from public.territoires t where t.code = v_territoire;
  if not coalesce(v_complet, false) then
    raise exception 'Les jours fériés de droit local de % ne sont pas au calendrier : Tiroma n''y calcule aucun jour ouvré.', v_territoire
      using errcode = '22023', hint = 'Relever d''abord ces jours dans le texte local (brique B5).';
  end if;
  if v_fuseau is distinct from v_fuseau_territoire then
    raise exception 'Le fuseau de l''entité (%) ne correspond pas à son territoire (%, %).', v_fuseau, v_territoire, v_fuseau_territoire
      using errcode = '22023', hint = '7 h à Pointe-à-Pitre n''est pas 7 h à Paris : le point du matin en dépend.';
  end if;
  insert into public.tiroma_cabinets (client_id, entite_id, logiciel, logiciel_version, perimetre_partage)
  values (p_client, p_entite, p_logiciel, p_logiciel_version, p_perimetre)
  returning id into v_id;
  insert into public.tiroma_regles (client_id, entite_id) values (p_client, p_entite);
  return v_id;
end $$;


--
-- Name: tiroma_maj_le(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_maj_le() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.maj_le := now();
  return new;
end $$;


--
-- Name: tiroma_mes_cabinets(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mes_cabinets() RETURNS TABLE(client_id uuid, entite_id uuid, profil text, praticien_id uuid, membre_id uuid, perimetre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive
  profils as (
    select p.client_id, p.entite_id, p.profil, p.praticien_id, p.membre_id
    from public.tiroma_profils p
    join public.comptes c on c.user_id = p.user_id and c.client_id = p.client_id
    where p.user_id = (select auth.uid())
      and (c.perimetre_total or exists (
        select 1 from public.comptes_entites ce
        where ce.user_id = c.user_id and ce.client_id = c.client_id and ce.entite_id = p.entite_id))
  ),
  sous_directions as (
    select d.client_id, d.entite_id, 0 as profondeur
    from profils d where d.profil = 'direction'
    union
    select s.client_id, e.id, s.profondeur + 1
    from sous_directions s
    join public.entites e on e.client_id = s.client_id and e.parent_id = s.entite_id
    where s.profondeur < 20
  )
  select p.client_id, p.entite_id, p.profil, p.praticien_id, p.membre_id, k.perimetre_partage
  from profils p
  join public.tiroma_cabinets k on k.client_id = p.client_id and k.entite_id = p.entite_id
  where p.profil <> 'direction'
  union
  select s.client_id, s.entite_id, 'direction', null::uuid, null::uuid, k.perimetre_partage
  from sous_directions s
  join public.tiroma_cabinets k on k.client_id = s.client_id and k.entite_id = s.entite_id
  where not exists (select 1 from profils p where p.entite_id = s.entite_id and p.profil <> 'direction')
$$;


--
-- Name: tiroma_mesure_acceptation(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_acceptation(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'tiroma.taux_acceptation_devis', null::text, null::text, null::text,
         count(*) filter (where p.signe_le is not null and p.signe_le <= p.presente_le + 60)::numeric,
         count(*)::numeric,
         round(count(*) filter (where p.signe_le is not null and p.signe_le <= p.presente_le + 60)::numeric / count(*), 6)
  from public.tiroma_plans p
  where p.client_id = p_client and p.entite_id = p_entite and p.type <> 'odf' and p.presente_le = p_jour
  having count(*) > 0
  union all
  select 'tiroma.taux_acceptation_devis_100_sante', null, null, null,
         count(*) filter (where p.signe_le is not null and p.signe_le <= p.presente_le + 60)::numeric,
         count(*)::numeric,
         round(count(*) filter (where p.signe_le is not null and p.signe_le <= p.presente_le + 60)::numeric / count(*), 6)
  from public.tiroma_plans p
  where p.client_id = p_client and p.entite_id = p_entite and p.type <> 'odf' and p.presente_le = p_jour
    and (p.panier = '100_sante' or coalesce(p.alternative_100_sante, false))
  having count(*) > 0
$$;


--
-- Name: tiroma_mesure_controles(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_controles(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with cab as (
    select e.fuseau, g.patient_actif_mois, g.actes_controle
    from public.entites e
    join public.tiroma_regles g on g.client_id = e.client_id and g.entite_id = e.id
    where e.client_id = p_client and e.id = p_entite
  ),
  actifs as (
    select p.id from public.tiroma_patients p, cab
    where p.client_id = p_client and p.entite_id = p_entite and p.actif and p.fusionne_dans_id is null
      and coalesce(greatest(p.dernier_rdv_le, p.dernier_acte_le), (p.vu_premier_le at time zone cab.fuseau)::date)
          >= (p_jour - make_interval(months => cab.patient_actif_mois))::date
  ),
  derniers as (
    select a.id, greatest(
             (select max(x.date) from public.tiroma_actes_realises x, cab
              where x.patient_id = a.id and x.date <= p_jour and x.code = any (cab.actes_controle)),
             (select max((r.debut at time zone cab.fuseau)::date)
              from public.tiroma_rendez_vous r
              join public.tiroma_types_rdv t on t.id = r.type_rdv_id, cab
              where r.patient_id = a.id and t.famille in ('controle', 'detartrage')
                and (r.statut = 'honore' or (r.statut = 'prevu' and r.presume = 'honore'))
                and (r.debut at time zone cab.fuseau)::date <= p_jour)) as dernier
    from actifs a
  )
  select 'tiroma.patients_sans_controle_18m', null::text, null::text, null::text, null::numeric,
         count(*)::numeric,
         count(*) filter (where dernier is null or dernier < (p_jour - interval '18 months')::date)::numeric
  from derniers
  having count(*) > 0
$$;


--
-- Name: tiroma_mesure_laboratoire(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_laboratoire(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with revenus as (
    select lower(btrim(w.laboratoire)) as cle, min(w.laboratoire) over (partition by lower(btrim(w.laboratoire))) as nom,
           (w.revenu_le - w.envoye_le)::numeric as jours
    from public.tiroma_travaux_labo w
    where w.client_id = p_client and w.entite_id = p_entite and w.revenu_le = p_jour
      and w.envoye_le is not null and w.revenu_le >= w.envoye_le
  )
  select 'tiroma.delai_laboratoire', null::text, null::text, null::text,
         sum(jours), count(*)::numeric, round(sum(jours) / count(*), 6)
  from revenus having count(*) > 0
  union all
  select 'tiroma.delai_laboratoire', 'laboratoire', cle, min(nom), sum(jours), count(*), round(sum(jours) / count(*), 6)
  from revenus where cle is not null
  group by cle
$$;


--
-- Name: tiroma_mesure_occupation(uuid, uuid, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_occupation(p_client uuid, p_entite uuid, p_jour date, p_genre text) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  f record;
  v_ouvert tstzmultirange;
  v_occ numeric;
  v_ouv numeric;
  v_tot_occ numeric := 0;
  v_tot_ouv numeric := 0;
begin
  for f in
    select k.id, k.nom from public.tiroma_fauteuils k
    where k.client_id = p_client and k.entite_id = p_entite and k.actif
    order by k.nom, k.id
  loop
    v_ouvert := private.tiroma_ouvert(p_client, p_entite, f.id, p_jour);
    continue when v_ouvert is null;
    v_ouv := private.tiroma_minutes(v_ouvert);
    continue when v_ouv = 0;
    v_occ := private.tiroma_minutes(private.tiroma_reserve(p_client, p_entite, f.id, p_jour, p_genre) * v_ouvert);
    v_tot_occ := v_tot_occ + v_occ;
    v_tot_ouv := v_tot_ouv + v_ouv;
    indicateur := 'tiroma.occupation_' || p_genre; objet_type := 'fauteuil'; objet_id := f.id::text; objet_libelle := f.nom;
    numerateur := v_occ; base := v_ouv; valeur := round(v_occ / v_ouv, 6);
    return next;
  end loop;
  if v_tot_ouv > 0 then
    indicateur := 'tiroma.occupation_' || p_genre; objet_type := null; objet_id := null; objet_libelle := null;
    numerateur := v_tot_occ; base := v_tot_ouv; valeur := round(v_tot_occ / v_tot_ouv, 6);
    return next;
  end if;
end $$;


--
-- Name: tiroma_mesure_production_prevue(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_production_prevue(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with cab as (select e.fuseau from public.entites e where e.client_id = p_client and e.id = p_entite),
  rdv as (
    select r.id, r.type_rdv_id, r.praticien_id
    from public.tiroma_rendez_vous r, cab
    where r.client_id = p_client and r.entite_id = p_entite
      and r.statut in ('prevu', 'honore')
      and (r.debut at time zone cab.fuseau)::date = p_jour
  ),
  lus as (
    select r.id, r.praticien_id, sum(pa.montant) as montant
    from rdv r join public.tiroma_plan_actes pa on pa.rendez_vous_id = r.id and pa.montant is not null
    group by r.id, r.praticien_id
  ),
  historique as (
    select h.type_rdv_id, sum(a.montant) as montant
    from public.tiroma_rendez_vous h
    join public.tiroma_actes_realises a on a.rendez_vous_id = h.id and a.montant is not null, cab
    where h.client_id = p_client and h.entite_id = p_entite and h.type_rdv_id is not null
      and h.statut = 'honore'
      and (h.debut at time zone cab.fuseau)::date between p_jour - 180 and p_jour - 1
    group by h.id, h.type_rdv_id
  ),
  medianes as (
    select type_rdv_id, percentile_cont(0.5) within group (order by montant)::numeric as mediane
    from historique group by type_rdv_id
  ),
  estimes as (
    select r.id, round(m.mediane, 2) as montant
    from rdv r join medianes m on m.type_rdv_id = r.type_rdv_id
    where not exists (select 1 from lus l where l.id = r.id)
  )
  select 'tiroma.production_prevue', null::text, null::text, null::text, null::numeric, count(*)::numeric, sum(montant)
  from lus having count(*) > 0
  union all
  select 'tiroma.production_prevue_estimee', null, null, null, null, count(*), sum(montant)
  from estimes having count(*) > 0
  union all
  select 'tiroma.production_prevue_praticien', 'praticien', l.praticien_id::text, p.nom_affiche, null, count(*), sum(l.montant)
  from lus l join public.tiroma_praticiens p on p.id = l.praticien_id
  group by l.praticien_id, p.nom_affiche
$$;


--
-- Name: tiroma_mesure_production_realisee(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_production_realisee(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with actes as (
    select a.montant, a.praticien_id, r.fauteuil_id
    from public.tiroma_actes_realises a
    left join public.tiroma_rendez_vous r on r.id = a.rendez_vous_id
    where a.client_id = p_client and a.entite_id = p_entite and a.date = p_jour and a.montant is not null
  )
  select 'tiroma.production_realisee', null::text, null::text, null::text,
         null::numeric, count(*)::numeric, sum(montant)
  from actes having count(*) > 0
  union all
  select 'tiroma.production_realisee', 'fauteuil', a.fauteuil_id::text, k.nom, null, count(*), sum(a.montant)
  from actes a join public.tiroma_fauteuils k on k.id = a.fauteuil_id
  group by a.fauteuil_id, k.nom
  union all
  select 'tiroma.production_realisee_praticien', 'praticien', a.praticien_id::text, p.nom_affiche, null, count(*), sum(a.montant)
  from actes a join public.tiroma_praticiens p on p.id = a.praticien_id
  group by a.praticien_id, p.nom_affiche
$$;


--
-- Name: tiroma_mesure_reinscription(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_reinscription(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with cab as (select e.fuseau from public.entites e where e.client_id = p_client and e.id = p_entite),
  vus as (
    select r.patient_id, max(r.fin) as fin_visite
    from public.tiroma_rendez_vous r, cab
    where r.client_id = p_client and r.entite_id = p_entite and r.patient_id is not null
      and (r.statut = 'honore' or (r.statut = 'prevu' and r.presume = 'honore'))
      and (r.debut at time zone cab.fuseau)::date = p_jour
    group by r.patient_id
  ),
  juges as (
    select v.patient_id, exists (
             select 1 from public.tiroma_rendez_vous s
             where s.client_id = p_client and s.entite_id = p_entite and s.patient_id = v.patient_id
               and s.debut > v.fin_visite and s.statut <> 'supprime'
               and coalesce(s.cree_source_le, s.vu_premier_le) <= v.fin_visite + interval '24 hours'
           ) as reinscrit
    from vus v
  )
  select 'tiroma.taux_reinscription', null::text, null::text, null::text,
         count(*) filter (where reinscrit)::numeric, count(*)::numeric,
         round(count(*) filter (where reinscrit)::numeric / count(*), 6)
  from juges
  having count(*) > 0
$$;


--
-- Name: tiroma_mesure_reprise(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesure_reprise(p_client uuid, p_entite uuid, p_jour date) RETURNS TABLE(indicateur text, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with cab as (
    select e.fuseau, g.creneau_min_minutes
    from public.entites e
    join public.tiroma_regles g on g.client_id = e.client_id and g.entite_id = e.id
    where e.client_id = p_client and e.id = p_entite
  ),
  liberes as (
    select distinct on (ev.rendez_vous_id, ev.avant ->> 'debut')
           ev.rendez_vous_id, ev.detecte_le,
           tstzrange((ev.avant ->> 'debut')::timestamptz, (ev.avant ->> 'fin')::timestamptz) as creneau,
           nullif(ev.avant ->> 'fauteuil_id', '')::uuid as fauteuil_id,
           nullif(ev.avant ->> 'praticien_id', '')::uuid as praticien_id
    from public.tiroma_evenements_agenda ev, cab
    where ev.client_id = p_client and ev.entite_id = p_entite
      and ev.type in ('annulation', 'report', 'deplacement')
      and ev.avant ? 'debut' and ev.avant ? 'fin'
      and ((ev.avant ->> 'debut')::timestamptz at time zone cab.fuseau)::date = p_jour
      and (ev.avant ->> 'debut')::timestamptz > ev.detecte_le
      and (ev.avant ->> 'debut')::timestamptz - ev.detecte_le <= interval '48 hours'
    order by ev.rendez_vous_id, ev.avant ->> 'debut', ev.detecte_le
  ),
  juges as (
    select l.fauteuil_id,
           exists (
             select 1 from public.tiroma_rendez_vous r, cab
             where r.client_id = p_client and r.entite_id = p_entite
               and r.id is distinct from l.rendez_vous_id
               and r.statut in ('prevu', 'honore', 'manque')
               and case when l.fauteuil_id is not null then r.fauteuil_id = l.fauteuil_id
                        else r.praticien_id = l.praticien_id end
               and r.vu_premier_le >= l.detecte_le
               and private.tiroma_minutes(tstzmultirange(tstzrange(r.debut, r.fin) * l.creneau))
                   >= least(private.tiroma_minutes(tstzmultirange(l.creneau)), cab.creneau_min_minutes)
           ) as repris
    from liberes l
  )
  select 'tiroma.taux_reprise_48h', 'fauteuil', j.fauteuil_id::text, k.nom,
         count(*) filter (where j.repris)::numeric, count(*)::numeric,
         round(count(*) filter (where j.repris)::numeric / count(*), 6)
  from juges j
  join public.tiroma_fauteuils k on k.id = j.fauteuil_id
  where j.fauteuil_id is not null
  group by j.fauteuil_id, k.nom
  union all
  select 'tiroma.taux_reprise_48h', null, null, null,
         count(*) filter (where j.repris)::numeric, count(*)::numeric,
         round(count(*) filter (where j.repris)::numeric / count(*), 6)
  from juges j
  having count(*) > 0
$$;


--
-- Name: tiroma_mesures(uuid, uuid, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_mesures(p_client uuid, p_entite uuid, p_passage text, p_jour date) RETURNS TABLE(jour date, indicateur text, version integer, objet_type text, objet_id text, objet_libelle text, numerateur numeric, base numeric, valeur numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  d date;
begin
  if p_passage = 'soir' then
    return query select p_jour, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_occupation(p_client, p_entite, p_jour, 'realisee') m;
    return query select p_jour, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_reprise(p_client, p_entite, p_jour) m;
    return query select p_jour, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_production_realisee(p_client, p_entite, p_jour) m;
    return query select p_jour, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_laboratoire(p_client, p_entite, p_jour) m;
    return query select p_jour, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_controles(p_client, p_entite, p_jour) m;
    return query select p_jour - 1, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_reinscription(p_client, p_entite, p_jour - 1) m;
    for d in select generate_series(p_jour - 60, p_jour, interval '1 day')::date loop
      return query select d, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                   from private.tiroma_mesure_acceptation(p_client, p_entite, d) m;
    end loop;
  elsif p_passage = 'matin' then
    for d in select generate_series(p_jour, p_jour + 1, interval '1 day')::date loop
      return query select d, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                   from private.tiroma_mesure_occupation(p_client, p_entite, d, 'prevue') m;
    end loop;
    return query select p_jour, m.indicateur, 1, m.objet_type, m.objet_id, m.objet_libelle, m.numerateur, m.base, m.valeur
                 from private.tiroma_mesure_production_prevue(p_client, p_entite, p_jour) m;
  else
    raise exception 'Passage inconnu : %.', coalesce(p_passage, 'vide') using errcode = '22023';
  end if;
end $$;


--
-- Name: tiroma_minutes(tstzmultirange); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_minutes(p tstzmultirange) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(sum(extract(epoch from (upper(r) - lower(r))) / 60.0), 0)::numeric
  from unnest(coalesce(p, '{}'::tstzmultirange)) as r
$$;


--
-- Name: tiroma_ouvert(uuid, uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_ouvert(p_client uuid, p_entite uuid, p_fauteuil uuid, p_jour date) RETURNS tstzmultirange
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fuseau text;
  v_territoire text;
  v_complet boolean;
  v_propres boolean;
  v_tenus boolean;
  v_exception boolean;
  v_jour tstzrange;
  v_ouvert tstzmultirange;
  v_ferme tstzmultirange;
begin
  select e.fuseau into v_fuseau from public.entites e where e.client_id = p_client and e.id = p_entite;
  if v_fuseau is null then
    return null;
  end if;
  v_jour := private.tiroma_bornes_jour(p_jour, v_fuseau);
  v_propres := exists (select 1 from public.tiroma_horaires h
                       where h.client_id = p_client and h.entite_id = p_entite and h.fauteuil_id = p_fauteuil);
  v_tenus := v_propres or exists (select 1 from public.tiroma_horaires h
                                  where h.client_id = p_client and h.entite_id = p_entite
                                    and h.fauteuil_id is null and h.praticien_id is null);
  if not v_tenus then
    return null;
  end if;

  v_exception := exists (
    select 1 from public.tiroma_horaires h
    where h.client_id = p_client and h.entite_id = p_entite and h.exceptionnel and h.valide_du = p_jour
      and (case when v_propres then h.fauteuil_id = p_fauteuil
                else h.fauteuil_id is null and h.praticien_id is null end));

  if not v_exception then
    v_territoire := private.territoire_de_entite(p_client, p_entite);
    select t.complet into v_complet from public.territoires t where t.code = v_territoire;
    if not coalesce(v_complet, false) then
      return null;  -- jours fériés inconnus : on ne sait pas si le cabinet ouvre
    end if;
    if public.jour_ferie(p_jour, v_territoire) then
      return '{}'::tstzmultirange;
    end if;
  end if;

  with lignes as (
    select h.* from public.tiroma_horaires h
    where h.client_id = p_client and h.entite_id = p_entite
      and (case when v_propres then h.fauteuil_id = p_fauteuil
                else h.fauteuil_id is null and h.praticien_id is null end)
      and (case when v_exception then h.exceptionnel and h.valide_du = p_jour
                else not h.exceptionnel and h.jour = extract(isodow from p_jour)
                     and (h.valide_du is null or h.valide_du <= p_jour)
                     and (h.valide_au is null or h.valide_au >= p_jour) end)
  )
  select range_agg(
           tstzmultirange(tstzrange((p_jour + l.debut) at time zone v_fuseau, (p_jour + l.fin) at time zone v_fuseau))
           - coalesce((select range_agg(tstzrange(f.debut, f.fin))
                       from public.tiroma_fermetures f
                       where l.praticien_id is not null
                         and f.client_id = p_client and f.entite_id = p_entite
                         and f.praticien_id = l.praticien_id
                         and tstzrange(f.debut, f.fin) && v_jour), '{}'::tstzmultirange))
  into v_ouvert
  from lignes l;

  select range_agg(tstzrange(f.debut, f.fin)) into v_ferme
  from public.tiroma_fermetures f
  where f.client_id = p_client and f.entite_id = p_entite and f.praticien_id is null
    and (f.fauteuil_id is null or f.fauteuil_id = p_fauteuil)
    and tstzrange(f.debut, f.fin) && v_jour;

  return (coalesce(v_ouvert, '{}'::tstzmultirange) - coalesce(v_ferme, '{}'::tstzmultirange))
         * tstzmultirange(v_jour);
end $$;


--
-- Name: tiroma_patient_efface(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_patient_efface() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.tiroma_effaces (client_id, entite_id, empreinte_ref)
  values (old.client_id, old.entite_id, private.tiroma_empreinte_ref(old.client_id, old.entite_id, old.source_ref))
  on conflict (client_id, entite_id, empreinte_ref) do nothing;
  return null;
end $$;


--
-- Name: tiroma_praticiens_patients(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_praticiens_patients() RETURNS TABLE(entite_id uuid, praticien_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.entite_id, coalesce(m.praticien_id, '00000000-0000-0000-0000-000000000000'::uuid)
  from private.tiroma_mes_cabinets() m
  where m.profil = 'collaborateur' and m.perimetre = 'praticien'
$$;


--
-- Name: tiroma_praticiens_production(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_praticiens_production() RETURNS TABLE(entite_id uuid, praticien_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.entite_id, coalesce(m.praticien_id, '00000000-0000-0000-0000-000000000000'::uuid)
  from private.tiroma_mes_cabinets() m
  where m.profil = 'collaborateur'
$$;


--
-- Name: tiroma_profil_coherent(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_profil_coherent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_role text;
begin
  select c.role into v_role from public.comptes c where c.user_id = new.user_id and c.client_id = new.client_id;
  if v_role is null then
    raise exception 'La personne n''est pas membre de l''organisation.' using errcode = '23503';
  end if;
  if new.profil = 'titulaire' and v_role <> 'gerant' then
    raise exception 'Un titulaire est gérant de l''organisation.' using errcode = '22023';
  end if;
  if new.profil = 'direction' and v_role not in ('gerant', 'admin') then
    raise exception 'Une direction est gérante ou administratrice de l''organisation.' using errcode = '22023';
  end if;
  if new.profil <> 'direction' and not exists (
       select 1 from public.tiroma_cabinets k where k.client_id = new.client_id and k.entite_id = new.entite_id) then
    raise exception 'Ce profil se pose sur un cabinet installé.' using errcode = '22023';
  end if;
  if new.praticien_id is not null and new.profil not in ('titulaire', 'collaborateur') then
    raise exception 'Seul un dentiste est relié à un praticien.' using errcode = '22023';
  end if;
  if new.membre_id is not null and new.profil <> 'assistante' then
    raise exception 'Seule une assistante est reliée à un membre de l''équipe.' using errcode = '22023';
  end if;
  new.maj_le := now();
  return new;
end $$;


--
-- Name: tiroma_profils_droits(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_profils_droits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Pendant l'effacement de l'organisation, rien ne se recrée.
  if coalesce(new.client_id, old.client_id)::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return null;
  end if;
  if tg_op in ('UPDATE', 'DELETE') then
    perform private.tiroma_accorder_droits(old.client_id, old.user_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform private.tiroma_accorder_droits(new.client_id, new.user_id);
  end if;
  return null;
end $$;


--
-- Name: tiroma_purger(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_purger(p_maintenant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_bilan jsonb := '{}'::jsonb;
  v_duree interval;
  t record;
  r record;
begin
  perform set_config('omega.tiroma_moteur', 'purge', true);

  for t in
    select v.nom, v.condition from (values
      (1, 'tiroma_evenements_agenda', 'x.detecte_le < $1 - $2'),
      (2, 'tiroma_liste_attente', 'x.retire_le < $1 - $2'),
      (3, 'tiroma_actes_realises', 'x.date < ($1 - $2)::date'),
      (4, 'tiroma_travaux_labo',
          'coalesce(x.revenu_le, x.retour_attendu_le, x.envoye_le, x.cree_le::date) < ($1 - $2)::date'),
      (5, 'tiroma_ententes_odf',
          '((x.statut in (''terminee'', ''abandonnee'', ''refusee'') and coalesce(x.fin_le, x.maj_le::date) < ($1 - $2)::date)'
          ' or (x.statut in (''demandee'', ''accordee'') and coalesce(x.accord_le, x.demande_le, x.maj_le::date) < ($1 - $2)::date))'),
      (6, 'tiroma_rendez_vous', 'x.fin < $1 - $2'),
      (7, 'tiroma_plans',
          '((x.statut in (''termine'', ''abandonne'', ''expire'', ''refuse'') and coalesce(x.clos_le, x.vu_dernier_le) < $1 - $2)'
          ' or (x.statut = ''presente'' and coalesce(x.presente_le, x.vu_premier_le::date) < ($1 - $2)::date))'),
      (8, 'tiroma_releves', 'x.recu_le < $1 - $2')) as v(rang, nom, condition)
    order by v.rang
  loop
    select c.duree into v_duree from private.tiroma_conservation c where c.nom = t.nom;
    continue when v_duree is null;
    for r in execute format(
      'with d as (delete from public.%I x where %s returning x.client_id, x.id::text as id) '
      'select d.client_id, count(*) as n, jsonb_agg(d.id order by d.id) as ids from d group by d.client_id',
      t.nom, t.condition)
      using p_maintenant, v_duree
    loop
      v_bilan := jsonb_set(v_bilan, array[r.client_id::text],
        coalesce(v_bilan -> r.client_id::text, '{}'::jsonb) || jsonb_build_object(t.nom, jsonb_build_object('n', r.n, 'ids', r.ids)));
    end loop;
  end loop;

  -- Les patients qui ne viennent plus : ni venue ni acte depuis la durée du
  -- cabinet, rien d'ouvert (rendez-vous à venir, attente, plan).
  for r in
    with d as (
      delete from public.tiroma_patients p
      using public.tiroma_regles g
      where g.client_id = p.client_id and g.entite_id = p.entite_id
        and coalesce(greatest(p.dernier_rdv_le, p.dernier_acte_le), (p.vu_premier_le at time zone 'UTC')::date)
            < (p_maintenant - make_interval(months => g.patient_actif_mois))::date
        and not exists (select 1 from public.tiroma_rendez_vous v
                        where v.patient_id = p.id and v.statut = 'prevu' and v.debut >= p_maintenant)
        and not exists (select 1 from public.tiroma_liste_attente a
                        where a.patient_id = p.id and a.retire_le is null)
        and not exists (select 1 from public.tiroma_plans pl
                        where pl.patient_id = p.id and pl.statut in ('presente', 'signe', 'commence'))
      returning p.client_id, p.id::text as id)
    select d.client_id, count(*) as n, jsonb_agg(d.id order by d.id) as ids from d group by d.client_id
  loop
    v_bilan := jsonb_set(v_bilan, array[r.client_id::text],
      coalesce(v_bilan -> r.client_id::text, '{}'::jsonb)
      || jsonb_build_object('tiroma_patients', jsonb_build_object('n', r.n, 'ids', r.ids)));
  end loop;

  -- Une ligne de synthèse par organisation, au journal : les objets retirés.
  for r in select e.key as client, e.value as lignes from jsonb_each(v_bilan) e loop
    perform private.journaliser_module(r.client::uuid, 'tiroma', 'tiroma.purge', 'tiroma', null,
      jsonb_build_object('lignes', r.lignes,
                         'le', to_char(p_maintenant at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')));
  end loop;

  perform set_config('omega.tiroma_moteur', '', true);
  return v_bilan;
end $_$;


--
-- Name: tiroma_reserve(uuid, uuid, uuid, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_reserve(p_client uuid, p_entite uuid, p_fauteuil uuid, p_jour date, p_genre text) RETURNS tstzmultirange
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(range_agg(tstzrange(r.debut, r.fin)), '{}'::tstzmultirange)
  from public.tiroma_rendez_vous r
  join public.entites e on e.client_id = r.client_id and e.id = r.entite_id
  left join public.tiroma_types_rdv t on t.id = r.type_rdv_id
  where r.client_id = p_client and r.entite_id = p_entite and r.fauteuil_id = p_fauteuil
    and tstzrange(r.debut, r.fin) && private.tiroma_bornes_jour(p_jour, e.fuseau)
    and coalesce(t.famille, '') <> 'personnel'
    and case p_genre
          when 'prevue' then r.statut in ('prevu', 'honore')
          when 'realisee' then r.statut = 'honore' or (r.statut = 'prevu' and r.presume = 'honore')
          else false
        end
$$;


--
-- Name: tiroma_reserve_valide(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_reserve_valide(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  e jsonb;
  j jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 20 then
    return false;
  end if;
  for e in select value from jsonb_array_elements(p) loop
    if jsonb_typeof(e) <> 'object'
       or jsonb_typeof(e -> 'jours') is distinct from 'array' or jsonb_array_length(e -> 'jours') = 0
       or coalesce(e ->> 'demi_journee', '') not in ('matin', 'apres_midi')
       or (e ->> 'minutes') !~ '^[0-9]+$' or (e ->> 'minutes')::integer not between 5 and 240 then
      return false;
    end if;
    for j in select value from jsonb_array_elements(e -> 'jours') loop
      if jsonb_typeof(j) <> 'number' or j::text !~ '^[1-7]$' then
        return false;
      end if;
    end loop;
  end loop;
  return true;
end $_$;


--
-- Name: tiroma_seances_valides(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_seances_valides(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  e jsonb;
  n integer := 0;
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) = 0 or jsonb_array_length(p) > 20 then
    return false;
  end if;
  for e in select value from jsonb_array_elements(p) loop
    n := n + 1;
    if jsonb_typeof(e) <> 'object'
       or jsonb_typeof(e -> 'rang') is distinct from 'number' or (e ->> 'rang') !~ '^[0-9]+$'
       or (e ->> 'rang')::integer <> n
       or jsonb_typeof(e -> 'duree_min') is distinct from 'number' or (e ->> 'duree_min') !~ '^[0-9]+$'
       or (e ->> 'duree_min')::integer not between 5 and 600
       or (e ? 'labo' and jsonb_typeof(e -> 'labo') <> 'boolean')
       or (e ? 'delai_min_jours' and ((e ->> 'delai_min_jours') !~ '^[0-9]+$'
                                      or (e ->> 'delai_min_jours')::integer > 365)) then
      return false;
    end if;
  end loop;
  return true;
end $_$;


--
-- Name: tiroma_signer_validation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_signer_validation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := (select auth.uid());
begin
  -- (deux « if » imbriqués : l'expression intérieure n'est préparée que pour
  -- le vocabulaire, seule table qui porte ces colonnes)
  if tg_table_name = 'tiroma_types_rdv' and v_uid is not null then
    if (new.famille, new.necessite_labo, new.chirurgie, new.exige_assistante, new.capacite_requise, new.duree_defaut_min)
       is distinct from
       (old.famille, old.necessite_labo, old.chirurgie, old.exige_assistante, old.capacite_requise, old.duree_defaut_min) then
      new.classe_par := 'humain';
      new.confiance := null;
    end if;
  end if;
  if new.statut = 'valide' and old.statut is distinct from 'valide' then
    if v_uid is not null then
      new.valide_par := v_uid;
      new.valide_le := now();
    else
      new.valide_le := coalesce(new.valide_le, now());
    end if;
  elsif new.statut <> 'valide' then
    new.valide_par := null;
    new.valide_le := null;
  end if;
  new.maj_le := now();
  return new;
end $$;


--
-- Name: tiroma_trace_ecriture(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tiroma_trace_ecriture() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(current_setting('omega.tiroma_moteur', true), '') = ''
      or coalesce(nullif(current_setting('role', true), ''), 'none') not in ('service_role', 'none')
$$;


--
-- Name: tracer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tracer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ligne jsonb;
  v_avant jsonb;
  v_client uuid;
  v_objet text;
  v_donnees jsonb;
  v_args text[] := coalesce(tg_argv::text[], array[]::text[]);
  v_inclus text[];
  v_exclus text[];
  v_cle text;
begin
  if coalesce(current_setting('omega.effacement_objet', true), '') = 'oui' then
    return null;
  end if;

  v_inclus := array(select substr(a, 2) from unnest(v_args) a where left(a, 1) = '+');
  v_exclus := array(select a from unnest(v_args) a where left(a, 1) <> '+');

  if tg_op = 'DELETE' then
    v_ligne := to_jsonb(old);
  else
    v_ligne := to_jsonb(new);
  end if;

  if tg_table_name = 'clients' then
    -- Une organisation qui disparaît emporte son journal : rien à écrire.
    if tg_op = 'DELETE' then
      return null;
    end if;
    v_client := (v_ligne ->> 'id')::uuid;
  else
    v_client := (v_ligne ->> 'client_id')::uuid;
  end if;

  if v_client is null
     or v_client::text = coalesce(current_setting('omega.effacement_client', true), '') then
    return null;
  end if;

  v_objet := case tg_table_name
    when 'comptes' then v_ligne ->> 'user_id'
    when 'comptes_entites' then (v_ligne ->> 'user_id') || ':' || (v_ligne ->> 'entite_id')
    else v_ligne ->> 'id'
  end;

  if tg_op = 'UPDATE' then
    v_avant := to_jsonb(old);
    v_donnees := '{}'::jsonb;
    for v_cle in select jsonb_object_keys(v_ligne) loop
      if (cardinality(v_inclus) = 0 or v_cle = any (v_inclus))
         and not (v_cle = any (v_exclus))
         and (v_avant -> v_cle) is distinct from (v_ligne -> v_cle) then
        v_donnees := v_donnees || jsonb_build_object(v_cle, jsonb_build_array(v_avant -> v_cle, v_ligne -> v_cle));
      end if;
    end loop;
    if v_donnees = '{}'::jsonb then
      return null;
    end if;
  elsif cardinality(v_inclus) > 0 then
    select coalesce(jsonb_object_agg(e.cle, e.valeur), '{}'::jsonb) into v_donnees
    from jsonb_each(v_ligne) as e(cle, valeur)
    where e.cle = any (v_inclus);
  else
    v_donnees := v_ligne - v_exclus;
  end if;

  perform private.journaliser(
    v_client,
    tg_table_name || '.' || case tg_op when 'INSERT' then 'creation' when 'UPDATE' then 'modification' else 'suppression' end,
    tg_table_name,
    v_objet,
    v_donnees,
    case when tg_table_name = 'entites' then (v_ligne ->> 'id')::uuid
         else nullif(v_ligne ->> 'entite_id', '')::uuid end);
  return null;
end $$;


--
-- Name: tracer_lecture(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tracer_lecture(p_client uuid, p_objet_type text, p_objet_id text, p_contexte text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_acteur record;
  v_role text := coalesce(nullif(current_setting('role', true), 'none'), session_user::text);
begin
  select * into v_acteur from private.acteur_courant();
  if v_acteur.acteur_type = 'utilisateur' then
    if not private.voit_objet_pour(v_acteur.acteur_id, p_client, p_objet_type, p_objet_id) then
      raise exception 'Cet objet ne vous est pas ouvert.' using errcode = '42501';
    end if;
  elsif v_role <> 'service_role' then
    raise exception 'Une lecture est tracée par une personne connectée ou par le serveur.' using errcode = '42501';
  end if;
  insert into public.lectures (client_id, acteur_type, user_id, acteur_libelle, objet_type, objet_id, contexte)
  values (p_client, v_acteur.acteur_type, v_acteur.acteur_id, v_acteur.acteur_libelle,
          p_objet_type, p_objet_id, left(p_contexte, 200));
end $$;


--
-- Name: trancher_instantane(uuid, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.trancher_instantane(p_instantane uuid, p_decision text, p_motif text DEFAULT NULL::text, p_par text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  i public.instantanes;
  b public.branchements;
  j public.branchements_jeux;
  v_par text;
begin
  select * into i from public.instantanes where id = p_instantane for update;
  if not found or ((select auth.uid()) is not null and not exists (
       select 1 from public.comptes c where c.user_id = (select auth.uid()) and c.client_id = i.client_id)) then
    raise exception 'Instantané introuvable.' using errcode = 'P0002';
  end if;
  select * into b from public.branchements where id = i.branchement_id;
  perform private.exiger_gestion_releve(b.client_id, b.entite_id);
  v_par := private.signature_releve(p_par);
  select * into j from public.branchements_jeux where id = i.jeu_id;

  if p_decision = 'appliquer' then
    if i.statut <> 'douteux' then
      raise exception 'Seul un relevé douteux s''applique sur décision (statut %).', i.statut using errcode = '55000';
    end if;
    if exists (select 1 from public.instantanes k
               where k.jeu_id = i.jeu_id and k.id <> i.id and k.recu_le > i.recu_le
                 and k.statut in ('recu', 'en_lecture', 'lu', 'a_appliquer', 'applique', 'identique', 'douteux')) then
      raise exception 'Un export plus récent de ce jeu existe : c''est lui qu''il faut trancher.' using errcode = '55000';
    end if;
    update public.instantanes
       set force = true, tranche_par = v_par, tranche_le = now(),
           motif = left(coalesce(nullif(btrim(p_motif), ''), motif), 500)
     where id = i.id;
    if i.lignes = 0 or exists (select 1 from public.instantanes_lignes l where l.instantane_id = i.id) then
      update public.instantanes set statut = 'lu' where id = i.id;
      perform private.avancer_jeu(i.jeu_id, private.limite_requete());
    else
      -- Les lignes sont purgées : on relit le fichier.
      update public.instantanes set statut = 'recu' where id = i.id;
      perform private.deposer_travail(b.client_id, b.module, 'releve.lire', jsonb_build_object('instantane', i.id),
                                      'instantane:' || i.id::text, 0::smallint);
    end if;
  elsif p_decision = 'ecarter' then
    if i.statut not in ('douteux', 'a_classer', 'rejete', 'echec') then
      raise exception 'Seul un relevé douteux, non reconnu ou illisible s''écarte (statut %).', i.statut using errcode = '55000';
    end if;
    update public.instantanes
       set statut = 'ecarte', tranche_par = v_par, tranche_le = now(),
           motif = left(coalesce(nullif(btrim(p_motif), ''), motif), 500)
     where id = i.id;
    delete from public.instantanes_lignes where instantane_id = i.id;
    update public.pieces set statut = 'lue' where id = i.piece_id and statut = 'a_verifier';
    if i.jeu_id is not null and not exists (select 1 from public.instantanes k where k.jeu_id = i.jeu_id and k.statut = 'douteux') then
      perform private.fermer_alertes_releve(b.client_id, b.module, 'releve.douteux.' || i.jeu_id::text, 'écarté par ' || v_par);
      perform private.fermer_alertes_releve(b.client_id, b.module, 'releve.douteux_suite.' || i.jeu_id::text, 'écarté par ' || v_par);
    end if;
    if not exists (select 1 from public.instantanes k where k.branchement_id = b.id and k.statut = 'a_classer') then
      perform private.fermer_alertes_releve(b.client_id, b.module, 'releve.a_classer.' || b.id::text, 'écarté par ' || v_par);
    end if;
    if not exists (select 1 from public.instantanes k where k.branchement_id = b.id and k.statut in ('rejete', 'echec')) then
      perform private.fermer_alertes_releve(b.client_id, b.module, 'releve.illisible.' || b.id::text, 'écarté par ' || v_par);
    end if;
  else
    raise exception 'Décision inconnue : % (appliquer ou ecarter).', coalesce(p_decision, 'vide') using errcode = '22023';
  end if;
  return (select jsonb_build_object('instantane', x.id, 'statut', x.statut, 'tranche_par', x.tranche_par)
          from public.instantanes x where x.id = i.id);
end $$;


--
-- Name: valider_gabarit(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.valider_gabarit(p_gabarit uuid, p_par text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_acteur record;
  v_par text;
begin
  perform private.exiger_ouvrier();
  select * into v_acteur from private.acteur_courant();
  v_par := coalesce(nullif(btrim(p_par), ''), case when v_acteur.acteur_type = 'operateur' then v_acteur.acteur_libelle end);
  if v_par is null then
    raise exception 'Un gabarit est validé par une personne nommée : qui valide ?' using errcode = '22023';
  end if;
  update public.gabarits_messages set statut = 'valide', valide_par = left(v_par, 200), valide_le = now()
   where id = p_gabarit and statut = 'brouillon';
  if not found then
    raise exception 'Gabarit introuvable, ou déjà validé.' using errcode = 'P0002';
  end if;
end $$;


--
-- Name: variables_du_texte(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.variables_du_texte(p text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(m.v[1] order by m.n), '{}')
  from regexp_matches(coalesce(p, ''), '\{\{([a-z][a-z0-9_]{0,39})\}\}', 'g') with ordinality as m(v, n)
$$;


--
-- Name: verifier_calendrier(text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verifier_calendrier(p_territoire text, p_jour date) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_complet boolean;
begin
  select t.complet into v_complet from public.territoires t where t.code = p_territoire;
  if not found then
    raise exception 'Territoire inconnu : %.', coalesce(p_territoire, 'vide') using errcode = '22023';
  end if;
  if not v_complet then
    raise exception 'Les jours fériés de droit local de % ne sont pas au calendrier : aucun décompte en jours ouvrés ou ouvrables, ni aucune prorogation, n''y est calculé.', p_territoire
      using errcode = '22023',
            hint = 'Relever ses jours dans le texte local, les ajouter à private.jours_feries_regles, régénérer, puis passer territoires.complet à vrai.';
  end if;
  if not exists (select 1 from public.jours_feries f
                 where f.territoire = p_territoire
                   and f.jour >= make_date(extract(year from p_jour)::int, 1, 1)
                   and f.jour <= make_date(extract(year from p_jour)::int, 12, 31)) then
    raise exception 'Le calendrier officiel de % ne couvre pas %.', p_territoire, extract(year from p_jour)::int
      using errcode = '22023', hint = 'Générer l''année par private.generer_jours_feries, après avoir vérifié les règles.';
  end if;
end $$;


--
-- Name: verifier_fuseau(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verifier_fuseau() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = new.fuseau) then
    raise exception 'Fuseau horaire inconnu : %.', new.fuseau using errcode = '22023';
  end if;
  return new;
end $$;


--
-- Name: verifier_gardien(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verifier_gardien() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  f regprocedure;
begin
  foreach f in array array_remove(array[new.voit, new.ecrit, new.lit], null) loop
    if not exists (
      select 1 from pg_catalog.pg_proc p
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace
      where p.oid = f
        and n.nspname = 'private'
        and p.prorettype = 'pg_catalog.bool'::pg_catalog.regtype::pg_catalog.oid
        and p.pronargs = 3
        and p.proargtypes[0] = 'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid
        and p.proargtypes[1] = 'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid
        and p.proargtypes[2] = 'pg_catalog.text'::pg_catalog.regtype::pg_catalog.oid
        and p.provolatile in ('s', 'i')
        and p.prosecdef
        and exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%')) then
      raise exception 'Un gardien est une fonction de private, (uuid, uuid, text) → boolean, stable, security definer, au search_path fixé : %.', f
        using errcode = '22023';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: verifier_journal(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verifier_journal(p_client uuid) RETURNS TABLE(lignes bigint, premiere_ligne_fausse bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.journal_opposable; v_precedent bytea; v_n bigint := 0;
begin
  for r in select * from public.journal_opposable j where j.client_id = p_client order by j.id loop
    v_n := v_n + 1;
    if r.hash_precedent is distinct from v_precedent
       or r.hash is distinct from private.empreinte_journal(v_precedent, r.id, r.client_id, r.entite_id,
            r.survenu_le, r.acteur_type, r.acteur_id, r.acteur_libelle, r.action, r.objet_type, r.objet_id, r.donnees)
    then
      lignes := v_n; premiere_ligne_fausse := r.id; return next; return;
    end if;
    v_precedent := r.hash;
  end loop;
  lignes := v_n; premiere_ligne_fausse := null; return next;
end $$;


--
-- Name: verifier_sauvegardes(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verifier_sauvegardes() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from private.sauvegardes s
             where s.restauration = 'reussie' and s.faite_le > now() - interval '26 hours') then
    update public.alertes
       set acquittee_le = now(), detail = detail || '{"resolution": "une sauvegarde restaurée a réussi"}'::jsonb
     where interne and cle_regroupement = 'sauvegarde:manquante' and acquittee_le is null;
  else
    perform private.lever_alerte(null, true, 'critique', 'sauvegarde',
      'Aucune sauvegarde restaurée avec succès depuis 26 heures',
      jsonb_build_object(
        'derniere_reussie', (select max(s.faite_le) from private.sauvegardes s where s.restauration = 'reussie'),
        'derniere_tentative', (select max(s.faite_le) from private.sauvegardes s),
        'que_faire', 'Voir la tâche GitHub « Sauvegarde de la base » et ses secrets SUPABASE_DB_URL et SAUVEGARDE_PHRASE.'),
      'sauvegarde:manquante');
  end if;
end $$;


--
-- Name: verrou(text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verrou(p_code text, p_motif text, p_definitif boolean DEFAULT true, p_reprise timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object('code', p_code, 'motif', left(p_motif, 500), 'definitif', p_definitif, 'reprise', p_reprise)
$$;


--
-- Name: verrous_envoi(public.envois, boolean, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verrous_envoi(p_e public.envois, p_complet boolean, p_instant timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  r jsonb := private.reglages_envois_effectifs(p_e.client_id, p_e.module);
  v_canal private.canaux_envoi;
  v_module private.modules_envois;
  v_mode text;
  v_exp public.expediteurs;
  v_fournisseur text;
  v_agree boolean;
  v_type text;
  v_jusqu_au timestamptz;
  v_verrou jsonb;
  v_plages jsonb;
  v_legales jsonb;
  v_t timestamptz;
  v_t2 timestamptz;
  v_dernier timestamptz;
  v_delai interval;
  v_n integer;
  v_n_org integer;
  v_debut timestamptz;
  v_fuseau_org text;
  v_complet boolean;
begin
  select * into v_canal from private.canaux_envoi c where c.canal = p_e.canal;
  select * into v_module from private.modules_envois m where m.module = p_e.module;

  if p_complet and coalesce((select g.valeur from private.reglages g where g.cle = 'envois_arret_general'), 'non') = 'oui' then
    return private.verrou('ARRET_GENERAL', 'Arrêt général des envois : rien ne part tant qu''Omega ne l''a pas levé.',
                          false, p_instant + interval '15 minutes');
  end if;

  v_mode := r ->> 'mode';
  if v_mode is null then
    return private.verrou('CONFIG_ABSENTE',
      format('Le module %s n''est pas réglé pour cette organisation : aucun envoi.', p_e.module));
  elsif v_mode = 'coupe' then
    return private.verrou('MOTEUR_COUPE', format('Les envois du module %s sont coupés pour cette organisation.', p_e.module));
  end if;
  if p_e.mode = 'essai' then
    v_mode := 'essai';   -- un envoi préparé en essai ne devient jamais réel
  end if;

  if (v_module.canaux is not null and not (p_e.canal = any (v_module.canaux)))
     or (jsonb_typeof(r -> 'canaux_organisation') = 'array' and not ((r -> 'canaux_organisation') ? p_e.canal))
     or (jsonb_typeof(r -> 'canaux_module') = 'array' and not ((r -> 'canaux_module') ? p_e.canal)) then
    return private.verrou('CANAL_NON_PERMIS', format('Le canal %s n''est pas permis pour ces envois.', v_canal.libelle));
  end if;
  if not v_canal.permis_sante and ((r ->> 'sante')::boolean or coalesce(v_module.sante, false)) then
    return private.verrou('CANAL_NON_PERMIS',
      format('Pas de %s dans un contexte de santé : aucun prestataire n''y est certifié.', v_canal.libelle));
  end if;

  if p_e.destinataire_adresse is null then
    return private.verrou('DESTINATAIRE_SANS_ADRESSE', coalesce(p_e.motif, 'Le destinataire n''a pas d''adresse pour ce canal.'));
  end if;

  if v_mode = 'essai' then
    if r ->> 'essai_adresse' is null then
      return private.verrou('ESSAI_SANS_ADRESSE', 'Mode essai sans adresse où recevoir les messages : réglez essai_adresse.');
    end if;
    v_fournisseur := coalesce((select g.valeur from private.reglages g where g.cle = 'envois_essai_fournisseur'), 'brevo');
  else
    select x.* into v_exp from public.expediteurs x
    where x.client_id = p_e.client_id and x.canal = p_e.canal and x.statut = 'actif'
      and (x.module is null or x.module = p_e.module)
    order by (x.module is not null) desc
    limit 1;
    if v_exp.id is null then
      return private.verrou('EXPEDITEUR_ABSENT',
        format('Aucun expéditeur actif pour le canal %s : Omega le branche à l''installation.', v_canal.libelle));
    end if;
    v_fournisseur := v_exp.fournisseur;
  end if;
  v_agree := coalesce((select f.agree_sante from private.fournisseurs_envoi f where f.fournisseur = v_fournisseur), false);

  select o.type, o.jusqu_au into v_type, v_jusqu_au
  from public.oppositions o
  where o.client_id = p_e.client_id and o.levee_le is null
    and (o.adresse = p_e.destinataire_adresse or (p_e.destinataire_ref is not null and o.ref = p_e.destinataire_ref))
    and (o.canal is null or o.canal = p_e.canal)
    and (o.type <> 'pause' or o.jusqu_au > p_instant)
    and not (o.type = 'desinscription' and p_e.canal = 'lre')
  order by case o.type when 'invalide' then 1 when 'desinscription' then 2 else 3 end, o.jusqu_au desc nulls first
  limit 1;
  if v_type = 'invalide' then
    return private.verrou('ADRESSE_INVALIDE', 'Cette adresse ne reçoit pas les messages (rebond, numéro erroné).');
  elsif v_type = 'desinscription' then
    return private.verrou('DESINSCRIT', 'Cette personne a demandé à ne plus recevoir de messages.');
  elsif v_type = 'pause' then
    return private.verrou('PAUSE', format('Cette personne est en pause jusqu''au %s : une réponse attend d''être traitée.',
                                          private.date_fr(v_jusqu_au, p_e.destinataire_fuseau)));
  end if;

  if (v_canal.consentement_toujours or not p_e.transactionnel
      or (p_e.canal = 'lre' and not p_e.destinataire_professionnel))
     and not exists (select 1 from public.consentements k
                     where k.client_id = p_e.client_id and k.canal = p_e.canal
                       and k.adresse = p_e.destinataire_adresse and k.retire_le is null
                       and (p_e.transactionnel or k.portee = 'tout')) then
    return private.verrou('CONSENTEMENT_ABSENT', case
      when v_canal.consentement_toujours then 'WhatsApp exige l''accord préalable du destinataire : il manque.'
      when not p_e.transactionnel then 'Un message non transactionnel exige l''accord du destinataire : il manque.'
      else 'Une LRE à un particulier exige son accord préalable (CPCE, art. L100) : il manque.' end);
  end if;

  if p_e.donnees_sante and not v_agree then
    return private.verrou('SANTE_HORS_CANAL_AGREE',
      'Ce message porte des données de santé : il ne part que par un expéditeur agréé (HDS, MSSanté).');
  end if;

  if exists (select 1 from public.envois x
             where x.client_id = p_e.client_id and x.canal = p_e.canal and x.mode = p_e.mode
               and x.destinataire_adresse = p_e.destinataire_adresse and x.empreinte = p_e.empreinte
               and x.statut in ('a_valider', 'differe', 'pret', 'en_cours', 'envoye')
               and (p_e.suivi_id is null or x.suivi_id is distinct from p_e.suivi_id)
               and (x.cree_le, x.id) < (p_e.cree_le, p_e.id)
               and x.cree_le > p_instant - (r ->> 'fenetre_doublon')::interval) then
    return private.verrou('DOUBLON', 'Le même message est déjà parti, ou en route, vers ce destinataire.');
  end if;

  if v_module.verrou is not null then
    execute format('select %s($1)', v_module.verrou::regproc) into v_verrou using p_e;
    if v_verrou is not null and nullif(v_verrou ->> 'code', '') is not null then
      if coalesce((v_verrou ->> 'definitif')::boolean, true) then
        return private.verrou(left(v_verrou ->> 'code', 60), coalesce(v_verrou ->> 'motif', 'Verrou du module.'));
      elsif p_complet then
        return private.verrou(left(v_verrou ->> 'code', 60), coalesce(v_verrou ->> 'motif', 'Verrou du module.'), false,
                              coalesce((v_verrou ->> 'reprise_le')::timestamptz, p_instant + interval '1 hour'));
      end if;
    end if;
  end if;

  if p_complet then
    -- Les heures et les jours du destinataire, dans son fuseau ; pour un
    -- message non transactionnel, aussi les heures légales du canal, qui
    -- excluent toujours les jours fériés : il faut alors connaître son calendrier.
    v_plages := r -> 'plages';
    v_legales := case when not p_e.transactionnel then v_canal.plages_non_transactionnel end;
    v_complet := (select t.complet from public.territoires t where t.code = p_e.destinataire_territoire);
    if v_legales is not null and not coalesce(v_complet, false) then
      return private.verrou('CALENDRIER_INCONNU',
        'Démarchage : jamais un jour férié ; le calendrier du destinataire est inconnu ou incomplet, l''envoi est retenu.');
    end if;
    if not (r ->> 'feries')::boolean and v_complet is false then
      return private.verrou('CALENDRIER_INCOMPLET',
        format('Les jours fériés de droit local (%s) ne sont pas au calendrier : l''envoi est retenu. Pour envoyer quand même, autorisez les jours fériés dans les réglages.',
               p_e.destinataire_territoire));
    end if;
    v_t := p_instant;
    for i in 1..20 loop
      v_t2 := private.prochaine_ouverture(v_plages, p_e.destinataire_fuseau, p_e.destinataire_territoire,
                                          (r ->> 'feries')::boolean, v_t);
      exit when v_t2 is null;
      if v_legales is not null then
        v_t2 := private.prochaine_ouverture(v_legales, p_e.destinataire_fuseau, p_e.destinataire_territoire, false, v_t2);
        exit when v_t2 is null;
      end if;
      exit when v_t2 = v_t;
      v_t := v_t2;
    end loop;
    if v_t2 is null or v_t2 > p_instant then
      v_t2 := coalesce(v_t2, p_instant + interval '1 day');
      return private.verrou('HORS_HEURES',
        format('Hors des heures d''envoi du destinataire : départ le %s, heure de %s.',
               private.date_fr(v_t2, p_e.destinataire_fuseau), p_e.destinataire_fuseau), false, v_t2);
    end if;

    if p_e.espacement then
      v_delai := (r ->> 'delai_min')::interval;
      if v_delai > interval '0' then
        select max(coalesce(x.envoye_le, x.pret_le)) into v_dernier
        from public.envois x
        where x.client_id = p_e.client_id and x.id <> p_e.id and x.espacement and x.mode = v_mode
          and x.statut in ('pret', 'en_cours', 'envoye')
          and (x.destinataire_adresse = p_e.destinataire_adresse
               or (p_e.destinataire_ref is not null and x.destinataire_ref = p_e.destinataire_ref));
        if v_dernier is not null and v_dernier + v_delai > p_instant then
          return private.verrou('DELAI_MINIMAL',
            format('Un message est parti vers cette personne le %s : le suivant attend le %s.',
                   private.date_fr(v_dernier, p_e.destinataire_fuseau),
                   private.date_fr(v_dernier + v_delai, p_e.destinataire_fuseau)), false, v_dernier + v_delai);
        end if;
      end if;
      v_debut := date_trunc('day', p_instant at time zone p_e.destinataire_fuseau) at time zone p_e.destinataire_fuseau;
      select count(*) into v_n
      from public.envois x
      where x.client_id = p_e.client_id and x.id <> p_e.id and x.espacement and x.mode = v_mode
        and x.statut in ('pret', 'en_cours', 'envoye') and x.pret_le >= v_debut
        and (x.destinataire_adresse = p_e.destinataire_adresse
             or (p_e.destinataire_ref is not null and x.destinataire_ref = p_e.destinataire_ref));
      if v_n >= (r ->> 'plafond_destinataire_jour')::int then
        return private.verrou('PLAFOND_DESTINATAIRE',
          format('Déjà %s messages aujourd''hui vers cette personne : le suivant part demain.', v_n), false,
          (date_trunc('day', p_instant at time zone p_e.destinataire_fuseau) + interval '1 day') at time zone p_e.destinataire_fuseau);
      end if;
    end if;

    v_fuseau_org := coalesce((select en.fuseau from public.entites en where en.client_id = p_e.client_id and en.principale),
                             'Europe/Paris');
    v_debut := date_trunc('day', p_instant at time zone v_fuseau_org) at time zone v_fuseau_org;
    select count(*) filter (where x.module = p_e.module), count(*) into v_n, v_n_org
    from public.envois x
    where x.client_id = p_e.client_id and x.id <> p_e.id and x.mode = v_mode
      and x.statut in ('pret', 'en_cours', 'envoye') and x.pret_le >= v_debut;
    if v_n >= (r ->> 'plafond_jour')::int then
      return private.verrou('PLAFOND_JOUR',
        format('Plafond du jour atteint pour le module %s (%s envois) : la suite part demain.', p_e.module, v_n), false,
        (date_trunc('day', p_instant at time zone v_fuseau_org) + interval '1 day') at time zone v_fuseau_org);
    end if;
    if v_n_org >= (r ->> 'plafond_jour_organisation')::int then
      return private.verrou('PLAFOND_ORGANISATION',
        format('Plafond du jour atteint pour l''organisation (%s envois) : la suite part demain.', v_n_org), false,
        (date_trunc('day', p_instant at time zone v_fuseau_org) + interval '1 day') at time zone v_fuseau_org);
    end if;
  end if;

  return jsonb_build_object('code', null, 'mode', v_mode, 'expediteur', v_exp.id, 'fournisseur', v_fournisseur);
end $_$;


--
-- Name: voit_entite(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.voit_entite(p_client uuid, p_entite uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.comptes c
    where c.user_id = (select auth.uid())
      and c.client_id = p_client
      and (c.perimetre_total or exists (
        select 1 from public.comptes_entites ce
        where ce.user_id = c.user_id and ce.client_id = p_client and ce.entite_id = p_entite))
  )
$$;


--
-- Name: voit_objet(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.voit_objet(p_client uuid, p_type text, p_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.voit_objet_pour((select auth.uid()), p_client, p_type, p_id)
$$;


--
-- Name: voit_objet_pour(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.voit_objet_pour(p_user uuid, p_client uuid, p_type text, p_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gardien regprocedure;
begin
  if p_type is not null and p_id is not null then
    select g.voit into v_gardien from private.gardiens_objets g where g.objet_type = p_type;
    if found then
      if not exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client) then
        return false;
      end if;
      return private.appeler_gardien(v_gardien, p_user, p_client, p_id);
    end if;
  end if;
  return exists (
      select 1 from public.comptes c
      where c.user_id = p_user and c.client_id = p_client and c.role = 'gerant')
    or (exists (select 1 from public.comptes c where c.user_id = p_user and c.client_id = p_client)
        and (p_type is null or p_id is null
             or not exists (select 1 from public.objets_restreints r
                            where r.client_id = p_client and r.objet_type = p_type)
             or exists (select 1 from public.acces_objets a
                        where a.client_id = p_client and a.objet_type = p_type and a.objet_id = p_id
                          and (a.user_id = p_user
                               or a.equipe_id in (select m.equipe_id from public.equipes_membres m
                                                  where m.user_id = p_user and m.client_id = p_client)))));
end $$;


