--
-- Name: agenda_public(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agenda_public(p_depuis date, p_jusqua date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_depuis date := greatest(p_depuis, current_date);
  v_jusqua date := least(p_jusqua, current_date + 70);
begin
  if v_jusqua < v_depuis then
    return jsonb_build_object('regles', '[]'::jsonb, 'blocages', '[]'::jsonb, 'occupes', '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'regles', coalesce((select jsonb_agg(jsonb_build_object(
        'jour', jour_semaine, 'debut', to_char(heure_debut,'HH24:MI'), 'fin', to_char(heure_fin,'HH24:MI')))
      from agenda_regles where actif), '[]'::jsonb),
    'blocages', coalesce((select jsonb_agg(jsonb_build_object('debut', debut, 'fin', fin))
      from agenda_blocages
      where fin > v_depuis::timestamptz and debut < (v_jusqua + 1)::timestamptz), '[]'::jsonb),
    'occupes', coalesce((select jsonb_agg(jsonb_build_object('debut', creneau_debut, 'fin', creneau_fin))
      from demandes_audit
      where statut = 'confirme' and creneau_debut is not null
        and creneau_fin > v_depuis::timestamptz
        and creneau_debut < (v_jusqua + 1)::timestamptz), '[]'::jsonb)
  );
end;
$$;


--
-- Name: ajouter_jours(date, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajouter_jours(p_depart date, p_nombre integer, p_mode text, p_territoire text DEFAULT 'metropole'::text) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v date := p_depart;
  v_reste integer := abs(p_nombre);
  v_pas integer := case when p_nombre < 0 then -1 else 1 end;
begin
  if p_depart is null or p_nombre is null then
    raise exception 'Un départ et un nombre de jours sont nécessaires.' using errcode = '22023';
  end if;
  if p_mode = 'calendaires' then
    return p_depart + p_nombre;
  elsif p_mode = 'francs' then
    return p_depart + p_nombre + v_pas;
  elsif p_mode not in ('ouvres', 'ouvrables') then
    raise exception 'Mode de décompte inconnu : %.', coalesce(p_mode, 'vide') using errcode = '22023';
  end if;
  while v_reste > 0 loop
    v := v + v_pas;
    if public.jour_ouvre(v, p_territoire, p_mode = 'ouvrables') then
      v_reste := v_reste - 1;
    end if;
  end loop;
  return v;
end $$;


