--
-- Name: annuler_demande(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.annuler_demande(p_demande uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  d public.demandes_audit;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'erreur', 'connexion_requise');
  end if;
  select * into d from public.demandes_audit
   where id = p_demande and utilisateur_id = auth.uid()
   for update;
  if not found or d.parcours <> 'reglage' then
    return jsonb_build_object('ok', false, 'erreur', 'demande_inconnue');
  end if;
  if d.client_id is not null then
    return jsonb_build_object('ok', false, 'erreur', 'deja_finalisee');
  end if;
  if d.statut not in ('confirme', 'a_traiter') then
    return jsonb_build_object('ok', false, 'erreur', 'statut_incompatible');
  end if;
  if d.creneau_debut is not null and d.creneau_debut < now() then
    return jsonb_build_object('ok', false, 'erreur', 'statut_incompatible');
  end if;
  update public.demandes_audit set statut = 'annule' where id = d.id;
  return jsonb_build_object('ok', true, 'id', d.id, 'statut', 'annule');
end $$;


