--
-- Name: commander_site(text, text, text, text, text, jsonb, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commander_site(p_modele text, p_entreprise text, p_secteur text DEFAULT NULL::text, p_telephone text DEFAULT NULL::text, p_commune text DEFAULT NULL::text, p_infos jsonb DEFAULT '{}'::jsonb, p_logo text DEFAULT NULL::text, p_images text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_id uuid;
  v_dossier text;
  f text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'erreur', 'connexion_requise');
  end if;
  if p_modele is null or p_modele !~ '^[a-z0-9-]{1,60}$' then
    return jsonb_build_object('ok', false, 'erreur', 'modele_invalide');
  end if;
  if coalesce(trim(p_entreprise), '') = '' or length(p_entreprise) > 120 then
    return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
  end if;
  if pg_column_size(coalesce(p_infos, '{}'::jsonb)) > 20000 then
    return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
  end if;
  if (select count(*) from commandes_site
      where utilisateur_id = auth.uid() and statut in ('brouillon','a_payer')) >= 3 then
    return jsonb_build_object('ok', false, 'erreur', 'trop_de_demandes');
  end if;
  v_dossier := auth.uid()::text || '/';
  if p_logo is not null and position(v_dossier in p_logo) <> 1 then
    return jsonb_build_object('ok', false, 'erreur', 'fichier_invalide');
  end if;
  foreach f in array coalesce(p_images, '{}'::text[]) loop
    if position(v_dossier in f) <> 1 then
      return jsonb_build_object('ok', false, 'erreur', 'fichier_invalide');
    end if;
  end loop;
  if coalesce(array_length(p_images, 1), 0) > 12 then
    return jsonb_build_object('ok', false, 'erreur', 'fichier_invalide');
  end if;
  insert into commandes_site
    (utilisateur_id, modele, entreprise, secteur, telephone, commune, infos, logo_chemin, images_chemins)
  values
    (auth.uid(), p_modele, trim(p_entreprise),
     nullif(trim(coalesce(p_secteur, '')), ''), nullif(trim(coalesce(p_telephone, '')), ''),
     nullif(trim(coalesce(p_commune, '')), ''), coalesce(p_infos, '{}'::jsonb), p_logo,
     coalesce(p_images, '{}'::text[]))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $_$;


