CREATE FUNCTION public.demande_pour_confirmation(p_id uuid) RETURNS TABLE(prenom text, nom text, email text, entreprise text, parcours text, formule text, creneau_debut timestamp with time zone, duree_min integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.demandes_audit d
     set confirmation_envoyee_le = now()
   where d.id = p_id
     and d.confirmation_envoyee_le is null
     and d.cree_le > now() - interval '30 minutes'
  returning d.prenom, d.nom, d.email, d.entreprise,
            d.parcours, d.formule, d.creneau_debut, d.duree_min;
$$;


--
-- Name: demander_abonnement(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.demander_abonnement(p_type text, p_detail jsonb DEFAULT '{}'::jsonb, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_detail jsonb;
  v_modules text[];
  v_client uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'erreur', 'connexion_requise');
  end if;
  if p_type is null or p_type not in ('changement','resiliation') then
    return jsonb_build_object('ok', false, 'erreur', 'type_inconnu');
  end if;
  v_detail := coalesce(p_detail, '{}'::jsonb);
  if jsonb_typeof(v_detail) <> 'object' or pg_column_size(v_detail) > 4000 then
    return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
  end if;
  if v_detail ? 'modules' then
    if jsonb_typeof(v_detail -> 'modules') <> 'array' then
      return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
    end if;
    v_modules := (select array_agg(distinct m order by m)
                  from jsonb_array_elements_text(v_detail -> 'modules') m
                  where m in ('cashd','reload','frontd','filed'));
    if v_modules is null then
      return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
    end if;
    v_detail := v_detail || jsonb_build_object('modules', to_jsonb(v_modules));
  end if;
  if v_detail ? 'periodicite'
     and (jsonb_typeof(v_detail -> 'periodicite') <> 'string'
          or v_detail ->> 'periodicite' not in ('mensuel','annuel')) then
    return jsonb_build_object('ok', false, 'erreur', 'periodicite_inconnue');
  end if;
  if v_detail ? 'motif' then
    if jsonb_typeof(v_detail -> 'motif') <> 'string' then
      return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
    end if;
    v_detail := v_detail || jsonb_build_object('motif',
      nullif(left(trim(v_detail ->> 'motif'), 500), ''));
  end if;
  if (select count(*) from public.demandes_abonnement
      where utilisateur_id = auth.uid() and statut = 'a_traiter') >= 3 then
    return jsonb_build_object('ok', false, 'erreur', 'trop_de_demandes');
  end if;
  select client_id into v_client from public.comptes
   where user_id = auth.uid() order by cree_le limit 1;
  if v_client is null and not exists (
       select 1 from public.demandes_audit
        where utilisateur_id = auth.uid() and parcours = 'reglage' and statut <> 'annule') then
    return jsonb_build_object('ok', false, 'erreur', 'aucun_abonnement');
  end if;
  insert into public.demandes_abonnement (utilisateur_id, client_id, type, detail, message)
  values (auth.uid(), v_client, p_type, v_detail,
          nullif(left(trim(coalesce(p_message, '')), 2000), ''))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;


