--
-- Name: f_audit_trail(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_audit_trail() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_avant jsonb; v_apres jsonb; v_cle text;
begin
  if tg_op in ('UPDATE','DELETE') then v_avant := to_jsonb(old); end if;
  if tg_op in ('INSERT','UPDATE') then v_apres := to_jsonb(new); end if;
  v_cle := coalesce(v_apres->>'id', v_avant->>'id', v_apres->>'cle', v_avant->>'cle',
                    (coalesce(v_apres->>'client_id', v_avant->>'client_id') || '/' ||
                     coalesce(v_apres->>'moteur', v_avant->>'moteur')));
  -- jamais de secret en clair dans l'audit
  if tg_table_name = 'parametres' and coalesce(v_apres->>'cle', v_avant->>'cle') ilike '%secret%' then
    if v_avant is not null then v_avant := jsonb_set(v_avant, '{valeur}', '"[EXPURGE]"'); end if;
    if v_apres is not null then v_apres := jsonb_set(v_apres, '{valeur}', '"[EXPURGE]"'); end if;
  end if;
  insert into public.audit_journal (table_cible, operation, cle_ligne, avant, apres)
  values (tg_table_name, tg_op, v_cle, v_avant, v_apres);
  return coalesce(new, old);
end $$;


--
-- Name: f_checklist_collecte(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_checklist_collecte(p_moteurs text[], p_palier text DEFAULT 'tpe'::text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
with pal as (
  select * from paliers_entreprise where code = p_palier
),
moments(code, titre, rang) as (values
  ('audit',              'À l''audit — ce qui dimensionne l''offre',            1),
  ('avant_entretien',    'Avant l''entretien — ce que le client prépare seul',  2),
  ('entretien',          'Jour J — l''entretien',                               3),
  ('pointage',           'Jour J — le pointage des données',                    4),
  ('branchement',        'Les branchements techniques',                         5),
  ('apres_installation', 'Après l''installation',                               6)
),
items as (
  select pr.moteur, pr.cle, pr.intitule, pr.pourquoi, pr.fournisseur, pr.bloquant,
         pr.moment, pr.varie_par_secteur, pr.ordre,
         nullif(concat_ws(' · ',
           nullif(pr.collecte -> p_palier ->> 'mode',   ''),
           nullif(pr.collecte -> p_palier ->> 'volume', ''),
           nullif(pr.collecte -> p_palier ->> 'delai',  '')), '') as collecte_palier
    from prerequis_moteur pr
   where pr.moteur is null or pr.moteur = any (p_moteurs)
),
lignes as (
  select m.rang, m.titre,
         string_agg(
           '- [ ] **' || i.intitule || '**' || E'  \n      `' || coalesce(i.moteur, 'socle') || '`' ||
           case when i.bloquant then ' · **bloquant**' else ' · souhaitable' end ||
           case i.fournisseur when 'client' then ' · fourni par le client'
                              when 'omega'  then ' · à notre charge'
                              else ' · dépend d''un tiers' end ||
           case when i.varie_par_secteur then ' · varie selon le métier' else '' end ||
           E'  \n      *' || i.pourquoi || '*' ||
           case when i.collecte_palier is not null
                then E'  \n      → **À ce palier :** ' || i.collecte_palier
                else '' end,
           E'\n' order by (i.moteur is not null), i.moteur, i.ordre, i.cle) as corps
    from items i join moments m on m.code = i.moment
   group by m.rang, m.titre
)
select
  '# Checklist de collecte — ' || cardinality(p_moteurs) || ' moteur(s)' || E'\n\n' ||
  '> Générée depuis `prerequis_moteur`. **Ne pas éditer à la main** : toute correction' || E'\n' ||
  '> se fait en base, sinon la checklist et le système repartent en deux vérités.' || E'\n\n' ||
  '**Package retenu :** ' ||
  coalesce((select string_agg(mr.libelle || ' (' || mr.code || ')', ', ' order by mr.code)
              from moteurs_reconnus mr where mr.code = any (p_moteurs)), '—') || E'\n\n' ||
  '**Palier :** ' || coalesce((select libelle from pal), p_palier) ||
  ' — ' || coalesce((select critere from pal), 'palier inconnu') || E'\n\n' ||
  '*Ce qui change d''une entreprise à l''autre n''est pas cette liste — elle est dictée par' || E'\n' ||
  'les moteurs retenus — mais le volume et le mode de collecte, signalés ci-dessous par' || E'\n' ||
  '« À ce palier ». Le contenu métier, lui, vient des profils.*' || E'\n\n---\n\n' ||
  coalesce((select string_agg('## ' || l.titre || E'\n\n' || l.corps, E'\n\n' order by l.rang)
              from lignes l), '_Aucun prérequis pour ce package._') || E'\n\n---\n\n' ||
  '## Ce qu''on ne demande jamais' || E'\n\n' ||
  '- Un mot de passe par écrit — les accès se posent avec le client, devant lui.' || E'\n' ||
  '- Le motif réel d''une absence, d''un arrêt ou d''un litige : seule la cause publique' || E'\n' ||
  '  est saisie, et aucun moteur ne charge la cause interne.' || E'\n' ||
  '- Des données de santé, et rien qui nomme un patient : les références suffisent.' || E'\n' ||
  '- Ce qu''on peut déduire de ce que le client a déjà donné — chaque question posée' || E'\n' ||
  '  deux fois entame la confiance dans tout le reste de l''installation.' || E'\n'
$$;


--
-- Name: f_cle_fournisseur(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_cle_fournisseur(p text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  select nullif(
           btrim(
             regexp_replace(
               lower(extensions.unaccent(coalesce(p, ''))),
               '[^a-z0-9]+', ' ', 'g'
             )
           ), '')
$$;


--
-- Name: f_cloisons_fk_simples(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_cloisons_fk_simples() RETURNS TABLE(relation text, contrainte text, colonne text, parent text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select cl.relname::text, c.conname::text, a.attname::text, pa.relname::text
    from pg_constraint c
    join pg_class     cl on cl.oid = c.conrelid
    join pg_class     pa on pa.oid = c.confrelid
    join pg_namespace n  on n.oid  = cl.relnamespace
    join pg_attribute a  on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
   where n.nspname   = 'public'
     and c.contype   = 'f'
     and array_length(c.conkey, 1) = 1
     and a.attname  <> 'client_id'
     and exists (select 1 from pg_attribute x
                  where x.attrelid = c.conrelid and x.attname = 'client_id'
                    and x.attnum > 0 and not x.attisdropped)
     and exists (select 1 from pg_attribute y
                  where y.attrelid = c.confrelid and y.attname = 'client_id'
                    and y.attnum > 0 and not y.attisdropped)
     and not exists (
           select 1
             from pg_constraint c2
            where c2.conrelid  = c.conrelid
              and c2.confrelid = c.confrelid
              and c2.contype   = 'f'
              and c2.oid      <> c.oid
              and a.attnum = any (c2.conkey)
              and exists (select 1 from pg_attribute z
                           where z.attrelid = c.conrelid and z.attname = 'client_id'
                             and z.attnum = any (c2.conkey)))
   order by 1, 2;
$$;


--
-- Name: f_cloisons_moteurs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_cloisons_moteurs() RETURNS TABLE(contrainte text, manquants text[])
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_def text;
begin
  select pg_get_constraintdef(oid) into v_def
    from pg_constraint where conname = 'config_moteurs_moteur_check';
  contrainte := 'config_moteurs_moteur_check';
  select coalesce(array_agg(m.code order by m.code), '{}') into manquants
    from moteurs_reconnus m
   where m.statut <> 'abandonne'
     and (v_def is null or position('''' || m.code || '''' in v_def) = 0);
  return next;
  select pg_get_constraintdef(oid) into v_def
    from pg_constraint where conname = 'relances_moteur_check';
  contrainte := 'relances_moteur_check';
  select coalesce(array_agg(m.code order by m.code), '{}') into manquants
    from moteurs_reconnus m
   where m.statut <> 'abandonne' and m.ecrit_relances
     and (v_def is null or position('''' || m.code || '''' in v_def) = 0);
  return next;
  contrainte := 'politiques_envoi';
  select coalesce(array_agg(m.code order by m.code), '{}') into manquants
    from moteurs_reconnus m
   where m.statut in ('construit','en_service') and m.ecrit_relances
     and not exists (select 1 from politiques_envoi p where p.moteur = m.code);
  return next;
end $$;


--
-- Name: f_cloisons_orphelins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_cloisons_orphelins() RETURNS TABLE(relation text, orphelins bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and c.column_name  = 'client_id'
       and t.table_type   = 'BASE TABLE'
       and c.table_name  <> 'clients'
     order by 1
  loop
    execute format(
      'select count(*) from public.%I x left join public.clients k on k.id = x.client_id where x.client_id is not null and k.id is null',
      r.table_name) into n;
    relation := r.table_name; orphelins := n;
    return next;
  end loop;
end $$;


--
-- Name: f_elargir_check_liste(text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_elargir_check_liste(p_table text, p_contrainte text, p_colonne text, p_ajouts text[]) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_def    text;
  v_actuel text[] := '{}';
  v_final  text[];
begin
  select pg_get_constraintdef(c.oid) into v_def
    from pg_constraint c
   where c.conrelid = p_table::regclass
     and c.conname  = p_contrainte;
  if v_def is null then
    raise notice '% : contrainte % introuvable — AUCUNE action. Vérifier son nom réel (pré-vol 0.1).',
      p_table, p_contrainte;
    return 'CONTRAINTE ABSENTE — rien fait';
  end if;
  select coalesce(array_agg(m[1]), '{}') into v_actuel
    from regexp_matches(v_def, '''((?:[^'']|'''')*)''', 'g') as m;
  select array_agg(distinct v order by v) into v_final
    from unnest(v_actuel || p_ajouts) as v;
  execute format('alter table %s drop constraint if exists %I', p_table, p_contrainte);
  execute format('alter table %s add constraint %I check (%I = any (array[%s]::text[]))',
                 p_table, p_contrainte, p_colonne,
                 (select string_agg(quote_literal(v), ', ' order by v) from unnest(v_final) as v));
  return array_to_string(v_final, ', ');
end $$;


