     where bloquant and statut = 'manquant'
  );
$$;


--
-- Name: f_journal_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_journal_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  raise exception 'VERROU_JOURNAL : % est un journal en écriture seule (tentative de %)',
    tg_table_name, tg_op;
end $$;


--
-- Name: f_journal_immuable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_journal_immuable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    -- L'unique exception, et elle est bornée à la transaction qui la demande.
    if coalesce(current_setting('omega.purge_banc', true), '') = 'oui' then
      return old;
    end if;
    raise exception 'VERROU_JOURNAL : le journal des envois ne se supprime pas (c''est la preuve)';
  end if;
  if old.statut_envoi = 'envoye' then
    raise exception 'VERROU_JOURNAL : un envoi déjà parti ne se modifie plus';
  end if;
  return new;
end
$$;


--
-- Name: f_prerequis_controles_valides(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_prerequis_controles_valides() RETURNS TABLE(moteur text, cle text, etat text, detail text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  r  record;
  ok boolean;
  n  uuid := '00000000-0000-0000-0000-000000000000'::uuid;
begin
  for r in select pr.moteur, pr.cle, pr.controle from prerequis_moteur pr
            where pr.controle is not null
            order by (pr.moteur is not null), pr.moteur, pr.ordre
  loop
    begin
      execute 'select coalesce((' || r.controle || '), false)' into ok using n;
      moteur := r.moteur; cle := r.cle; etat := 'ok';
      detail := 'renvoie ' || coalesce(ok::text,'null') || ' sur un client inexistant';
      return next;
    exception when others then
      moteur := r.moteur; cle := r.cle; etat := 'CASSE'; detail := sqlerrm;
      return next;
    end;
  end loop;
end
$$;


--
-- Name: f_prerequis_manquants(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_prerequis_manquants(p_client uuid) RETURNS TABLE(moteur text, cle text, intitule text, pourquoi text, fournisseur text, bloquant boolean, moment text, statut text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  r  record;
  ok boolean;
begin
  for r in
    select * from (
      select pr.* from prerequis_moteur pr
       where pr.moteur is null
         and exists (select 1 from config_moteurs cm
                      where cm.client_id = p_client and cm.actif)
      union all
      select pr.* from prerequis_moteur pr
        join config_moteurs cm on cm.moteur = pr.moteur
       where cm.client_id = p_client and cm.actif
    ) q
    order by (q.moteur is not null), q.moteur, q.ordre, q.cle
  loop
    if r.controle is null then
      ok := null;
    else
      begin
        execute 'select coalesce((' || r.controle || '), false)' into ok using p_client;
      exception when others then
        ok := false;   -- un controle qui casse est un controle qui n'a rien prouve
      end;
    end if;

    if ok then
      continue;
    end if;

    moteur      := r.moteur;
    cle         := r.cle;
    intitule    := r.intitule;
    pourquoi    := r.pourquoi;
    fournisseur := r.fournisseur;
    bloquant    := r.bloquant;
    moment      := r.moment;
    statut      := case when ok is null then 'a_confirmer' else 'manquant' end;
    return next;
  end loop;
end
$$;


--
-- Name: f_verifier_signature_twilio(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_verifier_signature_twilio(p_url text, p_params jsonb, p_signature text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
declare v_token text; v_base text; v_calc text;
begin
  select coalesce((select decrypted_secret from vault.decrypted_secrets
                    where name = 'twilio_auth_token'), '') into v_token;

  -- Fermeture par defaut, comme pour l'autre porte.
  if v_token = '' then return 'twilio_auth_token absent du Vault'; end if;
  if coalesce(btrim(p_signature), '') = '' then return 'en-tete X-Twilio-Signature absent'; end if;
  if coalesce(btrim(p_url), '') = '' then return 'URL de rappel absente'; end if;

  select p_url || coalesce(string_agg(k.key || k.value, '' order by k.key), '')
    into v_base
    from jsonb_each_text(coalesce(p_params, '{}'::jsonb)) as k;

  v_calc := encode(extensions.hmac(v_base, v_token, 'sha1'), 'base64');
  if v_calc <> btrim(p_signature) then return 'signature Twilio invalide'; end if;
  return '';
end $$;


--
-- Name: f_verifier_signature_webhook(text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_verifier_signature_webhook(p_corps text, p_signature text, p_timestamp bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
declare v_secret text; v_recue text; v_calc text; v_skew numeric;
begin
  select coalesce((select decrypted_secret from vault.decrypted_secrets
                    where name = 'webhook_secret'), '') into v_secret;

  -- Fermeture par defaut : pas de secret configure, on refuse. Un webhook ouvert par
  -- accident de configuration est precisement ce qu'on cherche a empecher.
  if v_secret = '' then return 'serveur non configure (webhook_secret absent du Vault)'; end if;

  v_recue := lower(btrim(replace(coalesce(p_signature, ''), 'sha256=', '')));
  if v_recue = '' then return 'en-tete X-Pegase-Signature absent'; end if;

  v_calc := encode(extensions.hmac(coalesce(p_corps, ''), v_secret, 'sha256'), 'hex');
  if v_recue <> v_calc then return 'signature invalide'; end if;

  -- Anti-rejeu : une requete valide capturee ne doit pas etre rejouable indefiniment.
  v_skew := abs(extract(epoch from now()) * 1000 - coalesce(p_timestamp, 0));
  if coalesce(p_timestamp, 0) = 0 or v_skew > 300000 then
    return 'timestamp absent ou expire (anti-rejeu 5 min)';
  end if;

  return '';  -- chaine vide = autorise
end $$;


--
-- Name: f_verrous_avant_envoi(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.f_verrous_avant_envoi() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_conf config_moteurs%rowtype; v_pol politiques_envoi%rowtype;
  v_statut_facture text; v_opt_out boolean; v_pause timestamptz; v_verif date;
  v_max_jours int; v_plafond_global int; v_envois_moteur int; v_envois_client int;
  v_h int; v_dow int; v_cooldown int; v_h_debut int; v_h_fin int;
  v_debiteur uuid; v_contact uuid; v_montant numeric; v_seuil numeric;
begin
  if coalesce((select valeur from parametres where cle='actif_global'),'oui') <> 'oui' then
    raise exception 'VERROU_SYSTEME_EN_PAUSE : kill switch global activé, aucun envoi';
  end if;
  select * into v_conf from config_moteurs where client_id=new.client_id and moteur=new.moteur;
  if not found then
    raise exception 'VERROU_CONFIG_ABSENTE : aucun réglage « % » pour ce client — envoi refusé', new.moteur;
  end if;
  if not v_conf.actif then
    raise exception 'VERROU_MOTEUR_COUPE : le moteur « % » est coupé pour ce client', new.moteur;
  end if;
  select * into v_pol from politiques_envoi where moteur=new.moteur;
  if not found then
    v_pol.respecte_horaires:=true; v_pol.heure_debut:=null; v_pol.heure_fin:=null;
    v_pol.autorise_weekend:=false; v_pol.cooldown_jours:=null; v_pol.compte_dans_cooldown:=true;
    v_pol.respecte_opt_out:=true; v_pol.respecte_pause:=true; v_pol.respecte_montant_mini:=false;
    v_pol.exige_paiements_verifies:=false; v_pol.exige_debiteur:=false;
  end if;
  if new.facture_id is not null then
    select statut into v_statut_facture from factures where id=new.facture_id;
    if v_statut_facture in ('paye','abandonne','anomalie') then
      raise exception 'VERROU_FACTURE_DEJA_REGLEE : la facture est « % » — relance refusée', v_statut_facture;
    end if;
  end if;
  v_debiteur := coalesce(new.debiteur_id,(select debiteur_id from factures where id=new.facture_id));
  v_contact  := new.contact_id;
  if v_pol.exige_debiteur and new.debiteur_id is null then
    if new.moteur='revive' then
      raise exception 'VERROU_REVIVE_SANS_DEBITEUR : une reprise de contact doit viser un débiteur identifié';
    else
      raise exception 'VERROU_SANS_DEBITEUR : le moteur « % » doit viser un débiteur identifié', new.moteur;
    end if;
  end if;
  -- ÉLARGI LE 05/08 : un message part vers un débiteur OU vers un contact (détenteur de
  -- pièce, intervenant, prescripteur, vivier). Les deux tables portent opt_out et
  -- pause_jusqua ; jusqu'ici seule `debiteurs` était lue, donc tout moteur visant un
  -- contact — DOSSIER, TRACE, PISTE, RELAI, SUBSTITUTION — aurait envoyé sans opt-out,
  -- sans pause et sans cooldown. Le défaut était ouvert, pas fermé.
  -- Recetté le 05/08 sur données jetables : opt-out refusé, pause refusée, contact
  -- joignable accepté, second message au même contact refusé par le cooldown.
  if v_pol.respecte_opt_out then
    if v_debiteur is not null then
      select opt_out into v_opt_out from debiteurs where id=v_debiteur;
      if coalesce(v_opt_out,false) then
        raise exception 'VERROU_OPT_OUT : ce débiteur a demandé à ne plus être contacté';
      end if;
    end if;
    if v_contact is not null then
      select opt_out into v_opt_out from contacts where id=v_contact;
      if coalesce(v_opt_out,false) then
        raise exception 'VERROU_OPT_OUT : ce contact a demandé à ne plus être contacté';
      end if;
    end if;
  end if;
  if v_pol.respecte_pause then
    if v_debiteur is not null then
      select pause_jusqua into v_pause from debiteurs where id=v_debiteur;
      if v_pause is not null and v_pause > now() then
        raise exception 'VERROU_PAUSE : ce débiteur est en pause jusqu''au % — envoi refusé', v_pause::date;
      end if;
    end if;
    if v_contact is not null then
      select pause_jusqua into v_pause from contacts where id=v_contact;
      if v_pause is not null and v_pause > now() then
        raise exception 'VERROU_PAUSE : ce contact est en pause jusqu''au % — envoi refusé', v_pause::date;
      end if;
    end if;
  end if;
  if v_pol.exige_paiements_verifies and v_conf.mode='prod' then
    select paiements_verifies_le into v_verif from clients where id=new.client_id;
    v_max_jours := coalesce((select valeur::int from parametres where cle='max_jours_sans_verif_paiements'),7);
    if v_verif is null or v_verif < current_date - v_max_jours then
      raise exception 'VERROU_PAIEMENTS_NON_VERIFIES : paiements non confirmés depuis plus de % jours — relances suspendues', v_max_jours;
    end if;
  end if;
  if v_pol.respecte_horaires then
    v_h := extract(hour from (now() at time zone 'America/Guadeloupe'))::int;
    v_dow := extract(isodow from (now() at time zone 'America/Guadeloupe'))::int;
    if v_dow >= 6 and not v_pol.autorise_weekend
       and coalesce((select valeur from parametres where cle='envoi_weekend'),'non') <> 'oui' then
      raise exception 'VERROU_HORS_HORAIRES : pas d''envoi le week-end pour le moteur « % »', new.moteur;
    end if;
    v_h_debut := coalesce(v_pol.heure_debut,(select valeur::int from parametres where cle='heure_envoi_debut'),8);
    v_h_fin := coalesce(v_pol.heure_fin,(select valeur::int from parametres where cle='heure_envoi_fin'),18);
    if v_h < v_h_debut or v_h >= v_h_fin then
      raise exception 'VERROU_HORS_HORAIRES : « % » n''envoie que de %h à %h', new.moteur, v_h_debut, v_h_fin;
    end if;
  end if;
  v_cooldown := coalesce(v_pol.cooldown_jours,(select valeur::int from parametres where cle='jours_min_entre_messages'),3);
  if (v_debiteur is not null or v_contact is not null) and v_cooldown > 0 then
    if exists (select 1 from relances r left join politiques_envoi p on p.moteur=r.moteur
                where r.client_id=new.client_id and coalesce(p.compte_dans_cooldown,true)
                  and r.cree_le > now() - make_interval(days => v_cooldown)
                  and ((v_debiteur is not null and (r.debiteur_id=v_debiteur
                        or r.facture_id in (select f.id from factures f where f.debiteur_id=v_debiteur)))
                    or (v_contact is not null and r.contact_id=v_contact))) then
      raise exception 'VERROU_COOLDOWN : cette personne a déjà reçu un message il y a moins de % jours', v_cooldown;
    end if;
  end if;
  if v_pol.respecte_montant_mini and new.facture_id is not null then
    select montant_ttc into v_montant from factures where id=new.facture_id;
    v_seuil := coalesce((select valeur::numeric from parametres where cle='montant_min_relance_eur'),20);
    if v_montant is not null and v_montant < v_seuil then
      raise exception 'VERROU_MONTANT_MINI : facture de % € sous le seuil de % € — à traiter à la main', v_montant, v_seuil;
    end if;
  end if;
  select count(*) into v_envois_moteur from relances
   where client_id=new.client_id and moteur=new.moteur and cree_le::date=current_date;
  if v_envois_moteur >= v_conf.plafond_envois_jour then
    raise exception 'VERROU_PLAFOND_MOTEUR : % envois « % » aujourd''hui, plafond % atteint',
      v_envois_moteur, new.moteur, v_conf.plafond_envois_jour;
  end if;
  v_plafond_global := coalesce((select valeur::int from parametres where cle='plafond_envois_jour_global'),50);
  select count(*) into v_envois_client from relances where client_id=new.client_id and cree_le::date=current_date;
  if v_envois_client >= v_plafond_global then
    raise exception 'VERROU_PLAFOND_CLIENT : % envois aujourd''hui pour ce client, plafond global % atteint',
      v_envois_client, v_plafond_global;
  end if;
  return new;
end $$;


