--
-- Name: finaliser_installation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finaliser_installation(p_demande uuid, p_client uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  d public.demandes_audit;
  c uuid;
  code text;
  m text;
  v_stripe text;
begin
  select * into d from public.demandes_audit where id = p_demande for update;
  if not found then
    raise exception 'demande inconnue';
  end if;
  if d.utilisateur_id is null then
    raise exception 'demande sans compte : rattacher un utilisateur d''abord';
  end if;
  v_stripe := d.stripe_customer_id;
  if v_stripe is not null and exists (
       select 1 from public.clients
        where stripe_customer_id = v_stripe
          and (p_client is null or id <> p_client)) then
    v_stripe := null;
  end if;
  c := p_client;
  if c is null then
    insert into public.clients (nom, email, telephone, commune, statut, stripe_customer_id)
    values (coalesce(nullif(trim(d.entreprise), ''), d.prenom || ' ' || d.nom),
            d.email, d.telephone, d.commune, 'actif', v_stripe)
    returning id into c;
  elsif v_stripe is not null then
    update public.clients set stripe_customer_id = v_stripe
     where id = c and stripe_customer_id is null;
  end if;
  insert into public.comptes (user_id, client_id) values (d.utilisateur_id, c)
  on conflict do nothing;
  foreach code in array coalesce(d.modules, '{}'::text[]) loop
    for m in select unnest(moteurs) from public.catalogue_site where code_site = code loop
      insert into public.abonnements_modules (client_id, moteur, code_site, demande_id, installe_le)
      values (c, m, code, d.id, now())
      on conflict (client_id, moteur) do update
        set installe_le = now(), suspendu_le = null,
            demande_id = excluded.demande_id, code_site = excluded.code_site, maj_le = now();
    end loop;
  end loop;
  update public.demandes_audit set client_id = c, statut = 'honore' where id = d.id;
  return c;
end $$;


