--
-- Name: jour_ferie(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jour_ferie(p_jour date, p_territoire text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  perform private.verifier_calendrier(p_territoire, p_jour);
  return exists (select 1 from public.jours_feries f where f.territoire = p_territoire and f.jour = p_jour);
end $$;


--
-- Name: jour_ouvre(date, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jour_ouvre(p_jour date, p_territoire text, p_samedi_compte boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_isodow int := extract(isodow from p_jour)::int;
begin
  perform private.verifier_calendrier(p_territoire, p_jour);
  if v_isodow = 7 or (v_isodow = 6 and not p_samedi_compte) then
    return false;
  end if;
  return not exists (select 1 from public.jours_feries f where f.territoire = p_territoire and f.jour = p_jour);
end $$;


