--
-- Name: limiter_contact(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.limiter_contact(p_cle text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cle text := left(coalesce(nullif(trim(p_cle), ''), 'inconnue'), 128);
begin
  delete from tentatives_securite where cree_le < now() - interval '48 hours';
  if (select count(*) from tentatives_securite
       where type = 'contact' and cle = v_cle and cree_le > now() - interval '1 hour') >= 3
     or (select count(*) from tentatives_securite
       where type = 'contact' and cree_le > now() - interval '1 hour') >= 20
     or (select count(*) from tentatives_securite
       where type = 'contact' and cree_le > now() - interval '24 hours') >= 60 then
    return false;
  end if;
  insert into tentatives_securite (type, cle, reussi) values ('contact', v_cle, true);
  return true;
end
$$;


