--
-- Name: demandes_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.demandes_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parcours text DEFAULT 'audit'::text NOT NULL,
    formule text NOT NULL,
    profil text,
    nom text NOT NULL,
    prenom text NOT NULL,
    email text NOT NULL,
    entreprise text NOT NULL,
    secteur text NOT NULL,
    telephone text,
    commune text,
    message text,
    creneau_debut timestamp with time zone,
    creneau_fin timestamp with time zone,
    duree_min integer,
    statut text DEFAULT 'confirme'::text NOT NULL,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    modules text[],
    prix_mensuel_eur numeric(8,2),
    utilisateur_id uuid,
    client_id uuid,
    stripe_customer_id text,
    periodicite text DEFAULT 'mensuel'::text NOT NULL,
    prix_annuel_eur numeric(8,2),
    stripe_payment_method_id text,
    paiement_statut text DEFAULT 'a_enregistrer'::text NOT NULL,
    moyen_paiement jsonb,
    stripe_subscription_id text,
    stripe_checkout_session_id text,
    installation_eur numeric(8,2),
    pieces_mois integer,
    confirmation_envoyee_le timestamp with time zone,
    CONSTRAINT creneau_coherent CHECK ((((creneau_debut IS NULL) = (creneau_fin IS NULL)) AND ((creneau_debut IS NULL) = (duree_min IS NULL)) AND ((creneau_fin IS NULL) OR (creneau_fin > creneau_debut)))),
    CONSTRAINT demandes_audit_commune_check CHECK ((char_length(commune) <= 80)),
    CONSTRAINT demandes_audit_duree_min_check CHECK (((duree_min >= 15) AND (duree_min <= 480))),
    CONSTRAINT demandes_audit_email_check CHECK (((email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text) AND (char_length(email) <= 160))),
    CONSTRAINT demandes_audit_entreprise_check CHECK (((char_length(entreprise) >= 1) AND (char_length(entreprise) <= 120))),
    CONSTRAINT demandes_audit_formule_check CHECK ((char_length(formule) <= 40)),
    CONSTRAINT demandes_audit_message_check CHECK ((char_length(message) <= 2000)),
    CONSTRAINT demandes_audit_modules_check CHECK (((modules IS NULL) OR ((array_length(modules, 1) >= 1) AND (array_length(modules, 1) <= 4)))),
    CONSTRAINT demandes_audit_moyen_paiement_check CHECK (((moyen_paiement IS NULL) OR (jsonb_typeof(moyen_paiement) = 'object'::text))),
    CONSTRAINT demandes_audit_nom_check CHECK (((char_length(nom) >= 1) AND (char_length(nom) <= 80))),
    CONSTRAINT demandes_audit_paiement_statut_check CHECK ((paiement_statut = ANY (ARRAY['a_enregistrer'::text, 'enregistre'::text, 'preleve'::text, 'echec'::text]))),
    CONSTRAINT demandes_audit_parcours_check CHECK ((parcours = ANY (ARRAY['audit'::text, 'reglage'::text, 'devis'::text]))),
    CONSTRAINT demandes_audit_periodicite_check CHECK ((periodicite = ANY (ARRAY['mensuel'::text, 'annuel'::text]))),
    CONSTRAINT demandes_audit_prenom_check CHECK (((char_length(prenom) >= 1) AND (char_length(prenom) <= 80))),
    CONSTRAINT demandes_audit_prix_annuel_check CHECK (((periodicite = 'annuel'::text) = (prix_annuel_eur IS NOT NULL))),
    CONSTRAINT demandes_audit_profil_check CHECK ((profil = ANY (ARRAY['tpe'::text, 'equipe'::text]))),
    CONSTRAINT demandes_audit_secteur_check CHECK ((char_length(secteur) <= 40)),
    CONSTRAINT demandes_audit_statut_check CHECK ((statut = ANY (ARRAY['confirme'::text, 'annule'::text, 'honore'::text, 'no_show'::text, 'a_traiter'::text]))),
    CONSTRAINT demandes_audit_telephone_check CHECK ((char_length(telephone) <= 30))
);


