-- Name: mesurer_suivis(uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mesurer_suivis(p_client uuid, p_module text, p_du timestamp with time zone, p_au timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is not null
     and not exists (select 1 from public.comptes c where c.user_id = (select auth.uid()) and c.client_id = p_client) then
    raise exception 'Organisation introuvable.' using errcode = 'P0002';
  end if;
  return private.mesurer_suivis(p_client, p_module, p_du, p_au);
end $$;


