--
-- Name: modifier_installation(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.modifier_installation(p_demande uuid, p_modules text[], p_periodicite text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  d public.demandes_audit;
  v_modules text[];
  v_prix numeric(8,2);
  v_prix_annuel numeric(8,2);
  v_installation numeric(8,2);
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'erreur', 'connexion_requise');
  end if;
  v_modules := (select array_agg(distinct m order by m) from unnest(coalesce(p_modules, '{}')) m
                where m in ('cashd','reload','frontd','filed'));
  if v_modules is null or array_length(v_modules, 1) < 1 then
    return jsonb_build_object('ok', false, 'erreur', 'modules_requis');
  end if;
  if p_periodicite is null or p_periodicite not in ('mensuel','annuel') then
    return jsonb_build_object('ok', false, 'erreur', 'periodicite_inconnue');
  end if;
  select * into d from public.demandes_audit
   where id = p_demande and utilisateur_id = auth.uid()
   for update;
  if not found or d.parcours <> 'reglage' then
    return jsonb_build_object('ok', false, 'erreur', 'demande_inconnue');
  end if;
  if d.client_id is not null then
    return jsonb_build_object('ok', false, 'erreur', 'deja_finalisee');
  end if;
  if d.statut not in ('confirme', 'a_traiter') then
    return jsonb_build_object('ok', false, 'erreur', 'statut_incompatible');
  end if;
  if d.creneau_debut is not null and d.creneau_debut < now() then
    return jsonb_build_object('ok', false, 'erreur', 'statut_incompatible');
  end if;
  if d.pieces_mois is not null then
    v_prix := ceil((greatest(149, round(d.pieces_mois * 2)) + 1) / 10.0) * 10 - 1;
  else
    v_prix := case array_length(v_modules, 1)
      when 1 then 299 when 2 then 790 when 3 then 790 else 1990 end;
  end if;
  v_installation := case array_length(v_modules, 1)
    when 1 then 590 when 2 then 790 when 3 then 790 else 1490 end;
  v_prix_annuel := case when p_periodicite = 'annuel' then floor(v_prix * 0.85) * 12 end;
  update public.demandes_audit
     set modules = v_modules,
         prix_mensuel_eur = v_prix,
         periodicite = p_periodicite,
         prix_annuel_eur = v_prix_annuel,
         installation_eur = v_installation
   where id = d.id;
  return jsonb_build_object(
    'ok', true, 'id', d.id,
    'modules', to_jsonb(v_modules),
    'periodicite', p_periodicite,
    'prix_mensuel_eur', v_prix,
    'prix_annuel_eur', v_prix_annuel);
end
$$;


