--
-- Name: poser_abonnement_stripe(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.poser_abonnement_stripe(p_demande uuid, p_subscription text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  d public.demandes_audit;
  n integer;
begin
  if p_subscription is null or p_subscription !~ '^sub_[A-Za-z0-9]+$' then
    raise exception 'identifiant de souscription invalide';
  end if;
  select * into d from public.demandes_audit where id = p_demande for update;
  if not found then
    raise exception 'demande inconnue';
  end if;
  if d.client_id is null then
    raise exception 'demande non finalisée : finaliser l''installation d''abord';
  end if;
  if d.stripe_subscription_id is not null and d.stripe_subscription_id <> p_subscription then
    raise exception 'demande déjà abonnée (%)', d.stripe_subscription_id;
  end if;
  update public.demandes_audit set stripe_subscription_id = p_subscription where id = d.id;
  update public.abonnements_modules
     set stripe_subscription_id = p_subscription, source = 'stripe', maj_le = now()
   where client_id = d.client_id and demande_id = d.id;
  get diagnostics n = row_count;
  return n;
end $_$;


