--

CREATE FUNCTION public.proroger(p_jour date, p_territoire text) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v date := p_jour;
begin
  while not public.jour_ouvre(v, p_territoire, false) loop
    v := v + 1;
  end loop;
  return v;
end $$;


