--
-- Name: reserver_audit(text, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, text[], text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserver_audit(p_parcours text, p_formule text, p_profil text, p_nom text, p_prenom text, p_email text, p_entreprise text, p_secteur text, p_telephone text DEFAULT NULL::text, p_commune text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_creneau_debut timestamp with time zone DEFAULT NULL::timestamp with time zone, p_modules text[] DEFAULT NULL::text[], p_periodicite text DEFAULT 'mensuel'::text, p_pieces integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_duree integer;
  v_local timestamp;
  v_jour integer;
  v_id uuid;
  v_fin timestamptz;
  v_modules text[];
  v_prix numeric(8,2);
  v_email text;
  v_periodicite text;
  v_prix_annuel numeric(8,2);
  v_installation numeric(8,2);
  v_pieces integer;
begin
  v_email := case when auth.uid() is not null
    then coalesce(nullif(lower(trim(auth.jwt() ->> 'email')), ''), lower(trim(p_email)))
    else lower(trim(p_email)) end;
  if p_periodicite is null or p_periodicite not in ('mensuel','annuel') then
    return jsonb_build_object('ok', false, 'erreur', 'periodicite_inconnue');
  end if;
  v_periodicite := 'mensuel';
  v_duree := case p_formule
    when 'diagnostic' then 30
    when 'complet'    then 90
    when 'cadrage'    then 45
    when 'process'    then 120
    when 'reglage'    then 45
    when 'site'       then null
    when 'atelier'    then null
    else -1 end;
  if v_duree = -1 then
    return jsonb_build_object('ok', false, 'erreur', 'formule_inconnue');
  end if;
  if p_parcours not in ('audit','reglage','devis') then
    return jsonb_build_object('ok', false, 'erreur', 'parcours_inconnu');
  end if;
  if p_parcours = 'reglage' then
    -- LE VERROU : pas de compte, pas d'installation (decision Teo 02/09)
    if auth.uid() is null then
      return jsonb_build_object('ok', false, 'erreur', 'connexion_requise');
    end if;
    if p_formule <> 'reglage' then
      return jsonb_build_object('ok', false, 'erreur', 'formule_inconnue');
    end if;
    v_modules := (select array_agg(distinct m) from unnest(coalesce(p_modules, '{}')) m
                  where m in ('cashd','reload','frontd','filed'));
    if v_modules is null or array_length(v_modules, 1) < 1 then
      return jsonb_build_object('ok', false, 'erreur', 'modules_requis');
    end if;
    -- Un volume aberrant est ignore plutot que refuse : on retombe alors sur
    -- le bareme par postes. Au-dela de 1000 pieces la grille ne s'applique
    -- plus (c'est l'audit qui chiffre), on ne fige donc rien de ce cote.
    v_pieces := case when p_pieces is not null and p_pieces > 0 and p_pieces <= 1000
                     then p_pieces end;
    if v_pieces is not null then
      -- prix continu : 2 EUR la piece, plancher 149 EUR, puis ARRONDI
      -- COMMERCIAL a la dizaine sur un montant termine par 9 (v3.4) —
      -- miroir de prixPourVolume() + arrondiCommercial() cote site.
      v_prix := ceil((greatest(149, round(v_pieces * 2)) + 1) / 10.0) * 10 - 1;
    else
      -- repli : l'ancien bareme par nombre de postes
      v_prix := case array_length(v_modules, 1)
        when 1 then 299 when 2 then 790 when 3 then 790 else 1990 end;
    end if;
    -- L'installation, facturee une seule fois — miroir de installationPour().
    -- Elle suit le nombre de postes, pas le volume : ce qu'elle couvre, c'est
    -- l'onboarding (entretiens, reprise d'historique), pas le traitement.
    v_installation := case array_length(v_modules, 1)
      when 1 then 590 when 2 then 790 when 3 then 790 else 1490 end;
    -- remise 15 % (0.85, miroir de REMISE_ANNUELLE cote site)
    v_periodicite := p_periodicite;
    v_prix_annuel := case when v_periodicite = 'annuel'
      then floor(v_prix * 0.85) * 12 end;
  end if;
  if v_duree is null then
    p_creneau_debut := null;
  elsif p_creneau_debut is null then
    return jsonb_build_object('ok', false, 'erreur', 'creneau_requis');
  end if;
  if (select count(*) from demandes_audit
      where email = v_email and cree_le > now() - interval '7 days') >= 3 then
    return jsonb_build_object('ok', false, 'erreur', 'trop_de_demandes');
  end if;

  -- 25/09/2026 (audit sécurité) : plafond GLOBAL des demandes sans compte.
  -- La limite par adresse ci-dessus se contourne en changeant d'adresse à
  -- chaque essai ; celle-ci non. Largement au-dessus du trafic réel (10
  -- demandes en 30 jours au 25/09). Annulation :
  -- base-de-donnees/2026-09-25-securite-limites.ANNULATION.sql
  if auth.uid() is null and (
       (select count(*) from demandes_audit
         where utilisateur_id is null and cree_le > now() - interval '1 hour') >= 12
    or (select count(*) from demandes_audit
         where utilisateur_id is null and cree_le > now() - interval '24 hours') >= 40) then
    return jsonb_build_object('ok', false, 'erreur', 'agenda_sature');
  end if;
  if p_creneau_debut is not null then
    if p_creneau_debut < now() + interval '2 hours' then
      return jsonb_build_object('ok', false, 'erreur', 'creneau_passe');
    end if;
    if p_creneau_debut > now() + interval '70 days' then
      return jsonb_build_object('ok', false, 'erreur', 'creneau_trop_loin');
    end if;
    v_local := p_creneau_debut at time zone 'America/Guadeloupe';
    if extract(minute from v_local) not in (0, 30) or extract(second from v_local) <> 0 then
      return jsonb_build_object('ok', false, 'erreur', 'creneau_non_aligne');
    end if;
    v_jour := extract(isodow from v_local);
    if not exists (select 1 from agenda_regles r
        where r.actif and r.jour_semaine = v_jour
          and v_local::time >= r.heure_debut
          and (v_local + make_interval(mins => v_duree))::time <= r.heure_fin
          and v_local::date = (v_local + make_interval(mins => v_duree))::date) then
      return jsonb_build_object('ok', false, 'erreur', 'hors_horaires');
    end if;
    v_fin := p_creneau_debut + make_interval(mins => v_duree);
    if exists (select 1 from agenda_blocages b where b.debut < v_fin and b.fin > p_creneau_debut) then
      return jsonb_build_object('ok', false, 'erreur', 'creneau_pris');
    end if;
  end if;
  begin
    insert into demandes_audit
      (parcours, formule, profil, nom, prenom, email, entreprise, secteur,
       telephone, commune, message, creneau_debut, creneau_fin, duree_min, statut,
       modules, prix_mensuel_eur, utilisateur_id,
       periodicite, prix_annuel_eur, installation_eur, pieces_mois)
    values
      (p_parcours, p_formule, nullif(p_profil,''),
       trim(p_nom), trim(p_prenom), v_email, trim(p_entreprise), p_secteur,
       nullif(trim(coalesce(p_telephone,'')),''), nullif(trim(coalesce(p_commune,'')),''),
       nullif(trim(coalesce(p_message,'')),''),
       p_creneau_debut,
       case when p_creneau_debut is null then null else p_creneau_debut + make_interval(mins => v_duree) end,
       case when p_creneau_debut is null then null else v_duree end,
       case when p_creneau_debut is null then 'a_traiter' else 'confirme' end,
       v_modules, v_prix,
       auth.uid(),
       v_periodicite, v_prix_annuel, v_installation, v_pieces)
    returning id into v_id;
  exception
    when exclusion_violation then
      return jsonb_build_object('ok', false, 'erreur', 'creneau_pris');
    when check_violation then
      return jsonb_build_object('ok', false, 'erreur', 'champs_invalides');
  end;
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


--
-- Name: reserver_audit_serveur(text, text, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, text[], text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserver_audit_serveur(p_ip text, p_parcours text, p_formule text, p_profil text, p_nom text, p_prenom text, p_email text, p_entreprise text, p_secteur text, p_telephone text DEFAULT NULL::text, p_commune text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_creneau_debut timestamp with time zone DEFAULT NULL::timestamp with time zone, p_modules text[] DEFAULT NULL::text[], p_periodicite text DEFAULT 'mensuel'::text, p_pieces integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cle text := left(coalesce(nullif(trim(p_ip), ''), 'inconnue'), 128);
  v_rep jsonb;
begin
  if p_parcours = 'reglage' then
    return jsonb_build_object('ok', false, 'erreur', 'connexion_requise');
  end if;
  delete from tentatives_securite where cree_le < now() - interval '48 hours';
  if (select count(*) from tentatives_securite
       where type = 'reservation' and cle = v_cle and cree_le > now() - interval '1 hour') >= 20
     or (select count(*) from tentatives_securite
       where type = 'reservation' and cle = v_cle and reussi and cree_le > now() - interval '1 hour') >= 2
     or (select count(*) from tentatives_securite
       where type = 'reservation' and cle = v_cle and reussi and cree_le > now() - interval '24 hours') >= 3 then
    return jsonb_build_object('ok', false, 'erreur', 'agenda_sature');
  end if;
  v_rep := public.reserver_audit(p_parcours, p_formule, p_profil, p_nom, p_prenom, p_email,
    p_entreprise, p_secteur, p_telephone, p_commune, p_message, p_creneau_debut,
    p_modules, p_periodicite, p_pieces);
  insert into tentatives_securite (type, cle, reussi)
  values ('reservation', v_cle, coalesce((v_rep ->> 'ok')::boolean, false));
  return v_rep;
end
$$;


