--
-- Name: territoire_calendrier(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.territoire_calendrier(p_iso text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  select coalesce(
    (select t.code from public.territoires t where upper(btrim(p_iso)) = any (t.iso)),
    case when upper(btrim(p_iso)) ~ '^FR-(0[1-9]|[1-8][0-9]|9[0-5]|2A|2B|75C|69M|20R|ARA|BFC|BRE|CVL|HDF|IDF|NOR|NAQ|OCC|PDL|PAC)$'
         then 'metropole' end)
$_$;


