--
-- Name: veille_replace_patterns(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.veille_replace_patterns(p_video_id text, p jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'veille', 'public'
    AS $$
declare n integer := 0; e jsonb;
begin
  delete from veille.patterns where video_id = p_video_id;
  for e in select * from jsonb_array_elements(coalesce(p, '[]'::jsonb)) loop
    insert into veille.patterns (video_id, titre, plateforme, declencheur, etapes, cas_usage, pieges, applicable_omega)
    values (p_video_id, coalesce(e->>'titre','(sans titre)'), e->>'plateforme', e->>'declencheur', e->'etapes', e->>'cas_usage', e->>'pieges', e->>'applicable_omega');
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: veille_upsert_outil(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.veille_upsert_outil(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'veille', 'public'
    AS $$
begin
  insert into veille.outils (nom, categorie, description, mentions, videos, verdict)
  values (p->>'nom', p->>'categorie', p->>'description', coalesce((p->>'mentions')::int, 0),
          coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'videos','[]'::jsonb)) x), '{}'), p->>'verdict')
  on conflict (nom) do update set categorie = coalesce(excluded.categorie, veille.outils.categorie), description = coalesce(excluded.description, veille.outils.description),
    mentions = excluded.mentions, videos = excluded.videos, verdict = coalesce(excluded.verdict, veille.outils.verdict);
end $$;


--
-- Name: veille_upsert_video(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.veille_upsert_video(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'veille', 'public'
    AS $$
begin
  insert into veille.videos (id, url, titre, chaine, chaine_url, date_publication, duree_s, vues, langue, themes, type_video, tutoriel, source_transcript, transcript, resume, fiche, fiche_md, pertinence, fiche_le)
  values (
    p->>'id', p->>'url', p->>'titre', p->>'chaine', p->>'chaine_url',
    nullif(p->>'date_publication','')::date, nullif(p->>'duree_s','')::int, nullif(p->>'vues','')::bigint, p->>'langue',
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'themes','[]'::jsonb)) x), '{}'),
    p->>'type_video', coalesce((p->>'tutoriel')::boolean, false), p->>'source_transcript', p->>'transcript', p->>'resume',
    p->'fiche', p->>'fiche_md', nullif(p->>'pertinence','')::smallint, case when p ? 'fiche' then now() end)
  on conflict (id) do update set
    url = excluded.url, titre = excluded.titre, chaine = excluded.chaine, chaine_url = excluded.chaine_url,
    date_publication = excluded.date_publication, duree_s = excluded.duree_s, vues = excluded.vues, langue = excluded.langue,
    themes = excluded.themes, type_video = coalesce(excluded.type_video, veille.videos.type_video), tutoriel = excluded.tutoriel,
    source_transcript = coalesce(excluded.source_transcript, veille.videos.source_transcript),
    transcript = coalesce(excluded.transcript, veille.videos.transcript), resume = coalesce(excluded.resume, veille.videos.resume),
    fiche = coalesce(excluded.fiche, veille.videos.fiche), fiche_md = coalesce(excluded.fiche_md, veille.videos.fiche_md),
    pertinence = coalesce(excluded.pertinence, veille.videos.pertinence), fiche_le = coalesce(excluded.fiche_le, veille.videos.fiche_le);
end $$;


