--
-- Name: activite_mensuelle; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.activite_mensuelle WITH (security_invoker='on') AS
 SELECT r.client_id,
    c.nom AS client_nom,
    (date_trunc('month'::text, r.cree_le))::date AS mois,
    r.moteur,
    count(*) AS envois
   FROM (public.relances r
     JOIN public.clients c ON ((c.id = r.client_id)))
  GROUP BY r.client_id, c.nom, ((date_trunc('month'::text, r.cree_le))::date), r.moteur
  ORDER BY ((date_trunc('month'::text, r.cree_le))::date) DESC, (count(*)) DESC;


