-- Name: usage_ia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.usage_ia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    survenu_le timestamp with time zone DEFAULT now() NOT NULL,
    client_id uuid,
    moteur text NOT NULL,
    modele text NOT NULL,
    tokens_entree integer DEFAULT 0 NOT NULL,
    tokens_sortie integer DEFAULT 0 NOT NULL,
    cout_eur numeric(10,6),
    workflow_execution text,
    contexte text
);


--
-- Name: couts_ia_mensuels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.couts_ia_mensuels WITH (security_invoker='on') AS
 SELECT c.id AS client_id,
    c.nom AS client_nom,
    (date_trunc('month'::text, u.survenu_le))::date AS mois,
    u.moteur,
    count(*) AS appels,
    sum(u.tokens_entree) AS tokens_entree,
    sum(u.tokens_sortie) AS tokens_sortie,
    round(COALESCE(sum(u.cout_eur), (0)::numeric), 4) AS cout_eur
   FROM (public.usage_ia u
     JOIN public.clients c ON ((c.id = u.client_id)))
  GROUP BY c.id, c.nom, (date_trunc('month'::text, u.survenu_le)), u.moteur;


