);


--
-- Name: encours_clients; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.encours_clients WITH (security_invoker='on') AS
 SELECT c.id AS client_id,
    c.nom AS client_nom,
    c.statut AS client_statut,
    count(*) FILTER (WHERE ((f.type = 'facture'::text) AND (f.statut <> ALL (ARRAY['paye'::text, 'abandonne'::text])))) AS factures_ouvertes,
    COALESCE(sum(f.montant_ttc) FILTER (WHERE ((f.type = 'facture'::text) AND (f.statut <> ALL (ARRAY['paye'::text, 'abandonne'::text])))), (0)::numeric) AS encours_ttc,
    count(*) FILTER (WHERE ((f.type = 'facture'::text) AND (f.statut <> ALL (ARRAY['paye'::text, 'abandonne'::text])) AND (f.date_echeance < CURRENT_DATE))) AS factures_en_retard,
    max((CURRENT_DATE - f.date_echeance)) FILTER (WHERE ((f.type = 'facture'::text) AND (f.statut <> ALL (ARRAY['paye'::text, 'abandonne'::text])) AND (f.date_echeance < CURRENT_DATE))) AS retard_max_jours,
    count(*) FILTER (WHERE ((f.type = 'devis'::text) AND (f.statut <> ALL (ARRAY['paye'::text, 'abandonne'::text])))) AS devis_en_cours,
    ( SELECT max(r.envoye_le) AS max
           FROM public.relances r
          WHERE ((r.client_id = c.id) AND (r.statut_envoi = 'envoye'::text))) AS derniere_relance_le
   FROM (public.clients c
     LEFT JOIN public.factures f ON ((f.client_id = c.id)))
  GROUP BY c.id, c.nom, c.statut;


