    CONSTRAINT filed_receptions_lignes_methode_check CHECK ((methode = ANY (ARRAY['commande_ligne'::text, 'reference'::text, 'designation'::text, 'seule'::text, 'humain'::text]))),
    CONSTRAINT filed_receptions_lignes_quantite_check CHECK ((quantite >= (0)::numeric)),
    CONSTRAINT filed_receptions_lignes_rang_check CHECK ((rang >= 1)),
    CONSTRAINT filed_receptions_lignes_reference_check CHECK ((char_length(reference) <= 100)),
    CONSTRAINT filed_receptions_lignes_source_check CHECK ((source = ANY (ARRAY['xml'::text, 'regle'::text, 'ia'::text, 'humain'::text, 'tableur'::text, 'import'::text, 'saisie'::text]))),
    CONSTRAINT filed_receptions_lignes_unite_check CHECK ((char_length(unite) <= 20))
);


--
-- Name: filed_commandes_suivi; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.filed_commandes_suivi WITH (security_invoker='on') AS
 SELECT c.client_id,
    c.entite_id,
    c.id AS commande_id,
    c.numero,
    c.statut,
    c.fournisseur_id,
    l.id AS ligne_id,
    l.rang,
    l.reference,
    l.designation,
    l.quantite AS commandee,
    l.unite,
    l.prix_unitaire,
    l.montant_ht,
    COALESCE(( SELECT sum(q.quantite) AS sum
           FROM (public.filed_receptions_lignes q
             JOIN public.filed_receptions r ON ((r.id = q.reception_id)))
          WHERE ((q.commande_ligne_id = l.id) AND (r.statut = 'enregistree'::text))), (0)::numeric) AS recue,
    COALESCE(( SELECT sum(((x.sens)::numeric * x.quantite)) AS sum
           FROM (public.filed_rapprochements_lignes x
             JOIN public.filed_factures f ON ((f.id = x.facture_id)))
          WHERE ((x.commande_ligne_id = l.id) AND (f.statut <> 'ecartee'::text))), (0)::numeric) AS facturee,
    (l.quantite - COALESCE(( SELECT sum(((x.sens)::numeric * x.quantite)) AS sum
           FROM (public.filed_rapprochements_lignes x
             JOIN public.filed_factures f ON ((f.id = x.facture_id)))
          WHERE ((x.commande_ligne_id = l.id) AND (f.statut <> 'ecartee'::text))), (0)::numeric)) AS reste_a_facturer
   FROM (public.filed_commandes c
     JOIN public.filed_commandes_lignes l ON ((l.commande_id = c.id)));


