    CONSTRAINT lorani_permis_echeances_nature_check CHECK ((nature = ANY (ARRAY['completude'::text, 'pieces'::text, 'instruction'::text, 'affichage'::text, 'retrait'::text, 'recours'::text, 'purge'::text]))),
