--
-- Name: lorani_echeances_permis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lorani_echeances_permis WITH (security_invoker='true') AS
 SELECT e.permis_id,
    e.projet_id,
    e.nature,
    d.id AS delai_id,
    d.libelle,
    d.echeance,
    d.echeance_calculee,
    d.echeance_notifiee,
    d.statut,
    d.rappels,
    d.rappels_faits,
    d.regle_code,
    d.regle_version,
    (d.calcul ->> 'detail'::text) AS detail,
    (d.calcul ->> 'source'::text) AS source,
    (d.calcul ->> 'source_url'::text) AS source_url,
    d.source_notification,
    d.responsable,
    d.action_attendue
   FROM (public.lorani_permis_echeances e
     JOIN public.delais d ON (((d.client_id = e.client_id) AND (d.id = e.delai_id))))
  WHERE e.courante;


