--
-- Name: mesures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mesures (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    indicateur text NOT NULL,
    version smallint NOT NULL,
    mode text NOT NULL,
    periode_type text NOT NULL,
    debut date NOT NULL,
    fin date NOT NULL,
    valeur numeric NOT NULL,
    numerateur numeric,
    base numeric,
    entite_id uuid,
    objet_type text,
    objet_id text,
    objet_libelle text,
    enregistre_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mesures_base_check CHECK ((base >= (0)::numeric)),
    CONSTRAINT mesures_libelle_d_un_objet CHECK (((objet_libelle IS NULL) OR (objet_id IS NOT NULL))),
    CONSTRAINT mesures_mode_check CHECK ((mode = ANY (ARRAY['a_blanc'::text, 'reel'::text]))),
    CONSTRAINT mesures_objet_complet CHECK (((objet_type IS NULL) = (objet_id IS NULL))),
    CONSTRAINT mesures_objet_id_check CHECK (((char_length(objet_id) >= 1) AND (char_length(objet_id) <= 120))),
    CONSTRAINT mesures_objet_libelle_check CHECK (((char_length(btrim(objet_libelle)) >= 1) AND (char_length(btrim(objet_libelle)) <= 120))),
    CONSTRAINT mesures_objet_type_check CHECK ((objet_type ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT mesures_periode CHECK (
CASE periode_type
    WHEN 'jour'::text THEN (fin = debut)
    WHEN 'semaine'::text THEN ((EXTRACT(isodow FROM debut) = (1)::numeric) AND (fin = (debut + 6)))
    WHEN 'mois'::text THEN ((EXTRACT(day FROM debut) = (1)::numeric) AND (fin = (((debut + '1 mon'::interval))::date - 1)))
    ELSE ((mode = 'a_blanc'::text) AND (fin >= debut) AND ((fin - debut) <= 366))
END),
    CONSTRAINT mesures_periode_type_check CHECK ((periode_type = ANY (ARRAY['jour'::text, 'semaine'::text, 'mois'::text, 'libre'::text])))
);


--
-- Name: mises_en_demeure; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mises_en_demeure (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    debiteur_id uuid NOT NULL,
    dossier_ref text NOT NULL,
    exercice text,
    factures_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    montant_total numeric(12,2),
    gabarit text NOT NULL,
    canal text DEFAULT 'lrar'::text NOT NULL,
    consentement_electronique boolean DEFAULT false NOT NULL,
    consentement_date date,
    consentement_preuve text,
    document_url text,
    envoyee_le timestamp with time zone,
    premiere_presentation_le date,
    delai_jours integer NOT NULL,
    echeance_le date GENERATED ALWAYS AS (
CASE
    WHEN (premiere_presentation_le IS NOT NULL) THEN ((premiere_presentation_le + 1) + delai_jours)
    ELSE NULL::date
END) STORED,
    statut text DEFAULT 'preparee'::text NOT NULL,
    ar_url text,
    suites text,
    notes text,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT med_consentement_electronique CHECK (((canal <> 'electronique'::text) OR (consentement_electronique AND (consentement_date IS NOT NULL)))),
    CONSTRAINT mises_en_demeure_canal_check CHECK ((canal = ANY (ARRAY['lrar'::text, 'electronique'::text, 'remise_main_propre'::text]))),
    CONSTRAINT mises_en_demeure_statut_check CHECK ((statut = ANY (ARRAY['preparee'::text, 'a_valider'::text, 'a_envoyer'::text, 'envoyee'::text, 'presentee'::text, 'delai_expire'::text, 'payee'::text, 'accord'::text, 'contentieux'::text, 'abandonnee'::text])))
);


