--
-- Name: omega_prospects_secteurs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.omega_prospects_secteurs WITH (security_invoker='true') AS
 SELECT secteur,
    min(moteurs) AS moteurs,
    (count(*))::integer AS total,
    (count(*) FILTER (WHERE (telephone IS NOT NULL)))::integer AS avec_tel,
    (count(*) FILTER (WHERE (statut <> 'À contacter'::text)))::integer AS contactes
   FROM public.omega_prospects
  GROUP BY secteur;


--
-- Name: oppositions; Type: TABLE; Schema: public; Owner: -
