    sha256 text NOT NULL,
    chemin text NOT NULL,
    statut text DEFAULT 'recue'::text NOT NULL,
    type_piece text,
    confiance_type numeric(4,3),
    nb_pages integer,
    methode text,
    version_lecteur text,
