    CONSTRAINT politiques_plancher_nuit CHECK ((((heure_debut IS NULL) OR ((heure_debut >= 5) AND (heure_debut <= 12))) AND ((heure_fin IS NULL) OR ((heure_fin >= 12) AND (heure_fin <= 22))) AND ((heure_debut IS NULL) OR (heure_fin IS NULL) OR (heure_debut < heure_fin))))
);


