--
-- Name: releves_etat; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.releves_etat WITH (security_invoker='true') AS
 SELECT j.client_id,
    b.entite_id,
    b.id AS branchement_id,
    b.module,
    b.logiciel,
    b.libelle AS branchement,
    b.voie,
    b.statut AS statut_branchement,
    j.id AS jeu_id,
    j.code AS jeu,
    j.libelle,
    j.actif,
    j.lignes,
    j.etat_le,
    j.dernier_recu_le,
    j.rythme,
    j.courant_id,
    ( SELECT i.statut
           FROM public.instantanes i
          WHERE (i.jeu_id = j.id)
          ORDER BY i.recu_le DESC
         LIMIT 1) AS dernier_statut,
    (( SELECT count(*) AS count
           FROM public.instantanes i
          WHERE ((i.jeu_id = j.id) AND (i.statut = 'douteux'::text) AND (i.recu_le > COALESCE(( SELECT max(k.recu_le) AS max
                   FROM public.instantanes k
                  WHERE ((k.jeu_id = j.id) AND (k.statut = ANY (ARRAY['applique'::text, 'identique'::text])))), '-infinity'::timestamp with time zone)))))::integer AS douteux_de_suite,
    (( SELECT count(*) AS count
           FROM public.instantanes i
          WHERE ((i.jeu_id = j.id) AND (i.statut = ANY (ARRAY['recu'::text, 'en_lecture'::text, 'lu'::text, 'a_appliquer'::text])))))::integer AS en_cours
   FROM (public.branchements_jeux j
     JOIN public.branchements b ON ((b.id = j.branchement_id)));


