--
-- Name: sante_clients; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sante_clients WITH (security_invoker='on') AS
 SELECT id,
    nom,
    statut,
    paiements_verifies_le,
    (CURRENT_DATE - paiements_verifies_le) AS jours_sans_verif_paiements,
    ( SELECT count(*) AS count
           FROM public.validations v
          WHERE ((v.client_id = c.id) AND (v.statut = 'en_attente'::text))) AS validations_en_attente,
    ( SELECT count(*) AS count
           FROM public.anomalies a
          WHERE ((a.client_id = c.id) AND (a.cree_le > (now() - '7 days'::interval)))) AS anomalies_7_jours,
    ( SELECT max(r.cree_le) AS max
           FROM public.relances r
          WHERE (r.client_id = c.id)) AS derniere_activite
   FROM public.clients c
  WHERE (statut = 'actif'::text);


