--
-- Name: tamila_registre; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tamila_registre WITH (security_invoker='true') AS
 SELECT id,
    client_id,
    reference_chiffree,
    statut,
    mode,
    ouvert_le,
    effacement_prevu_le,
    private.tamila_lieu_conservation() AS lieu_conservation
   FROM public.tamila_dossiers d
  WHERE (statut = ANY (ARRAY['attente'::text, 'ouvert'::text, 'audit'::text, 'clos'::text]));


