--
-- Name: validations_en_retard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.validations_en_retard WITH (security_invoker='on') AS
 SELECT v.id,
    v.client_id,
    v.type,
    v.payload,
    v.token,
    v.statut,
    v.decide_le,
    v.cree_le,
    c.nom AS client_nom,
    round((EXTRACT(epoch FROM (now() - v.cree_le)) / (3600)::numeric)) AS heures_d_attente
   FROM (public.validations v
     JOIN public.clients c ON ((c.id = v.client_id)))
  WHERE ((v.statut = 'en_attente'::text) AND (v.cree_le < (now() - make_interval(hours => COALESCE(( SELECT (parametres.valeur)::integer AS valeur
           FROM public.parametres
          WHERE (parametres.cle = 'alerte_validation_heures'::text)), 48)))));


