    mots_cles_touches text[] DEFAULT '{}'::text[] NOT NULL,
    statut text DEFAULT 'detecte'::text NOT NULL,
    criticite text DEFAULT 'normale'::text NOT NULL,
    digest_le timestamp with time zone,
    payload jsonb,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    maj_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT veille_elements_criticite_check CHECK ((criticite = ANY (ARRAY['normale'::text, 'critique'::text]))),
    CONSTRAINT veille_elements_statut_check CHECK ((statut = ANY (ARRAY['detecte'::text, 'pertinent'::text, 'ecarte'::text, 'anomalie_ia'::text])))
);


