-- Name: points_reglages chacun change son reglage, gerants et admins tous; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "chacun change son reglage, gerants et admins tous" ON public.points_reglages FOR UPDATE TO authenticated USING ((((user_id = ( SELECT auth.uid() AS uid)) AND (client_id IN ( SELECT private.mes_clients() AS mes_clients))) OR private.a_un_role(client_id, ARRAY['gerant'::text, 'admin'::text]))) WITH CHECK ((((user_id = ( SELECT auth.uid() AS uid)) AND (client_id IN ( SELECT private.mes_clients() AS mes_clients))) OR private.a_un_role(client_id, ARRAY['gerant'::text, 'admin'::text])));


