--

CREATE POLICY "on lit les exports des dossiers qu'on voit" ON public.tamila_exports FOR SELECT TO authenticated USING ((((dossier_id IS NULL) AND private.a_un_role(client_id, ARRAY['gerant'::text])) OR ((dossier_id IS NOT NULL) AND private.tamila_voit_dossier_pour(( SELECT auth.uid() AS uid), client_id, (dossier_id)::text))));


