--

CREATE POLICY "on lit les reglages qui nous concernent" ON public.points_reglages FOR SELECT TO authenticated USING (((client_id IN ( SELECT private.mes_clients() AS mes_clients)) AND ((user_id IS NULL) OR (user_id = ( SELECT auth.uid() AS uid)) OR private.a_un_role(client_id, ARRAY['gerant'::text, 'admin'::text]))));


--
-- Name: lorani_membres_projet on voit l'equipe des projets qu'on voit; Type: POLICY; Schema: public; Owner: -
--

