--
-- Name: jeux_lignes on voit l'etat des jeux qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit l'etat des jeux qu'on voit" ON public.jeux_lignes FOR SELECT TO authenticated USING (((client_id IN ( SELECT private.mes_clients() AS mes_clients)) AND (EXISTS ( SELECT 1
   FROM public.branchements_jeux j
  WHERE (j.id = jeux_lignes.jeu_id)))));


--
-- Name: suivis_evenements on voit l'histoire des suivis qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit l'histoire des suivis qu'on voit" ON public.suivis_evenements FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.suivis s
  WHERE (s.id = suivis_evenements.suivi_id))));


--
-- Name: filed_historique on voit l'historique des documents qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit l'historique des documents qu'on voit" ON public.filed_historique FOR SELECT TO authenticated USING ((((document_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.filed_documents d
  WHERE (d.id = filed_historique.document_id)))) OR ((document_id IS NULL) AND (client_id IN ( SELECT private.mes_clients() AS mes_clients)))));


--
-- Name: envois_evenements on voit la remise des envois qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit la remise des envois qu'on voit" ON public.envois_evenements FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.envois e
  WHERE (e.id = envois_evenements.envoi_id))));


--
-- Name: filed_factures_tva on voit la tva des documents qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit la tva des documents qu'on voit" ON public.filed_factures_tva FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.filed_documents d
  WHERE (d.id = filed_factures_tva.document_id))));


