--

CREATE POLICY "on voit le rapprochement des factures qu'on voit" ON public.filed_rapprochements FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.filed_factures f
  WHERE (f.id = filed_rapprochements.facture_id))));


--
-- Name: acces_objets on voit les acces qui nous concernent; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit les acces qui nous concernent" ON public.acces_objets FOR SELECT TO authenticated USING ((private.a_un_role(client_id, ARRAY['gerant'::text]) OR (user_id = ( SELECT auth.uid() AS uid)) OR ((equipe_id IS NOT NULL) AND private.dans_equipe(( SELECT auth.uid() AS uid), equipe_id)) OR private.ecrit_objet(client_id, objet_type, objet_id)));


--
-- Name: loc_contrats_amendements on voit les amendements des contrats qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit les amendements des contrats qu'on voit" ON public.loc_contrats_amendements FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.loc_contrats c
  WHERE ((c.client_id = loc_contrats_amendements.client_id) AND (c.id = loc_contrats_amendements.contrat_id)))));


--
-- Name: filed_appariements on voit les appariements des factures qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit les appariements des factures qu'on voit" ON public.filed_appariements FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.filed_factures f
  WHERE (f.id = filed_appariements.facture_id))));


--
-- Name: loc_avoirs on voit les avoirs des factures qu'on voit; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit les avoirs des factures qu'on voit" ON public.loc_avoirs FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.loc_factures f
  WHERE ((f.client_id = loc_avoirs.client_id) AND (f.id = loc_avoirs.facture_id)))));


--
-- Name: branchements on voit les branchements de son perimetre; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit les branchements de son perimetre" ON public.branchements FOR SELECT TO authenticated USING (((client_id IN ( SELECT private.mes_clients() AS mes_clients)) AND ((entite_id IS NULL) OR private.voit_entite(client_id, entite_id))));


--
-- Name: filed_commandes on voit les commandes de son perimetre; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "on voit les commandes de son perimetre" ON public.filed_commandes FOR SELECT TO authenticated USING (((client_id IN ( SELECT private.mes_clients() AS mes_clients)) AND private.voit_entite(client_id, entite_id)));


--
-- Name: loc_contrats on voit les contrats de son agence; Type: POLICY; Schema: public; Owner: -
--

