CREATE POLICY "tiroma : on voit les patients de son perimetre" ON public.tiroma_patients FOR SELECT TO authenticated USING (((client_id IN ( SELECT private.mes_clients() AS mes_clients)) AND ((entite_id IN ( SELECT private.tiroma_cabinets_patients() AS tiroma_cabinets_patients)) OR ((entite_id, praticien_habituel_id) IN ( SELECT p.entite_id,
    p.praticien_id
   FROM private.tiroma_praticiens_patients() p(entite_id, praticien_id))) OR (id IN ( SELECT r.patient_id
   FROM public.tiroma_rendez_vous r
  WHERE (r.patient_id IS NOT NULL))) OR (id IN ( SELECT pl.patient_id
   FROM public.tiroma_plans pl)))));


